/// Intersection of two clip rects (CSS-px space). Returns a zero-size rect if
/// they are disjoint. Used by the draw-list replay's clip stack so a nested
/// clip can never exceed its parent.
fn intersectClip(a: Rectangle, b: Rectangle) Rectangle {
    const x0: f32 = @max(a.x, b.x);
    const y0: f32 = @max(a.y, b.y);
    const x1: f32 = @min(a.x + a.width, b.x + b.width);
    const y1: f32 = @min(a.y + a.height, b.y + b.height);
    return .{ .x = x0, .y = y0, .width = @max(0, x1 - x0), .height = @max(0, y1 - y0) };
}
