// ============================================================================
// BoundedStack - fixed-capacity stack on the stack frame.
// Zig 0.16 removed std.BoundedArray. We need something simple for the
// small fixed stacks (window_stack, id_stack) that don't justify heap
// allocation. Six lines of obvious code; not worth a stdlib dep.
// ============================================================================

fn BoundedStack(comptime T: type, comptime cap: usize) type {
    return struct {
        items: [cap]T = undefined,
        len: usize = 0,

        const Self = @This();

        pub fn append(self: *Self, v: T) error{Overflow}!void {
            if (self.len >= cap) return error.Overflow;
            self.items[self.len] = v;
            self.len += 1;
        }

        pub fn pop(self: *Self) ?T {
            if (self.len == 0) return null;
            self.len -= 1;
            return self.items[self.len];
        }

        pub fn top(self: *const Self) ?T {
            if (self.len == 0) return null;
            return self.items[self.len - 1];
        }

        pub fn clear(self: *Self) void {
            self.len = 0;
        }
    };
}

test "BoundedStack: append/pop/top/clear semantics" {
    var s = BoundedStack(u32, 4){};
    try expectEqual(@as(?u32, null), s.top());

    try s.append(10);
    try s.append(20);
    try expectEqual(@as(usize, 2), s.len);
    try expectEqual(@as(?u32, 20), s.top());

    try expectEqual(@as(?u32, 20), s.pop());
    try expectEqual(@as(usize, 1), s.len);

    s.clear();
    try expectEqual(@as(usize, 0), s.len);
    try expectEqual(@as(?u32, null), s.pop());
}

test "BoundedStack: append on full returns Overflow" {
    var s = BoundedStack(u32, 2){};
    try s.append(1);
    try s.append(2);
    try expectError(error.Overflow, s.append(3));
}

// ============================================================================
// Public types
// ============================================================================

/// Stable widget identifier, computed by hashing the ID stack +
/// label. Same as ImGui's `ImGuiID` - a u32. Collisions are
/// vanishingly rare in practice; if they happen the user calls
/// `pushId(uniqueValue)` to disambiguate.
pub const Id = u32;

// ============================================================================
// ID hashing - FNV-1a with seeded chaining, identical to ImGui's
// algorithm so test fixtures are interoperable.
// ============================================================================

const fnv_offset: u32 = 2166136261;
const fnv_prime: u32 = 16777619;

pub fn hashStr(seed: Id, str: []const u8) Id {
    var h: u32 = if (seed == 0) fnv_offset else seed;
    for (str) |b| {
        h = (h ^ b) *% fnv_prime;
    }
    return h;
}

pub fn hashInt(seed: Id, value: i64) Id {
    var h: u32 = if (seed == 0) fnv_offset else seed;
    var v: u64 = @bitCast(value);
    var i: usize = 0;
    while (i < 8) : (i += 1) {
        h = (h ^ @as(u8, @truncate(v))) *% fnv_prime;
        v >>= 8;
    }
    return h;
}

/// Options for `getOrPutState`. The `persist` flag enrolls T in
/// the on-disk save/load path — once set on any slot of T, the
/// serializer will include all (id, T) pairs in the next save.
pub const StateOpts = struct {
    /// When true, the typed slot's value gets included in `.zon`
    /// serialization at the next autosave. Requires T to be
    /// auto-serializable (no pointers, no fn pointers) — the
    /// comptime serializer fails to compile otherwise.
    persist: bool = false,
};

/// Curated easing functions for `u.animated`. The full set lives
/// in `src/easings.zig` (25 curves); extension authors needing
/// `bounceOut`, `elasticIn`, etc. can import `easings` directly.
pub const Easing = enum {
    linear,
    ease_in,
    ease_out,
    ease_in_out,
    back,
    elastic,
};

fn applyEasing(e: Easing, t: f32) f32 {
    return switch (e) {
        .linear => easings.linear(t),
        .ease_in => easings.cubicIn(t),
        .ease_out => easings.cubicOut(t),
        .ease_in_out => easings.cubicInOut(t),
        .back => easings.backOut(t),
        .elastic => easings.elasticOut(t),
    };
}

/// Options for `u.animated` — a one-shot tween from `from` to
/// `to` over `duration` seconds, optionally delayed by `delay`
/// seconds before motion starts.
pub const AnimatedOpts = struct {
    from: f32,
    to: f32,
    /// Total motion time in seconds. Must be > 0.
    duration: f32,
    easing: Easing = .linear,
    /// Hold at `from` for this many seconds before starting the
    /// tween. Useful for staggered entrances.
    delay: f32 = 0,
};

/// Internal slot stored via `getOrPutState`. Tracks elapsed time
/// against the tween's duration; the value returned each frame
/// is purely a function of `(elapsed - delay) / duration`.
pub const TweenSlot = struct {
    /// Seconds elapsed since the tween was first created. Resets
    /// when the caller calls `u.animated` with a different `to`
    /// value (i.e. the tween restarts from `from`).
    elapsed: f32 = 0,
    /// Remembered `to` from the previous frame. If the caller
    /// passes a new `to`, the tween resets — common for "fade
    /// IN when hovered, fade OUT when not" patterns where the
    /// caller flips `to` between frames.
    last_to: f32 = 0,
    /// True once the slot has been seeded with `last_to`.
    /// Avoids treating the very first call (where `last_to` is
    /// zero by default) as a `to`-change.
    seeded: bool = false,
};

/// Options for `u.spring` — a critically-damped-by-default
/// physical spring tracking `target`. Adjusting `target`
/// between frames is the normal mode of use; the spring
/// smoothly follows.
pub const SpringOpts = struct {
    target: f32,
    /// Spring stiffness. Higher = snappier. Common range
    /// 50-500. Default 200 feels natural for UI motion.
    stiffness: f32 = 200,
    /// Damping ratio. 1.0 = critical (no overshoot).
    /// 0.5 = bouncy. 2.0 = sluggish.
    damping: f32 = 1.0,
    /// Initial value on the first frame the spring exists.
    /// After that, ignored — the spring's own state takes over.
    initial: f32 = 0,
};

/// Internal slot stored via `getOrPutState`. Spring state is two
/// scalars: current position and current velocity. Each frame the
/// `u.spring` call integrates one step of the spring ODE forward.
pub const SpringSlot = struct {
    value: f32 = 0,
    velocity: f32 = 0,
    /// True after the first `u.spring` call has run; before that,
    /// the slot's `value` gets seeded with `opts.initial`.
    seeded: bool = false,
};

/// Throwaway smoke-test type — `u.miniPlot` is a stub that
/// validates the canvas + arcs + state + style + input +
/// animation pillars compose.  Real `beginPlot` / `endPlot`
