    fitted: bool = false,
};

/// Internal: one outer-map entry. Holds a type-erased pointer
/// to the typed `AutoHashMapUnmanaged(Id, T)` for one specific T,
/// plus a function pointer that knows how to deinit + free the
/// typed map when the UiContext tears down.
///
/// The deinit closure has to be stored alongside the map because
/// at UiContext.deinit time we no longer have access to T — only
/// the erased `*anyopaque`. Capturing the deinit fn at first-put
/// time (where T is known via comptime) sidesteps the problem.
/// Type-erased function bound at first persist-true put time to
/// serialize all (id, T) pairs in a typed inner map. Returns
/// owned zon text; caller frees.
const SerializeExtFn = *const fn (
    map: *anyopaque,
    gpa: Allocator,
) anyerror![]u8;

/// Type-erased function bound at first-put time to parse a zon
/// payload back into a typed inner map. Overwrites existing
/// entries (load-time, not merge).
const DeserializeExtFn = *const fn (
    map: *anyopaque,
    gpa: Allocator,
    text: [:0]const u8,
) anyerror!void;

const ExtStorageSlot = struct {
    /// Type-erased pointer to a `*std.AutoHashMapUnmanaged(Id, T)`
    /// allocated on the gpa. Re-cast to the concrete typed map
    /// at every get/put through a comptime-known T.
    map: *anyopaque,
    /// Deinit + free function. Captured at first-put time
    /// (where T is known) as `&deinitErasedMap(T)`. Called by
    /// `UiContext.deinit` walking `ext_storage`.
    deinit_fn: *const fn (map: *anyopaque, gpa: Allocator) void,
    /// True once a `getOrPutState(T,...,.{.persist = true })`
    /// call has fired for this type. `serialize` walks slots with
    /// this flag set and asks each one to encode itself.
    has_persist: bool = false,
    /// Captured `@typeName(T)` of the typed inner map, used to
    /// match persisted-state entries on load. Null until the
    /// first persist-true lookup binds it.
    type_name: ?[]const u8 = null,
    /// Encodes all (id, T) pairs as zon text. Null until the
    /// first persist-true lookup binds it.
    serialize_fn: ?SerializeExtFn = null,
    /// Parses encoded zon text back into the typed inner map.
    /// Null until the first persist-true lookup binds it.
    deserialize_fn: ?DeserializeExtFn = null,
};

/// Comptime-generated key for the outer `ext_storage` map. Hashes
/// the type's name via std.hash.Fnv1a_64. Two types with the same
/// name (which Zig wouldn't allow anyway in the same compilation
/// unit) would collide — practical guarantee is fine.
inline fn extStorageKey(comptime T: type) u64 {
    comptime {
        return std.hash.Fnv1a_64.hash(@typeName(T));
    }
}

/// Comptime-generated deinit for the typed inner map of T.
/// Bound at first-put time, called by UiContext.deinit. Frees
/// the inner-map's own buckets THEN the outer pointer.
fn deinitErasedMap(comptime T: type) (fn (map: *anyopaque, gpa: Allocator) void) {
    return struct {
        fn fun(map: *anyopaque, gpa: Allocator) void {
            const typed: *std.AutoHashMapUnmanaged(Id, T) = @ptrCast(@alignCast(map));
            typed.deinit(gpa);
            gpa.destroy(typed);
        }
    }.fun;
}

/// Comptime-generated serializer for the typed inner map of T.
/// Encodes the live (id, T) pairs as a zon array of
/// `.{.id = u32,.value = T }` tuples and returns the owned
/// bytes. Bound at first-persist-put time.
///
/// **T must be a plain-data type**: structs, arrays, enums, fixed
/// numeric types, BoundedArrays-of-plain-data. Pointers or
/// slices in T will compile but produce garbage at parse time
/// (the slice header survives serialization but points at freed
/// memory after load). Lint rule could enforce this — backlog'd.
fn serializeErasedMap(comptime T: type) SerializeExtFn {
    const Entry = struct { id: u32, value: T };
    return struct {
        fn fun(map: *anyopaque, gpa: Allocator) anyerror![]u8 {
            const typed: *std.AutoHashMapUnmanaged(Id, T) = @ptrCast(@alignCast(map));
            // Walk live entries into a temporary array, then
            // stringify. ArrayList sizing is bounded by the live
            // map count.
            var entries: ArrayList(Entry) = .empty;
            defer entries.deinit(gpa);
            var it = typed.iterator();
            while (it.next()) |kv| {
                try entries.append(gpa, .{ .id = kv.key_ptr.*, .value = kv.value_ptr.* });
            }
            var out: std.Io.Writer.Allocating = .init(gpa);
            errdefer out.deinit();
            try std.zon.stringify.serialize(entries.items, .{}, &out.writer);
            return try out.toOwnedSlice();
        }
    }.fun;
}

/// Comptime-generated deserializer for the typed inner map of T.
/// Parses zon text produced by `serializeErasedMap(T)` and
/// overwrites the typed map's entries. Existing entries with
/// matching ids are replaced; unmatched live entries are left
/// alone (load is union-with-incoming, not replacement).
fn deserializeErasedMap(comptime T: type) DeserializeExtFn {
    const Entry = struct { id: u32, value: T };
    return struct {
        fn fun(map: *anyopaque, gpa: Allocator, text: [:0]const u8) anyerror!void {
            const typed: *std.AutoHashMapUnmanaged(Id, T) = @ptrCast(@alignCast(map));
            var diag: std.zon.parse.Diagnostics = .{};
            defer diag.deinit(gpa);
            // Parse as a slice of Entry — that's the wire shape
            // serializeErasedMap emits.
            const parsed = try std.zon.parse.fromSliceAlloc(
                []Entry,
                gpa,
                text,
                &diag,
                .{ .ignore_unknown_fields = true },
            );
            defer std.zon.parse.free(gpa, parsed);
            for (parsed) |e| {
                try typed.put(gpa, e.id, e.value);
            }
        }
    }.fun;
}

/// Per-widget RGBA color, stored packed in u32 for the renderer's
/// vertex format. ImGui uses 0xAABBGGRR (little-endian); we match
/// to keep the wire format identical.
const ColorU32 = zm.ColorU32;

/// Pack a `Color` into the renderer's u32 format.
/// Multiply the alpha channel of a packed `ColorU32` by `mul` in
/// [0, 1], clamping the result. Used by the draw helpers to apply
/// `ctx.alpha_mul` (the disabled-scope dimming) to every painted
/// rect/text without invalidating colour cache hits at call sites.
pub inline fn multiplyAlpha(col: ColorU32, mul: f32) ColorU32 {
    if (mul >= 1.0) {
        return col;
    }
    const a: u32 = (col >> 24) & 0xFF;
    const a_f: f32 = float(a);
    const a_new: u32 = @round(clamp(a_f * mul, 0, 255));
    return (col & 0x00FFFFFF) | (a_new << 24);
}

/// Resolve the width a widget should use for its primary input
/// element. Priority (high to low):
///   1. `next_item_width` (set via `setNextItemWidth`; consumed)
///   2. top of `item_width_stack` (set via `pushItemWidth`)
///   3. `opts_width` (per-call-site option), if > 0
///   4. `default_w` (the widget's natural width if nothing else fires)
/// `next_item_width` is cleared on read - the override is one-shot.
pub fn effectiveItemWidth(
    ctx: *UiContext,
    opts_width: f32,
    default_w: f32,
) f32 {
    if (ctx.next_item_width) |w| {
        ctx.next_item_width = null;
        return w;
    }
    if (ctx.item_width_stack.top()) |w| {
        return w;
    }
    if (opts_width > 0) {
        return opts_width;
    }
    return default_w;
}

