    /// Re-derive the interactive colors from a single accent color.
    /// Structural chrome (text, borders, window bg, base title bar)
    /// stays unchanged - that's neutral by design and shouldn't bend
    /// to the accent. Modeled on `ImGui::StyleColorsDark()`'s ratios:
    /// button at 40% alpha, hovered at full, active darkened 20%, etc.
    ///     f.ui.style().applyAccent(z.colors.amber_500);
    ///     // every interactive widget now reads as "amber"
    pub fn applyAccent(self: *Style, accent: Color) void {
        self.button = accent.fade(0.40);
        self.button_hovered = accent.fade(1.00);
        self.button_active = accent.brightness(0.80).fade(1.00);
        // Slider bar / checkbox bg / inputText box - sit below button
        // intensity so the active widget reads on top of them.
        self.frame_bg = accent.brightness(0.60).fade(0.54);
        self.frame_bg_hovered = accent.fade(0.40);
        self.frame_bg_active = accent.fade(0.67);
        // Active window's title bar takes the accent darkened so it
        // reads as "this window's chrome, in the brand color."
        self.title_bg_active = accent.brightness(0.50).fade(1.00);
    }

    /// One-call retheme using a Tailwind-CSS-named hue at the 500
    /// shade (Tailwind's standard "primary" weight - bright enough
    /// to read as the brand color, not so saturated it fights the
    /// chrome). Add hues here as we add them to `z.colors`; the
    /// 9 currently in the palette are listed.
    pub fn applyTailwind(self: *Style, hue: TailwindHue) void {
        const accent: Color = switch (hue) {
            .slate => types.slate_500,
            .sky => types.sky_500,
            .amber => types.amber_500,
            .red => types.red_500,
            .pink => types.pink_500,
            .green => types.green_500,
            .emerald => types.emerald_500,
            .rose => types.rose_500,
            .violet => types.violet_500,
        };
        self.applyAccent(accent);
    }

