    /// One-call theme switcher. Replaces every Color slot with the
    /// preset's values; leaves the numeric chrome (padding, spacing,
    /// font*) untouched so the user's typography/density choices
    /// survive a theme flip.
    ///     ui.ctx.style.applyPreset(.light);
    /// Pair with `applyTailwind` for "neutral theme + brand accent":
    ///     ui.ctx.style.applyPreset(.light);
    ///     ui.ctx.style.applyTailwind(.emerald);
    pub fn applyPreset(self: *Style, preset: Preset) void {
        const src: Style = switch (preset) {
            .dark => Style.dark_default,
            .light => Style.light_default,
            .classic => Style.classic_default,
        };
        // Copy colors only — preserve user's numeric chrome + font.
        self.text = src.text;
        self.text_disabled = src.text_disabled;
        self.window_bg = src.window_bg;
        self.border = src.border;
        self.title_bg = src.title_bg;
        self.title_bg_active = src.title_bg_active;
        self.button = src.button;
        self.button_hovered = src.button_hovered;
        self.button_active = src.button_active;
        self.frame_bg = src.frame_bg;
        self.frame_bg_hovered = src.frame_bg_hovered;
        self.frame_bg_active = src.frame_bg_active;
        self.scrollbar_bg = src.scrollbar_bg;
        self.scrollbar_grab = src.scrollbar_grab;
        self.scrollbar_grab_hovered = src.scrollbar_grab_hovered;
        self.scrollbar_grab_active = src.scrollbar_grab_active;
        self.popup_bg = src.popup_bg;
        self.modal_dim_bg = src.modal_dim_bg;
        self.menu_bar_bg = src.menu_bar_bg;
        self.menu_hovered = src.menu_hovered;
        self.tab = src.tab;
        self.tab_hovered = src.tab_hovered;
        self.tab_active = src.tab_active;
        self.tab_separator = src.tab_separator;
        self.table_row_bg = src.table_row_bg;
        self.table_row_bg_alt = src.table_row_bg_alt;
        self.text_link = src.text_link;
        self.text_link_hovered = src.text_link_hovered;
        self.text_link_underline = src.text_link_underline;
    }
};

// Style override guard — defer-RAII for one-frame style changes.
//

// Pattern:
//     {
//         const g = u.styleOverride(.{.text = my_red });
//         defer g.restore();
//         u.text("warning",.{}); // red
//     }
//     // back to previous text color
//

// Why defer-RAII over imgui's pushStyleColor/popStyleColor stack?
// Two reasons: (1) Zig's `defer` already exists, no need for a
// custom stack data structure; (2) override+restore is symmetric
// at the source level — pop misuse (forgetting one, popping the
// wrong type) is impossible. Trade-off: one PartialStyle worth
// of stack memory per active guard (~64 bytes today). Acceptable.
//

// Comptime-derived: `PartialStyle` is generated via
// `inline for (fields(Style))` to map each Color/f32/Vec2 field
// to an optional of the same type. Adding a new field to Style
// automatically extends PartialStyle without further edits.

/// Comptime-derived "optional override" version of `Style`. Each
/// field is `?T` of the original field type — null means "leave
/// the live value alone". Caller fills in only the fields they
/// want to override:
///
///     const overrides: PartialStyle =.{.text = my_red };
pub const PartialStyle = blk: {
    const s_names = @typeInfo(Style).@"struct".field_names;
    const s_types = @typeInfo(Style).@"struct".field_types;
    const N: usize = s_names.len;
    var ps_names: [N][:0]const u8 = undefined;
    var ps_types: [N]type = undefined;
    var ps_attrs: [N]std.builtin.Type.Struct.FieldAttributes = undefined;
    for (s_names, s_types, 0..) |f_name, f_type, i| {
        ps_names[i] = f_name;
        ps_types[i] = ?f_type;
        // Each optional field defaults to null so a caller can
        // omit it in the struct literal: `.{.text = my_red }`
        // works without listing every other field.
        const default: ?f_type = null;
        ps_attrs[i] = .{ .default_value_ptr = @ptrCast(&default) };
    }
    break :blk @Struct(.auto, null, &ps_names, &ps_types, &ps_attrs);
};

/// Returned by `styleOverride`. Holds the prior values of just
/// the fields the caller actually overrode, so `restore` can put
/// them back. Memory footprint = size of one PartialStyle (one
/// optional per Style field). Use with `defer g.restore()`.
pub const StyleGuard = struct {
    ctx: *UiContext,
    saved: PartialStyle,

    /// Restore prior values for every field the matching
    /// `styleOverride` call modified. Safe to call exactly once;
    /// calling again is a no-op (all saved values were already
    /// written back, but no harm in re-writing them — the
    /// idempotence test verifies this).
    pub fn restore(self: StyleGuard) void {
        inline for (@typeInfo(Style).@"struct".field_names) |f_name| {
            if (@field(self.saved, f_name)) |prior| {
                @field(self.ctx.style, f_name) = prior;
            }
        }
    }
};

/// Dense zimr-side key enum. Mirrors raylib's `KeyboardKey`
/// (`types.zig:819`) but **dense** — every value in `0..MAX` is a
/// valid KeyCode, so it indexes a fixed-size array on
/// `InputSnapshot.keys` without holes. raylib's KeyboardKey has
/// sparse values (e.g. space=32, escape=256, f1=290) that would
/// need a 348-slot array with mostly empty entries; this dense
/// remapping keeps the snapshot compact.
///
/// `fromRaylib(types.KeyboardKey) → ?KeyCode` translates the
/// runtime input layer into zimr's key index. Keys raylib
/// supports but zimr doesn't surface return null and are skipped
/// during snapshot construction.
///
/// `MAX` is the count sentinel — `@intFromEnum(KeyCode.MAX)`
/// gives the array size. Do not pass `MAX` to `u.isKeyDown` —
/// it's a count, not a key.
pub const KeyCode = enum(u8) {
    // Letters
    a,
    b,
    c,
    d,
    e,
    f,
    g,
    h,
    i,
    j,
    k,
    l,
    m,
    n,
    o,
    p,
    q,
    r,
    s,
    t,
    u,
    v,
    w,
    x,
    y,
    z,
    // Digits (top row)
    zero,
    one,
    two,
    three,
    four,
    five,
    six,
    seven,
    eight,
    nine,
    // Function keys
    f1,
    f2,
    f3,
    f4,
    f5,
    f6,
    f7,
    f8,
    f9,
    f10,
    f11,
    f12,
    // Arrow keys
    left,
    right,
    up,
    down,
    // Navigation cluster
    home,
    end,
    page_up,
    page_down,
    insert,
    delete,
    // Action keys
    enter,
    escape,
    tab,
    backspace,
    space,
    // Modifiers (tracked individually; convenience accessors below)
    left_shift,
    right_shift,
    left_control,
    right_control,
    left_alt,
    right_alt,
    left_super,
    right_super,
    // Punctuation
    apostrophe,
    comma,
    minus,
    period,
    slash,
    semicolon,
    equal,
    left_bracket,
    right_bracket,
    backslash,
    grave,
    // Keypad
    kp_0,
    kp_1,
    kp_2,
    kp_3,
    kp_4,
    kp_5,
    kp_6,
    kp_7,
    kp_8,
    kp_9,
    kp_decimal,
    kp_divide,
    kp_multiply,
    kp_subtract,
    kp_add,
    kp_enter,
    kp_equal,
    // Lock keys
    caps_lock,
    num_lock,
    scroll_lock,
    print_screen,
    pause,
    // Sentinel — NOT a key, just the count of preceding enum values.
    // Used as the size of `InputSnapshot.keys`.
    MAX,

    /// Translate a raylib `KeyboardKey` to a zimr `KeyCode`.
    /// Returns `null` for raylib keys zimr doesn't surface
    /// (e.g. `kb_menu`, `null` sentinel).
    /// Translate a raylib `KeyboardKey` to a zimr `KeyCode`.
    /// Returns `null` for raylib keys zimr doesn't surface
    /// (e.g. `kb_menu`, `null` sentinel).
    pub fn fromRaylib(rk: types.KeyboardKey) ?KeyCode {
        return switch (rk) {
            .a => .a,
            .b => .b,
            .c => .c,
            .d => .d,
            .e => .e,
            .f => .f,
            .g => .g,
            .h => .h,
            .i => .i,
            .j => .j,
            .k => .k,
            .l => .l,
            .m => .m,
            .n => .n,
            .o => .o,
            .p => .p,
            .q => .q,
            .r => .r,
            .s => .s,
            .t => .t,
            .u => .u,
            .v => .v,
            .w => .w,
            .x => .x,
            .y => .y,
            .z => .z,
            .zero => .zero,
            .one => .one,
            .two => .two,
            .three => .three,
            .four => .four,
            .five => .five,
            .six => .six,
            .seven => .seven,
            .eight => .eight,
            .nine => .nine,
            .f1 => .f1,
            .f2 => .f2,
            .f3 => .f3,
            .f4 => .f4,
            .f5 => .f5,
            .f6 => .f6,
            .f7 => .f7,
            .f8 => .f8,
            .f9 => .f9,
            .f10 => .f10,
            .f11 => .f11,
            .f12 => .f12,
            .left => .left,
            .right => .right,
            .up => .up,
            .down => .down,
            .home => .home,
            .end => .end,
            .page_up => .page_up,
            .page_down => .page_down,
            .insert => .insert,
            .delete => .delete,
            .enter => .enter,
            .escape => .escape,
            .tab => .tab,
            .backspace => .backspace,
            .space => .space,
            .left_shift => .left_shift,
            .right_shift => .right_shift,
            .left_control => .left_control,
            .right_control => .right_control,
            .left_alt => .left_alt,
            .right_alt => .right_alt,
            .left_super => .left_super,
            .right_super => .right_super,
            .apostrophe => .apostrophe,
            .comma => .comma,
            .minus => .minus,
            .period => .period,
            .slash => .slash,
            .semicolon => .semicolon,
            .equal => .equal,
            .left_bracket => .left_bracket,
            .right_bracket => .right_bracket,
            .backslash => .backslash,
            .grave => .grave,
            .kp_0 => .kp_0,
            .kp_1 => .kp_1,
            .kp_2 => .kp_2,
            .kp_3 => .kp_3,
            .kp_4 => .kp_4,
            .kp_5 => .kp_5,
            .kp_6 => .kp_6,
            .kp_7 => .kp_7,
            .kp_8 => .kp_8,
            .kp_9 => .kp_9,
            .kp_decimal => .kp_decimal,
            .kp_divide => .kp_divide,
            .kp_multiply => .kp_multiply,
            .kp_subtract => .kp_subtract,
            .kp_add => .kp_add,
            .kp_enter => .kp_enter,
            .kp_equal => .kp_equal,
            .caps_lock => .caps_lock,
            .num_lock => .num_lock,
            .scroll_lock => .scroll_lock,
            .print_screen => .print_screen,
            .pause => .pause,
            else => null, // .null, .kb_menu, anything zimr doesn't surface
        };
    }

    /// Inverse of `fromRaylib` — every `KeyCode` (except `MAX`)
    /// maps to a `types.KeyboardKey` of the same field name.
    /// Used by repeat-aware helpers that need to call back into
    /// the raylib input layer (which owns the OS-level repeat
    /// timer). Calling this on `KeyCode.MAX` is a logic error and
    /// will fail at compile time via the inline-for guard.
    pub fn toRaylib(kc: KeyCode) types.KeyboardKey {
        return switch (kc) {
            .MAX => unreachable,
            inline else => |tag| @field(types.KeyboardKey, @tagName(tag)),
        };
    }
};

/// Per-key state, indexed by `KeyCode` in `InputSnapshot.keys`.
/// Mirrors imgui's `ImGuiKeyData` (imgui.h:2481-2487) plus a
/// `pressed_this_frame` / `released_this_frame` pair zimr uses for
/// the common edge-event pattern. Memory: ~12 bytes per key ×
/// `KeyCode.MAX` ≈ 1.5 KB per snapshot.
pub const KeyState = struct {
    /// True while the key is being held.
    down: bool = false,
    /// True for exactly one frame: the frame the key transitioned
    /// from up to down. Edge event.
    pressed_this_frame: bool = false,
    /// True for exactly one frame: the frame the key transitioned
    /// from down to up. Edge event.
    released_this_frame: bool = false,
    /// Frame count the key has been held. 0 the frame of press,
    /// increments each subsequent frame. Reset on release.
    down_duration_frames: u32 = 0,
};

/// Snapshot of the input state at the start of a frame. The Ui
/// reads this rather than reaching back into `Frame.input` directly
/// - keeps the dependency graph clean (ui.zig doesn't import
/// runtime.zig) and makes head-less testing trivial.
pub const InputSnapshot = struct {
    mouse_pos: Vec2 = .{ -10000, -10000 }, // off-screen sentinel
    mouse_left_down: bool = false,
    mouse_left_clicked: bool = false, // pressed this frame
    mouse_left_released: bool = false, // released this frame
    /// Right-mouse-button click - pressed-this-frame edge event.
    /// Used by `beginPopupContextItem` to auto-open a context menu
    /// over the previous widget when the user right-clicks it.
    mouse_right_clicked: bool = false,
    /// Middle-mouse-button click - pressed-this-frame edge event.
    /// Used by `beginTabItem` for middle-click-to-close, the
    /// standard browser-tab interaction.
    mouse_middle_clicked: bool = false,
    /// Vertical mouse-wheel delta this frame. Positive = wheel
    /// scrolled up (away from user); negative = down. Used by
    /// hovered windows to translate scroll_y.
    mouse_wheel_y: f32 = 0,
    /// Horizontal mouse-wheel delta this frame (trackpad two-finger
    /// horizontal swipe, or shift-scroll on a wheel mouse). Positive
    /// = right; negative = left. Used by hovered windows that have
    /// `WindowFlags.horizontal_scrollbar` set to translate scroll_x.
    /// P5.5b.
    mouse_wheel_x: f32 = 0,
    /// Number of fingers currently down (0 on desktop). Consumers read 2+ to
    /// detect a pinch; a single touch already drives the mouse_* fields.
    touch_count: i32 = 0,
    /// Screen positions of the first two touch points (valid when
    /// touch_count >= 1 / >= 2 respectively). Used for pinch-zoom.
    touch_pos: [2]Vec2 = .{ .{ 0, 0 }, .{ 0, 0 } },
    delta_time: f32 = 0,

    // ---- Keyboard state for inputText -----------------------
    /// Codepoints typed this frame. ASCII for now; the framework
    /// already gives us codepoints from `getCharPressed`. Fixed
    /// capacity keeps the snapshot a value type. Excess chars in a
    /// frame (>16) are dropped, which never happens in practice.
    chars_typed: [16]u32 = undefined,
    chars_typed_count: usize = 0,

    // Dense per-frame key-state array indexed by `KeyCode`. Tests
    // use `keyEventSnapshot(.X)` to construct synthetic input.
    // Mirrors imgui's `ImGuiIO::KeysData[ImGuiKey_NamedKey_COUNT]`
    // (imgui.h:2487-2690) but with zimr's own dense KeyCode enum.
    keys: [@backingInt(KeyCode.MAX)]KeyState = @splat(.{}),
};

/// Test helper: returns an `InputSnapshot` with a single
/// pressed-this-frame edge event for `key` set. Used by host-
/// side tests that inject synthetic input via `beginFrameRaw`.
/// Production code populates the snapshot via the inline-for loop
/// in `beginFrame` — this helper exists only for tests.
pub fn keyEventSnapshot(key: KeyCode) InputSnapshot {
    var s: InputSnapshot = .{};
    s.keys[@backingInt(key)].pressed_this_frame = true;
    s.keys[@backingInt(key)].down = true;
    return s;
}

/// Convenience: held-state modifier checks that aggregate left+right
/// sides. Same shape as the `Ui.isShiftDown` / `isCtrlDown` /
/// `isAltDown` / `isSuperDown` helpers but takes a snapshot
/// directly — used inside widget impl code that has a `*UiContext`
/// but no `Ui` handle. Resolves to the same array lookup.
pub fn snapshotShiftDown(s: *const InputSnapshot) bool {
    return s.keys[@backingInt(KeyCode.left_shift)].down or
        s.keys[@backingInt(KeyCode.right_shift)].down;
}
pub fn snapshotCtrlDown(s: *const InputSnapshot) bool {
    return s.keys[@backingInt(KeyCode.left_control)].down or
        s.keys[@backingInt(KeyCode.right_control)].down;
}
pub fn snapshotAltDown(s: *const InputSnapshot) bool {
    return s.keys[@backingInt(KeyCode.left_alt)].down or
        s.keys[@backingInt(KeyCode.right_alt)].down;
}
pub fn snapshotSuperDown(s: *const InputSnapshot) bool {
    return s.keys[@backingInt(KeyCode.left_super)].down or
        s.keys[@backingInt(KeyCode.right_super)].down;
}

/// `Ui.isKeyPressedOrRepeat` for callers that have a `*UiContext`
/// but no `Ui` handle — same semantics, no construction ceremony.
/// Initial-press case reads `keys[i].pressed_this_frame`; held-
/// and-repeating case routes through raylib's OS-level timer.
pub fn ctxKeyPressedOrRepeat(ctx: *UiContext, key: KeyCode) bool {
    if (ctx.input.keys[@backingInt(key)].pressed_this_frame) {
        return true;
    }
    const s: *runtime.input.InputState = ctx.input_state orelse return false;
    return runtime.input.isKeyPressedRepeat(s, key.toRaylib());
}

// ============================================================================
// P3: Long-press → right-click synthesis
// ============================================================================
// Touch-input UX: a long-press should fire the same
// `mouse_right_clicked` event that desktop right-click fires, so
// existing context-menu popups built on `beginPopupContextItem`
// (which reads `snapshot.mouse_right_clicked`) work on phone
// without a parallel "long-press menu" code path.
//

// Detection rules:
//   1. Exactly ONE touch active (multi-touch is a different gesture
//      — pinch/pan — and never triggers synthesis).
//   2. `snapshot.mouse_left_down` (touchstart already bridges to
//      mouse-button-down on the JS side, so this is always true
//      under a single-finger press; the check guards against the
//      "mouse left button released but touch state still present"
//      race window).
//   3. Position drift from the touchdown point < touch_long_press_drift_px.
//      Cancels the synthesis if the user drags.
//   4. Elapsed time since touchdown >= touch_long_press_threshold_ms.
//

// On the frame the threshold crosses:
//   - `snapshot.mouse_right_clicked` is OR'd to true.
//   - `snapshot.mouse_left_down` is cleared so widgets don't
//     interpret the same gesture as both a click and a right-click.
//   - `snapshot.mouse_left_clicked` is cleared (defensive: should
//     already be false this frame because the press was on a prior
//     frame, but covers the corner case where the test harness
//     fires touchdown + ticks both within frame N).
//   - Tracker enters "fired" state and won't re-trigger until the
//     touch lifts.
//

// Desktop mouse path: NEVER triggers, because the helper only acts
// when `touch_count == 1`. A desktop user holding the mouse for
// 500ms keeps `touch_count == 0`.
//

// State storage on UiContext (one tracker; multi-touch beyond 1
// finger resets it).

/// Time the user must hold a single touch (without moving more
/// than `touch_long_press_drift_px`) before the synthesis fires.
pub const touch_long_press_threshold_ms: f32 = 500;

/// Position drift in pixels from the touchdown anchor that cancels
/// the long-press. 6px matches typical touch-jitter on phones
/// without requiring the user to hold dead-still.
pub const touch_long_press_drift_px: f32 = 6;

pub const LongPressTracker = struct {
    /// Browser-assigned id of the tracked touch (-1 = not tracking).
    /// Single-touch only; multi-touch resets to -1.
    touch_id: i32 = -1,
    /// Anchor position at touchdown. Drift is measured against this.
    start_pos: Vec2 = .{ 0, 0 },
    /// Accumulated time since touchdown (ms). Resets to 0 on
    /// touchdown. Set to `THRESHOLD + 1` on fire so subsequent
    /// frames in the same press don't re-fire. Set to a negative
    /// sentinel on drift-cancel so the press is locked out.
    elapsed_ms: f32 = 0,
    /// One-frame flag: true on the frame the synthesis fired this
    /// press cycle. Read-only for callers; reset by the next
    /// `applyLongPressSynthesis` call. Useful for debug logging.
    just_fired_this_frame: bool = false,
};

/// Pure synthesis helper. Reads touch state from `input_state`,
/// mutates `snapshot` to inject the right-click on the frame the
/// long-press threshold crosses, and updates `ctx.long_press`.
///
/// Factored out of `beginFrame` so tests can drive it directly with
/// a synthetic `InputState` + `InputSnapshot` pair, without needing
/// a `Frame` / `GlState` harness.
pub fn applyLongPressSynthesis(
    ctx: *UiContext,
    snapshot: *InputSnapshot,
    input_state: *const runtime.input.InputState,
) void {
    // Reset the per-frame "fired" flag so callers that read it
    // always see the latest result.
    ctx.long_press.just_fired_this_frame = false;

    const touch_count: i32 = runtime.input.getTouchPointCount(input_state);
    if (touch_count != 1) {
        // 0 or 2+ touches — reset tracker.
        ctx.long_press.touch_id = -1;
        ctx.long_press.elapsed_ms = 0;
        return;
    }

    const tid: i32 = runtime.input.getTouchPointId(input_state, 0);
    const tpos: Vec2 = runtime.input.getTouchPosition(input_state, 0);

    if (ctx.long_press.touch_id != tid) {
        // New touch — start tracking.
        ctx.long_press.touch_id = tid;
        ctx.long_press.start_pos = tpos;
        ctx.long_press.elapsed_ms = 0;
        return;
    }

    // Same touch as last frame. Already fired or cancelled?
    if (ctx.long_press.elapsed_ms < 0 or
        ctx.long_press.elapsed_ms > touch_long_press_threshold_ms)
    {
        return;
    }

    // Check drift. If we moved too far from the anchor, cancel
    // this press cycle (will be re-armed on next touchdown).
    const dx: f32 = tpos[0] - ctx.long_press.start_pos[0];
    const dy: f32 = tpos[1] - ctx.long_press.start_pos[1];
    const drift_sq: f32 = dx * dx + dy * dy;
    if (drift_sq > touch_long_press_drift_px * touch_long_press_drift_px) {
        ctx.long_press.elapsed_ms = -1; // cancel
        return;
    }

    // Mouse must still be down — guards the touchend race window
    // where the OS released the mouse button but the touch slot
    // hasn't been compacted yet.
    if (!snapshot.mouse_left_down) {
        ctx.long_press.elapsed_ms = -1;
        return;
    }

    // Accumulate.
    ctx.long_press.elapsed_ms += snapshot.delta_time * 1000.0;
    if (ctx.long_press.elapsed_ms < touch_long_press_threshold_ms) {
        return;
    }

    // Threshold crossed THIS frame. Inject the right-click and
    // mark fired. OR-semantics: if the real mouse-right button
    // ALSO clicked this frame, the merge is idempotent.
    snapshot.mouse_right_clicked = true;
    snapshot.mouse_left_down = false;
    snapshot.mouse_left_clicked = false;
    ctx.long_press.elapsed_ms = touch_long_press_threshold_ms + 1;
    ctx.long_press.just_fired_this_frame = true;
}

/// Pending tooltip submission - collected during the frame, rendered
/// at endFrame on top of all other content. Owns its text in a
/// fixed-size buffer (no heap allocation per tooltip).
pub const TooltipData = struct {
    pos: Vec2,
    text_buf: [256]u8 = undefined,
    text_len: usize = 0,

    pub fn text(self: *const TooltipData) []const u8 {
        return self.text_buf[0..self.text_len];
    }
};

/// What the UI is currently rendering to. The default surface is
/// the main canvas (screen-space pixels). `pushRenderTexture` adds
/// a surface for the duration of an RT scope. Used to (a) compute
/// ortho projection at the right size, (b) restore viewport when
/// popping back to the outer surface, (c) inform `image()` to
/// auto-flip V when the source is an RT.
pub const Surface = struct {
    /// Pixel width of the render target.
    width: u32,
    /// Pixel height of the render target.
    height: u32,
    /// True for render targets - origin bottom-left, V flipped at
    /// sample time. The default canvas surface is `false`.
    y_flipped: bool = false,
};

/// Per-active-input edit state for `inputText`. Lives on UiContext
/// - only the currently-focused input cares about it, so a single
/// instance is enough. Reset on focus change.
pub const InputTextState = struct {
    /// Byte offset of the cursor within the buffer's current
    /// content. In `[0, len]` inclusive (cursor sits BETWEEN bytes;
    /// at `len` means "after the last char").
    cursor_pos: usize = 0,
    /// Accumulated time since the input gained focus. Used to
    /// blink the cursor. Reset on focus.
    blink_t: f32 = 0,
};

/// Persistent per-window state. Created on first `window(title,
/// ...)` call by hashing the title. Position, size, scroll, etc.
/// survive across frames. The window store is App-owned.
// ============================================================================
// Draw command list - deferred rendering for proper z-order
// ============================================================================
// Widgets append commands to a `DrawList` instead of emitting to rlgl
// immediately. At endFrame, draw lists are replayed in z-order:
// window draw lists first, foreground draw list (popups, tooltips)
// last. This gives us:
//   - **Proper z-ordering** - popups overlay rather than reflow,
//     tooltips always on top, multiple popups stack correctly
//   - **Per-widget clip rects** - push_clip / pop_clip commands
//     translate to rlgl scissor changes at replay time
//   - **Order-independent submission** - combo can call setTooltip
//     without worrying about who renders first
//   - **Snapshot-testable** - hash the draw list, compare frames,
//     no GL context needed
// Why a command list instead of ImGui's vertex-buffer approach:
// rlgl already batches GL emissions internally (rlBegin/rlVertex
// append to its vertex buffer; flush on state change). Recording
// commands and replaying through `shapes.drawRectangleRec` /
// `text.drawWithFont` lets rlgl do its own batching downstream. We avoid
// duplicating rlgl's machinery and keep one source of GL-call truth.
// Tradeoff: no per-cmd shader override (rlgl doesn't expose mid-batch
// program swap). For zimr's use case - UI overlaid on raylib scenes
// we never wanted that anyway.
// **Eager mode** - when `pushRenderTexture` is in scope, draw helpers
// emit straight to rlgl instead of recording. This keeps the
// recursive_hud demo's "push RT, draw stuff, pop RT" semantics.
// `eager_mode: bool` on UiContext is the switch.

/// One drawing operation, recorded for later replay. Tagged union so
/// switch dispatch at replay is exhaustive.
pub const DrawCmd = union(enum) {
    rect_filled: struct { rect: Rectangle, col: ColorU32 },
    rect_outline: struct { rect: Rectangle, col: ColorU32 },
    textured_quad: struct {
        rect: Rectangle,
        tex_id: u32,
        uv0: Vec2,
        uv1: Vec2,
        col: ColorU32,
    },
    /// A Sprite drawn at replay: residency (upload + cache) resolves against the
    /// replay backend's `image`, so record time needs no renderer. The Sprite is
    /// copied by value (id + Image view); its pixels must outlive the frame's
    /// replay — true for the per-frame DrawList lifecycle.
    sprite_quad: struct {
        dst: Rectangle,
        sprite: Sprite,
        opts: draw2d.ImageOpts,
    },
    text: struct {
        /// Bytes live in the DrawList's `arena` so the slice
        /// outlives the user's `update()` return. Invalidated on
        /// the next `clear()`.
        font: ?*const Font,
        s: []const u8,
        pos: Vec2,
        size: f32,
        spacing: f32,
        line_spacing: i32,
        col: ColorU32,
    },
    /// Push a scissor rect onto the rlgl scissor stack at replay.
    push_clip: struct { rect: Rectangle },
    /// Pop the topmost scissor rect at replay.
    pop_clip: void,

    // ---- primitives
    // The 13 primitives mirror imgui's `ImDrawList::Add*` surface. Each
    // replay arm calls into `shapes2d.*` - no new rasterizer code,
    // just a record/replay wrapper over raylib's existing shape API.

    line: struct {
        a: Vec2,
        b: Vec2,
        col: ColorU32,
        thickness: f32,
    },
    /// Polyline / line strip. When `closed`, the renderer adds a
    /// final segment from `points[count-1]` back to `points[0]`.
    /// Points live in the DrawList's arena.
    polyline: struct {
        points: []const Vec2,
        col: ColorU32,
        thickness: f32,
        closed: bool,
    },
    triangle: struct {
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: ColorU32,
        thickness: f32,
    },
    triangle_filled: struct {
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: ColorU32,
    },
    quad_filled: struct {
        a: Vec2,
        b: Vec2,
        c: Vec2,
        d: Vec2,
        col: ColorU32,
    },
    /// Circle outline. `n_segments = 0` means auto-compute from
    /// radius via `autoCircleSegments`.
    circle: struct {
        center: Vec2,
        radius: f32,
        col: ColorU32,
        thickness: f32,
        n_segments: u32,
    },
    /// Filled circle. Same `n_segments = 0 → auto` convention.
    circle_filled: struct {
        center: Vec2,
        radius: f32,
        col: ColorU32,
        n_segments: u32,
    },
    /// Regular polygon outline (triangle / square / hex / pentagon…).
    /// `sides` is explicit - stylistic markers want exact shapes.
    ngon: struct {
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: ColorU32,
        thickness: f32,
    },
    ngon_filled: struct {
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: ColorU32,
    },
    bezier_cubic: struct {
        p1: Vec2,
        p2: Vec2,
        p3: Vec2,
        p4: Vec2,
        col: ColorU32,
        thickness: f32,
    },
    ellipse: struct {
        center: Vec2,
        radius_h: f32,
        radius_v: f32,
        col: ColorU32,
        thickness: f32,
    },
    ellipse_filled: struct {
        center: Vec2,
        radius_h: f32,
        radius_v: f32,
        col: ColorU32,
    },
    /// Four-color gradient rectangle. `c_tl`/`c_tr`/`c_br`/`c_bl` are
    /// the corner colors; raylib interpolates linearly between them.
    rect_filled_multi_color: struct {
        rect: Rectangle,
        c_tl: ColorU32,
        c_tr: ColorU32,
        c_br: ColorU32,
        c_bl: ColorU32,
    },
};

/// One entry on a CanvasCtx's transform stack: 2D translate +
/// per-axis scale. A point `P` in child space maps to
/// `P * scale + translate` in the parent space. Rotation is
/// intentionally omitted — pan+zoom (the dominant canvas use
/// case) needs only translate+scale, and the composition math
/// stays a 5-multiply / 4-add affair instead of a full 2×2
/// matrix. If rotation ever becomes needed, this struct gains
/// a `rotation: f32` field and `compose` grows ~6 trig ops.
///
/// Module-level (not nested under `Ui`) because UiContext holds
/// the stack and forward-references through `Ui` would create
/// a circular dep.
pub const CanvasTransform = struct {
    translate: Vec2 = .{ 0, 0 },
    scale: Vec2 = .{ 1, 1 },

    /// Compose `child` ONTO `parent`. Result is the transform
    /// that applies `child` first, then `parent`. Used at push
    /// time so the stack always stores cumulative transforms —
    /// `top()` returns "everything stacked so far" directly, no
    /// walk needed.
    pub fn compose(parent: CanvasTransform, child: CanvasTransform) CanvasTransform {
        return .{
            .translate = .{
                child.translate[0] * parent.scale[0] + parent.translate[0],
                child.translate[1] * parent.scale[1] + parent.translate[1],
            },
            .scale = .{
                child.scale[0] * parent.scale[0],
                child.scale[1] * parent.scale[1],
            },
        };
    }

    /// Apply this transform to a point in child space:
    /// `out = p * scale + translate`.
    pub fn applyLocal(self: CanvasTransform, p: Vec2) Vec2 {
        return .{
            p[0] * self.scale[0] + self.translate[0],
            p[1] * self.scale[1] + self.translate[1],
        };
    }

    /// Invert the transform. Inverse exists iff scale[0] and
    /// scale[1] are both non-zero. Used by `localMouse` to pull
    /// screen-space mouse coords back into the canvas's authoring
    /// space. Caller responsibility: don't push a scale=0
    /// transform if you plan to call localMouse.
    pub fn inverse(self: CanvasTransform) CanvasTransform {
        const inv_sx: f32 = if (self.scale[0] != 0) 1.0 / self.scale[0] else 0;
        const inv_sy: f32 = if (self.scale[1] != 0) 1.0 / self.scale[1] else 0;
        return .{
            .translate = .{
                -self.translate[0] * inv_sx,
                -self.translate[1] * inv_sy,
            },
            .scale = .{ inv_sx, inv_sy },
        };
    }
};

/// Unpack a packed RGBA `ColorU32` into a `Color`. Format:
/// little-endian RGBA (matching `colorToU32` below).
/// Emit a textured quad to the renderer (gl: anytype). Used at draw list replay.
/// Two triangles, single rlBegin/rlEnd, sets+resets texture.
fn renderTexturedQuad(
    gl: anytype,
    r: Rectangle,
    tex_id: u32,
    uv0: Vec2,
    uv1: Vec2,
    col: ColorU32,
) void {
    const r8: u8 = @truncate((col >> 0) & 0xFF);
    const g8: u8 = @truncate((col >> 8) & 0xFF);
    const b8: u8 = @truncate((col >> 16) & 0xFF);
    const a8: u8 = @truncate((col >> 24) & 0xFF);

    gl.setTexture(tex_id);
    gl.begin(.triangles);
    gl.color4ub(r8, g8, b8, a8);

    const x0: f32 = r.x;
    const y0: f32 = r.y;
    const x1: f32 = r.x + r.width;
    const y1: f32 = r.y + r.height;

    gl.texCoord2f(uv0[0], uv0[1]);
    gl.vertex2f(x0, y0);
    gl.texCoord2f(uv0[0], uv1[1]);
    gl.vertex2f(x0, y1);
    gl.texCoord2f(uv1[0], uv1[1]);
    gl.vertex2f(x1, y1);

    gl.texCoord2f(uv0[0], uv0[1]);
    gl.vertex2f(x0, y0);
    gl.texCoord2f(uv1[0], uv1[1]);
    gl.vertex2f(x1, y1);
    gl.texCoord2f(uv1[0], uv0[1]);
    gl.vertex2f(x1, y0);

    gl.end();
    gl.setTexture(0);
}

pub const DrawList = struct {
    /// Recorded commands. Lives in the UiContext's frame arena
    /// (allocator is passed per `add*` call). The list slice
    /// `cmds.items` is invalidated whenever the arena is reset
    /// at endFrame - that's why `clear()` zeros the list back to
    /// `.empty` rather than calling `clearRetainingCapacity`
    /// (which would keep a stale items.ptr).
    cmds: ArrayList(DrawCmd) = .empty,

    /// Deinit the command list. Pass the same allocator used by the
    /// `add*` calls (in production, that's the UiContext's frame
    /// arena; in tests, it's typically `std.testing.allocator`).
    /// Safe to call with the arena allocator even though the arena
    /// will be deinit'd separately - `cmds.deinit` on arena memory
    /// is a no-op `free` plus a slice zero, which is harmless.
    pub fn deinit(self: *DrawList, alloc: Allocator) void {
        self.cmds.deinit(alloc);
    }

    /// Reset the command list for a new frame's submission. The
    /// arena may have been reset since the last submission, in
    /// which case `cmds.items.ptr` points at memory that's been
    /// reused - so we zero the list rather than calling
    /// `clearRetainingCapacity`.
    pub fn clear(self: *DrawList) void {
        self.cmds = .empty;
    }

    pub fn isEmpty(self: *const DrawList) bool {
        return self.cmds.items.len == 0;
    }

    /// Append a filled rectangle. OOM is silently dropped - UI
    /// degrades gracefully under memory pressure (a missing rect is
    /// ugly, not a crash).
    pub fn addRectFilled(
        self: *DrawList,
        gpa: Allocator,
        rect: Rectangle,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .rect_filled = .{ .rect = rect, .col = col } }) catch
            assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addRectOutline(
        self: *DrawList,
        gpa: Allocator,
        rect: Rectangle,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .rect_outline = .{ .rect = rect, .col = col } }) catch
            assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addTexturedQuad(
        self: *DrawList,
        gpa: Allocator,
        rect: Rectangle,
        tex_id: u32,
        uv0: Vec2,
        uv1: Vec2,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .textured_quad = .{
            .rect = rect,
            .tex_id = tex_id,
            .uv0 = uv0,
            .uv1 = uv1,
            .col = col,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addSpriteQuad(
        self: *DrawList,
        gpa: Allocator,
        dst: Rectangle,
        sprite: Sprite,
        opts: draw2d.ImageOpts,
    ) void {
        self.cmds.append(gpa, .{ .sprite_quad = .{
            .dst = dst,
            .sprite = sprite,
            .opts = opts,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Record a text command. String bytes are duplicated into
    /// `alloc` (which must be the UiContext's frame arena) so they
    /// outlive the caller's stack frame. `line_spacing` is captured
    /// at record time so the replay path doesn't need a separate
    /// parameter - multiple records in the same DrawList can have
    /// different line-spacing values if the user mutated
    /// `ctx.style.line_spacing` between calls.
    pub fn addText(
        self: *DrawList,
        alloc: Allocator,
        font: ?*const Font,
        s: []const u8,
        pos: Vec2,
        size: f32,
        spacing: f32,
        line_spacing: i32,
        col: ColorU32,
    ) void {
        if (s.len == 0) {
            return;
        }
        const owned: []const u8 = alloc.dupe(u8, s) catch return;
        self.cmds.append(alloc, .{ .text = .{
            .font = font,
            .s = owned,
            .pos = pos,
            .size = size,
            .spacing = spacing,
            .line_spacing = line_spacing,
            .col = col,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    // ---- primitives
    pub fn addLine(
        self: *DrawList,
        gpa: Allocator,
        a: Vec2,
        b: Vec2,
        col: ColorU32,
        thickness: f32,
    ) void {
        self.cmds.append(gpa, .{ .line = .{
            .a = a,
            .b = b,
            .col = col,
            .thickness = thickness,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Record a polyline (line strip). Points are duplicated into
    /// `alloc` (the UiContext's frame arena) so they survive past
    /// the caller's frame. `closed = true` adds a final segment
    /// from `points[count-1]` back to `points[0]`. OOM drops the
    /// command silently.
    pub fn addPolyline(
        self: *DrawList,
        alloc: Allocator,
        points: []const Vec2,
        col: ColorU32,
        thickness: f32,
        closed: bool,
    ) void {
        if (points.len < 2) {
            return;
        }
        const owned: []const Vec2 = alloc.dupe(Vec2, points) catch return;
        self.cmds.append(alloc, .{ .polyline = .{
            .points = owned,
            .col = col,
            .thickness = thickness,
            .closed = closed,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    // Arcs and polygons are emitted at submission time as
    // `polyline` (stroked) / `triangle_filled` (filled) commands —
    // no dedicated renderer-side DrawCmd variants. Cost: each
    // filled arc costs `segments` separate triangle_filled cmds
    // vs a single command record with center+radius+a0+a1. Fine
    // for occasional knobs/gauges; if arc spam ever shows up in
    // a profile, add a dedicated `arc` / `arc_filled` variant
    // and route through `shapes2d.drawRingFilled`.
    //

    // Angle convention: radians, 0 = +X axis, CCW positive. Same
    // as math.zig. Imgui uses a similar convention internally;
    // public API exposed in radians not degrees to avoid the
    // multiply at every call site.

    /// Stroked arc from `a0` to `a1` radians on a circle of
    /// `radius` centered at `center`. When `a1 < a0`, sweep goes
    /// clockwise (matches naive interpretation). `segments = 0`
    /// auto-derives a count from the arc length and radius (matches
    /// the existing `n_segments = 0` convention on circles).
    pub fn addArc(
        self: *DrawList,
        alloc: Allocator,
        center: Vec2,
        radius: f32,
        a0: f32,
        a1: f32,
        col: ColorU32,
        thickness: f32,
        segments: u32,
    ) void {
        if (radius <= 0 or thickness <= 0) {
            return;
        }
        const seg_count: u32 = if (segments == 0)
            autoArcSegments(radius, a1 - a0)
        else
            segments;
        if (seg_count < 1) {
            return;
        }
        const n_points: usize = @intCast(seg_count + 1);
        const points: []Vec2 = alloc.alloc(Vec2, n_points) catch return;
        defer alloc.free(points);
        const step: f32 = (a1 - a0) / float(seg_count);
        var i: usize = 0;
        while (i < n_points) : (i += 1) {
            const a: f32 = a0 + step * float(i);
            points[i] = .{
                center[0] + radius * @cos(a),
                center[1] + radius * @sin(a),
            };
        }
        // Polyline is the natural fit — `addPolyline` handles the
        // dupe-into-arena step, so points[] is safe to release on
        // function exit.
        self.addPolyline(alloc, points, col, thickness, false);
    }

    /// Filled arc (pie slice) — fan-triangulates from `center` to
    /// `segments + 1` points on the arc. When `a1 - a0 == 2π`,
    /// degenerates to a filled disk (equivalent to
    /// `addCircleFilled` minus the auto-segment-count convenience).
    /// `segments = 0` auto-derives.
    pub fn addArcFilled(
        self: *DrawList,
        alloc: Allocator,
        center: Vec2,
        radius: f32,
        a0: f32,
        a1: f32,
        col: ColorU32,
        segments: u32,
    ) void {
        if (radius <= 0) {
            return;
        }
        const seg_count: u32 = if (segments == 0)
            autoArcSegments(radius, a1 - a0)
        else
            segments;
        if (seg_count < 1) {
            return;
        }
        const step: f32 = (a1 - a0) / float(seg_count);
        // Triangle-fan: each adjacent pair of perimeter points
        // forms a triangle with the center. No allocation needed
        // — point pairs are computed on the fly.
        var i: u32 = 0;
        var prev: Vec2 = .{
            center[0] + radius * @cos(a0),
            center[1] + radius * @sin(a0),
        };
        while (i < seg_count) : (i += 1) {
            const a_next: f32 = a0 + step * float(i + 1);
            const next: Vec2 = .{
                center[0] + radius * @cos(a_next),
                center[1] + radius * @sin(a_next),
            };
            self.addTriangleFilled(alloc, center, prev, next, col);
            prev = next;
        }
    }

    /// Filled polygon over the given points, fan-triangulated from
    /// `points[0]`. Assumes the polygon is convex; concave polygons
    /// will render with overlapping triangles (caller's problem).
    /// Returns silently with < 3 points.
    pub fn addPolygon(
        self: *DrawList,
        alloc: Allocator,
        points: []const Vec2,
        col: ColorU32,
    ) void {
        if (points.len < 3) {
            return;
        }
        // Fan from points[0]. Each triangle: (0, i, i+1).
        var i: usize = 1;
        while (i + 1 < points.len) : (i += 1) {
            self.addTriangleFilled(alloc, points[0], points[i], points[i + 1], col);
        }
    }

    pub fn addTriangle(
        self: *DrawList,
        gpa: Allocator,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: ColorU32,
        thickness: f32,
    ) void {
        self.cmds.append(gpa, .{ .triangle = .{
            .a = a,
            .b = b,
            .c = c,
            .col = col,
            .thickness = thickness,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addTriangleFilled(
        self: *DrawList,
        gpa: Allocator,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .triangle_filled = .{
            .a = a,
            .b = b,
            .c = c,
            .col = col,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addQuadFilled(
        self: *DrawList,
        gpa: Allocator,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        d: Vec2,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .quad_filled = .{
            .a = a,
            .b = b,
            .c = c,
            .d = d,
            .col = col,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Circle outline. Pass `n_segments = 0` to let the replay
    /// path pick a segment count from `radius` via
    /// `autoCircleSegments`.
    pub fn addCircle(
        self: *DrawList,
        gpa: Allocator,
        center: Vec2,
        radius: f32,
        col: ColorU32,
        thickness: f32,
        n_segments: u32,
    ) void {
        self.cmds.append(gpa, .{ .circle = .{
            .center = center,
            .radius = radius,
            .col = col,
            .thickness = thickness,
            .n_segments = n_segments,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addCircleFilled(
        self: *DrawList,
        gpa: Allocator,
        center: Vec2,
        radius: f32,
        col: ColorU32,
        n_segments: u32,
    ) void {
        self.cmds.append(gpa, .{ .circle_filled = .{
            .center = center,
            .radius = radius,
            .col = col,
            .n_segments = n_segments,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Regular polygon outline. `sides` is explicit (no auto) since
    /// stylistic markers (hex, triangle) want exact shape counts.
    pub fn addNgon(
        self: *DrawList,
        gpa: Allocator,
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: ColorU32,
        thickness: f32,
    ) void {
        self.cmds.append(gpa, .{ .ngon = .{
            .center = center,
            .radius = radius,
            .sides = sides,
            .rotation_rad = rotation_rad,
            .col = col,
            .thickness = thickness,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addNgonFilled(
        self: *DrawList,
        gpa: Allocator,
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .ngon_filled = .{
            .center = center,
            .radius = radius,
            .sides = sides,
            .rotation_rad = rotation_rad,
            .col = col,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Cubic Bezier curve. Drawn at replay via raylib's
    /// `drawLineBezierCubic`.
    pub fn addBezierCubic(
        self: *DrawList,
        gpa: Allocator,
        p1: Vec2,
        p2: Vec2,
        p3: Vec2,
        p4: Vec2,
        col: ColorU32,
        thickness: f32,
    ) void {
        self.cmds.append(gpa, .{ .bezier_cubic = .{
            .p1 = p1,
            .p2 = p2,
            .p3 = p3,
            .p4 = p4,
            .col = col,
            .thickness = thickness,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn addEllipse(
        self: *DrawList,
        gpa: Allocator,
        center: Vec2,
        radius_h: f32,
        radius_v: f32,
