    /// Four-color gradient rectangle (TL, TR, BR, BL colors).
    /// Drawn at replay via raylib's `drawRectangleGradientEx`.
    pub fn addRectFilledMultiColor(
        self: *DrawList,
        gpa: Allocator,
        rect: Rectangle,
        c_tl: ColorU32,
        c_tr: ColorU32,
        c_br: ColorU32,
        c_bl: ColorU32,
    ) void {
        self.cmds.append(gpa, .{ .rect_filled_multi_color = .{
            .rect = rect,
            .c_tl = c_tl,
            .c_tr = c_tr,
            .c_br = c_br,
            .c_bl = c_bl,
        } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn pushClipRect(
        self: *DrawList,
        gpa: Allocator,
        rect: Rectangle,
    ) void {
        // Catch degenerate clip rects at submission time, not at the
        // GL boundary.  A negative-height clip eventually trips
        // WebGL's GL_INVALID_VALUE inside `rlScissor` — that
        // downstream assert exists but its stack trace points at the
        // batch replay, not the widget that pushed the bad rect.
        // Asserting here surfaces the actual caller in the wasm
        // stack and gives us the rect's components for diagnosis.
        // Width-0 / negative-height most often means a window's
        // outer size came out smaller than `title_bar_height`,
        // making `inner = outer - title_bar` go negative.
        assertf(
            rect.width >= 0 and rect.height >= 0,
            @src(),
            "DrawList.pushClipRect: degenerate rect ({d:.0},{d:.0} {d:.0}×{d:.0}) — " ++
                "width or height is negative.  Common cause: window outer size " ++
                "smaller than title_bar_height.  Clamp the source computation " ++
                "to >= 0 (e.g. `@max(0, sh - chrome)`).",
            .{ rect.x, rect.y, rect.width, rect.height },
        );
        self.cmds.append(gpa, .{ .push_clip = .{ .rect = rect } }) catch assertUnreachable(@src(), "OOM", .{});
    }

    pub fn popClipRect(self: *DrawList, gpa: Allocator) void {
        self.cmds.append(gpa, .pop_clip) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Pick a segment count for a circle of `radius` so the
    /// polygonal approximation has at most ~0.30 pixels of error
    /// against a true circle. Used when `n_segments = 0` is
    /// passed to `addCircle` / `addCircleFilled`. Port of
    /// imgui's `_CalcCircleAutoSegmentCount`.
    /// The math: an N-segment polygon approximates a circle of
    /// radius r with max edge-to-arc distance `r * (1 - cos(π/N))`.
    /// Solve for N at the target error: N = π / acos(1 - err/r).
    /// Clamp to [12, 512] to avoid degenerate cases at tiny/huge
    /// radii.
    fn autoCircleSegments(radius: f32) u32 {
        const min_segments: u32 = 12;
        const max_segments: u32 = 512;
        const max_error: f32 = 0.30;
        if (radius <= max_error) {
            return min_segments;
        }
        const ratio: f32 = 1.0 - max_error / radius;
        const denom: f32 = acosRad(ratio);
        // Huge radii drive acos(ratio) toward 0, which would send
        // n_segments to infinity. Cap explicitly.
        if (denom <= 0 or !isFinite(denom)) {
            return max_segments;
        }
        const n: f32 = pi / denom;
        if (!isFinite(n) or n >= float(max_segments)) {
            return max_segments;
        }
        const rounded: u32 = @ceil(n);
        return clamp(rounded, min_segments, max_segments);
    }

    /// Auto-derived segment count for an arc spanning `arc_angle`
    /// radians on a circle of `radius`. Uses the same error
    /// budget as `autoCircleSegments` (0.30 px max edge-to-arc
    /// distance) but scales the count to the arc fraction:
    /// `segments = autoCircleSegments(r) * (|arc_angle| / 2π)`.
    /// Clamped to [1, 512].
    fn autoArcSegments(radius: f32, arc_angle: f32) u32 {
        const full: u32 = autoCircleSegments(radius);
        const frac: f32 = @abs(arc_angle) / (2.0 * pi);
        const scaled: f32 = float(full) * frac;
        const rounded: u32 = @ceil(scaled);
        return @max(rounded, 1);
    }

    /// Replay all commands, emitting to rlgl through the existing
    /// `shapes.drawRectangleRec` / `text.draw` paths. rlgl batches
    /// the resulting vertex appends downstream.
    /// At replay time, the GL state (projection, viewport, framebuffer)
    /// must already be set up by the caller - this function just
    /// emits draw calls.
    /// `gl` is mutated for every shape/text/scissor command emitted.
    /// `window` is read-only - only the push_clip path needs canvas
    /// dimensions for the scissor y-flip. Each `.text` cmd carries
    /// its own `line_spacing` (captured at `addText` time).
    /// Replay all recorded commands. This is the deferred-render
    /// path: each `addRect`/`addText`/etc captured during widget
    /// submission gets translated into the corresponding `drawing`
    /// fn call here, in submission order.
    /// Reads `self.cmds` (the recorded command list); cmd payloads
    /// for variable-length data (`.text.s`, `.polyline.points`)
    /// carry slices into the DrawList's arena, used directly here.
    /// `shapes_state.*` provides the texture for every rect/quad;
    /// `font_cache.font` is the default font fallback for `.text`
    /// commands without a captured font.
    /// `gl` is mutated for every shape/text/scissor command emitted.
    /// `window` is read-only - only the push_clip path needs canvas
    /// dimensions for the scissor y-flip. Each `.text` cmd carries
    /// its own `line_spacing` (captured at `addText` time).
    /// `gl: anytype` - passes through to shapes2d / text2d
    /// which call method-style (`gl.begin(.quads)` etc). Both
    /// `*Gl` and `*raster.Context` satisfy the trait, so the
    /// same DrawList drives either backend.
    pub fn render(
        self: *const DrawList,
        gl: anytype,
        window: *const runtime.core.WindowState,
        shapes_state: *const shapes2d.ShapesTextureState,
        font_cache: *const text2d.FontCache,
    ) void {
        // Clip-rect stack (CSS-px). Each push intersects with the parent so a
        // nested clip can't exceed it; each pop restores the parent rather than
        // disabling the scissor outright (the old counter did the latter, which
        // both let oversized children spill past their window and left later
        // draws unclipped).
        var clip_stack: [32]Rectangle = undefined;
        var clip_top: usize = 0;
        for (self.cmds.items) |cmd| switch (cmd) {
            .rect_filled => |c| shapes2d.drawRectangleRec(gl, shapes_state, c.rect, Color.fromWire(c.col)),
            .rect_outline => |c| {
                // Four 1px filled strips. Same path as the old eager
                // drawRect - kept consistent so visuals match.
                const col: Color = Color.fromWire(c.col);
                const r: Rectangle = c.rect;
                shapes2d.drawRectangleRec(
                    gl,
                    shapes_state,
                    .{ .x = r.x, .y = r.y, .width = r.width, .height = 1 },
                    col,
                );
                shapes2d.drawRectangleRec(
                    gl,
                    shapes_state,
                    .{ .x = r.x, .y = r.y + r.height - 1, .width = r.width, .height = 1 },
                    col,
                );
                shapes2d.drawRectangleRec(
                    gl,
                    shapes_state,
                    .{ .x = r.x, .y = r.y, .width = 1, .height = r.height },
                    col,
                );
                shapes2d.drawRectangleRec(
                    gl,
                    shapes_state,
                    .{ .x = r.x + r.width - 1, .y = r.y, .width = 1, .height = r.height },
                    col,
                );
            },
            .textured_quad => |c| renderTexturedQuad(gl, c.rect, c.tex_id, c.uv0, c.uv1, c.col),
            .sprite_quad => |c| {
                // Residency resolves at replay via the backend's `image`. Backends
                // without a high-level `image` (the bare SW raster context, test
                // mocks) skip sprite draws rather than failing to compile — the UI
                // DrawList is replayed on WgpuGl in practice.
                const GlT: type = @TypeOf(gl);
                const Target: type = if (@typeInfo(GlT) == .pointer) @typeInfo(GlT).pointer.child else GlT;
                if (comptime @hasDecl(Target, "image")) {
                    gl.image(c.dst, c.sprite, c.opts);
                }
            },
            .text => |c| {
                if (c.font) |f| {
                    text2d.drawWithFont(
                        gl,
                        c.line_spacing,
                        f.*,
                        c.s,
                        c.pos,
                        c.size,
                        c.spacing,
                        Color.fromWire(c.col),
                    );
                } else {
                    text2d.draw(
                        gl,
                        font_cache,
                        c.line_spacing,
                        c.s,
                        @trunc(c.pos[0]),
                        @trunc(c.pos[1]),
                        @trunc(c.size),
                        Color.fromWire(c.col),
                    );
                }
            },
            .push_clip => |c| {
                const r: Rectangle = if (clip_top == 0)
                    c.rect
                else
                    intersectClip(clip_stack[clip_top - 1], c.rect);
                if (clip_top < clip_stack.len) {
                    clip_stack[clip_top] = r;
                    clip_top += 1;
                }
                shapes2d.beginScissorMode(
                    gl,
                    window,
                    @trunc(r.x),
                    @trunc(r.y),
                    @trunc(r.width),
                    @trunc(r.height),
                );
            },
            .pop_clip => {
                if (clip_top > 0) {
                    clip_top -= 1;
                }
                if (clip_top > 0) {
                    const r: Rectangle = clip_stack[clip_top - 1];
                    shapes2d.beginScissorMode(
                        gl,
                        window,
                        @trunc(r.x),
                        @trunc(r.y),
                        @trunc(r.width),
                        @trunc(r.height),
                    );
                } else {
                    shapes2d.endScissorMode(gl);
                }
            },

            // ---- primitive replay
            .line => |c| {
                shapes2d.drawLineThick(gl, shapes_state, c.a, c.b, c.thickness, Color.fromWire(c.col));
            },
            .polyline => |c| {
                const col: Color = Color.fromWire(c.col);
                // Render as N-1 (or N if closed) line segments. raylib's
                // drawLineStrip doesn't respect thickness, so we loop
                // drawLineThick ourselves.
                var i: usize = 0;
                while (i + 1 < c.points.len) : (i += 1) {
                    shapes2d.drawLineThick(gl, shapes_state, c.points[i], c.points[i + 1], c.thickness, col);
                }
                if (c.closed and c.points.len >= 2) {
                    shapes2d.drawLineThick(
                        gl,
                        shapes_state,
                        c.points[c.points.len - 1],
                        c.points[0],
                        c.thickness,
                        col,
                    );
                }
            },
            .triangle => |c| {
                // Three thick line segments. raylib's drawTriangleLines is
                // fixed-1px (uses RL_LINES), so we use drawLineThick for
                // each edge to honor thickness.
                const col: Color = Color.fromWire(c.col);
                shapes2d.drawLineThick(gl, shapes_state, c.a, c.b, c.thickness, col);
                shapes2d.drawLineThick(gl, shapes_state, c.b, c.c, c.thickness, col);
                shapes2d.drawLineThick(gl, shapes_state, c.c, c.a, c.thickness, col);
            },
            .triangle_filled => |c| {
                shapes2d.drawTriangle(gl, shapes_state, c.a, c.b, c.c, Color.fromWire(c.col));
            },
            .quad_filled => |c| {
                // Two triangles sharing edge a-c: (a,b,c) and (a,c,d).
                const col: Color = Color.fromWire(c.col);
                shapes2d.drawTriangle(gl, shapes_state, c.a, c.b, c.c, col);
                shapes2d.drawTriangle(gl, shapes_state, c.a, c.c, c.d, col);
            },
            .circle => |c| {
                // Outline circle = ngon outline at high segment count.
                // raylib's drawCircleLinesV is fixed-1px, but
                // drawPolyLinesThick takes both sides + thickness, which
                // is exactly what we need.
                const segs: u32 = if (c.n_segments == 0) autoCircleSegments(c.radius) else c.n_segments;
                shapes2d.drawPolyLinesThick(
                    gl,
                    shapes_state,
                    c.center,
                    @intCast(segs),
                    c.radius,
                    0,
                    c.thickness,
                    Color.fromWire(c.col),
                );
            },
            .circle_filled => |c| {
                // Filled circle = filled ngon at high segment count.
                // drawPoly + auto-segments gives us a smoother fill
                // than raylib's drawCircleV (which uses a fixed
                // 36-segment internal default).
                const segs: u32 = if (c.n_segments == 0) autoCircleSegments(c.radius) else c.n_segments;
                shapes2d.drawPoly(
                    gl,
                    shapes_state,
                    c.center,
                    @intCast(segs),
                    c.radius,
                    0,
                    Color.fromWire(c.col),
                );
            },
            .ngon => |c| {
                shapes2d.drawPolyLinesThick(
                    gl,
                    shapes_state,
                    c.center,
                    @intCast(c.sides),
                    c.radius,
                    turnsFromRad(c.rotation_rad),
                    c.thickness,
                    Color.fromWire(c.col),
                );
            },
            .ngon_filled => |c| {
                shapes2d.drawPoly(
                    gl,
                    shapes_state,
                    c.center,
                    @intCast(c.sides),
                    c.radius,
                    turnsFromRad(c.rotation_rad),
                    Color.fromWire(c.col),
                );
            },
            .bezier_cubic => |c| {
                shapes2d.drawSplineSegmentBezierCubic(
                    gl,
                    shapes_state,
                    c.p1,
                    c.p2,
                    c.p3,
                    c.p4,
                    c.thickness,
                    Color.fromWire(c.col),
                );
            },
            .ellipse => |c| {
                // No thick-line variant for ellipses in raylib (1px
                // outline only). For thicker outlines, fall back to
                // a polyline at higher segment count - not done yet.
                shapes2d.drawEllipseLinesV(
                    gl,
                    c.center,
                    c.radius_h,
                    c.radius_v,
                    Color.fromWire(c.col),
                );
                _ = c.thickness;
            },
            .ellipse_filled => |c| {
                shapes2d.drawEllipseV(gl, c.center, c.radius_h, c.radius_v, Color.fromWire(c.col));
            },
            .rect_filled_multi_color => |c| {
                // raylib's signature is (TL, BL, BR, TR) - note the
                // diagonal order vs imgui's clockwise.
                shapes2d.drawRectangleGradientEx(
                    gl,
                    shapes_state,
                    c.rect,
                    Color.fromWire(c.c_tl),
                    Color.fromWire(c.c_bl),
                    Color.fromWire(c.c_br),
                    Color.fromWire(c.c_tr),
                );
            },
        };
        // Defensive: end any scissor left dangling (should never happen
        // with a balanced widget - but if a user opened a scrollable
        // child and forgot to close it, we don't leak GL state).
        if (clip_top > 0) {
            shapes2d.endScissorMode(gl);
        }
    }
};

/// Multi-channel command buffer for rendering a region with a
/// well-defined paint order regardless of submission interleave.
///
/// Background: when rendering a table cell-by-cell, you want to
/// paint the cell background BEFORE the cell content, but both are
/// submitted while iterating columns left-to-right. Without
/// channels, painting the bg in cell N would paint over the content
/// of cell N-1. With a `DrawListSplitter`, the caller sets up two
/// channels (channel 0 = bg, channel 1 = content), submits each
/// cell's bg then content via `setCurrentChannel` + `getCurrentChannel`,
/// and at end-of-region calls `merge(target)`. The merge concatenates
/// channel 0's commands first, then channel 1's — bg under content
/// across the whole region, regardless of cell submission order.
///
/// Typical usage:
/// ```zig
/// var splitter: DrawListSplitter =.{};
/// defer splitter.deinit(alloc);
/// try splitter.split(alloc, 2);
/// for (cells) |cell| {
///     splitter.setCurrentChannel(0);
///     if (splitter.getCurrentChannel()) |dl| dl.addRectFilled(alloc, cell.rect, bg);
///     splitter.setCurrentChannel(1);
///     if (splitter.getCurrentChannel()) |dl| dl.addText(alloc, font, cell.text,...);
/// }
/// try splitter.merge(alloc, &window.draw_list);
/// ```
///
/// ImGui equivalent: `ImDrawListSplitter` (imgui_draw.cpp). The
/// zimr API factors `target` out of `merge` (ImGui ties it to the
/// owning draw list); this lets a caller merge channels into a
/// different draw list than the recording originated from, which
/// can be useful for compositing into parent windows' draw lists.
pub const DrawListSplitter = struct {
    /// Side channels. Each channel records commands independently.
    /// Order in this slice determines the final order of commands
    /// in the target DrawList on `merge()` — channel 0's commands
    /// go first, channel N-1's last.
    channels: ArrayList(DrawList) = .empty,

    /// Index of the active channel — the one `getCurrentChannel()`
    /// returns. Initialized to 0 by `split()`. `setCurrentChannel`
    /// updates it.
    current: usize = 0,

    /// Free channel storage. Pass the same allocator used by
    /// `split()` (and by any `add*` calls on the channels).
    pub fn deinit(self: *DrawListSplitter, alloc: Allocator) void {
        for (self.channels.items) |*ch| {
            ch.deinit(alloc);
        }
        self.channels.deinit(alloc);
    }

    /// Allocate `n` empty channels. Calling `split` again is
    /// allowed — the new layout supersedes any previous one (any
    /// unmerged commands are lost; channel storage is freed first).
    /// Errors propagate from the underlying ArrayList allocations.
    pub fn split(
        self: *DrawListSplitter,
        alloc: Allocator,
        n: usize,
    ) !void {
        for (self.channels.items) |*ch| {
            ch.deinit(alloc);
        }
        self.channels.clearRetainingCapacity();
        try self.channels.ensureTotalCapacity(alloc, n);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            self.channels.appendAssumeCapacity(.{});
        }
        self.current = 0;
    }

    /// Switch the active channel. Subsequent `getCurrentChannel()`
    /// calls return this index's DrawList. Out-of-range indices
    /// are clamped to the last channel — defensive default so a
    /// misconfigured call doesn't crash the render path. When the
    /// splitter has no channels (split() not yet called), `current`
    /// is forced to 0.
    pub fn setCurrentChannel(self: *DrawListSplitter, i: usize) void {
        if (self.channels.items.len == 0) {
            self.current = 0;
            return;
        }
        self.current = @min(i, self.channels.items.len - 1);
    }

    /// Get the active channel's DrawList — call `add*` methods on
    /// the returned pointer. Returns null when the splitter has
    /// no channels (split() wasn't called, or was called with n=0).
    pub fn getCurrentChannel(self: *DrawListSplitter) ?*DrawList {
        if (self.current >= self.channels.items.len) {
            return null;
        }
        return &self.channels.items[self.current];
    }

    /// Concatenate all channel command lists into `target` in
    /// channel-index order (channel 0 first, channel N-1 last),
    /// then empty each channel (clearRetainingCapacity — the
    /// channels remain valid for further `add*` calls). The
    /// splitter is ready for a new `split()` after this.
    /// Allocates only to grow `target.cmds`. Errors propagate
    /// from the underlying append.
    pub fn merge(
        self: *DrawListSplitter,
        alloc: Allocator,
        target: *DrawList,
    ) !void {
        for (self.channels.items) |*ch| {
            try target.cmds.appendSlice(alloc, ch.cmds.items);
            ch.cmds.clearRetainingCapacity();
        }
    }
};

/// Allocator-bound handle over a `*DrawList`. What the user
/// receives from `Ui.getBackgroundDrawList` / `Ui.getForegroundDrawList`.
/// The underlying `DrawList.add*` methods each take an allocator as
/// their first argument (the UiContext's frame arena). Plumbing
/// that allocator through every call site at user code would be
/// noisy and error-prone - pair it once with the list pointer here
/// and the user can write `dl.addRectFilled(rect, col)` with no
/// allocator visible.
/// The most common 8 add* methods are wrapped directly. For less-
/// common ones (textured quads, polylines, bezier curves, ellipses,
/// multi-color gradients, clip rects, etc.) reach through `dl.list`
/// and pass `dl.gpa` explicitly:
///     dl.list.addEllipse(dl.gpa, center, radii, col, 0, 32, 1);
/// The handle is cheap (one pointer + one Allocator interface =
/// 24 bytes) and is meant to be created per call site and dropped.
pub const DrawListHandle = struct {
    list: *DrawList,
    gpa: Allocator,

    pub fn addRectFilled(
        self: DrawListHandle,
        r: Rectangle,
        col: Color,
    ) void {
        self.list.addRectFilled(self.gpa, r, col.toWire());
    }

    pub fn addRectOutline(
        self: DrawListHandle,
        r: Rectangle,
        col: Color,
    ) void {
        self.list.addRectOutline(self.gpa, r, col.toWire());
    }

    // ---- Unified draw2d surface (see notes/drawing_api.md). Thin wrappers over
    // the add* methods above: Color at the surface (packed via toWire internally),
    // the frame-arena allocator held by the handle. Rounding + outline thickness
    // beyond 1px are deferred on the DrawList (the add* rect methods don't take
    // them yet); `line`/`text` are deferred pending the plot-sink reconciliation.

    /// Fill or 1px-outline a `Rectangle`.
    pub fn rect(self: DrawListHandle, r: Rectangle, opts: draw2d.RectOpts) void {
        if (opts.outline <= 0) {
            self.addRectFilled(r, opts.color);
        } else {
            self.addRectOutline(r, opts.color);
        }
    }

    /// `rect` twin taking loose numbers.
    pub fn rectXYWH(
        self: DrawListHandle,
        x: f32,
        y: f32,
        w: f32,
        h: f32,
        opts: draw2d.RectOpts,
    ) void {
        self.rect(.{ .x = x, .y = y, .width = w, .height = h }, opts);
    }

    /// Fill or stroke a circle. `segments` and outline thickness pass straight
    /// through to the underlying add* methods.
    pub fn circle(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        opts: draw2d.CircleOpts,
    ) void {
        if (opts.outline <= 0) {
            self.list.addCircleFilled(self.gpa, center, radius, opts.color.toWire(), opts.segments);
        } else {
            self.list.addCircle(self.gpa, center, radius, opts.color.toWire(), opts.outline, opts.segments);
        }
    }

    /// Unified primitive: a thick line from `a` to `b`.
    pub fn line(self: DrawListHandle, a: Vec2, b: Vec2, opts: draw2d.LineOpts) void {
        self.addLine(a, b, opts.color, opts.thickness);
    }

    /// Unified primitive: a filled triangle.
    pub fn triangle(
        self: DrawListHandle,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        opts: draw2d.ShapeOpts,
    ) void {
        self.list.addTriangleFilled(self.gpa, a, b, c, opts.color.toWire());
    }

    /// Unified primitive: draw `str` at `pos`. `opts.font` null → the UiContext's
    /// default font; recorded for replay, so a non-null font must outlive the frame.
    pub fn text(
        self: DrawListHandle,
        pos: Vec2,
        str: []const u8,
        opts: draw2d.TextOpts,
    ) void {
        self.list.addText(self.gpa, opts.font, str, pos, opts.size, opts.spacing, 0, opts.color.toWire());
    }

    /// Unified primitive: draw `sprite` at `dst`. Recorded now; residency (upload
    /// + cache) resolves at replay via the backend's `image`, so the sprite's
    /// pixels must outlive the frame (true for the per-frame DrawList).
    pub fn image(
        self: DrawListHandle,
        dst: Rectangle,
        sprite: Sprite,
        opts: draw2d.ImageOpts,
    ) void {
        self.list.addSpriteQuad(self.gpa, dst, sprite, opts);
    }

    /// `image` twin taking loose numbers for the destination.
    pub fn imageXYWH(
        self: DrawListHandle,
        x: f32,
        y: f32,
        w: f32,
        h: f32,
        sprite: Sprite,
        opts: draw2d.ImageOpts,
    ) void {
        self.image(.{ .x = x, .y = y, .width = w, .height = h }, sprite, opts);
    }

    pub fn addText(
        self: DrawListHandle,
        s: []const u8,
        pos: Vec2,
        size: f32,
        col: Color,
    ) void {
        // Spacing + line_spacing default to the same values
        // `text.draw` would use - 1 px char spacing, no extra line
        // height beyond the font's native baseline-to-baseline.
        // Pass null for `font` so the renderer uses the default
        // font cached on the UiContext.
        self.list.addText(self.gpa, null, s, pos, size, 1, 0, col.toWire());
    }

    pub fn addLine(
        self: DrawListHandle,
        p0: Vec2,
        p1: Vec2,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addLine(self.gpa, p0, p1, col.toWire(), thickness);
    }

    pub fn addCircle(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        col: Color,
        thickness: f32,
    ) void {
        // n_segments = 0 → DrawList picks an automatic count based
        // on radius (~0.30 px error against a true circle).
        self.list.addCircle(self.gpa, center, radius, col.toWire(), thickness, 0);
    }

    pub fn addCircleFilled(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        col: Color,
    ) void {
        self.list.addCircleFilled(self.gpa, center, radius, col.toWire(), 0);
    }

    pub fn addTriangle(
        self: DrawListHandle,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addTriangle(self.gpa, a, b, c, col.toWire(), thickness);
    }

    pub fn addTriangleFilled(
        self: DrawListHandle,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        col: Color,
    ) void {
        self.list.addTriangleFilled(self.gpa, a, b, c, col.toWire());
    }

    pub fn addQuadFilled(
        self: DrawListHandle,
        a: Vec2,
        b: Vec2,
        c: Vec2,
        d: Vec2,
        col: Color,
    ) void {
        self.list.addQuadFilled(self.gpa, a, b, c, d, col.toWire());
    }

    pub fn addPolyline(
        self: DrawListHandle,
        points: []const Vec2,
        col: Color,
        thickness: f32,
        closed: bool,
    ) void {
        self.list.addPolyline(self.gpa, points, col.toWire(), thickness, closed);
    }

    /// Stroked arc, radians, 0=+X, CCW positive. `segments = 0`
    /// auto-derives from radius + arc fraction.
    pub fn addArc(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        a0: f32,
        a1: f32,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addArc(self.gpa, center, radius, a0, a1, col.toWire(), thickness, 0);
    }

    /// Filled arc / pie slice. Pass `a1 - a0 == 2π` for a full
    /// disk equivalent to `addCircleFilled`.
    pub fn addArcFilled(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        a0: f32,
        a1: f32,
        col: Color,
    ) void {
        self.list.addArcFilled(self.gpa, center, radius, a0, a1, col.toWire(), 0);
    }

    /// Filled convex polygon, fan-triangulated from points[0].
    pub fn addPolygon(
        self: DrawListHandle,
        points: []const Vec2,
        col: Color,
    ) void {
        self.list.addPolygon(self.gpa, points, col.toWire());
    }

    pub fn addBezierCubic(
        self: DrawListHandle,
        p1: Vec2,
        p2: Vec2,
        p3: Vec2,
        p4: Vec2,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addBezierCubic(self.gpa, p1, p2, p3, p4, col.toWire(), thickness);
    }

    pub fn addNgon(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addNgon(self.gpa, center, radius, sides, rotation_rad, col.toWire(), thickness);
    }

    pub fn addNgonFilled(
        self: DrawListHandle,
        center: Vec2,
        radius: f32,
        sides: u32,
        rotation_rad: f32,
        col: Color,
    ) void {
        self.list.addNgonFilled(self.gpa, center, radius, sides, rotation_rad, col.toWire());
    }

    pub fn addEllipse(
        self: DrawListHandle,
        center: Vec2,
        radius_h: f32,
        radius_v: f32,
        col: Color,
        thickness: f32,
    ) void {
        self.list.addEllipse(self.gpa, center, radius_h, radius_v, col.toWire(), thickness);
    }

    pub fn addEllipseFilled(
        self: DrawListHandle,
        center: Vec2,
        radius_h: f32,
        radius_v: f32,
        col: Color,
    ) void {
        self.list.addEllipseFilled(self.gpa, center, radius_h, radius_v, col.toWire());
    }
};

/// All per-scope layout state. One LayoutScope lives on each
/// `Window`; `beginChild` pushes the parent's onto a stack and
/// installs a fresh one for the child. Centralizing this state
/// fixes the four turn-308 bugs (sameLine, layout_origin, splitter
/// pos, treePop indent) and preempts the same pattern of bug for
/// every future scope-aware feature (per-child scrolling,
/// docking, treeNode draw_lines).
/// Field group rationale:
/// - `origin` - where THIS scope's content area starts. For a
///   top-level window, this is the inside of the window padding.
///   For a child, the child rect's inner-top-left. advanceLayout's
///   row-reset uses this; sameLine with `offset_x > 0` uses this.
/// - `cursor_pos` - where the NEXT widget will be placed. Most
///   widgets read this at submission start and write to it at end
///   via advanceLayout.
/// - `cursor_max` - bottom-right of laid-out content. Used for
///   auto-fit window sizing and scroll_max computation.
/// - `cursor_pos_prev_line` / `prev_line_height` - track the
///   previous row's right edge and tallest widget. `sameLine`
///   reads these to restore the cursor onto the previous row
///   instead of the wrap-advanced position. Matches imgui's
///   `DC.CursorPosPrevLine` / `DC.PrevLineSize.y`.
/// - `line_height` - tallest widget on the CURRENT row,
///   accumulating as sameLine adds more widgets. Reset to 0
///   when the cursor wraps to the next row. Matches imgui's
///   `DC.CurrLineSize.y`.
/// - `indent_x` - current indent depth. `treeNode` / `indent()`
///   push; `treePop` / `unindent()` pop. Added to `origin[0]`
///   on row wrap.
/// - `last_item_*` - bookkeeping for `IsItemHovered` /
///   `IsItemActive` / `IsItemEdited` etc. Set by widgets on
///   submission.
pub const LayoutScope = struct {
    /// Top-left of this scope's content area (screen px). COUPLED to
    /// `cursor_pos`: row 0 is placed at `cursor_pos`, but `advanceLayout`
    /// resets every later row's X to `origin[0] + indent - scroll_x`. So
    /// `origin` and `cursor_pos` MUST be initialized together — set one
    /// without the other and rows 2+ snap to the stale origin (default
    /// {0,0} = canvas left). Always init via `resetContentLayout`, never
    /// by assigning `cursor_pos` alone (that was the combo/popup bug).
    origin: Vec2 = .{ 0, 0 },
    /// Bottom-right of this scope's content area (screen px).
    /// Used by `getContentRegionAvail` and `beginChild`'s auto-fill
    /// (size=0 dimension) to know HOW MUCH room is available without
    /// reaching past the scope. Imgui: `ImGuiWindow.WorkRect.Max`.
    /// At window-open this is the inner bottom-right (window rect
    /// minus padding + title bar). At `beginChild` it's the child
    /// rect's inner bottom-right. Restored on `endChild` along
    /// with the rest of `LayoutScope`.
    /// Without this, nested children's auto-fill / region-avail
    /// queries reached past the immediate parent into the top-level
    /// window - caused the right-pane spillover where
    /// the editor pane (auto-fill width=0) inside the right pane
    /// rendered past the right pane's right edge.
    work_rect_max: Vec2 = .{ 0, 0 },

    /// Where the next widget will be placed.
    cursor_pos: Vec2 = .{ 0, 0 },
    /// Bottom-right of all laid-out content.
    cursor_max: Vec2 = .{ 0, 0 },

    /// (right edge of last item, top of current row). `sameLine`
    /// restores cursor X from `[0]`, Y from `[1]`. Imgui:
    /// `DC.CursorPosPrevLine`.
    cursor_pos_prev_line: Vec2 = .{ 0, 0 },
    /// Tallest widget on the CURRENT row. Accumulates across
    /// sameLine submissions. Reset to 0 by advanceLayout when
    /// the row wraps.
    line_height: f32 = 0,
    /// Tallest widget on the PREVIOUS row. Set by advanceLayout
    /// when the row wraps; read by `sameLine` to restore
    /// `line_height` for ongoing accumulation on the row that
    /// sameLine just rejoined. Imgui: `DC.PrevLineSize.y`.
    prev_line_height: f32 = 0,

    /// Indent depth. Added to `origin[0]` on every row wrap.
    indent_x: f32 = 0,

    /// Last-item bookkeeping - set by widgets, queried by
    /// `isItemHovered` / `isItemActive` / etc.
    last_item_id: Id = 0,
    last_item_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 },
    last_item_hovered: bool = false,
    last_item_edited: bool = false,
    last_item_clicked: bool = false,
    last_item_activated: bool = false,
    last_item_deactivated: bool = false,
    last_item_deactivated_after_edit: bool = false,
};

/// Per-window flags. These control window-category behavior (is it
/// a child? a popup? a tooltip?) and what chrome to render (title
/// bar, move-on-drag, resize grips). Default-init = "ordinary
/// user-created top-level window."
/// Maps to imgui's `ImGuiWindowFlags_*` bit constants, but expressed
/// as a Zig struct-of-bools so each flag is independently
/// type-checked. Bit-flag enums save 8 bytes; the type safety is
/// worth more than 8 bytes in our case.
pub const WindowFlags = struct {
    /// True if this window was opened via `beginChild`. Affects
    /// chrome (no title bar, no move handle) and how `endFrame`
    /// renders it (children submit into the parent's draw list via
    /// clip-rect stacking, not as separate top-level windows).
    is_child: bool = false,

    // ---- Chrome suppression -------------------------
    // Each flag suppresses one piece of window chrome. Combine freely;
    // a borderless overlay is `.{.no_title_bar = true,.no_resize = true,
    // .no_move = true,.no_background = true }`. Matches imgui's
    // `ImGuiWindowFlags_NoTitleBar` / `NoResize` / `NoMove` /
    // `NoCollapse` / `NoBackground` / `NoScrollbar` semantics.

    /// Skip the title-bar rect + text rendering AND the title-bar
    /// drag handle. Content origin shifts up by `title_bar_height`.
    /// Useful for fullscreen overlays and toolbars.
    no_title_bar: bool = false,
    /// Skip the corner resize grip render + the resize drag hit-test.
    /// The window keeps whatever size it was created with (or last
    /// got via `setNextWindowSize`). Pair with explicit `initial_size`
    /// to lock window dimensions.
    no_resize: bool = false,
    /// Skip the title-bar drag hit-test. The title bar still renders
    /// (unless `no_title_bar` is also set); only the drag-to-move
    /// behavior is disabled. Useful for fixed-position chrome.
    no_move: bool = false,
    /// Reserve a flag slot for "skip the collapse arrow / toggle."
    /// Currently a NO-OP: zimr doesn't yet ship a collapsible-window
    /// mechanism (windows are always uncollapsed). Setting this is
    /// future-proof — once collapse lands, the flag attaches at the
    /// new hit-test site automatically.
    no_collapse: bool = false,
    /// Skip the window-background `drawRectFilled` before content.
    /// Use for transparent overlays where the content provides its
    /// own backdrop (e.g. a HUD over a 3D scene). The frame border,
    /// title bar, and grip still render — those are separate
    /// chrome elements; suppress them with the matching flags if you
    /// want a fully invisible window.
    no_background: bool = false,
    /// Skip scrollbar render AND skip wheel-scroll consumption when
    /// this window is hovered. Content that overflows the window
    /// remains clipped, just not scrollable. Useful for fixed
    /// dashboards / HUD windows that should never scroll.
    no_scrollbar: bool = false,

    // ---- Sizing -------------------------------------
    // Three sizing-related flags mirroring imgui's
    // `ImGuiWindowFlags_AlwaysAutoResize` / `_AlwaysUseWindowPadding` /
    // `_NoSavedSettings`.

    /// Every frame, shrink-to-fit content regardless of any previous
    /// `user_resized` state. Persisted size is ignored when this
    /// flag is set on first submission. Combine with `no_resize`
    /// for a pure content-fit overlay (toast notification, status
    /// pill). Imgui: `ImGuiWindowFlags_AlwaysAutoResize`.
    always_auto_resize: bool = false,
    /// Reserved slot. Top-level windows always pad with
    /// `style.window_padding` today, so this flag is currently a
    /// NO-OP for them. For children, the equivalent already exists
    /// as `ChildFlags.always_use_window_padding` (use that path
    /// today). Wiring this flag for top-level windows in the future
    /// would mean "even when other layout overrides shrink the
    /// inner rect to zero, keep the padding gap visible" — not yet
    /// a real failure mode. Imgui:
    /// `ImGuiWindowFlags_AlwaysUseWindowPadding`.
    always_use_window_padding: bool = false,
    /// Exclude this window from `.zon` persistence. The serializer
    /// skips windows with this flag set; the loader can't see them
    /// (they were never written). Use for transient inspector
    /// windows, debug overlays, or any UI element whose
    /// pos/size shouldn't survive across sessions. Imgui:
    /// `ImGuiWindowFlags_NoSavedSettings`.
    no_saved_settings: bool = false,

    // ---- Focus + ordering ---------------------------
    // All four flags are RESERVED slots today. zimr's render order is
    // purely submission-driven (no internal z-order sort) and there's
    // no keyboard-nav state machine, so the imgui semantics these
    // mirror have nothing to gate against yet. Same convention as
    // `no_collapse` (P5.1) and `always_use_window_padding` (P5.2):
    // reserve the API surface now, wire when the mechanism lands.

    /// Skip auto-focus-on-first-appearance. NO-OP today: zimr does
    /// not currently auto-focus newly-appeared windows (a window's
    /// `focused_window_id` only flips on click / `setNextWindowFocus`).
    /// Wires when first-frame-detection + auto-focus default lands.
    /// Imgui: `ImGuiWindowFlags_NoFocusOnAppearing`.
    no_focus_on_appearing: bool = false,
    /// Focusing this window does NOT reorder it to the top of the
    /// render stack. NO-OP today: zimr renders windows in the order
    /// the caller submits them — no internal focus-driven reorder
    /// exists yet. Wires when a `last_focus_frame: u64` is added to
    /// `Window` and `endFrame` sorts `frame_windows` by it.
    /// Imgui: `ImGuiWindowFlags_NoBringToFrontOnFocus`.
    no_bring_to_front_on_focus: bool = false,
    /// Skip this window when navigating with the keyboard. NO-OP
    /// today: zimr has no keyboard-nav state machine. Wires when
    /// nav infrastructure lands. Imgui: `ImGuiWindowFlags_NoNavFocus`.
    no_nav_focus: bool = false,
    /// Don't accept keyboard nav inputs targeted at this window.
    /// NO-OP today (same reason as `no_nav_focus`). Wires when
    /// nav infrastructure lands. Imgui: `ImGuiWindowFlags_NoNavInputs`.
    no_nav_inputs: bool = false,

    // ---- Input passthrough --------------------------
    // Two flags that make a window "see-through" for input. Used for
    // HUD overlays, decorative panels, and any UI element that
    // shouldn't capture mouse interaction over content underneath.
    // Mechanism: zimr's hover resolution lives in `openWindow` — each
    // submitted window unconditionally claims hover if the mouse is
    // inside its outer rect, and submission order is back-to-front
    // (the LAST overwriter wins). These flags skip the claim, so a
    // covered window underneath keeps the hover. Since every other
    // interaction (title-drag, resize, click, wheel) gates on
    // `hovered_window_id == w.id`, the flagged window becomes
    // mechanically passthrough.

    /// Skip mouse input claiming for this window. Hover, clicks, and
    /// wheel events pass through to whatever window is underneath.
    /// Imgui: `ImGuiWindowFlags_NoMouseInputs`.
    no_mouse_inputs: bool = false,
    /// Skip ALL input claiming. Today this is equivalent to
    /// `no_mouse_inputs` (zimr has no keyboard-nav yet); future-proof
    /// for when nav lands. Imgui: `ImGuiWindowFlags_NoInputs`.
    no_inputs: bool = false,

    // ---- Document + menubar markers ----------------
    // Two small flags that complete the P5 wave (horizontal scroll
    // is the remaining piece, shipped separately in P5.5b).

    /// Required for `beginMenuBar` to return true. Without it,
    /// `beginMenuBar` returns false and the body is skipped — matches
    /// imgui's `ImGuiWindowFlags_MenuBar` contract. Default false so
    /// existing callers that DIDN'T use menu bars continue to work;
    /// callers that DID call `beginMenuBar` without the flag (which
    /// previously opened unconditionally) need to set the flag now.
    /// Imgui: `ImGuiWindowFlags_MenuBar`.
    menu_bar: bool = false,
    /// Render a "modified" marker (" *") after the title text in the
    /// title bar. Pure visual; no behavioral side-effects. Use for
    /// text editors / document panels with unsaved changes.
    /// Imgui: `ImGuiWindowFlags_UnsavedDocument`.
    unsaved_document: bool = false,

    // ---- Horizontal scrollbar ----------------------

    /// Opt into a horizontal scrollbar when content overflows the
    /// window's width. Without this flag, X-overflow is silent —
    /// content gets clipped at the window's right edge. With it,
    /// `scroll_max_x > 0` triggers `renderScrollbarX` on the
    /// window's bottom edge, and wheel-X gestures translate to
    /// `scroll_x` updates. Imgui:
    /// `ImGuiWindowFlags_HorizontalScrollbar`.
    horizontal_scrollbar: bool = false,
    // Future: popup, tooltip, modal, dock_node - added as features
    // land in Phases 2-5.
    // is_popup: bool = false,
    // is_tooltip: bool = false,
};

pub const Window = struct {
    id: Id,
    name_buf: [128]u8 = undefined,
    name_len: usize = 0,

    /// Top-left of the window in screen pixels.
    pos: Vec2,
    /// Window outer size in pixels (includes title bar).
    size: Vec2,

    /// All per-scope layout state - cursor, indent, last-item
    /// bookkeeping, etc. See `LayoutScope` for field-by-field docs.
    /// Each Window owns its layout outright - children are full
    /// `Window`s with their own `layout`, so the parent's `layout` is never mutated during
    /// a child's scope.
    layout: LayoutScope = .{},

    /// Frame counter at last submission. Future GC pass drops
    /// windows not seen in N frames; not implemented in.
    last_frame_active: u64 = 0,

    /// Per-window draw command list. Widgets append commands during
    /// submission; the renderer replays the list at endFrame. Cleared
    /// (and the underlying memory recycled via the shared
    /// `UiContext.frame_arena`) at each `openWindow`. Default-inits
    /// because all storage is owned by the ctx-level arena, not the
    /// DrawList itself.
    draw_list: DrawList = .{},

    // ---- scroll + user-resize state
    /// Vertical scroll offset in pixels. When positive, content
    /// renders shifted UP by this amount; effectively the y-coord of
    /// the visible top edge inside the content area. Clamped to
    /// `[0, scroll_max_y]` at end-of-frame.
    scroll_y: f32 = 0,
    /// Maximum allowed `scroll_y` - recomputed every frame in
    /// `closeWindow` from `cursor_max.y - viewport_h`. Zero means
    /// content fits, no scrollbar shown.
    scroll_max_y: f32 = 0,
    /// P5.5b: horizontal scroll offset in pixels, analog
    /// of `scroll_y`. Content widgets read this via the layout
    /// origin shift in `openWindow`. Only meaningful when the
    /// window's `WindowFlags.horizontal_scrollbar` is set; otherwise
    /// stays at 0 and content beyond the window's right edge is
    /// clipped without scrollbar.
    scroll_x: f32 = 0,
    /// Maximum allowed `scroll_x` — analog of `scroll_max_y`.
    /// Recomputed every frame in `closeWindow` from
    /// `cursor_max.x - viewport_w` when the horizontal-scrollbar
    /// flag is set.
    scroll_max_x: f32 = 0,

    /// Touch-pan scroll bookkeeping.  When the user touch-drags
    /// across the window body and no widget claims the input,
    /// the gesture pans `scroll_y` (and `scroll_x` if H-scrollbar
    /// enabled).  Captured at gesture start so each frame's scroll
    /// can be computed from the absolute mouse delta, avoiding
    /// drift from per-frame integration.
    touch_pan_active: bool = false,
    touch_pan_start_mouse: Vec2 = .{ 0, 0 },
    touch_pan_start_scroll_y: f32 = 0,
    touch_pan_start_scroll_x: f32 = 0,
    /// True once the user has manually resized this window via the
    /// corner grip (or the user passed an explicit `setNextWindow
    /// Size`). When true, `closeWindow` skips the auto-fit grow
    /// behaviour so content overflow shows a scrollbar instead of
    /// silently re-growing the window.
    user_resized: bool = false,

    /// Only used by the tooltip-block window - stash points for the
    /// current_window / current_draw_list at `beginTooltip` so
    /// `endTooltip` can restore them. Untouched on normal windows.
    saved_window_ptr: ?*Window = null,
    saved_draw_list: ?*DrawList = null,

    // ---- Turn 309d: child-as-Window plumbing
    // Children are now full `Window` values stored in `ctx.windows`
    // keyed by their hashed ID (parent_id_stack ⊕ str_id). See
    // `beginChildImpl` / `endChildImpl` and the architecture tutorial
    // at `src/notes/architecture-imgui-vs-zimr.md` for the rationale.

    /// Window category + behavior flags. Top-level windows have all
    /// these false; children flip `is_child`; popups flip
    /// `no_title_bar` and `no_move`; etc. Matches imgui's
    /// `ImGuiWindowFlags` (we'll grow this as features land).
    flags: WindowFlags = .{},

    /// Parent window's persistent ID (only set when `flags.is_child`).
    /// Null for top-level windows. Used by `endChild` to find the
    /// parent on the window stack for cursor advancement, and by
    /// future docking / nav features. Imgui equivalent: `ParentWindow`
    /// (a direct pointer; we use ID-by-value to keep `Window` POD-ish
    /// and avoid lifetime hazards if the parent is GC'd).
    parent_id: ?Id = null,

    /// docking attachment. Non-null when
    /// this window has been routed into a dock leaf - either by
    /// the user dragging it into a dock zone, or programmatically
    /// via `dockBuilderDockWindow`. When set, `findOrCreateWindow`
    /// → `openWindow` route through `beginDockedWindow` instead of
    /// rendering free-floating chrome; the window's content
    /// occupies the leaf's rect minus the tab strip at top.
    /// Cleared by `undockWindow` or by docking elsewhere. The
    /// dock layer maintains the inverse mapping (leaf → window list)
    /// so the routing here is informational rather than canonical.
    /// Restored from persistence via `PersistedWindow.dock_node_id`
    /// (when 5.5k lands).
    dock_node_id: ?Id = null,
    /// Frame counter of this window's most recent focus; floating windows render
    /// sorted by this (ascending) so the focused one draws on top.
    last_focus_frame: u64 = 0,
    /// True if this window hosts a dockSpace; kept out of the focus reorder so it
    /// stays behind its docked children.
    hosts_dockspace: bool = false,

    /// pos/size at the moment this window
    /// first docked. Used to restore the window to its pre-dock
    /// rect when it undocks - without this, an undocked window
    /// stays at the leaf's rect, which is rarely where the user
    /// wants it.
    /// `null` means "this window has never been docked, or it has
    /// been undocked and restored, no stash to apply."
    /// imgui parallel: `AuthorityForPos/Size` 3-bit fields on
    /// ImGuiDockNode track ownership granularly per-axis. Our
    /// model is simpler - just stash + restore as a unit. Loses
    /// the "I docked, then moved the leaf, now undocking should
    /// keep the leaf's pos" nuance; gains a much simpler mental
    /// model. Filed as JUSTIFIED divergence in the audit.
    pre_dock_pos: ?Vec2 = null,
    pre_dock_size: ?Vec2 = null,

    pub fn name(self: *const Window) []const u8 {
        return self.name_buf[0..self.name_len];
    }
};

// ============================================================================
// HoveredFlags / FocusedFlags - query-tuning flags for the `Ex` variants
// of `isItemHovered`, `isWindowHovered`, `isWindowFocused`.
// ============================================================================
// Maps to imgui's `ImGuiHoveredFlags_*` + `ImGuiFocusedFlags_*` bit
// constants. pull-forward - these gate behavior
// the docking system relies on ("is the dockspace's host OR any of
// its docked windows focused?" → `FocusedFlags{.root_and_child_windows }`).
// Hover-delay fields (delay_short, delay_normal, no_shared_delay,
// stationary, for_tooltip) are DEFERRED until a follow-up turn lands
// the per-item-id hover-start timestamp infra. Adding the flag with
// no implementation would be a footgun; we'd rather have the API
// surface track what's actually wired.
// Many flags (allow_when_blocked_by_*, allow_when_overlapped_by_*,
// allow_when_disabled, no_nav_override) are accepted but EFFECTIVELY
// NO-OP today: zimr doesn't yet implement modal-popup blocking,
// active-item occlusion, or keyboard-nav state. When those land,
// the flag's effect attaches at that line - no API churn for users
// who set the flag now. Doc-string on each field calls this out.

/// Flag set for `isItemHovered` and `isWindowHovered`. All
/// default to false; pass `.{}` for "no special flags."
/// Zig idiom: struct-of-bools rather than imgui's bit-flag enum.
/// Each flag is independently type-checked at the call site; you
/// cannot mistype `ChildWindwos` (typo) and have it silently default
/// to 0 - the compiler catches it.
pub const HoveredFlags = struct {
    /// `isWindowHovered` only: return true if the mouse is over
    /// THIS window OR any of its child windows. Without this flag,
    /// a parent window is NOT considered hovered when the mouse is
    /// over one of its children (the child obstructs).
    child_windows: bool = false,
    /// `isWindowHovered` only: walk up the `parent_id` chain to
    /// the root before testing. Combined with `child_windows`,
    /// gives "any window in my hierarchy is hovered."
    root_window: bool = false,
    /// `isWindowHovered` only: return true if ANY window in this
    /// `UiContext` is hovered (mouse over any window's outer rect).
    /// IMPORTANT: do NOT use this to gate low-level input dispatch;
    /// for "should I capture this click?" use the relevant scope's
    /// per-scope hovered state.
    any_window: bool = false,
    /// `isWindowHovered` only: don't consider popup hierarchy
    /// when traversing (treat popups as independent windows even
    /// when combined with `child_windows`/`root_window`). No-op
    /// today until popups gain a proper hierarchy link.
    no_popup_hierarchy: bool = false,

    /// Return true even if a popup window normally blocks access
    /// to this item/window. **NO-OP today** - popup-blocking is
    /// not yet implemented; landed when modals land.
    allow_when_blocked_by_popup: bool = false,
    /// Return true even if an `active_id` is set on a DIFFERENT
    /// item. Useful for drag-and-drop patterns (source stays
    /// "hovered" so its preview tooltip can render while dragging).
    /// **NO-OP today** - active-id occlusion is not yet implemented.
    allow_when_blocked_by_active_item: bool = false,
    /// `isItemHovered` only: return true even if the item uses
    /// `setNextItemAllowOverlap` and is overlapped by a later item.
    /// **NO-OP today** - `setNextItemAllowOverlap` is filed in
    /// .
    allow_when_overlapped_by_item: bool = false,
    /// `isItemHovered` only: return true even if obstructed by
    /// a later window covering the position. **NO-OP today**
    /// per-item z-order obstruction isn't tracked; only per-window
    /// is (via `ctx.hovered_window_id`).
    allow_when_overlapped_by_window: bool = false,
    /// `isItemHovered` only: return true even if the item is
    /// disabled. **NO-OP today** - disabled-state hover gating
    /// isn't yet implemented.
    allow_when_disabled: bool = false,
    /// `isItemHovered` only: disable using keyboard/gamepad nav
    /// state, always query mouse. **NO-OP today** - keyboard nav
    /// affecting hover is not yet implemented.
    no_nav_override: bool = false,

    /// Convenience: "any window hovered without occlusion checks."
    /// Equivalent to imgui's `ImGuiHoveredFlags_RectOnly`.
    pub const rect_only: HoveredFlags = .{
        .allow_when_blocked_by_popup = true,
        .allow_when_blocked_by_active_item = true,
        .allow_when_overlapped_by_item = true,
        .allow_when_overlapped_by_window = true,
    };
    /// Convenience: walk to root AND include all children.
    /// Equivalent to imgui's `ImGuiHoveredFlags_RootAndChildWindows`.
    pub const root_and_child_windows: HoveredFlags = .{
        .root_window = true,
        .child_windows = true,
    };
};

/// Flag set for `isWindowFocused`. Same hierarchy-traversal
/// semantics as `HoveredFlags`'s window-traversal fields.
pub const FocusedFlags = struct {
    /// True if THIS window OR any child has focus. Without it, a
    /// parent reports unfocused when focus is on a child.
    child_windows: bool = false,
    /// Walk to root before testing. With `child_windows`: "is
    /// anything in my hierarchy focused?"
    root_window: bool = false,
    /// True if ANY window has focus. Note: in a frame with no
    /// window clicks yet, focus may be on a previously-focused
    /// window from a prior frame - this flag reflects the
    /// persistent state, not "did focus change this frame."
    any_window: bool = false,
    /// Don't consider popup hierarchy. Same no-op caveat as
    /// `HoveredFlags.no_popup_hierarchy`.
    no_popup_hierarchy: bool = false,

    /// Convenience: walk to root AND include all children.
    /// Equivalent to imgui's `ImGuiFocusedFlags_RootAndChildWindows`.
    pub const root_and_child_windows: FocusedFlags = .{
        .root_window = true,
        .child_windows = true,
    };
};

// ============================================================================
// ItemFlags. Cross-widget behavior flags that
// can be pushed onto a stack via `pushItemFlag`/`popItemFlag`, or
// passed as `opts` to individual widgets that accept them.
// Imgui's `ImGuiItemFlags` is internal-flagged but exposed via
// BeginDisabled/EndDisabled and `PushItemFlag`/`PopItemFlag`. We
// model it the same way: a stack of `ItemFlags` lives on
// `UiContext.item_flags_stack`; widgets read the effective stack-
// merged flags via `currentItemFlags()`. Pre-existing
// `beginDisabled`/`endDisabled` is a special-case wrapper around
// `pushItemFlag(.{.disabled = true })` for ergonomics + back-compat.
// Field-by-field status:
// - `disabled` WIRED via the existing `disabled_count` path.
//                      Pushing flags-with-`.disabled = true` is
//                      equivalent to `beginDisabled(true)`.
// - `button_repeat` WIRED for button-family widgets that consult
//                      `currentItemFlags()` (button, arrowButton).
// - `allow_overlap` WIRED: tells `*HoveredImpl` to keep
//                      reporting the item as hovered even when a
//                      later item also passes its hit-test.
// - `no_tab_stop` PLUMBED (no-op). Wires up when keyboard nav
//                      lands (+).
// - `no_nav` PLUMBED. Same waiting room as no_tab_stop.
// - `no_nav_default_focus` PLUMBED.
// - `auto_close_popups` WIRED for menuItem + selectable
//                      controls whether the parent popup auto-closes
//                      on activation. Default ON in imgui; we use
//                      explicit bool so the default-on case is
//                      `auto_close_popups: bool = true` rather than
//                      "no flag = behavior X".

pub const ItemFlags = struct {
    /// Disable interactions for widgets submitted inside this scope.
    /// Visuals dim by `style.disabled_alpha`. Pre-existing
    /// `beginDisabled(true)` is equivalent to pushing this flag.
    disabled: bool = false,
    /// Disable keyboard tabbing onto items. **NOT YET WIRED**
    /// needs keyboard nav (+). Imgui:
    /// `ImGuiItemFlags_NoTabStop`.
    no_tab_stop: bool = false,
    /// Disable any focus mechanism on items. **NOT YET WIRED.**
    /// Imgui: `ImGuiItemFlags_NoNav`.
    no_nav: bool = false,
    /// Disable being a default-focus candidate. **NOT YET WIRED.**
    no_nav_default_focus: bool = false,
    /// Buttons behave as auto-repeat while held. Wired
    /// `button` checks `currentItemFlags().button_repeat`. Imgui:
    /// `ImGuiItemFlags_ButtonRepeat`.
    button_repeat: bool = false,
    /// MenuItem/Selectable auto-close their parent popup on
    /// activation. Default true to match imgui. Wired for
    /// menuItem. Imgui: `ImGuiItemFlags_AutoClosePopups`.
    auto_close_popups: bool = true,
    /// Allow this item to be hovered even when a later item
    /// overlaps it. WIRED - sets the item's
    /// `layout.last_item_allow_overlap` flag; the *next* item's
    /// hit-test honors it. Imgui: `ImGuiItemFlags_AllowOverlap`.
    allow_overlap: bool = false,
};

/// Merge two `ItemFlags` per imgui's stack semantics: each bool is
/// OR'd EXCEPT `auto_close_popups` which is AND'd (a parent disable
/// of auto-close propagates). Used internally when pushing onto
/// `item_flags_stack`.
pub fn mergeItemFlags(parent: ItemFlags, child: ItemFlags) ItemFlags {
    return .{
        .disabled = parent.disabled or child.disabled,
        .no_tab_stop = parent.no_tab_stop or child.no_tab_stop,
        .no_nav = parent.no_nav or child.no_nav,
        .no_nav_default_focus = parent.no_nav_default_focus or child.no_nav_default_focus,
        .button_repeat = parent.button_repeat or child.button_repeat,
        .auto_close_popups = parent.auto_close_popups and child.auto_close_popups,
        .allow_overlap = parent.allow_overlap or child.allow_overlap,
    };
}

// ============================================================================
// DragDropFlags.
// Replaces the old `DragDropSourceOpts { no_preview: bool }`. Same
// type covers source-side and target-side flags (imgui collapses
// them too into a single bitfield). Per Rule 14 a single
// struct-of-bools.
// Wired fields:
// - `source_no_preview` - was `DragDropSourceOpts.no_preview`,
//                            renamed to match imgui's
//                            `ImGuiDragDropFlags_SourceNoPreviewTooltip`.
// - `accept_no_draw_default_rect` - suppress the dashed
//                            highlight rect the target draws by
//                            default when a payload is over it.
// - `accept_before_delivery` - the target accepts mid-drag so the
//                            caller can peek-into the payload
//                            before the user releases. Already
//                            de-facto how zimr handles things
//                            (single-slot payload, last-frame-of-drag
//                            applies on release); this flag is a
//                            no-op in current impl but documents
//                            the future semantics.
// Plumbed/no-op fields:
// - `source_no_disable_hover` - needs hover-on-source-during-drag
//                            machinery (filed).
// - `source_no_hold_to_open_others` - hold-tree-to-open-it during
//                            drag isn't wired anyway.
// - `source_allow_null_id` - null-id sources (Text(), Image())
//                            need a per-position synthetic id;
//                            not wired.
// - `source_extern` - not relevant; we don't have external sources.
// - `payload_auto_expire` - payload-expiry-on-source-disappear
//                            (matches imgui 1.90.9+ rename of
//                            ImGuiDragDropFlags_SourceAutoExpirePayload).
// - `accept_no_preview_tooltip` - hide the source's tooltip while
//                            hovering this target; filed.
// - `accept_draw_as_hovered` - render the target item with its
//                            hover bg as if the user were hovering;
//                            useful for button-as-target. PARTIAL
//                            wire-up; only sets `last_item_hovered`
//                            on the target, doesn't yet override bg.

pub const DragDropFlags = struct {
    // ---- Source-side flags --------------------------------------
    /// Suppress the source's preview tooltip (would otherwise show
    /// a window following the cursor with the drag's payload
    /// representation). Wired - gates the tooltip rendering.
    /// Replaces old `DragDropSourceOpts.no_preview`. Imgui:
    /// `ImGuiDragDropFlags_SourceNoPreviewTooltip`.
    source_no_preview: bool = false,
    /// Keep the source item reporting hovered during the drag.
    /// **NOT YET WIRED.** Imgui:
    /// `ImGuiDragDropFlags_SourceNoDisableHover`.
    source_no_disable_hover: bool = false,
    /// Disable the "hold-over-a-tree-or-header-to-open-it" assist
    /// during drag. **NO-OP today** - hold-to-open isn't wired.
    source_no_hold_to_open_others: bool = false,
    /// Allow items without unique ids (Text, Image) to be drag
    /// sources. **NOT YET WIRED.** Imgui:
    /// `ImGuiDragDropFlags_SourceAllowNullID`.
    source_allow_null_id: bool = false,
    /// External-origin source (outside imgui). Not applicable in
    /// the zimr environment; **NO-OP**. Imgui:
    /// `ImGuiDragDropFlags_SourceExtern`.
    source_extern: bool = false,
    /// Auto-expire payload when the source stops being submitted.
    /// **NOT YET WIRED.** Imgui:
    /// `ImGuiDragDropFlags_PayloadAutoExpire`.
    payload_auto_expire: bool = false,

    // ---- Target-side flags --------------------------------------
    /// `acceptDragDropPayload` returns the payload BEFORE the user
    /// releases the mouse - caller can peek. **PARTIAL** - zimr's
    /// existing peek-before-release is implicit; this flag is
    /// documentation today. Imgui:
    /// `ImGuiDragDropFlags_AcceptBeforeDelivery`.
    accept_before_delivery: bool = false,
    /// Skip drawing the default dashed-highlight rect around the
    /// target while a payload is hovering. Wired - gates the
    /// `drawDragDropTargetHighlight` call. Imgui:
    /// `ImGuiDragDropFlags_AcceptNoDrawDefaultRect`.
    accept_no_draw_default_rect: bool = false,
    /// Hide the source's preview tooltip while hovering this
    /// target. **NOT YET WIRED.** Imgui:
    /// `ImGuiDragDropFlags_AcceptNoPreviewTooltip`.
    accept_no_preview_tooltip: bool = false,
    /// Render the target item with its hover-bg as if hovered.
    /// **PARTIAL** - `isItemHovered` returns true on the target
    /// when payload is over, but the bg-override isn't wired yet.
    /// Imgui: `ImGuiDragDropFlags_AcceptDrawAsHovered`.
    accept_draw_as_hovered: bool = false,

    /// Convenience: peek without redrawing. Imgui:
    /// `ImGuiDragDropFlags_AcceptPeekOnly`.
    pub const accept_peek_only: DragDropFlags = .{
        .accept_before_delivery = true,
        .accept_no_draw_default_rect = true,
    };
};

/// State saved on the `group_stack` when entering a `beginGroup`
/// scope. At `endGroup`, we compute the group's bounding rect from
/// `(saved_cursor_pos, cursor_max - saved_cursor_pos)` and write
/// it into `last_item_*` so subsequent `isItemHovered` queries see
/// the WHOLE group, not just the last widget in it.
/// Layout-wise the group is invisible - widgets inside it lay out
/// exactly as they would outside. endGroup just bookmarks the rect
/// and advances the parent cursor by the group's height.
pub const GroupState = struct {
    /// Cursor position when the group opened. Group's top-left.
    saved_cursor_pos: Vec2,
    /// `cursor_max` at the moment the group opened. endGroup
    /// computes the group rect from `cursor_max - cursor_max_at_start`.
    saved_cursor_max: Vec2,
    /// Saved row-height tracker - group widgets shouldn't inherit
    /// the row state from outside the group.
    saved_line_height: f32,
};

/// Per-popup persistent state stored in `UiContext.popup_open`.
/// Keyed by popup id. Presence in the map = "popup is open".
pub const PopupState = struct {
    /// Anchor point in screen pixels - popup's top-left when first
    /// opened. Captured at `openPopup` time (typically the mouse
    /// position).
    anchor: Vec2 = .{ 0, 0 },
    /// `frame_count` at the moment `openPopup` fired. Used to
    /// suppress the "click outside closes popup" check on the
    /// frame the popup just opened (the click that opened it would
    /// otherwise close it immediately).
    opened_at_frame: u64 = 0,
    /// True if this popup is a modal - renders a dim backdrop
    /// before the popup's chrome AND ignores click-outside-to-close
    /// (must be dismissed explicitly via `closeCurrentPopup` or by
    /// setting the `*open` bool to false on a `beginPopupModal`
    /// scope).
    is_modal: bool = false,
};

// ============================================================================
// TabBar. imgui-parity tab strip + per-tab state.
// Architecture:
// - `TabBarState` is the bar's persistent state (HashMap entry on
//   UiContext.tab_bar_state). Owns a list of `TabState` so the bar
//   remembers its tabs across frames - required for stable order +
//   reorder + GC.
// - `TabBarFrame` is per-frame scope state pushed onto
//   `UiContext.tab_bar_stack` between beginTabBar/endTabBar.
// - `TabBarFlags` / `TabItemFlags` are typed flag structs per Rule 14.
//   `TabFittingPolicy` is a mutually-exclusive enum (imgui's two
//   ImGuiTabBarFlags_FittingPolicy_* bits, collapsed).
// Per-frame flow:
//   beginTabBar: find/create state, mark `last_frame_active`, push frame.
//   beginTabItem: register/update TabState entry (or update existing).
//     Compute width. Render now if rendering pass. Return is_active.
//   endTabItem: pop id_stack if pushed.
//   endTabBar: GC stale tabs (last_frame_active < frame_count), render
//     separator, advance parent cursor, pop frame.
// Tab labels are stored inline in `TabState.label_buf` (32-byte cap)
// so the state survives across frames without depending on the
// caller's label-storage lifetime. Labels longer than 32 bytes
// truncate; rare in practice.

/// Mutually-exclusive policy for handling tabs that don't fit the
/// bar's width. imgui has two `ImGuiTabBarFlags_FittingPolicy_*`
/// bits; we collapse into an enum so the caller can't pick both.
pub const TabFittingPolicy = enum {
    /// Default: shrink tabs proportionally so they fit. Labels
    /// truncate when too narrow.
    resize_down,
    /// Keep tabs at their natural width; add scroll arrows when
    /// they overflow. **NOT YET IMPLEMENTED** as
    /// falls back to `resize_down` behavior.
    scroll,
};

/// Per-bar flags for `beginTabBar(str_id, opts: TabBarFlags)`.
/// Mirrors imgui's `ImGuiTabBarFlags` struct-of-bools.
///.
pub const TabBarFlags = struct {
    /// Let the user drag tabs to reorder them. Tabs marked
    /// `.no_reorder` stay in place; `.leading` / `.trailing` tabs
    /// reorder only within their pin section. **NOT YET WIRED**
    /// - filed for 3.6b follow-up turn. Imgui:
    /// `ImGuiTabBarFlags_Reorderable`.
    reorderable: bool = false,
    /// Auto-select new tabs as they appear (in addition to the
    /// always-on behavior of auto-selecting the very first tab on
    /// a fresh bar). Imgui: `ImGuiTabBarFlags_AutoSelectNewTabs`.
    auto_select_new_tabs: bool = false,
    /// Show a `...` button at the right edge that opens a popup
    /// listing all tabs. Useful when many tabs overflow.
    /// **NOT YET IMPLEMENTED.** Imgui:
    /// `ImGuiTabBarFlags_TabListPopupButton`.
    tab_list_popup_button: bool = false,
    /// Disable middle-click-to-close on tabs that have an
    /// `open_ptr`. Default false: middle-click closes.
    /// Imgui: `ImGuiTabBarFlags_NoCloseWithMiddleMouseButton`.
    no_close_with_middle_mouse_button: bool = false,
    /// Hide the left/right scroll arrows when overflow uses the
    /// scroll fitting policy. **NOT YET WIRED** - scroll policy
    /// itself isn't wired. Imgui:
    /// `ImGuiTabBarFlags_NoTabListScrollingButtons`.
    no_tab_list_scrolling_buttons: bool = false,
    /// Don't show the truncated-label tooltip on hover.
    /// **NOT YET WIRED** - needs hover-delay infra.
    no_tooltip: bool = false,
    /// Draw a 2px overline above the selected tab to emphasize it.
    /// Optional; matches imgui 1.91+ behavior. Off by default for
    /// the zimr theme's flatter look.
    draw_selected_overline: bool = false,
    /// How to handle the case where tabs don't fit. Default
    /// `.resize_down` - shrink tabs to fit. `.scroll` is **NOT
    /// YET WIRED** and falls back to `.resize_down`.
    fitting_policy: TabFittingPolicy = .resize_down,
};

/// Per-tab flags for `beginTabItem(label, open_ptr, opts: TabItemFlags)`.
/// Mirrors imgui's `ImGuiTabItemFlags`.
pub const TabItemFlags = struct {
    /// Show a `*` next to the label indicating unsaved changes.
    /// Wired: asterisk renders. Close-confirmation popup is the
    /// caller's responsibility (zimr doesn't pop one
    /// automatically; the caller can check `open_ptr.*` on click
    /// and show their own). Imgui:
    /// `ImGuiTabItemFlags_UnsavedDocument`.
    unsaved_document: bool = false,
    /// Force-select THIS tab on the frame the flag is set.
    /// One-shot - clear the flag next frame if you want repeated
    /// behavior. Imgui: `ImGuiTabItemFlags_SetSelected`.
    set_selected: bool = false,
    /// Disable middle-click-to-close on this specific tab,
    /// overriding the bar's setting.
    no_close_with_middle_mouse_button: bool = false,
    /// Don't push the tab's id onto `id_stack` while active. By
    /// default zimr pushes the tab id so widgets inside have
    /// per-tab ids. Set this if you've handled ID scoping
    /// manually. Imgui: `ImGuiTabItemFlags_NoPushId`.
    no_push_id: bool = false,
    /// Don't show truncated-label tooltip. **NOT YET WIRED.**
    no_tooltip: bool = false,
    /// Mark this tab as non-reorderable. Drag-reorder skips it.
    /// **NOT YET WIRED** - drag-reorder not yet implemented.
    no_reorder: bool = false,
    /// Pin this tab to the LEFT of the bar, before all
    /// reorderable tabs. Useful for hamburger / `+` buttons.
    /// Imgui: `ImGuiTabItemFlags_Leading`.
    leading: bool = false,
    /// Pin this tab to the RIGHT of the bar. Imgui:
    /// `ImGuiTabItemFlags_Trailing`.
    trailing: bool = false,
};

/// Inline label storage cap for `TabState`. 32 covers all
/// practical tab labels (file names, section names, "+"). Labels
/// longer than 32 truncate; the hashed `id` is the real identity,
/// so truncation only affects display.
pub const tab_label_cap: usize = 32;

/// Per-tab persistent state, lives on `TabBarState.tabs`.
pub const TabState = struct {
    /// Hashed id (label seed under the bar's id).
    id: Id,
    /// Inline label storage so the tab outlives the caller's
    /// label-string borrow. Required because tabs persist across
    /// frames but the caller's label might be a per-frame
    /// std.fmt.bufPrint result.
    label_buf: [tab_label_cap]u8 = undefined,
    label_len: usize = 0,
    /// Width recorded for the most recent `beginTabItem`. Used by
    /// the resize_down fitting policy.
    width: f32 = 0,
    /// `frame_count` of the most recent `beginTabItem`. Tabs
    /// stale by `endTabBar` are GC'd.
    last_frame_active: u64 = 0,
    /// Section pin (0 = leading, 1 = middle, 2 = trailing).
    /// Drives layout order within the bar.
    section: u8 = 1,
    /// Recorded `unsaved_document` flag this frame; drives the
    /// `*` decoration.
    unsaved: bool = false,
    /// Caller's `open_ptr`, cached so endTabBar can set it false
    /// after a close-click without having to re-look-up the
    /// caller's address. May be null.
    open_ptr_cache: ?*bool = null,
    /// Set to true by a close-X click or middle-click. Cleared
    /// at endTabBar after writing `open_ptr_cache.* = false`.
    want_close: bool = false,
};

/// Inline cap for `TabBarState.str_id_buf` and `parent_window_name_buf`.
/// 32 bytes covers typical tab-bar names like "mainbar", "settings_tabs",
/// "files#left_panel". Names longer than this are truncated for
/// persistence purposes only - the hashed Id (which is what drives
/// the live HashMap routing) hashes the full string regardless.
pub const tab_bar_name_cap: usize = 32;

/// Persistent per-tab-bar state. Lives in
/// `UiContext.tab_bar_state`, keyed by the bar's hashed `str_id`.
/// Survives across frames so selection + tab order stay stable.
pub const TabBarState = struct {
    /// Currently-active tab id. Zero = none. First-tab-of-fresh-bar
    /// auto-selects in `beginTabItem` if this stays zero.
    selected_id: Id = 0,
    /// Bar's bottom-y in screen pixels (set during endTabBar).
    bottom_y: f32 = 0,
    /// All tabs known to this bar, in insertion order initially
    /// (drag-reorder may permute when wired).
    tabs: ArrayList(TabState) = .empty,
    /// `frame_count` of the bar's most recent `beginTabBar`.
    /// Future use: bar GC on stale `UiContext.tab_bar_state` entries.
    last_frame_active: u64 = 0,

    // inline buffers identifying the bar by
    // (parent_window_name, str_id). Set once when openTabBar
    // allocates the state, then immutable for the bar's lifetime.
    // Used by `ui_persistence.serialize` to round-trip the bar's
    // selected tab across reloads - persistence needs a stable
    // human-readable identifier, not the hashed `Id`. Sized to
    // cover typical labels; truncation is silent but won't crash
    // (longer names still hash to the same Id, which is what
    // matters for routing).
    str_id_buf: [tab_bar_name_cap]u8 = undefined,
    str_id_len: usize = 0,
    parent_window_name_buf: [tab_bar_name_cap]u8 = undefined,
    parent_window_name_len: usize = 0,

    pub fn deinit(self: *TabBarState, gpa: Allocator) void {
        self.tabs.deinit(gpa);
    }

    /// Linear search by id. Tab counts are small (~5-20 in
    /// practice); a HashMap would be overkill and add indirection.
    pub fn findTab(self: *const TabBarState, id: Id) ?usize {
        for (self.tabs.items, 0..) |t, i| {
            if (t.id == id) {
                return i;
            }
        }
        return null;
    }

    /// Returns the bar's caller-given str_id (truncated to fit if
    /// the original was longer than `tab_bar_name_cap`). Used by
    /// persistence to identify the bar by name rather than by
    /// hashed Id. Empty until openTabBar populates the buffer.
    pub fn strId(self: *const TabBarState) []const u8 {
        return self.str_id_buf[0..self.str_id_len];
    }

    /// Returns the bar's parent window name at allocation time.
    /// See `strId` for the same caveats around truncation.
    pub fn parentWindowName(self: *const TabBarState) []const u8 {
        return self.parent_window_name_buf[0..self.parent_window_name_len];
    }
};

/// Per-frame transient state for the active tab bar. Pushed on
/// `tab_bar_stack` between beginTabBar/endTabBar. The persistent
/// fields live on `TabBarState`; this struct only carries this-frame
/// layout cursor + flags snapshot.
pub const TabBarFrame = struct {
    /// Bar's hashed id (matches the key into `tab_bar_state`).
    id: Id,
    /// Outer rect of the bar's row, screen pixels.
    rect: Rectangle,
    /// Flags as passed to `beginTabBar` this frame.
    flags: TabBarFlags,
    /// X cursors per section. Tabs render left-to-right within
    /// their section; leading section starts at rect.x, middle
    /// after leading, trailing right-anchored.
    leading_cursor_x: f32,
    middle_cursor_x: f32,
    trailing_cursor_x: f32, // grows LEFTWARDS from rect right edge
    /// True if the active tab id changed THIS frame due to a click.
    /// Used to suppress `auto_select_new_tabs` on click-frames.
    selection_changed_this_frame: bool,
    /// True if a tab pushed its id onto id_stack via the
    /// auto-push behavior (cleared by `no_push_id`). Tracked
    /// here so endTabItem knows whether to pop.
    pushed_tab_id_this_item: bool,
};

/// Drag-drop state machine. Lives single-slot on `UiContext`.
/// Phases:
/// - `.idle` - nothing happening; default.
/// - `.pending` - user clicked a draggable widget, mouse is held
///                 down, but hasn't moved past the drag threshold
///                 yet. Promotes to `.active` on first movement
///                 past `DRAG_THRESHOLD` pixels.
/// - `.active` - a drag is in flight. `source_widget_id` says
///                 which widget started it; `payload_*` carry the
///                 typed payload. When the user releases the
///                 mouse, the phase stays `.active` for the rest
///                 of THIS frame so targets can read the payload
///                 in `acceptDragDropPayload`; cleanup back to
///                 `.idle` happens at endFrame.
/// The payload is stored inline in `payload_buf` to keep the
/// drag-drop path heap-free. 256 bytes is enough for typical
/// reference types (struct pointers, ids, small POD structs);
/// anything larger should be passed by id/pointer.
pub const DragDropState = struct {
    pub const Phase = enum { idle, pending, active };
    pub const PAYLOAD_CAP: usize = 256;
    pub const TYPE_NAME_CAP: usize = 96;
    pub const DRAG_THRESHOLD: f32 = 4;

    phase: Phase = .idle,
    /// Widget that originated the drag (last_item_id at the time
    /// `beginDragDropSource` was called).
    source_widget_id: Id = 0,
    /// Where the mouse was when the drag began. Used to detect
    /// movement past the threshold for `.pending →.active`.
    drag_start_pos: Vec2 = .{ 0, 0 },
    /// Comptime type name from `@typeName(T)`, truncated to
    /// `TYPE_NAME_CAP`. Used by `acceptDragDropPayload` ()
    /// to type-match. Empty when no payload is set.
    type_name_buf: [TYPE_NAME_CAP]u8 = undefined,
    type_name_len: usize = 0,
    /// Raw payload bytes. Caller copies a `T` into here via
    /// `setDragDropPayload`.
    payload_buf: [PAYLOAD_CAP]u8 = undefined,
    payload_len: usize = 0,
    /// Widget id of the in-progress drop-target scope, when
    /// `beginDragDropTarget` returned true this frame. Reset to 0
    /// at every beginFrame; reset to 0 at `endDragDropTarget`.
    /// `acceptDragDropPayload` is a no-op when this is 0.
    target_widget_id: Id = 0,

    pub fn typeName(self: *const DragDropState) []const u8 {
        return self.type_name_buf[0..self.type_name_len];
    }
    pub fn payload(self: *const DragDropState) []const u8 {
        return self.payload_buf[0..self.payload_len];
    }
    pub fn clearPayload(self: *DragDropState) void {
        self.type_name_len = 0;
        self.payload_len = 0;
    }
};

/// Saved Style-field state for `pushStyle` / `popStyle`. Each push
/// records the byte offset + size of one Style field plus a copy
/// of its prior bytes; `popStyle` writes those bytes back. Works
/// for any POD field type (all current Style fields qualify:
/// Color, Vec2, f32, i32, ?*const Font). 32 bytes of backup is
/// plenty for any of them.
pub const StyleSnapshot = struct {
    /// Byte offset of the field inside `Style`.
    offset: usize,
    /// Size in bytes of the saved field.
    size: usize,
    /// Original bytes copied at push time. Sized to accommodate
    /// the widest current Style field (?*const Font is 16 bytes on
    /// 64-bit; Vec2 is 8; Color/f32/i32 are 4). 32 is the
    /// safety margin.
    backup: [32]u8 = undefined,
};

/// How a table column's width gets computed. Two modes per
/// decision Q7 - `NoResize` / `NoReorder` / `NoHide` flags from
/// imgui are deferred.
/// Per-column sizing. Set explicitly via `tableSetupColumn`'s
/// `sizing` opt; default null (inherit from the table's
/// `TableOpts.sizing` policy).
///
/// Mirrors imgui's per-column `ImGuiTableColumnFlags_WidthFixed`
/// and `ImGuiTableColumnFlags_WidthStretch` (imgui.h:2200+). zimr
/// folds `WidthAuto` into `.fixed` — a fixed column whose
/// `user_width` is zero behaves the way imgui's `WidthAuto` does:
/// the table sizing policy fills in the width from the column's
/// measured `width_auto_seen`.
pub const TableColumnSizing = enum {
    /// Column grows to fill remaining row width, sharing the
    /// available pixels with other stretch columns according to
    /// their effective weight (see `effectiveStretchWeight`).
    stretch,
    /// Column has an absolute pixel width. When `user_width` is
    /// non-zero, that value is used directly; when zero, the
    /// width is filled in by the table-level sizing policy from
    /// `width_auto_seen` (the previous frame's measured content).
    fixed,
};

/// Per-column sort direction. Imgui's convention: ascending is
/// "smallest first" (alphabetical A→Z, numeric low→high).
pub const TableSortDirection = enum { ascending, descending };

/// Per-column state inside an active table. Capped at
/// `max_table_columns` per the bounded-state convention.
pub const TableColumnState = struct {
    /// Display name passed to `tableSetupColumn`. Length-prefixed
    /// inline buffer so the slice survives past the caller's
    /// `update()` frame - names are read at `tableHeadersRow` time.
    name_buf: [64]u8 = undefined,
    name_len: usize = 0,
    /// Resolved per-column sizing policy. In contrast to the
    /// `?TableColumnSizing` on `TableColumnOpts` (which can be
    /// null = inherit-from-table), this is the concrete value
    /// after inheritance has been applied — never null at the
    /// point any layout code reads it. Default `.stretch` is
    /// only meaningful before `tableSetupColumnImpl` has run; in
    /// practice the inheritance fill in `computeTableColumnLayout`
    /// (or `tableSetupColumnImpl` itself) writes the resolved
    /// value.
    sizing: TableColumnSizing = .stretch,
    /// User-supplied width for `.fixed` columns. Zero means
    /// "no override" — the table's sizing policy decides the
    /// width from `width_auto_seen` (see `effectiveFixedWidth`).
    user_width: f32 = 0,
    /// User-supplied stretch weight. null = "no override" —
    /// the table's sizing policy decides the weight (see
    /// `effectiveStretchWeight`). Non-null means the caller
    /// explicitly set this column's weight, which always wins
    /// over the policy-derived value.
    user_weight: ?f32 = null,
    /// P8.4: maximum content width seen in any cell
    /// of this column during the CURRENT frame, measured in
    /// pixels INCLUDING left+right cell padding (one symmetric
    /// padding's worth on each side). Updated by
    /// `snapshotCellWidth` after each cell submits its content;
    /// persisted to `ctx.table_width_auto_cache` at endTable;
    /// re-loaded from that cache at the NEXT frame's beginTable.
    ///
    /// First-frame caveat: there is no previous-frame data on
    /// the very first frame a table is submitted, so
    /// `computeTableColumnLayout` falls back to
    /// `fallbackColumnWidth(style.font_size)` when this is zero.
    /// One frame of layout lag is intrinsic — zimr is
    /// single-pass and can't know a column's natural width
    /// before its cells render. Stable thereafter as long as
    /// content doesn't change frame-to-frame.
    width_auto_seen: f32 = 0,
    /// Whether sort is suppressed on this column.  Negated form
    /// of the old `sortable: bool = true`.  Default false — sort
    /// cycles normally.  From `TableColumnOpts.no_sort`.
    no_sort: bool = false,
    /// Block ascending direction in the sort cycle.  See
    /// `TableColumnOpts.no_sort_ascending`.
    no_sort_ascending: bool = false,
    /// Block descending direction in the sort cycle.  See
    /// `TableColumnOpts.no_sort_descending`.
    no_sort_descending: bool = false,
    /// Initial sort direction for first-frame seeding.  Consumed
    /// once at `tableSetupColumnImpl` time — the seed result
    /// lives in `ctx.table_sort_state[ts.id]` thereafter and
    /// reads of this field don't affect the live spec.  Kept on
    /// the column for inspection / debug only.  See
    /// `TableColumnOpts.default_sort`.
    default_sort: ?TableSortDirection = null,
    /// Suppress the header text on this column.  Mirrors imgui's
    /// `ImGuiTableColumnFlags_NoHeaderLabel`.  See
    /// `TableColumnOpts.no_header_label`.
    no_header_label: bool = false,
    /// Final computed width in pixels, set at `tableNextRow` based
    /// on outer_width and the sum of fixed/stretch demands.
    width: f32 = 0,
    /// Left edge x in screen pixels, set at `tableNextRow`.
    x: f32 = 0,

    /// Per-cell bg override for the cell at (current_row, this
    /// column). Set by `tableSetCellBgColor` after entering a
    /// column with `tableNextColumn`; consumed (painted to the
    /// splitter's bg channel) when the row finalizes — either at
    /// the NEXT `tableNextRow` or at `endTable`. Reset to null
    /// after painting so the next row's cells start fresh.
    /// P8.1: cell bg paints UNDER cell content because
    /// the splitter merges channel 0 before channel 1; the cell
    /// bg overlays the row bg because cell bgs are emitted AFTER
    /// the row bg in channel 0. Final z-order:
    ///   row_bg → cell_bg → cell_content.
    cell_bg_pending: ?Color = null,

    pub fn name(self: *const TableColumnState) []const u8 {
        return self.name_buf[0..self.name_len];
    }
};

/// One entry in the sort spec list - one of up to three active
/// sort columns.
pub const TableSortSpec = struct {
    /// Index into the table's `tableSetupColumn` order.
    column_index: u32,
    /// Direction this column sorts in.
    direction: TableSortDirection,
};

/// The full sort spec for an active table - up to N=3 columns
/// stacked in priority order (specs[0] is the primary key,
/// specs[1] the secondary tie-breaker, etc.). Per decision Q8.
pub const TableSortSpecs = struct {
    specs: [3]TableSortSpec = undefined,
    len: u8 = 0,

    /// Slice view of the active specs. Caller uses this in
    /// `std.mem.sort` cmp functions.
    pub fn items(self: *const TableSortSpecs) []const TableSortSpec {
        return self.specs[0..self.len];
    }
};

/// Maximum columns per table. Bounded to avoid heap allocation in
/// the hot loop; a tabular dashboard with 32 visible columns is
/// already pushing readability.
pub const max_table_columns: usize = 32;

/// Active-table state. Lives in `UiContext.active_table` between
/// `beginTable` and `endTable`. Single-slot: nested tables are
/// not supported in.
pub const TableState = struct {
    /// Stable id derived from the table's label + parent stack at
    /// `beginTable`. Used for child-state lookups (header click,
    /// sort spec persistence - those come in ).
    id: Id,
    /// Configured column count (from `beginTable`).
    n_columns: u32,
    /// Number of `tableSetupColumn` calls received so far. When
    /// less than `n_columns` at first row, defaults fill in.
    columns_set_up: u32,
    /// Per-column state. Only `[0..n_columns]` is meaningful.
    columns: [max_table_columns]TableColumnState,
    /// Current row's top y (screen pixels).
    row_y: f32,
    /// Current row's accumulated height (max of every cell's
    /// content height submitted so far).
    row_max_h: f32,
    /// Current column index within the row. -1 means "not yet
    /// entered any column this row" (between `tableNextRow` and
    /// the first `tableNextColumn`).
    cur_col: i32,
    /// 0-indexed row number; -1 before any `tableNextRow`.
    cur_row: i32,
    /// Cached options from `beginTable`.
    opts: TableOpts,
    /// Outer table rect in screen pixels, computed at `beginTable`.
    outer_rect: Rectangle,
    /// True once at least one column setup has been recorded, to
    /// short-circuit no-op default fills.
    has_setup: bool,
    /// Vertical scroll offset (pixels). Resolved at `beginTable`
    /// from the persistent `table_scroll_state` map; mutated by
    /// wheel input during data rows; clamped + written back at
    /// `endTable`. Zero means "scrolled to top."
    scroll_y: f32,
    /// Pixel y at which the first data row begins, in screen
    /// coordinates BEFORE applying scroll. Set by
    /// `tableHeadersRow` (or, when no header, by the first
    /// `tableNextRow`). Used at `endTable` to compute the total
    /// data height and clamp `scroll_y`.
    data_origin_y: f32,
    /// True after the data clip-rect has been pushed onto the
    /// draw list. Pushed by the first `tableNextRow`; popped at
    /// `endTable`. Only set when the table actually scrolls
    /// (i.e. `outer_height > 0`).
    clip_pushed: bool,
    /// Per-row background override for the CURRENT row. null
    /// means "use the auto-tint from `opts.row_bg` (if any)."
    /// Reset to null on every `tableNextRow`; set by
    /// `tableSetRowBgColor`.
    row_bg_override: ?Color = null,

    /// 2-channel splitter. Channel 0 receives the
    /// table's row backgrounds + cell borders; channel 1 receives
    /// cell content (widget submissions via `ctx.current_draw_list`).
    /// On `endTable`, the splitter is merged into the window's
    /// draw_list — channel 0's commands first, then channel 1's.
    /// Effect: cell backgrounds always paint UNDER cell content,
    /// regardless of the left-to-right interleave of bg / content
    /// submissions during row iteration. Pre-the bg was
    /// painted AFTER cells were submitted, so it overlapped content;
    /// the workaround was a translucent bg tint. Splitter makes
    /// fully-opaque bg colors render correctly.
    splitter: DrawListSplitter = .{},

    /// Saved value of `ctx.current_draw_list` at `beginTable`.
    /// `endTable` restores it after merging the splitter into the
    /// window's draw_list. The redirection during the table sends
    /// widget content submissions into the splitter's channel 1.
    saved_draw_list: ?*DrawList = null,
};

// ============================================================================
// P2.1: DebugLog ring
// ============================================================================
// Internal event ring buffer that captures the "why did the wrong
// thing get hovered/clicked" trail. Equivalent to imgui's
// `g.DebugLogBuf` (see imgui.cpp `DEBUG_LOG_EVENT_*` macros).
//

// Storage: `BoundedArray(DebugEvent, debug_log_cap)` on `UiContext`.
// When the buffer fills, the oldest event is dropped via
// `orderedRemove(0)` before the new event is appended. No
// allocation; fits inline on the context.
//

// Pushes are best-effort: format-arg truncation past `MAX_MSG`
// bytes is silent; the event still lands with what fit. The
// log never holds allocations — message is an inline byte
// buffer with a length suffix. Process-only state, NOT serialized
// to the persistence layer (debug data, not user data).
//

// Initial wired sites:
//   - openPopup → popup_opened
//   - closeCurrentPopup → popup_closed
//   - beginDragDropSource (when drag starts) → drag_started
//   - acceptDragDropPayloadImpl (on accept) → drop_accepted
//

// Future sites (onward): focus changes, item activations,
// dock requests queued, lint warnings, id collisions.

pub const debug_log_cap: usize = 256;
const debug_log_msg_max: usize = 128;

pub const DebugEventKind = enum {
    focus_changed,
    popup_opened,
    popup_closed,
    item_activated,
    drag_started,
    drop_accepted,
    dock_request_queued,
    id_collision,
    lint_warning,
};

pub const DebugEvent = struct {
    frame: u32,
    kind: DebugEventKind,
    message: [debug_log_msg_max]u8,
    message_len: u8,

    /// Borrow the populated message bytes.
    pub fn messageSlice(self: *const DebugEvent) []const u8 {
        return self.message[0..self.message_len];
    }
};

/// Append a debug event to the ring. Format-args are written into
/// the inline buffer up to `debug_log_msg_max` bytes; longer messages
/// truncate silently. When the ring is full, the oldest event is
/// dropped via `orderedRemove(0)` so the latest cap-many events are
/// always retained.
///
/// Cost when not at cap: one bufPrint + one struct copy. Cost at
/// cap: same plus an O(N) shift inside `orderedRemove(0)`. Both
/// well below the per-frame budget for realistic event rates.
///
/// Errors during format are swallowed: the event still lands with
/// whatever bytes fit before the format ran out of room.
pub fn debugLogPush(
    ctx: *UiContext,
    kind: DebugEventKind,
    comptime fmt: []const u8,
    args: anytype,
) void {
    var ev: DebugEvent = .{
        .frame = @intCast(ctx.frame_count),
        .kind = kind,
        .message = undefined,
        .message_len = 0,
    };
    if (bufPrint(&ev.message, fmt, args)) |written| {
        ev.message_len = @intCast(written.len);
    } else |_| {
        // Truncated. bufPrint may have left a prefix in the buffer
        // even on NoSpaceLeft; record the full buffer as "what got
        // attempted" and move on.
        ev.message_len = debug_log_msg_max;
    }

    if (ctx.debug_log.len == ctx.debug_log.capacity()) {
        _ = ctx.debug_log.orderedRemove(0);
    }
    // BoundedArray.append returns error.Overflow only when at
    // capacity; we just freed a slot, so this can't fail.
    ctx.debug_log.append(ev) catch assertUnreachable(@src(), "OOM", .{});
}

/// Borrow the populated events as a slice in oldest-to-newest order.
/// Returned slice is valid until the next `debugLogPush`.
pub fn debugLogSlice(ctx: *const UiContext) []const DebugEvent {
    return ctx.debug_log.constSlice();
}

// ============================================================================
// P2.2: Frame metrics
// ============================================================================
// `UiContext.metrics: Metrics` — a struct of per-frame counters
// populated by `beginFrame` / `endFrame` and a few collection
// helpers. Equivalent to imgui's `ShowMetricsWindow` data block
// (`imgui_demo.cpp` "Dear ImGui Metrics" panel).
//

// What's tracked:
//   - `frame_count: u32` — wraps once every 828 days
//                                       at 60fps; fine.
//   - `frame_time_ms: f32` — most recent frame's input
//                                       delta_time × 1000.
//   - `frame_time_ms_history: [120]f32` — ring of last 120 samples,
//                                          newest at `history_head`.
//                                          Designed for plotLines.
//   - `history_head: u8` — write index for the next
//                                       sample (0..120 then wraps).
//   - `windows_active: u32` — windows submitted this frame
//                                       (frame_windows.len).
//   - `windows_hovered: u32` — 0 or 1, reflects
//                                       `hovered_window_id != 0`.
//   - `cmd_count: u32` — sum of `draw_list.cmds.len`
//                                       across every drawlist rendered
//                                       this frame. Cheap proxy for
//                                       "how busy was the UI".
//   - `drawlist_count: u32` — number of drawlists rendered
//                                       (background + per-window +
//                                       popups + foreground).
//   - `last_active_widget_id: Id` — sticks (no reset) so the
//                                       user can see WHAT widget got
//                                       clicked even after it goes
//                                       inactive.
//

// What's NOT tracked (deliberately omitted):
//   - Vertex / index counts. zimr submits immediate-mode through
//     rlgl batches; counting vertices means instrumenting rlgl,
//     which is out of scope for a UI-side metrics struct. cmd_count
//     is the practical substitute.
//

// Why no allocator: the metrics struct is plain data (16 bytes for
// scalar fields + 480 bytes for history) and lives inline on the
// context. Reset cycle: per-frame fields zeroed in `beginFrame`,
// counters incremented through the frame, finalized in `endFrame`.
// `history_head` and `frame_count` advance once per frame; the
// rolling history is preserved across resets.

pub const metrics_history_len: usize = 120;

pub const Metrics = struct {
    frame_count: u32 = 0,
    frame_time_ms: f32 = 0,
    frame_time_ms_history: [metrics_history_len]f32 = @splat(0),
    history_head: u8 = 0,
    windows_active: u32 = 0,
    windows_hovered: u32 = 0,
    cmd_count: u32 = 0,
    drawlist_count: u32 = 0,
    last_active_widget_id: Id = 0,
};

/// Sample collector: pushes the per-frame counters that aren't
/// natively tracked elsewhere. Called near the top of `endFrame`
/// after all submissions have closed but before the draw lists
/// render. Reads from `ctx` and writes into `ctx.metrics`.
fn metricsCollectAtEndFrame(ctx: *UiContext) void {
    const m: *Metrics = &ctx.metrics;
    m.frame_count = @intCast(ctx.frame_count);
    m.frame_time_ms = ctx.input.delta_time * 1000.0;
    m.windows_active = @intCast(ctx.frame_windows.len);
    m.windows_hovered = if (ctx.hovered_window_id != 0) 1 else 0;
    if (ctx.active_id != 0) {
        m.last_active_widget_id = ctx.active_id;
    }
    // Ring the frame-time sample. Head advances mod LEN; oldest
    // sample at `(head + 1) % LEN` after the write, newest at
    // `head` AFTER the post-increment below.
    m.frame_time_ms_history[m.history_head] = m.frame_time_ms;
    m.history_head = @intCast((@as(usize, m.history_head) + 1) % metrics_history_len);
}

/// Pre-render counter reset: zeroed before the per-frame replay
/// walks each drawlist and accumulates `cmd_count` / `drawlist_count`.
fn metricsResetRenderCounters(ctx: *UiContext) void {
    ctx.metrics.cmd_count = 0;
    ctx.metrics.drawlist_count = 0;
}

/// Accumulate one drawlist's cmd count. Called for every
/// `DrawList.render` site in `endFrame` (background, per-window,
/// per-popup, foreground, tooltip-block, drag-preview).
fn metricsAccumulateDrawList(ctx: *UiContext, dl: *const DrawList) void {
    ctx.metrics.cmd_count += @intCast(dl.cmds.items.len);
    ctx.metrics.drawlist_count += 1;
}

/// One bar's persisted selection. Identified by the bar's
/// caller-given `str_id`, not its hashed Id, so the storage
/// survives rebuilds. The selected tab is stored by `label`,
/// hashed at restore time under the bar's Id (which itself is
/// the hash of `str_id` under the window's id stack).
pub const PersistedTabBar = struct {
    str_id: []const u8,
    /// Empty string means "no selection persisted" - distinct
    /// from "this bar has no entry at all", which is represented
    /// by the bar's absence from the `tab_bars` array.
    selected_tab_label: []const u8 = "",
};

/// A single window's persistable state. Field set kept minimal
/// today; will grow with `collapsed` (when the field lands on
/// `Window`), `dock_node_id`, and `column_widths`
/// (when tables persist).
/// The window is keyed by `name` - the user-facing title - not by
/// the hashed Id. Hash IDs are stable within a build but the
/// human-meaningful identity is the name, so a refactor that
/// renames a window's title is a clean break in persistence
/// (just as it is in imgui).
pub const PersistedWindow = struct {
    name: []const u8,
    pos: [2]f32,
    size: [2]f32,
    /// Vertical scroll offset. Defaulted so older payloads (or
    /// ones written by demos that don't scroll) parse cleanly.
    scroll_y: f32 = 0,
    /// Horizontal scroll offset. Defaulted so older payloads
    /// without it parse cleanly. Only restored when the live
    /// window has `WindowFlags.horizontal_scrollbar` set —
    /// otherwise scroll_x is force-zeroed each frame by the
    /// X-axis bookkeeping path.
    scroll_x: f32 = 0,
    /// True if the user has manually resized OR explicitly placed
    /// the window - disables auto-fit on the next frame. Defaulted
    /// to false so new-window submissions auto-fit until the user
    /// interacts.
    user_resized: bool = false,
    /// tab-bar selection per bar contained
    /// in this window. Identified by the bar's caller-given
    /// `str_id` so a rename is a clean break (the user submits
    /// `beginTabBar("new_id")`, doesn't find a persisted entry,
    /// falls back to first-tab-auto-select). Defaulted empty
    /// - older payloads parse cleanly.
    tab_bars: []const PersistedTabBar = &.{},
};

/// Pending dock operation. Enqueued by drag-drop interaction;
/// applied by `processRequests` at a well-defined point in the
/// frame so mutations don't interleave with reads during widget
/// submission.
pub const DockRequest = union(enum) {
    /// Add `source_window` as a tab into `target_node` (which
    /// must be a LEAF; the operation is a no-op if it's a SPLIT).
    dock_as_tab: struct { target_node: Id, source_window: Id },

    /// Split `target_node` and place `source_window` in the new
    /// side determined by `dir`. Target must be a LEAF; after the
    /// operation, target's original windows occupy ONE child and
    /// `source_window` occupies the other. No-op if `dir ==.center`.
    dock_as_split: struct { target_node: Id, source_window: Id, dir: Dir },

    /// Remove `source_window` from whatever leaf it's currently in.
    /// If that leaf becomes empty AND has a parent SPLIT, the
    /// parent collapses (the sibling takes the parent's slot).
    /// No-op if the window isn't docked anywhere.
    undock: struct { source_window: Id },

    /// Split a dockspace root (or any leaf) into two children.
    /// Returns the new child IDs via callback (in 5.5b's
    /// `dockBuilderSplitNode` impl). Used by the dockBuilder
    /// API to set up default layouts.
    split: struct { target_node: Id, dir: Dir, ratio: f32 },
};

/// Tagged role for `DockContext.createNode`. Distinct from
/// `DockNode` itself because at creation we only want to specify
/// "leaf or split", not the full node shape.
pub const NodeRole = union(enum) {
    leaf: void,
    split: DockNode.SplitData,
};

/// Pool of nodes + bookkeeping for the docking system. One per
/// UiContext.
pub const DockContext = struct {
    /// All allocated nodes, keyed by `Id`. Values are
    /// heap-allocated so the HashMap can grow without
    /// invalidating outstanding pointers (callers stash `*DockNode`
    /// across frame boundaries).
    nodes: std.AutoHashMapUnmanaged(Id, *DockNode) = .{},

    /// IDs of dockspace roots submitted this frame. Reset each
    /// frame by `beginFrame`; populated by `dockSpace` calls.
    /// Used by drag-drop hit-testing to know which dockspaces are
    /// candidate targets.
    dockspaces_this_frame: ArrayList(Id) = .empty,

    /// Queued operations waiting for `processRequests`. FIFO
    /// requests apply in submission order so a sequence like
    /// "undock A, dock A into B" produces the expected outcome.
    pending_requests: ArrayList(DockRequest) = .empty,

    /// The window currently being dragged for a dock operation,
    /// if any. Drag-drop sets this when a window's title bar
    /// drag exceeds the dock-detach threshold. Used by 5.5e for
    /// rendering the dock-target overlay.
    dragging_window: ?Id = null,

    /// Monotonic ID counter for new nodes. Bumped by
    /// `createNode`. Stable across frames - node IDs persist as
    /// long as the DockContext lives.
    next_node_id: Id = 1,

    pub fn deinit(self: *DockContext, gpa: Allocator) void {
        var it: std.AutoHashMapUnmanaged(Id, *DockNode).Iterator = self.nodes.iterator();
        while (it.next()) |entry| {
            const node: *DockNode = entry.value_ptr.*;
            if (node.leaf) |*leaf| {
                leaf.deinit(gpa);
            }
            gpa.destroy(node);
        }
        self.nodes.deinit(gpa);
        self.dockspaces_this_frame.deinit(gpa);
        self.pending_requests.deinit(gpa);
    }

    /// Resolve `id` to a node pointer. Null when the id doesn't
    /// exist in the pool - caller should always handle this since
    /// IDs may dangle if a node was removed between submission
    /// frames.
    pub fn lookup(self: *const DockContext, id: Id) ?*DockNode {
        return self.nodes.get(id);
    }

    /// Allocate a fresh node with the given role. `role` is
    /// either `.{.leaf =.{} }` (empty leaf) or
    /// `.{.split =.{...} }` (split with two existing child IDs).
    /// Returns the new node's ID.
    pub fn createNode(
        self: *DockContext,
        gpa: Allocator,
        parent_id: ?Id,
        role: NodeRole,
    ) Allocator.Error!Id {
        const id: Id = self.next_node_id;
        self.next_node_id += 1;
        const node = try gpa.create(DockNode);
        errdefer gpa.destroy(node);
        node.* = .{
            .id = id,
            .parent_id = parent_id,
        };
        switch (role) {
            .leaf => node.leaf = .{},
            .split => |s| node.split = s,
        }
        try self.nodes.put(gpa, id, node);
        return id;
    }

    /// Convenience: allocate a fresh empty leaf. Used by
    /// `dockSpace` for the root of a new dockspace.
    pub fn createLeaf(
        self: *DockContext,
        gpa: Allocator,
        parent_id: ?Id,
    ) Allocator.Error!Id {
        return self.createNode(gpa, parent_id, .{ .leaf = {} });
    }

    /// Find the leaf containing `window_id`, if any. Linear scan
    /// over all leaves - fine for the expected node counts (low
    /// dozens at most).
    pub fn findLeafFor(self: *const DockContext, window_id: Id) ?*DockNode {
        var it: std.AutoHashMapUnmanaged(Id, *DockNode).Iterator = self.nodes.iterator();
        while (it.next()) |entry| {
            const node: *DockNode = entry.value_ptr.*;
            if (node.leaf) |*leaf| {
                if (leaf.indexOf(window_id) != null) {
                    return node;
                }
            }
        }
        return null;
    }

    /// Free a node's memory (leaf list + the node itself). Used by
    /// `removeNode` and tree collapse paths. Does NOT update any
    /// parent's child_ids - callers must do that first or the tree
    /// becomes inconsistent.
    fn freeNode(
        self: *DockContext,
        gpa: Allocator,
        node: *DockNode,
    ) void {
        if (node.leaf) |*leaf| {
            leaf.deinit(gpa);
        }
        _ = self.nodes.remove(node.id);
        gpa.destroy(node);
    }
};

/// one dock-tree node's persistable
/// state. Flat representation (no tagged union) so.zon
/// round-tripping is straightforward - `is_split` discriminates
/// the role; the per-role fields are zero/empty for the other.
/// Keyed by `id` - the same u32 the runtime uses for
/// `DockNode.id`. Dockspace ROOT ids are derived by
/// `widgetId(window, str_id)` and stable across runs (assuming
/// the user doesn't rename their dockspace). Split/leaf node
/// ids are auto-allocated sequentially; we restore them
/// verbatim and bump `DockContext.next_node_id` past the max
/// observed id on load.
/// Restore failure (id collisions with already-built tree,
/// dangling child_ids, etc.) falls back to "skip this node and
/// log a warning." Persistence is a hint, never a hard
/// dependency.
pub const PersistedDockNode = struct {
    id: u32,
    /// 0 = no parent (this is a root). Roots are identified
    /// by `flags.is_dockspace` being set as well - bundling
    /// both keeps the schema explicit.
    parent_id: u32 = 0,
    /// `DockNodeFlags` reinterpreted as u16 via `@bitCast`.
    /// Survives schema changes that ADD flag bits (new bits
    /// default to 0); breaks if existing bits are renumbered
    /// (don't do that without a current_version bump).
    flags: u16 = 0,

    // ---- SPLIT role fields (valid when is_split == true)
    is_split: bool = false,
    /// 0 = horizontal, 1 = vertical. Matches `SplitAxis` enum
    /// values; we don't store the enum directly because.zon
    /// would emit the case name as a string and we want
    /// numeric stability.
    split_axis: u8 = 0,
    split_ratio: f32 = 0.5,
    split_child_a: u32 = 0,
    split_child_b: u32 = 0,
    /// `size_ref` is `[2]?f32` at runtime. Use the sentinel
    /// `-1` (negative pixel sizes are invalid anyway) to
    /// encode `null` in the.zon stream.
    split_size_ref_a: f32 = -1,
    split_size_ref_b: f32 = -1,

    // ---- LEAF role fields (valid when is_split == false)
    /// Names of the windows docked into this leaf, in tab
    /// order. Stored by NAME, not by hashed id - names are
    /// human-meaningful and survive rebuilds; ids may not.
    leaf_window_names: []const []const u8 = &.{},
    /// Name of the currently-selected tab. Empty string =
    /// "no selection yet, pick the first one on restore."
    leaf_selected_window_name: []const u8 = "",
};

/// State carried between `beginCombo` and `endCombo` while a combo's
/// dropdown is open. Lives in `UiContext.combo_scope` for the
/// duration of the open-and-submitting phase.
pub const ComboScope = struct {
    /// The combo's widget id - used to verify endCombo pairs.
    id: Id,
    /// Top-left of the dropdown rect (in canvas coords).
    dropdown_origin: Vec2,
    /// Dropdown width - equals the closed-row width.
    dropdown_width: f32,
    /// Saved current_draw_list (the host window's) so endCombo can
    /// restore it after redirecting to foreground_dl.
    saved_dl: ?*DrawList,
    /// Saved owning window so its cursor doesn't get bumped by
    /// widgets submitted into the combo dropdown.
    saved_window: ?*Window,
    /// Inside-the-popup cursor - advanced by every selectable() or
    /// custom widget submitted between begin/end. endCombo uses
    /// the final value to size the dropdown panel.
    cursor_y: f32,
};

/// Per-scope persistent state, survives across frames. Keyed by
/// the scope's window-id-stack-top in `UiContext.ms_storage`. Imgui:
/// `ImGuiMultiSelectState` (`imgui_internal.h`).
pub const MultiSelectState = struct {
    /// The anchor item - see `MultiSelectIO.range_src_item`.
    range_src_item: ?u64 = null,
    /// Selected-state of the anchor. Imgui uses `-1` for "unknown";
    /// we use a separate optional. When the anchor moves
    /// (`range_src_item` changes), this updates to match.
    range_selected: ?bool = null,
    /// Last focused item (for deletion-aware focus restore).
    /// Imgui: `NavIdItem`.
    nav_id_item: ?u64 = null,
    /// Selected-state of `nav_id_item`. Imgui: `NavIdSelected`.
    nav_id_selected: ?bool = null,
    /// `frame_count` from the most recent `beginMultiSelect`. Used
    /// for GC of stale scope state in `ms_storage`.
    last_frame_active: u64 = 0,
    /// `selection_size` passed to the most recent `beginMultiSelect`.
    /// Used by box-select for the "first-selected-item" path.
    /// Imgui: `LastSelectionSize`.
    last_selection_size: u32 = 0,
};

/// Free every entry in `ctx.pending_persistence` and
/// `ctx.pending_tab_bar_selections`. Called from `UiContext.deinit`.
/// After this call, the maps are empty but their backing allocations
/// are left intact for the caller to release via their `deinit(gpa)`.
pub fn clearPending(ctx: *UiContext) void {
    var it: std.StringHashMapUnmanaged(PersistedWindow).Iterator = ctx.pending_persistence.iterator();
    while (it.next()) |entry| {
        ctx.gpa.free(@constCast(entry.key_ptr.*));
    }
    ctx.pending_persistence.clearRetainingCapacity();

    // tab-bar selection staging gets the
    // same treatment. Both key and value are owned by gpa.
    var tb_it: std.StringHashMapUnmanaged([]const u8).Iterator = ctx.pending_tab_bar_selections.iterator();
    while (tb_it.next()) |entry| {
        ctx.gpa.free(@constCast(entry.key_ptr.*));
        ctx.gpa.free(@constCast(entry.value_ptr.*));
    }
    ctx.pending_tab_bar_selections.clearRetainingCapacity();
}

/// release every allocation owned by
/// `ctx.pending_dock_tree` and reset it to empty. Called from
/// `UiContext.deinit`, from `apply()` when re-staging, and from
/// `tryRestoreDockTree` after a successful restore.
pub fn freePendingDockTree(gpa: Allocator, ctx: *UiContext) void {
    for (ctx.pending_dock_tree) |pn| {
        for (pn.leaf_window_names) |n| {
            gpa.free(@constCast(n));
        }
        if (pn.leaf_window_names.len > 0) {
            gpa.free(@constCast(pn.leaf_window_names));
        }
        if (pn.leaf_selected_window_name.len > 0) {
            gpa.free(@constCast(pn.leaf_selected_window_name));
        }
    }
    if (ctx.pending_dock_tree.len > 0) {
        gpa.free(ctx.pending_dock_tree);
    }
    ctx.pending_dock_tree = &.{};
}

fn advanceNav(ctx: *UiContext) void {
    const items: []Id = ctx.frame_nav_items.items[0..ctx.frame_nav_items.len];
    if (items.len == 0) {
        return;
    }
    // Find current nav_id's position; -1 if not in the list.
    var current_idx: i32 = -1;
    for (items, 0..) |item, i| {
        if (item == ctx.nav_id) {
            current_idx = @intCast(i);
            break;
        }
    }
    const items_len_i32: i32 = @intCast(items.len);
    const stepping_back: bool = snapshotShiftDown(&ctx.input);

    if (current_idx < 0) {
        // No current focus - Tab focuses first, Shift+Tab focuses last.
        ctx.nav_id = if (stepping_back) items[items.len - 1] else items[0];
        return;
    }

    // Wrap-around step. We use rem-then-add idiom because Zig's `%`
    // on i32 keeps sign and we want a positive index.
    const step: i32 = if (stepping_back) -1 else 1;
    const raw_next: i32 = current_idx + step;
    const wrapped: i32 = @mod(raw_next, items_len_i32);
    ctx.nav_id = items[@intCast(wrapped)];
}

///.iv: hit-test the mouse against every leaf's drop
/// zones across every dockspace submitted this frame. Returns
/// the FIRST hit found (depth-first, dockspaces in submission
/// order, leaves in tree order). Null when no zone has a
/// non-zero score for `mp`. Called from the title-bar
/// drag-release branch.
/// Sync the window-side dock link from the tree. `processRequests` (dock module)
/// only updates `leaf.window_ids`; it can't touch Window records. This walks every
/// dock node and sets `window.dock_node_id = leaf.id` for each window in each leaf,
/// so runtime drag-to-dock (which goes through processRequests) actually makes the
/// window render docked. Idempotent — the builder/persistence paths already set
/// dock_node_id; re-setting it here is harmless. Undock paths clear dock_node_id,
/// and a window no longer in any leaf is simply not touched (stays floating).
fn syncDockedWindowIds(ctx: *UiContext) void {
    var it: @TypeOf(ctx.dock.nodes.valueIterator()) = ctx.dock.nodes.valueIterator();
    while (it.next()) |node_ptr| {
        const node: *DockNode = node_ptr.*;
        const leaf: DockNode.LeafData = node.leaf orelse continue;
        for (leaf.window_ids.items) |wid| {
            if (ctx.windows.get(wid)) |w| {
                w.dock_node_id = node.id;
            }
        }
    }
}

fn windowIsFloating(w: *Window) bool {
    return w.dock_node_id == null and !w.hosts_dockspace;
}

/// Deferred-render callback queued by `UiContext.endFrame` and
/// fired by `endDrawing`.  Replays every draw list this frame
/// submitted, in the layering order the prior inline-render code
/// used: background → per-window → popups → foreground → tooltip
/// block → drag preview.  Reads the live GlState/Window/shapes/
/// fonts from fields on the UiContext (stamped at `beginFrame`).
/// If any of those is null we silently no-op — the only way that
/// happens is the test path (`beginFrameRaw`), which doesn't run
/// the full lifecycle.
/// Replay this frame's UI draw lists IMMEDIATELY to `gl` (no deferred queue).
/// The GL backend defers via gl.pending_renders (off the framebuffer); the
/// WebGPU backend renders in a single pass, so it calls this directly after the
/// widget calls and before endDrawing. `window`/`shapes_state`/`font_cache` are
/// passed explicitly (beginFrameRaw doesn't stamp frame_window). Mirrors
/// uiContextDeferredRender's replay order (background, windows, popups,
/// foreground, tooltip, drag).
/// Reorder frame_windows so the most-recently-focused FLOATING window renders
/// last (on top). Docked windows and dockspace hosts keep last_focus_frame=0, so
/// they sort first (behind) in submit order; only free-floating windows reorder.
fn bringFocusedFloatingToFront(ctx: *UiContext) void {
    if (ctx.focused_window_id != 0) {
        if (ctx.windows.get(ctx.focused_window_id)) |fw| {
            if (fw.dock_node_id == null and !fw.hosts_dockspace) {
                fw.last_focus_frame = ctx.frame_count;
            }
        }
    }
    const Lt = struct {
        fn lt(_: void, a: *Window, b: *Window) bool {
            const af: bool = windowIsFloating(a);
            const bf: bool = windowIsFloating(b);
            // All docked windows + dockspace hosts sort BEFORE (behind) all
            // floating windows; within a class, by focus recency.
            if (af != bf) {
                return bf;
            }
            return a.last_focus_frame < b.last_focus_frame;
        }
    };
    std.sort.insertion(*Window, ctx.frame_windows.items[0..ctx.frame_windows.len], {}, Lt.lt);
}

fn measureTextS(ctx: *const UiContext, s: []const u8) Vec2 {
    const line_h: f32 = ctx.style.font_size;
    if (s.len == 0) {
        return .{ 0, line_h };
    }
    if (ctx.style.font) |font| {
        const m: Vec2 = text2d.measureWithFont(
            ctx.style.line_spacing,
            font.*,
            s,
            ctx.style.font_size,
            ctx.style.font_spacing,
        );
        // measureEx returns f32 width and height; height = font_size in
        // single-line case, which we want.
        return m;
    }
    // Default-font path - read the live frame font_cache stashed in
    // UiContext at beginFrame. Stale outside begin/endFrame; widgets
    // can only be called between them.
    if (ctx.frame_font_cache) |fc| {
        const w: i32 = text2d.measure(fc, ctx.style.line_spacing, s, @trunc(ctx.style.font_size));
        return .{ @floatFromInt(w), line_h };
    }
    // No frame font_cache (test path or pre-beginFrame). Width
    // is unknowable without metrics; report zero.
    return .{ 0, line_h };
}

/// Filled axis-aligned rectangle. Used by everything (window
/// backgrounds, buttons, frame bgs, separators).
/// Filled rectangle. Routes through the active draw list unless
/// the UI is in eager mode (inside a `pushRenderTexture` scope), in
/// which case it emits straight to rlgl through `shapes.drawRectangleRec`.
/// Either way, one source of truth: rectangles always end up at
/// `shapes.drawRectangleRec`.
fn drawRectFilled(
    ctx: *UiContext,
    r: Rectangle,
    col: ColorU32,
) void {
    const eff: ColorU32 = multiplyAlpha(col, ctx.alpha_mul);
    if (ctx.eager_mode or ctx.current_draw_list == null) {
        const gl: *Gl = ctx.frame_gl orelse return;
        const shapes_state: *const shapes2d.ShapesTextureState = ctx.frame_shapes_state orelse return;
        shapes2d.drawRectangleRec(gl, shapes_state, r, Color.fromWire(eff));
        return;
    }
    ctx.current_draw_list.?.addRectFilled(ctx.frame_arena.allocator(), r, eff);
}

/// Hollow rectangle outline (1px thick). Recorded as a single
/// `rect_outline` command - the four-strip emission happens at
/// replay (so a snapshot of the draw list shows ONE command per
/// outline, not four).
fn drawRect(
    ctx: *UiContext,
    r: Rectangle,
    col: ColorU32,
) void {
    const eff: ColorU32 = multiplyAlpha(col, ctx.alpha_mul);
    if (ctx.eager_mode or ctx.current_draw_list == null) {
        // Mirror the replay path - four 1px strips.
        const c: Color = Color.fromWire(eff);
        const gl: *Gl = ctx.frame_gl orelse return;
        const shapes_state: *const shapes2d.ShapesTextureState = ctx.frame_shapes_state orelse return;
        shapes2d.drawRectangleRec(gl, shapes_state, .{ .x = r.x, .y = r.y, .width = r.width, .height = 1 }, c);
        shapes2d.drawRectangleRec(
            gl,
            shapes_state,
            .{ .x = r.x, .y = r.y + r.height - 1, .width = r.width, .height = 1 },
            c,
        );
        shapes2d.drawRectangleRec(gl, shapes_state, .{ .x = r.x, .y = r.y, .width = 1, .height = r.height }, c);
        shapes2d.drawRectangleRec(
            gl,
            shapes_state,
            .{ .x = r.x + r.width - 1, .y = r.y, .width = 1, .height = r.height },
            c,
        );
        return;
    }
    ctx.current_draw_list.?.addRectOutline(ctx.frame_arena.allocator(), r, eff);
}

fn drawTextAtS(
    ctx: *UiContext,
    pos: Vec2,
    s: []const u8,
    col: ColorU32,
) void {
    if (s.len == 0) {
        return;
    }
    const eff: ColorU32 = multiplyAlpha(col, ctx.alpha_mul);
    if (ctx.eager_mode or ctx.current_draw_list == null) {
        // Eager path - read the live frame substates stashed in
        // UiContext at beginFrame. Stale outside begin/endFrame;
        // widgets can only be called between them.
        const c: Color = Color.fromWire(eff);
        const gl: *Gl = ctx.frame_gl orelse return;
        if (ctx.style.font) |font| {
            text2d.drawWithFont(
                gl,
                ctx.style.line_spacing,
                font.*,
                s,
                pos,
                ctx.style.font_size,
                ctx.style.font_spacing,
                c,
            );
        } else {
            const fc: *const text2d.FontCache = ctx.frame_font_cache orelse return;
            text2d.draw(
                gl,
                fc,
                ctx.style.line_spacing,
                s,
                @trunc(pos[0]),
                @trunc(pos[1]),
                @trunc(ctx.style.font_size),
                c,
            );
        }
        return;
    }
    // Deferred - record. Strings are duplicated into the draw list's
    // arena so they survive past update()'s return.
    ctx.current_draw_list.?.addText(
        ctx.frame_arena.allocator(),
        ctx.style.font,
        s,
        pos,
        ctx.style.font_size,
        ctx.style.font_spacing,
        ctx.style.line_spacing,
        eff,
    );
}

fn renderTooltip(ctx: *UiContext, t: TooltipData) void {
    const text_size: Vec2 = measureTextS(ctx, t.text());
    const padding: Vec2 = ctx.style.frame_padding;
    const rect = Rectangle{
        .x = t.pos[0],
        .y = t.pos[1],
        .width = text_size[0] + 2 * padding[0],
        .height = text_size[1] + 2 * padding[1],
    };
    drawRectFilled(ctx, rect, Color.toWire(ctx.style.window_bg));
    drawRect(ctx, rect, Color.toWire(ctx.style.border));
    drawTextAtS(ctx, .{ rect.x + padding[0], rect.y + padding[1] }, t.text(), Color.toWire(ctx.style.text));
}

/// Compute per-node rects given a root's `pos` and `size`.
/// Walks the tree, splitting space by each SPLIT's ratio and
/// axis. Mutates `node.pos` + `node.size` for every node in
/// the subtree; LEAF rects equal their final on-screen space.
/// Called once per frame per dockspace by the future `dockSpace`
/// widget.
/// Width (or height) of the splitter strip rendered between two
/// siblings of a SPLIT node. The strip is interactive - drag it
/// to change the split ratio. Constant - matches imgui's
/// `g.Style.DockingSeparatorSize` default (4 px). Layout
/// reserves this many pixels per split; the interactive
/// `renderDockSplitters` pass (5.5i, in ui.zig) draws + handles
/// drag in this gap.
pub const splitter_size: f32 = 4.0;

/// work out child sizes for a SPLIT node
/// given the available extent. Returns `[w_a, w_b]` (or `[h_a,
/// h_b]` for vertical splits) summing to `avail`.
/// Resolution order:
///   1. If exactly one child has a non-null `size_ref`, that
///      child is locked at `clamp(size_ref, MIN, avail-MIN)` and
///      the other child absorbs the remainder. This is the
///      "fixed-width left panel, flexible center" UX - the
///      hallmark feature this turn unlocks.
///   2. If both `size_ref` slots are null OR both are non-null
///      (over-constrained), fall back to `ratio`.
/// Imgui equivalent: per-node `SizeRef` field consulted by
/// `DockNodeTreeUpdatePosSize` (imgui.cpp:20322-20338). Our
/// model differs in two ways:
///   (a) `size_ref` lives on the SPLIT (one-per-pair) rather
///       than on each NODE - simpler, fewer places state can
///       drift, easier to serialize.
///   (b) No `WantLockSizeOnce` transient bool - splitter drag
///       writes directly to size_ref or ratio, no two-phase
///       protocol.
/// Compute the two child sizes for a SPLIT node given the available
/// pixels along the split axis. Returns `[size_of_child_a, size_of_child_b]`.
///
/// Rules:
///   - Both children locked OR both free → fall back to `split.ratio`.
///   - Exactly one locked → that child takes its locked size, the
///     other takes the remainder.
///   - Either child clamps to MIN_PANEL (24px) so a dragged splitter
///     can't shrink a pane to a sliver.
///
/// Used both by the runtime dock-rendering path (twice) and by the
/// docking persistence/test paths. Pre-turn-414 there was a `Public`
/// wrapper alias here because `DockNode.SplitData` lived in a
/// separate file; that wrapper is gone now that the dock layer is
/// inlined.
pub fn computeSplitChildSizes(split: DockNode.SplitData, avail: f32) [2]f32 {
    const MIN_PANEL: f32 = 24.0;
    const a_lock: ?f32 = split.size_ref[0];
    const b_lock: ?f32 = split.size_ref[1];

    // Both locked OR both free → ratio fallback.
    if ((a_lock != null) == (b_lock != null)) {
        const w_a: f32 = avail * split.ratio;
        return .{ w_a, avail - w_a };
    }

    if (a_lock) |px| {
        const w_a: f32 = clamp(px, MIN_PANEL, @max(MIN_PANEL, avail - MIN_PANEL));
        return .{ w_a, avail - w_a };
    } else {
        // b is locked
        const w_b: f32 = clamp(b_lock.?, MIN_PANEL, @max(MIN_PANEL, avail - MIN_PANEL));
        return .{ avail - w_b, w_b };
    }
}

pub fn layoutSubtree(
    ctx: *const DockContext,
    root_id: Id,
    root_pos: Vec2,
    root_size: Vec2,
) void {
    const root: *DockNode = ctx.lookup(root_id) orelse return;
    root.pos = root_pos;
    root.size = root_size;

    if (root.split) |split| {
        const a: *DockNode = ctx.lookup(split.child_ids[0]) orelse return;
        const b: *DockNode = ctx.lookup(split.child_ids[1]) orelse return;
        switch (split.axis) {
            .horizontal => {
                const avail: f32 = @max(0, root_size[0] - splitter_size);
                const sizes: [2]f32 = computeSplitChildSizes(split, avail);
                layoutSubtree(ctx, a.id, root_pos, .{ sizes[0], root_size[1] });
                layoutSubtree(
                    ctx,
                    b.id,
                    .{ root_pos[0] + sizes[0] + splitter_size, root_pos[1] },
                    .{ sizes[1], root_size[1] },
                );
            },
            .vertical => {
                const avail: f32 = @max(0, root_size[1] - splitter_size);
                const sizes: [2]f32 = computeSplitChildSizes(split, avail);
                layoutSubtree(ctx, a.id, root_pos, .{ root_size[0], sizes[0] });
                layoutSubtree(
                    ctx,
                    b.id,
                    .{ root_pos[0], root_pos[1] + sizes[0] + splitter_size },
                    .{ root_size[0], sizes[1] },
                );
            },
        }
    }
    // Leaves get their rect directly from the recursion above;
    // nothing else to compute.
}

/// The seam between a split node's two children, sized
/// `splitter_size` along the split axis and the full
/// perpendicular extent of the split. Returns a zero-sized
/// rectangle for leaf nodes (caller should already have
/// branched on `node.split`).
/// Position respects size_ref: a child locked at N pixels makes
/// the seam land at N pixels in, not at the ratio-derived
/// position. Otherwise the seam appears to drift when the user
/// resizes the dockspace.
fn dockSplitterSeamRect(node: *const DockNode) Rectangle {
    const split: DockNode.SplitData = node.split orelse return .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    const avail: f32 = switch (split.axis) {
        .horizontal => @max(0, node.size[0] - splitter_size),
        .vertical => @max(0, node.size[1] - splitter_size),
    };
    const sizes: [2]f32 = computeSplitChildSizes(split, avail);
    const a_size: f32 = sizes[0];
    return switch (split.axis) {
        .horizontal => .{
            .x = node.pos[0] + a_size,
            .y = node.pos[1],
            .width = splitter_size,
            .height = node.size[1],
        },
        .vertical => .{
            .x = node.pos[0],
            .y = node.pos[1] + a_size,
            .width = node.size[0],
            .height = splitter_size,
        },
    };
}

/// Is `rect` under the mouse AND actually visible?
///
/// ── ★ THE CLIP TEST IS THE WHOLE POINT ──
///
/// Widgets used to hit-test with a bare `itemHoverable(ctx, rect)`, which asks
/// only "is the mouse where this widget WOULD be". A widget scrolled out of its window, or
/// sitting past the window's edge, keeps its layout rect — so it stayed grabbable through the
/// window frame and through whatever was drawn on top. Dragging in empty space moved sliders
/// that were nowhere on screen.
///
/// ★ The clip stack that already existed is a DRAW-TIME structure, consulted when the draw
/// list is replayed. Interaction ran with no clip at all, which is why the bug was invisible
/// from the rendering side: the widget was correctly not DRAWN and incorrectly still LIVE.
///
/// ImGui's equivalent is `ItemHoverable` calling `IsClippedEx`; this is the same idea with one
/// rect instead of a stack, which is all a window-scoped UI needs.
/// Point interaction clipping at whatever window is now on top of the stack.
///
/// ★★ MUST BE CALLED ON BOTH PUSH AND POP. Setting it only on POP — which is how this shipped
/// first — leaves `item_clip` holding the PREVIOUS window's rect (or null, for the first
/// window) for the entire time a window's widgets are being submitted. Every widget then
/// hit-tests unclipped, which is exactly the bug the clip was added to fix: sliders below a
/// window's bottom edge stay grabbable.
fn refreshItemClip(ctx: *UiContext) void {
    ctx.current_window = if (ctx.window_stack.len > 0)
        ctx.window_stack.items[ctx.window_stack.len - 1]
    else
        null;
    ctx.item_clip = if (ctx.current_window) |cw| Rectangle{
        .x = cw.pos[0],
        .y = cw.pos[1],
        .width = cw.size[0],
        .height = cw.size[1],
    } else null;
}

fn itemHoverable(ctx: *UiContext, rect: Rectangle) bool {
    if (!pointInRect(ctx.input.mouse_pos, rect)) {
        return false;
    }
    if (ctx.item_clip) |clip| {
        return pointInRect(ctx.input.mouse_pos, clip);
    }
    return true;
}

fn pointInRect(p: Vec2, r: Rectangle) bool {
    return p[0] >= r.x and p[0] < r.x + r.width and
        p[1] >= r.y and p[1] < r.y + r.height;
}

fn renderDockSplittersImpl(ctx: *UiContext, node_id: Id) bool {
    const node: *DockNode = ctx.dock.lookup(node_id) orelse return false;
    if (node.split) |split| {
        // Recurse into children first. Visually, parent seam
        // draws on top of children, so we paint child seams
        // first (further from root) then ours.
        var changed: bool = false;
        if (renderDockSplittersImpl(ctx, split.child_ids[0])) {
            changed = true;
        }
        if (renderDockSplittersImpl(ctx, split.child_ids[1])) {
            changed = true;
        }

        const seam_rect: Rectangle = dockSplitterSeamRect(node);

        // Widget id: derive from node id with a salt so we can't
        // collide with normal widgetId hashes for the same u32.
        const id: Id = hashStr(node.id, "__dock_splitter");

        const hovered: bool = itemHoverable(ctx, seam_rect);
        if (hovered) {
            ctx.hovered_id = id;
        }

        const interactive: bool = !node.flags.no_resize;

        // Press: claim active_id.
        if (interactive and hovered and ctx.input.mouse_left_clicked and ctx.active_id == 0) {
            ctx.active_id = id;
            ctx.active_id_just_activated = true;
        }

        const held: bool = (ctx.active_id == id and ctx.input.mouse_left_down);

        if (held and interactive) {
            // Compute new ratio from mouse position relative to
            // the available (non-seam) extent. Convert mouse
            // position in the split's axis to a fraction.
            const avail: f32 = switch (split.axis) {
                .horizontal => @max(1, node.size[0] - splitter_size),
                .vertical => @max(1, node.size[1] - splitter_size),
            };
            const mouse_in_axis: f32 = switch (split.axis) {
                .horizontal => ctx.input.mouse_pos[0] - node.pos[0],
                .vertical => ctx.input.mouse_pos[1] - node.pos[1],
            };
            // Mouse landed at the LEFT edge of the seam (seam
            // origin) when ratio was 0. Use seam center as the
            // pivot for symmetric feel.
            const target_w_a: f32 = clamp(
                mouse_in_axis - splitter_size * 0.5,
                avail * 0.05,
                avail * 0.95,
            );

            // if a size_ref lock is active,
            // drag updates the locked side's px rather than the
            // ratio - this preserves the fixed-width-panel UX
            // (drag widens/narrows the locked panel, keeps it
            // locked at the new size). When no lock is set, fall
            // back to ratio mutation (5.5i behavior).
            if (split.size_ref[0] != null) {
                // a is locked → mutate its px to the new width.
                if (split.size_ref[0].? != target_w_a) {
                    node.split.?.size_ref[0] = target_w_a;
                    node.generation +%= 1;
                    changed = true;
                }
            } else if (split.size_ref[1] != null) {
                // b is locked → b's px is `avail - target_w_a`.
                const new_b_px: f32 = avail - target_w_a;
                if (split.size_ref[1].? != new_b_px) {
                    node.split.?.size_ref[1] = new_b_px;
                    node.generation +%= 1;
                    changed = true;
                }
            } else {
                const new_ratio: f32 = target_w_a / avail;
                if (new_ratio != split.ratio) {
                    node.split.?.ratio = new_ratio;
                    node.generation +%= 1;
                    changed = true;
                }
            }
        }

        // Release: clear active_id.
        if (ctx.active_id == id and ctx.input.mouse_left_released) {
            ctx.active_id = 0;
        }

        // Draw the seam. Color by state. Idle seam is a
        // visible (but not loud) strip so the user can SEE where
        // to grab; hover brightens it; held uses the active
        // button color for maximum feedback. Style tokens for a
        // dedicated splitter color don't exist yet; filed for
        // future style cleanup (matches imgui's pending TODO).
        const fill_color: Color = if (held)
            ctx.style.button_active
        else if (hovered and interactive)
            ctx.style.button_hovered
        else
            .{ .r = 90, .g = 100, .b = 130, .a = 230 };
        drawRectFilled(ctx, seam_rect, Color.toWire(fill_color));

        return changed;
    }
    return false;
}

/// walk the subtree and handle interaction
/// + rendering for every split node's seam. Returns true if a
/// drag changed any `split.ratio` this call - the caller re-runs
/// layout to apply the change THIS frame.
/// The seam rect is the `splitter_size`-wide gap reserved by
/// `layoutSubtree` between a split node's two children. We draw
/// + hit-test it directly; no widget id is "registered" on a
/// window because dockspace seams don't live in any window's
/// content area.
/// The widget id is derived from the split node id via
/// `hashU32` so it can't collide with normal `widgetId` hashes
/// (which thread through `current_window`'s id stack).
/// Quick-hit UX features beyond imgui's basic drag:
///   - Double-click resets ratio to 0.5 (50/50). imgui doesn't
///     do this; common pattern from VS Code / Photoshop.
///   - `no_resize` flag on the split node disables interaction
///     (but the seam still renders so the visual layout reads
///     correctly).
/// Runs inside `flushDockTabsToForeground`, so renders into
/// whatever draw list is current there (caller switches to
/// foreground_dl AFTER this returns - splitters draw into the
/// per-window dl by default, layered below the tab bars; ideal).
fn renderDockSplitters(ctx: *UiContext, root_id: Id) bool {
    return renderDockSplittersImpl(ctx, root_id);
}

/// walk the dockspace subtree rooted at
/// `root_id` and emit a clickable tab bar across the top edge of
/// every leaf. Tabs reflect the leaf's `window_ids` in order;
/// the active tab matches `leaf.selected_window_id`.
/// Click handling: if the mouse is over a tab AND the user pressed
/// left this frame, set `selected_window_id` to that tab's window.
/// The selected window's content shows from THIS frame's submission
/// because findOrCreateWindow read pos/size from the leaf earlier,
/// and openWindow's docked-and-selected check sees the just-updated
/// selection. Tab clicks on a non-selected window therefore take
/// effect on the SAME frame - no one-frame stutter.
/// Tab labels: looked up via `ctx.windows.get(wid).name()`. Windows
/// that haven't been submitted yet (dockBuilder ran before any
/// `window()` call) get a fallback hex-id label so the bar is at
/// least visible.
/// Drains `ctx.dock.dockspaces_this_frame` and emits tabs into
/// `ctx.foreground_dl`.  Called from `endFrame` in normal
/// run-mode; called from the screenshot section's `renderToBytes`
/// in host-test mode so single-frame PNG renders see the tabs.
pub fn flushDockTabsToForeground(ctx: *UiContext) void {
    for (ctx.dock.dockspaces_this_frame.items) |dockspace_id| {
        // Re-run layout with the dockspace's CURRENT root pos/size.
        // The user's `dockBuilder*` calls between `dockSpace()` and
        // endFrame may have mutated the tree (splits, dock-as-tab)
        // - re-walking the tree here ensures every leaf has a
        // fresh rect for the tab-bar rendering pass. Pos/size of
        // the root were captured by `dockSpaceImpl` and persist on
        // the root node across the frame.
        const root: *DockNode = ctx.dock.lookup(dockspace_id) orelse continue;
        layoutSubtree(&ctx.dock, dockspace_id, root.pos, root.size);

        // process splitter drags BEFORE
        // drawing tabs. A drag updates `split.ratio` in place;
        // we re-run layout once more so the visual reflects the
        // new ratio THIS frame (otherwise the splitter visibly
        // lags one frame behind the cursor - annoying).
        const splitter_changed: bool = renderDockSplitters(ctx, dockspace_id);
        if (splitter_changed) {
            layoutSubtree(&ctx.dock, dockspace_id, root.pos, root.size);
        }

        const saved: ?*DrawList = ctx.current_draw_list;
        ctx.current_draw_list = &ctx.dock_tabs_dl;
        renderDockLeafTabBars(ctx, dockspace_id);

        //.iii: when a window is being dragged,
        // overlay each leaf with a 5-zone preview (center + 4 edges)
        // so the user can see where the released drag will dock.
        // Renders into foreground_dl above the tab bars. The
        // hit-test + DockRequest enqueue belongs to 5.5d.iv
        // today the overlay is purely visual feedback.
        if (ctx.dock.dragging_window != null) {
            renderDockTargetOverlay(ctx, dockspace_id);
        }

        ctx.current_draw_list = saved;
    }
}

/// The "global" state, made explicit. Lives in `App`, set up once,
/// borrowed each frame. Owns the persistent window store.
pub const UiContext = struct {
    gpa: Allocator,

    /// Per-frame arena for DrawList variable-length payloads - text
    /// bytes, polyline points, future path data, and the DrawList
    /// command lists themselves. Reset (capacity-retaining) at
    /// endFrame after all draw lists have rendered. Slices recorded
    /// into cmds remain valid for one full frame.
    /// Initialized in `UiContext.init` from `gpa`. The user passes
    /// only gpa - ui creates and manages this arena internally, which
    /// is an exception to the broader zimr rule that allocating
    /// functions take scratch/gpa/both per call.
    frame_arena: FrameArena,

    // Whether the wasm runtime should swallow keyboard / mouse
    // events instead of forwarding them to the host page is
    // computed on demand by `Ui.wantCaptureKeyboard` /
    // `Ui.wantCaptureMouse` (active_id != 0 / mouse-over a frame
    // window), so no static flag lives on the context.

    /// Persistent open/closed state for `treeNode` widgets, keyed
    /// by the node's hashed ID. Survives across frames so trees
    /// stay in the state the user left them. Default: missing
    /// entry → closed. Memory: lives in `gpa`.
    tree_open_state: std.AutoHashMapUnmanaged(Id, bool) = .{},

    /// Persistent window store, keyed by hashed title.
    windows: std.AutoArrayHashMapUnmanaged(Id, *Window) = .{},

    // ---- persistence
    // `pending_persistence` holds PersistedWindow entries loaded from
    // a previous session's `.zon` payload before any `beginFrame` has
    // run. When `findOrCreateWindow` first sees a title, it consumes
    // the matching pending entry (if any) and grafts pos/size/scroll
    // onto the new Window before the per-frame layout runs. After
    // consumption the entry is removed; entries that never get
    // consumed (titles no longer in the program) are dropped on
    // `UiContext.deinit`.
    // `persistence_key` is the opt-in identifier used by the
    // storage layer (localStorage key, file path on host). When
    // null, no save/load happens - pure in-memory mode, same as
    // every existing demo today. Set by callers before the first
    // beginFrame.
    pending_persistence: std.StringHashMapUnmanaged(PersistedWindow) = .{},
    persistence_key: ?[]const u8 = null,

    /// per-bar selection staging. Keyed by
    /// the compound string `"<window_name>\x00<str_id>"` (NUL
    /// separator is fine for our use - both window names and
    /// str_ids exclude NUL). Value is the persisted selected-tab
    /// label. Populated by `ui_persistence.apply`; consumed by
    /// `openTabBar` on the FIRST submission of each bar. Unconsumed
    /// entries (bars no longer in the program) are released on
    /// `UiContext.deinit`.
    pending_tab_bar_selections: std.StringHashMapUnmanaged([]const u8) = .{},

    /// docking system. Pure-data tree of
    /// `DockNode` pooled by `Id` plus per-frame bookkeeping
    /// (active dockspaces, pending operations). Defaulted to
    /// empty - apps that don't use docking pay zero overhead
    /// (the maps stay empty, the per-frame lists are no-op'd).
    dock: DockContext = .{},

    /// persisted dock tree awaiting
    /// restore. Populated by `ui_persistence.apply` from a
    /// loaded payload; drained by `dockSpace()` on the first
    /// call after load. Memory is owned by `gpa` - strings
    /// inside (window names) are duped at apply-time so
    /// they survive past the zon-parse free. Cleared on
    /// successful drain or on `UiContext.deinit`.
    pending_dock_tree: []PersistedDockNode = &.{},

    /// Active style - mutated directly or via push/pop in later phases.
    style: Style = Style.dark_default,

    // ---- Phase A1: clipboard read-cache
    // Browser clipboard reads are async (Promise-based). This
    // 4KB fixed buffer caches the most recent successful read so
    // `Ui.getClipboardText()` can be sync from the user's
    // perspective. Populated by `runtime.pollClipboardText` when
    // a fetch completes; until then `clipboard_cache_len` is 0
    // and the getter returns "".
    // Sized at 4096 bytes - covers typical text-clipboard
    // contents (URLs, command lines, code snippets). Longer
    // contents truncate cleanly. Pure-data; no allocation.
    clipboard_cache: [4096]u8 = undefined,
    clipboard_cache_len: usize = 0,

    // ---- DebugLog ring
    // BoundedArray<DebugEvent, 256> — fixed-capacity ring backed by
    // an inline array. Overflow is handled in `debugLogPush` by
    // dropping the oldest event before appending. No allocation,
    // no serialization. See `DebugEvent` and `debugLogPush`.
    debug_log: BoundedArray(DebugEvent, debug_log_cap) = .{},

    // ---- Frame metrics
    // Plain inline struct (~520B). Reset cadence:
    //   - `metricsResetRenderCounters` zeroes cmd_count + drawlist_count
    //     just before the per-frame render loop in `endFrame`.
    //   - `metricsCollectAtEndFrame` populates the rest near the top
    //     of `endFrame`.
    //   - `metricsAccumulateDrawList` adds to cmd_count + drawlist_count
    //     once per `DrawList.render` call (5 fixed sites in `endFrame`
    //     plus tooltip-block + drag-preview if active).
    metrics: Metrics = .{},

    // ---- P3: Long-press → right-click synthesis
    // Single-touch long-press tracker. Inspected + mutated by
    // `applyLongPressSynthesis` once per `beginFrame`. Default-zero
    // state means "no touch being tracked"; gets initialised on the
    // first frame a single finger is observed down.
    long_press: LongPressTracker = .{},

    /// Input snapshot for the in-flight frame. Stamped by
    /// `beginFrame`.
    input: InputSnapshot = .{},

    /// Live `*InputState` for the in-flight frame. Most input reads
    /// go through `input` (the snapshot) for headless-testability, but
    /// a few imgui-parity calls - `Ui.resetMouseDragDelta`,
    /// `Ui.setMouseCursor` - need to MUTATE input state, and a few
    /// drag helpers need fields the snapshot doesn't carry
    /// (per-button press anchor). Stamped by `beginFrame`; null
    /// outside a frame.
    input_state: ?*runtime.input.InputState = null,

    /// Per-frame gesture detector, ticked once in `beginFrameRaw` from
    /// `input_state` + the monotonic UI clock. Lets widgets read pinch /
    /// drag / swipe via `Ui.pinch()` etc. without each rolling their own
    /// touch bookkeeping — the same detector the standalone demos use.
    gestures: runtime.gestures.GesturesState = .{},

    /// The window currently being submitted to (between
    /// `window(...)` and `WindowHandle.close()`). Null outside.
    current_window: ?*Window = null,
    /// The rect interaction is confined to, or null outside any window. Set from the current
    /// window's bounds each time the window stack changes; see `itemHoverable`.
    item_clip: ?Rectangle = null,

    /// FIFO of active window pointers - supports nested
    /// `window(...)` calls (rare but allowed).
    window_stack: BoundedStack(*Window, 8) = .{},

    /// ID stack for disambiguation. Push a parent ID; subsequent
    /// `getId(label)` calls hash with the top of stack as seed.
    id_stack: BoundedStack(Id, 32) = .{},

    /// The widget the user is currently interacting with (e.g.
    /// holding a button down). Zero = none.
    active_id: Id = 0,
    /// Set the frame `active_id` was set non-zero - used for one-
    /// shot logic like "did the user just start a drag?"
    active_id_just_activated: bool = false,
    /// When true, the NEXT focusable widget submitted this frame
    /// claims keyboard focus (`active_id` set to that widget's id).
    /// Set by `ui.setKeyboardFocusHere()`; cleared either by the
    /// widget that consumed it OR at the end of the frame. Today
    /// only `inputText` honors this - every other focusable widget
    /// could opt in by checking the flag in the same idiom.
    next_widget_take_focus: bool = false,
    /// Mouse-X at the moment the active widget was first clicked.
    /// Used by `drag` to compute cumulative drag distance.
    active_id_press_x: f32 = 0,
    /// Initial value (as f64) at the moment the active widget was
    /// first clicked. Used by `drag` to compute new value =
    /// initial + delta * speed.
    active_id_press_value: f64 = 0,
    /// frame time (seconds since context init)
    /// when active widget was first clicked. Used by
    /// `ItemFlags.button_repeat` to compute initial-delay timing.
    active_id_press_time: f32 = 0,
    ///.ii: mouse position at the moment the
    /// active widget was first clicked, in SCREEN (canvas) pixels.
    /// `active_id_press_x` / `_value` stash the offset WITHIN the
    /// dragged target (window-local), useful for "stay anchored to
    /// the press point" continue-drag behavior; this field is the
    /// raw screen press point, useful for cumulative-motion
    /// thresholds (e.g. dock-drag detach: "did the mouse move more
    /// than 8px from where it was pressed?"). Set on every
    /// active_id_just_activated frame; never cleared (the next
    /// activation overwrites).
    active_id_press_screen: Vec2 = .{ 0, 0 },
    /// frame time of the most recent
    /// auto-repeat tick for the active button-repeat widget.
    active_id_last_repeat_time: f32 = 0,
    /// cumulative frame time, accumulated
    /// from `frame.time.delta_time` at every beginFrame. Used as the
    /// monotonic clock for button-repeat cadence (and future
    /// hover-delay). Independent of wall clock - only advances
    /// when the ui ticks, so a tab-backgrounded app doesn't
    /// emit a flood of repeats when re-foregrounded.
    frame_time_seconds: f32 = 0,
    /// The widget the mouse is over. Set during widget submission
    /// in the order of submission, so the LAST widget under the
    /// mouse wins (matches ImGui's behavior).
    hovered_id: Id = 0,
    /// Hovered ID from the previous frame - used for hover-stable
    /// transitions (e.g. "just-hovered" detection).
    hovered_id_prev_frame: Id = 0,
    /// Active ID from the previous frame. Used to compute per-widget
    /// activated/deactivated transitions (e.g. for `isItemActivated`).
    /// Snapshotted in `endFrame`; the helper `markItem` consults it.
    active_id_prev_frame: Id = 0,
    /// Was the previous-frame's active widget edited at any point
    /// during its activation? Sticky during the activation; resets
    /// when the widget is deactivated. Drives
    /// `isItemDeactivatedAfterEdit`.
    active_id_was_edited: bool = false,

    // ---- keyboard nav state ---------------------------------
    /// The widget that currently holds keyboard focus. Independent
    /// of `active_id` (which tracks mouse-drag captures). Zero =
    /// nothing focused; widgets compare their id to this value to
    /// decide whether to (a) draw a focus border, (b) treat Enter as
    /// a synthesized click. Mutated at beginFrame from Tab/Shift+Tab
    /// based on the PREVIOUS frame's submitted nav items.
    nav_id: Id = 0,
    /// Submitted-this-frame focusable widget IDs in submission order.
    /// Built up via `markItemNavigable` calls during widget
    /// submission, consulted at the START of the NEXT frame's
    /// beginFrame to advance `nav_id` on Tab. Cleared each frame.
    /// Cap of 64 covers typical workloads - a screen with more than
    /// 64 focusable widgets at once is a UX problem regardless.
    frame_nav_items: BoundedStack(Id, 64) = .{},

    /// Auto-position counter for windows that didn't specify a
    /// position. Increments each frame to spread default windows.
    next_default_pos: Vec2 = .{ 60, 60 },

    /// Frame counter for GC + animation timing.
    frame_count: u64 = 0,

    // ---- setNextWindow* state
    // Per-frame "next window" overrides; consumed by the next
    // `openWindow` call and reset. Mirrors ImGui's `SetNextWindowPos`
    // / `SetNextWindowSize` family.

    /// Position to apply to the next window opened this frame.
    /// Cleared after `openWindow` consumes it.
    next_window_pos: ?Vec2 = null,
    /// `true` ⇒ apply on every frame; `false` ⇒ apply only when the
    /// window is first created (matches ImGui's `ImGuiCond_Once`).
    next_window_pos_always: bool = true,
    /// Size override (analogous to next_window_pos).
    next_window_size: ?Vec2 = null,
    /// Per-axis: this axis of `next_window_size` was given as zero, meaning "fit the
    /// content" rather than "be zero pixels".
    next_window_size_auto: [2]bool = .{ false, false },
    next_window_size_always: bool = true,
    /// Minimum-size constraint for the next window, applied at
    /// open time and every subsequent frame the window exists.
    /// Stored as `(min, max)` pair so a single
    /// `setNextWindowSizeConstraints` call covers both bounds.
    /// `null` = no min constraint. Imgui: `SetNextWindowSizeConstraints`
    /// (`imgui.cpp:8664-8671`). Imgui also supports a custom
    /// callback for non-rectangular constraints (aspect ratio
    /// etc.) - deferred follow-up.
    next_window_size_min: ?Vec2 = null,
    /// Max-size constraint, same shape as min. `null` = no max.
    /// FLT_MAX semantically equivalent; we use null because
    /// optional is cheap.
    next_window_size_max: ?Vec2 = null,
    /// Background alpha multiplier for the next window - 0 = fully
    /// transparent background, 1 = opaque (default). Cleared after
    /// the window is opened.
    next_window_bg_alpha: ?f32 = null,
    /// Force the next window to top-of-z-order (raises it above
    /// other windows in the submission order list).
    next_window_focus: bool = false,
    /// override the next tree node's open
    /// state. Consumed by the first `treeNode` after the call.
    /// `null` = no override (use stored state or `default_open`).
    /// Imgui: `SetNextItemOpen` (`g.NextItemData.OpenVal` /
    /// `OpenCondVal`).
    next_item_open: ?bool = null,
    /// set to true within `treeNodeExImpl` when the
    /// node's open state flipped this frame. Surfaced via
    /// `isItemToggledOpen` (matches imgui's
    /// `ImGuiItemStatusFlags_ToggledOpen`). Reset at every
    /// widget submission.
    item_just_toggled: bool = false,
    /// Window-id of the currently-focused window (top of z-order in
    /// `frame_windows`). Updated when a window is clicked or
    /// `setNextWindowFocus` raises one.
    focused_window_id: Id = 0,
    /// Window-id under the mouse this frame (set during widget
    /// submission as windows are encountered). Used by
    /// `isWindowHovered` and to gate widget hit-tests so a click
    /// hitting two stacked windows only activates the top one.
    hovered_window_id: Id = 0,

    /// Per-frame flag set true once a window (or child window)
    /// consumes the mouse wheel. Inner children's `endChildImpl`
    /// runs before outer's (due to nesting order), so the deepest
    /// scope under the cursor gets first dibs. Reset to false at
    /// each `beginFrameRaw`; checked + set by every scroll-aware
    /// scope (`closeWindow`, `endChildImpl`, `closeListBox`).
    /// Matches imgui's `WantCaptureMouse`-like cascade - the
    /// deepest hovered scope wins, outer scopes see "wheel
    /// already handled" and don't double-apply.
    mouse_wheel_consumed: bool = false,
    /// P5.5b: horizontal counterpart of
    /// `mouse_wheel_consumed`. Reset at each `beginFrameRaw`;
    /// checked + set by horizontal-scroll-aware scopes. Kept
    /// separate from the Y consumed flag so a window can scroll Y
    /// from a hovered child while still allowing X scroll on the
    /// outer window (axes consume independently).
    mouse_wheel_x_consumed: bool = false,

    /// Pending tooltip submission. Last call wins (matches ImGui
    /// semantics). Rendered at endFrame on top of everything else.
    pending_tooltip: ?TooltipData = null,

    /// Active input-text edit state. Valid only while a text input
    /// has focus (active_id matches the input's ID). Reset to
    /// defaults when focus is gained on a different inputText (the
    /// cursor jumps to wherever the new one was last left or to the
    /// end of buffer if first focus). holds just cursor +
    /// blink; selection ranges + scroll come later.
    input_text_state: InputTextState = .{},

    /// Id of the combo widget currently in its "open" (dropdown
    /// expanded) state, or 0 for none. Single-slot - only one combo
    /// is open at a time. Persisted across frames. Opening combo B
    /// while combo A is open implicitly closes A.
    combo_open_id: Id = 0,

    /// Active `beginCombo` scope. Non-null between a `beginCombo`
    /// call that returned true and the matching `endCombo`. Holds
    /// the dropdown's geometry + saved cursor state so widgets
    /// submitted inside the combo (typically `selectable` calls)
    /// route into the dropdown rect instead of advancing the
    /// host window's cursor.
    combo_scope: ?ComboScope = null,

    // ---- Deferred draw lists (proper z-order)
    // Widgets append commands to a draw list during submission. At
    // endFrame, lists are replayed: window draw lists first (in order
    // they were submitted this frame), foreground draw list last (so
    // popups + tooltips overlay everything).

    /// Currently active draw list. Widget helpers
    /// (drawRectFilled etc.) append commands here unless `eager_mode`
    /// is true. Set by openWindow/closeWindow to the active window's
    /// draw list, or temporarily redirected for popups/tooltips.
    /// Null means no widget submission is currently in scope.
    current_draw_list: ?*DrawList = null,

    /// Foreground draw list - popups, tooltips, anything that should
    /// overlay all windows. Lives on the context (not a window) since
    /// it's not bound to any specific window's z-order. Cleared each
    /// frame. Allocates through `frame_arena` like every other
    /// DrawList. Exposed via `Ui.getForegroundDrawList()`.
    foreground_dl: DrawList = .{},
    /// Dock leaf tab bars render here — ABOVE docked content but BELOW floating
    /// windows, so floating headers sit on top of dock tabs.
    dock_tabs_dl: DrawList = .{},

    /// Background draw list - renders BEFORE any window, so callers
    /// can paint a backdrop / grid / watermark that lives under all
    /// UI. Same shape as `foreground_dl` (frame-arena allocated,
    /// cleared every frame). Exposed via `Ui.getBackgroundDrawList()`.
    /// Most apps leave this empty; useful for tools that want a
    /// consistent backdrop behind their windows (a CAD app's grid,
    /// a level editor's brush preview, etc.).
    background_dl: DrawList = .{},

    /// Block-tooltip window - lazily allocated on first
    /// `beginTooltip()` call, reused across frames. When non-null
    /// AND `tooltip_active_this_frame` is true at endFrame, its
    /// draw list is rendered on top of everything else (after
    /// foreground_dl) so the tooltip overlays popups too.
    tooltip_window: ?*Window = null,
    /// Set by `beginTooltip` when the block opens this frame;
    /// consumed at endFrame to decide whether to render the
    /// tooltip window. Reset to false in beginFrame.
    tooltip_active_this_frame: bool = false,

    /// Drag-drop state. Single-slot - only one drag in flight at
    /// any moment, matching imgui's model. Persists across frames
    /// while a drag is in progress; resets to idle on mouse release.
    drag_drop: DragDropState = .{},
    /// Drag preview window - lazily allocated on first drag.
    /// Reused across frames. Hosts the draw list submitted inside
    /// a `beginDragDropSource` block. Rendered on top of
    /// everything (alongside the tooltip) at endFrame.
    drag_preview_window: ?*Window = null,
    /// Set by `beginDragDropSource` when the block opens this
    /// frame; consumed at endFrame to decide whether to render the
    /// drag preview window. Reset to false in beginFrame.
    drag_preview_active_this_frame: bool = false,

    /// stack of `Style` field snapshots so `pushStyle`
    /// / `popStyle` can temporarily override style values
    /// (e.g. for a custom-padded button group, an accent-colored
    /// section). Bounded - 32 nested pushes is more than any
    /// real app needs. Field name + bytes copy approach handles
    /// every current Style field (all POD: Color, Vec2, f32,
    /// i32, optional pointer).
    style_stack: BoundedStack(StyleSnapshot, 32) = .{},

    /// Windows submitted this frame, in submission order. Replayed
    /// at endFrame. Cleared in beginFrame; appended in openWindow.
    /// Cap of 32 is plenty - real apps rarely exceed 8 simultaneous
    /// windows.
    frame_windows: BoundedStack(*Window, 32) = .{},
    /// Rects of the windows submitted LAST frame. Used only by
    /// `wantCaptureMouse` as an order-independent fallback — see the comment at
    /// the snapshot site in `beginFrameRaw`. Stored as plain rects (not `*Window`)
    /// so it stays valid even if a window is destroyed between frames.
    prev_window_rects: BoundedStack(Rectangle, 32) = .{},

    /// When true (inside a `pushRenderTexture` scope), draw helpers
    /// emit straight to rlgl instead of recording commands. Preserves
    /// the recursive_hud demo's "push RT, draw stuff, pop RT" eager
    /// semantics - UI submitted in an RT scope renders synchronously
    /// to the RT, not deferred to endFrame.
    eager_mode: bool = false,

    /// Active table state when inside a `beginTable` scope.
    /// Single-slot: nested tables are not supported in.
    /// Null outside any table scope.
    active_table: ?TableState = null,

    /// Persistent sort state keyed by table id - survives across
    /// frames so click-to-sort changes "stick" until the user
    /// clicks something else. Lazily populated at
    /// `tableHeadersRow` time; entries never auto-evicted (sort
    /// specs are tiny).
    table_sort_state: std.AutoHashMapUnmanaged(Id, TableSortSpecs) = .empty,

    /// Persistent vertical-scroll offset per table id. Lazily
    /// populated at `beginTable` time when `outer_height > 0`.
    /// Mutated by mouse-wheel handling at row submission.
    /// Clamped + written back at `endTable`.
    table_scroll_state: std.AutoHashMapUnmanaged(Id, f32) = .empty,

    /// P8.4: per-table cache of measured column
    /// content widths, keyed by table id. Populated at endTable
    /// from each `TableColumnState.width_auto_seen`; read back at
    /// beginTable into the new frame's column state. Used by the
    /// content-fit sizing modes (`fixed_fit`, `fixed_same`,
    /// `stretch_prop`) which need the previous frame's measured
    /// widths to size the current frame. Entries never
    /// auto-evicted; the per-id cost is one `[max_table_columns]f32`
    /// (~128 B at max_table_columns=32), small enough to leave
    /// resident.
    table_width_auto_cache: std.AutoHashMapUnmanaged(Id, [max_table_columns]f32) = .empty,

    // ---- Live-frame substate refs
    // These three pointers are the per-frame live substates the UI
    // needs for eager-mode draw paths and for any path that bypasses
    // the deferred draw list (typically the small handful of
    // immediate-mode helpers that emit to GL directly when no
    // current_draw_list is set).
    // Set in `beginFrame` from the caller's Frame. Stale outside
    // of begin/endFrame - never dereference them between frames.
    // Long-lived UiContext fields they're NOT - they're purely a
    // per-frame stash so widgets called inside `update` can find
    // the active gl/shapes/font without threading them through
    // every widget signature.
    // The deferred path (DrawList replay in `endFrame`) takes its
    // substates as explicit parameters and does NOT use these.

    /// Live `*GlState` for the current frame. Used by eager-mode
    /// draw paths (debug/RT scope) which bypass the draw list and
    /// emit directly to GL. Set in `beginFrame`, cleared logically
    /// after `endFrame` (we leave the pointer alive but don't
    /// dereference between frames).
    frame_gl: ?*Gl = null,
    /// Live `*const WindowState` for the current frame, captured at
    /// `beginFrame`.  Read by the deferred-render path so DrawList
    /// replays know the canvas dims and coord conventions.  We hold
    /// only `WindowState`, not the whole `*Frame` — UI has no business
    /// looking at the loader / clock / rng / log / random bits of
    /// `Frame`.  Stays null on the test path (`beginFrameRaw`).
    frame_window: ?*const runtime.core.WindowState = null,
    /// Live shapes-texture cache for the current frame. Used by
    /// eager-mode shape draws.
    frame_shapes_state: ?*const shapes2d.ShapesTextureState = null,
    /// Live font cache for the current frame. Used by eager-mode
    /// text draws + measureTextS.
    frame_font_cache: ?*const text2d.FontCache = null,

    // ---- Surface / render-target composition (recursive UI)
    // The UI tracks a stack of surfaces. Empty stack ⇒ rendering to
    // the main canvas. `pushRenderTexture(rt)` enters an RT scope:
    // FBO bound, viewport + ortho matrices set for RT size.
    // `popRenderTexture()` undoes. Composition is recursive - render
    // a HUD to one RT while another RT is bound, then `image(rt)`
    // both anywhere downstream.

    /// Width of the main canvas in pixels. Populated by `beginFrame`
    /// from the host. Used as the implicit bottom-of-stack surface.
    canvas_w: u32 = 0,
    /// Height of the main canvas in pixels. See `canvas_w`.
    canvas_h: u32 = 0,
    /// Active surface stack. Top = current render target. Bounded
    /// at 8 levels - recursive UIs more than 8 deep are unusual and
    /// likely a bug.
    surface_stack: BoundedStack(Surface, 8) = .{},

    // ---- layout + disabling state
    // pushItemWidth / popItemWidth - push/pop a "preferred width"
    // value that widgets read for their primary input element.
    // setNextItemWidth fires once for the next widget; setting the
    // stack value gives a longer-lived override.
    // beginDisabled / endDisabled - push/pop a counter; while > 0,
    // input is gated and rendering uses an alpha multiplier so
    // widgets read as "greyed out". ImGui semantics exactly.
    // beginGroup / endGroup - wrap a sequence of widgets so the
    // group reads as a single item to `isItemHovered`/`isItemActive`
    // queries that follow `endGroup`. Useful for clusters like
    // "label + reset button" that want to act as one row.

    /// Per-widget width override consumed by the next widget call,
    /// then cleared. ImGui: `SetNextItemWidth`.
    next_item_width: ?f32 = null,
    /// Stacked width override. Top-of-stack value applies to
    /// every subsequent widget until popped. Cap of 8 - deeper
    /// nesting than that is a likely caller bug.
    item_width_stack: BoundedStack(f32, 8) = .{},
    /// Push-count for `beginDisabled`. When non-zero, widgets
    /// silently ignore input AND render with `style.alpha *
    /// disabled_alpha`. Counter form (not bool) so nested
    /// `beginDisabled(false)` blocks compose: an inner
    /// `beginDisabled(false)` doesn't re-enable a parent that
    /// already disabled itself.
    disabled_count: u32 = 0,
    /// Per-scope marker - was THIS `beginDisabled` call's argument
    /// `true`? `endDisabled` consults the top of stack to know
    /// whether to decrement `disabled_count`. `false`-passes are
    /// recorded so the push/pop pairing stays balanced.
    disabled_marker_stack: BoundedStack(bool, 16) = .{},
    /// Saved input snapshot at the moment `disabled_count`
    /// transitioned 0 → 1. Restored when it transitions back to
    /// zero. Only the OUTERMOST disabled scope saves; inner
    /// `beginDisabled(true)` calls just bump the count without
    /// changing the already-suppressed input.
    saved_input_when_disabled: ?InputSnapshot = null,
    /// Alpha multiplier applied to every draw command. 1.0 by
    /// default; reduced inside a `beginDisabled` scope to
    /// `style.disabled_alpha` so widgets render greyed-out.
    alpha_mul: f32 = 1.0,
    /// cross-widget behavior flags stack.
    /// `pushItemFlag(opts)` merges with the existing top via
    /// `mergeItemFlags`; `popItemFlag` pops one entry. Widgets
    /// read `currentItemFlags()` for the merged effective view.
    /// `beginDisabled` continues to maintain its own
    /// `disabled_count` for back-compat; the two systems agree on
    /// "is disabled" via `currentItemFlags().disabled`.
    item_flags_stack: BoundedStack(ItemFlags, 16) = .{},
    /// Open `beginGroup` scopes. Each entry remembers the cursor
    /// position + cursor_max at the moment the group opened, so
    /// `endGroup` can compute the group's bounding rect.
    group_stack: BoundedStack(GroupState, 8) = .{},

    // ---- popup state
    // Popups are mini-windows: they reuse the existing `Window`
    // struct (persistent state in `ctx.windows`, same draw list +
    // cursor pipeline) but draw chrome differently (no title bar,
    // border + bg only) and replay AFTER regular windows so they
    // overlay parent content.
    // Open/closed state survives across frames in `popup_open`,
    // keyed by hashed popup id (parent_window_id ++ str_id).
    // `frame_popups` is the per-frame replay list; `popup_stack`
    // tracks currently-active popups during submission so
    // `closeCurrentPopup` can target the top.

    /// Open popups, keyed by their hashed id. Entries live across
    /// frames; deleted on user dismiss (click outside, click on a
    /// menu item, `closeCurrentPopup`).
    popup_open: std.AutoHashMapUnmanaged(Id, PopupState) = .{},
    /// Popups submitted this frame, in submission order. Replayed
    /// in `endFrame` AFTER `frame_windows` so popups overlay regular
    /// windows. Cleared each `beginFrame`.
    frame_popups: BoundedStack(*Window, 8) = .{},
    /// IDs of currently-active popups during submission - the top is
    /// the innermost popup that `closeCurrentPopup` would close.
    popup_stack: BoundedStack(Id, 8) = .{},

    // ---- main menu bar state
    // The main menu bar is a synthetic always-on "window" rendered
    // on the foreground draw list at the top of the canvas. Its
    // layout cursor advances horizontally as the user submits
    // `beginMenu("File")` etc. Menus inside are popups anchored
    // immediately below their button.

    /// True between `beginMainMenuBar` and `endMainMenuBar`. Widgets
    /// like `beginMenu` check this to know whether to lay out
    /// horizontally (in-bar) vs vertically (in-popup).
    /// True while inside `beginMainMenuBar`/`endMainMenuBar` OR
    /// `beginMenuBar`/`endMenuBar` (per-window). Read by `openMenu`
    /// so menu items can be submitted only inside a bar. The
    /// concrete coordinates (cursor x, origin y, bottom y) live on
    /// ctx and get re-anchored on each bar's open.
    in_menu_bar: bool = false,
    /// Synthetic Window* used by the main menu bar. Allocated lazily
    /// the first time `beginMainMenuBar` runs; reused thereafter.
    main_menu_bar_win: ?*Window = null,
    /// The window whose menu bar is currently active. For
    /// `beginMainMenuBar` this is `main_menu_bar_win` (the synthetic
    /// bar window). For `beginMenuBar` this is the parent window
    /// (the bar is drawn into the parent's pixels). Read by
    /// `openMenu` so it knows where to draw bar buttons / anchor
    /// popups regardless of which path opened the bar.
    active_menu_bar_win: ?*Window = null,
    /// X cursor inside the menu bar - incremented by each
    /// `beginMenu` button. Reset at every `beginMainMenuBar`.
    menu_bar_cursor_x: f32 = 0,
    /// Bottom-y of the menu bar (used by `beginMenu` to anchor its
    /// popup just below the button).
    menu_bar_bottom_y: f32 = 0,
    /// The ONE menu currently open across the menu bars (single-open). The bar's
    /// open INTENT; `popup_open` holds the live popup. null = no menu open.
    bar_open_menu: ?Id = null,
    /// Button rect of the open menu (last frame), so click-outside dismissal can
    /// tell a toggle-click on the button from a genuine outside click.
    bar_open_menu_btn: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 },

    // ---- tab bar state
    // Persistent state keyed by the bar's hashed `str_id` (so two
    // bars with different ids in the same window are independent).
    // Per-frame transient state lives on `tab_bar_stack`, pushed
    // by `beginTabBar` and popped by `endTabBar`.

    /// Persistent per-tab-bar state - selected tab survives frames.
    tab_bar_state: std.AutoHashMapUnmanaged(Id, TabBarState) = .{},
    /// Active tab bars during submission. Cap 4 - nesting tab
    /// bars more than 4 deep is a likely caller bug.
    tab_bar_stack: BoundedStack(TabBarFrame, 4) = .{},

    // Typed-generic per-extension state. Each call to
    // `getOrPutState(T, id, opts)` resolves through here: the outer
    // map is keyed by `@typeName(T)`'s hash and points at a
    // `*AutoHashMapUnmanaged(Id, T)` allocated lazily on the first
    // access for that type. Types never accessed cost nothing.
    //

    // Why type-erased outer pointer (`*anyopaque`) instead of a
    // tagged union? Comptime-known type set isn't viable —
    // extensions are user code that imports `zimr`, so the type
    // set is unknown to zimr at its own compile time. Type
    // erasure + comptime cast on every access gives us a closed
    // loop where the user-facing API is fully type-safe at each
    // call site even though the storage itself is `*anyopaque`.
    //

    // Cleanup: each typed inner map's deinit is registered when
    // the map is created (lazily), keyed by the type-hash.
    // UiContext teardown walks the outer map, calls each
    // registered deinit fn through a function-pointer, then frees
    // the outer map. No leaks even if the user never explicitly
    // clears state.
    ext_storage: std.AutoHashMapUnmanaged(u64, ExtStorageSlot) = .empty,

    // Bounded stack of translate+scale 2D affine transforms.
    // Lives on the context (not on CanvasCtx) because CanvasCtx
    // is returned by-value from beginCanvas; mutating state has
    // to live somewhere stable. One stack shared across canvases
    // is fine for now — nested canvases are an extension worth
    // explicitly designing if/when a real use case shows up.
    //

    // Each entry encodes a 2D affine: a point P in child space
    // becomes P * scale + translate in parent space. Compose:
    // when push happens, the new top is computed by composing
    // the incoming (t, s) with the previous top. Pop just shrinks.
    canvas_transforms: BoundedStack(CanvasTransform, 16) = .{},

    // ---- MultiSelect scope plumbing
    // Three fields wire multi-select into the context:
    //   1. `ms_storage` - persistent per-scope state, keyed by the
    //      scope's id (window-id-stack-top at Begin time). Survives
    //      frames; GC'd via `last_frame_active`. Matches imgui's
    //      `g.MultiSelectStorage`.
    //   2. `current_multi_select` - transient single-slot for the
    //      in-progress Begin/End pair. `null` outside a scope.
    //      Single-slot is the MVP decision;
    //      nested scopes are deferred (see imgui-plan.md deferred
    //      section).
    //   3. `next_item_selection_user_data` - the value most recently
    //      passed to `setNextItemSelectionUserData`; consumed (and
    //      cleared) by the next widget that calls into the
    //      item-side multi-select hooks. Imgui:
    //      `g.NextItemData.SelectionUserData` - note: imgui stores
    //      this regardless of whether a scope is active (so widgets
    //      can pre-tag for future scopes); we follow the same
    //      pattern (`imgui_widgets.cpp:8208-8226`).

    /// Persistent per-scope state, keyed by scope id. Imgui:
    /// `g.MultiSelectStorage`.
    ms_storage: std.AutoHashMapUnmanaged(Id, MultiSelectState) = .{},
    /// In-progress scope, or null. Set by `beginMultiSelect`,
    /// cleared by `endMultiSelect`.
    current_multi_select: ?MultiSelectScope = null,
    /// Pending user-data tag for the next widget. Set by
    /// `setNextItemSelectionUserData`; consumed by the next
    /// widget's item-side hooks. Stored regardless of whether
    /// a scope is active (matches imgui).
    next_item_selection_user_data: ?u64 = null,

    // ---- scalar-input scratch buffer
    // `inputFloat`/`inputInt` operate on caller-owned numeric
    // pointers (`*f32`, `*i32`). While the user is typing, we need
    // a string buffer to hold the edit; on commit we parse it back
    // to T. This is the buffer. Only the currently-focused
    // scalar-input (matched by `active_id`) reads/writes it.

    /// Scratch text buffer for the active scalar input. Seeded with
    /// the current value formatted via `opts.fmt` on focus-gain.
    scalar_edit_buf: [64]u8 = @splat(0),
    /// Used length of `scalar_edit_buf`.
    scalar_edit_len: usize = 0,

    pub fn init(gpa: Allocator) UiContext {
        return .{
            .gpa = gpa,
            .frame_arena = FrameArena.init(gpa, ui_frame_arena_ceiling, "ui"),
        };
    }

    pub fn deinit(self: *UiContext) void {
        // Tear down the persistent maps first. DrawList memory
        // (cmds + payload slices) is all owned by `frame_arena`,
        // so DrawList.deinit is a no-op - `frame_arena.deinit()`
        // below releases it all at once.
        var it: @TypeOf(self.windows.iterator()) = self.windows.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.draw_list.deinit(self.frame_arena.allocator());
            self.gpa.destroy(entry.value_ptr.*);
        }
        self.windows.deinit(self.gpa);
        self.tree_open_state.deinit(self.gpa);
        self.popup_open.deinit(self.gpa);
        // TabBarState owns an ArrayList of TabState; deinit
        // each before freeing the bar HashMap itself.
        var tb_it: @TypeOf(self.tab_bar_state.iterator()) = self.tab_bar_state.iterator();
        while (tb_it.next()) |entry| {
            entry.value_ptr.deinit(self.gpa);
        }
        self.tab_bar_state.deinit(self.gpa);
        self.table_sort_state.deinit(self.gpa);
        self.table_scroll_state.deinit(self.gpa);
        self.table_width_auto_cache.deinit(self.gpa);

        // Tear down the typed-generic ext storage. Each entry's
        // `deinit_fn` was captured at first-put time when `T` was
        // comptime-known; we call it through the function pointer
        // to deinit + free the typed inner map. The outer map
        // then releases its own backing.
        var ext_it: @TypeOf(self.ext_storage.iterator()) = self.ext_storage.iterator();
        while (ext_it.next()) |entry| {
            entry.value_ptr.deinit_fn(entry.value_ptr.map, self.gpa);
        }
        self.ext_storage.deinit(self.gpa);
        // release pending persistence entries.
        // Their owned `name` allocations are freed via `clearPending`;
        // the map's own backing capacity then goes away here. Same
        // pattern for the tab-bar staging map.
        clearPending(self);
        self.pending_persistence.deinit(self.gpa);
        self.pending_tab_bar_selections.deinit(self.gpa);
        // release the staged dock tree
        // if persistence loaded one but no dockSpace() was
        // ever submitted to drain it.
        freePendingDockTree(self.gpa, self);
        // docking pool tear-down. Frees every
        // allocated DockNode plus the per-frame bookkeeping lists.
        self.dock.deinit(self.gpa);
        // multi-select scope plumbing.
        self.ms_storage.deinit(self.gpa);
        if (self.current_multi_select) |*scope| {
            scope.requests_buf.deinit(self.gpa);
        }
        // foreground_dl's cmds live on the frame arena - its deinit
        // is effectively a no-op because the arena will free all
        // its pages on the next line. Pass the frame arena's
        // allocator for API symmetry.
        self.foreground_dl.deinit(self.frame_arena.allocator());
        self.background_dl.deinit(self.frame_arena.allocator());
        // Tooltip window (lazily allocated) - free if it was ever
        // created. Its draw list lives on the arena so deinit is
        // a no-op for the cmds list itself.
        if (self.tooltip_window) |tw| {
            tw.draw_list.deinit(self.frame_arena.allocator());
            self.gpa.destroy(tw);
            self.tooltip_window = null;
        }
        if (self.drag_preview_window) |dw| {
            dw.draw_list.deinit(self.frame_arena.allocator());
            self.gpa.destroy(dw);
            self.drag_preview_window = null;
        }
        self.frame_arena.deinit();
    }

    /// Test-friendly form of `beginFrame` that takes pre-built
    /// snapshot + dims + GL primitives directly, skipping the
    /// `*Frame` plumbing. Inline tests use this so they don't
    /// have to construct a fake `Frame` (with all its loader /
    /// clock / rng / log vtables). Production code uses
    /// `beginFrame`; this is the underlying body.
    pub fn beginFrameRaw(
        self: *UiContext,
        snapshot: InputSnapshot,
        input_state: ?*runtime.input.InputState,
        canvas_w: u32,
        canvas_h: u32,
        gl: *Gl,
        shapes_state: *const shapes2d.ShapesTextureState,
        font_cache: *const text2d.FontCache,
    ) Ui {
        self.input = snapshot;
        self.input_state = input_state;
        self.canvas_w = canvas_w;
        self.canvas_h = canvas_h;
        self.frame_gl = gl;
        self.frame_shapes_state = shapes_state;
        self.frame_font_cache = font_cache;
        // on the very first beginFrame after
        // a fresh UiContext, attempt to load persisted window state
        // from localStorage. No-op on host builds and when no
        // `persistence_key` is set. After this call the pending
        // map is populated; the first `findOrCreateWindow` for each
        // persisted name will graft pos/size before opts.initial_*
        // takes effect.
        if (self.frame_count == 0) {
            tryAutoLoad(self);
        }
        self.frame_count += 1;
        // clear per-frame dockspace tracking.
        // Apps using docking re-submit their `dockSpace(...)` widgets
        // each frame; the list captures submissions for drag-drop
        // hit-testing (5.5e). Reset before the user's submissions
        // begin. No-op for apps that don't use docking.
        self.dock.dockspaces_this_frame.clearRetainingCapacity();

        // monotonic UI clock for repeat /
        // hover-delay timing. Reads from the snapshot's delta_time
        // (which beginFrame sets from `f.time.delta_time`). Independent
        // of wall clock - only advances when the ui ticks.
        self.frame_time_seconds += snapshot.delta_time;
        // Tick the shared gesture detector once per frame so widgets can
        // read pinch/drag/swipe off the UI handle. No-op without input.
        if (self.input_state) |istate| {
            var gt: runtime.core.TimeState = .{ .current = self.frame_time_seconds };
            runtime.gestures.update(&self.gestures, istate, &gt);
        }

        // First-frame misconfig diagnostic. The single most-common
        // way to ship a demo that renders BLANK widgets is to bump
        // `style.font_size` (e.g. for phone readability) and forget
        // to also point `style.font` at a loaded TTF. Without a TTF
        // bound, text routes through the bitmap-glyph fallback path,
        // which assumes its built-in 10-px size - bumping font_size
        // tells the layout code to reserve more space, but the actual
        // glyph quads come out at the wrong scale (or simply invisible
        // at common sizes like 16/18/20).
        // We can't physically prevent this - `Style` is a plain struct
        // and Zig has no setters. Instead, on the first frame, we
        // check the misconfig pattern and emit a single diagnostic to
        // stderr (which surfaces as `console.error` in the browser)
        // explaining the exact fix. Fires once per UiContext lifetime
        // so a misconfigured demo doesn't spam the console.
        // Tripped of the imgui-port arc, hence the
        // very specific message.
        // Stay silent under `zig build test`.  Most UI tests use
        // `beginFrameRaw` with no font loaded — and now that the
        // desktop-default `font_size` is 16 (not 10), every such
        // test trips this warning, drowning the test output in
        // hundreds of identical messages.  The warning is for
        // app authors who hit the misconfig live, not for the
        // test harness.  `builtin.is_test` is comptime so the
        // check vanishes from non-test builds.
        if (comptime !builtin.is_test) {
            // Only a genuine misconfig: font_size was bumped off the bitmap-
            // fallback size (10) AND there is no usable font for this frame —
            // neither a `style.font` (the GL mechanism) NOR a loaded
            // `font_cache` (the wgpu `UiHost` mechanism, which supplies the
            // TTF via this very call). Without the font_cache check this fired
            // on EVERY correctly-configured UiHost app, whose `style.font` is
            // legitimately null because the font rides in `font_cache`.
            const has_font: bool = self.style.font != null or font_cache.loaded;
            if (self.frame_count == 1 and !has_font and self.style.font_size != 10) {
                // Route through std.log (-> std_options.logFn -> js_log on wasm),
                // NOT std.debug.print: the latter writes to the raw stderr writer,
                // whose wasm path traps under ReleaseSmall (silent freeze in a
                // release standalone). std.log is the safe, browser-visible path.
                std.log.warn(
                    "zimr: style.font_size is {d:.1} but no font is loaded " ++
                        "(style.font is null and no TTF FontCache was supplied). " ++
                        "Text will render BLANK or at the wrong scale (bitmap " ++
                        "fallback only handles size 10). Fix: load a TTF — wgpu " ++
                        "UiHost: pass it to `z.UiHost.init(gpa, try z.loadFont(f, " ++
                        "gpa, ttf_bytes, size))`; GL: `try z.loadFontDefault(gpa, " ++
                        "&s.font_cache)` AND set `s.ui_ctx.style.font = &s.font_cache.font`.",
                    .{self.style.font_size},
                );
            }
        }
        self.hovered_id_prev_frame = self.hovered_id;
        self.hovered_id = 0;
        self.mouse_wheel_consumed = false;
        self.mouse_wheel_x_consumed = false;
        self.current_window = null;
        self.window_stack = .{};
        self.id_stack = .{};
        self.active_id_just_activated = false;
        self.pending_tooltip = null;
        self.tooltip_active_this_frame = false;
        self.drag_preview_active_this_frame = false;

        // ---- /b: drag-drop state machine
        // opens drags via.idle→.pending→.active.
        // needs the payload to remain readable on the frame the user
        // releases the mouse so targets can accept it during update().
        // That means.active→.idle cleanup runs at endFrame, NOT here.
        // Here we only handle.pending: if the user releases before
        // crossing the drag threshold, cancel; if movement crosses it,
        // promote to.active.
        switch (self.drag_drop.phase) {
            .idle => {},
            .pending => {
                if (!self.input.mouse_left_down) {
                    // Click released before threshold crossed → cancel.
                    self.drag_drop.phase = .idle;
                } else {
                    const dx: f32 = self.input.mouse_pos[0] - self.drag_drop.drag_start_pos[0];
                    const dy: f32 = self.input.mouse_pos[1] - self.drag_drop.drag_start_pos[1];
                    if (dx * dx + dy * dy >= DragDropState.DRAG_THRESHOLD * DragDropState.DRAG_THRESHOLD) {
                        self.drag_drop.phase = .active;
                        debugLogPush(
                            self,
                            .drag_started,
                            "source_id={x}",
                            .{self.drag_drop.source_widget_id},
                        );
                    }
                }
            },
            .active => {
                // Cleanup deferred to endFrame so this frame's target
                // accepts can read the payload.
            },
        }
        // Reset the per-frame "inside a target scope" pointer; widgets
        // may set it during this frame's submission via
        // beginDragDropTarget.
        self.drag_drop.target_widget_id = 0;

        // ---- keyboard nav advance
        // Process Tab from the PREVIOUS frame's submitted nav items.
        // Forward (just Tab) advances to the next item; backward
        // (Shift+Tab) steps to the previous. Wraps at both ends. If
        // nav_id isn't in the current list (e.g. focused widget went
        // away), focus the first item. Done BEFORE clearing the list,
        // then we clear so this frame's submissions can repopulate.
        if (self.input.keys[@backingInt(KeyCode.tab)].pressed_this_frame) {
            advanceNav(self);
        }
        self.frame_nav_items.clear();

        // Surface stack always starts empty each frame - implicit
        // canvas surface. If user pushes RTs and forgets to pop,
        // they bleed into the next frame's main render; we'd rather
        // detect that than silently mask it.
        self.surface_stack.clear();

        // Reset draw list state. Foreground draw list cleared (fresh
        // tooltips / popups each frame). Per-window draw lists are
        // cleared in openWindow when the user resubmits the window;
        // windows not submitted this frame retain last frame's
        // contents but won't be replayed (they're not in frame_windows).
        self.foreground_dl.clear();
        self.dock_tabs_dl.clear();
        self.background_dl.clear();
        // NOTE: `prev_window_rects` is deliberately NOT cleared here — it holds
        // last frame's snapshot, taken in `endFrame` while those windows were
        // still alive. Rebuilding it here instead would mean dereferencing
        // `frame_windows`' `*Window`s a frame later, which can dangle.
        self.frame_windows.clear();
        self.frame_popups.clear();
        self.popup_stack.clear();
        // Reclaim the previous frame's per-frame allocations. Every `add*` call
        // dupes its payload (polyline points, triangle fans, text glyph slices)
        // into `frame_arena`, and the DrawList `cmds` lists are duped here too;
        // all of it is consumed by `uiRenderNow` during the previous frame's
        // render and is dead by the time we reach the next beginFrame. The
        // DrawList docs and `clear()` (which zeros to `.empty` rather than
        // `clearRetainingCapacity`) are written precisely around this reset —
        // without it the arena grew ~one frame's draw payload every frame
        // (≈2 MB/frame in the heaviest 2D scenes), eventually exhausting wasm
        // linear memory.
        //
        // Before freeing the pages, EVERY persistent draw list must be emptied:
        // a window (or the tooltip / drag-preview window) not resubmitted this
        // frame would otherwise keep a `cmds.items.ptr` into reclaimed pages.
        // foreground/background/dock_tabs were just cleared; do the rest here.
        // `.clear()` abandons the stale slice (→ `.empty`); resubmitted windows
        // refill from the fresh arena via openWindow. `.retain_capacity` keeps
        // the backing pages so we don't re-grow wasm memory each frame.
        var win_it: @TypeOf(self.windows.iterator()) = self.windows.iterator();
        while (win_it.next()) |entry| {
            entry.value_ptr.*.draw_list.clear();
        }
        if (self.tooltip_window) |tw| {
            tw.draw_list.clear();
        }
        if (self.drag_preview_window) |dw| {
            dw.draw_list.clear();
        }
        _ = self.frame_arena.reset(.retain_capacity);
        self.current_draw_list = null;
        self.eager_mode = false;
        // dismiss any open popups whose rects don't contain
        // a click that fired this frame. Done at frame start so the
        // user's update() callback sees the correct popup_open state.
        dismissPopupsOnClickOutside(self);

        return Ui{ .ctx = self };
    }

    /// Finalize the frame WITHOUT rendering (no deferred GL queue). For
    /// single-pass backends (WebGPU): call this, then uiRenderNow(gl, ...)
    /// directly. Does everything endFrame does EXCEPT append to
    /// gl.pending_renders — the tooltip flush, dock-tab emission, and metrics,
    /// so the draw lists are in their final per-frame state for the immediate
    /// replay.
    pub fn endFrameNoRender(self: *UiContext) void {
        self.next_widget_take_focus = false;
        // Snapshot this frame's window RECTS while the `*Window`s are still
        // alive and their layout is final. `wantCaptureMouse` hit-tests this as
        // a fallback next frame, so it answers correctly even when called BEFORE
        // that frame's windows have been submitted — which is the natural way to
        // write an update (gate the camera/scene input, THEN draw the UI).
        // Without it, an early call sees an empty `frame_windows`, returns false,
        // and the pointer "clicks through" the panel: tapping a button also drags
        // the scene underneath it. Dear ImGui has the same semantics
        // (WantCaptureMouse reflects the previous frame's layout). Rects (not
        // pointers) are stored, so a window destroyed before the next frame can't
        // dangle.
        self.prev_window_rects.clear();
        for (self.frame_windows.items[0..self.frame_windows.len]) |w| {
            self.prev_window_rects.append(.{
                .x = w.pos[0],
                .y = w.pos[1],
                .width = w.size[0],
                .height = w.size[1],
            }) catch assertUnreachable(@src(), "OOM", .{});
        }
        // Apply queued dock operations (drag-dock / undock / split) and sync the
        // window-side link. THIS is the only end-of-frame path the wgpu UiHost
        // takes (endFrame() is the GL/host path) — without these two lines,
        // drag-to-dock requests were enqueued by the release handler and never
        // drained, so nothing ever docked at runtime.
        processRequests(&self.dock, self.gpa) catch assertUnreachable(@src(), "OOM", .{});
        syncDockedWindowIds(self);
        bringFocusedFloatingToFront(self);
        if (self.pending_tooltip) |t| {
            const saved: ?*DrawList = self.current_draw_list;
            self.current_draw_list = &self.foreground_dl;
            renderTooltip(self, t);
            self.current_draw_list = saved;
        }
        flushDockTabsToForeground(self);
        metricsCollectAtEndFrame(self);
        metricsResetRenderCounters(self);
        metricsAccumulateDrawList(self, &self.background_dl);
        for (self.frame_windows.items[0..self.frame_windows.len]) |w| {
            metricsAccumulateDrawList(self, &w.draw_list);
        }
        for (self.frame_popups.items[0..self.frame_popups.len]) |p| {
            metricsAccumulateDrawList(self, &p.draw_list);
        }
        metricsAccumulateDrawList(self, &self.foreground_dl);
    }
};

// ============================================================================
// Widget: TextFilter - substring include/exclude filter
// ============================================================================
// Maps `ImGuiTextFilter` 1:1. Holds a small input buffer the user
// types filter terms into (e.g. `"error,-test"`), parses it into
// include/exclude segments, and offers `passFilter(text)` so the
// caller can decide per-line whether to render.
// Syntax (matches imgui exactly, see imgui.cpp `PassFilter`):
//   "foo" → include: pass anything containing "foo"
//   "foo,bar" → include union: pass anything containing "foo" OR "bar"
//   "-foo" → exclude: drop anything containing "foo"
//   "foo,-bar" → first match wins (order matters in imgui too):
//                     "foo bar" passes via the "foo" include before
//                     "-bar" is ever consulted. This is imgui's
//                     intentional behaviour; we match it for parity.
// Empty filter passes everything. All-exclude filter passes anything
// not excluded. Case-insensitive matching (ASCII only - matches
// imgui's `ImStristr`).
// Storage caps (256 buffer / 16 segments) match imgui's
// `InputBuf[256]` and the practical max grep count. Both are tunable
// at compile time via the pub constants.

inline fn isAsciiBlank(c: u8) bool {
    return c == ' ' or c == '\t';
}

inline fn asciiLower(c: u8) u8 {
    return if (c >= 'A' and c <= 'Z') c + ('a' - 'A') else c;
}

/// Case-insensitive ASCII substring search. Returns true if
/// `haystack` contains `needle` ignoring case on `[A-Za-z]`. Empty
/// needle matches everything (imgui-parity edge: callers in
/// `passFilter` never pass empty needles because `build` skipped
/// empty segments).
fn containsIgnoreCaseAscii(haystack: []const u8, needle: []const u8) bool {
    if (needle.len == 0) {
        return true;
    }
    if (needle.len > haystack.len) {
        return false;
    }
    // Slide along haystack looking for the start byte (case-insensitive).
    // Naive O(n*m); good enough for filter lengths (<<256).
    var i: usize = 0;
    while (i + needle.len <= haystack.len) : (i += 1) {
        var match: bool = true;
        var j: usize = 0;
        while (j < needle.len) : (j += 1) {
            if (asciiLower(haystack[i + j]) != asciiLower(needle[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            return true;
        }
    }
    return false;
}

pub const TextFilter = struct {
    pub const buf_capacity: usize = 256;
    pub const max_segments: usize = 16;

    /// Input buffer. Mutated directly by `inputText` inside `draw`.
    /// Always NUL-terminator-friendly (last byte reserved as 0).
    buf: [buf_capacity]u8 = @splat(0),
    /// Number of bytes used in `buf` (exclusive of any trailing 0).
    buf_len: usize = 0,

    /// Parsed segments. Each (start, len) is a slice into `buf`.
    /// `negate=true` marks an exclude (prefix `-` was present).
    segments: [max_segments]Segment = @splat(.{ .start = 0, .len = 0, .negate = false }),
    segment_count: usize = 0,
    /// Count of non-negated segments. When 0 (filter is empty or
    /// all-exclude), `passFilter` defaults to "pass" unless a
    /// negate hits.
    include_count: usize = 0,

    pub const Segment = struct {
        start: usize,
        len: usize,
        negate: bool,
    };

    /// Parse `buf[0..buf_len]` into `segments`. Idempotent; safe to
    /// call every frame. `draw` does this automatically when
    /// inputText reports a change.
    /// Algorithm matches imgui's `Build`: split on `,`, trim each
    /// piece's whitespace, skip empty pieces, mark `-`-prefixed pieces
    /// as negated (and trim the `-` off the segment slice itself).
    pub fn build(self: *TextFilter) void {
        self.segment_count = 0;
        self.include_count = 0;
        assertf(
            self.buf_len <= buf_capacity,
            @src(),
            "TextFilter.build: buf_len={d} exceeds capacity={d}",
            .{ self.buf_len, buf_capacity },
        );

        var i: usize = 0;
        while (i < self.buf_len) {
            // Find the next comma (or end).
            var end: usize = i;
            while (end < self.buf_len and self.buf[end] != ',') {
                end += 1;
            }

            // Trim leading whitespace.
            var s: usize = i;
            while (s < end and isAsciiBlank(self.buf[s])) {
                s += 1;
            }
            // Trim trailing whitespace.
            var e: usize = end;
            while (e > s and isAsciiBlank(self.buf[e - 1])) {
                e -= 1;
            }

            if (e > s) {
                var neg: bool = false;
                if (self.buf[s] == '-') {
                    neg = true;
                    s += 1;
                    // Re-trim leading whitespace after the '-' - imgui's
                    // implementation doesn't, but accepting "- foo" feels
                    // more forgiving and matches no test we'd otherwise
                    // be reproducing. Cheap +5 LOC, more humane.
                    while (s < e and isAsciiBlank(self.buf[s])) {
                        s += 1;
                    }
                }
                if (e > s and self.segment_count < max_segments) {
                    self.segments[self.segment_count] = .{
                        .start = s,
                        .len = e - s,
                        .negate = neg,
                    };
                    self.segment_count += 1;
                    if (!neg) {
                        self.include_count += 1;
                    }
                }
            }

            // Advance past the comma.
            i = end + 1;
        }
    }

    /// True if `text` should be displayed under the current filter.
    /// Empty filter → always true. Otherwise iterates segments in
    /// input order; first matching include returns true, first
    /// matching exclude returns false. If no include ever matches
    /// AND at least one include is defined, returns false (default-
    /// deny once includes are present). Matches imgui exactly.
    pub fn passFilter(self: *const TextFilter, text: []const u8) bool {
        if (self.segment_count == 0) {
            return true;
        }

        var k: usize = 0;
        while (k < self.segment_count) : (k += 1) {
            const seg: Segment = self.segments[k];
            assertf(
                seg.start + seg.len <= self.buf_len,
                @src(),
                "TextFilter.passFilter: segment {d} range {d}+{d} exceeds buf_len={d}",
                .{ k, seg.start, seg.len, self.buf_len },
            );
            const needle: []const u8 = self.buf[seg.start .. seg.start + seg.len];
            const hit: bool = containsIgnoreCaseAscii(text, needle);
            if (seg.negate) {
                if (hit) {
                    return false;
                }
            } else {
                if (hit) {
                    return true;
                }
            }
        }
        // No include matched. If includes existed at all, default-deny.
        // If only excludes existed (or nothing), default-allow.
        return self.include_count == 0;
    }

    /// True if any segment is parsed (filter does something).
    pub fn isActive(self: *const TextFilter) bool {
        return self.segment_count > 0;
    }

    /// Reset to empty buffer + zero segments.
    pub fn clear(self: *TextFilter) void {
        self.buf = @splat(0);
        self.buf_len = 0;
        self.segment_count = 0;
        self.include_count = 0;
    }

    /// Render the filter's input box and re-parse on any change.
    /// Returns true if the filter (and therefore which lines pass)
    /// changed this frame - callers may use that to invalidate
    /// caches. `label` and `hint` follow imgui's
    /// `Draw("Filter (inc,-exc)")` convention; `hint` is shown
    /// inside the empty input so users discover the syntax.
    pub fn draw(
        self: *TextFilter,
        ui_handle: Ui,
        label: []const u8,
        hint: []const u8,
    ) bool {
        const changed: bool = ui_handle.inputTextWithHint(
            label,
            hint,
            &self.buf,
            &self.buf_len,
            .{},
        );
        if (changed) {
            self.build();
        }
        return changed;
    }
};

test "TextFilter - empty buffer passes everything" {
    var f: TextFilter = .{};
    f.build();
    try expect(f.passFilter("anything"));
    try expect(f.passFilter(""));
    try expect(!f.isActive());
}

test "TextFilter - single include" {
    var f: TextFilter = .{};
    const term: []const u8 = "error";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expectEqual(@as(usize, 1), f.segment_count);
    try expectEqual(@as(usize, 1), f.include_count);
    try expect(f.passFilter("ERROR: boom")); // case-insensitive
    try expect(f.passFilter("an error here"));
    try expect(!f.passFilter("warning"));
}

test "TextFilter - single exclude" {
    var f: TextFilter = .{};
    const term: []const u8 = "-test";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expectEqual(@as(usize, 1), f.segment_count);
    try expectEqual(@as(usize, 0), f.include_count);
    try expect(!f.passFilter("running test foo"));
    try expect(f.passFilter("plain log line"));
    // segment stored with negate=true and the '-' trimmed off:
    try expectEqual(true, f.segments[0].negate);
    try expectEqualSlices(
        u8,
        "test",
        f.buf[f.segments[0].start .. f.segments[0].start + f.segments[0].len],
    );
}

test "TextFilter - multi-segment union semantics" {
    var f: TextFilter = .{};
    const term: []const u8 = "error,warn";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expectEqual(@as(usize, 2), f.segment_count);
    try expect(f.passFilter("ERROR: x"));
    try expect(f.passFilter("warning"));
    try expect(!f.passFilter("info"));
}

test "TextFilter - include + exclude, order matters" {
    var f: TextFilter = .{};
    const term: []const u8 = "error,-test";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    // "error in test.zig" - "error" include hits FIRST, returns true.
    // (Imgui's documented behaviour - order matters.)
    try expect(f.passFilter("error in test.zig"));
    // "warning in test.zig" - "error" misses, "-test" hits, false.
    try expect(!f.passFilter("warning in test.zig"));
    // Plain unrelated text: "error" misses, "-test" misses, but
    // include_count > 0 → default-deny.
    try expect(!f.passFilter("info plain"));
}

test "TextFilter - whitespace trim around segments" {
    var f: TextFilter = .{};
    const term: []const u8 = "  foo  , -  bar  ";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expectEqual(@as(usize, 2), f.segment_count);
    // Segment 0: "foo", not negated.
    try expectEqualSlices(u8, "foo", f.buf[f.segments[0].start .. f.segments[0].start + f.segments[0].len]);
    try expectEqual(false, f.segments[0].negate);
    // Segment 1: "bar", negated. Note the "- bar " - the leading
    // dash, then whitespace, then bar. We trim both.
    try expectEqualSlices(u8, "bar", f.buf[f.segments[1].start .. f.segments[1].start + f.segments[1].len]);
    try expectEqual(true, f.segments[1].negate);
}

test "TextFilter - empty segments dropped" {
    var f: TextFilter = .{};
    const term: []const u8 = ",,foo,,";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expectEqual(@as(usize, 1), f.segment_count);
}

test "TextFilter - clear" {
    var f: TextFilter = .{};
    const term: []const u8 = "err";
    @memcpy(f.buf[0..term.len], term);
    f.buf_len = term.len;
    f.build();
    try expect(f.isActive());
    f.clear();
    try expect(!f.isActive());
    try expect(f.passFilter("anything"));
    try expectEqual(@as(usize, 0), f.buf_len);
}

/// The handle the user holds. Cheap value type - 8 bytes (single
/// pointer). All real state lives in the pointed-to UiContext.
/// Sits at `Frame.ui`.
/// A frame's pinch state, returned by `Ui.pinch()`. `scale` is the
/// frame-to-frame two-finger distance ratio (1.0 = no pinch); `mid` is
/// the screen-space focal point to hold fixed while zooming.
pub const Pinch = struct {
    scale: f32 = 1,
    mid: Vec2 = .{ 0, 0 },
};

/// The gesture the shared detector classified this frame (tap, doubletap,
/// hold, drag, swipe_*, pinch_*). Read via `Ui.gesture()`.
pub const Gesture = runtime.gestures.Gesture;

pub const WindowOpts = struct {
    /// Initial position when the window is first created. After
    /// that, the persistent position is used. Pass null to use the
    /// auto-tile default.
    initial_pos: ?Vec2 = null,
    /// Initial size when the window is first created.
    initial_size: Vec2 = .{ 320, 200 },
    /// Flag set controlling chrome suppression + future behaviors.
    /// See `WindowFlags` for the full menu. shipped
    /// the six chrome-suppression flags; P5.2+ extend this.
    flags: WindowFlags = .{},
};

/// Effective title-bar height for `w` — `style.title_bar_height`
/// when the window has a title bar, `0` when `flags.no_title_bar`
/// is set. Use at every layout site that subtracts/adds the title
/// bar's vertical contribution: content cursor origin, viewport
/// height, scroll clip, content-natural-height in auto-expand.
fn effectiveTitleBarHeight(ctx: *const UiContext, w: *const Window) f32 {
    if (w.flags.no_title_bar) {
        return 0;
    }
    return ctx.style.title_bar_height;
}

/// Compute a widget's ID by hashing `label` against the current ID
/// scope. The scope is the top of `ctx.id_stack` if any
/// `pushId`/`pushIdInt` is active, otherwise the current window's
/// ID. ALL widget impls should use this rather than calling
/// `hashStr(w.id, label)` directly - the difference matters when
/// the caller wraps a loop in `pushIdInt(i)` to disambiguate IDs
/// across iterations (e.g. `editArrayList`'s per-element delete
/// buttons).
pub fn widgetId(
    ctx: *UiContext,
    w: *Window,
    label: []const u8,
) Id {
    const seed: Id = ctx.id_stack.top() orelse w.id;
    return hashStr(seed, label);
}

/// Vertical scrollbar - track + draggable thumb on the right edge of
/// the window. minimum: thumb-drag and mouse-wheel both
/// update `w.scroll_y`; track-clicks (jump to position) are deferred.
/// Rendered LAST in `closeWindow` so it overlays content; ID hashed
/// from the window's id so it's stable + unique across windows.
/// Vertical scrollbar - track + draggable thumb on the right edge
/// of the window's content area. Uses `w.layout.origin[1]` /
/// `w.layout.work_rect_max[1]` for the track's vertical bounds so
/// the same function works for both top-level windows (where
/// `origin.y = pos.y + title_bar + padding`) and child windows
/// (where `origin.y = pos.y + opts.padding`) without branching.
/// Caller responsibility:
///   - Must be called AFTER the content clip rect is popped (so
///     the scrollbar isn't clipped out alongside the content).
///   - Must verify `scroll_max_y > 0` before calling - a window
///     with content that fits doesn't need a scrollbar.
///   - The window's `scroll_y` is mutated in-place if the user
///     drags the thumb.
fn renderScrollbar(ctx: *UiContext, w: *Window) void {
    const scrollbar_w: f32 = 10;
    const track_x: f32 = w.pos[0] + w.size[0] - scrollbar_w - 2;
    const track_y: f32 = w.layout.origin[1];
    const track_h: f32 = @max(0, w.layout.work_rect_max[1] - w.layout.origin[1]);
    if (track_h <= 0 or w.scroll_max_y <= 0) {
        return;
    }
    // Visible viewport height == track height (the scrollbar
    // overlays the visible content area exactly). Content height
    // is the scrollable extent: viewport + scroll_max.
    const viewport_h: f32 = track_h;
    const content_h: f32 = viewport_h + w.scroll_max_y;

    // Thumb size proportional to viewport/content ratio; clamped
    // to a minimum of 16 px so a deeply overflowing window still
    // has a grabbable thumb.
    const min_thumb: f32 = 16;
    const ratio: f32 = clamp(viewport_h / content_h, 0, 1);
    const thumb_h: f32 = @max(min_thumb, ratio * track_h);
    // Thumb position interpolates linearly from scroll_y / scroll_max.
    const t: f32 = if (w.scroll_max_y > 0) w.scroll_y / w.scroll_max_y else 0;
    const thumb_y: f32 = track_y + t * (track_h - thumb_h);

    // ---- Hit-test + drag --------------------------------------------
    // Visible thumb is `scrollbar_w` (10 px) wide — fine for mouse,
    // far below the ~44–48 px touch-target minimum.  Hit-test rect
    // inflates leftward (into content area) by `touch_inflate` so a
    // fingertip landing in a ~32-px-wide band to the left of the
    // bar still registers.  Leftward only — rightward would push
    // the hit region past the window's right edge.
    const touch_inflate: f32 = 22;
    const hit_rect: Rectangle = .{
        .x = track_x - touch_inflate,
        .y = thumb_y,
        .width = scrollbar_w + touch_inflate,
        .height = thumb_h,
    };
    const visual_thumb_rect: Rectangle = .{
        .x = track_x,
        .y = thumb_y,
        .width = scrollbar_w,
        .height = thumb_h,
    };
    const scroll_id: Id = widgetId(ctx, w, "##scroll_thumb");
    const mp: Vec2 = ctx.input.mouse_pos;
    const md: bool = ctx.input.mouse_left_down;
    const mp_in_thumb: bool = pointInRect(mp, hit_rect);

    if (md and ctx.active_id == 0 and mp_in_thumb) {
        ctx.active_id = scroll_id;
        ctx.active_id_just_activated = true;
        // Stash the thumb-y vs mouse-y delta so the thumb doesn't
        // jump on first drag frame.
        ctx.active_id_press_value = @floatCast(mp[1] - thumb_y);
    }
    if (ctx.active_id == scroll_id) {
        if (md) {
            const grab_dy: f32 = @floatCast(ctx.active_id_press_value);
            const new_thumb_y: f32 = mp[1] - grab_dy;
            const new_t: f32 = (new_thumb_y - track_y) / @max(1, track_h - thumb_h);
            w.scroll_y = clamp(new_t * w.scroll_max_y, 0, w.scroll_max_y);
        } else {
            ctx.active_id = 0;
        }
    }

    // ---- Render: track + thumb -------------------------------------
    drawRectFilled(
        ctx,
        .{ .x = track_x, .y = track_y, .width = scrollbar_w, .height = track_h },
        Color.toWire(ctx.style.scrollbar_bg),
    );
    const thumb_col: Color = if (ctx.active_id == scroll_id)
        ctx.style.scrollbar_grab_active
    else if (mp_in_thumb)
        ctx.style.scrollbar_grab_hovered
    else
        ctx.style.scrollbar_grab;
    drawRectFilled(
        ctx,
        visual_thumb_rect,
        Color.toWire(thumb_col),
    );
}

/// P5.5b: horizontal scrollbar — straight mirror of
/// `renderScrollbar`, rotated 90°. Track + draggable thumb on the
/// bottom edge of the window's content area. Same caller contract:
///   - Called AFTER content clip pop (so scrollbar isn't clipped).
///   - Caller must verify `scroll_max_x > 0` AND
///     `flags.horizontal_scrollbar` AND `!flags.no_scrollbar` before
///     calling — `closeWindow` enforces this.
///   - Mutates `w.scroll_x` in place on thumb drag.
fn renderScrollbarX(ctx: *UiContext, w: *Window) void {
    const scrollbar_h: f32 = 10;
    // Track sits on the bottom edge, just inside the border. Leave a
    // 12px gap on the right so the X bar doesn't visually collide
    // with the Y bar's track when both are shown.
    const corner_gap: f32 = if (w.scroll_max_y > 0) 12 else 2;
    const track_x: f32 = w.layout.origin[0];
    const track_y: f32 = w.pos[1] + w.size[1] - scrollbar_h - 2;
    const track_w: f32 = @max(0, (w.pos[0] + w.size[0] - corner_gap) - w.layout.origin[0]);
    if (track_w <= 0 or w.scroll_max_x <= 0) {
        return;
    }
    const viewport_w: f32 = track_w;
    const content_w: f32 = viewport_w + w.scroll_max_x;

    // Thumb size proportional to viewport/content; min 16px so a deep
    // overflow still leaves a grabbable handle.
    const min_thumb: f32 = 16;
    const ratio: f32 = clamp(viewport_w / content_w, 0, 1);
    const thumb_w: f32 = @max(min_thumb, ratio * track_w);
    const t: f32 = if (w.scroll_max_x > 0) w.scroll_x / w.scroll_max_x else 0;
    const thumb_x: f32 = track_x + t * (track_w - thumb_w);

    // ---- Hit-test + drag --------------------------------------------
    // The VISIBLE thumb is `scrollbar_h` (10 px) tall — fine for
    // mouse, far below the ~44–48 px touch-target minimum.  The
    // HIT-TEST rect inflates upward by `touch_inflate` so a
    // fingertip landing anywhere in a ~32-px-tall band above the
    // bar still registers as a thumb press.  Inflation is upward
    // only (into the content area) because downward would push the
    // hit region off the window's bottom edge or past the home
    // indicator on phones.  Desktop mouse hits the visual thumb
    // exactly as before; touch gains a much more forgiving target.
    const touch_inflate: f32 = 22;
    const hit_rect: Rectangle = .{
        .x = thumb_x,
        .y = track_y - touch_inflate,
        .width = thumb_w,
        .height = scrollbar_h + touch_inflate,
    };
    const visual_thumb_rect: Rectangle = .{
        .x = thumb_x,
        .y = track_y,
        .width = thumb_w,
        .height = scrollbar_h,
    };
    const scroll_id: Id = widgetId(ctx, w, "##scroll_thumb_x");
    const mp: Vec2 = ctx.input.mouse_pos;
    const md: bool = ctx.input.mouse_left_down;
    const mp_in_thumb: bool = pointInRect(mp, hit_rect);

    if (md and ctx.active_id == 0 and mp_in_thumb) {
        ctx.active_id = scroll_id;
        ctx.active_id_just_activated = true;
        // Stash thumb-x vs mouse-x delta so the thumb doesn't jump
        // on first drag frame. Reuse `active_id_press_x` for the
        // X stash (Y's drag uses `active_id_press_value`).
        ctx.active_id_press_x = mp[0] - thumb_x;
    }
    if (ctx.active_id == scroll_id) {
        if (md) {
            const grab_dx: f32 = ctx.active_id_press_x;
            const new_thumb_x: f32 = mp[0] - grab_dx;
            const new_t: f32 = (new_thumb_x - track_x) / @max(1, track_w - thumb_w);
            w.scroll_x = clamp(new_t * w.scroll_max_x, 0, w.scroll_max_x);
        } else {
            ctx.active_id = 0;
        }
    }

    // ---- Render: track + thumb --------------------------------------
    drawRectFilled(
        ctx,
        .{ .x = track_x, .y = track_y, .width = track_w, .height = scrollbar_h },
        Color.toWire(ctx.style.scrollbar_bg),
    );
    const thumb_col: Color = if (ctx.active_id == scroll_id)
        ctx.style.scrollbar_grab_active
    else if (mp_in_thumb)
        ctx.style.scrollbar_grab_hovered
    else
        ctx.style.scrollbar_grab;
    drawRectFilled(
        ctx,
        visual_thumb_rect,
        Color.toWire(thumb_col),
    );
}

fn closeWindow(ctx: *UiContext, w: *Window) void {
    // ---- Auto-fit window size to content (behaviour)
    // Only applies when the user hasn't manually resized AND hasn't
    // passed an explicit `setNextWindowSize`. Once `user_resized` is
    // true, content overflow shows a scrollbar instead of growing
    // the window - that's the entire point of giving it a size.
    // Note: `cursor_max` is in scrolled coordinates (it includes the
    // scroll_y shift applied at openWindow), so we add scroll_y back
    // to recover the un-shifted "natural" content extent.
    const inner_origin_y: f32 = w.pos[1] + effectiveTitleBarHeight(ctx, w) + ctx.style.window_padding[1];
    const content_h_natural: f32 = w.layout.cursor_max[1] + w.scroll_y - inner_origin_y;
    const content_w_natural: f32 = w.layout.cursor_max[0] + w.scroll_x - w.pos[0] + ctx.style.window_padding[0];
    // P5.2: `always_auto_resize` matches imgui's
    // `ImGuiWindowFlags_AlwaysAutoResize` semantics — every frame,
    // window matches its content's natural extent (BOTH grow AND
    // shrink), ignoring `user_resized`. Normal behavior (no flag)
    // only grows, and pins once the user has dragged.
    if (w.flags.always_auto_resize) {
        const total_h: f32 = content_h_natural + effectiveTitleBarHeight(ctx, w) + ctx.style.window_padding[1];
        w.size[0] = content_w_natural;
        w.size[1] = total_h;
    } else if (!w.user_resized) {
        if (content_w_natural > w.size[0]) {
            w.size[0] = content_w_natural;
        }
        const total_h: f32 = content_h_natural + effectiveTitleBarHeight(ctx, w) + ctx.style.window_padding[1];
        if (total_h > w.size[1]) {
            w.size[1] = total_h;
        }
    }

    // lint #5: content overflow. v7 spec phrased this as
    // "cursor_y > inner.y + region.h with no scrollbar", but zimr
    // currently auto-shows the scrollbar whenever scroll_max_y > 0,
    // so the literal condition never holds. The grounded variant:
    // when the auto-expanded window grew taller than the canvas, OR
    // when the user-sized window's content overflows by more than
    // 3× its viewport (scrollbar travel ratio so tight it's nearly
    // unusable). Either case usually means the caller wanted an
    // explicit size, a smaller font, or a scroll region they
    // forgot.
    if (!w.user_resized) {
        const canvas_h_f: f32 = float(ctx.canvas_h);
        if (w.pos[1] + w.size[1] > canvas_h_f) {
            warnOnce(
                @src(),
                "ui.window: auto-expanded '{s}' (h={d:.0}) extends below canvas " ++
                    "(h={d:.0}); consider setNextWindowSize",
                .{ w.name(), w.size[1], canvas_h_f },
            );
        }
    } else {
        // Sized window — scrollbar present whenever there's
        // overflow, so the bug is "viewport tiny relative to
        // content". Warn once at 3× ratio.
        const viewport_h_local: f32 = @max(
            1,
            w.size[1] - effectiveTitleBarHeight(ctx, w) - ctx.style.window_padding[1],
        );
        if (content_h_natural > viewport_h_local * 3) {
            warnOnce(
                @src(),
                "ui.window: '{s}' content ({d:.0}px) is >3× its viewport ({d:.0}px); consider enlarging the window",
                .{ w.name(), content_h_natural, viewport_h_local },
            );
        }
    }

    // ---- Compute scroll bookkeeping ----------------------------------
    const viewport_h: f32 = @max(0, w.size[1] - effectiveTitleBarHeight(ctx, w) - ctx.style.window_padding[1]);
    w.scroll_max_y = @max(0, content_h_natural - viewport_h);
    // Shift-wheel pan: when the user holds Shift, vertical wheel
    // ticks route to horizontal scroll instead of vertical.  Common
    // OS convention (Firefox/Chrome do this); wide content lanes
    // (timelines, code with long lines) get keyboard-mouse-only
    // horizontal navigation without needing a trackpad gesture.
    // Only fires when the window actually has horizontal capacity
    // (`horizontal_scrollbar` flag + `scroll_max_x > 0`); falls
    // through to normal Y handling otherwise so the user doesn't
    // feel a dead key.
    const shift_pan_active: bool = (ctx.input.keys[@backingInt(KeyCode.left_shift)].down or
        ctx.input.keys[@backingInt(KeyCode.right_shift)].down) and
        w.flags.horizontal_scrollbar and
        ctx.hovered_window_id == w.id and
        ctx.input.mouse_wheel_y != 0 and
        !ctx.mouse_wheel_x_consumed and
        !w.flags.no_scrollbar;
    if (shift_pan_active) {
        const wheel_speed: f32 = 5 * ctx.style.font_size;
        w.scroll_x -= ctx.input.mouse_wheel_y * wheel_speed;
        ctx.mouse_wheel_x_consumed = true;
        ctx.mouse_wheel_consumed = true;
    }
    // Touch-pan scroll: when the user drags across the window body
    // and no widget claimed the input (button/slider/etc), translate
    // the drag delta into scroll_y / scroll_x.  This is the mobile-
    // touch equivalent of mouse-wheel scrolling — desktop sites
    // generate `wheel` events from trackpad/mousewheel, but phones
    // only generate mouse-down/move/up from finger drags.  Without
    // this path, content that overflows is reachable only by
    // grabbing the thin scrollbar thumb — a 10 px wide target.
    //
    // Activation rule: hovered window, left-mouse held, active_id
    // is 0 (no widget grabbed it), scrollbar not suppressed, AND
    // there's actually somewhere to scroll.  Once activated, the
    // window keeps the pan active until release even if the cursor
    // wanders over a widget — avoids the gesture cancelling mid-
    // swipe when the finger crosses a button.
    //
    // Per-axis: Y always active when scroll_max_y > 0.  X only
    // when the horizontal_scrollbar flag is set (matches the wheel
    // gate at line 14046).  Pan is recomputed each frame from the
    // gesture start to avoid integration drift; captured offsets
    // live on the Window.
    const hovered_or_panning: bool = ctx.hovered_window_id == w.id or w.touch_pan_active;
    const can_pan_y: bool = w.scroll_max_y > 0;
    const can_pan_x: bool = w.flags.horizontal_scrollbar and w.scroll_max_x > 0;
    if (hovered_or_panning and ctx.input.mouse_left_down and
        !w.flags.no_scrollbar and (can_pan_y or can_pan_x))
    {
        // Geometric test: was the press DOWN-EDGE inside this window's body
        // (below the title bar, within its rect)? We can't trust
        // `hovered_window_id` here: it is only ever SET to a window id, never
        // cleared, so it stays stale-pointing at the last-entered window when
        // the finger is over empty space. Combined with the press-edge
        // (mouse_left_clicked), this ties the gesture to where the finger
        // actually went down, so a press that starts outside the window (or in
        // empty space the stale hover still points here) can't hijack-scroll.
        const tbh_pan: f32 = effectiveTitleBarHeight(ctx, w);
        const mp_pan: Vec2 = ctx.input.mouse_pos;
        const press_in_body: bool = mp_pan[0] >= w.pos[0] and
            mp_pan[0] < w.pos[0] + w.size[0] and
            mp_pan[1] >= w.pos[1] + tbh_pan and
            mp_pan[1] < w.pos[1] + w.size[1];
        if (!w.touch_pan_active and ctx.active_id == 0 and
            ctx.input.mouse_left_clicked and press_in_body)
        {
            // Gesture start. Capture mouse + scroll origin so each subsequent
            // frame's delta is computed from a fixed base.
            w.touch_pan_active = true;
            w.touch_pan_start_mouse = ctx.input.mouse_pos;
            w.touch_pan_start_scroll_y = w.scroll_y;
            w.touch_pan_start_scroll_x = w.scroll_x;
        }
        if (w.touch_pan_active) {
            const dx: f32 = ctx.input.mouse_pos[0] - w.touch_pan_start_mouse[0];
            const dy: f32 = ctx.input.mouse_pos[1] - w.touch_pan_start_mouse[1];
            if (can_pan_y) {
                w.scroll_y = w.touch_pan_start_scroll_y - dy;
            }
            if (can_pan_x) {
                w.scroll_x = w.touch_pan_start_scroll_x - dx;
            }
        }
    } else {
        // Gesture end on release OR conditions invalidated.
        w.touch_pan_active = false;
    }

    // Mouse-wheel input: if this is the hovered window AND no inner
    // child already consumed the wheel, translate wheel ticks into
    // scroll_y. Wheel ticks are signed (positive = user pulled wheel
    // up = content should move down = scroll_y decreases). Multiplier
    // matches ImGui's default of ~5 lines per tick at the current
    // font size. After consuming, set `mouse_wheel_consumed` so any
    // OUTER scope (if this is itself somehow inside one) doesn't
    // double-apply - though for top-level windows the cascade ends
    // here.  Skipped if shift-pan already consumed the wheel this
    // frame (shift_pan_active sets `mouse_wheel_consumed` too).
    if (ctx.hovered_window_id == w.id and ctx.input.mouse_wheel_y != 0 and !ctx.mouse_wheel_consumed and
        !w.flags.no_scrollbar)
    {
        const wheel_speed: f32 = 5 * ctx.style.font_size;
        w.scroll_y -= ctx.input.mouse_wheel_y * wheel_speed;
        ctx.mouse_wheel_consumed = true;
    }
    // Clamp scroll_y to its valid range.
    w.scroll_y = @max(0, w.scroll_y);
    w.scroll_y = @min(w.scroll_y, w.scroll_max_y);

    // ---- X-axis bookkeeping + wheel ----------------
    // scroll_max_x mirrors scroll_max_y but only when the
    // horizontal_scrollbar flag is set. Without the flag, the
    // window stays at scroll_x = 0 and X-overflowing widgets get
    // clipped at the right edge (legacy behavior).
    if (w.flags.horizontal_scrollbar) {
        const viewport_w: f32 = @max(0, w.size[0] - 2 * ctx.style.window_padding[0]);
        w.scroll_max_x = @max(0, content_w_natural - viewport_w);
        // Wheel-X: same shape as wheel-Y above, gated separately so
        // a Y-consumed inner scope doesn't block X scrolling on the
        // outer (axes are independent). Also gated on `no_scrollbar`
        // to match the Y behavior — a single "no_scrollbar = true"
        // disables both directions.
        if (ctx.hovered_window_id == w.id and ctx.input.mouse_wheel_x != 0 and
            !ctx.mouse_wheel_x_consumed and !w.flags.no_scrollbar)
        {
            const wheel_speed: f32 = 5 * ctx.style.font_size;
            w.scroll_x += ctx.input.mouse_wheel_x * wheel_speed;
            ctx.mouse_wheel_x_consumed = true;
        }
        // Clamp scroll_x to its valid range.
        w.scroll_x = @max(0, w.scroll_x);
        w.scroll_x = @min(w.scroll_x, w.scroll_max_x);
    } else {
        // Flag not set — keep state in a clean reset position so a
        // later flag flip doesn't surface stale values.
        w.scroll_max_x = 0;
        w.scroll_x = 0;
    }

    // ---- Pop the content clip rect ------------------------------------
    if (!ctx.eager_mode) {
        w.draw_list.popClipRect(ctx.frame_arena.allocator());
    }

    // ---- Render ------------ ------------- scrollbar (after content, outside content clip) ------
    // P5.1: skipped when `no_scrollbar` is set. Wheel consumption
    // above is gated by the same flag — both must agree to fully
    // disable scrolling on this window.
    if (w.scroll_max_y > 0 and !w.flags.no_scrollbar) {
        renderScrollbar(ctx, w);
    }
    // P5.5b: horizontal scrollbar mirrors the vertical
    // logic — only renders when content overflows X AND the flag
    // opted in. `no_scrollbar` suppresses both axes.
    if (w.scroll_max_x > 0 and w.flags.horizontal_scrollbar and !w.flags.no_scrollbar) {
        renderScrollbarX(ctx, w);
    }

    // Pop window stack.
    _ = ctx.window_stack.pop();
    refreshItemClip(ctx);

    // Restore current draw list to whichever window is now top of
    // stack (or null if no window is in scope). Skip in eager
    // mode - there's no draw list to restore.
    if (!ctx.eager_mode) {
        if (ctx.current_window) |outer| {
            ctx.current_draw_list = &outer.draw_list;
        } else {
            ctx.current_draw_list = null;
        }
    }
}

/// Returned by `ui.window(...)`. Tiny value type holding the
/// window pointer + the Ui handle so `close()` can run cleanup.
/// Caller defers `close()` to ensure the window stack pops even on
/// early returns.
pub const WindowHandle = struct {
    ui: Ui,
    win: *Window,

    pub fn close(self: WindowHandle) void {
        closeWindow(self.ui.ctx, self.win);
    }
};

/// Helper around `ctx.gpa.free(key)` that satisfies the type
/// system - `pending_persistence`'s key is `[]const u8` but we
/// allocated `[]u8`, so the free call needs `@constCast`. Kept
/// in one place so the cast doesn't proliferate.
fn gpa_free_key_safely(ctx: *UiContext, key: []const u8) void {
    ctx.gpa.free(@constCast(key));
}

/// Look up and remove the pending entry for `title`. Called by
/// `findOrCreateWindow`'s first-time branch BEFORE applying
/// `opts.initial_*` so persisted state takes precedence over the
/// caller's defaults. Returns null when no persisted entry
/// exists (new window, never seen before).
pub fn takeFor(ctx: *UiContext, title: []const u8) ?PersistedWindow {
    const entry: std.StringHashMapUnmanaged(PersistedWindow).KV =
        ctx.pending_persistence.fetchRemove(title) orelse return null;
    // The caller will copy out the fields it needs synchronously.
    // The key's memory is freed here; the value's `name` field
    // aliases the same memory we just freed, so the returned
    // struct's `name` is technically dangling - but the caller
    // doesn't read `name` (it already has the title). Document
    // this contract loudly:
    //   The returned `PersistedWindow.name` is dangling. Read
    //   `pos`, `size`, `scroll_y`, `user_resized` only.
    // Safer would be to keep the name alive for the duration of
    // the return - but that'd complicate the call site for no
    // real win (callers ignore `name` entirely).
    var result: PersistedWindow = entry.value;
    gpa_free_key_safely(ctx, entry.key);
    result.name = ""; // explicitly clobber to prevent UAF reads
    return result;
}

/// Clamp a window size to optional min / max bounds. Either
/// bound being `null` means "no limit on that side". Per-axis
/// independent.
fn clampWindowSize(
    size: Vec2,
    min: ?Vec2,
    max: ?Vec2,
) Vec2 {
    var out: @TypeOf(size) = size;
    if (min) |m| {
        if (out[0] < m[0]) {
            out[0] = m[0];
        }
        if (out[1] < m[1]) {
            out[1] = m[1];
        }
    }
    if (max) |m| {
        if (out[0] > m[0]) {
            out[0] = m[0];
        }
        if (out[1] > m[1]) {
            out[1] = m[1];
        }
    }
    return out;
}

pub fn findOrCreateWindow(
    ctx: *UiContext,
    title: []const u8,
    opts: WindowOpts,
) *Window {
    const id: Id = hashStr(0, title);
    if (ctx.windows.get(id)) |existing| {
        // docked windows pull pos/size from
        // their dock leaf every frame, overriding any setNextWindow*
        // overrides AND the stored fields. The leaf rect was just
        // refreshed by `dockSpaceImpl`'s `layoutSubtree` call earlier
        // this frame, so reading it here is consistent.
        // If the docked window's leaf has gone missing (the user
        // tore down the dockspace mid-session), we silently fall
        // back to the floating path by clearing `dock_node_id`
        // better than orphaning the window inside a dead tree.
        if (existing.dock_node_id) |node_id| {
            if (ctx.dock.lookup(node_id)) |leaf_node| {
                if (leaf_node.isLeaf()) {
                    existing.pos = leaf_node.pos;
                    existing.size = leaf_node.size;
                    existing.user_resized = true; // suppress auto-fit
                    return existing;
                }
            }
            existing.dock_node_id = null;
        }

        // Apply setNextWindow* overrides that fire every frame
        // (the *_always variants). Once-only variants fired only at
        // first-time creation below.
        if (ctx.next_window_pos) |p| {
            if (ctx.next_window_pos_always) {
                existing.pos = p;
            }
        }
        if (ctx.next_window_size) |s| {
            if (ctx.next_window_size_always) {
                // ★ A ZERO COMPONENT MEANS "FIT THE CONTENT" on that axis (imgui's
                // `SetNextWindowSize` semantics), so it must not overwrite the window's own
                // size with a literal zero. Only the axes the caller actually specified are
                // applied, and auto-fit stays enabled when either axis was left to the
                // layout.
                //
                // This path runs EVERY FRAME, which is what made the first version of this
                // fix ineffective: patching only the creation path left the per-frame
                // override re-applying the zero on frame two, and the window collapsed to a
                // title bar with its content clipped away.
                if (!ctx.next_window_size_auto[0]) {
                    existing.size[0] = s[0];
                }
                if (!ctx.next_window_size_auto[1]) {
                    existing.size[1] = s[1];
                }
                if (!ctx.next_window_size_auto[0] and !ctx.next_window_size_auto[1]) {
                    existing.user_resized = true; // a FULLY explicit size disables auto-fit
                }
            }
        }
        // P5.1: re-stamp flags from the per-frame opts so
        // callers can toggle chrome suppression between frames
        // (e.g. "lock window once user clicks Settle layout").
        // Preserves `is_child` which is set once at child creation
        // and shouldn't flip later.
        const was_child: bool = existing.flags.is_child;
        existing.flags = opts.flags;
        existing.flags.is_child = was_child;
        return existing;
    }

    // First-time submission for this title: allocate persistent state.
    const w: *Window = ctx.gpa.create(Window) catch panicf(@src(), "OOM", .{});

    // persisted state takes precedence over
    // `opts.initial_*`. If a previous session saved this window's
    // pos/size, restore them before the explicit `setNextWindow*`
    // / `opts.initial_*` cascade. setNextWindow* still wins (it's
    // a runtime override - caller asked explicitly) - but in the
    // common case where the caller didn't set those, the persisted
    // values override the demo's hardcoded defaults.
    const persisted: ?PersistedWindow = takeFor(ctx, title);

    // setNextWindowPos overrides initial_pos; setNextWindowSize overrides
    // initial_size - both apply to first-creation regardless of
    // `_always` because `cond_once` is the most-common ImGui usage.
    const pos: Vec2 = ctx.next_window_pos orelse
        (if (persisted) |p| @as(Vec2, .{ p.pos[0], p.pos[1] }) else null) orelse
        opts.initial_pos orelse
        blk: {
            // Auto-tile: stagger new windows down-and-right by 30px
            // each so a fresh app doesn't pile every window at the
            // same screen origin. Advance the running counter
            // after capturing the position so the NEXT
            // not-positioned window starts 30px further along.
            const p: Vec2 = ctx.next_default_pos;
            ctx.next_default_pos = .{ p[0] + 30, p[1] + 30 };
            break :blk p;
        };
    // A zero component means auto-fit, so drop it and let the content-derived path below
    // supply that axis. Doing it here rather than in the setter keeps the caller's request
    // intact for the per-frame consumer.
    if (ctx.next_window_size) |requested| {
        if (ctx.next_window_size_auto[0] or ctx.next_window_size_auto[1]) {
            const fallback: Vec2 = opts.initial_size;
            ctx.next_window_size = .{
                if (ctx.next_window_size_auto[0]) fallback[0] else requested[0],
                if (ctx.next_window_size_auto[1]) fallback[1] else requested[1],
            };
        }
    }
    var size: Vec2 = ctx.next_window_size orelse
        (if (persisted) |p|
            // P5.2: `always_auto_resize` overrides the persisted
            // size — caller asked for auto-fit-each-frame, so the
            // last save shouldn't pin a value the user explicitly
            // dragged to. initial_size still applies as the
            // first-frame starting point until content fills in.
            (if (opts.flags.always_auto_resize) null else @as(Vec2, .{ p.size[0], p.size[1] }))
        else
            null) orelse
        opts.initial_size;
    // Apply size constraints at creation. Same clamping is
    // re-applied per-frame in openWindow's consumer block so
    // user drag-resize is also bounded.
    size = clampWindowSize(size, ctx.next_window_size_min, ctx.next_window_size_max);
    w.* = .{
        .id = id,
        .pos = pos,
        .size = size,
        .scroll_y = if (persisted) |p| p.scroll_y else 0,
        .scroll_x = if (persisted) |p| p.scroll_x else 0,
        // Explicit size at creation time also disables auto-fit so a
        // 280×240 phase-4a window doesn't immediately grow to fit
        // overflow content - that's the whole point of giving it a size.
        // Persisted state implies the user already resized at some
        // point - preserve that signal so auto-fit stays disabled.
        .user_resized = (ctx.next_window_size != null) or (opts.initial_pos != null) or
            (if (persisted) |p| p.user_resized else false),
        // P5.1: propagate caller's chrome-suppression
        // flags onto the persistent window state. Re-stamped each
        // frame by the existing-window path above so the caller can
        // toggle flags between submissions.
        .flags = opts.flags,
    };
    const cap: usize = @min(title.len, w.name_buf.len);
    @memcpy(w.name_buf[0..cap], title[0..cap]);
    w.name_len = cap;

    ctx.windows.put(ctx.gpa, id, w) catch panicf(@src(), "OOM", .{});
    return w;
}

///.ii: cumulative-motion threshold (in
/// canvas pixels) past which a title-bar drag becomes a
/// dock-drag operation - i.e. `DockContext.dragging_window` gets
/// set and the dock-target overlay becomes visible. Matches
/// imgui's default `MouseDragThreshold` (8 px). Measured as
/// chebyshev distance (`max(|dx|, |dy|)`) from the press point.
pub const dock_drag_threshold_px: f32 = 8.0;

fn renderWindowChrome(ctx: *UiContext, w: *Window) void {
    // ---- title-bar drag + corner resize
    // Hit-test the title bar: if the user mouse-presses inside it and
    // no other widget owns active_id, capture the drag. While we
    // own active_id, follow the mouse delta on `w.pos`. Symmetric
    // logic for the bottom-right corner grip drives `w.size`.
    // The drag and resize get DETERMINISTIC ids derived from the
    // window's id so they're unique across all windows + don't collide
    // with user widgets.
    const drag_id: Id = widgetId(ctx, w, "##drag_title");
    const resize_id: Id = widgetId(ctx, w, "##resize_grip");

    const title_rect = Rectangle{
        .x = w.pos[0],
        .y = w.pos[1],
        .width = w.size[0],
        .height = ctx.style.title_bar_height,
    };
    const grip_size: f32 = 14;
    const resize_rect = Rectangle{
        .x = w.pos[0] + w.size[0] - grip_size,
        .y = w.pos[1] + w.size[1] - grip_size,
        .width = grip_size,
        .height = grip_size,
    };
    const min_size: Vec2 = .{ 80, ctx.style.title_bar_height + 24 };

    const mp: Vec2 = ctx.input.mouse_pos;
    const md: bool = ctx.input.mouse_left_down;
    // Rising-edge signal: true only on the frame the user PRESSES.
    // imgui uses `IsMouseClicked(0)` for the same purpose at
    // `imgui.cpp` ~line 5524 (UpdateMouseMovingWindowNewFrame).  We
    // must NOT start a drag on "currently held" — that would let the
    // user click on canvas, hold, walk the cursor into a window's
    // title bar, and unintentionally pick up the window.  Bug was
    // reproducible by holding LMB on bare canvas then dragging the
    // cursor into the Physics panel header in `ball_physics`.
    const mc: bool = ctx.input.mouse_left_clicked;
    const mp_in_title: bool = pointInRect(mp, title_rect);
    const mp_in_grip: bool = pointInRect(mp, resize_rect);

    // ---- Title-bar drag ----------------------------------------------
    // Begin drag: mouse fresh-CLICKED inside title, no other widget
    // active.  P5.1: skipped when `no_move` is set OR when
    // `no_title_bar` is set (no title bar means no drag handle to
    // hit).
    const can_move: bool = !w.flags.no_move and !w.flags.no_title_bar;
    if (can_move and mc and ctx.active_id == 0 and mp_in_title and !mp_in_grip) {
        ctx.active_id = drag_id;
        ctx.active_id_just_activated = true;
        // Stash press-x as click-anchor offset within the title bar
        // so the window doesn't snap-to-mouse on first frame.
        ctx.active_id_press_x = mp[0] - w.pos[0];
        ctx.active_id_press_value = @floatCast(mp[1] - w.pos[1]);
        //.ii: also stash the raw press SCREEN position so
        // the cumulative-motion threshold can fire below. The
        // delta (mp - press_screen) measures how far the mouse has
        // travelled from where the user clicked, independent of
        // any clamping applied to `w.pos`.
        ctx.active_id_press_screen = mp;
        // Clicking a window focuses it.
        ctx.focused_window_id = w.id;
    }
    // Continue drag.
    if (ctx.active_id == drag_id) {
        if (md) {
            w.pos[0] = mp[0] - ctx.active_id_press_x;
            w.pos[1] = mp[1] - @as(f32, @floatCast(ctx.active_id_press_value));
            // Clamp to canvas so the title bar can't disappear off-screen.
            const cw: f32 = float(ctx.canvas_w);
            const ch: f32 = float(ctx.canvas_h);
            w.pos[0] = @max(w.pos[0], -w.size[0] + 32);
            w.pos[0] = @min(w.pos[0], cw - 32);
            w.pos[1] = @max(w.pos[1], 0);
            w.pos[1] = @min(w.pos[1], ch - ctx.style.title_bar_height);

            //.ii: dock-drag tracking is GATED
            // on a cumulative-motion threshold from the press
            // point. Without this gate, the dock-target overlay
            // would pop on every single click of a title bar - bad
            // UX (overlay flashes on simple focus clicks). Past
            // the threshold, we're confident the user intends to
            // drag, and the overlay (5.5d.iii) becomes useful.
            // 8 px matches imgui's default `MouseDragThreshold`.
            // Cumulative motion = max(|dx|, |dy|) - cheaper and
            // matches imgui's chebyshev metric.
            const dx: f32 = mp[0] - ctx.active_id_press_screen[0];
            const dy: f32 = mp[1] - ctx.active_id_press_screen[1];
            const motion: f32 = @max(@abs(dx), @abs(dy));
            if (motion >= dock_drag_threshold_px) {
                ctx.dock.dragging_window = w.id;
            }
        } else {
            ctx.active_id = 0;
            // Mouse released.iv: if we
            // were tracking a dock-drag AND the release landed
            // over one of the drop zones, enqueue the matching
            // DockRequest. `processRequests` (already called
            // by endFrame) drains the queue on this same frame
            // so the dock takes effect next frame.
            // The hit-test runs even when `dragging_window` is
            // null - that path means motion never crossed the
            // threshold, and `hitTestDockTargets` returns null
            // anyway because no overlay was visible.
            if (ctx.dock.dragging_window) |dragging_id| {
                if (hitTestDockTargets(ctx, mp)) |hit| {
                    // stash the dragged window's
                    // current pos/size as its pre-dock anchor IF
                    // it isn't already docked. This is the
                    // runtime drag-to-dock path; the programmatic
                    // path stashes in dockBuilderDockWindow.
                    // (We can't stash from processRequests itself
                    // - that lives in ui_dock.zig and doesn't
                    // know about Window's pre_dock_*. Doing it
                    // at enqueue time is the cleanest hook.)
                    if (ctx.windows.get(dragging_id)) |dragged| {
                        if (dragged.pre_dock_pos == null and dragged.dock_node_id == null) {
                            dragged.pre_dock_pos = dragged.pos;
                            dragged.pre_dock_size = dragged.size;
                        }
                    }
                    const req: DockRequest = switch (hit.kind) {
                        .center => .{ .dock_as_tab = .{
                            .target_node = hit.target_node,
                            .source_window = dragging_id,
                        } },
                        .top => .{ .dock_as_split = .{
                            .target_node = hit.target_node,
                            .source_window = dragging_id,
                            .dir = .top,
                        } },
                        .right => .{ .dock_as_split = .{
                            .target_node = hit.target_node,
                            .source_window = dragging_id,
                            .dir = .right,
                        } },
                        .bottom => .{ .dock_as_split = .{
                            .target_node = hit.target_node,
                            .source_window = dragging_id,
                            .dir = .bottom,
                        } },
                        .left => .{ .dock_as_split = .{
                            .target_node = hit.target_node,
                            .source_window = dragging_id,
                            .dir = .left,
                        } },
                    };
                    ctx.dock.pending_requests.append(ctx.gpa, req) catch assertUnreachable(@src(), "OOM", .{});
                }
                ctx.dock.dragging_window = null;
            }
        }
    }

    // ---- Corner-grip resize ------------------------------------------
    // Begin resize: mouse fresh-CLICKED inside corner grip, no other
    // active widget.  Same rising-edge rule as the title-bar drag
    // above — a held-LMB cursor entering the grip should NOT pick
    // up a resize.  P5.1: gated on `no_resize`.
    if (!w.flags.no_resize and mc and ctx.active_id == 0 and mp_in_grip) {
        ctx.active_id = resize_id;
        ctx.active_id_just_activated = true;
        ctx.active_id_press_x = mp[0] - (w.pos[0] + w.size[0]);
        ctx.active_id_press_value = @floatCast(mp[1] - (w.pos[1] + w.size[1]));
        ctx.focused_window_id = w.id;
    }
    if (!w.flags.no_resize and ctx.active_id == resize_id) {
        if (md) {
            const new_w: f32 = mp[0] - w.pos[0] - ctx.active_id_press_x;
            const new_h: f32 = mp[1] - w.pos[1] - @as(f32, @floatCast(ctx.active_id_press_value));
            w.size[0] = @max(new_w, min_size[0]);
            w.size[1] = @max(new_h, min_size[1]);
            w.user_resized = true; // disables future auto-fit grow
        } else {
            ctx.active_id = 0;
        }
    }

    // ---- Background
    // Outer background (everything below the title bar).
    // P5.1: skipped when `no_background` is set — useful for HUD-style
    // overlays where caller provides their own backdrop.
    if (!w.flags.no_background) {
        drawRectFilled(
            ctx,
            .{ .x = w.pos[0], .y = w.pos[1], .width = w.size[0], .height = w.size[1] },
            Color.toWire(ctx.style.window_bg),
        );
    }

    // Title bar - colour reflects focus state. Focused windows draw
    // with `title_bg_active`; unfocused windows use `title_bg`.
    // P5.1: entire title-bar block (rect + text) skipped when
    // `no_title_bar` is set.
    if (!w.flags.no_title_bar) {
        const title_col: Color = if (ctx.focused_window_id == w.id)
            ctx.style.title_bg_active
        else
            ctx.style.title_bg;
        drawRectFilled(
            ctx,
            .{ .x = w.pos[0], .y = w.pos[1], .width = w.size[0], .height = ctx.style.title_bar_height },
            Color.toWire(title_col),
        );
        // Title text - center vertically inside the title bar.
        // P5.5a: when `unsaved_document` is set, render
        // a " *" marker after the title. Format into a stack buffer
        // sized for the max name length (128) + " *\0" suffix.
        const title_y: f32 = w.pos[1] + (ctx.style.title_bar_height - ctx.style.font_size) / 2;
        if (w.flags.unsaved_document) {
            var name_buf: [132]u8 = undefined;
            const formatted: []const u8 = bufPrint(
                &name_buf,
                "{s} *",
                .{w.name()},
            ) catch w.name(); // overflow → fall back to plain name (no marker)
            drawTextAtS(
                ctx,
                .{ w.pos[0] + 8, title_y },
                formatted,
                Color.toWire(ctx.style.text),
            );
        } else {
            drawTextAtS(
                ctx,
                .{ w.pos[0] + 8, title_y },
                w.name(),
                Color.toWire(ctx.style.text),
            );
        }
    }

    // ---- Resize-grip glyph (small triangle in bottom-right) ----------
    // Render only if window is interactive (not eager-mode in an RT scope).
    // The grip is two filled triangles forming a corner.
    // P5.1: skipped when `no_resize` is set.
    if (!w.flags.no_resize) {
        const grip_col: Color = if (ctx.active_id == resize_id or
            (ctx.hovered_window_id == w.id and mp_in_grip))
            ctx.style.button_active
        else
            ctx.style.border;
        drawRectFilled(
            ctx,
            .{
                .x = resize_rect.x + grip_size - 4,
                .y = resize_rect.y + grip_size - 8,
                .width = 3,
                .height = 3,
            },
            Color.toWire(grip_col),
        );
        drawRectFilled(
            ctx,
            .{
                .x = resize_rect.x + grip_size - 8,
                .y = resize_rect.y + grip_size - 4,
                .width = 3,
                .height = 3,
            },
            Color.toWire(grip_col),
        );
        drawRectFilled(
            ctx,
            .{
                .x = resize_rect.x + grip_size - 4,
                .y = resize_rect.y + grip_size - 4,
                .width = 3,
                .height = 3,
            },
            Color.toWire(grip_col),
        );
    }

    // Border.
    drawRect(
        ctx,
        .{ .x = w.pos[0], .y = w.pos[1], .width = w.size[0], .height = w.size[1] },
        Color.toWire(ctx.style.border),
    );
}

fn openWindow(
    ctx: *UiContext,
    title: []const u8,
    opts: WindowOpts,
) ?WindowHandle {
    const w: *Window = findOrCreateWindow(ctx, title, opts);
    w.last_frame_active = ctx.frame_count;

    // docked-window gating. When a window is
    // assigned to a dock leaf, only the leaf's currently-selected
    // window submits this frame - every other docked-but-inactive
    // tab returns null so the caller's `if (u.window(...)) |w| {}`
    // block is skipped (widgets don't submit, the draw list isn't
    // added to `frame_windows`, no chrome is rendered).
    // Selected docked windows DO continue through openWindow; they
    // skip chrome rendering below (the leaf's tab bar plays the
    // role of the title bar) but otherwise behave like floating
    // windows - content area, scroll, clip rect, etc. all unchanged.
    const docked: bool = w.dock_node_id != null;
    if (docked) {
        const node_id: Id = w.dock_node_id.?;
        if (ctx.dock.lookup(node_id)) |node| {
            if (node.leaf) |leaf| {
                if (leaf.selected_window_id != w.id) {
                    // Inactive tab. Stamp the frame counter so
                    // window GC doesn't drop us; everything else
                    // skipped. The leaf's tab bar (rendered by
                    // dockSpaceImpl) handles tab-click selection.
                    return null;
                }
            }
        }
    }

    // NOTE: the per-frame layout reset (content cursor) is computed AFTER
    // renderWindowChrome below — the chrome's title-bar drag updates w.pos this
    // frame, and the content must use that SAME post-drag pos or the text lags
    // the window chrome by one frame while dragging.

    // Push onto the window stack so `current_window` is correct
    // for any widget calls before close().
    ctx.window_stack.append(w) catch {
        return null;
    };
    ctx.current_window = w;
    // ★ Clip interaction to THIS window for the whole time its widgets are submitted. Setting
    // this only on the pop path left every widget hit-testing unclipped.
    refreshItemClip(ctx);

    // ---- Draw-list bookkeeping
    // Each window owns its own draw list, recorded fresh every
    // frame. We append to the frame's render order list so endFrame
    // knows what to play back. In eager mode (inside an RT scope)
    // we DON'T append - eager submissions render synchronously, no
    // need for endFrame replay.
    if (!ctx.eager_mode) {
        w.draw_list.clear();
        ctx.frame_windows.append(w) catch assertUnreachable(@src(), "OOM", .{});
        ctx.current_draw_list = &w.draw_list;
    }

    // Render window chrome (title bar, border, resize grip). Done
    // BEFORE the content clip push so chrome isn't clipped.
    // docked windows skip chrome - their
    // identity + selection lives in the leaf's tab bar (rendered
    // by `dockSpaceImpl`), and the leaf's parent split provides
    // the resize affordance (splitter drag, later step). The
    // title-bar-height SPACE is still reserved by the inner_origin
    // computation above; the leaf's tab bar paints in that area
    // from outside the window's draw list.
    if (!docked) {
        renderWindowChrome(ctx, w);
    }

    // Reset per-frame layout state. Cursor starts inside the title
    // bar's bottom edge plus window padding. Scroll-aware: when
    // `scroll_y > 0`, content renders shifted UP by that amount
    // i.e. the cursor's initial y is moved UP so widgets that would
    // have appeared at the natural inner_origin now sit ABOVE the
    // visible content area (and get clipped by the content clip rect
    // we push below).
    const inner_origin: Vec2 = .{
        w.pos[0] + ctx.style.window_padding[0],
        w.pos[1] + effectiveTitleBarHeight(ctx, w) + ctx.style.window_padding[1],
    };
    const inner_max: Vec2 = .{
        w.pos[0] + w.size[0] - ctx.style.window_padding[0],
        w.pos[1] + w.size[1] - ctx.style.window_padding[1],
    };
    // Reset the whole LayoutScope each frame. Origin = inner top-
    // left; work_rect_max = inner bottom-right (the right + bottom
    // edges of the content area, used by `getContentRegionAvail`
    // and `beginChild` auto-fill); cursor + cursor_max = inner
    // top-left (modulo scroll); cursor_pos_prev_line seeded to the
    // same so a pathological `sameLine` call before any widget
    // submission lands at a sensible position rather than (0,0).
    // All other fields zero.
    w.layout = .{
        .origin = inner_origin,
        .work_rect_max = inner_max,
        .cursor_pos = .{ inner_origin[0] - w.scroll_x, inner_origin[1] - w.scroll_y },
        .cursor_max = .{ inner_origin[0] - w.scroll_x, inner_origin[1] - w.scroll_y },
        .cursor_pos_prev_line = inner_origin,
    };

    // ---- Push the content-area clip rect
    // Content lives below the title bar and inside the window border.
    // Pushing this clip rect ensures scrolled-out widgets (those
    // shifted above or below the visible content) get scissored away
    // at GL replay. Popped in closeWindow before the scrollbar
    // renders (the scrollbar lives outside the content clip).
    if (!ctx.eager_mode) {
        // Use effectiveTitleBarHeight (0 when no_title_bar=true) to
        // match the cursor's inner_origin calculation above. Earlier
        // versions hard-coded ctx.style.title_bar_height here, which
        // meant borderless windows (no_title_bar=true) clipped away
        // the top N pixels of their own content — the cursor started
        // at y=window_padding[1] while the clip rect started at
        // y=title_bar_height, so anything between the two got
        // scissored off. Visible symptom: tab bars and other widgets
        // submitted as the first thing inside the window appeared
        // truncated/squished. See screenshots/turn-411-tab-clip.png.
        const tbh: f32 = effectiveTitleBarHeight(ctx, w);
        // Clamp to non-negative.  A window whose outer height is
        // less than the title-bar height (e.g. a brand-new docked
        // window on the frame its dock leaf hasn't been sized yet,
        // or a user-set 0×0 initial size) would otherwise produce
        // `content_clip.height < 0`, which crashes WebGL's
        // `glScissor` later at draw-list replay time.  A 0-size
        // clip is harmless (no pixels pass the test); a negative
        // one is a GL invariant violation.
        const content_clip: Rectangle = .{
            .x = w.pos[0],
            .y = w.pos[1] + tbh,
            .width = @max(0, w.size[0]),
            .height = @max(0, w.size[1] - tbh),
        };
        w.draw_list.pushClipRect(ctx.frame_arena.allocator(), content_clip);
    }

    // ---- setNextWindow* consumption + focus / hover
    // `setNextWindowFocus()` raises this window to top-of-z by
    // updating the focused id. Mouse-down on a window also
    // refocuses it (handled in renderWindowChrome's title-bar drag).
    if (ctx.next_window_focus) {
        ctx.focused_window_id = w.id;
    }
    // Hover detection: walk the mouse position; if it's inside this
    // window's outer rect AND no later (higher-z) window claims it,
    // record us as hovered. We update unconditionally - submission
    // order is back-to-front, so the LAST window covering the mouse
    // wins (matches ImGui).
    // P5.4: when `no_mouse_inputs` or `no_inputs` is set, this
    // window stays passthrough — skip the overwrite so any earlier
    // (deeper) covered window keeps the hover. All downstream
    // interaction gates test `hovered_window_id == w.id`, so this
    // single skip is enough to make the window mechanically
    // see-through for mouse input.
    const mp: Vec2 = ctx.input.mouse_pos;
    const passthrough_mouse: bool = w.flags.no_mouse_inputs or w.flags.no_inputs;
    if (!passthrough_mouse and
        mp[0] >= w.pos[0] and mp[0] < w.pos[0] + w.size[0] and
        mp[1] >= w.pos[1] and mp[1] < w.pos[1] + w.size[1])
    {
        ctx.hovered_window_id = w.id;
    }
    // Reset for next caller.
    ctx.next_window_pos = null;
    ctx.next_window_size = null;
    ctx.next_window_bg_alpha = null;
    ctx.next_window_focus = false;
    ctx.next_window_pos_always = true;
    ctx.next_window_size_always = true;
    // Size constraints clamp the existing window size on every
    // frame they're set, then clear so they don't bleed into
    // unrelated subsequent windows. Imgui keeps these
    // associated with the window (so they persist across
    // frames) - we follow the simpler "per-call" semantics:
    // user must call setNextWindowSizeConstraints each frame
    // they want the bounds enforced. Document if/when this
    // turns out to be a footgun.
    if (ctx.next_window_size_min != null or ctx.next_window_size_max != null) {
        w.size = clampWindowSize(w.size, ctx.next_window_size_min, ctx.next_window_size_max);
        ctx.next_window_size_min = null;
        ctx.next_window_size_max = null;
    }

    return WindowHandle{ .ui = .{ .ctx = ctx }, .win = w };
}

/// Flags for `beginChild`. Mirrors imgui's `ImGuiChildFlags`
/// (10 fields per imgui 1.92.8). Struct-of-bools per Zig idiom
/// each flag independently type-checked at the call site.
/// - replaces the older `ChildOpts {border,
/// padding}`. `padding` was a zimr-specific field that doesn't
/// map to imgui's convention (padding comes from
/// `style.window_padding` when the relevant flags are set).
/// **Current implementation status:** `border` and
/// `always_use_window_padding` are wired and active. The
/// resize/auto-resize/frame_style/nav_flattened flags are plumbed
/// as no-op-today - user code can set them now and pick up the
/// behavior automatically when each lands. Filed per-flag below.
pub const ChildFlags = struct {
    /// Show an outer 1px border around the child's outer rect.
    /// Implicitly enables `always_use_window_padding` semantics
    /// (border without inner padding looks cramped). Imgui:
    /// `ImGuiChildFlags_Borders`.
    border: bool = false,
    /// Pad inside the child with `style.window_padding` even if no
    /// border is drawn. Default false - non-bordered children
    /// start their layout at the child's top-left (matches imgui's
    /// `ImGuiChildFlags_None`). Set this when you want a tight
    /// border-less panel with breathing room inside. Imgui:
    /// `ImGuiChildFlags_AlwaysUseWindowPadding`.
    always_use_window_padding: bool = false,
    /// Allow the user to resize the child by dragging its right
    /// edge. **NOT YET IMPLEMENTED** - landed when child-edge
    /// drag handles are wired (filed for follow-up). Imgui:
    /// `ImGuiChildFlags_ResizeX`.
    resize_x: bool = false,
    /// Allow resize from the bottom edge. **NOT YET IMPLEMENTED.**
    /// Imgui: `ImGuiChildFlags_ResizeY`.
    resize_y: bool = false,
    /// Auto-size the child's width to its content. **NOT YET
    /// IMPLEMENTED** - needs two-pass measurement. Imgui:
    /// `ImGuiChildFlags_AutoResizeX`.
    auto_resize_x: bool = false,
    /// Auto-size the child's height to its content. **NOT YET
    /// IMPLEMENTED.** Imgui: `ImGuiChildFlags_AutoResizeY`.
    auto_resize_y: bool = false,
    /// Force measurement even when the child is hidden / clipped.
    /// **NOT YET IMPLEMENTED.** Imgui: `ImGuiChildFlags_AlwaysAutoResize`.
    always_auto_resize: bool = false,
    /// Render the child like a framed item - uses `frame_bg`,
    /// `frame_padding`, `frame_rounding` instead of the window
    /// variants. Same shape as a `listBox` frame. **NOT YET
    /// IMPLEMENTED** as a flag on beginChild - `listBox` has its
    /// own framing path that does this already. Imgui:
    /// `ImGuiChildFlags_FrameStyle`.
    frame_style: bool = false,
    /// Share focus scope with the parent; let keyboard nav cross
    /// child borders. **NOT YET IMPLEMENTED** - needs keyboard
    /// nav infrastructure (+). Imgui:
    /// `ImGuiChildFlags_NavFlattened`.
    nav_flattened: bool = false,
};

fn advanceLayout(
    w: *Window,
    consumed: Vec2,
    item_spacing: Vec2,
    window_pad_x: f32,
) void {
    _ = window_pad_x;
    const s: *LayoutScope = &w.layout;
    const placed_at: Vec2 = s.cursor_pos;
    const right: f32 = placed_at[0] + consumed[0];
    const bottom: f32 = placed_at[1] + consumed[1];

    // Track laid-out bottom-right for autosize / scroll_max.
    if (right > s.cursor_max[0]) {
        s.cursor_max[0] = right;
    }
    if (bottom > s.cursor_max[1]) {
        s.cursor_max[1] = bottom;
    }

    // Accumulate this row's tallest widget.
    if (consumed[1] > s.line_height) {
        s.line_height = consumed[1];
    }

    // Record where THIS item sits, for any subsequent `sameLine`
    // call. X = right edge (so the next sameLine starts there);
    // Y = top of the row (so cursor.y restores correctly).
    s.cursor_pos_prev_line = .{ right, placed_at[1] };

    // Promote current row tracking to "previous" so a sameLine
    // call after this advance keeps the right line_height.
    s.prev_line_height = s.line_height;

    // Advance cursor to the next row. X resets to origin+indent
    // minus scroll_x (imgui's `window.Pos.x - window.Scroll.x +
    // local_x` formula — origin already holds `Pos.x + padding`,
    // so subtract scroll here to get the screen-space cursor for
    // the next line's first widget).  Y drops past the bottom of
    // the tallest widget on this row; scroll_y stays baked in
    // because cursor_pos.y advances by additions, never resets.
    s.cursor_pos[0] = s.origin[0] - w.scroll_x + s.indent_x;
    s.cursor_pos[1] = placed_at[1] + s.line_height + item_spacing[1];

    // Current-row accumulator resets - `sameLine` would re-seed
    // it from `prev_line_height` if it fires before another widget.
    s.line_height = 0;
}

/// `endChild` core - pop the child Window, advance the parent's
/// layout past it, and record the child's outer rect as the
/// parent's "last item" so `isItemHovered()` after `endChild` asks
/// "was the user hovering the child's outer rect?" - useful for
/// scrollbar future-work and drag-and-drop target detection.
/// Parent's `current_window` restoration is by popping the window
/// stack; there's no state to save/restore on the parent because
/// the parent's `layout` was never touched during the child's
/// scope (the whole point of the child-as-Window refactor).
fn endChildImpl(ctx: *UiContext) void {
    const child: *Window = ctx.current_window orelse return;
    // Safety: if `endChild` is called without a matching
    // `beginChild` (e.g. due to early return inside the block),
    // current_window might not be a child - bail gracefully.
    if (!child.flags.is_child) {
        return;
    }

    // ---- Compute scroll bookkeeping
    // `cursor_max[1]` was tracked in scrolled coordinates (because
    // beginChild seeded the cursor at `inner_origin - scroll_y`), so
    // add `scroll_y` back to recover the un-shifted natural extent.
    // `viewport_h` is the visible content height - the distance
    // between `origin[1]` (top of content area) and
    // `work_rect_max[1]` (bottom of content area).
    const inner_origin_y: f32 = child.layout.origin[1];
    const content_h_natural: f32 = child.layout.cursor_max[1] + child.scroll_y - inner_origin_y;
    const viewport_h: f32 = @max(0, child.layout.work_rect_max[1] - inner_origin_y);
    child.scroll_max_y = @max(0, content_h_natural - viewport_h);

    // Capture the child's outer rect for hit-tests + later layout
    // advance. `pos` + `size` are the rect set by beginChild.
    const child_rect: Rectangle = .{
        .x = child.pos[0],
        .y = child.pos[1],
        .width = child.size[0],
        .height = child.size[1],
    };

    // Mouse-wheel input: if the cursor is inside this child's outer
    // rect AND no inner scope already claimed the wheel this frame,
    // translate wheel ticks into scroll_y. Inner children's
    // `endChildImpl` runs before their parent's (nesting order), so
    // the deepest scope under the pointer gets first dibs - that's
    // why we check `mouse_wheel_consumed` and set it after applying.
    if (!ctx.mouse_wheel_consumed and ctx.input.mouse_wheel_y != 0 and itemHoverable(ctx, child_rect)) {
        const wheel_speed: f32 = 5 * ctx.style.font_size;
        child.scroll_y -= ctx.input.mouse_wheel_y * wheel_speed;
        ctx.mouse_wheel_consumed = true;
    }
    // Clamp scroll_y to its valid range.
    child.scroll_y = clamp(child.scroll_y, 0, child.scroll_max_y);

    // ---- Pop the content clip + render scrollbar -------------------
    // Order matters: pop the clip BEFORE rendering the scrollbar so
    // the scrollbar isn't clipped by the child's own viewport. The
    // scrollbar still ends up inside the parent's clip (it's drawn
    // before we pop the window stack, while `current_window` is
    // still the child).
    if (!ctx.eager_mode) {
        if (ctx.current_draw_list) |dl| {
            dl.popClipRect(ctx.frame_arena.allocator());
        }
    }
    if (child.scroll_max_y > 0) {
        renderScrollbar(ctx, child);
    }

    // ---- Pop id_stack + window_stack ------------------------------
    _ = ctx.id_stack.pop();
    _ = ctx.window_stack.pop();
    const parent: *Window = if (ctx.window_stack.len > 0)
        ctx.window_stack.items[ctx.window_stack.len - 1]
    else
        return; // malformed nesting - parent already popped
    ctx.current_window = parent;

    // Record the child as the parent's "last item." The child
    // doesn't take an interaction id (children themselves aren't
    // clickable widgets - items INSIDE them are), so `last_item_id`
    // is zero. `last_item_hovered` reflects pointer-in-child-rect
    // so `isItemHovered` works after endChild.
    parent.layout.last_item_id = 0;
    parent.layout.last_item_rect = child_rect;
    parent.layout.last_item_hovered = itemHoverable(ctx, child_rect);

    // Advance the parent's cursor past the child's outer rect.
    // This is what makes `sameLine` after `endChild` land beside
    // the child (it sets cursor_pos_prev_line to the child's right
    // edge + row top) and what makes the next non-sameLine widget
    // sit BELOW the child.
    advanceLayout(
        parent,
        .{ child_rect.width, child_rect.height },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
}

/// Options for `Ui.dockSpace`. Today only sized for forward-
/// compat; will grow `flags: DockNodeFlags` for the imgui-parity
/// behavior toggles (passthru-central-node, no-split, no-resize,
/// no-tab-bar, etc).
pub const DockSpaceOpts = struct {
    /// Optional override of the dockspace background color. Null
    /// inherits from `style`.
    bg_color: ?Color = null,
};

/// Returns where the next widget will be placed. In the new
/// model, `cursor_pos` always reflects the resolved position
/// (sameLine writes directly to it), so this is just a read.
/// Kept as a function for callsite readability + a single place
/// to revisit if we re-introduce deferred-resolve semantics.
/// The `spacing_x` argument is no longer used (was needed for the
/// old pending-same-line branch that computed
/// `cursor_max[0] + spacing` lazily). Retained in the signature
/// to keep the existing ~30 callsites compiling; the unused-param
/// suppression makes the intent explicit.
fn resolveCursor(w: *Window, _: f32) Vec2 {
    return w.layout.cursor_pos;
}

fn drawRectLines(
    ctx: *UiContext,
    r: Rectangle,
    color: Color,
) void {
    // Hollow rectangle = 4 thin filled rectangles around the edges.
    // 1px thickness picks up cleanly on the LCD without antialiasing.
    const thickness: f32 = 1;
    const c: ColorU32 = Color.toWire(color);
    drawRect(ctx, .{ .x = r.x, .y = r.y, .width = r.width, .height = thickness }, c);
    drawRect(ctx, .{ .x = r.x, .y = r.y + r.height - thickness, .width = r.width, .height = thickness }, c);
    drawRect(ctx, .{ .x = r.x, .y = r.y, .width = thickness, .height = r.height }, c);
    drawRect(ctx, .{ .x = r.x + r.width - thickness, .y = r.y, .width = thickness, .height = r.height }, c);
}

/// Internal: register/resolve the dockspace root + render the
/// outline placeholder. Mutates layout (advances the cursor by
/// `size`) and `ctx.dock` (creates root node if first call;
/// pushes the id to `dockspaces_this_frame`).
fn dockSpaceImpl(
    ctx: *UiContext,
    str_id: []const u8,
    size: Vec2,
    opts: DockSpaceOpts,
) Id {
    const w: *Window = ctx.current_window orelse return 0;

    // Derive a stable id by hashing the str_id under the window's
    // id stack - same convention as widgetId for all other widgets.
    // The result fits in `Id` (u32 alias of `Id`).
    const id: Id = widgetId(ctx, w, str_id);

    // Reserve layout space. Resolve any pending sameLine; we
    // want the dockspace at the current row's leading edge.
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const rect: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = @max(0, size[0]),
        .height = @max(0, size[1]),
    };

    // if there's a pending dock tree
    // staged from persistence, try to restore it BEFORE we
    // fall through to the fresh-root creation path. Restore
    // is one-shot - it consumes the whole pending payload at
    // once. If the persisted tree contains a root matching
    // this dockspace's id, the user's subsequent builder
    // calls (`dockBuilderSplitNode`, etc.) become safe no-ops
    // (split target is no longer a leaf → rejected with
    // a/b = 0; user's `if (split.a != 0)` skips).
    if (ctx.pending_dock_tree.len > 0) {
        _ = tryRestoreDockTree(ctx.gpa, ctx);
    }

    // Find or create the root DockNode for this dockspace. IDs
    // are stable per-(window, str_id) so calling dockSpace with
    // the same arguments every frame reaches the same root.
    if (ctx.dock.lookup(id) == null) {
        // First-time: allocate a fresh leaf as the root. Pre-set
        // the id slot so `createNode` doesn't claim a fresh
        // `next_node_id` we don't want (we want the widget-hash
        // id, not a synthesized one).
        const node: *DockNode = ctx.gpa.create(DockNode) catch return 0;
        node.* = .{
            .id = id,
            .parent_id = null,
            .leaf = .{},
            // mark this node as a dockspace root.
            // Persistence (5.5k) uses this to distinguish trees
            // owned by a `dockSpace()` call from freestanding
            // node trees (which we don't create today, but the
            // bit reserves the distinction).
            .flags = .{ .is_dockspace = true },
        };
        ctx.dock.nodes.put(ctx.gpa, id, node) catch {
            ctx.gpa.destroy(node);
            return 0;
        };
    }

    // Push to per-frame dockspaces list for drag-drop hit-test
    // discovery in 5.5e.
    ctx.dock.dockspaces_this_frame.append(ctx.gpa, id) catch assertUnreachable(@src(), "OOM", .{});

    // Compute layout of the entire subtree rooted here. This
    // walks every node and writes per-node pos/size; the actual
    // rendering of leaf content happens via the per-window
    // submission path in `openWindow` - docked windows pull their
    // rect from the leaf, suppress their own chrome, and the
    // leaf's tab bar (emitted below) handles selection.
    layoutSubtree(&ctx.dock, id, .{ rect.x, rect.y }, .{ rect.width, rect.height });

    // ---- Placeholder rendering (5.5b) -------------------------------
    // A subtle 1px outline + corner hint label so the user can
    // see the dockspace is alive even before any windows dock in.
    const bg: Color = opts.bg_color orelse .{ .r = 20, .g = 30, .b = 50, .a = 60 };
    drawRectFilled(ctx, rect, Color.toWire(bg));
    drawRectLines(ctx, rect, .{ .r = 100, .g = 110, .b = 140, .a = 120 });

    // ---- tab-bar rendering DEFERRED
    // Originally tabs rendered inline here, but that meant the
    // FIRST frame after a `dockBuilder*` block saw empty leaves
    // (the builder runs AFTER `dockSpace()` returns). Deferring
    // tab-bar emission to endFrame fixes the ordering: by then
    // every builder call AND every docked-window submission has
    // run, so the tree is in its final per-frame state.
    // Tabs render into `foreground_dl` so they overlay docked
    // window content (which submits into per-window draw lists).
    // The id is added to `dockspaces_this_frame` already (above)
    // - endFrame walks that list to find dockspaces to draw.

    // Advance the parent cursor past the dockspace rect. Same
    // pattern as `beginChild` after content rendering completes.
    advanceLayout(
        w,
        .{ rect.width, rect.height },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );

    return id;
}

pub const SplitResult = struct { a: Id, b: Id };

/// per-node constraints. Flat packed
/// struct(u16), no Shared/Local/Local-in-Windows tier system
/// JUSTIFIED divergence from imgui (`ImGuiDockNodeFlags_`,
/// imgui.h:1533 + imgui_internal.h:1988). imgui's three-tier
/// system exists because it evolved the docking branch
/// incrementally on top of a `WindowClass`-typed restriction
/// system; we don't have window classes, so a flat single
/// bitset suffices.
/// Which imgui flags map to which zimr field:
///   imgui | zimr
///   -------------------------------------|---------------------
///   NoDockingSplit / NoSplit | `no_split`
///   NoTabBar | `no_tab_bar`
///   HiddenTabBar | `hidden_tab_bar`
///   NoResize / NoResizeX / NoResizeY | `no_resize`
///   NoDockingOverMe | `no_docking_over_me`
///   NoCloseButton | `no_close_button`
///   PassthruCentralNode | `passthru_central`
///   CentralNode | `is_central`
///   DockSpace | `is_dockspace`
/// Not modeled (out of scope or deferred):
///   NoWindowMenuButton (we don't have a window menu)
///   AutoHideTabBar (UX nicety, low priority)
///   KeepAliveOnly (matters if dockspaces in tabs)
///   NoUndocking (we don't ship undock-protect yet)
///   NoDockingSplitOther (we don't have "split other")
///   NoDockingOverOther (we don't have "over other")
///   NoDockingOverEmpty (we don't have "over empty")
pub const DockNodeFlags = packed struct(u16) {
    /// Prevent the user from splitting this node. The center
    /// (dock-as-tab) zone still works on this node's leaves; the
    /// top/right/bottom/left split zones are hidden + skipped in
    /// hit-test.
    no_split: bool = false,

    /// Tab bar is completely unavailable. No triangle in the
    /// corner to toggle it back. Useful for single-window panels
    /// where the tab bar would be visual noise.
    no_tab_bar: bool = false,

    /// Tab bar is hidden but conceptually present. Distinguished
    /// from `no_tab_bar` only for future toggle UX (a small
    /// indicator that brings the tab bar back). For now both
    /// flags hide the bar identically.
    hidden_tab_bar: bool = false,

    /// Disable splitter resize on this node (5.5i - not yet
    /// implemented; flag defined for forward compatibility).
    no_resize: bool = false,

    /// Refuse incoming docks onto this leaf. Both tab-merge
    /// (center zone) and side-splits are blocked. Hides the
    /// overlay entirely for this leaf.
    no_docking_over_me: bool = false,

    /// Hide per-tab close buttons (5.5j - not yet implemented).
    no_close_button: bool = false,

    /// Root-level: render `WindowBg` background everywhere except
    /// the central node; let inputs pass through the central node
    /// when empty. (5.5g - not yet implemented; flag defined.)
    passthru_central: bool = false,

    /// Marker: this is the "central" node of its dockspace.
    /// Central nodes stay visible when empty and absorb remaining
    /// space from siblings. At most one per dockspace.
    /// (5.5g - central-node layout logic uses this.)
    is_central: bool = false,

    /// Marker: this node is the root of a dockspace (set by
    /// `dockSpace()`). Floating multi-tab nodes (if we ever
    /// support them) would have this cleared. Helps
    /// `dockBuilderFinish` find the root and helps persistence
    /// distinguish trees that belong to a dockspace from any
    /// freestanding nodes.
    is_dockspace: bool = false,

    _padding: u7 = 0,

    /// Mask of flags that transfer from a leaf to its inheritor
    /// when that leaf is split (e.g. dock-as-split). The new
    /// "fresh" child gets default flags; the inheritor (the child
    /// that kept the existing content) keeps these.
    /// Mirrors imgui's `LocalFlagsTransferMask_`
    /// (imgui_internal.h:2016) - leaf-affinity flags transfer;
    /// tree-structural flags (`is_dockspace`, `passthru_central`)
    /// don't.
    pub const transfer_mask: DockNodeFlags = .{
        .no_split = true,
        .no_tab_bar = true,
        .hidden_tab_bar = true,
        .no_resize = true,
        .no_docking_over_me = true,
        .no_close_button = true,
        .is_central = true,
    };

    /// Return only the bits set in BOTH `self` and `mask`.
    /// Used for the inheritor-transfer pattern above.
    pub fn intersect(self: DockNodeFlags, mask: DockNodeFlags) DockNodeFlags {
        const a: u16 = @bitCast(self);
        const b: u16 = @bitCast(mask);
        return @bitCast(a & b);
    }

    /// Return `self` with every bit in `mask` cleared.
    pub fn except(self: DockNodeFlags, mask: DockNodeFlags) DockNodeFlags {
        const a: u16 = @bitCast(self);
        const b: u16 = @bitCast(mask);
        return @bitCast(a & ~b);
    }

    /// Bitwise OR of two flag sets. Used by the collapse paths to fold a
    /// surviving sibling's leaf-affinity flags into the parent slot while
    /// keeping the parent's structural bits.
    pub fn union_(self: DockNodeFlags, other: DockNodeFlags) DockNodeFlags {
        const a: u16 = @bitCast(self);
        const b: u16 = @bitCast(other);
        return @bitCast(a | b);
    }
};

/// Internal: an empty leaf with a parent SPLIT collapses away
/// the sibling node "absorbs" the parent's identity. The parent
/// node's id stays valid but its role changes to match the
/// sibling (split → split, leaf → leaf), preserving any
/// outstanding references to the parent id.
/// Steps:
///   1. Identify the sibling (the parent's other child).
///   2. Copy the sibling's role into the parent (split/leaf data).
///   3. If sibling was a split, re-parent its children to the
///      (now-rewritten) parent.
///   4. Free the original (empty) leaf and the sibling node.
fn collapseEmptyLeaf(
    ctx: *DockContext,
    gpa: Allocator,
    empty_leaf: *DockNode,
    parent_id: Id,
) void {
    const parent: *DockNode = ctx.lookup(parent_id) orelse return;
    const split: DockNode.SplitData = parent.split orelse return;
    const sibling_id: Id = if (split.child_ids[0] == empty_leaf.id)
        split.child_ids[1]
    else
        split.child_ids[0];
    const sibling: *DockNode = ctx.lookup(sibling_id) orelse return;

    // Adopt the sibling's role into the parent. Preserves the
    // parent's id (callers may hold it) while replacing its role.
    parent.split = sibling.split;
    if (sibling.leaf) |sl| {
        parent.leaf = .{
            .window_ids = sl.window_ids,
            .selected_window_id = sl.selected_window_id,
        };
    } else {
        parent.leaf = null;
    }
    // 9.1 fix: adopt the sibling's leaf-affinity flags (is_central, no_resize,
    // no_tab_bar, ...) while keeping the parent's structural bits (is_dockspace,
    // passthru_central). Without this, collapsing an empty sibling silently drops
    // the survivor's central/resize/tab-bar flags.
    parent.flags = sibling.flags.intersect(DockNodeFlags.transfer_mask)
        .union_(parent.flags.except(DockNodeFlags.transfer_mask));

    // Re-parent the sibling's children, if any.
    if (parent.split) |new_split| {
        for (new_split.child_ids) |cid| {
            if (ctx.lookup(cid)) |c| {
                c.parent_id = parent.id;
            }
        }
    }
    parent.generation +%= 1;

    // Free the empty leaf and the (now-orphaned) sibling shell.
    // Clear sibling's lists FIRST so we don't double-free its
    // window_ids - we already moved them into parent.leaf above.
    if (sibling.leaf) |*sl_old| {
        sl_old.window_ids = .empty;
    }
    ctx.freeNode(gpa, empty_leaf);
    ctx.freeNode(gpa, sibling);
}

/// Remove `window_id` from whatever leaf currently holds it.
/// If that leaves the leaf empty AND it has a parent SPLIT, the
/// sibling node takes the parent's slot and the parent is
/// freed. Returns true if anything changed.
pub fn undockWindow(
    ctx: *DockContext,
    gpa: Allocator,
    window_id: Id,
) bool {
    const leaf_node: *DockNode = ctx.findLeafFor(window_id) orelse return false;
    var leaf: *DockNode.LeafData = &(leaf_node.leaf orelse return false);
    const idx: usize = leaf.indexOf(window_id) orelse return false;
    _ = leaf.window_ids.orderedRemove(idx);

    // Pick a new selected tab if we just removed the active one.
    if (leaf.selected_window_id == window_id) {
        leaf.selected_window_id = if (leaf.window_ids.items.len > 0)
            leaf.window_ids.items[@min(idx, leaf.window_ids.items.len - 1)]
        else
            0;
    }
    leaf_node.generation +%= 1;

    // Collapse if the leaf is now empty and has a parent split.
    // Root leaves are kept around - a dockspace with no docked
    // windows is a valid (if visually empty) state.
    if (leaf.window_ids.items.len == 0) {
        if (leaf_node.parent_id) |pid| {
            collapseEmptyLeaf(ctx, gpa, leaf_node, pid);
        }
    }
    return true;
}

/// Dock `window_id` as a new tab into the leaf `leaf_id`. Adds
/// to the end of the tab list (rightmost tab); selects the new
/// tab automatically. No-op if `leaf_id` doesn't refer to a leaf,
/// or if the window is already in this leaf.
pub fn dockWindowAsTab(
    ctx: *DockContext,
    gpa: Allocator,
    leaf_id: Id,
    window_id: Id,
) Allocator.Error!void {
    const node: *DockNode = ctx.lookup(leaf_id) orelse return;
    var leaf: *DockNode.LeafData = &(node.leaf orelse return);
    if (leaf.indexOf(window_id) != null) {
        // Already present - promote to selected and return.
        leaf.selected_window_id = window_id;
        return;
    }
    try leaf.window_ids.append(gpa, window_id);
    leaf.selected_window_id = window_id;
    node.generation +%= 1;
}

/// walk the subtree rooted at `root_id` and clear
/// `dock_node_id` on every Window whose current dock leaf is part
/// of the subtree. Called by `dockBuilderRemoveNode` BEFORE the
/// nodes are destroyed, so we can still resolve the leaves' window
/// lists. After this returns, the dock layer can safely tear
/// down the subtree without leaving dangling `Window.dock_node_id`
/// references pointing at freed memory.
fn clearDockIdsInSubtree(ctx: *UiContext, root_id: Id) void {
    const root: *DockNode = ctx.dock.lookup(root_id) orelse return;
    if (root.leaf) |leaf| {
        // Clear dock_node_id on every window currently in this leaf.
        for (leaf.window_ids.items) |wid| {
            // We don't have a windows-by-id reverse map, so do
            // a linear walk. Tab counts per leaf are small; the
            // outer walk over all windows is bounded by the
            // total window count which is similarly small in
            // practice (~10s).
            if (ctx.windows.get(wid)) |w| {
                w.dock_node_id = null;
                // restore pre-dock pos/size. When a
                // window comes back to floating, it should land
                // back at the rect it had before it was first
                // docked - not at the leaf's last rect (which is
                // usually inside the dockspace and not where the
                // user wants it). Clears the stash so the next
                // dock cycle re-anchors fresh.
                if (w.pre_dock_pos) |pos| {
                    w.pos = pos;
                }
                if (w.pre_dock_size) |size| {
                    w.size = size;
                }
                w.pre_dock_pos = null;
                w.pre_dock_size = null;
            }
        }
    }
    if (root.split) |s| {
        clearDockIdsInSubtree(ctx, s.child_ids[0]);
        clearDockIdsInSubtree(ctx, s.child_ids[1]);
    }
}

/// Remove an entire subtree rooted at `node_id`. Frees the node
/// and all its descendants. If the node has a parent SPLIT, the
/// parent collapses the same way as an undockWindow that empties
/// a leaf. Use cases: a dockspace is torn down, or a layout
/// resets via `dockBuilderRemoveNode`.
pub fn removeNode(
    ctx: *DockContext,
    gpa: Allocator,
    node_id: Id,
) void {
    const node: *DockNode = ctx.lookup(node_id) orelse return;
    const parent_id: ?Id = node.parent_id;

    // Recurse into split children before freeing this node.
    if (node.split) |split| {
        // Snapshot child IDs because the recursive removeNode
        // calls mutate the pool.
        const children: [2]Id = split.child_ids;
        for (children) |cid| {
            removeNode(ctx, gpa, cid);
        }
    }
    ctx.freeNode(gpa, node);

    // Collapse parent if it had only this node and a sibling.
    if (parent_id) |pid| {
        if (ctx.lookup(pid)) |parent| {
            if (parent.split) |sp| {
                // If the removed node was a child of the parent,
                // re-route parent's surviving child up. We mimic
                // the collapseEmptyLeaf path but with a removed
                // child instead of an empty one.
                const surviving_id: ?Id =
                    if (sp.child_ids[0] == node_id)
                        sp.child_ids[1]
                    else if (sp.child_ids[1] == node_id)
                        sp.child_ids[0]
                    else
                        null;
                if (surviving_id) |sid| {
                    if (ctx.lookup(sid)) |survivor| {
                        parent.split = survivor.split;
                        if (survivor.leaf) |sl| {
                            parent.leaf = .{
                                .window_ids = sl.window_ids,
                                .selected_window_id = sl.selected_window_id,
                            };
                        } else {
                            parent.leaf = null;
                        }
                        // 9.1 fix: carry the survivor's leaf-affinity flags up.
                        parent.flags = survivor.flags.intersect(DockNodeFlags.transfer_mask)
                            .union_(parent.flags.except(DockNodeFlags.transfer_mask));
                        if (parent.split) |new_split| {
                            for (new_split.child_ids) |cid| {
                                if (ctx.lookup(cid)) |c| {
                                    c.parent_id = parent.id;
                                }
                            }
                        }
                        parent.generation +%= 1;
                        // Detach the survivor's list before
                        // freeing so we don't double-free.
                        if (survivor.leaf) |*sl_old| {
                            sl_old.window_ids = .empty;
                        }
                        ctx.freeNode(gpa, survivor);
                    }
                }
            }
        }
    }
}

pub const SameLineOpts = struct {
    /// Optional X position override (in window-local coordinates).
    /// 0 means use the default item spacing.
    offset_x: f32 = 0,
};

pub const ButtonOpts = struct {
    /// Override size. Zero on either axis means "auto-fit to label".
    size: Vec2 = .{ 0, 0 },
};

/// Direction the triangle glyph of an `arrowButton` points.
pub const ArrowDir = enum { left, right, up, down };

fn textImpl(
    ctx: *UiContext,
    comptime fmt: []const u8,
    args: anytype,
    color: Color,
) void {
    const w: *Window = ctx.current_window orelse return;

    // Format into a stack buffer. 256 bytes covers typical UI text;
    // longer strings get truncated cleanly. Future phases may move
    // to a per-frame arena for arbitrary lengths.
    var buf: [256]u8 = undefined;
    const formatted: []u8 = bufPrint(&buf, fmt, args) catch buf[0..0];

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const sz: Vec2 = measureTextS(ctx, formatted);
    drawTextAtS(ctx, at, formatted, Color.toWire(color));

    // Bookkeeping for IsItemHovered: even text reports a hovered rect.
    const rect = Rectangle{ .x = at[0], .y = at[1], .width = sz[0], .height = sz[1] };
    w.layout.last_item_id = 0; // text isn't interactive - no stable ID
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = itemHoverable(ctx, rect);

    advanceLayout(w, sz, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

fn textWrappedImpl(
    ctx: *UiContext,
    comptime fmt: []const u8,
    args: anytype,
) void {
    const w: *Window = ctx.current_window orelse return;

    var buf: [512]u8 = undefined;
    const full: []u8 = bufPrint(&buf, fmt, args) catch buf[0..0];
    if (full.len == 0) {
        return;
    }

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const wrap_x: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const max_width: f32 = wrap_x - at[0];
    if (max_width <= 0) {
        // No room - just draw and advance like normal text would.
        const sz: Vec2 = measureTextS(ctx, full);
        drawTextAtS(ctx, at, full, Color.toWire(ctx.style.text));
        advanceLayout(w, sz, ctx.style.item_spacing, ctx.style.window_padding[0]);
        return;
    }

    // Greedy word-wrap: scan tokens (whitespace-delimited), accumulate
    // until the next token would overflow `max_width`, emit a line,
    // restart. Falls back to mid-word splits for tokens longer than
    // the line.
    var line_y: f32 = at[1];
    var line_start: usize = 0;
    var i: usize = 0;
    var line_end: usize = 0; // last word boundary that fit

    while (i < full.len) : (i += 1) {
        // Find end of current word (or end of string).
        if (full[i] == ' ' or full[i] == '\n' or i + 1 == full.len) {
            // EXCLUSIVE end. A space or newline is not part of the word, so the slice stops AT it;
            // at end-of-string there is no separator to exclude, so it stops one past.
            const word_end: usize = if (full[i] == ' ' or full[i] == '\n') i else i + 1;
            const candidate: []const u8 = full[line_start..word_end];
            const candidate_w: f32 = measureTextS(ctx, candidate)[0];
            if (candidate_w > max_width and line_end > line_start) {
                // Emit the previous-good line, restart from after it.
                const slice: []u8 = full[line_start..line_end];
                drawTextAtS(ctx, .{ at[0], line_y }, slice, Color.toWire(ctx.style.text));
                line_y += ctx.style.font_size;
                // Skip leading spaces
                line_start = line_end;
                // Skip the spaces that separated the wrapped word, so the next line starts on a glyph
                // rather than inheriting the break's whitespace as leading indent.
                while (line_start < full.len and full[line_start] == ' ') {
                    line_start += 1;
                }
                line_end = line_start;
            } else {
                line_end = word_end;
            }
            // Force a break on explicit \n.
            if (i < full.len and full[i] == '\n') {
                if (line_end > line_start) {
                    const slice: []u8 = full[line_start..line_end];
                    drawTextAtS(ctx, .{ at[0], line_y }, slice, Color.toWire(ctx.style.text));
                    line_y += ctx.style.font_size;
                }
                line_start = i + 1;
                line_end = line_start;
            }
        }
    }
    // Trailing line.
    if (line_end > line_start) {
        const slice: []u8 = full[line_start..line_end];
        drawTextAtS(ctx, .{ at[0], line_y }, slice, Color.toWire(ctx.style.text));
        line_y += ctx.style.font_size;
    }

    const consumed = Vec2{ max_width, line_y - at[1] };
    advanceLayout(w, consumed, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

/// imgui-parity `LabelText`: render `label` on the LEFT and the
/// formatted value on the RIGHT of the same row. Used as a
/// readout in property panels. The value column starts at a
/// fixed offset from the row's left edge so consecutive label
/// rows visually align.
fn labelTextImpl(
    ctx: *UiContext,
    label: []const u8,
    comptime fmt: []const u8,
    args: anytype,
) void {
    const w: *Window = ctx.current_window orelse return;

    var buf: [256]u8 = undefined;
    const value_str: []u8 = bufPrint(&buf, fmt, args) catch buf[0..0];

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const value_w: f32 = measureTextS(ctx, value_str)[0];
    const label_w: f32 = measureTextS(ctx, label)[0];

    // imgui-parity: value rendered on the right of the line (or
    // at a fixed offset from row start). We follow the same
    // convention as in widget value-readouts: value first (which
    // is what the eye scans), then label. But ImGui's LabelText
    // is value-first → label-after on the same row.
    drawTextAtS(ctx, at, value_str, Color.toWire(ctx.style.text));
    if (label.len > 0) {
        const label_pos: Vec2 = .{ at[0] + value_w + ctx.style.item_spacing[0], at[1] };
        drawTextAtS(ctx, label_pos, label, Color.toWire(ctx.style.text));
    }

    const total_w: f32 = value_w + ctx.style.item_spacing[0] + label_w;
    advanceLayout(w, .{ total_w, ctx.style.font_size }, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

fn separatorTextImpl(ctx: *UiContext, label: []const u8) void {
    const w: *Window = ctx.current_window orelse return;

    // Hardcoded constants matching imgui's `style.SeparatorText*` defaults,
    // tweaked slightly. Imgui ships padding (20, 3) + border thickness 3;
    // we use border thickness 2 - 3px reads as a bit chunky next to zimr's
    // 1px plain `separator`, while 2px stays visually distinct as a
    // "section header" without overwhelming surrounding text. Promote
    // these to `Style` fields (`separator_text_padding`, `_border_size`,
    // `_align`) if a demo wants the control.
    const padding_x: f32 = 20;
    const padding_y: f32 = 3;
    const border_thickness: f32 = 2;

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const label_size: Vec2 = measureTextS(ctx, label);

    // Row height: enough for the label with padding, or at least the
    // border-only case (matches imgui's `ImMax(label.y + 2*pad.y, border)`).
    const row_height: f32 = @max(label_size[1] + padding_y * 2, border_thickness);

    // Row spans from cursor to the right edge of the window's work area
    // (window right minus right-side padding).
    const row_right_x: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const row_width: f32 = row_right_x - at[0];

    // Rules are drawn at the row's vertical centre. `rule_y` is the TOP
    // of the rule rect, so we subtract half the thickness to centre it.
    const rule_y: f32 = at[1] + row_height * 0.5 - border_thickness * 0.5;
    const rule_color: u32 = Color.toWire(ctx.style.border);

    if (label_size[0] > 0) {
        // Two-rule layout: short rule on left, label, long rule on right
        // filling to the row's right edge. imgui defaults
        // `SeparatorTextAlign.x = 0` which left-aligns the label, so the
        // left rule is just `padding_x` wide and the rest of the row goes
        // to the right rule.
        const left_rule_end_x: f32 = at[0] + padding_x;
        const label_x: f32 = left_rule_end_x + ctx.style.item_spacing[0];
        const label_y: f32 = at[1] + (row_height - label_size[1]) * 0.5;
        const right_rule_start_x: f32 = label_x + label_size[0] + ctx.style.item_spacing[0];

        // Left rule.
        drawRectFilled(ctx, .{
            .x = at[0],
            .y = rule_y,
            .width = left_rule_end_x - at[0],
            .height = border_thickness,
        }, rule_color);

        // Label.
        drawTextAtS(ctx, .{ label_x, label_y }, label, Color.toWire(ctx.style.text));

        // Right rule (if there's room for it after the label).
        const right_rule_width: f32 = row_right_x - right_rule_start_x;
        if (right_rule_width > 0) {
            drawRectFilled(ctx, .{
                .x = right_rule_start_x,
                .y = rule_y,
                .width = right_rule_width,
                .height = border_thickness,
            }, rule_color);
        }
        // NOTE: imgui's SeparatorTextEx sets `CursorPosPrevLine.x` to
        // `label_pos.x + label_size.x` so a subsequent `SameLine()`
        // places the next widget right after the label (between left
        // and right rules). zimr's layout state machine drives sameLine
        // off `cursor_max[0]`, which the `advanceLayout` below will set
        // to the row's right edge. Replicating the "sameLine after
        // separatorText lands next to the label" trick would require
        // splitting the advance into two parts (advance Y past the row,
        // but report consumed X as label_end). Deferred - no current
        // demo needs it.
    } else {
        // Empty label - degrade to a full-width rule at the row's centre.
        drawRectFilled(ctx, .{
            .x = at[0],
            .y = rule_y,
            .width = row_width,
            .height = border_thickness,
        }, rule_color);
    }

    // Bookkeeping. separatorText is not interactive, so no widget ID
    // and `last_item_hovered` stays false.
    w.layout.last_item_id = 0;
    w.layout.last_item_rect = .{ .x = at[0], .y = at[1], .width = row_width, .height = row_height };
    w.layout.last_item_hovered = false;

    advanceLayout(w, .{ row_width, row_height }, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

/// Returns true when the given focusable widget should treat this
/// frame as a synthesized click - i.e. it's the focused widget AND
/// Enter was pressed. Used by button/checkbox to wire keyboard
/// activation alongside their existing mouse-click handling.
fn triggerNavActivate(ctx: *const UiContext, id: Id) bool {
    const is_focused: bool = ctx.nav_id == id;
    if (!is_focused) {
        return false;
    }
    return ctx.input.keys[@backingInt(KeyCode.enter)].pressed_this_frame;
}

/// Per-widget post-bookkeeping: computes the activation-transition
/// flags (`isItemActivated`, `isItemDeactivated`,
/// `isItemDeactivatedAfterEdit`) and the click flag (`isItemClicked`)
/// from state already populated by the widget (`w.layout.last_item_id`,
/// `w.layout.last_item_hovered`).
/// Each widget calls this exactly once at the end of its submission,
/// passing whether the user mutated the value this frame
/// (`edited = true`). Most widgets pass `false` because they don't
/// mutate; the seven that do (checkbox, slider, drag, colorEdit,
/// combo, radioButton, inputText) pass `true` only on the frame the
/// mutation actually happened.
/// Centralising the transition logic here means each widget needs one
/// line of new code (`markItemPost(ctx, w, edited);`) rather than
/// re-implementing the active_id-vs-prev_active_id comparison inline
/// in 8 places.
fn markItemPost(
    ctx: *UiContext,
    w: *Window,
    edited: bool,
) void {
    const id: Id = w.layout.last_item_id;
    // Non-interactive items (text, image, bullet) record id=0 and
    // skip the activation-transition computation - their "active",
    // "clicked", "edited" queries should always return false.
    if (id == 0) {
        w.layout.last_item_edited = false;
        w.layout.last_item_clicked = false;
        w.layout.last_item_activated = false;
        w.layout.last_item_deactivated = false;
        w.layout.last_item_deactivated_after_edit = false;
        return;
    }
    w.layout.last_item_edited = edited;

    // Click detection: hovered AND mouse-down went from up → down
    // this frame. ImGui uses a richer timing model; this matches
    // `IsItemClicked` semantics in 95% of usage.
    w.layout.last_item_clicked = w.layout.last_item_hovered and ctx.input.mouse_left_clicked;

    // Activation transitions - derive from active_id vs.
    // active_id_prev_frame. An ID transitioning into active_id this
    // frame is "activated"; the reverse is "deactivated".
    const was_active: bool = (ctx.active_id_prev_frame == id);
    const is_active: bool = (ctx.active_id == id);
    w.layout.last_item_activated = is_active and !was_active;
    w.layout.last_item_deactivated = was_active and !is_active;

    // Sticky "was-edited-during-activation" flag on the context.
    // While the widget is active, any frame that reports `edited`
    // sets the flag; on deactivation we surface it through
    // `last_item_deactivated_after_edit`, then clear the sticky
    // value for the next activation.
    if (is_active and edited) {
        ctx.active_id_was_edited = true;
    }
    if (w.layout.last_item_deactivated) {
        w.layout.last_item_deactivated_after_edit = ctx.active_id_was_edited;
        ctx.active_id_was_edited = false;
    } else {
        w.layout.last_item_deactivated_after_edit = false;
    }
}

fn invisibleButtonImpl(
    ctx: *UiContext,
    id_str: []const u8,
    size_arg: Vec2,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, id_str);

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);

    // 0-on-axis means "use a sensible default." X: fill remaining row
    // width to the right-side window padding. Y: standard widget row
    // height (`font_size + 2 * frame_padding[1]`, matching imgui's
    // `GetFrameHeight()`). Mirrors imgui's `0 → -FLT_MIN → fill` for
    // the X axis.
    const row_right_x: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const available_x: f32 = row_right_x - at[0];
    const default_h: f32 = ctx.style.font_size + 2 * ctx.style.frame_padding[1];
    const size: Vec2 = .{
        if (size_arg[0] > 0) size_arg[0] else @max(available_x, 1),
        if (size_arg[1] > 0) size_arg[1] else default_h,
    };

    const rect: Rectangle = .{ .x = at[0], .y = at[1], .width = size[0], .height = size[1] };

    // Hit test + state machine. Same shape as buttonImpl - only the
    // draw step is omitted (that's the whole point of "invisible").
    const hovered: bool = itemHoverable(ctx, rect);
    if (hovered) {
        ctx.hovered_id = id;
    }

    var pressed: bool = false;
    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
    }
    if (ctx.active_id == id and ctx.input.mouse_left_released) {
        if (hovered) {
            pressed = true;
        }
        ctx.active_id = 0;
    }
    if (triggerNavActivate(ctx, id)) {
        pressed = true;
    }

    // NO draw. That's what makes it invisible.

    w.layout.last_item_id = id;
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false);
    // Skip `markItemNavigable` - imgui defaults `InvisibleButton` to
    // `NoNav` (Tab skips it) because invisible regions usually exist as
    // hit zones for other things and shouldn't gain focus indicators.
    // Add an `enable_nav: bool = false` opt later if a use case wants
    // tab focus on an invisible region.

    advanceLayout(w, size, ctx.style.item_spacing, ctx.style.window_padding[0]);
    return pressed;
}

pub const SliderOpts = struct {
    /// Lower bound (inclusive). Stored as f64 to be lossless across
    /// every numeric `value` pointer type the widget accepts.
    min: f64 = 0,
    /// Upper bound (inclusive).
    max: f64 = 1,
    /// Format string for the value display. `std.fmt`-compatible.
    /// For ints, `{d}` is appropriate; for floats, `{d:.3}`.
    fmt: []const u8 = "{d:.3}",
    /// Override the inline width (full row by default = window
    /// content width minus value-text width).
    width: f32 = 0,
};

/// Format a scalar (any int or float) into a fixed buffer using a
/// type-appropriate default format. `std.fmt.bufPrint` requires
/// comptime format strings, which means we can't honor the user's
/// `opts.fmt` field directly without making opts itself a comptime
/// argument - too invasive for. The defaults below match
/// what most users want:
///   - floats: 3 decimal places (`"{d:.3}"`)
///   - integers: no decimals (`"{d}"`)
/// may revisit with a comptime-format generic or an enum-of-
/// styles trick to make `opts.fmt` actually wire in.
fn formatScalar(
    buf: []u8,
    comptime T: type,
    v: T,
    _fmt_runtime: []const u8,
) []const u8 {
    _ = _fmt_runtime; // reserved for (see comment above)
    return switch (@typeInfo(T)) {
        .float => bufPrint(buf, "{d:.3}", .{v}) catch buf[0..0],
        .int => bufPrint(buf, "{d}", .{v}) catch buf[0..0],
        else => buf[0..0],
    };
}

/// Convert f64 back to any int/float (used to commit the new slider
/// value). Truncates for ints, casts for floats.
fn scalarFromF64(comptime T: type, v: f64) T {
    return switch (@typeInfo(T)) {
        .float => @floatCast(v),
        .int => @round(v),
        else => @compileError("scalarFromF64: unsupported"),
    };
}

/// Convert any int/float to f64 (used to position the slider grab).
fn scalarToF64(comptime T: type, v: T) f64 {
    return switch (@typeInfo(T)) {
        .float => @floatCast(v),
        .int => @floatFromInt(v),
        else => @compileError("scalarToF64: unsupported"),
    };
}

fn sliderScalar(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    comptime T: type,
    opts: SliderOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    // Layout: the bar fills available row width minus space for the
    // value text on the right. Label appears AFTER the bar (matches
    // ImGui), separated by item_spacing.
    const padding: Vec2 = ctx.style.frame_padding;
    const bar_h: f32 = ctx.style.font_size + 2 * padding[1];
    const label_size: Vec2 = measureTextS(ctx, label);

    // Compute current value text for sizing.
    var val_buf: [64]u8 = undefined;
    const val_str = formatScalar(&val_buf, T, value.*, opts.fmt);
    const val_size: Vec2 = measureTextS(ctx, val_str);

    const inner_w: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0] - (resolveCursor(
        w,
        ctx.style.item_spacing[0],
    )[0]);
    const value_text_reserve: f32 = val_size[0] + ctx.style.item_spacing[0];
    const label_reserve: f32 = label_size[0] + ctx.style.item_spacing[0];
    const default_bar_w: f32 = inner_w - label_reserve;
    var bar_w: f32 = effectiveItemWidth(ctx, opts.width, default_bar_w);
    if (bar_w < 60) {
        bar_w = 60; // sensible floor
    }

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const bar = Rectangle{ .x = at[0], .y = at[1], .width = bar_w, .height = bar_h };

    const hovered: bool = itemHoverable(ctx, bar);
    if (hovered) {
        ctx.hovered_id = id;
    }

    // State machine: clicking + holding within the bar puts us in
    // "active" mode; we update the value from mouse X every frame
    // until release. Clamp value to [min, max].
    var changed: bool = false;
    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        const t: f32 = clamp((ctx.input.mouse_pos[0] - bar.x) / bar.width, 0.0, 1.0);
        const new_f: f64 = opts.min + @as(f64, t) * (opts.max - opts.min);
        const new_v: T = scalarFromF64(T, new_f);
        if (new_v != value.*) {
            value.* = new_v;
            changed = true;
            // Re-render value text since it changed.
            _ = formatScalar(&val_buf, T, value.*, opts.fmt);
        }
    }

    // Draw bar background.
    const bar_bg: Color = if (ctx.active_id == id)
        ctx.style.frame_bg_active
    else if (hovered)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, bar, Color.toWire(bar_bg));

    // Draw the grab - a thin vertical bar at the value's position.
    const range: f64 = opts.max - opts.min;
    const tnorm: f32 = if (range > 0)
        @floatCast(clamp((@as(f64, scalarToF64(T, value.*)) - opts.min) / range, 0.0, 1.0))
    else
        0;
    const grab_w: f32 = 8;
    const grab_x: f32 = bar.x + tnorm * (bar.width - grab_w);
    const grab_color: Color = if (ctx.active_id == id)
        ctx.style.button_active
    else
        ctx.style.button;
    drawRectFilled(
        ctx,
        .{ .x = grab_x, .y = bar.y + 2, .width = grab_w, .height = bar.height - 4 },
        Color.toWire(grab_color),
    );

    // Draw value text centered in the bar.
    const val_pos = Vec2{ bar.x + (bar.width - val_size[0]) / 2, bar.y + (bar.height - ctx.style.font_size) / 2 };
    drawTextAtS(ctx, val_pos, val_str, Color.toWire(ctx.style.text));

    // Draw the label to the right of the bar.
    const label_pos = Vec2{
        bar.x + bar.width + ctx.style.item_spacing[0],
        bar.y + (bar.height - ctx.style.font_size) / 2,
    };
    drawTextAtS(ctx, label_pos, label, Color.toWire(ctx.style.text));

    // Bookkeeping.
    const total_w: f32 = bar.width + ctx.style.item_spacing[0] + label_size[0];
    w.layout.last_item_id = id;
    w.layout.last_item_rect = .{ .x = bar.x, .y = bar.y, .width = total_w, .height = bar.height };
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, changed);

    advanceLayout(w, .{ total_w, bar.height }, ctx.style.item_spacing, ctx.style.window_padding[0]);
    _ = value_text_reserve; // future: position value text outside bar
    return changed;
}

fn sliderDispatch(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    opts: SliderOpts,
) bool {
    // lint #1: slider's range must be valid — min < max. Equal
    // bounds produce a degenerate bar with no usable thumb travel and
    // hidden divide-by-zero behavior inside normaliseValue. Warns
    // once per call site for the process lifetime.
    if (opts.min >= opts.max) {
        warnOnce(
            @src(),
            "ui.slider({s}): degenerate range — min={d} >= max={d}",
            .{ label, opts.min, opts.max },
        );
    }
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.slider: pass a single-item pointer (e.g., &my_value), got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    return switch (@typeInfo(Child)) {
        .float => sliderScalar(ctx, label, value, Child, opts),
        .int => sliderScalar(ctx, label, value, Child, opts),
        .array => |arr| blk: {
            // Multi-component slider: `*[N]T` renders N narrow bars
            // side-by-side, each with its own click+drag state, sharing
            // the row width. Element type still has to be float or int.
            switch (@typeInfo(arr.child)) {
                .float, .int => {},
                else => @compileError("ui.slider: array element must be float or int, got " ++ @typeName(arr.child)),
            }
            break :blk sliderArray(ctx, label, value, arr.child, arr.len, opts);
        },
        else => @compileError("ui.slider: child type must be float, int, or [N]float/int, got " ++ @typeName(Child)),
    };
}

fn colorEditColor(
    ctx: *UiContext,
    label: []const u8,
    value: *Color,
    opts: ColorEditOpts,
) bool {
    // Convert to [4]f32, edit, convert back. Lossy at ±1/255 per
    // channel, fine for a color picker.
    var f4: [4]f32 = .{
        float(value.r) / 255.0,
        float(value.g) / 255.0,
        float(value.b) / 255.0,
        float(value.a) / 255.0,
    };
    const changed: bool = colorEditNFloat(ctx, label, &f4, 4, opts);
    if (changed) {
        value.* = .{
            .r = @trunc(clamp(f4[0], 0.0, 1.0) * 255),
            .g = @trunc(clamp(f4[1], 0.0, 1.0) * 255),
            .b = @trunc(clamp(f4[2], 0.0, 1.0) * 255),
            .a = @trunc(clamp(f4[3], 0.0, 1.0) * 255),
        };
    }
    return changed;
}

fn colorEditDispatch(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    opts: ColorEditOpts,
) bool {
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.colorEdit: pass a single-item pointer, got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    // The Float3/Float4 cases are just colorEditNFloat with the
    // channel count bound at the call site - no need for separate
    // shim functions. The Color case has its own implementation
    // (handles u8 channels + alpha differently).
    if (Child == [3]f32) {
        return colorEditNFloat(ctx, label, value, 3, opts);
    }
    if (Child == [4]f32) {
        return colorEditNFloat(ctx, label, value, 4, opts);
    }
    if (Child == Color) {
        return colorEditColor(ctx, label, value, opts);
    }
    @compileError("ui.colorEdit: pointed-to type must be [3]f32, [4]f32, or zimr Color, got " ++ @typeName(Child));
}

pub const PlotOpts = struct {
    /// Optional overlay text drawn centered near the top of the
    /// plot frame. Typical use: current value or a stat summary.
    overlay: []const u8 = "",
    /// Value-axis lower bound. When `min == max`, the plot
    /// auto-fits to the observed data range each frame.
    min: f32 = 0,
    /// Value-axis upper bound. See `min`.
    max: f32 = 0,
    /// Plot frame width. Zero = fill remaining row width.
    width: f32 = 0,
    /// Plot frame height in pixels. Zero = default of 80.
    height: f32 = 0,
};

/// Pack four normalized floats into a ColorU32 in zimr's RGBA8
/// wire format.
fn packF(r: f32, g: f32, b: f32, a: f32) ColorU32 {
    return Color.fromFloats(r, g, b, a).toWire();
}

/// Horizontal hue gradient. `segments` controls smoothness.
fn drawHueStrip(
    dl: *DrawList,
    alloc: Allocator,
    rect: Rectangle,
    segments: u32,
) void {
    const seg_w: f32 = rect.width / float(segments);
    var i: u32 = 0;
    while (i < segments) : (i += 1) {
        const h: f32 = float(i) / float(segments);
        const rgb: [3]f32 = hsvToRgb3(h, 1, 1);
        const col: ColorU32 = packF(rgb[0], rgb[1], rgb[2], 1);
        dl.addRectFilled(alloc, .{
            .x = rect.x + float(i) * seg_w,
            .y = rect.y,
            .width = seg_w + 1,
            .height = rect.height,
        }, col);
    }
}

/// SV box at fixed hue. Drawn as a vertical stack of slim slabs.
/// Each slab samples value at its y position and renders a 2-color
/// (S=0 dark, S=1 fully saturated) horizontal gradient.
fn drawSvBox(
    dl: *DrawList,
    alloc: Allocator,
    rect: Rectangle,
    h: f32,
    slabs: u32,
) void {
    const slab_h: f32 = rect.height / float(slabs);
    var i: u32 = 0;
    while (i < slabs) : (i += 1) {
        const v: f32 = 1.0 - (float(i) / float(slabs - 1));
        const rgb_left: [3]f32 = hsvToRgb3(h, 0, v);
        const rgb_right: [3]f32 = hsvToRgb3(h, 1, v);
        const c_l: ColorU32 = packF(rgb_left[0], rgb_left[1], rgb_left[2], 1);
        const c_r: ColorU32 = packF(rgb_right[0], rgb_right[1], rgb_right[2], 1);
        dl.addRectFilledMultiColor(alloc, .{
            .x = rect.x,
            .y = rect.y + float(i) * slab_h,
            .width = rect.width,
            .height = slab_h + 1,
        }, c_l, c_r, c_r, c_l);
    }
}

fn handleHueBar(
    ctx: *UiContext,
    rect: Rectangle,
    id: Id,
    h_ptr: *f32,
    changed: *bool,
) void {
    if (itemHoverable(ctx, rect) and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        const h_new: f32 = clamp((ctx.input.mouse_pos[0] - rect.x) / rect.width, 0, 1);
        if (h_new != h_ptr.*) {
            h_ptr.* = h_new;
            changed.* = true;
        }
    }
}

fn handleSvBox(
    ctx: *UiContext,
    rect: Rectangle,
    id: Id,
    s_ptr: *f32,
    v_ptr: *f32,
    changed: *bool,
) void {
    if (itemHoverable(ctx, rect) and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        const s_new: f32 = clamp((ctx.input.mouse_pos[0] - rect.x) / rect.width, 0, 1);
        const v_new: f32 = clamp(1.0 - (ctx.input.mouse_pos[1] - rect.y) / rect.height, 0, 1);
        if (s_new != s_ptr.* or v_new != v_ptr.*) {
            s_ptr.* = s_new;
            v_ptr.* = v_new;
            changed.* = true;
        }
    }
}

/// Alpha bar - current color from full-alpha (right) to zero-alpha
/// (left), letting users see the result of alpha blending against
/// the window background.
fn drawAlphaBar(
    dl: *DrawList,
    alloc: Allocator,
    rect: Rectangle,
    r: f32,
    g: f32,
    b: f32,
) void {
    const c0: ColorU32 = packF(r, g, b, 0);
    const c1: ColorU32 = packF(r, g, b, 1);
    dl.addRectFilledMultiColor(alloc, rect, c0, c1, c1, c0);
}

fn handleAlphaBar(
    ctx: *UiContext,
    rect: Rectangle,
    id: Id,
    a_ptr: *f32,
    changed: *bool,
) void {
    if (itemHoverable(ctx, rect) and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        const a_new: f32 = clamp((ctx.input.mouse_pos[0] - rect.x) / rect.width, 0, 1);
        if (a_new != a_ptr.*) {
            a_ptr.* = a_new;
            changed.* = true;
        }
    }
}

/// Hue ring drawn as N wedges (filled triangles). `inner_r` is
/// the SV-box bound; the ring fills `[inner_r, outer_r]`.
fn drawHueRing(
    dl: *DrawList,
    alloc: Allocator,
    center: Vec2,
    outer_r: f32,
    inner_r: f32,
    segments: u32,
) void {
    const da: f32 = tau / float(segments);
    var i: u32 = 0;
    while (i < segments) : (i += 1) {
        const a0: f32 = float(i) * da;
        const a1: f32 = a0 + da;
        const h_mid: f32 = (float(i) + 0.5) / float(segments);
        const rgb: [3]f32 = hsvToRgb3(h_mid, 1, 1);
        const col: ColorU32 = packF(rgb[0], rgb[1], rgb[2], 1);
        // Two triangles per wedge: outer-a0 / outer-a1 / inner-a0 +
        // outer-a1 / inner-a1 / inner-a0.
        const o0: Vec2 = .{ center[0] + @cos(a0) * outer_r, center[1] + @sin(a0) * outer_r };
        const o1: Vec2 = .{ center[0] + @cos(a1) * outer_r, center[1] + @sin(a1) * outer_r };
        const in_a: Vec2 = .{ center[0] + @cos(a0) * inner_r, center[1] + @sin(a0) * inner_r };
        const in_b: Vec2 = .{ center[0] + @cos(a1) * inner_r, center[1] + @sin(a1) * inner_r };
        dl.addTriangleFilled(alloc, o0, o1, in_a, col);
        dl.addTriangleFilled(alloc, o1, in_b, in_a, col);
    }
}

fn handleHueRing(
    ctx: *UiContext,
    center: Vec2,
    outer_r: f32,
    inner_r: f32,
    id: Id,
    h_ptr: *f32,
    changed: *bool,
) void {
    const dx: f32 = ctx.input.mouse_pos[0] - center[0];
    const dy: f32 = ctx.input.mouse_pos[1] - center[1];
    const d2: f32 = dx * dx + dy * dy;
    const in_ring: bool = d2 >= inner_r * inner_r and d2 <= outer_r * outer_r;
    if (in_ring and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        var ang: f32 = atan2Rad(dy, dx);
        if (ang < 0) {
            ang += tau;
        }
        const h_new: f32 = ang / tau;
        if (h_new != h_ptr.*) {
            h_ptr.* = h_new;
            changed.* = true;
        }
    }
}

fn drawAlphaBarVertical(
    dl: *DrawList,
    alloc: Allocator,
    rect: Rectangle,
    r: f32,
    g: f32,
    b: f32,
) void {
    const c0: ColorU32 = packF(r, g, b, 0); // bottom = alpha 0
    const c1: ColorU32 = packF(r, g, b, 1); // top = alpha 1
    dl.addRectFilledMultiColor(alloc, rect, c1, c1, c0, c0);
}

fn handleAlphaBarVertical(
    ctx: *UiContext,
    rect: Rectangle,
    id: Id,
    a_ptr: *f32,
    changed: *bool,
) void {
    if (itemHoverable(ctx, rect) and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        const a_new: f32 = clamp(1.0 - (ctx.input.mouse_pos[1] - rect.y) / rect.height, 0, 1);
        if (a_new != a_ptr.*) {
            a_ptr.* = a_new;
            changed.* = true;
        }
    }
}

/// Core picker impl. All inputs are f32 in [0, 1]. Pass `a_ptr =
/// null` to disable the alpha bar. The bar layout draws a hue
/// strip + an SV box (sat horizontal, value vertical). The wheel
/// layout draws a hue ring with an SV square inscribed.
/// Convention: SV box has S=0 at left, S=1 at right, V=1 at top,
/// V=0 at bottom - matches imgui.
fn colorPickerImpl(
    ctx: *UiContext,
    label: []const u8,
    r_ptr: *f32,
    g_ptr: *f32,
    b_ptr: *f32,
    a_ptr: ?*f32,
    opts: ColorPickerOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const dl: *DrawList = &w.draw_list;
    const arena: Allocator = ctx.frame_arena.allocator();
    const parent_id: Id = widgetId(ctx, w, label);

    const size: f32 = if (opts.size > 0) opts.size else 180;
    const start: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);

    // Always work in HSV space inside the picker.
    var hsv: [3]f32 = rgbToHsv3(r_ptr.*, g_ptr.*, b_ptr.*);
    var alpha_val: f32 = if (a_ptr) |ap| ap.* else 1.0;

    var any_changed: bool = false;

    // ---- Layout
    // Both layouts share: SV box on the right, swatch + label below.
    // .bar adds a hue strip ABOVE the SV box.
    // .wheel adds a hue ring AROUND the SV box (slightly larger
    //   footprint for the ring radius).

    switch (opts.layout) {
        .bar => {
            // Hue strip: thin horizontal gradient across `size` width
            // above the SV box.
            const hue_h: f32 = 16;
            const hue_rect: Rectangle = .{ .x = start[0], .y = start[1], .width = size, .height = hue_h };
            drawHueStrip(dl, arena, hue_rect, 64);

            const sv_rect: Rectangle = .{ .x = start[0], .y = start[1] + hue_h + 4, .width = size, .height = size };
            // SV gradient drawn as a vertical stack of slim
            // horizontal slabs. Each slab is one V level; within a
            // slab we use a 2-color gradient from (h,0,V)→(h,1,V).
            drawSvBox(dl, arena, sv_rect, hsv[0], 24);

            // Interaction: hue strip drag, then SV box drag.
            const hue_id: Id = hashInt(parent_id, 0);
            const sv_id: Id = hashInt(parent_id, 1);
            handleHueBar(ctx, hue_rect, hue_id, &hsv[0], &any_changed);
            handleSvBox(ctx, sv_rect, sv_id, &hsv[1], &hsv[2], &any_changed);

            // Indicator: a small ring at the active hue / SV point.
            const hx: f32 = hue_rect.x + hsv[0] * hue_rect.width;
            dl.addLine(arena, .{ hx, hue_rect.y - 1 }, .{ hx, hue_rect.y + hue_rect.height + 1 }, 0xFF000000, 2);
            const sx: f32 = sv_rect.x + hsv[1] * sv_rect.width;
            const sy: f32 = sv_rect.y + (1.0 - hsv[2]) * sv_rect.height;
            dl.addCircle(arena, .{ sx, sy }, 6, 0xFFFFFFFF, 2, 16);

            // Optional alpha bar BELOW the SV box.
            if (a_ptr != null) {
                const alpha_rect: Rectangle = .{
                    .x = start[0],
                    .y = sv_rect.y + sv_rect.height + 4,
                    .width = size,
                    .height = hue_h,
                };
                drawAlphaBar(dl, arena, alpha_rect, r_ptr.*, g_ptr.*, b_ptr.*);
                const alpha_id: Id = hashInt(parent_id, 2);
                handleAlphaBar(ctx, alpha_rect, alpha_id, &alpha_val, &any_changed);
                const ax: f32 = alpha_rect.x + alpha_val * alpha_rect.width;
                dl.addLine(
                    arena,
                    .{ ax, alpha_rect.y - 1 },
                    .{ ax, alpha_rect.y + alpha_rect.height + 1 },
                    0xFF000000,
                    2,
                );
            }
        },
        .wheel => {
            // Wheel: hue ring around the picker, SV box inscribed.
            const radius: f32 = size * 0.5;
            const center: Vec2 = .{ start[0] + radius, start[1] + radius };
            const inner_r: f32 = radius - 18; // ring thickness 18
            drawHueRing(dl, arena, center, radius, inner_r, 96);

            // Inscribed SV box - a square inside the inner radius.
            const box_size: f32 = inner_r * sqrt1_2 * 1.6;
            const sv_rect: Rectangle = .{
                .x = center[0] - box_size * 0.5,
                .y = center[1] - box_size * 0.5,
                .width = box_size,
                .height = box_size,
            };
            drawSvBox(dl, arena, sv_rect, hsv[0], 24);

            const hue_id: Id = hashInt(parent_id, 0);
            const sv_id: Id = hashInt(parent_id, 1);
            handleHueRing(ctx, center, radius, inner_r, hue_id, &hsv[0], &any_changed);
            handleSvBox(ctx, sv_rect, sv_id, &hsv[1], &hsv[2], &any_changed);

            // Ring indicator + SV cursor.
            const ang: f32 = hsv[0] * tau;
            const r_mid: f32 = (radius + inner_r) * 0.5;
            const ind_x: f32 = center[0] + @cos(ang) * r_mid;
            const ind_y: f32 = center[1] + @sin(ang) * r_mid;
            dl.addCircle(arena, .{ ind_x, ind_y }, 5, 0xFFFFFFFF, 2, 16);
            const sx: f32 = sv_rect.x + hsv[1] * sv_rect.width;
            const sy: f32 = sv_rect.y + (1.0 - hsv[2]) * sv_rect.height;
            dl.addCircle(arena, .{ sx, sy }, 6, 0xFFFFFFFF, 2, 16);

            if (a_ptr != null) {
                // Alpha bar to the right of the wheel.
                const alpha_rect: Rectangle = .{ .x = start[0] + size + 4, .y = start[1], .width = 16, .height = size };
                drawAlphaBarVertical(dl, arena, alpha_rect, r_ptr.*, g_ptr.*, b_ptr.*);
                const alpha_id: Id = hashInt(parent_id, 2);
                handleAlphaBarVertical(ctx, alpha_rect, alpha_id, &alpha_val, &any_changed);
                const ay: f32 = alpha_rect.y + (1.0 - alpha_val) * alpha_rect.height;
                dl.addLine(
                    arena,
                    .{ alpha_rect.x - 1, ay },
                    .{ alpha_rect.x + alpha_rect.width + 1, ay },
                    0xFF000000,
                    2,
                );
            }
        },
    }

    // Convert HSV back to RGB if anything changed.
    if (any_changed) {
        const rgb: [3]f32 = hsvToRgb3(hsv[0], hsv[1], hsv[2]);
        r_ptr.* = rgb[0];
        g_ptr.* = rgb[1];
        b_ptr.* = rgb[2];
        if (a_ptr) |ap| {
            ap.* = alpha_val;
        }
    }

    // Final swatch + label below the picker.
    const total_h: f32 = switch (opts.layout) {
        .bar => size + 16 + 4 + (if (a_ptr != null) @as(f32, 16 + 4) else 0),
        .wheel => size,
    };
    const swatch_y: f32 = start[1] + total_h + 6;
    const swatch_rect: Rectangle = .{ .x = start[0], .y = swatch_y, .width = 40, .height = 20 };
    const final_col: Color = .{
        .r = @trunc(clamp(r_ptr.* * 255.0, 0, 255)),
        .g = @trunc(clamp(g_ptr.* * 255.0, 0, 255)),
        .b = @trunc(clamp(b_ptr.* * 255.0, 0, 255)),
        .a = @trunc(clamp(alpha_val * 255.0, 0, 255)),
    };
    dl.addRectFilled(arena, swatch_rect, Color.toWire(final_col));

    if (label.len > 0) {
        const label_pos: Vec2 = .{
            swatch_rect.x + swatch_rect.width + ctx.style.item_spacing[0],
            swatch_rect.y + (swatch_rect.height - ctx.style.font_size) * 0.5,
        };
        drawTextAtS(ctx, label_pos, label, Color.toWire(ctx.style.text));
    }

    const total_consumed_h: f32 = total_h + 6 + 20;
    const total_consumed_w: f32 = switch (opts.layout) {
        .bar => size,
        .wheel => size + (if (a_ptr != null) @as(f32, 4 + 16) else 0),
    };
    w.layout.last_item_id = parent_id;
    w.layout.last_item_rect = .{ .x = start[0], .y = start[1], .width = total_consumed_w, .height = total_consumed_h };
    markItemPost(ctx, w, any_changed);

    advanceLayout(
        w,
        .{ total_consumed_w, total_consumed_h },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return any_changed;
}

/// Color picker over zimr `Color` (u8 RGBA). Converts to f32,
/// runs the picker, writes back on change.
fn colorPickerColor(
    ctx: *UiContext,
    label: []const u8,
    value: *Color,
    opts: ColorPickerOpts,
) bool {
    var r: f32 = float(value.r) / 255.0;
    var g: f32 = float(value.g) / 255.0;
    var b: f32 = float(value.b) / 255.0;
    var a: f32 = float(value.a) / 255.0;
    const changed: bool = colorPickerImpl(ctx, label, &r, &g, &b, if (opts.alpha) &a else null, opts);
    if (changed) {
        value.r = @trunc(clamp(r * 255.0, 0, 255));
        value.g = @trunc(clamp(g * 255.0, 0, 255));
        value.b = @trunc(clamp(b * 255.0, 0, 255));
        value.a = @trunc(clamp(a * 255.0, 0, 255));
    }
    return changed;
}

fn colorPickerDispatch(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    opts: ColorPickerOpts,
) bool {
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.colorPicker: pass a single-item pointer, got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    return switch (@typeInfo(Child)) {
        .array => |arr| blk: {
            if (arr.child != f32) {
                @compileError("ui.colorPicker: array element must be f32, got " ++ @typeName(arr.child));
            }
            if (arr.len == 3) {
                break :blk colorPickerImpl(ctx, label, &value[0], &value[1], &value[2], null, opts);
            }
            if (arr.len == 4) {
                break :blk colorPickerImpl(ctx, label, &value[0], &value[1], &value[2], &value[3], opts);
            }
            @compileError("ui.colorPicker: array length must be 3 or 4, got " ++ @as(
                []const u8,
                std.fmt.comptimePrint("{d}", .{arr.len}),
            ));
        },
        .@"struct" => blk: {
            // Treat as zimr Color (u8 RGBA). Convert u8 → f32 in,
            // back out on change.
            if (Child != Color) {
                @compileError("ui.colorPicker: pointed-to struct must be zimr Color, got " ++ @typeName(Child));
            }
            break :blk colorPickerColor(ctx, label, value, opts);
        },
        else => @compileError(
            "ui.colorPicker: pointed-to type must be [3]f32, [4]f32, or zimr Color, got " ++ @typeName(Child),
        ),
    };
}

pub const DragOpts = struct {
    /// Pixels of mouse drag per unit value change. `0.01` ⇒ very
    /// fine; `1.0` ⇒ coarse. Sign of speed never inverted.
    speed: f32 = 1.0,
    /// Lower clamp (inclusive). Stored f64 to be lossless across
    /// every numeric pointer type the widget accepts. Set
    /// `min == max` to disable clamping.
    min: f64 = 0,
    /// Upper clamp (inclusive). See `min`.
    max: f64 = 0,
    /// Inline width override (default: 80 - narrower than slider).
    width: f32 = 80,
    /// Reserved - see comment in `formatScalar`. Currently ignored.
    fmt: []const u8 = "{d:.3}",
};

fn dragScalar(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    comptime T: type,
    opts: DragOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    const padding: Vec2 = ctx.style.frame_padding;
    const bar_h: f32 = ctx.style.font_size + 2 * padding[1];
    const bar_w: f32 = effectiveItemWidth(ctx, opts.width, 80);
    const label_size: Vec2 = measureTextS(ctx, label);

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const bar = Rectangle{ .x = at[0], .y = at[1], .width = bar_w, .height = bar_h };

    const hovered: bool = itemHoverable(ctx, bar);
    if (hovered) {
        ctx.hovered_id = id;
    }

    var changed: bool = false;
    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
    }
    if (ctx.active_id == id and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }
    if (ctx.active_id == id) {
        // Pixel-delta drag: each frame's horizontal mouse motion moves
        // the value by speed * delta. We re-derive delta by
        // remembering the previous mouse_pos in the active_id state.
        // For, simple-and-correct: derive delta from
        // (current - press position) and scale. More finicky than
        // ImGui's per-frame accumulation but easy to reason about.
        const cur_f: f64 = scalarToF64(T, value.*);
        const dx: f32 = ctx.input.mouse_pos[0] - ctx.active_id_press_x;
        const new_f: f64 = ctx.active_id_press_value + @as(f64, dx) * @as(f64, opts.speed);
        const clamped: f64 = if (opts.min == opts.max)
            new_f
        else
            clamp(new_f, opts.min, opts.max);
        if (clamped != cur_f) {
            value.* = scalarFromF64(T, clamped);
            changed = true;
        }
    }
    if (ctx.active_id == id and ctx.active_id_just_activated) {
        // First-frame-of-active: snapshot the press position + initial
        // value so subsequent frames can compute correct deltas.
        ctx.active_id_press_x = ctx.input.mouse_pos[0];
        ctx.active_id_press_value = scalarToF64(T, value.*);
    }

    // Draw bar background.
    const bg: Color = if (ctx.active_id == id)
        ctx.style.frame_bg_active
    else if (hovered)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, bar, Color.toWire(bg));

    // Draw value text centered.
    var val_buf: [64]u8 = undefined;
    const val_str = formatScalar(&val_buf, T, value.*, opts.fmt);
    const val_size: Vec2 = measureTextS(ctx, val_str);
    drawTextAtS(
        ctx,
        .{ bar.x + (bar.width - val_size[0]) / 2, bar.y + (bar.height - ctx.style.font_size) / 2 },
        val_str,
        Color.toWire(ctx.style.text),
    );

    // Draw label to the right.
    drawTextAtS(
        ctx,
        .{ bar.x + bar.width + ctx.style.item_spacing[0], bar.y + (bar.height - ctx.style.font_size) / 2 },
        label,
        Color.toWire(ctx.style.text),
    );

    const total_w: f32 = bar.width + ctx.style.item_spacing[0] + label_size[0];
    w.layout.last_item_id = id;
    w.layout.last_item_rect = .{ .x = bar.x, .y = bar.y, .width = total_w, .height = bar.height };
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, changed);

    advanceLayout(w, .{ total_w, bar.height }, ctx.style.item_spacing, ctx.style.window_padding[0]);
    return changed;
}

fn dragDispatch(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    opts: DragOpts,
) bool {
    // lint #2: drag range — `min == max` is the documented
    // "disable clamping" sentinel (see DragOpts.min docstring), so
    // we only warn on STRICTLY inverted bounds (min > max) which
    // can never produce a valid clamp.
    if (opts.min > opts.max) {
        warnOnce(
            @src(),
            "ui.drag({s}): inverted clamp — min={d} > max={d}",
            .{ label, opts.min, opts.max },
        );
    }
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.drag: pass a single-item pointer (e.g., &my_value), got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    return switch (@typeInfo(Child)) {
        .float => dragScalar(ctx, label, value, Child, opts),
        .int => dragScalar(ctx, label, value, Child, opts),
        .array => |arr| blk: {
            switch (@typeInfo(arr.child)) {
                .float, .int => {},
                else => @compileError("ui.drag: array element must be float or int, got " ++ @typeName(arr.child)),
            }
            break :blk dragArray(ctx, label, value, arr.child, arr.len, opts);
        },
        else => @compileError("ui.drag: child type must be float, int, or [N]float/int, got " ++ @typeName(Child)),
    };
}

pub const SelectableOpts = struct {
    /// Override row width. Zero means use the remaining content
    /// width (full-row selectable, like ImGui's default).
    width: f32 = 0,
};

/// Splitter axis. `.x` = vertical bar splitting left from right
/// (drag along X); `.y` = horizontal bar splitting top from bottom
/// (drag along Y). Names refer to the AXIS OF MOTION (x = bar
/// moves horizontally), matching imgui's `ImGuiAxis_X` / `_Y`
/// convention (`imgui_internal.h`).
pub const SplitterAxis = enum { x, y };

pub const SplitterOpts = struct {
    /// Visible bar thickness in pixels. Default 4 - pro-looking
    /// thin bar without being fragile.
    bar_width: f32 = 4,
    /// Invisible interaction-zone padding perpendicular to the
    /// axis (added to each side of the visible bar). Default 16
    /// → 36px total hit zone with a 4px bar. Forgiving on touch
    /// without making the visible bar chunky. Imgui:
    /// `hover_extend`.
    hit_extend: f32 = 16,
    /// Minimum size for the first pane (the one whose size is
    /// directly `*split_pos`). `*split_pos` is clamped against
    /// this on drag. Default 0 (no minimum).
    min1: f32 = 0,
    /// Minimum size for the second pane. Computed against the
    /// available size at draw time (caller must pass via
    /// `total_along_axis`). Default 0 (no minimum).
    min2: f32 = 0,
    /// Total available size along the splitter's axis (used to
    /// compute pane-2's clamp). Zero means "use the remaining
    /// content area on this axis" (i.e. cursor → window edge).
    total_along_axis: f32 = 0,
};

fn splitterImpl(
    ctx: *UiContext,
    str_id: []const u8,
    split_pos: *f32,
    axis: SplitterAxis,
    opts: SplitterOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, str_id);

    const cur: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);

    // Compute the total along-axis size - caller-provided or
    // remaining content area on this axis.
    const total: f32 = if (opts.total_along_axis > 0)
        opts.total_along_axis
    else switch (axis) {
        .x => @max(0, w.pos[0] + w.size[0] - ctx.style.window_padding[0] - cur[0]),
        .y => @max(0, w.pos[1] + w.size[1] - ctx.style.window_padding[1] - cur[1]),
    };

    // The "perpendicular" extent - how thick is the splitter strip
    // relative to its perpendicular axis? For an.x (vertical) bar
    // it's the available height; for.y (horizontal) it's the width.
    // The bar visually spans the perpendicular axis fully so it
    // separates the two panes visibly.
    const perp_extent: f32 = switch (axis) {
        .x => @max(0, w.pos[1] + w.size[1] - ctx.style.window_padding[1] - cur[1]),
        .y => @max(0, w.pos[0] + w.size[0] - ctx.style.window_padding[0] - cur[0]),
    };

    // Visible-bar rect. Located AT the cursor position - the caller
    // positions the splitter via `sameLine` after the first pane's
    // endChild, so the cursor is already at the boundary between the
    // two panes. `split_pos` is the size of pane 1 (state the
    // splitter mutates on drag), NOT an offset from the cursor.
    // Was a bug in the original impl: bar.x was
    // `cur[0] + split_pos`, which combined with the
    // `sameLine`-after-endChild flow meant the bar rendered at
    // tree_right + left_w - i.e., a left_w offset past where it
    // should sit. Discovered.
    const bar_rect: Rectangle = switch (axis) {
        .x => .{
            .x = cur[0],
            .y = cur[1],
            .width = opts.bar_width,
            .height = perp_extent,
        },
        .y => .{
            .x = cur[0],
            .y = cur[1],
            .width = perp_extent,
            .height = opts.bar_width,
        },
    };

    // Interact rect: visible expanded by hit_extend perpendicular.
    // This makes the bar grabbable from the wider hot zone while
    // keeping the visual thin. Matches imgui's `bb_interact` from
    // `bb.Expand(...)` at imgui_widgets.cpp:1819.
    const interact_rect: Rectangle = switch (axis) {
        .x => .{
            .x = bar_rect.x - opts.hit_extend,
            .y = bar_rect.y,
            .width = bar_rect.width + 2 * opts.hit_extend,
            .height = bar_rect.height,
        },
        .y => .{
            .x = bar_rect.x,
            .y = bar_rect.y - opts.hit_extend,
            .width = bar_rect.width,
            .height = bar_rect.height + 2 * opts.hit_extend,
        },
    };

    const hovered: bool = itemHoverable(ctx, interact_rect);
    if (hovered) {
        ctx.hovered_id = id;
    }

    // Press start: snapshot the click offset so we can compute the
    // mouse-delta relative to where the user grabbed. Matches
    // imgui's `g.ActiveIdClickOffset`.
    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
        // Stash the offset between cursor and the bar's interact
        // origin on the relevant axis. Re-derived each frame from
        // `mouse - bar_interact.origin` (a held splitter always has
        // mouse position; if mouse left the hot zone, drag still
        // continues because active_id is sticky).
    }

    const held: bool = (ctx.active_id == id and ctx.input.mouse_left_down);

    // Drag handling.
    if (held) {
        // mouse_delta = mouse along axis - bar's current along-axis
        // origin. This is the same as imgui's
        // `(mouse - active_id_click_offset - bb_interact.min)[axis]`
        // because we treat bar position as the implicit reference;
        // any deviation between mouse and bar mid-line IS the delta
        // to apply.
        const mouse_along: f32 = switch (axis) {
            .x => ctx.input.mouse_pos[0],
            .y => ctx.input.mouse_pos[1],
        };
        const bar_origin_along: f32 = switch (axis) {
            .x => bar_rect.x + bar_rect.width * 0.5,
            .y => bar_rect.y + bar_rect.height * 0.5,
        };
        var delta: f32 = mouse_along - bar_origin_along;

        // Clamp against min sizes. Pane 1 = split_pos; can't go
        // below min1. Pane 2 = total - split_pos - bar_width; can't
        // go below min2 (i.e. split_pos can't exceed total - min2 -
        // bar_width).
        const max_delta_neg: f32 = -(split_pos.* - opts.min1); // most-negative legal delta
        const max_delta_pos: f32 = total - split_pos.* - opts.bar_width - opts.min2;
        if (delta < max_delta_neg) {
            delta = max_delta_neg;
        }
        if (delta > max_delta_pos) {
            delta = max_delta_pos;
        }

        if (delta != 0) {
            split_pos.* += delta;
        }
    }

    // Release: clear active.
    if (ctx.active_id == id and ctx.input.mouse_left_released) {
        ctx.active_id = 0;
    }

    // No recompute needed - bar position is at the cursor, which
    // doesn't move during this widget's execution. `split_pos` may
    // have been mutated by the drag; that change applies on the
    // NEXT frame when the caller uses the new value to size pane 1.
    // (Imgui has the same 1-frame visual lag for drag feedback.)
    const render_rect: Rectangle = bar_rect;

    // Color: held > hovered > idle. Reuses button-family colors;
    // imgui has dedicated Separator/SeparatorHovered/SeparatorActive
    // slots - filed as polish (extract dedicated Style fields if
    // more widgets want separator colors).
    const col_u32: ColorU32 = if (held)
        Color.toWire(ctx.style.button_active)
    else if (hovered)
        Color.toWire(ctx.style.button_hovered)
    else
        Color.toWire(ctx.style.button);
    drawRectFilled(ctx, render_rect, col_u32);

    w.layout.last_item_id = id;
    w.layout.last_item_rect = render_rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, held); // splitter mutates on drag

    // Layout: only advance along the splitter's axis by bar_width.
    // Perpendicular extent doesn't consume parent cursor - the
    // caller has already accounted for it via beginChild's height
    // for the panes. The splitter looks like a thin "spacer" of
    // bar_width × perp_extent from the layout's perspective.
    switch (axis) {
        .x => advanceLayout(w, .{ opts.bar_width, 0 }, ctx.style.item_spacing, ctx.style.window_padding[0]),
        .y => advanceLayout(w, .{ 0, opts.bar_width }, ctx.style.item_spacing, ctx.style.window_padding[0]),
    }

    return held;
}

/// Flags for `beginMultiSelect`. Per zimr's flag-decision rule, exclusive
/// groups become enums; independent options stay bools.
/// Sourced from `imgui.h:3027-3055` (ImGuiMultiSelectFlags_). 6 fields
/// are wired in MVP (marked ✓ below); the other 11 exist in the struct
/// from day 1 so future steps can fill them in without API churn.
pub const MultiSelectFlags = struct {
    // ---- Selection model (exclusive group) ----
    /// `.multi` (default) allows multiple selected items. `.single`
    /// forces single-selection; the API shape stays identical, useful
    /// when toggling a list between single ↔ multi modes. Imgui:
    /// `ImGuiMultiSelectFlags_SingleSelect`. ✓ MVP.
    selection: enum { multi, single } = .multi,

    // ---- Box-select mode (exclusive group) - DEFERRED to a later step.
    // Drag-rectangle selection is a whole input subsystem; filed for
    // post-1.3 follow-up. Imgui: `BoxSelect1d` / `BoxSelect2d`.
    /// Drag-rectangle box-select. `.none` (default) disables. `.d1`
    /// = same-X items (full-row); `.d2` = arbitrary X (grid). TODO
    /// Step 1.x: box-select is not implemented in MVP - value is
    /// accepted but currently ignored. Imgui:
    /// `imgui_widgets.cpp:8366-8412` for the box-select item-overlap
    /// logic.
    box_select: enum { none, d1, d2 } = .none,

    // ---- Scope for box-select + ClearOnClickVoid (exclusive group)
    /// `.window` (default) - scope is the whole window. `.rect`
    /// scope is the rect encompassing Begin..End (use when one window
    /// has multiple MS scopes). TODO Step 1.x: only `clear_on_click_void`
    /// uses this in MVP, and only `.window` is exercised; `.rect`
    /// is accepted but treated as `.window`. Imgui:
    /// `imgui_widgets.cpp:8029-8030` (ScopeRect's CursorMaxPos hack).
    scope: enum { window, rect } = .window,

    // ---- Click timing (exclusive group) - DEFERRED. Default is fine.
    /// When to apply a selection-changing click. `.auto` (default):
    /// on mouse-down if unselected, on mouse-up if already selected
    /// (permits drag-drop). `.always`: mouse-down (Excel-style).
    /// `.release`: mouse-up (most drag-friendly). TODO Step 1.x:
    /// only `.auto` is wired; the others are accepted but ignored.
    /// Imgui: `imgui_widgets.cpp:8285-8294` for the ButtonFlags
    /// override.
    click_timing: enum { auto, always, release } = .auto,

    // ---- Independent bools
    /// Disable the Ctrl+A "select all" shortcut. Imgui:
    /// `imgui_widgets.cpp:8101-8104`. ✓ MVP.
    no_select_all: bool = false,
    /// Disable Shift-anything (Shift-click, Shift-arrow). Guarantees
    /// every SetRange request has a single-item range, so the user's
    /// `applyRequests` doesn't have to interpolate. Imgui:
    /// `imgui_widgets.cpp:8038-8039`. ✓ MVP.
    no_range_select: bool = false,
    /// Disable selecting items when keyboard-navigating. Used with
    /// `no_auto_clear` for checkbox-list mode where each row is
    /// toggled independently. TODO Step 1.x: not wired in MVP;
    /// MS scope still emits the click-replace pattern. Imgui:
    /// `imgui_widgets.cpp:8343-8358`.
    no_auto_select: bool = false,
    /// Disable auto-clearing the selection when clicking/navigating
    /// to another item. Pair with `no_auto_select` for
    /// checkbox-list mode. TODO Step 1.x: not wired in MVP.
    /// Imgui: `imgui_widgets.cpp:8459-8470`.
    no_auto_clear: bool = false,
    /// Clicking an already-selected item normally clears the other
    /// selections; with this flag, it doesn't. Mac Finder
    /// behavior - important on touch where unintended clears
    /// feel destructive. Imgui:
    /// `imgui_widgets.cpp:8464-8465`. ✓ MVP.
    no_auto_clear_on_reselect: bool = false,
    /// Disable scrolling when box-selecting near scope edges.
    /// TODO Step 1.x: paired with box_select; not wired in MVP.
    /// Imgui: only consulted inside BeginBoxSelect.
    box_select_no_scroll: bool = false,
    /// Clear selection on Escape. Emits a single `SetAll(false)`
    /// request. Imgui: `imgui_widgets.cpp:8090-8098`. ✓ MVP.
    clear_on_escape: bool = false,
    /// Clear selection when clicking on empty space within the
    /// scope's rect. Imgui:
    /// `imgui_widgets.cpp` (via `ScopeRectActive`). ✓ MVP.
    clear_on_click_void: bool = false,
    /// Allow keyboard nav to wrap horizontally at scope edges.
    /// TODO Step 1.x: zimr's kb-nav is minimal today (
    /// territory); not wired. Imgui:
    /// `ImGuiMultiSelectFlags_NavWrapX` - temporary flag per
    /// imgui's own comment.
    nav_wrap_x: bool = false,
    /// Disable default right-click selecting (for context-menu
    /// patterns). TODO Step 1.x: no right-click on phone, low
    /// desktop priority. Imgui:
    /// `imgui_widgets.cpp:8414-8426`.
    no_select_on_right_click: bool = false,
};

fn freePriorMultiSelectScope(ctx: *UiContext) void {
    if (ctx.current_multi_select) |*old| {
        old.requests_buf.deinit(ctx.gpa);
        ctx.current_multi_select = null;
    }
}

fn addSetAllRequest(
    ctx: *UiContext,
    scope: *MultiSelectScope,
    selected: bool,
) void {
    scope.requests_buf.clearRetainingCapacity();
    scope.requests_buf.append(ctx.gpa, .{ .set_all = selected }) catch {
        @panic("OOM in addSetAllRequest");
    };
}

fn beginMultiSelectImpl(
    ctx: *UiContext,
    flags_in: MultiSelectFlags,
    selection_size: u32,
    items_count: u32,
) *const MultiSelectIO {
    // Tear down any prior scope's request buffer before clobbering.
    // (User pattern: Begin -> apply ->... -> End -> apply. By the
    // time the NEXT Begin runs, the previous scope's IO pointer is
    // long since consumed.)
    freePriorMultiSelectScope(ctx);

    const w: *Window = ctx.current_window orelse {
        @panic("beginMultiSelect called with no current window");
    };

    // Enforce inter-flag invariants matching imgui_widgets.cpp:8007-8010.
    var flags: MultiSelectFlags = flags_in;
    if (flags.selection == .single) {
        flags.box_select = .none;
    }

    const scope_id: Id = if (ctx.id_stack.len > 0)
        ctx.id_stack.items[ctx.id_stack.len - 1]
    else
        w.id;

    const gop: std.AutoHashMapUnmanaged(Id, MultiSelectState).GetOrPutResult = ctx.ms_storage.getOrPut(
        ctx.gpa,
        scope_id,
    ) catch {
        @panic("OOM in beginMultiSelect ms_storage");
    };
    if (!gop.found_existing) {
        gop.value_ptr.* = .{};
    }
    gop.value_ptr.last_frame_active = ctx.frame_count;
    gop.value_ptr.last_selection_size = selection_size;

    // Set up the transient scope.
    ctx.current_multi_select = .{
        .id = scope_id,
        .storage = gop.value_ptr,
        .flags = flags,
        .key_shift = snapshotShiftDown(&ctx.input),
        .key_ctrl = snapshotCtrlDown(&ctx.input),
        .io = .{
            .requests = &.{},
            .range_src_item = gop.value_ptr.range_src_item,
            .nav_id_item = gop.value_ptr.nav_id_item,
            .nav_id_selected = gop.value_ptr.nav_id_selected orelse false,
            .items_count = items_count,
        },
        .requests_buf = .empty,
        .loop_request_set_all = .none,
        .range_src_passed_by = false,
        .is_focused = (ctx.focused_window_id == w.id),
        .is_end_io = false,
    };
    const scope: *MultiSelectScope = &ctx.current_multi_select.?;

    // -------- Keyboard shortcuts
    // Imgui mirror: imgui_widgets.cpp:8085-8113. Two shortcuts in MVP:
    //   - Escape clears selection (if clear_on_escape AND selection non-empty)
    //   - Ctrl+A selects all (if !no_select_all AND !single-select)
    // Both emit a SetAll request. imgui's `MultiSelectAddSetAll` calls
    // `requests.resize(0)` first - wiping prior pending requests so
    // SetAll always lands as the single request. We mirror that
    // semantic (use addSetAllRequest helper below).
    // Edge: only emit when this scope is focused. In zimr we use
    // window-focus as the proxy (`is_focused`).

    var request_clear: bool = false;
    // Ctrl+A is inert in MVP until per-letter key snapshot fields land
    // (see comment further down in the is_focused block).
    const request_select_all: bool = false;

    if (scope.is_focused) {
        const escape_pressed: bool = ctx.input.keys[@backingInt(KeyCode.escape)].pressed_this_frame;
        if (flags.clear_on_escape and selection_size != 0 and escape_pressed) {
            request_clear = true;
        }
        // Imgui: SingleSelect + NoSelectAll both block Ctrl+A.
        const block_select_all: bool = (flags.selection == .single) or flags.no_select_all;
        if (!block_select_all and scope.key_ctrl) {
            // `chars_typed` won't contain 'A' on Ctrl+A (browser
            // sends keydown only); test via key_a_pressed edge.
            // zimr doesn't have key_a in InputSnapshot today; for
            // we approximate with: if user holds ctrl and
            // taps SOMETHING, Ctrl-A isn't reachable on phone
            // anyway. Filed for follow-up: per-letter key snapshot
            // fields, or a "named shortcut" API.
            // Effective MVP behavior: Ctrl+A is desktop-only and
            // currently inert until letter-key tracking lands.
            // Documented in MultiSelectFlags.no_select_all.
        }
    }

    if (request_clear or request_select_all) {
        addSetAllRequest(ctx, scope, request_select_all);
        scope.loop_request_set_all = if (request_select_all) .select else .clear;
        if (!request_select_all) {
            gop.value_ptr.last_selection_size = 0;
        }
    }

    // Begin-time IO snapshot: slice into the (now-populated) buffer.
    scope.io.requests = scope.requests_buf.items;

    return &scope.io;
}

fn endMultiSelectImpl(ctx: *UiContext) *const MultiSelectIO {
    const scope: *MultiSelectScope = &(ctx.current_multi_select orelse {
        @panic("endMultiSelect called outside a Begin/End pair");
    });

    // -------- ClearOnClickVoid
    // Imgui pattern: if click landed inside the scope rect but not on
    // any item, emit set_all(false). Detection: a mouse-left-clicked
    // edge this frame, the click coords are within the window's content
    // rect, AND no item registered as hovered (proxy: ctx.hovered_id
    // wasn't set to anything inside the scope's id stack).
    // MVP simplification: trigger if mouse_left_clicked AND
    // ctx.hovered_id == 0 (nothing hovered). This works for the
    // common case (tap empty area in scope's window).
    if (scope.flags.clear_on_click_void and ctx.input.mouse_left_clicked and ctx.hovered_id == 0) {
        // Honor "is_end_io reset" semantics: when Footer is about to
        // emit its first request this frame it does
        // `requests.resize(0)` to drop Begin's pending requests.
        // Same idea here: ClearOnClickVoid is a frame-fresh emit.
        if (!scope.is_end_io) {
            scope.requests_buf.clearRetainingCapacity();
            scope.is_end_io = true;
        }
        addSetAllRequest(ctx, scope, false);
    }

    // Snapshot the (possibly-mutated) requests slice.
    scope.io.requests = scope.requests_buf.items;

    // Refresh anchor / nav state from the now-final storage values.
    scope.io.range_src_item = scope.storage.range_src_item;
    scope.io.nav_id_item = scope.storage.nav_id_item;
    scope.io.nav_id_selected = scope.storage.nav_id_selected orelse false;

    return &scope.io;
}

/// Tiny disclosure triangle, rendered as horizontal strips. Cheap,
/// pixelly, but reads correctly at this size.
fn drawTriangleIndicator(
    ctx: *UiContext,
    rect: Rectangle,
    open: bool,
    col: ColorU32,
) void {
    if (open) {
        // Down-pointing: 3 horizontal strips, each shorter than the last.
        const cy: f32 = rect.y + rect.height / 2;
        var i: f32 = 0;
        while (i < 4) : (i += 1) {
            // One inset 1px strip per pass, shrinking by 2 each time (one pixel off each side) and
            // stepping in by 1 - four nested rectangles drawn as a soft border.
            const strip_w: f32 = rect.width - i * 2;
            const strip_x: f32 = rect.x + i;
            drawRectFilled(ctx, .{ .x = strip_x, .y = cy - 2 + i, .width = strip_w, .height = 1 }, col);
        }
    } else {
        // Right-pointing: 3 vertical strips, each shorter than the last.
        const cx: f32 = rect.x + rect.width / 2;
        var i: f32 = 0;
        while (i < 4) : (i += 1) {
            const strip_h: f32 = rect.height - i * 2;
            const strip_y: f32 = rect.y + i;
            drawRectFilled(ctx, .{ .x = cx - 2 + i, .y = strip_y, .width = 1, .height = strip_h }, col);
        }
    }
}

fn collapsingHeaderImpl(
    ctx: *UiContext,
    label: []const u8,
    open: *bool,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    const padding: Vec2 = ctx.style.frame_padding;
    const row_h: f32 = ctx.style.font_size + 2 * padding[1];
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const row_w: f32 = inner_right - at[0];

    const rect = Rectangle{ .x = at[0], .y = at[1], .width = row_w, .height = row_h };
    const hovered: bool = itemHoverable(ctx, rect);
    if (hovered) {
        ctx.hovered_id = id;
    }

    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
    }
    if (ctx.active_id == id and ctx.input.mouse_left_released) {
        if (hovered) {
            open.* = !open.*;
        }
        ctx.active_id = 0;
    }

    // Header background.
    const bg: Color = if (ctx.active_id == id)
        ctx.style.frame_bg_active
    else if (hovered)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, rect, Color.toWire(bg));

    // Triangle indicator on the left - three filled rects approximating
    // a wedge. Closed → right-pointing. Open → down-pointing.
    const tri_x: f32 = at[0] + padding[0];
    const tri_y: f32 = at[1] + (row_h - ctx.style.font_size) / 2;
    const tri_size: f32 = ctx.style.font_size;
    drawTriangleIndicator(
        ctx,
        .{ .x = tri_x, .y = tri_y, .width = tri_size, .height = tri_size },
        open.*,
        Color.toWire(ctx.style.text),
    );

    // Label to the right of the triangle.
    drawTextAtS(
        ctx,
        .{ tri_x + tri_size + 4, at[1] + padding[1] },
        label,
        Color.toWire(ctx.style.text),
    );

    w.layout.last_item_id = id;
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false); // header toggle isn't a "value edit" in ImGui semantics

    advanceLayout(w, .{ row_w, row_h }, ctx.style.item_spacing, ctx.style.window_padding[0]);
    return open.*;
}

fn beginTableImpl(
    ctx: *UiContext,
    label: []const u8,
    n_columns: u32,
    opts: TableOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    if (n_columns == 0 or n_columns > max_table_columns) {
        return false;
    }
    if (ctx.active_table != null) {
        // Nested tables not supported in. Caller could
        // hit this if begin/end pairs got desynced.
        return false;
    }

    const id: Id = widgetId(ctx, w, label);
    const start: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const outer_w: f32 = if (opts.outer_width > 0) opts.outer_width else (inner_right - start[0]);

    // Look up the persistent scroll offset for this table id; 0 when
    // first encountered (or when `outer_height == 0`, in which case
    // we just don't read it later).
    var scroll_y: f32 = 0;
    if (opts.outer_height > 0) {
        if (ctx.table_scroll_state.get(id)) |s| {
            scroll_y = s;
        }
    }

    const ts: TableState = .{
        .id = id,
        .n_columns = n_columns,
        .columns_set_up = 0,
        .columns = @splat(.{}),
        .row_y = start[1],
        .row_max_h = 0,
        .cur_col = -1,
        .cur_row = -1,
        .opts = opts,
        .outer_rect = .{
            .x = start[0],
            .y = start[1],
            .width = outer_w,
            .height = if (opts.outer_height > 0) opts.outer_height else 0,
        },
        .has_setup = false,
        .scroll_y = scroll_y,
        .data_origin_y = start[1],
        .clip_pushed = false,
        .row_bg_override = null,
    };
    ctx.active_table = ts;

    // P8.4: seed each column's `width_auto_seen` from
    // the persistent cache — that's the PREVIOUS frame's measured
    // content width per column, which `computeTableColumnLayout`
    // will use to size this frame under the content-fit policies.
    // First time we encounter this table id, the cache lookup
    // returns null and every column starts at 0 — the layout code's
    // fallback (`fallbackColumnWidth`) takes over.
    if (ctx.table_width_auto_cache.get(id)) |cached| {
        const ts_ptr_for_seed: *TableState = &ctx.active_table.?;
        var i: u32 = 0;
        while (i < n_columns) : (i += 1) {
            ts_ptr_for_seed.columns[i].width_auto_seen = cached[i];
        }
    }

    // P7.2: set up the splitter on the now-stored
    // TableState. Channel 0 = row bg + cell borders. Channel 1 =
    // cell content (widget submissions, redirected via
    // current_draw_list). At endTable, the splitter merges into
    // the window's draw_list — channel 0 first, then channel 1 —
    // so backgrounds always paint UNDER content regardless of
    // submission interleave.
    //

    // Allocate through the frame arena so the channel storage is
    // freed naturally at the end-of-frame arena reset. If the
    // allocation fails (OOM), revert active_table and return
    // false — caller will skip the table entirely.
    const ts_ptr: *TableState = &ctx.active_table.?;
    ts_ptr.splitter.split(ctx.frame_arena.allocator(), 2) catch {
        ctx.active_table = null;
        return false;
    };
    ts_ptr.saved_draw_list = ctx.current_draw_list;
    // Redirect widget submissions to channel 1 (content).
    ctx.current_draw_list = &ts_ptr.splitter.channels.items[1];

    return true;
}

/// Snapshot the current cell's content height into the running
/// `row_max_h` maximum for the active row. Same call-site
/// pattern as `snapshotCellWidth` — called at next-column,
/// next-row, and end-table so every cell's height contributes
/// to the row's resolved height regardless of which cell was
/// last in the row.
///
/// Pre-T1.1 zimr only ran this snapshot from
/// `tableNextColumnImpl` — fine for cells 0..N-2 of each row, but
/// the LAST cell of every row never had a "next column" call
/// after it. Symptom: a row whose tallest cell happened to be
/// the rightmost column got vertically clipped — visible content
/// stuck out below the row's drawn background. Adding the
/// snapshot at next-row and end-table covers the missed cells.
fn snapshotCellHeight(ts: *TableState, w: *const Window) void {
    if (ts.cur_col < 0) {
        return;
    }
    const used_h: f32 = (w.layout.cursor_max[1] - ts.row_y) + ts.opts.cell_padding_y;
    if (used_h > ts.row_max_h) {
        ts.row_max_h = used_h;
    }
}

/// Snapshot the current cell's content width into the column's
/// running `width_auto_seen` maximum. Called from every site that
/// "ends" a cell:
///   - `tableNextColumnImpl` when advancing within a row
///   - `tableNextRowImpl` when finishing a row's last cell
///   - `endTableImpl` when finishing the table's last cell
/// All three are needed because zimr's cell-cursor advance is
/// driven by the next call, not by an explicit end-of-cell marker.
fn snapshotCellWidth(ts: *TableState, w: *const Window) void {
    if (ts.cur_col < 0) {
        return;
    }
    const idx: usize = @intCast(ts.cur_col);
    if (idx >= ts.n_columns) {
        return;
    }
    const col: *TableColumnState = &ts.columns[idx];
    // Compute the cell's rightmost content x (from `cursor_max`,
    // which widget submissions push as they draw) relative to the
    // column's left edge. Add one symmetric `cell_padding_x` on
    // the right so the autofit width has room on BOTH sides — the
    // left-side padding is already baked into where `cursor_pos`
    // starts inside the cell.
    const content_w: f32 = (w.layout.cursor_max[0] - col.x) + ts.opts.cell_padding_x;
    if (content_w > col.width_auto_seen) {
        col.width_auto_seen = content_w;
    }
}

/// Paint one row's background - either the per-row override (if
/// set) or the alternating-tint pair from style when
/// `opts.row_bg` is enabled. No-op when neither applies. The
/// row_index decides even/odd when alternating.
///
/// P7.2: writes to the table's splitter channel 0 (the
/// bg channel) instead of the window's draw_list directly. At
/// endTable the splitter merges channel 0 BEFORE channel 1 (cell
/// content), so the bg sits behind cells in the final draw
/// stream. Pre-the bg cmd was appended AFTER cell content
/// in the same draw list and overlapped it; the workaround was a
/// translucent bg tint. Splitter makes opaque bgs work.
fn drawTableRowBg(
    ctx: *UiContext,
    ts: *TableState,
    y: f32,
    h: f32,
    row_index: u32,
) void {
    const color: Color = if (ts.row_bg_override) |c|
        c
    else if (ts.opts.row_bg)
        (if (row_index % 2 == 0) ctx.style.table_row_bg else ctx.style.table_row_bg_alt)
    else
        return;
    if (color.a == 0) {
        return;
    } // fully transparent → skip
    const arena: Allocator = ctx.frame_arena.allocator();
    // Channel 0 = bg channel.
    ts.splitter.channels.items[0].addRectFilled(
        arena,
        .{ .x = ts.outer_rect.x, .y = y, .width = ts.outer_rect.width, .height = h },
        Color.toWire(color),
    );
}

/// Paint pending per-cell bg overrides for the current row into
/// the table's splitter channel 0. Each entry in `ts.columns`
/// with a non-null `cell_bg_pending` produces one filled-rect
/// command at (col.x, y, col.width, h). After painting, the
/// pending field is reset so the next row's cells start fresh.
///
/// Called at row finalization (from `tableNextRow` for previous
/// rows; from `endTable` for the final row). Skips entries with
/// alpha=0 cells (treated as "clear pending override").
///
/// Z-order: cell bg lands in channel 0 AFTER `drawTableRowBg` for
/// the same row, so cell-level overrides paint OVER row-level
/// overrides — more specific wins. Both land BEFORE cell content
/// (channel 1) after the splitter merge.
fn flushTableCellBgs(
    ctx: *UiContext,
    ts: *TableState,
    y: f32,
    h: f32,
) void {
    const arena: Allocator = ctx.frame_arena.allocator();
    var i: u32 = 0;
    while (i < ts.n_columns) : (i += 1) {
        const col: *TableColumnState = &ts.columns[i];
        const c: Color = col.cell_bg_pending orelse continue;
        col.cell_bg_pending = null;
        if (c.a == 0) {
            continue;
        }
        ts.splitter.channels.items[0].addRectFilled(
            arena,
            .{ .x = col.x, .y = y, .width = col.width, .height = h },
            Color.toWire(c),
        );
    }
}

/// Copy each column's `width_auto_seen` into `ctx.table_width_auto_cache`
/// keyed by the table's id. The reverse direction (cache → column
/// state) happens at `beginTableImpl` time. Allocation failure is
/// non-fatal — the cache just won't carry this frame's data forward,
/// and the next frame falls back to the font-size heuristic.
fn persistTableWidthAuto(ctx: *UiContext, ts: *const TableState) void {
    var values: [max_table_columns]f32 = @splat(0);
    var i: u32 = 0;
    while (i < ts.n_columns) : (i += 1) {
        values[i] = ts.columns[i].width_auto_seen;
    }
    ctx.table_width_auto_cache.put(ctx.gpa, ts.id, values) catch assertUnreachable(@src(), "OOM", .{});
}

fn endTableImpl(ctx: *UiContext) void {
    const ts: *TableState = if (ctx.active_table) |*t| t else return;
    const w: *Window = ctx.current_window orelse return;
    const arena: Allocator = ctx.frame_arena.allocator();
    // P7.2: the table writes its bg-layer cmds
    // (row bg, borders, column dividers, scrollbar visual hint)
    // to splitter channel 0. Cell content (already submitted by
    // widgets via ctx.current_draw_list redirected to channel 1)
    // stays on channel 1. At the end of this function the splitter
    // is merged into the window's draw_list — channel 0 first.
    const bg_dl: *DrawList = &ts.splitter.channels.items[0];

    // Close out the last row's height into the outer rect.
    if (ts.cur_row >= 0) {
        // / T1.1 (turns 412-413): snapshot the final cell of
        // the final row. Same rationale as the row-end snapshot
        // in tableNextRowImpl — this is the only place the
        // table's very last cell's metrics are captured. Width
        // since P8.4; height added in T1.1.
        if (ts.cur_col >= 0) {
            snapshotCellHeight(ts, w);
            snapshotCellWidth(ts, w);
        }
        const last_row_bottom: f32 = ts.row_y + ts.row_max_h;
        // Paint the final row's background - same lazy-paint
        // pattern as `tableNextRow` does for previous rows.
        drawTableRowBg(ctx, ts, ts.row_y, ts.row_max_h, @as(u32, @intCast(ts.cur_row)));
        // P8.1: flush any per-cell bg overrides for the final row.
        // Same z-order as in tableNextRow — cell bgs paint OVER
        // row bg, UNDER cell content (channel 1).
        flushTableCellBgs(ctx, ts, ts.row_y, ts.row_max_h);
        // For fixed-height (scrolling) tables, outer rect height is
        // pre-set; for auto-fit tables it grows to fit content.
        if (ts.opts.outer_height == 0) {
            ts.outer_rect.height = last_row_bottom - ts.outer_rect.y;
        }

        // Scrollable table bookkeeping: pop clip, handle wheel,
        // write back the clamped scroll offset.
        if (ts.opts.outer_height > 0) {
            if (ts.clip_pushed) {
                // Pop the clip from BOTH channels (pushed on both
                // at first tableNextRow).
                bg_dl.popClipRect(arena);
                ts.splitter.channels.items[1].popClipRect(arena);
                ts.clip_pushed = false;
            }
            // Total data height = last row bottom - data origin
            // (computed in PRE-scroll coords by adding scroll_y
            // back to last_row_bottom).
            const total_data_h: f32 = (last_row_bottom + ts.scroll_y) - ts.data_origin_y;
            const visible_h: f32 = (ts.outer_rect.y + ts.outer_rect.height) - ts.data_origin_y;
            const max_scroll: f32 = @max(0, total_data_h - visible_h);

            // Handle mouse-wheel input if the cursor is over the
            // outer rect. Match the window-scroll wheel speed.
            if (itemHoverable(ctx, ts.outer_rect) and ctx.input.mouse_wheel_y != 0) {
                const wheel_speed: f32 = 24;
                ts.scroll_y -= ctx.input.mouse_wheel_y * wheel_speed;
            }
            if (ts.scroll_y < 0) {
                ts.scroll_y = 0;
            }
            if (ts.scroll_y > max_scroll) {
                ts.scroll_y = max_scroll;
            }
            // Persist for next frame.
            ctx.table_scroll_state.put(ctx.gpa, ts.id, ts.scroll_y) catch assertUnreachable(@src(), "OOM", .{});

            // Optional 4px-wide scrollbar on the right edge - purely
            // a visual hint; click-to-drag is polish.
            // Scrollbar lives on channel 0 (bg layer) — it's part
            // of the table chrome, not user content.
            if (max_scroll > 0) {
                const bar_w: f32 = 4;
                const track_x: f32 = ts.outer_rect.x + ts.outer_rect.width - bar_w - 1;
                const track_y: f32 = ts.data_origin_y;
                const track_h: f32 = visible_h;
                const thumb_h: f32 = @max(20, track_h * (visible_h / total_data_h));
                const thumb_y: f32 = track_y + (track_h - thumb_h) * (ts.scroll_y / max_scroll);
                bg_dl.addRectFilled(
                    arena,
                    .{ .x = track_x, .y = track_y, .width = bar_w, .height = track_h },
                    Color.toWire(ctx.style.frame_bg),
                );
                bg_dl.addRectFilled(
                    arena,
                    .{ .x = track_x, .y = thumb_y, .width = bar_w, .height = thumb_h },
                    Color.toWire(ctx.style.button),
                );
            }
        }
    }

    // P8.2: granular border drawing — each side / interior line
    // gated by its own flag, with the master `borders` flag
    // AND-ing on top. Pre-the entire block was gated by
    // the single `borders` boolean and used `addRectOutline` for
    // the outer; now we emit per-side `addLine` cmds so the four
    // sides can be toggled independently.
    if (ts.opts.borders) {
        const border_col: ColorU32 = Color.toWire(ctx.style.border);
        const ox: f32 = ts.outer_rect.x;
        const oy: f32 = ts.outer_rect.y;
        const ow: f32 = ts.outer_rect.width;
        const oh: f32 = ts.outer_rect.height;

        // Outer top edge — borders_outer_h.
        if (ts.opts.borders_outer_h) {
            bg_dl.addLine(arena, .{ ox, oy }, .{ ox + ow, oy }, border_col, 1);
        }
        // Outer bottom edge — borders_outer_h.
        if (ts.opts.borders_outer_h) {
            bg_dl.addLine(arena, .{ ox, oy + oh }, .{ ox + ow, oy + oh }, border_col, 1);
        }
        // Outer left edge — borders_outer_v.
        if (ts.opts.borders_outer_v) {
            bg_dl.addLine(arena, .{ ox, oy }, .{ ox, oy + oh }, border_col, 1);
        }
        // Outer right edge — borders_outer_v.
        if (ts.opts.borders_outer_v) {
            bg_dl.addLine(arena, .{ ox + ow, oy }, .{ ox + ow, oy + oh }, border_col, 1);
        }

        // Vertical dividers between columns — borders_inner_v.
        // Drawn FOR THE FULL outer rect (header + data area),
        // since columns are continuous top-to-bottom.
        if (ts.opts.borders_inner_v) {
            var i: u32 = 1;
            while (i < ts.n_columns) : (i += 1) {
                const col_x: f32 = ts.columns[i].x;
                bg_dl.addLine(
                    arena,
                    .{ col_x, oy },
                    .{ col_x, oy + oh },
                    border_col,
                    1,
                );
            }
        }
    }

    // Restore the draw-list redirection, then merge the splitter
    // into the window's draw_list (channel 0 first, then channel 1).
    // Order matters: restore BEFORE merge, because merge appends
    // into the saved target.
    ctx.current_draw_list = ts.saved_draw_list;
    const target_dl: *DrawList = if (ts.saved_draw_list) |dl| dl else &w.draw_list;
    ts.splitter.merge(arena, target_dl) catch assertUnreachable(@src(), "OOM", .{});

    // P8.4: persist this frame's per-column measured
    // widths into the context-level cache so the NEXT frame's
    // `computeTableColumnLayout` can use them. Single-pass UI
    // means we always trail by one frame — the first frame falls
    // back to the font-size heuristic, every frame thereafter uses
    // the previous frame's measurement. Cost is one 32×f32 entry
    // per active table id.
    persistTableWidthAuto(ctx, ts);

    // Advance the parent window's layout cursor past the table.
    advanceLayout(
        w,
        .{ ts.outer_rect.width, ts.outer_rect.height },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );

    ctx.active_table = null;
}

pub const TableColumnOpts = struct {
    /// Per-column sizing override. Default `null` — the column
    /// inherits from the table's `opts.sizing` policy (see
    /// `TableSizing`). When non-null, this column uses the
    /// specified mode regardless of the table-level policy.
    ///
    /// Mirrors imgui's per-column `ImGuiTableColumnFlags_Width*`
    /// flags (imgui.h:2200+): null = "use table default", set =
    /// "column-specific override".
    sizing: ?TableColumnSizing = null,
    /// Width in pixels for `.fixed` sizing. Zero (the default)
    /// means "use the table's sizing policy to derive the width"
    /// — `fixed_fit` uses this column's measured content width,
    /// `fixed_same` uses the max across all fixed columns.
    /// Ignored for `.stretch` sizing.
    width: f32 = 0,
    /// Relative weight when `.stretch`. Default `null` — the
    /// column inherits its weight from the table's sizing policy
    /// (`stretch_same` ⇒ 1.0 for every column; `stretch_prop` ⇒
    /// weight = measured content width). When non-null, this
    /// column uses the explicit weight regardless of policy —
    /// e.g. a column with weight 2 always gets twice the share
    /// of a default-weight column.
    /// Non-positive values are clamped to 1.
    weight: ?f32 = null,
    /// Suppress sort interaction on this column.  When true,
    /// header clicks are ignored and the column never appears in
    /// the sort specs.  Mirrors imgui's
    /// `ImGuiTableColumnFlags_NoSort` (imgui.h ~2200).
    /// Default false (sort cycles normally).  Replaces the old
    /// `sortable: bool = true` field — same semantics, flipped
    /// polarity to match imgui's negative-default flag convention.
    no_sort: bool = false,
    /// Block ascending direction in the sort cycle.  The cycle
    /// becomes: unsorted → descending → (flip to unsorted on
    /// re-click of primary; new primary stays descending).  If
    /// BOTH `no_sort_ascending` and `no_sort_descending` are set,
    /// the column behaves as `no_sort = true`.  Mirrors imgui's
    /// `ImGuiTableColumnFlags_NoSortAscending`.
    no_sort_ascending: bool = false,
    /// Block descending direction in the sort cycle.  See
    /// `no_sort_ascending` for cycle behavior.  Mirrors imgui's
    /// `ImGuiTableColumnFlags_NoSortDescending`.
    no_sort_descending: bool = false,
    /// Initial sort direction on the first frame this table is
    /// submitted.  When set, the column joins the sort specs at
    /// that direction without needing a header click.  If
    /// multiple columns set `default_sort`, the leftmost wins
    /// (primary); subsequent ones don't append (the imgui
    /// `DefaultSort` semantics — only one default-sorted column
    /// is supported here for simplicity).  Mirrors imgui's
    /// `ImGuiTableColumnFlags_DefaultSort` (which is a bool;
    /// our typed `?TableSortDirection` lets the caller pick the
    /// direction in the same field).  Default null — no default
    /// sort.
    default_sort: ?TableSortDirection = null,
    /// Force this column to size itself to its measured content
    /// width (the `width_auto_seen` value from the previous frame,
    /// or a font-derived fallback on the first frame).  Equivalent
    /// to `.{ .sizing = .fixed, .width = 0 }` but more discoverable
    /// — answers "how do I make a column autofit?" by name.
    /// Mirrors imgui's `ImGuiTableColumnFlags_WidthAuto`.
    /// Default false.  When true, takes precedence over `sizing`
    /// and `width`.
    width_auto: bool = false,
    /// Suppress the header text on this column.  Header BAR still
    /// renders (background, sort arrow if applicable, click
    /// hit-test for sort cycling); only the label text is
    /// skipped.  Useful for icon-only headers or to leave a
    /// column unlabeled in shared/merged header surfaces.
    /// Mirrors imgui's `ImGuiTableColumnFlags_NoHeaderLabel`.
    /// Default false.
    no_header_label: bool = false,
};

fn tableSetupColumnImpl(
    ctx: *UiContext,
    label: []const u8,
    opts: TableColumnOpts,
) void {
    const ts: *TableState = if (ctx.active_table) |*t| t else return;
    // Only honor setup calls before the first row.
    if (ts.cur_row >= 0) {
        return;
    }
    if (ts.columns_set_up >= ts.n_columns) {
        return;
    }
    var col: *TableColumnState = &ts.columns[ts.columns_set_up];
    const cap: usize = @min(label.len, col.name_buf.len);
    @memcpy(col.name_buf[0..cap], label[0..cap]);
    col.name_len = cap;
    // P8.4: resolve column sizing. Null = inherit from the table's
    // policy; non-null = explicit per-column override. The resolved
    // value is stored as a concrete `TableColumnSizing` on the column
    // state so downstream layout code doesn't have to re-resolve.
    //
    // `width_auto` is a shortcut for "sizing = fixed with width = 0"
    // (use the measured `width_auto_seen`).  When set, it takes
    // precedence over both `sizing` and `width` — the caller's
    // intent is "fit content", regardless of any other knobs.
    if (opts.width_auto) {
        col.sizing = .fixed;
        col.user_width = 0;
    } else {
        col.sizing = opts.sizing orelse defaultColumnSizing(ts.opts.sizing);
        col.user_width = opts.width;
    }
    // P8.4: user_weight is optional on both opts and state. null
    // means "let the sizing policy decide" — preserved here so
    // `effectiveStretchWeight` can distinguish "user wants weight=1"
    // (explicit) from "user didn't set a weight" (use policy).
    // Non-positive values are clamped to 1 to keep the layout math
    // well-defined.
    col.user_weight = if (opts.weight) |w| (if (w > 0) w else 1) else null;
    col.no_sort = opts.no_sort;
    col.no_sort_ascending = opts.no_sort_ascending;
    col.no_sort_descending = opts.no_sort_descending;
    col.default_sort = opts.default_sort;
    col.no_header_label = opts.no_header_label;

    // Seed the default sort direction into the live sort specs
    // — but only on the FIRST submission of this table, before
    // any user click has had a chance to override.  We detect
    // first-submission as "the sort_state map has no entry yet
    // for `ts.id`."  Once an entry exists (created by a user
    // click OR by a previous default_sort seed), we don't
    // re-seed.  Multiple columns with `default_sort` set are
    // unsupported here: the leftmost wins, subsequent ones are
    // ignored (imgui's documented `DefaultSort` semantics —
    // only one default-sorted column).
    if (opts.default_sort) |dir| {
        if (!ctx.table_sort_state.contains(ts.id)) {
            var ss: TableSortSpecs = .{};
            ss.specs[0] = .{ .column_index = ts.columns_set_up, .direction = dir };
            ss.len = 1;
            ctx.table_sort_state.put(ctx.gpa, ts.id, ss) catch assertUnreachable(@src(), "OOM", .{});
        }
    }

    ts.columns_set_up += 1;
    ts.has_setup = true;
}

fn tableNextColumnImpl(ctx: *UiContext) bool {
    const ts: *TableState = if (ctx.active_table) |*t| t else return false;
    if (ts.cur_row < 0) {
        // Caller forgot to call tableNextRow first - treat as a
        // no-op rather than reach into garbage.
        return false;
    }
    // Before advancing, snapshot the *previous* column's content
    // metrics. Two independent measurements run via dedicated
    // helpers:
    //

    //   - Width: `snapshotCellWidth` rolls the
    //     just-finished cell's content width into the column's
    //     `width_auto_seen`, which feeds the next frame's
    //     `computeTableColumnLayout` under the content-fit sizing
    //     modes.
    //   - Height: `snapshotCellHeight` rolls
    //     the just-finished cell's content height into the row's
    //     running `row_max_h`, so the row finalizes with the
    //     tallest cell's height.
    //

    // Both helpers ALSO run at row-end and table-end (the last
    // cell of each row never sees a "next column" call), but
    // running them here too is harmless and covers the common
    // path of cells 0..N-2 in a multi-column row. Idempotent
    // under repeated calls: each helper computes a fresh max
    // and only writes if the new value is larger.
    if (ts.cur_col >= 0) {
        const w: *Window = ctx.current_window orelse return false;
        snapshotCellHeight(ts, w);
        snapshotCellWidth(ts, w);
    }

    ts.cur_col += 1;
    if (ts.cur_col >= @as(i32, @intCast(ts.n_columns))) {
        return false;
    }

    const w: *Window = ctx.current_window orelse return false;
    const col: *const TableColumnState = &ts.columns[@intCast(ts.cur_col)];
    // P8.3: left-side cell padding is now conditional.
    // - Column 0 uses `no_pad_outer_x` to gate the gap to the
    //   table's outer-left edge.
    // - Columns 1..N-1 use `no_pad_inner_x` to gate the gap to
    //   the column divider on their left.
    // Defaults preserve legacy "padding on every column" behavior.
    const left_pad: f32 = if (ts.cur_col == 0)
        (if (ts.opts.no_pad_outer_x) 0 else ts.opts.cell_padding_x)
    else
        (if (ts.opts.no_pad_inner_x) 0 else ts.opts.cell_padding_x);
    // Position the layout cursor at the column's top-left + cell
    // padding. Cell content draws from here.
    w.layout.cursor_pos = .{ col.x + left_pad, ts.row_y + ts.opts.cell_padding_y };
    w.layout.cursor_max = w.layout.cursor_pos;
    w.layout.line_height = 0;
    return true;
}

fn tableGetSortSpecsImpl(ctx: *UiContext) ?*const TableSortSpecs {
    const ts: *const TableState = if (ctx.active_table) |*t| t else return null;
    const p: *TableSortSpecs = ctx.table_sort_state.getPtr(ts.id) orelse return null;
    if (p.len == 0) {
        return null;
    }
    return p;
}

/// Queryable subset of a column's flag state, returned by
/// `tableGetColumnFlags`.  Mirrors the fields of
/// `TableColumnOpts` that are stored 1:1 in `TableColumnState`
/// and can be read back faithfully after `tableSetupColumn`.
///
/// Not included: `sizing` / `width` / `weight` / `width_auto`.
/// Those resolve through inheritance + fallback paths (see
/// `defaultColumnSizing`, `effectiveStretchWeight`,
/// `width_auto_seen`) and aren't roundtrippable — by the time
/// any layout code looks at them, the original opts have been
/// normalized into a single concrete sizing + weight.  Query
/// the column's COMPUTED width via the column state's `width`
/// field directly if needed (no public accessor today; add one
/// behind P8.x if a use case appears).
pub const TableColumnFlags = struct {
    no_sort: bool = false,
    no_sort_ascending: bool = false,
    no_sort_descending: bool = false,
    no_header_label: bool = false,
    default_sort: ?TableSortDirection = null,
};

/// Open / refresh the drag preview window. Symmetric with
/// `beginTooltipImpl`. Lazily allocates on first use; reused
/// across frames.
fn openDragPreviewWindow(ctx: *UiContext) void {
    if (ctx.drag_preview_window == null) {
        const dw: *Window = ctx.gpa.create(Window) catch return;
        dw.* = .{
            .id = 0xFFFFFFFD, // reserved id (tooltip uses 0xFFFFFFFE)
            .pos = .{ 0, 0 },
            .size = .{ 0, 0 },
        };
        ctx.drag_preview_window = dw;
    }
    const dw: *Window = ctx.drag_preview_window.?;

    const padding: Vec2 = ctx.style.frame_padding;
    dw.pos = .{ ctx.input.mouse_pos[0] + 16, ctx.input.mouse_pos[1] + 16 };
    dw.size = .{ 9999, 9999 };
    dw.draw_list.clear();
    dw.layout.cursor_pos = .{ dw.pos[0] + padding[0], dw.pos[1] + padding[1] };
    dw.layout.cursor_max = dw.layout.cursor_pos;
    dw.layout.line_height = 0;

    dw.saved_window_ptr = ctx.current_window;
    dw.saved_draw_list = ctx.current_draw_list;

    ctx.current_window = dw;
    ctx.current_draw_list = &dw.draw_list;
    ctx.drag_preview_active_this_frame = true;
}

fn beginDragDropSourceImpl(ctx: *UiContext, flags: DragDropFlags) bool {
    const w: *Window = ctx.current_window orelse return false;
    const item_id: Id = w.layout.last_item_id;
    if (item_id == 0) {
        return false;
    }

    // Hovered? Reuse the last-item rect from the just-submitted widget.
    const item_hovered: bool = itemHoverable(ctx, w.layout.last_item_rect);

    // Start tracking when the user clicks on a draggable item.
    if (ctx.drag_drop.phase == .idle and item_hovered and ctx.input.mouse_left_clicked) {
        ctx.drag_drop.phase = .pending;
        ctx.drag_drop.source_widget_id = item_id;
        ctx.drag_drop.drag_start_pos = ctx.input.mouse_pos;
        ctx.drag_drop.clearPayload();
    }

    // Only return true for the widget that originated the drag,
    // and only once we've actually crossed the movement threshold.
    if (ctx.drag_drop.phase != .active or ctx.drag_drop.source_widget_id != item_id) {
        return false;
    }

    // Open the preview window (mirrors beginTooltip). Skipped when
    // the caller passes `.source_no_preview = true`.
    // renamed `no_preview` → `source_no_preview` to match
    // imgui's `ImGuiDragDropFlags_SourceNoPreviewTooltip`.
    if (!flags.source_no_preview) {
        openDragPreviewWindow(ctx);
    }
    return true;
}

fn setDragDropPayloadImpl(
    ctx: *UiContext,
    comptime T: type,
    v: *const T,
) void {
    // Only valid inside an active drag started by THIS frame's
    // beginDragDropSource scope. Guard against misuse.
    if (ctx.drag_drop.phase != .active) {
        return;
    }

    const tname: []const u8 = @typeName(T);
    const tlen: usize = @min(tname.len, DragDropState.TYPE_NAME_CAP);
    @memcpy(ctx.drag_drop.type_name_buf[0..tlen], tname[0..tlen]);
    ctx.drag_drop.type_name_len = tlen;

    const size: usize = @sizeOf(T);
    if (size > DragDropState.PAYLOAD_CAP) {
        // Oversize: clear type tag so target won't match.
        ctx.drag_drop.type_name_len = 0;
        ctx.drag_drop.payload_len = 0;
        return;
    }
    // Reinterpret value's bytes as [size]u8 and copy in.
    const src_bytes: [*]const u8 = @ptrCast(v);
    @memcpy(ctx.drag_drop.payload_buf[0..size], src_bytes[0..size]);
    ctx.drag_drop.payload_len = size;
}

fn endDragDropSourceImpl(ctx: *UiContext) void {
    // Symmetric with the tooltip pattern: pop the saved
    // window/draw_list off the preview window if we opened it.
    if (!ctx.drag_preview_active_this_frame) {
        return;
    }
    const dw: *Window = ctx.drag_preview_window orelse return;
    const padding: Vec2 = ctx.style.frame_padding;
    dw.size = .{
        (dw.layout.cursor_max[0] - dw.pos[0]) + padding[0],
        (dw.layout.cursor_max[1] - dw.pos[1]) + padding[1],
    };
    ctx.current_window = dw.saved_window_ptr;
    ctx.current_draw_list = dw.saved_draw_list;
}

fn beginDragDropTargetImpl(ctx: *UiContext, flags: DragDropFlags) bool {
    const w: *Window = ctx.current_window orelse return false;
    const item_id: Id = w.layout.last_item_id;
    if (item_id == 0) {
        return false;
    }

    // Only meaningful when a drag is in flight.
    if (ctx.drag_drop.phase != .active) {
        return false;
    }

    // Cursor must be over the just-submitted widget.
    if (!itemHoverable(ctx, w.layout.last_item_rect)) {
        return false;
    }

    // Mark this widget as the active drop target.
    ctx.drag_drop.target_widget_id = item_id;

    // Visual: highlight ring around the target so the user sees
    // where the drop will land. Outline only (no fill) so the
    // target's own content remains visible. Suppressed by
    // `.accept_no_draw_default_rect` (step 3.7).
    if (!flags.accept_no_draw_default_rect) {
        const dl: *DrawList = &w.draw_list;
        const arena: Allocator = ctx.frame_arena.allocator();
        // Inflate by 2 px so the ring sits OUTSIDE the widget content.
        const r: Rectangle = w.layout.last_item_rect;
        const ring: Rectangle = .{
            .x = r.x - 2,
            .y = r.y - 2,
            .width = r.width + 4,
            .height = r.height + 4,
        };
        dl.addRectOutline(arena, ring, Color.toWire(ctx.style.button_active));
    }
    // `.accept_draw_as_hovered`: also set the item's hovered flag
    // so the next `isItemHovered` call (or post-target user code)
    // reports the target as hovered. Useful for button-shaped
    // drop targets - they "light up" while the payload is over.
    if (flags.accept_draw_as_hovered) {
        w.layout.last_item_hovered = true;
    }
    return true;
}

fn acceptDragDropPayloadImpl(
    ctx: *UiContext,
    comptime T: type,
    flags: DragDropFlags,
) ?T {
    // No-op outside a target scope.
    if (ctx.drag_drop.target_widget_id == 0) {
        return null;
    }
    // No-op without an active drag.
    if (ctx.drag_drop.phase != .active) {
        return null;
    }

    // Type match: tag stored by setDragDropPayload must equal
    // @typeName(T). Also size-check defensively (a target asking
    // for the wrong T would otherwise read undefined trailing
    // bytes).
    const tname: []const u8 = @typeName(T);
    if (!eql(u8, ctx.drag_drop.typeName(), tname)) {
        return null;
    }
    if (ctx.drag_drop.payload_len != @sizeOf(T)) {
        return null;
    }

    // Delivery happens on the release edge - the frame the user
    // lets go of the button. Without this check, every frame the
    // cursor sits on the target during a drag would "accept" the
    // same payload over and over.
    // `.accept_before_delivery` skips the release-edge gate so
    // the caller can peek the payload mid-drag (preview-update
    // patterns, drop-zone enable/disable based on payload type).

    if (!flags.accept_before_delivery and !ctx.input.mouse_left_released) {
        return null;
    }

    // Copy out via @memcpy into a properly-aligned local - the
    // payload buffer is u8-aligned, so direct ptrCast would be UB
    // for any T whose alignment > 1.
    var out: T = undefined;
    @memcpy(std.mem.asBytes(&out), ctx.drag_drop.payload_buf[0..@sizeOf(T)]);
    debugLogPush(ctx, .drop_accepted, "target_id={x} type='{s}'", .{
        ctx.drag_drop.target_widget_id,
        tname,
    });
    return out;
}

fn bulletImpl(ctx: *UiContext) void {
    const w: *Window = ctx.current_window orelse return;
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const dot_size: f32 = 4;
    const offset: f32 = (ctx.style.font_size - dot_size) / 2;

    drawRectFilled(
        ctx,
        .{
            .x = at[0] + offset,
            .y = at[1] + offset,
            .width = dot_size,
            .height = dot_size,
        },
        Color.toWire(ctx.style.text),
    );

    // Consume a fixed-width cell so the next `sameLine` text has
    // predictable left-alignment across rows.
    const cell_w: f32 = ctx.style.font_size;
    const cell_h: f32 = ctx.style.font_size;

    w.layout.last_item_id = 0;
    w.layout.last_item_rect = .{ .x = at[0], .y = at[1], .width = cell_w, .height = cell_h };
    w.layout.last_item_hovered = false;

    advanceLayout(w, .{ cell_w, cell_h }, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

/// Draw a textured quad with explicit UVs and a per-vertex tint.
/// Used by `image`. Two triangles, single rlBegin/rlEnd batch.
fn drawTexturedQuad(
    ctx: *UiContext,
    r: Rectangle,
    tex_id: u32,
    uv0: Vec2,
    uv1: Vec2,
    col: ColorU32,
) void {
    if (ctx.eager_mode or ctx.current_draw_list == null) {
        // Eager-mode debug path: bypass the draw list and emit straight
        // to GL. The live `*GlState` is stashed into UiContext at
        // beginFrame time so we don't need to re-thread it through
        // every widget. Stale outside begin/endFrame - but eager-mode
        // can only be triggered between them.
        if (ctx.frame_gl) |gl| {
            renderTexturedQuad(gl, r, tex_id, uv0, uv1, col);
        }
        return;
    }
    ctx.current_draw_list.?.addTexturedQuad(ctx.frame_arena.allocator(), r, tex_id, uv0, uv1, col);
}

fn imageImpl(
    ctx: *UiContext,
    tex_id: u32,
    size: Vec2,
    flipped: bool,
) void {
    const w: *Window = ctx.current_window orelse return;
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const rect = Rectangle{ .x = at[0], .y = at[1], .width = size[0], .height = size[1] };

    // Y-flip RTs at sample time. raylib's offscreen-pass convention
    // hands us a texture with origin bottom-left, so swap V for the
    // user (matching the pattern in examples/rtt.zig).
    const uv0: Vec2 = if (flipped) .{ 0, 1 } else .{ 0, 0 };
    const uv1: Vec2 = if (flipped) .{ 1, 0 } else .{ 1, 1 };
    drawTexturedQuad(ctx, rect, tex_id, uv0, uv1, 0xFFFFFFFF);

    w.layout.last_item_id = 0;
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = itemHoverable(ctx, rect);

    advanceLayout(w, size, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

fn pushStyleImpl(
    ctx: *UiContext,
    comptime field_name: []const u8,
    value: anytype,
) void {
    const FieldT = @TypeOf(@field(ctx.style, field_name));
    const size: usize = @sizeOf(FieldT);
    if (size > 32) {
        @compileError("pushStyle: field '" ++ field_name ++ "' exceeds the 32-byte snapshot buffer");
    }

    var snap: StyleSnapshot = .{
        .offset = @offsetOf(Style, field_name),
        .size = size,
    };
    // Snapshot the current value via mem.asBytes - same memcpy
    // pattern as the drag-drop payload code, alignment-safe.
    const cur_val: FieldT = @field(ctx.style, field_name);
    @memcpy(snap.backup[0..size], std.mem.asBytes(&cur_val));

    ctx.style_stack.append(snap) catch return;

    // Apply the new value. Type coercion + compile errors flow
    // through Zig's normal assignment rules.
    @field(ctx.style, field_name) = value;
}

fn popStyleImpl(ctx: *UiContext) void {
    const snap: StyleSnapshot = ctx.style_stack.pop() orelse return;
    // Write the saved bytes back to the field's address. Direct
    // byte-level restore works because the snapshot came from the
    // same field's `mem.asBytes` view, so alignment matches by
    // construction.
    const dst: [*]u8 = @ptrCast(&ctx.style);
    @memcpy(dst[snap.offset .. snap.offset + snap.size], snap.backup[0..snap.size]);
}

/// Browser soft-keyboard hints — maps 1:1 to the HTML
/// `inputmode` attribute values.  Only consulted when the
/// runtime is wasm + has a DOM; ignored everywhere else.
///
/// Reference: https://html.spec.whatwg.org/#input-modalities:-the-inputmode-attribute
pub const InputMode = enum {
    /// Default text keyboard.
    text,
    /// Numeric keypad (no decimal point, no sign).
    numeric,
    /// Numeric keypad with decimal point.  Use for general
    /// floating-point input where a sign isn't usually needed.
    decimal,
    /// Email keyboard (typically includes `@` and `.com` keys).
    email,
    /// Telephone keypad.
    tel,
    /// URL keyboard (typically includes `/` and `.com`).
    url,
    /// Search keyboard (typically shows a "search" return key).
    search,

    /// Map to the HTML attribute string the JS bridge sends to
    /// the runtime.  All values are lowercase as the spec requires.
    pub fn toAttr(self: InputMode) []const u8 {
        return switch (self) {
            .text => "text",
            .numeric => "numeric",
            .decimal => "decimal",
            .email => "email",
            .tel => "tel",
            .url => "url",
            .search => "search",
        };
    }
};

pub const InputTextOpts = struct {
    /// Override box width. Zero means auto-fit to remaining row
    /// width (with the label reserved on the right).
    width: f32 = 0,
    /// Placeholder text shown in dimmed (`style.text_disabled`)
    /// color when the buffer is empty AND the widget isn't
    /// focused. Disappears the moment the user types or focuses.
    /// Empty string (default) → no hint. ImGui: parameter to
    /// `InputTextWithHint`; we put it on the opts so a single
    /// `inputText(...)` call can pass a hint without going through
    /// the variant.
    hint: []const u8 = "",

    // ---- A4: text-input callbacks
    // Each non-null callback gets called at the relevant event.
    // `user_data` is opaque - caller casts to whatever typed state
    // they need to consult inside the callback (autocomplete table,
    // history ring buffer, etc.). See `examples/ui_input_callbacks.zig`.
    // Multiline rules:
    //   - `char_filter` and `edit` fire for both single-line AND
    //     multiline.
    //   - `completion` (Tab) and `history` (Up/Down) fire only for
    //     single-line. In multiline, Tab is reserved for future
    //     "insert tab character" behavior and Up/Down already drive
    //     line navigation.

    /// Fires on every printable character about to be inserted.
    /// Callback can replace via `data.event_char = X` or drop via
    /// `data.event_char = 0`.  Run BEFORE the declarative
    /// `chars_*` flags so the user can fully override default
    /// behavior.  ImGui: `CallbackCharFilter`.
    ///
    /// Web-path note: host-only today.  The DOM input/textarea
    /// overlay handles character entry directly without
    /// dispatching back to wasm per-char.  The declarative
    /// `chars_*` flags (turn 440c) have a JS-side mirror that
    /// works on web; the user `char_filter` callback does not.
    /// Web parity for the callback would require a JS↔wasm
    /// round-trip per keystroke — feasible but not yet
    /// implemented.  See turn 442 for the contract on host;
    /// future turn for web parity.
    char_filter: ?InputTextCallback = null,

    /// Fires on every frame the buffer was changed.  Useful for
    /// "type-to-search" / live-filter UIs.  Note: `inputText()`
    /// itself returns true on the same frames; this callback is
    /// useful when you want the buffer state at callback time
    /// (e.g., to update an external index).  ImGui: `CallbackEdit`.
    ///
    /// Web-path note: works on web.  Length-change polling on
    /// the DOM overlay sets `changed=true`, which fires this
    /// callback the same way as on host.  This is the only one
    /// of the four callbacks that's fully cross-platform today.
    edit: ?InputTextCallback = null,

    /// Fires on Tab in single-line.  Callback can rewrite the
    /// buffer via `data.insertChars` / `deleteChars` / `setBuffer`.
    /// Typical use: tab-completion that replaces a typed prefix
    /// with the matching dictionary entry.  Does NOT fire when
    /// `allow_tab_input` is set (that flag takes precedence and
    /// inserts a literal `\t`).  ImGui: `CallbackCompletion`.
    ///
    /// Web-path note: host-only today.  The DOM input/textarea
    /// overlay swallows Tab for browser focus advancement.  Web
    /// parity would need a JS-side `keydown` listener that calls
    /// a wasm export on Tab — straightforward but deferred.
    completion: ?InputTextCallback = null,

    /// Fires on Up or Down arrow in single-line.  Read
    /// `data.history_dir` to know which direction.  Typical use:
    /// shell-style "scroll through prior commands."  Gated on
    /// `!read_only` — a read-only field's history callback would
    /// be unable to mutate the buffer anyway.  ImGui: `CallbackHistory`.
    ///
    /// Web-path note: host-only today.  The DOM input overlay
    /// uses Up/Down for caret navigation within the field.  Web
    /// parity here is harder than completion because the keys
    /// have a legitimate native meaning — would need a flag
    /// telling JS "treat Up/Down as history, not caret nav."
    history: ?InputTextCallback = null,

    /// Opaque pointer passed to every callback. Cast it back to
    /// your typed state in the callback body. Null is fine for
    /// callbacks that don't need state (e.g., a stateless decimal-
    /// only filter).
    user_data: ?*anyopaque = null,

    /// Hint to the browser about which soft-keyboard variant to
    /// show on mobile when this input is focused.  Maps directly
    /// to the HTML `inputmode` attribute on a hidden DOM input
    /// the runtime keeps for IME / mobile keyboard capture.
    /// Desktop browsers and wasm runtimes without a DOM ignore it.
    input_mode: InputMode = .text,

    // ---- P9.1: declarative character filters
    // Run BEFORE `char_filter` callback.  When more than one
    // filter is set, characters must pass ALL of them.  Filters
    // operate on incoming codepoints only — paste / setBuffer
    // bypass them (matches imgui).

    /// Accept only the digits `0`-`9` plus the symbols `.+-`.
    /// For free-form decimal-number entry.  Mirrors imgui's
    /// `ImGuiInputTextFlags_CharsDecimal` minus the legacy `*/`
    /// it includes (those are math-expression characters from
    /// imgui's `InputScalar` heritage; zimr keeps the set focused
    /// on actual numbers).
    chars_decimal: bool = false,

    /// Accept only `0`-`9` + `a`-`f` + `A`-`F`.  For hex colour
    /// entry, hash digests, address fields.  Mirrors imgui's
    /// `ImGuiInputTextFlags_CharsHexadecimal`.
    chars_hexadecimal: bool = false,

    /// Accept only digits + `.+-eE`.  Superset of `chars_decimal`
    /// adding the exponent letters for entries like `1.5e-3`.
    /// Mirrors imgui's `ImGuiInputTextFlags_CharsScientific`.
    chars_scientific: bool = false,

    /// Rewrite incoming `a`-`z` to `A`-`Z` (replace, not drop).
    /// Anything else passes through unchanged.  Use for case-
    /// normalized entry like license plates or stock tickers.
    /// Mirrors imgui's `ImGuiInputTextFlags_CharsUppercase`.
    chars_uppercase: bool = false,

    /// Reject ASCII space (0x20) and horizontal tab (0x09).
    /// Newline isn't blocked here — multiline already controls
    /// newline acceptance independently.  Use for usernames,
    /// identifiers, URLs.  Mirrors imgui's
    /// `ImGuiInputTextFlags_CharsNoBlank`.
    chars_no_blank: bool = false,

    // ---- P9.2: form-flavor behavior flags
    // All five ship both paths.  Host path (used in tests + any
    // hypothetical native desktop backend) gates / changes
    // behavior in `inputTextImpl`.  Web path sets the
    // corresponding attribute on the DOM overlay element via
    // dedicated JS calls.  The DOM overlay does the heavy lifting
    // on web; the host path is the reference behavior the tests
    // pin down.

    /// Return `true` from `inputText()` ONLY on the frame Enter
    /// was pressed (and the widget had focus).  Default behavior:
    /// `inputText()` returns true on every frame the buffer
    /// changed (so callers can react to each keystroke).  Set
    /// this when the caller only wants to act on "commit" —
    /// e.g. a search bar that fires the search on Enter, not
    /// on every character.
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_EnterReturnsTrue`.
    enter_returns_true: bool = false,

    /// Pressing Escape clears the buffer (`len.* = 0`, cursor
    /// returns to 0) AND defocuses.  Default Escape behavior:
    /// just defocus, buffer untouched.  Use for editable fields
    /// where Escape should mean "cancel my edit, start over."
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_EscapeClearsAll`.
    escape_clears: bool = false,

    /// Render buffer content as `*` characters instead of the
    /// real bytes.  Host path: substitution happens in the
    /// rendering branch only — the buffer itself still holds the
    /// real characters; cursor measurement also uses the masked
    /// text (so caret position matches what the user sees).
    /// Web path: the DOM overlay element is given `type="password"`,
    /// so the browser does masking + secure-paste + no-autofill.
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_Password`.
    password_mask: bool = false,

    /// Disable all editing operations.  Cursor + focus still work
    /// (caller can highlight content for copy on web; host path
    /// supports arrow nav for accessibility).  Insertions,
    /// backspace, delete, paste, and the `char_filter` callback
    /// are all gated.  The widget always returns `false` from
    /// `inputText()` because the buffer can't change.  Web path:
    /// the DOM overlay gets `readOnly = true`; the browser
    /// preserves focus + selection but blocks input.
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_ReadOnly`.
    read_only: bool = false,

    /// Pressing Tab inserts an ASCII tab (`\t`, 0x09) into the
    /// buffer instead of triggering the `completion` callback.
    /// Default Tab behavior: dispatch to `opts.completion` if
    /// set, otherwise no-op (and the browser focuses the next
    /// element on web, which usually isn't what the caller
    /// wants for a multi-line code-style edit).  Web path: a
    /// `keydown` handler in the overlay intercepts Tab and
    /// `preventDefault`s it, then inserts `\t` directly into the
    /// input value via `setRangeText`.
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_AllowTabInput`.
    allow_tab_input: bool = false,

    /// Multiline only.  Inverts the default Enter/Ctrl+Enter
    /// behavior:
    ///   - default (off):  Enter inserts `\n`.  Ctrl+Enter is
    ///     ignored.
    ///   - on:             Enter commits + defocuses (plays
    ///     well with `enter_returns_true`).  Ctrl+Enter inserts
    ///     `\n`.
    ///
    /// Use for chat-style boxes where Enter sends the message
    /// and Ctrl+Enter (or Shift+Enter — see "Note" below)
    /// inserts a newline.  Single-line `inputText` ignores this
    /// flag entirely; it has no `\n` insertion path.
    ///
    /// Note: real-world chat UIs often use Shift+Enter for
    /// newline rather than Ctrl+Enter.  The flag is named after
    /// imgui's `CtrlEnterForNewLine` for parity; the caller can
    /// poll `u.isKeyDown(.left_shift)` in `opts.edit` if Shift
    /// semantics are wanted instead.  Future: a separate
    /// `shift_enter_for_newline` opt if a real UI needs it.
    ///
    /// Mirrors imgui's `ImGuiInputTextFlags_CtrlEnterForNewLine`.
    ctrl_enter_for_newline: bool = false,
};

/// Options for `sliderAngle`. Range is specified in DEGREES even
/// though the underlying value is stored in radians - degrees are
/// what users want to see.
pub const SliderAngleOpts = struct {
    /// Minimum value in degrees. Default -360.
    min_deg: f32 = -360,
    /// Maximum value in degrees. Default 360.
    max_deg: f32 = 360,
    /// Display format string. Default appends a degree symbol so
    /// the readout reads naturally ("45°", "-12°").
    fmt: []const u8 = "{d:.0}°",
};

pub const ComboOpts = struct {
    /// Override box width. Zero means auto-fit to remaining row
    /// width (with the label reserved on the right).
    width: f32 = 0,
};

fn comboImpl(
    ctx: *UiContext,
    label: []const u8,
    current_index: *i32,
    items: []const []const u8,
    opts: ComboOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    const padding: Vec2 = ctx.style.frame_padding;
    const row_h: f32 = ctx.style.font_size + 2 * padding[1];
    const arrow_size: f32 = ctx.style.font_size;

    const text_size: Vec2 = measureTextS(ctx, label);
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const reserve_label: f32 = text_size[0] + ctx.style.item_spacing[0];
    const box_w: f32 = effectiveItemWidth(
        ctx,
        opts.width,
        @max(80, inner_right - at[0] - reserve_label),
    );

    const closed_box = Rectangle{ .x = at[0], .y = at[1], .width = box_w, .height = row_h };
    const hovered_closed: bool = itemHoverable(ctx, closed_box);
    if (hovered_closed) {
        ctx.hovered_id = id;
    }

    const was_open: bool = ctx.combo_open_id == id;
    var changed: bool = false;

    // Click on closed row toggles. Opens this combo, implicitly
    // closes any other.
    if (hovered_closed and ctx.input.mouse_left_clicked) {
        if (was_open) {
            ctx.combo_open_id = 0;
        } else {
            ctx.combo_open_id = id;
        }
    }
    const is_open: bool = ctx.combo_open_id == id;

    // ---- Render closed row -------------------------------------------------
    const closed_bg: Color = if (is_open)
        ctx.style.frame_bg_active
    else if (hovered_closed)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, closed_box, Color.toWire(closed_bg));

    // Current item label inside the box (left-aligned, padded).
    const have_valid_index = current_index.* >= 0 and current_index.* < @as(i32, @intCast(items.len));
    if (have_valid_index) {
        drawTextAtS(
            ctx,
            .{ closed_box.x + padding[0], closed_box.y + padding[1] },
            items[@intCast(current_index.*)],
            Color.toWire(ctx.style.text),
        );
    }

    // Arrow indicator on the right (down when open or closed - same
    // glyph, conventional for combos).
    drawTriangleIndicator(
        ctx,
        .{
            .x = closed_box.x + closed_box.width - arrow_size - padding[0],
            .y = closed_box.y + (closed_box.height - arrow_size) / 2,
            .width = arrow_size,
            .height = arrow_size,
        },
        true, // always render down-pointing - ImGui convention
        Color.toWire(ctx.style.text),
    );

    // Label to the right of the box.
    drawTextAtS(
        ctx,
        .{ closed_box.x + closed_box.width + ctx.style.item_spacing[0], closed_box.y + padding[1] },
        label,
        Color.toWire(ctx.style.text),
    );

    // ---- Render dropdown items (only when open)
    // Dropdown emits to the foreground draw list - that's what makes
    // it a real popup: it overlays everything else regardless of
    // submission order, and the layout below doesn't reflow. Click
    // handling for items still happens DURING this combo() call
    // (we have the `current_index` pointer here; we don't have it at
    // foreground_dl render time), but the visual emission is deferred
    // to endFrame's foreground render pass.
    // Provably better than ImGui's combo:
    //  - ImGui's combo is also a popup, but uses the popup-stack +
    //    BeginPopup machinery. Ours uses the foreground draw list
    //    directly with no popup state machine. Same overlay result,
    //    fewer moving parts.
    //  - Our combo only ever needs ONE redirect to foreground_dl;
    //    ImGui pushes a full window onto the popup stack and runs
    //    its layout pipeline. Ours runs trivial linear layout
    //    inline - measurably less code path for the same UX.

    if (is_open and items.len > 0) {
        const dropdown_top: f32 = closed_box.y + closed_box.height;
        const dropdown_height: f32 = float(items.len) * row_h;
        const dropdown_rect = Rectangle{
            .x = closed_box.x,
            .y = dropdown_top,
            .width = closed_box.width,
            .height = dropdown_height,
        };

        // Click handling on dropdown items happens FIRST, while the
        // window's draw list is still active - we mutate combo state
        // (close, set selection) but emit nothing here. All visual
        // emission goes through the foreground_dl redirect below.
        for (items, 0..) |_, i| {
            const item_y: f32 = dropdown_top + float(i) * row_h;
            const item_rect = Rectangle{ .x = closed_box.x, .y = item_y, .width = closed_box.width, .height = row_h };
            if (itemHoverable(ctx, item_rect) and ctx.input.mouse_left_clicked) {
                current_index.* = @intCast(i);
                ctx.combo_open_id = 0;
                changed = true;
            }
        }
        // Click outside both the closed row AND the dropdown closes.
        if (ctx.input.mouse_left_clicked and !hovered_closed and
            !itemHoverable(ctx, dropdown_rect))
        {
            ctx.combo_open_id = 0;
        }

        // Dropdown visuals → foreground draw list. Saved/restored
        // around the emission so any state we change is local.
        // In eager mode (RT scope), foreground_dl isn't used
        // emissions just go straight to rlgl from the helpers.
        const saved_dl: ?*DrawList = ctx.current_draw_list;
        if (!ctx.eager_mode) {
            ctx.current_draw_list = &ctx.foreground_dl;
        }
        defer if (!ctx.eager_mode) {
            ctx.current_draw_list = saved_dl;
        };

        // Background panel - slightly darker than frame_bg to
        // visually separate from the closed row. Plus a 1px border
        // so the popup pops off whatever it's overlaying.
        drawRectFilled(ctx, dropdown_rect, Color.toWire(ctx.style.window_bg));
        drawRect(ctx, dropdown_rect, Color.toWire(ctx.style.border));

        for (items, 0..) |item, i| {
            const item_y: f32 = dropdown_top + float(i) * row_h;
            const item_rect = Rectangle{ .x = closed_box.x, .y = item_y, .width = closed_box.width, .height = row_h };
            const item_hovered: bool = itemHoverable(ctx, item_rect);
            const is_selected = current_index.* == @as(i32, @intCast(i));

            if (item_hovered or is_selected) {
                const item_bg: Color = if (item_hovered)
                    ctx.style.button_hovered
                else
                    ctx.style.button;
                drawRectFilled(ctx, item_rect, Color.toWire(item_bg));
            }

            drawTextAtS(
                ctx,
                .{ item_rect.x + padding[0], item_rect.y + padding[1] },
                item,
                Color.toWire(ctx.style.text),
            );
        }
    }

    // Layout: combo always consumes ONLY the closed-row height,
    // even when open. The dropdown overlays subsequent widgets via
    // the foreground draw list - it does NOT push them down. This
    // is the architectural payoff of going deferred.
    const total_w: f32 = closed_box.width + ctx.style.item_spacing[0] + text_size[0];
    w.layout.last_item_id = id;
    w.layout.last_item_rect = .{ .x = closed_box.x, .y = closed_box.y, .width = total_w, .height = closed_box.height };
    w.layout.last_item_hovered = hovered_closed;
    markItemPost(ctx, w, changed);

    advanceLayout(w, .{ total_w, closed_box.height }, ctx.style.item_spacing, ctx.style.window_padding[0]);
    return changed;
}

/// Called by every widget at end-of-submission with the
/// `consumed` size it occupies on its row. Updates the layout
/// scope's row tracking and advances the cursor to the next row.
/// New model:
/// - `cursor_pos_prev_line` tracks (right edge, row top) - used
///   by `sameLine` to restore the cursor.
/// - `prev_line_height` records the row's tallest widget - used
///   by `sameLine` to restore `line_height` for ongoing
///   accumulation if the row continues.
/// - The cursor wraps to `(origin.x + indent, row_bottom +
///   spacing)`. Row reset uses `layout.origin[0]`, NOT the
///   parent window's `pos[0]` - this is what fixed the editor-
///   pane left-clip bug.
/// The `window_pad_x` argument is retained for callsite-signature
/// compat but no longer participates in the cursor reset (the
/// `LayoutScope.origin` already encodes the content-left).
/// Initialize a window's per-frame layout for a content region whose
/// top-left content cursor is `content_origin` (the caller has already
/// added window padding). This sets `origin` AND `cursor_pos` together,
/// deliberately: they are COUPLED and must agree. The first widget in the
/// window is placed at `cursor_pos`, but `advanceLayout` resets every
/// SUBSEQUENT row's X to `origin[0] + indent - scroll_x` (imgui's
/// Pos.x-based row reset). So setting `cursor_pos` WITHOUT `origin` makes
/// row 0 land correctly while rows 1+ snap to the stale origin (default
/// {0,0} => the canvas left edge). That was exactly the combo/popup
/// dropdown bug: the first item rendered inside the dropdown, the rest
/// jumped to screen-left. ALWAYS init a window's content layout through
/// this helper instead of poking `layout.cursor_pos` field-by-field — it
/// makes the "forgot to set origin" mistake impossible.
fn resetContentLayout(w: *Window, content_origin: Vec2) void {
    w.layout.origin = content_origin;
    w.layout.cursor_pos = content_origin;
    w.layout.cursor_max = content_origin;
    w.layout.line_height = 0;
    w.layout.indent_x = 0;
}

fn beginComboImpl(
    ctx: *UiContext,
    label: []const u8,
    preview: []const u8,
    opts: ComboOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    const padding: Vec2 = ctx.style.frame_padding;
    const row_h: f32 = ctx.style.font_size + 2 * padding[1];
    const arrow_size: f32 = ctx.style.font_size;
    const text_size: Vec2 = measureTextS(ctx, label);
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const reserve_label: f32 = text_size[0] + ctx.style.item_spacing[0];
    const box_w: f32 = effectiveItemWidth(
        ctx,
        opts.width,
        @max(80, inner_right - at[0] - reserve_label),
    );

    const closed_box = Rectangle{ .x = at[0], .y = at[1], .width = box_w, .height = row_h };
    const hovered_closed: bool = itemHoverable(ctx, closed_box);
    if (hovered_closed) {
        ctx.hovered_id = id;
    }

    const was_open: bool = ctx.combo_open_id == id;
    if (hovered_closed and ctx.input.mouse_left_clicked) {
        ctx.combo_open_id = if (was_open) 0 else id;
    }
    const is_open: bool = ctx.combo_open_id == id;

    // -------- Render closed row -------------------------------------------
    const closed_bg: Color = if (is_open)
        ctx.style.frame_bg_active
    else if (hovered_closed)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, closed_box, Color.toWire(closed_bg));
    if (preview.len > 0) {
        drawTextAtS(
            ctx,
            .{ closed_box.x + padding[0], closed_box.y + padding[1] },
            preview,
            Color.toWire(ctx.style.text),
        );
    }
    drawTriangleIndicator(
        ctx,
        .{
            .x = closed_box.x + closed_box.width - arrow_size - padding[0],
            .y = closed_box.y + (closed_box.height - arrow_size) / 2,
            .width = arrow_size,
            .height = arrow_size,
        },
        true,
        Color.toWire(ctx.style.text),
    );
    drawTextAtS(
        ctx,
        .{ closed_box.x + closed_box.width + ctx.style.item_spacing[0], closed_box.y + padding[1] },
        label,
        Color.toWire(ctx.style.text),
    );

    // Layout: combo's closed row consumes its row height regardless
    // of open state, just like combo(). The dropdown floats above
    // subsequent widgets without reflowing them.
    const total_w: f32 = closed_box.width + ctx.style.item_spacing[0] + text_size[0];
    w.layout.last_item_id = id;
    w.layout.last_item_rect = .{ .x = closed_box.x, .y = closed_box.y, .width = total_w, .height = closed_box.height };
    w.layout.last_item_hovered = hovered_closed;
    markItemPost(ctx, w, false);
    advanceLayout(w, .{ total_w, closed_box.height }, ctx.style.item_spacing, ctx.style.window_padding[0]);

    if (!is_open) {
        return false;
    }

    // -------- Open the dropdown popup ------------------------------------
    // Synthetic key `##combo_<hex>` namespaces dropdown windows
    // away from user-named windows + regular popups. Same key on
    // subsequent frames reuses the same persistent Window so its
    // last-frame size is available for the BG draw below.
    var key_buf: [40]u8 = undefined;
    const key: []const u8 = bufPrint(&key_buf, "##combo_{x}", .{id}) catch return false;

    const dropdown_origin: Vec2 = .{ closed_box.x, closed_box.y + closed_box.height };
    const popup_w: *Window = findOrCreateWindow(ctx, key, .{
        .initial_pos = dropdown_origin,
        .initial_size = .{ box_w, row_h },
    });
    popup_w.pos = dropdown_origin;
    // Width always tracks closed-row width; height grows in endCombo
    // based on submitted-widget cursor advancement.
    popup_w.size[0] = box_w;
    popup_w.last_frame_active = ctx.frame_count;
    popup_w.user_resized = true; // suppress auto-fit grow loop quirks

    const inner_origin: Vec2 = .{
        popup_w.pos[0] + ctx.style.window_padding[0],
        popup_w.pos[1] + ctx.style.window_padding[1],
    };
    resetContentLayout(popup_w, inner_origin);

    ctx.window_stack.append(popup_w) catch return false;
    ctx.current_window = popup_w;

    const saved_dl: ?*DrawList = ctx.current_draw_list;
    if (!ctx.eager_mode) {
        popup_w.draw_list.clear();
        ctx.frame_popups.append(popup_w) catch assertUnreachable(@src(), "OOM", .{});
        ctx.current_draw_list = &popup_w.draw_list;
        // Background panel using LAST frame's size (one-frame lag,
        // tolerable for dropdowns). Both fill + border drawn here so
        // they sit BELOW the items the caller is about to submit.
        drawRectFilled(
            ctx,
            .{ .x = popup_w.pos[0], .y = popup_w.pos[1], .width = popup_w.size[0], .height = popup_w.size[1] },
            Color.toWire(ctx.style.popup_bg),
        );
        drawRect(
            ctx,
            .{ .x = popup_w.pos[0], .y = popup_w.pos[1], .width = popup_w.size[0], .height = popup_w.size[1] },
            Color.toWire(ctx.style.border),
        );
    }

    ctx.combo_scope = .{
        .id = id,
        .dropdown_origin = dropdown_origin,
        .dropdown_width = box_w,
        .saved_dl = saved_dl,
        .saved_window = w,
        .cursor_y = popup_w.layout.cursor_pos[1],
    };
    return true;
}

fn endComboImpl(ctx: *UiContext) void {
    const scope: ComboScope = ctx.combo_scope orelse return;
    const popup_w: *Window = ctx.current_window orelse return;

    // Auto-fit height to actual content for next frame's BG draw.
    // Width stays pinned to closed-row width - combos don't expand
    // horizontally with content.
    const content_h: f32 = popup_w.layout.cursor_max[1] - popup_w.pos[1] + ctx.style.window_padding[1];
    popup_w.size[1] = @max(@as(f32, ctx.style.font_size + 2 * ctx.style.frame_padding[1]), content_h);

    // Click outside both the closed row AND the dropdown closes the
    // combo (next frame). Use the popup rect at its CURRENT size,
    // which after this turn's endCombo reflects this frame's content.
    if (!ctx.eager_mode and ctx.input.mouse_left_clicked) {
        const dropdown_rect: Rectangle = .{
            .x = scope.dropdown_origin[0],
            .y = scope.dropdown_origin[1],
            .width = scope.dropdown_width,
            .height = popup_w.size[1],
        };
        const closed_above: Rectangle = .{
            .x = scope.dropdown_origin[0],
            .y = scope.dropdown_origin[1] - (ctx.style.font_size + 2 * ctx.style.frame_padding[1]),
            .width = scope.dropdown_width,
            .height = ctx.style.font_size + 2 * ctx.style.frame_padding[1],
        };
        const click_in_dropdown: bool = itemHoverable(ctx, dropdown_rect);
        const click_on_closed: bool = itemHoverable(ctx, closed_above);
        if (!click_in_dropdown and !click_on_closed) {
            ctx.combo_open_id = 0;
        }
    }

    _ = ctx.window_stack.pop();
    refreshItemClip(ctx);
    if (!ctx.eager_mode) {
        ctx.current_draw_list = scope.saved_dl;
    }
    ctx.combo_scope = null;
}

/// Pixels of indent per nesting level. ImGui default is 21px.
const indent_amount: f32 = 21;

fn treeNodeExImpl(
    ctx: *UiContext,
    label: []const u8,
    opts: TreeNodeOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    // -------- Resolve open state
    // Priority order:
    //   1. setNextItemOpen overrides everything (one-shot; consumed).
    //   2. Stored state if present.
    //   3. `default_open` flag if this is the first encounter.
    //   4. Closed.
    // For leaf nodes, all of the above is moot - leaves always
    // "return true" (so the caller's children-submission block
    // can run if they have one) and never store toggle state.
    var is_open: bool = blk: {
        if (opts.leaf) {
            break :blk true;
        }
        if (ctx.next_item_open) |forced| {
            ctx.next_item_open = null;
            // Persist so subsequent frames see it.
            ctx.tree_open_state.put(ctx.gpa, id, forced) catch assertUnreachable(@src(), "OOM", .{});
            break :blk forced;
        }
        if (ctx.tree_open_state.get(id)) |stored| {
            break :blk stored;
        }
        // First encounter: apply default_open, persist immediately
        // so toggling from open → closed on first click sticks.
        if (opts.default_open) {
            ctx.tree_open_state.put(ctx.gpa, id, true) catch assertUnreachable(@src(), "OOM", .{});
            break :blk true;
        }
        break :blk false;
    };

    // -------- Layout geometry
    // Vertical: frame_padding (default) OR style.frame_padding when
    // `opts.frame_padding = true`. Either way 2*padding[1] is added
    // to font_size for total height.
    const padding: Vec2 = ctx.style.frame_padding;
    const v_pad: f32 = if (opts.frame_padding) padding[1] else 0;
    const total_h: f32 = ctx.style.font_size + 2 * v_pad;
    const text_size: Vec2 = measureTextS(ctx, label);
    const tri_size: f32 = ctx.style.font_size;

    // Horizontal: triangle/bullet/leaf-gap + 4 gap + label.
    // For leaf with neither bullet nor arrow: still reserve the
    // tri_size so leaf nodes vertically align with siblings.
    const indicator_w: f32 = tri_size;
    const label_x_offset: f32 = indicator_w + 4;

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);

    // Width of the highlight / hit rect. `default` covers
    // triangle+gap+label; `avail_width` extends to right edge.
    // Other span variants accepted but treated as `default` /
    // `avail_width` per MVP scope (see TreeNodeSpan doc).
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const natural_w: f32 = label_x_offset + text_size[0];
    const span_w: f32 = switch (opts.span) {
        .default, .label_width => natural_w,
        .avail_width, .full_width, .all_columns, .label_all_columns => inner_right - at[0],
    };

    const rect = Rectangle{ .x = at[0], .y = at[1], .width = span_w, .height = total_h };

    // -------- Hit detect
    // The interact rect depends on `open_trigger`:
    //   - click_anywhere: full `rect`.
    //   - click_arrow: just the indicator's bounding box on the left.
    //   - double_click: full rect but only fires on edge.click2 (TODO).
    const interact_rect: Rectangle = switch (opts.open_trigger) {
        .click_anywhere, .double_click => rect,
        .click_arrow => .{ .x = at[0], .y = at[1], .width = indicator_w, .height = total_h },
    };

    const hovered: bool = itemHoverable(ctx, interact_rect);
    if (hovered) {
        ctx.hovered_id = id;
    }

    // -------- Click → toggle -------------------------------------------
    if (hovered and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
        ctx.active_id_just_activated = true;
    }
    var toggled: bool = false;
    if (ctx.active_id == id and ctx.input.mouse_left_released) {
        if (hovered and !opts.leaf) {
            is_open = !is_open;
            ctx.tree_open_state.put(ctx.gpa, id, is_open) catch assertUnreachable(@src(), "OOM", .{});
            toggled = true;
        }
        ctx.active_id = 0;
    }
    ctx.item_just_toggled = toggled;

    // -------- Render: background
    // `framed`: always draw a frame_bg-color background (looks like
    // a collapsing header).
    // Selected: highlight even when not hovered.
    // Hovered / active: hover/active background.
    if (opts.framed) {
        drawRectFilled(ctx, rect, Color.toWire(ctx.style.frame_bg));
    }
    if (opts.selected) {
        // Use a "header"-ish highlight - reuse button_hovered as the
        // selected-bg slot for now (matches the convention
        // selectable uses). Filed: dedicated `header_*` slots if
        // more widgets want them.
        drawRectFilled(ctx, rect, Color.toWire(ctx.style.button_hovered));
    }
    if (hovered or ctx.active_id == id) {
        const bg: Color = if (ctx.active_id == id)
            ctx.style.frame_bg_active
        else
            ctx.style.frame_bg_hovered;
        drawRectFilled(ctx, rect, Color.toWire(bg));
    }

    // -------- Render: indicator
    // Leaf: no indicator at all (reserves the space for alignment).
    // Bullet: small filled dot.
    // Else: triangle (closed=right, open=down).
    if (!opts.leaf) {
        if (opts.bullet) {
            const bullet_r: f32 = tri_size * 0.18;
            const cx: f32 = at[0] + tri_size * 0.5;
            const cy: f32 = at[1] + total_h * 0.5;
            drawRectFilled(ctx, .{
                .x = cx - bullet_r,
                .y = cy - bullet_r,
                .width = bullet_r * 2,
                .height = bullet_r * 2,
            }, Color.toWire(ctx.style.text));
        } else {
            drawTriangleIndicator(
                ctx,
                .{ .x = at[0], .y = at[1] + (total_h - tri_size) / 2, .width = tri_size, .height = tri_size },
                is_open,
                Color.toWire(ctx.style.text),
            );
        }
    } else if (opts.bullet) {
        // Leaf+bullet: render a bullet at the indicator slot
        // (leaves can still want bullets - matches imgui's
        // "Bullet flag visible regardless of Leaf").
        const bullet_r: f32 = tri_size * 0.18;
        const cx: f32 = at[0] + tri_size * 0.5;
        const cy: f32 = at[1] + total_h * 0.5;
        drawRectFilled(ctx, .{
            .x = cx - bullet_r,
            .y = cy - bullet_r,
            .width = bullet_r * 2,
            .height = bullet_r * 2,
        }, Color.toWire(ctx.style.text));
    }

    // -------- Render: label --------------------------------------------
    drawTextAtS(
        ctx,
        .{ at[0] + label_x_offset, at[1] + v_pad },
        label,
        Color.toWire(ctx.style.text),
    );

    w.layout.last_item_id = id;
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false);

    advanceLayout(w, .{ rect.width, total_h }, ctx.style.item_spacing, ctx.style.window_padding[0]);

    // Push indent for children if open. Matches existing
    // behavior; `no_tree_push_on_open` would skip this but isn't
    // wired in MVP (collapsing-header territory).
    if (is_open and !opts.leaf and !opts.no_tree_push_on_open) {
        w.layout.indent_x += indent_amount;
        w.layout.cursor_pos[0] += indent_amount;
    }

    return is_open;
}

/// Options for `setNextWindowPos` / `setNextWindowSize`. Mirrors
/// ImGui's `ImGuiCond` enum collapsed to the only two we actually
/// support: always (default) and once (apply only on first creation).
pub const SetNextWindowOpts = struct {
    /// If true, the override applies only the first time this window
    /// is created. After that the user can drag/resize freely and
    /// subsequent `setNextWindow*` calls with `once = true` are
    /// ignored. Default false ⇒ apply every frame (ImGui's
    /// `ImGuiCond_Always`).
    once: bool = false,
};

/// Walk to the root of the parent chain. Returns `start` if it
/// has no parent. Bounded at 32 hops same as `isWindowAncestor`.
fn rootWindowOf(ctx: *UiContext, start: *Window) *Window {
    var current: *Window = start;
    var hops: u8 = 0;
    while (hops < 32) : (hops += 1) {
        const parent_id: Id = current.parent_id orelse return current;
        const parent: *Window = ctx.windows.get(parent_id) orelse return current;
        current = parent;
    }
    return current;
}

/// Walk up `descendant`'s `parent_id` chain looking for `ancestor`.
/// Returns true if descendant IS ancestor, OR if ancestor sits
/// anywhere on the chain. Used by `isWindowHovered` /
/// `isWindowFocused` for the `child_windows` flag - "is the
/// hovered/focused window me or a descendant of me?"
/// Bounded at 32 hops to defend against accidental cycles (which
/// shouldn't be possible - parent_id is set once per frame from
/// the window_stack - but cheap belt-and-suspenders).
fn isWindowAncestor(
    ctx: *UiContext,
    ancestor: *const Window,
    descendant_id: Id,
) bool {
    var current_id: Id = descendant_id;
    var hops: u8 = 0;
    while (hops < 32) : (hops += 1) {
        if (current_id == ancestor.id) {
            return true;
        }
        const cur: *const Window = ctx.windows.get(current_id) orelse return false;
        const parent_id: Id = cur.parent_id orelse return false;
        current_id = parent_id;
    }
    return false;
}

/// Read effective ItemFlags - top of `item_flags_stack`, or
/// all-defaults if empty.
fn currentItemFlagsImpl(ctx: *UiContext) ItemFlags {
    const len: usize = ctx.item_flags_stack.len;
    if (len == 0) {
        return .{};
    }
    return ctx.item_flags_stack.items[len - 1];
}

fn closePopupScope(ctx: *UiContext) void {
    const popup_w: *Window = ctx.current_window orelse return;

    // Auto-fit size to content used this frame (popups always
    // auto-fit; user can't manually resize them).
    const content_w: f32 = popup_w.layout.cursor_max[0] - popup_w.pos[0] + ctx.style.window_padding[0];
    const content_h: f32 = popup_w.layout.cursor_max[1] - popup_w.pos[1] + ctx.style.window_padding[1];
    if (content_w > popup_w.size[0]) {
        popup_w.size[0] = content_w;
    }
    if (content_h > popup_w.size[1]) {
        popup_w.size[1] = content_h;
    }

    // Pop content clip rect.
    if (!ctx.eager_mode) {
        popup_w.draw_list.popClipRect(ctx.frame_arena.allocator());
    }

    // Pop window + popup stack.
    _ = ctx.window_stack.pop();
    _ = ctx.popup_stack.pop();
    ctx.current_window = if (ctx.window_stack.len > 0)
        ctx.window_stack.items[ctx.window_stack.len - 1]
    else
        null;
    // ★ Interaction is clipped to the window that owns it. Outside any window (an overlay
    // drawn straight to the viewport) there is nothing to clip against.
    ctx.item_clip = if (ctx.current_window) |cw| Rectangle{
        .x = cw.pos[0],
        .y = cw.pos[1],
        .width = cw.size[0],
        .height = cw.size[1],
    } else null;
    if (!ctx.eager_mode) {
        if (ctx.current_window) |outer| {
            ctx.current_draw_list = &outer.draw_list;
        } else {
            ctx.current_draw_list = null;
        }
    }
}

fn openMainMenuBar(ctx: *UiContext) bool {
    // Allocate the synthetic bar window lazily. Same persistent
    // storage as regular windows, keyed by a `##main_menu_bar`
    // synthetic title (won't collide with any user-named window).
    if (ctx.main_menu_bar_win == null) {
        const bar: *Window = findOrCreateWindow(
            ctx,
            "##main_menu_bar",
            .{
                .initial_pos = .{ 0, 0 },
                .initial_size = .{ 0, ctx.style.menu_bar_height },
            },
        );
        bar.user_resized = true; // skip auto-fit grow
        ctx.main_menu_bar_win = bar;
    }
    const bar: *Window = ctx.main_menu_bar_win.?;
    const cw: f32 = float(ctx.canvas_w);
    bar.pos = .{ 0, 0 };
    bar.size = .{ cw, ctx.style.menu_bar_height };
    bar.last_frame_active = ctx.frame_count;
    bar.layout.cursor_pos = .{ 8, 0 };
    bar.layout.cursor_max = bar.layout.cursor_pos;
    bar.layout.line_height = ctx.style.menu_bar_height;
    bar.layout.indent_x = 0;

    // Push onto window stack + record menu-bar mode.
    ctx.window_stack.append(bar) catch {
        return false;
    };
    ctx.current_window = bar;
    ctx.in_menu_bar = true;
    ctx.active_menu_bar_win = bar;
    ctx.menu_bar_cursor_x = 8;
    ctx.menu_bar_bottom_y = ctx.style.menu_bar_height;

    // Append to per-frame popup list so the bar replays AFTER
    // regular windows (above all content) but BEFORE foreground
    // (tooltips still float on top). Popups submitted from inside
    // beginMenu will append later; bar appears first → menus on top.
    if (!ctx.eager_mode) {
        bar.draw_list.clear();
        ctx.frame_popups.append(bar) catch assertUnreachable(@src(), "OOM", .{});
        ctx.current_draw_list = &bar.draw_list;
    }

    // Render bar background.
    drawRectFilled(
        ctx,
        .{ .x = 0, .y = 0, .width = cw, .height = ctx.style.menu_bar_height },
        Color.toWire(ctx.style.menu_bar_bg),
    );
    return true;
}

fn closeMainMenuBar(ctx: *UiContext) void {
    if (!ctx.in_menu_bar) {
        return;
    }
    ctx.in_menu_bar = false;
    ctx.active_menu_bar_win = null;
    _ = ctx.window_stack.pop();
    refreshItemClip(ctx);
    if (!ctx.eager_mode) {
        if (ctx.current_window) |outer| {
            ctx.current_draw_list = &outer.draw_list;
        } else {
            ctx.current_draw_list = null;
        }
    }
}

/// Per-window menu bar. Unlike `openMainMenuBar`, this one doesn't
/// spin up a synthetic bar window - the bar is drawn into the
/// CURRENT window's pixels at a horizontal strip just below the
/// title bar. Menu items + their dropdowns reuse the same paths
/// as the main bar via `active_menu_bar_win`.
/// Position: the bar occupies `[win.pos.y + title_bar_height,
/// win.pos.y + title_bar_height + menu_bar_height)`. The window's
/// content cursor is bumped down by `menu_bar_height` so user widgets
/// don't draw on top. No interaction with `window_padding.y` - the
/// bar sits flush with the title bar; padding kicks in BELOW the
/// bar before content.
fn openWindowMenuBar(ctx: *UiContext) bool {
    if (ctx.in_menu_bar) {
        return false;
    } // already in a bar - caller bug
    const win: *Window = ctx.current_window orelse return false;
    // P5.5a: require `WindowFlags.menu_bar` on the parent
    // window. Matches imgui's `ImGuiWindowFlags_MenuBar` contract —
    // callers must declare intent at window creation time. This
    // lets a future layout pass reserve the menu-bar's height
    // *before* content is submitted (today we shift cursor down
    // mid-frame, which is fine for single-frame menus but blocks
    // proper layout-driven content rect computation).
    if (!win.flags.menu_bar) {
        return false;
    }
    const bar_h: f32 = ctx.style.menu_bar_height;
    const bar_y: f32 = win.pos[1] + ctx.style.title_bar_height;
    // Paint bar background using current_draw_list (the parent
    // window's list). Same color as the main menu bar so the look
    // is consistent across the two bar paths.
    drawRectFilled(
        ctx,
        .{ .x = win.pos[0], .y = bar_y, .width = win.size[0], .height = bar_h },
        Color.toWire(ctx.style.menu_bar_bg),
    );
    // Activate bar-mode. `menu_bar_cursor_x` / `menu_bar_bottom_y`
    // live in canvas coords so `openMenu` can position the button
    // and anchor its popup without caring which bar path opened us.
    ctx.in_menu_bar = true;
    ctx.active_menu_bar_win = win;
    ctx.menu_bar_cursor_x = win.pos[0] + 8;
    ctx.menu_bar_bottom_y = bar_y + bar_h;
    // Push window content down past the bar so subsequent widgets
    // in the user's window body land below it.
    win.layout.cursor_pos[1] += bar_h;
    win.layout.cursor_max[1] = @max(win.layout.cursor_max[1], win.layout.cursor_pos[1]);
    return true;
}

fn closeWindowMenuBar(ctx: *UiContext) void {
    if (!ctx.in_menu_bar) {
        return;
    }
    ctx.in_menu_bar = false;
    ctx.active_menu_bar_win = null;
}

fn openMenu(
    ctx: *UiContext,
    label: []const u8,
    enabled: bool,
) bool {
    if (!ctx.in_menu_bar) {
        // Submenu inside an open menu - also handled like a popup
        // anchored to the parent menu's row. Out of scope for
        // 's first cut; left as no-op for now.
        return false;
    }
    const bar: *Window = ctx.active_menu_bar_win orelse return false;
    const id: Id = hashStr(bar.id, label);
    const padding_x: f32 = 12;
    const text_size: Vec2 = measureTextS(ctx, label);
    const button_w: f32 = text_size[0] + 2 * padding_x;
    const button_h: f32 = ctx.style.menu_bar_height;
    const button_rect: Rectangle = .{
        .x = ctx.menu_bar_cursor_x,
        // The bar's top in canvas coords. menu_bar_bottom_y = bar_top + bar_h
        // for BOTH paths (main bar: bottom=height so this is 0; per-window bar:
        // win.pos.y + title_h). Was hardcoded 0 — correct only for the main bar,
        // so per-window menu labels drew at the canvas top instead of in the
        // window's strip (and hit-tested there too). This fixes both.
        .y = ctx.menu_bar_bottom_y - button_h,
        .width = button_w,
        .height = button_h,
    };
    const hovered: bool = enabled and itemHoverable(ctx, button_rect);
    if (hovered) {
        ctx.hovered_id = id;
    }

    const popup_id: Id = hashStr(bar.id, label); // the menu's popup uses this key
    const anchor: Vec2 = .{ button_rect.x, ctx.menu_bar_bottom_y };

    // Single-open + hover-tracking (imgui menu-bar behaviour). `bar_open_menu` is
    // the ONE menu the bar treats as open (only one is ever open at a time) — the
    // intent — while `popup_open` is the live popup set (which click-outside
    // dismissal also edits).
    // 0) If the designated menu was dismissed externally (clicked outside), drop
    //    the intent so a later hover doesn't spuriously reopen it.
    if (ctx.bar_open_menu) |open_id| {
        if (!ctx.popup_open.contains(open_id)) {
            ctx.bar_open_menu = null;
        }
    }
    // 1) Tracking: once a menu is open, hovering a DIFFERENT label switches to it.
    if (ctx.bar_open_menu != null and hovered and ctx.bar_open_menu.? != popup_id) {
        ctx.popup_open.put(ctx.gpa, popup_id, .{ .anchor = anchor, .opened_at_frame = ctx.frame_count }) catch
            assertUnreachable(@src(), "OOM", .{});
        ctx.bar_open_menu = popup_id;
    }
    // 2) Click toggles this menu (open when closed, close when already open).
    if (hovered and ctx.input.mouse_left_clicked) {
        if (ctx.bar_open_menu == popup_id) {
            _ = ctx.popup_open.remove(popup_id);
            ctx.bar_open_menu = null;
        } else {
            ctx.popup_open.put(ctx.gpa, popup_id, .{ .anchor = anchor, .opened_at_frame = ctx.frame_count }) catch
                assertUnreachable(@src(), "OOM", .{});
            ctx.bar_open_menu = popup_id;
        }
    }
    // 3) Single-open: any menu that's open but NOT the designated one closes.
    if (ctx.bar_open_menu != null and ctx.bar_open_menu.? != popup_id and ctx.popup_open.contains(popup_id)) {
        _ = ctx.popup_open.remove(popup_id);
    }
    const is_open: bool = ctx.bar_open_menu == popup_id and ctx.popup_open.contains(popup_id);
    if (is_open) {
        // Remember the button rect so click-outside dismissal can tell a toggle
        // click (on the button) from a real outside click (it runs next frame).
        ctx.bar_open_menu_btn = button_rect;
    }

    // Render button background - accent on hover OR open state.
    if (hovered or is_open) {
        drawRectFilled(ctx, button_rect, Color.toWire(ctx.style.menu_hovered));
    }
    // Label, vertically centered.
    drawTextAtS(
        ctx,
        .{ button_rect.x + padding_x, button_rect.y + (button_h - ctx.style.font_size) / 2 },
        label,
        Color.toWire(ctx.style.text),
    );

    // Advance bar cursor.
    ctx.menu_bar_cursor_x += button_w;

    if (!is_open) {
        return false;
    }
    // Enter the menu's popup scope. Anchor was set at click-time
    // to the button's bottom-left. The popup's body submission
    // begins now; user calls menuItem(...) inside.
    return openPopupScope(ctx, label);
}

pub const MenuItemOpts = struct {
    /// Optional right-aligned shortcut hint (e.g. "Ctrl+S").
    /// Display-only - caller still wires the actual key handler.
    shortcut: []const u8 = "",
    /// Show a checkmark on the left. Toggle-style menu items
    /// pass their boolean's current value here.
    selected: bool = false,
    /// Greyed-out + non-interactive when false.
    enabled: bool = true,
};

fn menuItemImpl(
    ctx: *UiContext,
    label: []const u8,
    opts: MenuItemOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);
    const padding: Vec2 = ctx.style.frame_padding;
    const row_h: f32 = ctx.style.font_size + 2 * padding[1];

    // Full-row layout - extend to the parent popup's right edge.
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    // Min row width: label + shortcut + 2 paddings + spacing.
    const label_size: Vec2 = measureTextS(ctx, label);
    const shortcut_size: Vec2 = if (opts.shortcut.len > 0)
        measureTextS(ctx, opts.shortcut)
    else
        .{ 0, 0 };
    const min_w: f32 = label_size[0] + shortcut_size[0] + 4 * padding[0] + ctx.style.item_spacing[0];
    const row_w: f32 = @max(min_w, inner_right - at[0]);
    const rect: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = row_w,
        .height = row_h,
    };

    const ptr_in_rect: bool = itemHoverable(ctx, rect);
    const hovered: bool = opts.enabled and ptr_in_rect;
    if (hovered) {
        ctx.hovered_id = id;
    }
    var clicked: bool = false;
    if (hovered and ctx.input.mouse_left_clicked) {
        clicked = true;
        // Auto-close the menu on item click - matches OS-style
        // menu UX. Closes the topmost popup (the menu itself).
        if (ctx.popup_stack.top()) |top_id| {
            _ = ctx.popup_open.remove(top_id);
        }
    }

    // Background - hover highlight; greyed if disabled.
    if (hovered) {
        drawRectFilled(ctx, rect, Color.toWire(ctx.style.menu_hovered));
    }
    // Optional checkmark (on the left, before the label).
    const checkmark_size: f32 = 8;
    const left_pad: f32 = padding[0] * 3; // room for a checkmark
    if (opts.selected) {
        drawRectFilled(
            ctx,
            .{
                .x = rect.x + padding[0],
                .y = rect.y + (row_h - checkmark_size) / 2,
                .width = checkmark_size,
                .height = checkmark_size,
            },
            Color.toWire(ctx.style.text),
        );
    }
    const text_col: Color = if (opts.enabled) ctx.style.text else ctx.style.text_disabled;
    drawTextAtS(
        ctx,
        .{ rect.x + left_pad, rect.y + padding[1] },
        label,
        Color.toWire(text_col),
    );
    // Right-aligned shortcut text.
    if (opts.shortcut.len > 0) {
        drawTextAtS(
            ctx,
            .{ rect.x + rect.width - shortcut_size[0] - padding[0], rect.y + padding[1] },
            opts.shortcut,
            Color.toWire(ctx.style.text_disabled),
        );
    }

    w.layout.last_item_id = id;
    w.layout.last_item_rect = rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false);
    advanceLayout(
        w,
        .{ rect.width, rect.height },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return clicked;
}

/// Pop the persisted selected-tab label for a `(window_name, str_id)`
/// pair. Returns null when nothing was persisted for this bar.
/// Returns an empty string when the persistence layer recorded an
/// entry but no tab was selected - caller can treat empty as
/// "no selection" (matches `state.selected_id = 0` semantics).
/// Returned slice is owned by the caller; free with `ctx.gpa.free`.
pub fn takeTabBarSelection(
    ctx: *UiContext,
    window_name: []const u8,
    str_id: []const u8,
) ?[]const u8 {
    // Build a transient compound key to look up; we don't want
    // to allocate just for the lookup, so use a small stack
    // buffer with a fallback to gpa for unusually long names.
    var stack_buf: [256]u8 = undefined;
    const needed: usize = window_name.len + 1 + str_id.len;
    var search_key: []const u8 = undefined;
    var search_key_owned: ?[]u8 = null;
    defer if (search_key_owned) |b| ctx.gpa.free(b);
    if (needed <= stack_buf.len) {
        @memcpy(stack_buf[0..window_name.len], window_name);
        stack_buf[window_name.len] = 0;
        @memcpy(stack_buf[window_name.len + 1 .. needed], str_id);
        search_key = stack_buf[0..needed];
    } else {
        const owned = ctx.gpa.alloc(u8, needed) catch return null;
        @memcpy(owned[0..window_name.len], window_name);
        owned[window_name.len] = 0;
        @memcpy(owned[window_name.len + 1 ..], str_id);
        search_key_owned = owned;
        search_key = owned;
    }

    const entry: std.StringHashMapUnmanaged([]const u8).KV =
        ctx.pending_tab_bar_selections.fetchRemove(search_key) orelse return null;
    // Free the entry's key (we allocated it in `apply`); return
    // the value slice to the caller.
    ctx.gpa.free(@constCast(entry.key));
    return entry.value;
}

fn openTabBar(
    ctx: *UiContext,
    str_id: []const u8,
    flags: TabBarFlags,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, str_id);
    // Resolve any pending sameLine; we want the bar at the current row.
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const bar_h: f32 = ctx.style.font_size + 2 * ctx.style.frame_padding[1];
    const right_x: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const bar_rect: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = @max(0, right_x - at[0]),
        .height = bar_h,
    };

    // Find or create persistent state.
    if (!ctx.tab_bar_state.contains(id)) {
        ctx.tab_bar_state.put(ctx.gpa, id, .{}) catch return false;
        // on first-creation, populate the
        // bar's name fields so persistence (and any other consumer
        // that needs a stable human identifier) can round-trip the
        // bar without holding onto the user's borrowed str_id.
        // Done here rather than in TabBarState's init so we don't
        // need to plumb name through `getPtr`/`put` calls.
        const new_state: *TabBarState = ctx.tab_bar_state.getPtr(id).?;
        const wname: []const u8 = w.name();
        const wname_n: usize = @min(wname.len, new_state.parent_window_name_buf.len);
        @memcpy(new_state.parent_window_name_buf[0..wname_n], wname[0..wname_n]);
        new_state.parent_window_name_len = wname_n;
        const sid_n: usize = @min(str_id.len, new_state.str_id_buf.len);
        @memcpy(new_state.str_id_buf[0..sid_n], str_id[0..sid_n]);
        new_state.str_id_len = sid_n;

        // Persistence restore: if the persistence layer
        // staged a selected-tab label for this (window, str_id)
        // pair on startup, hash it now to derive the would-be tab
        // Id and stash on `selected_id`. beginTabItem's equality
        // check then routes the matching tab as active. If no tab
        // submitted this frame matches the persisted id, the
        // fallback path in closeTabBar resets `selected_id` to 0
        // so first-tab-auto-select kicks in next frame.
        if (takeTabBarSelection(ctx, wname, str_id)) |label| {
            defer ctx.gpa.free(@constCast(label));
            new_state.selected_id = hashStr(id, label);
        }
    }
    const state: *TabBarState = ctx.tab_bar_state.getPtr(id).?;
    state.last_frame_active = ctx.frame_count;

    ctx.tab_bar_stack.append(.{
        .id = id,
        .rect = bar_rect,
        .flags = flags,
        .leading_cursor_x = bar_rect.x,
        .middle_cursor_x = bar_rect.x, // leading section grows this rightward
        .trailing_cursor_x = bar_rect.x + bar_rect.width, // trailing grows leftward
        .selection_changed_this_frame = false,
        .pushed_tab_id_this_item = false,
    }) catch return false;

    // ---- Underline separator running across the bar's full width ----
    //

    // Drawn HERE (before any tabs are submitted) so per-tab background
    // rects can overdraw it. Active tabs render at full bar height
    // and so cover the separator at their position — that's the visual
    // "lift" effect (the active tab merges with the content below).
    // Inactive tabs render at `bar_height - 1` so the separator
    // remains visible at their bottom edge.
    //

    // Previously this was drawn in closeTabBar, AFTER the tabs. That
    // meant the separator overdrew every tab including the active
    // one, and a separately-drawn 1px lift slice was needed to
    // restore the active-tab merge. Drawing separator-first lets us
    // get the lift effect for free via the tab bg's own geometry.
    // imgui takes a third route — drawing the tab shape with rounded
    // top corners that geometrically end above the separator
    // (`imgui_widgets.cpp:10991`, `TabItemBackground`). Our flat-rect
    // approach is simpler at the cost of one cosmetic detail (no
    // rounded corners).
    drawRectFilled(
        ctx,
        .{
            .x = bar_rect.x,
            .y = bar_rect.y + bar_rect.height - 1,
            .width = bar_rect.width,
            .height = 1,
        },
        Color.toWire(ctx.style.tab_separator),
    );

    // Advance the parent cursor past the bar's full row NOW. Doing
    // this in `closeTabBar` instead - as we used to - meant the
    // active tab's content was submitted at the same y as
    // the tab strip itself, overlapping the strip. Advancing here
    // lays out the strip at `at`, then leaves the cursor on the row
    // below it for the active tab's body. Visible in the
    // ui_tabbar_bug-turn317.png screenshot when the bug was present.
    advanceLayout(
        w,
        .{ bar_rect.width, bar_rect.height },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );

    return true;
}

fn closeTabBar(ctx: *UiContext) void {
    const frame: TabBarFrame = ctx.tab_bar_stack.pop() orelse return;
    const state: *TabBarState = ctx.tab_bar_state.getPtr(frame.id) orelse return;

    // ---- GC tabs whose caller stopped submitting them this frame ----
    // Walk backwards so removals don't shift indices we haven't visited.
    var i: usize = state.tabs.items.len;
    while (i > 0) {
        i -= 1;
        if (state.tabs.items[i].last_frame_active < ctx.frame_count) {
            // If the GC'd tab was selected, clear so endTabBar's "first
            // tab takes over" code path runs next frame.
            if (state.tabs.items[i].id == state.selected_id) {
                state.selected_id = 0;
            }
            _ = state.tabs.orderedRemove(i);
        }
    }

    // ---- Finalize close-clicks (set caller's open_ptr.* = false) -----
    // Done here so callers see the change on the NEXT frame's begin
    // (we don't want want_close to also affect the rendering of THIS
    // frame - clicking the X this frame still keeps the tab visible
    // until the user submits next frame; matches imgui semantics).
    for (state.tabs.items) |*t| {
        if (t.want_close) {
            if (t.open_ptr_cache) |p| {
                p.* = false;
            }
            t.want_close = false;
        }
    }

    // persistence: if `selected_id` was restored from a
    // persisted payload at openTabBar time but no submitted tab
    // matches that id (the caller may have removed the tab between
    // sessions), reset to 0 so first-tab-auto-select takes over
    // next frame. Without this, the bar shows no active tab
    // visible only on the first post-reload frame.
    if (state.selected_id != 0 and state.findTab(state.selected_id) == null) {
        state.selected_id = 0;
    }

    // Remember bar's bottom edge for external anchors.
    // (The bar's underline separator was drawn in openTabBar — see
    // the comment block there for why it's first, not last.)
    state.bottom_y = frame.rect.y + frame.rect.height;

    // (Parent cursor was advanced in `openTabBar` so active-tab
    // content lays out below the strip rather than overlapping it.
    // bug fix - see the comment block there.)
}

fn closeTabItem(ctx: *UiContext) void {
    if (ctx.tab_bar_stack.len == 0) {
        return;
    }
    const frame_idx: usize = ctx.tab_bar_stack.len - 1;
    const frame: *TabBarFrame = &ctx.tab_bar_stack.items[frame_idx];
    if (frame.pushed_tab_id_this_item) {
        _ = ctx.id_stack.pop();
        frame.pushed_tab_id_this_item = false;
    }
}

fn closeListBox(ctx: *UiContext) void {
    const list_box: *Window = ctx.current_window orelse return;
    if (!list_box.flags.is_child) {
        return;
    } // mismatched begin/end - bail safely

    // Capture the list box's outer rect before we pop, so we can
    // advance the parent's cursor past it AND hit-test the wheel.
    const box_rect: Rectangle = .{
        .x = list_box.pos[0],
        .y = list_box.pos[1],
        .width = list_box.size[0],
        .height = list_box.size[1],
    };

    // ---- Scroll bookkeeping
    // Same shape as `endChildImpl` - see notes there.
    const inner_origin_y: f32 = list_box.layout.origin[1];
    const content_h_natural: f32 = list_box.layout.cursor_max[1] + list_box.scroll_y - inner_origin_y;
    const viewport_h: f32 = @max(0, list_box.layout.work_rect_max[1] - inner_origin_y);
    list_box.scroll_max_y = @max(0, content_h_natural - viewport_h);

    if (!ctx.mouse_wheel_consumed and ctx.input.mouse_wheel_y != 0 and itemHoverable(ctx, box_rect)) {
        const wheel_speed: f32 = 5 * ctx.style.font_size;
        list_box.scroll_y -= ctx.input.mouse_wheel_y * wheel_speed;
        ctx.mouse_wheel_consumed = true;
    }
    list_box.scroll_y = clamp(list_box.scroll_y, 0, list_box.scroll_max_y);

    // Pop content clip, then render scrollbar (so the scrollbar
    // isn't clipped out alongside the content).
    if (!ctx.eager_mode) {
        if (ctx.current_draw_list) |dl| {
            dl.popClipRect(ctx.frame_arena.allocator());
        }
    }
    if (list_box.scroll_max_y > 0) {
        renderScrollbar(ctx, list_box);
    }

    _ = ctx.id_stack.pop();
    _ = ctx.window_stack.pop();
    const parent: *Window = if (ctx.window_stack.len > 0)
        ctx.window_stack.items[ctx.window_stack.len - 1]
    else
        return; // malformed nesting
    ctx.current_window = parent;

    // The list box becomes the parent's "last item" so `isItemHovered`
    // after `endListBox` queries the box's outer rect. Set the id
    // to the list_box_id (NOT zero like beginChild's child rect)
    // because the list box IS an interactive item - focus state
    // hangs off it.
    parent.layout.last_item_id = list_box.id;
    parent.layout.last_item_rect = box_rect;
    parent.layout.last_item_hovered = itemHoverable(ctx, box_rect);

    // Advance the parent's cursor past the box's outer size.
    advanceLayout(parent, .{ box_rect.width, box_rect.height }, ctx.style.item_spacing, ctx.style.window_padding[0]);
}

fn listBoxImpl(
    ctx: *UiContext,
    label: []const u8,
    current: *i32,
    items: []const []const u8,
) bool {
    const ui: Ui = .{ .ctx = ctx };
    if (!ui.beginListBox(label, .{ 0, 0 })) {
        return false;
    }
    defer ui.endListBox();

    var changed: bool = false;
    var i: i32 = 0;
    while (i < @as(i32, @intCast(items.len))) : (i += 1) {
        const idx: usize = @intCast(i);
        const sel: bool = current.* == i;
        if (ui.selectable(items[idx], sel, .{})) {
            if (current.* != i) {
                current.* = i;
                changed = true;
            }
        }
    }
    return changed;
}

fn progressBarImpl(
    ctx: *UiContext,
    fraction: f32,
    size: Vec2,
    overlay: []const u8,
) void {
    const w: *Window = ctx.current_window orelse return;
    const padding: Vec2 = ctx.style.frame_padding;
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);

    // Resolve auto sizes. Width: full content row. Height: 1 text row + padding.
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const default_w: f32 = @max(60, inner_right - at[0]);
    const default_h: f32 = ctx.style.font_size + 2 * padding[1];
    const bar_w: f32 = if (size[0] > 0) size[0] else default_w;
    const bar_h: f32 = if (size[1] > 0) size[1] else default_h;
    const bar: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = bar_w,
        .height = bar_h,
    };

    // Clamp fraction to [0, 1].
    const f_clamped: f32 = clamp(fraction, 0, 1);
    const fill_w: f32 = bar_w * f_clamped;
    const fill: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = fill_w,
        .height = bar_h,
    };

    // Background, then fill.
    drawRectFilled(ctx, bar, Color.toWire(ctx.style.frame_bg));
    drawRectFilled(ctx, fill, Color.toWire(ctx.style.button));

    // Optional centred overlay caption.
    if (overlay.len > 0) {
        const overlay_size: Vec2 = measureTextS(ctx, overlay);
        const overlay_pos: Vec2 = .{ at[0] + (bar_w - overlay_size[0]) / 2, at[1] + (bar_h - ctx.style.font_size) / 2 };
        drawTextAtS(ctx, overlay_pos, overlay, Color.toWire(ctx.style.text));
    }

    // Item-state record + cursor advance.
    w.layout.last_item_id = 0;
    w.layout.last_item_rect = bar;
    w.layout.last_item_hovered = itemHoverable(ctx, bar);
    markItemPost(ctx, w, false);
    advanceLayout(
        w,
        .{ bar_w, bar_h },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
}

fn vSliderScalar(
    ctx: *UiContext,
    label: []const u8,
    size: Vec2,
    value: anytype,
    comptime T: type,
    opts: SliderOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);
    const padding: Vec2 = ctx.style.frame_padding;

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const default_w: f32 = ctx.style.font_size + 2 * padding[0];
    const default_h: f32 = ctx.style.font_size * 6;
    const bar_w: f32 = if (size[0] > 0) size[0] else default_w;
    const bar_h: f32 = if (size[1] > 0) size[1] else default_h;
    const bar: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = bar_w,
        .height = bar_h,
    };

    const ptr_in_bar: bool = itemHoverable(ctx, bar);
    if (ptr_in_bar) {
        ctx.hovered_id = id;
    }
    var changed: bool = false;

    // Click-to-grab - capture active_id while dragging.
    if (ptr_in_bar and ctx.input.mouse_left_clicked) {
        ctx.active_id = id;
    }
    const is_active: bool = ctx.active_id == id;
    if (is_active and !ctx.input.mouse_left_down) {
        ctx.active_id = 0;
    }

    // While active, drive the value from mouse_y position within bar.
    if (is_active) {
        const t: f32 = clamp((ctx.input.mouse_pos[1] - bar.y) / bar.height, 0, 1);
        // ImGui's vertical-slider convention: top = max, bottom = min.
        const t_inverted: f32 = 1.0 - t;
        const new_v_f64: f64 = opts.min + (opts.max - opts.min) * @as(f64, t_inverted);
        const new_v: T = scalarFromF64(T, new_v_f64);
        if (new_v != value.*) {
            value.* = new_v;
            changed = true;
        }
    }

    // Render bar background + filled portion.
    drawRectFilled(ctx, bar, Color.toWire(ctx.style.frame_bg));
    const cur_f64: f64 = scalarToF64(T, value.*);
    const range: f64 = opts.max - opts.min;
    const t_cur: f64 = if (range == 0) 0 else (cur_f64 - opts.min) / range;
    const fill_h: f32 = bar_h * @as(f32, @floatCast(t_cur));
    const grab_col: Color = if (is_active)
        ctx.style.button_active
    else if (ptr_in_bar)
        ctx.style.button_hovered
    else
        ctx.style.button;
    // Fill grows from the bottom up (matches "level meter" convention).
    drawRectFilled(
        ctx,
        .{
            .x = bar.x,
            .y = bar.y + bar.height - fill_h,
            .width = bar.width,
            .height = fill_h,
        },
        Color.toWire(grab_col),
    );

    // Value caption ABOVE the bar.
    var val_buf: [64]u8 = undefined;
    const val_str: []const u8 = formatScalar(&val_buf, T, value.*, opts.fmt);
    const val_size: Vec2 = measureTextS(ctx, val_str);
    const caption_gap_px: f32 = 2; // gap between caption baseline and bar top
    drawTextAtS(
        ctx,
        .{ bar.x + (bar.width - val_size[0]) / 2, bar.y - val_size[1] - caption_gap_px },
        val_str,
        Color.toWire(ctx.style.text),
    );

    // Item state + advance.
    w.layout.last_item_id = id;
    w.layout.last_item_rect = bar;
    w.layout.last_item_hovered = ptr_in_bar;
    markItemPost(ctx, w, changed);
    advanceLayout(
        w,
        .{ bar_w, bar_h },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return changed;
}

fn vSliderDispatch(
    ctx: *UiContext,
    label: []const u8,
    size: Vec2,
    value: anytype,
    opts: SliderOpts,
) bool {
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.vSlider: pass a single-item pointer (e.g., &my_value), got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    return switch (@typeInfo(Child)) {
        .float => vSliderScalar(ctx, label, size, value, Child, opts),
        .int => vSliderScalar(ctx, label, size, value, Child, opts),
        else => @compileError("ui.vSlider: child type must be float or int, got " ++ @typeName(Child)),
    };
}

pub const InputScalarOpts = struct {
    /// std.fmt-compatible format used to render the current value
    /// before the user starts editing. Floats default to 3
    /// decimal places; ints to plain `{d}`.
    fmt: []const u8 = "{d:.3}",
    /// Override the input box width (zero = auto-fit row).
    width: f32 = 0,
};

/// Parse a slice into T. Returns null on parse failure (caller
/// keeps the previous value). Trims surrounding whitespace.
fn parseScalar(comptime T: type, raw: []const u8) ?T {
    const trimmed: []const u8 = std.mem.trim(u8, raw, " \t");
    if (trimmed.len == 0) {
        return null;
    }
    return switch (@typeInfo(T)) {
        .float => std.fmt.parseFloat(T, trimmed) catch null,
        .int => std.fmt.parseInt(T, trimmed, 10) catch null,
        else => null,
    };
}

/// Render an input box at an explicit rect + id. The caller owns
/// layout - the box is drawn, the state machine runs, the value is
/// edited. Caller is responsible for drawing any label and for
/// advancing the layout afterward. Used by both single-input and
/// multi-component-input paths.
fn inputScalarInRect(
    ctx: *UiContext,
    w: *Window,
    id: Id,
    box: Rectangle,
    value_ptr: anytype,
    comptime T: type,
    opts: InputScalarOpts,
) bool {
    const padding: Vec2 = ctx.style.frame_padding;
    const hovered: bool = itemHoverable(ctx, box);
    if (hovered) {
        ctx.hovered_id = id;
    }

    // Click to focus. On focus-gain, seed the edit buffer with the
    // current value formatted via opts.fmt - so the user sees what's
    // there and can edit in place. This block runs BEFORE the
    // `is_focused` capture so a click + chars_typed on the SAME
    // frame both register correctly: focus first, then process the
    // chars using the just-set active_id.
    const click_to_focus: bool = hovered and ctx.input.mouse_left_clicked;
    if (click_to_focus) {
        ctx.active_id = id;
        var seed_buf: [64]u8 = undefined;
        const seeded: []const u8 = formatScalar(&seed_buf, T, value_ptr.*, opts.fmt);
        ctx.scalar_edit_buf = @splat(0);
        @memcpy(ctx.scalar_edit_buf[0..seeded.len], seeded);
        ctx.scalar_edit_len = seeded.len;
        ctx.active_id_just_activated = true;
    }
    const is_focused: bool = ctx.active_id == id;

    // Click outside box deactivates AND triggers commit.
    var commit_now: bool = false;
    const click_outside: bool = ctx.input.mouse_left_clicked and !hovered;
    if (is_focused and click_outside) {
        commit_now = true;
        ctx.active_id = 0;
    }
    // Enter commits. Escape cancels (just clears focus, no write).
    if (is_focused and ctx.input.keys[@backingInt(KeyCode.enter)].pressed_this_frame) {
        commit_now = true;
        ctx.active_id = 0;
    }
    if (is_focused and ctx.input.keys[@backingInt(KeyCode.escape)].pressed_this_frame) {
        ctx.active_id = 0;
        ctx.scalar_edit_len = 0;
    }
    // Backspace.
    if (is_focused and ctxKeyPressedOrRepeat(ctx, .backspace)) {
        if (ctx.scalar_edit_len > 0) {
            ctx.scalar_edit_len -= 1;
            ctx.scalar_edit_buf[ctx.scalar_edit_len] = 0;
        }
    }

    // While focused, route typed characters into the edit buffer.
    var changed: bool = false;
    if (is_focused) {
        var i: usize = 0;
        while (i < ctx.input.chars_typed_count) : (i += 1) {
            const ch: u32 = ctx.input.chars_typed[i];
            // Numeric chars + sign + dot only (rough filter - full
            // parse happens at commit).
            const is_digit: bool = ch >= '0' and ch <= '9';
            const is_punct: bool = ch == '.' or ch == '-' or ch == '+' or ch == 'e' or ch == 'E';
            const is_acceptable: bool = is_digit or is_punct;
            const has_room: bool = ctx.scalar_edit_len < ctx.scalar_edit_buf.len;
            if (is_acceptable and has_room) {
                ctx.scalar_edit_buf[ctx.scalar_edit_len] = @intCast(ch);
                ctx.scalar_edit_len += 1;
            }
        }
    }

    // On commit, parse the buffer and write to value_ptr if valid.
    if (commit_now) {
        const text_slice: []const u8 = ctx.scalar_edit_buf[0..ctx.scalar_edit_len];
        const parsed: ?T = parseScalar(T, text_slice);
        if (parsed) |p| {
            if (p != value_ptr.*) {
                value_ptr.* = p;
                changed = true;
            }
        }
        ctx.scalar_edit_len = 0;
    }

    // Render frame.
    const bg_col: Color = if (is_focused)
        ctx.style.frame_bg_active
    else if (hovered)
        ctx.style.frame_bg_hovered
    else
        ctx.style.frame_bg;
    drawRectFilled(ctx, box, Color.toWire(bg_col));
    drawRect(ctx, box, Color.toWire(ctx.style.border));

    // Render the visible text - buffer when focused, current value
    // when not.
    var disp_buf: [64]u8 = undefined;
    const display_text: []const u8 = if (is_focused)
        ctx.scalar_edit_buf[0..ctx.scalar_edit_len]
    else
        formatScalar(&disp_buf, T, value_ptr.*, opts.fmt);
    drawTextAtS(
        ctx,
        .{ box.x + padding[0], box.y + padding[1] },
        display_text,
        Color.toWire(ctx.style.text),
    );

    w.layout.last_item_id = id;
    w.layout.last_item_rect = box;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, changed);
    return changed;
}

fn inputScalarImpl(
    ctx: *UiContext,
    label: []const u8,
    value_ptr: anytype,
    comptime T: type,
    opts: InputScalarOpts,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, label);

    const padding: Vec2 = ctx.style.frame_padding;
    const text_size: Vec2 = measureTextS(ctx, label);
    const box_h: f32 = ctx.style.font_size + 2 * padding[1];
    const inner_right: f32 = w.pos[0] + w.size[0] - ctx.style.window_padding[0];
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const reserve_label: f32 = text_size[0] + ctx.style.item_spacing[0];
    const default_box_w: f32 = @max(60, inner_right - at[0] - reserve_label);
    const box_w: f32 = effectiveItemWidth(ctx, opts.width, default_box_w);
    const box: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = box_w,
        .height = box_h,
    };

    const changed: bool = inputScalarInRect(ctx, w, id, box, value_ptr, T, opts);

    // Label after the box.
    if (label.len > 0) {
        drawTextAtS(
            ctx,
            .{ box.x + box.width + ctx.style.item_spacing[0], box.y + padding[1] },
            label,
            Color.toWire(ctx.style.text),
        );
    }

    advanceLayout(
        w,
        .{ box_w + reserve_label, box_h },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return changed;
}

fn inputDispatch(
    ctx: *UiContext,
    label: []const u8,
    value: anytype,
    opts: InputScalarOpts,
) bool {
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.input: pass a single-item pointer (e.g., &my_value), got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    return switch (@typeInfo(Child)) {
        .float => inputScalarImpl(ctx, label, value, Child, opts),
        .int => inputScalarImpl(ctx, label, value, Child, opts),
        .array => |arr| blk: {
            switch (@typeInfo(arr.child)) {
                .float, .int => {},
                else => @compileError("ui.input: array element must be float or int, got " ++ @typeName(arr.child)),
            }
            break :blk inputArray(ctx, label, value, arr.child, arr.len, opts);
        },
        else => @compileError("ui.input: child type must be float, int, or [N]float/int, got " ++ @typeName(Child)),
    };
}

fn colorButtonImpl(
    ctx: *UiContext,
    desc_id: []const u8,
    rgba: [4]f32,
    size: Vec2,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, desc_id);

    const default_size: f32 = ctx.style.font_size + 2 * ctx.style.frame_padding[1];
    const sw_w: f32 = if (size[0] > 0) size[0] else default_size;
    const sw_h: f32 = if (size[1] > 0) size[1] else default_size;
    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const swatch: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = sw_w,
        .height = sw_h,
    };

    const hovered: bool = itemHoverable(ctx, swatch);
    if (hovered) {
        ctx.hovered_id = id;
    }
    const clicked: bool = hovered and ctx.input.mouse_left_clicked;

    // Render swatch + border.
    const swatch_color: Color = .{
        .r = @round(clamp(rgba[0], 0, 1) * 255),
        .g = @round(clamp(rgba[1], 0, 1) * 255),
        .b = @round(clamp(rgba[2], 0, 1) * 255),
        .a = @round(clamp(rgba[3], 0, 1) * 255),
    };
    drawRectFilled(ctx, swatch, Color.toWire(swatch_color));
    drawRect(ctx, swatch, Color.toWire(ctx.style.border));

    // Hover tooltip - RGBA breakdown.
    if (hovered) {
        const ui: Ui = .{ .ctx = ctx };
        ui.setTooltip("R:{d:.2} G:{d:.2} B:{d:.2} A:{d:.2}", .{
            rgba[0], rgba[1], rgba[2], rgba[3],
        });
    }

    w.layout.last_item_id = id;
    w.layout.last_item_rect = swatch;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false);
    advanceLayout(
        w,
        .{ sw_w, sw_h },
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return clicked;
}

fn colorButtonDispatch(
    ctx: *UiContext,
    desc_id: []const u8,
    value: anytype,
    size: Vec2,
) bool {
    const T = @TypeOf(value);
    const ti = @typeInfo(T);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("ui.colorButton: pass a single-item pointer (e.g., &my_color), got " ++ @typeName(T));
    }
    const Child: type = ti.pointer.child;
    var rgba_f: [4]f32 = undefined;
    if (Child == [3]f32) {
        rgba_f = .{ value[0], value[1], value[2], 1.0 };
    } else if (Child == [4]f32) {
        rgba_f = .{ value[0], value[1], value[2], value[3] };
    } else if (Child == Color) {
        rgba_f = .{
            float(value.r) / 255.0,
            float(value.g) / 255.0,
            float(value.b) / 255.0,
            float(value.a) / 255.0,
        };
    } else {
        @compileError("ui.colorButton: child must be [3]f32, [4]f32, or Color, got " ++ @typeName(Child));
    }
    return colorButtonImpl(ctx, desc_id, rgba_f, size);
}

fn imageButtonImpl(
    ctx: *UiContext,
    str_id: []const u8,
    source: anytype,
    size: ?Vec2,
) bool {
    const w: *Window = ctx.current_window orelse return false;
    const id: Id = widgetId(ctx, w, str_id);

    // Resolve texture id + natural size via the same dispatch the
    // existing `image` method uses.
    const T = @TypeOf(source);
    const default_natural_px: f32 = 64; // fallback when the source has no intrinsic size (raw GL id)
    var tex_id: u32 = 0;
    var natural: Vec2 = .{ default_natural_px, default_natural_px };
    var flipped: bool = false;
    switch (@typeInfo(T)) {
        .int, .comptime_int => {
            tex_id = @intCast(source);
        },
        .pointer => |p| switch (p.child) {
            types.Texture => {
                tex_id = source.id;
                natural = .{ @floatFromInt(source.width), @floatFromInt(source.height) };
            },
            RenderTexture => {
                tex_id = source.texture.id;
                natural = .{ @floatFromInt(source.texture.width), @floatFromInt(source.texture.height) };
                flipped = true;
            },
            else => @compileError(
                "ui.imageButton: pointer must target Texture or RenderTexture, got *" ++ @typeName(p.child),
            ),
        },
        .@"struct" => switch (T) {
            types.Texture => {
                tex_id = source.id;
                natural = .{ @floatFromInt(source.width), @floatFromInt(source.height) };
            },
            RenderTexture => {
                tex_id = source.texture.id;
                natural = .{ @floatFromInt(source.texture.width), @floatFromInt(source.texture.height) };
                flipped = true;
            },
            else => @compileError("ui.imageButton: unsupported struct type " ++ @typeName(T)),
        },
        else => @compileError("ui.imageButton: pass u32 GL ID, Texture, or RenderTexture, got " ++ @typeName(T)),
    }

    const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
    const eff_size: Vec2 = size orelse natural;
    const button_rect: Rectangle = .{
        .x = at[0],
        .y = at[1],
        .width = eff_size[0],
        .height = eff_size[1],
    };

    const hovered: bool = itemHoverable(ctx, button_rect);
    if (hovered) {
        ctx.hovered_id = id;
    }
    const clicked: bool = hovered and ctx.input.mouse_left_clicked;

    // Render the texture using the same draw command imageImpl uses.
    // UV flip handled identically: RTs sample bottom-up, regular
    // textures top-down.
    const uv0: Vec2 = if (flipped) .{ 0, 1 } else .{ 0, 0 };
    const uv1: Vec2 = if (flipped) .{ 1, 0 } else .{ 1, 1 };
    drawTexturedQuad(ctx, button_rect, tex_id, uv0, uv1, 0xFFFFFFFF);
    // Hover border.
    if (hovered) {
        drawRect(ctx, button_rect, Color.toWire(ctx.style.button_hovered));
    }

    w.layout.last_item_id = id;
    w.layout.last_item_rect = button_rect;
    w.layout.last_item_hovered = hovered;
    markItemPost(ctx, w, false);
    advanceLayout(
        w,
        eff_size,
        ctx.style.item_spacing,
        ctx.style.window_padding[0],
    );
    return clicked;
}

fn editStructImpl(
    ctx: *UiContext,
    value_ptr: anytype,
    opts: anytype,
) bool {
    const PtrT = @TypeOf(value_ptr);
    const ti = @typeInfo(PtrT);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("editStruct: pass a pointer to a struct, got " ++ @typeName(PtrT));
    }
    const StructT: type = ti.pointer.child;
    const struct_info = @typeInfo(StructT);
    if (struct_info != .@"struct") {
        @compileError("editStruct: child type must be a struct, got " ++ @typeName(StructT));
    }

    var any_changed: bool = false;
    inline for (struct_info.@"struct".field_names, struct_info.@"struct".field_types) |field_name, field_type| {
        // Per-field opts: empty struct if not mentioned.
        const has_opts: bool = comptime @hasField(@TypeOf(opts), field_name);
        const field_opts: @TypeOf(if (has_opts) @field(opts, field_name) else .{}) =
            if (has_opts) @field(opts, field_name) else .{};

        // `.skip = true` excludes the field from the editor.
        const skip: bool = blk: {
            if (comptime @hasField(@TypeOf(field_opts), "skip")) {
                break :blk field_opts.skip;
            }
            break :blk false;
        };
        if (skip) {
            continue;
        }

        // `.label` overrides the displayed label. Falls back to the
        // field's identifier as it appears in the source.
        const label: []const u8 = blk: {
            if (comptime @hasField(@TypeOf(field_opts), "label")) {
                break :blk field_opts.label;
            }
            break :blk field_name;
        };

        const field_ptr: @TypeOf(&@field(value_ptr.*, field_name)) = &@field(value_ptr.*, field_name);
        if (editFieldDispatch(ctx, label, field_type, field_ptr, field_opts)) {
            any_changed = true;
        }
    }
    return any_changed;
}

fn editArrayListImplOpts(
    ctx: *UiContext,
    label: []const u8,
    list_ptr: anytype,
    opts: anytype,
) bool {
    const PtrT = @TypeOf(list_ptr);
    const ti = @typeInfo(PtrT);
    if (ti != .pointer or ti.pointer.size != .one) {
        @compileError("editArrayList: pass a pointer to std.ArrayList(T), got " ++ @typeName(PtrT));
    }
    const ListT: type = ti.pointer.child;
    if (!@hasField(ListT, "items")) {
        @compileError("editArrayList: child must be std.ArrayList(T) (no `items` field), got " ++ @typeName(ListT));
    }
    // `list.items` is `[]T`; extract T from it.
    const items_field = @TypeOf(@as(ListT, undefined).items);
    const items_info: std.builtin.Type = @typeInfo(items_field);
    if (items_info != .pointer or items_info.pointer.size != .slice) {
        @compileError("editArrayList: list.items is not a slice (got " ++ @typeName(items_field) ++ ")");
    }
    const T: type = items_info.pointer.child;

    const ui: Ui = .{ .ctx = ctx };
    if (!ui.treeNode(label, .{})) {
        return false;
    }
    defer ui.treePop();

    var any_changed: bool = false;

    // Header row: count + "Add" button.
    ui.text("count: {d}", .{list_ptr.items.len});
    ui.sameLine(.{});
    const add_clicked: bool = ui.button("+ Add", .{});
    if (add_clicked) {
        const default_item: T = std.mem.zeroes(T);
        list_ptr.append(ctx.gpa, default_item) catch assertUnreachable(@src(), "OOM", .{});
        any_changed = true;
    }

    // Per-element rows. Defer remove to after the loop so we don't
    // mutate the slice we're iterating.
    var to_remove: ?usize = null;
    var i: usize = 0;
    while (i < list_ptr.items.len) : (i += 1) {
        // Scope IDs by index so per-element widgets get unique IDs.
        ui.pushIdInt(@intCast(i));
        defer ui.popId();

        var row_label_buf: [16]u8 = undefined;
        const row_label: []const u8 = bufPrint(&row_label_buf, "[{d}]", .{i}) catch row_label_buf[0..0];

        // Element editor - uses same dispatch as editStruct. Pass
        // `opts` through so struct elements can have per-field
        // constraints applied uniformly to every row.
        const elem_changed: bool = editFieldDispatch(ctx, row_label, T, &list_ptr.items[i], opts);
        if (elem_changed) {
            any_changed = true;
        }

        // Per-row "Remove" button on the same line as the editor's
        // last item. Note: for nested structs (which open a tree
        // node), the X button appears on the row where the tree
        // node header was - not perfect but acceptable for v1.
        ui.sameLine(.{});
        const remove_clicked: bool = ui.button("x", .{});
        if (remove_clicked) {
            to_remove = i;
        }
    }

    if (to_remove) |r| {
        _ = list_ptr.orderedRemove(r);
        any_changed = true;
    }

    return any_changed;
}

fn editArrayListImpl(
    ctx: *UiContext,
    label: []const u8,
    list_ptr: anytype,
) bool {
    return editArrayListImplOpts(ctx, label, list_ptr, .{});
}

fn showLayoutTab(self: Ui, state: *DemoState) void {
    self.text("Same-line layout", .{});
    _ = self.button("A", .{});
    self.sameLine(.{});
    _ = self.button("B", .{});
    self.sameLine(.{});
    _ = self.button("C", .{});

    if (state.layout_show_separator) {
        self.separator();
    }
    _ = self.checkbox("Show separators", &state.layout_show_separator);

    self.text("Indent / unindent", .{});
    _ = self.checkbox("Outer", &state.layout_indent_a);
    self.indent();
    _ = self.checkbox("Inner", &state.layout_indent_b);
    self.unindent();

    self.separator();
    self.text("Tree node demo", .{});
    if (self.treeNode("Click to expand", .{})) {
        defer self.treePop();
        self.text("This is inside the tree.", .{});
        if (self.treeNode("Deeper", .{})) {
            defer self.treePop();
            self.text("And this is even deeper.", .{});
        }
    }

    self.separator();
    self.text("Group + child", .{});
    self.beginGroup();
    self.text("In a group", .{});
    _ = self.button("Group btn", .{});
    self.endGroup();
}

fn showAboutTab(self: Ui) void {
    self.text("zimr - pure-Zig raylib + ImGui port", .{});
    self.text("Targets wasm32-wasi + WebGL2 and native.", .{});
    self.separator();
    self.text("Documentation: see /src/notes/architecture.md", .{});
    self.text("Cheatsheet: zimr-cheatsheet.html", .{});
    self.separator();
    self.text("This window itself is rendered via the same widgets", .{});
    self.text("you see in the Widgets tab - it's a self-portrait.", .{});
}

fn showDemoWindowImpl(
    self: Ui,
    state: *DemoState,
    p_open: ?*bool,
) void {
    if (p_open) |op| {
        if (!op.*) {
            return;
        }
    }

    self.setNextWindowSize(.{ 540, 480 }, .{ .once = true });
    if (self.window("Dear ZIMR - demo", .{})) |w| {
        defer w.close();

        self.text("zimr {s} - every widget the port supports.", .{"6.0"});
        self.text("Press Tab / Shift+Tab to move keyboard focus.", .{});
        self.separator();

        if (self.beginTabBar("##demo_tabs", .{})) {
            defer self.endTabBar();
            if (self.beginTabItem("Widgets", null, .{})) {
                defer self.endTabItem();
                showWidgetsTab(self, state);
            }
            if (self.beginTabItem("Layout", null, .{})) {
                defer self.endTabItem();
                showLayoutTab(self, state);
            }
            if (self.beginTabItem("Style", null, .{})) {
                defer self.endTabItem();
                _ = self.styleEditor();
            }
            if (self.beginTabItem("About", null, .{})) {
                defer self.endTabItem();
                showAboutTab(self);
            }
        }
    }
}

/// Open a tooltip block. Lazily allocates the tooltip window on
/// first call, then reuses it across frames. Routes subsequent
/// widget submission into the tooltip's draw list by swapping
/// `ctx.current_window` and `ctx.current_draw_list`.
fn beginTooltipImpl(ctx: *UiContext) void {
    // Lazy alloc on first ever begin - outlives the call by sitting
    // on the ctx, freed in UiContext.deinit.
    if (ctx.tooltip_window == null) {
        const tw: *Window = ctx.gpa.create(Window) catch return;
        tw.* = .{
            .id = 0xFFFFFFFE, // reserved id for the tooltip window
            .pos = .{ 0, 0 },
            .size = .{ 0, 0 },
        };
        ctx.tooltip_window = tw;
    }
    const tw: *Window = ctx.tooltip_window.?;

    // Position at mouse + (16, 16) offset. Size is set at
    // endTooltip from accumulated cursor_max. Background drawn
    // there too.
    const padding: Vec2 = ctx.style.frame_padding;
    tw.pos = .{ ctx.input.mouse_pos[0] + 16, ctx.input.mouse_pos[1] + 16 };
    tw.size = .{ 9999, 9999 }; // huge - widgets won't wrap
    // Reset per-frame layout state; the tooltip is a fresh
    // submission every frame. The draw list arena was just reset
    // in endFrame, so `cmds =.empty` is the right cleanup.
    tw.draw_list.clear();
    tw.layout.cursor_pos = .{ tw.pos[0] + padding[0], tw.pos[1] + padding[1] };
    tw.layout.cursor_max = tw.layout.cursor_pos;
    tw.layout.line_height = 0;

    // Save the current window context so endTooltip can pop. We
    // stash them on the tooltip window itself for the duration of
    // the block - no separate stack needed since nested tooltips
    // aren't supported.
    tw.saved_window_ptr = ctx.current_window;
    tw.saved_draw_list = ctx.current_draw_list;

    ctx.current_window = tw;
    ctx.current_draw_list = &tw.draw_list;
    ctx.tooltip_active_this_frame = true;
}

/// Close the tooltip block. Sizes the tooltip rect to fit the
/// submitted content; the actual frame background is drawn at
/// endFrame in renderTooltipBlock.
fn endTooltipImpl(ctx: *UiContext) void {
    if (!ctx.tooltip_active_this_frame) {
        return;
    }
    const tw: *Window = ctx.tooltip_window orelse return;
    const padding: Vec2 = ctx.style.frame_padding;
    tw.size = .{
        (tw.layout.cursor_max[0] - tw.pos[0]) + padding[0],
        (tw.layout.cursor_max[1] - tw.pos[1]) + padding[1],
    };
    // Floor - degenerate-content case (no widgets between begin/end)
    // still gets a visible box so users notice the call.
    if (tw.size[0] < 8) {
        tw.size[0] = 8;
    }
    if (tw.size[1] < 8) {
        tw.size[1] = 8;
    }

    ctx.current_window = tw.saved_window_ptr;
    ctx.current_draw_list = tw.saved_draw_list;
}

/// Virtualized iterator for long item lists. Submitted from
/// inside an active window scope; reserves the FULL content
/// height up-front via `dummy`-style cursor advancement so the
/// scrollbar reflects the total range, then on `step()` returns
/// only the row range intersecting the visible area.
/// The single-step model: `step()` returns one Range covering
/// every visible row, then null. ImGui's clipper supports
/// multi-step for variable item heights (a feature we don't yet
/// support - A2 covers known-height lists, which is ~90% of real
/// uses including log viewers, scoreboards, file lists).
pub const Clipper = struct {
    ctx: *UiContext,
    item_count: usize,
    item_height: f32,
    /// Y position where row 0 would have been placed without the
    /// clipper, in screen coordinates. Captured at init from
    /// the resolved cursor position.
    origin_y: f32,
    /// Top edge of the visible viewport in screen coords.
    viewport_top: f32,
    /// Bottom edge of the visible viewport in screen coords.
    viewport_bot: f32,
    /// Inclusive start row index of the visible range, computed
    /// at init. Same as Range.start returned by the first step.
    visible_start: usize,
    /// Exclusive end row index of the visible range.
    visible_end: usize,
    /// State machine for `step()`:
    ///   .not_started → return visible range, advance to.stepped
    ///   .stepped → end-of-iteration cleanup, advance to.done, return null
    ///   .done → return null
    state: State = .not_started,

    pub const Range = struct {
        start: usize,
        end: usize, // exclusive
    };

    const State = enum { not_started, stepped, done };

    fn init(
        ctx: *UiContext,
        item_count: usize,
        item_height: f32,
    ) Clipper {
        const h: f32 = if (item_height > 0) item_height else 1;
        const w_opt: ?*Window = ctx.current_window;
        if (w_opt == null or item_count == 0) {
            return .{
                .ctx = ctx,
                .item_count = 0,
                .item_height = h,
                .origin_y = 0,
                .viewport_top = 0,
                .viewport_bot = 0,
                .visible_start = 0,
                .visible_end = 0,
                .state = .done,
            };
        }
        const w: *Window = w_opt.?;

        // The cursor is currently where row 0 would be placed.
        // Resolve any pending sameLine so we see the actual y.
        const at: Vec2 = resolveCursor(w, ctx.style.item_spacing[0]);
        const origin_y: f32 = at[1];

        // Visible viewport in screen coords - the vertical bounds
        // of the CURRENT scope's content area. After's
        // child-as-Window refactor, `current_window` is the child
        // window itself when inside `beginChild` (with its own
        // `pos` / `size` / `layout`), so the viewport math is the
        // same regardless of nesting:
        //   vtop = top of content area = layout.origin.y
        //   vbot = bottom of content area = layout.work_rect_max.y
        // These were set correctly at `openWindow` (for top-level)
        // and `beginChildImpl` (for children). No more
        // `child_stack` peek needed - `layout` already encodes the
        // tighter bound when we're inside a child.
        const vtop: f32 = w.layout.origin[1];
        const vbot: f32 = w.layout.work_rect_max[1];

        // Compute first/last visible row indices.
        const visible_height: f32 = @max(0, vbot - vtop);
        const first_visible_f: f32 = @max(0, (vtop - origin_y) / h);
        var first_visible: usize = @floor(first_visible_f);
        const visible_rows_f: f32 = @ceil(visible_height / h) + 1; // +1 for partial rows at top + bottom
        var visible_rows: usize = @trunc(visible_rows_f);
        // Add 1 extra row of overscan top + bottom so a row that's
        // 1 pixel above the viewport still renders (avoids a
        // flicker at boundaries).
        if (first_visible > 0) {
            first_visible -= 1;
            visible_rows += 1;
        }
        visible_rows += 1;

        var last_visible: usize = first_visible + visible_rows;
        if (last_visible > item_count) {
            last_visible = item_count;
        }
        if (first_visible > item_count) {
            first_visible = item_count;
        }

        return .{
            .ctx = ctx,
            .item_count = item_count,
            .item_height = h,
            .origin_y = origin_y,
            .viewport_top = vtop,
            .viewport_bot = vbot,
            .visible_start = first_visible,
            .visible_end = last_visible,
            .state = .not_started,
        };
    }

    /// Returns the row range to render this step, or null when
    /// done. Caller-side pattern:
    ///     while (clip.step()) |r| {... render rows r.start..r.end... }
    /// On the first call (state ==.not_started):
    ///   - If no rows are visible, advance cursor past the entire
    ///     content height and return null.
    ///   - Otherwise advance cursor to the visible-start row's
    ///     position and return the visible range.
    /// On the second call (state ==.stepped):
    ///   - Advance cursor past the remaining content (rows after
    ///     visible_end through item_count). Return null.
    pub fn step(self: *Clipper) ?Range {
        const w: *Window = self.ctx.current_window orelse {
            self.state = .done;
            return null;
        };
        switch (self.state) {
            .not_started => {
                if (self.visible_start >= self.visible_end) {
                    // Nothing visible - advance to total content height and finish.
                    const total_h: f32 = self.item_height * float(self.item_count);
                    w.layout.cursor_pos[1] += total_h;
                    if (w.layout.cursor_pos[1] > w.layout.cursor_max[1]) {
                        w.layout.cursor_max[1] = w.layout.cursor_pos[1];
                    }
                    self.state = .done;
                    return null;
                }
                // Advance cursor down to where the first visible row should sit.
                const skip_pixels: f32 = self.item_height * float(self.visible_start);
                w.layout.cursor_pos[1] += skip_pixels;
                self.state = .stepped;
                return Range{ .start = self.visible_start, .end = self.visible_end };
            },
            .stepped => {
                // Caller has just submitted rows visible_start..visible_end.
                // The window's cursor is now at visible_end's bottom edge.
                // Advance past the remaining rows so the window's
                // total content extent reflects all `item_count` rows.
                const remaining: usize = self.item_count - self.visible_end;
                const remaining_h: f32 = self.item_height * float(remaining);
                w.layout.cursor_pos[1] += remaining_h;
                if (w.layout.cursor_pos[1] > w.layout.cursor_max[1]) {
                    w.layout.cursor_max[1] = w.layout.cursor_pos[1];
                }
                self.state = .done;
                return null;
            },
            .done => return null,
        }
    }

    /// Manual termination, in case the caller breaks out of the
    /// step loop early. Equivalent to draining `step()` until it
    /// returns null. Safe to call multiple times. ImGui: `End()`.
    pub fn end(self: *Clipper) void {
        while (self.step()) |_| {}
    }
};

pub const Ui = struct {
    ctx: *UiContext,

    // ---- Window scope
    /// Open a window scope. Returns a handle if the window is
    /// "alive" this frame (visible + uncollapsed). Caller pattern:
    ///     if (f.ui.window("Stats",.{})) |w| {
    ///         defer w.close();
    ///         f.ui.text("FPS: {d}",.{f.clock.fps()});
    ///     }
    /// Every window is uncollapsed and at a default position; the
    /// optional return type carries the API shape for collapse /
    /// dismiss / hide flags.
    pub fn window(
        self: Ui,
        title: []const u8,
        opts: WindowOpts,
    ) ?WindowHandle {
        return openWindow(self.ctx, title, opts);
    }

    /// Begin a child window scope inside the current window. Widgets
    /// submitted between `beginChild` / `endChild` are clipped to the
    /// child's bounds via the draw list's `push_clip` command, run
    /// their own layout from the child's top-left, and have their IDs
    /// hashed under `str_id` (so identical labels in different
    /// children don't collide).
    ///     if (f.ui.beginChild("log",.{ 0, 120 },.{.border = true })) {
    ///         defer f.ui.endChild();
    ///         for (lines) |line| f.ui.text("{s}",.{line});
    ///     }
    /// Layout: the child consumes its OUTER size from the parent's
    /// cursor - subsequent parent widgets sit below it. Width 0
    /// auto-fills to the parent's content right edge; height 0
    /// defaults to a comfortable 100px (caller can pass an explicit
    /// height for log windows / lists / preview panes).
    /// **Why this matters architecturally** - child windows are the
    /// foundation for tables (each scrollable area is a child) and
    /// for log/list views. Getting clipping right here proves the
    /// deferred-draw-list scissor pipeline works correctly in
    /// nested cases.
    pub fn beginChild(
        self: Ui,
        str_id: []const u8,
        size: Vec2,
        flags: ChildFlags,
    ) bool {
        return beginChildImpl(self.ctx, str_id, size, flags);
    }

    /// End the current child scope. Restores the parent's layout
    /// cursor and pops the clip rect from the draw list. Symmetric
    /// with `beginChild` - call EXACTLY once per `beginChild` that
    /// returned true. The `defer f.ui.endChild()` pattern is the
    /// right way to spell that.
    pub fn endChild(self: Ui) void {
        endChildImpl(self.ctx);
    }

    // ---- Docking
    /// Submit a dockspace within the current scope. Reserves
    /// `size` worth of layout space, looks up (or creates) the
    /// root `DockNode` for `str_id`, returns its `Id`. The
    /// returned id is stable across frames and can be passed to
    /// `dockBuilderDockWindow` / `dockBuilderSplitNode` to define
    /// the default layout.
    /// `size`: outer dimensions of the dockspace. Pass
    /// `Ui.contentRegionAvail()` to fill the remaining space of
    /// the containing window - typical pattern for "the whole
    /// window IS a dockspace."
    /// `opts.flags`: not yet used; reserved for future
    /// `passthru_central_node`, `no_split`, `no_resize` etc.
    /// matching imgui's `ImGuiDockNodeFlags_*`.
    /// What renders today (5.5b): a single empty container outline
    /// where docked windows WILL appear. 5.5c wires
    /// `Window.dock_node_id` so the actual docked-window rendering
    /// happens. 5.5d/e add splitters and drag-targets.
    /// Returns 0 if no `current_window` is set (must be called
    /// inside a `window()` scope).
    pub fn dockSpace(
        self: Ui,
        str_id: []const u8,
        size: Vec2,
        opts: DockSpaceOpts,
    ) Id {
        if (self.ctx.current_window) |hw| {
            hw.hosts_dockspace = true;
        }
        return dockSpaceImpl(self.ctx, str_id, size, opts);
    }

    // ---- Docking builder API
    // Programmatic layout construction. Used by demos to set up a
    // default arrangement at startup. Once the user has interacted
    // with the layout (drag-dock, resize, etc.) the builder calls
    // become no-ops in practice - `dockBuilderDockWindow` only
    // applies to a window that doesn't yet have a `dock_node_id`,
    // so calling it on an already-docked window is a no-op. Demos
    // typically gate the builder block behind a "first frame"
    // check to avoid stomping on user interaction.
    // The standard pattern (in a demo's update fn):
    //     const root = u.dockSpace("MainDockSpace", size,.{});
    //     if (state.first_frame) {
    //         const a_b = u.dockBuilderSplitNode(root,.left, 0.25);
    //         u.dockBuilderDockWindow("Tools", a_b.a);
    //         u.dockBuilderDockWindow("Viewport", a_b.b);
    //         u.dockBuilderFinish(root);
    //         state.first_frame = false;
    //     }

    /// Split `node_id` along `dir` with the given `ratio`. Returns
    /// the two new child node ids. Existing window list (if any)
    /// is preserved on the side OPPOSITE `dir` - e.g. splitting
    /// `.left` with windows already docked puts the existing
    /// content on the right (b), with a fresh empty leaf on the
    /// left (a) waiting for new windows.
    /// Returns `.{.a = 0,.b = 0 }` on error (invalid node id,
    /// target is already a split, etc). Callers can detect by
    /// checking whether `a` is zero.
    pub fn dockBuilderSplitNode(
        self: Ui,
        node_id: Id,
        dir: Dir,
        ratio: f32,
    ) SplitResult {
        const result: SplitResult = splitNode(
            &self.ctx.dock,
            self.ctx.gpa,
            node_id,
            dir,
            ratio,
        ) catch {
            return .{ .a = 0, .b = 0 };
        };
        return .{ .a = result.a, .b = result.b };
    }

    /// Dock the window named `window_name` into the leaf node
    /// `node_id`. Creates the window if it doesn't exist yet
    /// (with default opts; the demo's subsequent `u.window(name,...)`
    /// call will pick up the same window via name lookup).
    /// No-op when the window is already docked into `node_id`
    /// (idempotent - safe to call from inside the demo's
    /// per-frame builder block without gating). When the window
    /// is docked elsewhere, it's first undocked then re-docked.
    pub fn dockBuilderDockWindow(
        self: Ui,
        window_name: []const u8,
        node_id: Id,
    ) void {
        const ctx: *UiContext = self.ctx;
        const target: *DockNode = ctx.dock.lookup(node_id) orelse return;
        if (!target.isLeaf()) {
            return;
        }

        // Find or create the persistent Window via the standard
        // name-hash path. Pass minimal opts - pos/size will be
        // overridden by the leaf rect each frame anyway.
        const w: *Window = findOrCreateWindow(ctx, window_name, .{});

        // Idempotent fast path.
        if (w.dock_node_id == node_id) {
            return;
        }

        // If docked elsewhere, undock first to keep the dock
        // layer's window→leaf inverse correct. `undockWindow`
        // walks the leaves to find the window - we don't need to
        // pass the old leaf id.
        if (w.dock_node_id != null) {
            _ = undockWindow(&ctx.dock, ctx.gpa, w.id);
        }

        // stash pre-dock pos/size on the
        // FIRST docking event, so undocking later restores the
        // window to where the user had it. Subsequent re-docks
        // (e.g. moving from one leaf to another via drag) keep
        // the existing stash - the pre-dock anchor is the spot
        // the user originally chose. Clear only on actual
        // undock-to-floating in `clearDockIdsInSubtree` /
        // `processRequests`'s undock handler.
        if (w.pre_dock_pos == null) {
            w.pre_dock_pos = w.pos;
            w.pre_dock_size = w.size;
        }

        // Wire the window into the new leaf, both directions.
        dockWindowAsTab(&ctx.dock, ctx.gpa, node_id, w.id) catch return;
        w.dock_node_id = node_id;
    }

    /// Remove a dock subtree. Tears down `node_id` and every
    /// node beneath it; the parent (if any) collapses to a leaf
    /// with the surviving sibling's contents. Windows that were
    /// in the removed subtree have their `dock_node_id` cleared
    /// (they fall back to floating).
    /// Used by demos to reset a layout: typically called once,
    /// followed by a fresh sequence of split + dockWindow calls.
    pub fn dockBuilderRemoveNode(self: Ui, node_id: Id) void {
        const ctx: *UiContext = self.ctx;
        // Walk every window and clear `dock_node_id` if its leaf
        // is part of the subtree being removed. Done BEFORE the
        // removal so we can still resolve ancestry; afterward the
        // nodes are gone.
        clearDockIdsInSubtree(ctx, node_id);
        removeNode(&ctx.dock, ctx.gpa, node_id);
    }

    /// Finalize the layout. Currently a no-op marker - our
    /// `layoutSubtree` runs every frame in `dockSpaceImpl` regardless,
    /// so there's nothing to "commit". Reserved for future
    /// optimization where `dockBuilderFinish` would write into a
    /// frozen cache rather than re-walking every frame.
    pub fn dockBuilderFinish(self: Ui, node_id: Id) void {
        _ = self;
        _ = node_id;
    }

    /// set the constraint flags on a dock
    /// node. Mirrors imgui's `DockBuilderGetNode(id)->LocalFlags
    /// =...` pattern, but in a single explicit call. No-op if
    /// the node id is unknown.
    /// Example: lock down a side panel so the user can't dock
    /// other windows over it, split it, or accidentally close
    /// its tabs:
    ///     u.dockBuilderSetNodeFlags(side_id,.{
    ///         .no_split = true,
    ///         .no_docking_over_me = true,
    ///         .no_close_button = true,
    ///     });
    pub fn dockBuilderSetNodeFlags(
        self: Ui,
        node_id: Id,
        flags: DockNodeFlags,
    ) void {
        const node: *DockNode = self.ctx.dock.lookup(node_id) orelse return;
        node.flags = flags;
        node.generation +%= 1;
    }

    /// Read the current flags on a dock node. Returns
    /// default-init (all false) for unknown ids - callers don't
    /// need to handle the null case.
    pub fn dockBuilderGetNodeFlags(
        self: Ui,
        node_id: Id,
    ) DockNodeFlags {
        const node: *DockNode = self.ctx.dock.lookup(node_id) orelse return .{};
        return node.flags;
    }

    /// lock one child of a SPLIT node to a
    /// fixed pixel size along the split axis. The other child
    /// absorbs the dockspace remainder when the host resizes.
    /// This is the "Tools panel stays 200px wide regardless of
    /// window size" UX.
    ///   `parent_id`: the SPLIT node (NOT the child leaf).
    ///   `side`: `.a` = top/left child; `.b` = bottom/right.
    ///   `px`: target pixel size; `null` clears the lock and
    ///         falls back to `ratio`-driven sizing.
    /// Locking both children at once is over-constrained; the
    /// layout falls back to `ratio` in that case (same behavior
    /// as no lock). No-op for leaf nodes or unknown ids.
    /// Splitter drag on a node with an active lock writes the
    /// new pixel size back into `size_ref` (preserving the lock
    /// semantic) instead of mutating `ratio`.
    pub fn dockBuilderSetSizeRef(
        self: Ui,
        parent_id: Id,
        side: enum { a, b },
        px: ?f32,
    ) void {
        const node: *DockNode = self.ctx.dock.lookup(parent_id) orelse return;
        if (node.split == null) {
            return;
        }
        const idx: usize = if (side == .a) 0 else 1;
        node.split.?.size_ref[idx] = px;
        node.generation +%= 1;
    }

    /// mark a node as "central" - the one
    /// that absorbs remaining space when its siblings are locked
    /// at fixed sizes. Pure marker; sets `is_central = true` in
    /// the node's flags. Today the layout doesn't yet special-
    /// case central nodes (the `size_ref` mechanism already
    /// gives the "fixed sibling + free central" UX); the flag
    /// reservation is for 5.5k persistence and future drop-zone
    /// behavior (`NoDockingOverCentralNode` semantics).
    pub fn dockBuilderSetCentralNode(
        self: Ui,
        node_id: Id,
    ) void {
        const node: *DockNode = self.ctx.dock.lookup(node_id) orelse return;
        node.flags.is_central = true;
        node.generation +%= 1;
    }

    // ---- ID stack
    pub fn pushId(self: Ui, str_id: []const u8) void {
        const top: Id = if (self.ctx.id_stack.len > 0)
            self.ctx.id_stack.items[self.ctx.id_stack.len - 1]
        else
            0;
        const id: Id = hashStr(top, str_id);
        self.ctx.id_stack.append(id) catch return;
    }

    pub fn pushIdInt(self: Ui, int_id: i64) void {
        const top: Id = if (self.ctx.id_stack.len > 0)
            self.ctx.id_stack.items[self.ctx.id_stack.len - 1]
        else
            0;
        const id: Id = hashInt(top, int_id);
        self.ctx.id_stack.append(id) catch return;
    }

    pub fn popId(self: Ui) void {
        _ = self.ctx.id_stack.pop();
    }

    pub fn getId(self: Ui, str_id: []const u8) Id {
        const top: Id = if (self.ctx.id_stack.len > 0)
            self.ctx.id_stack.items[self.ctx.id_stack.len - 1]
        else if (self.ctx.current_window) |w|
            w.id
        else
            0;
        return hashStr(top, str_id);
    }

    // ---- Layout --------------------------------------------------- primitives
    /// Place the next widget on the same row as the last. Optional
    /// `offset_x` overrides the default cursor advance.
    /// Place the next widget on the same row as the previous one,
    /// just to its right (separated by `item_spacing[0]`, or at an
    /// explicit X if `opts.offset_x` is non-zero). Matches imgui's
    /// `SameLine` semantics - specifically:
    /// - cursor X = right edge of the previous row's items
    ///   (`cursor_pos_prev_line[0]`) + spacing.
    /// - cursor Y = top of the previous row
    ///   (`cursor_pos_prev_line[1]`).
    /// - `line_height` = `prev_line_height` so the row's max-height
    ///   tracking continues accumulating as the next widget submits.
    /// The new widget submits at the resolved cursor; on its
    /// `advanceLayout`, `cursor_pos_prev_line` and `prev_line_height`
    /// are updated to include it, and the cursor wraps to the next
    /// row past the tallest widget on this row.
    pub fn sameLine(self: Ui, opts: SameLineOpts) void {
        const w: *Window = self.ctx.current_window orelse return;
        const s: *LayoutScope = &w.layout;
        const item_sp_x: f32 = self.ctx.style.item_spacing[0];
        // `opts.offset_x` is a logical content X (imgui's
        // SetCursorPosX semantics: "X from the window's start,
        // not from the visible left edge").  Convert to screen
        // by adding origin and subtracting scroll, matching
        // imgui's `window->Pos.x - window->Scroll.x + x`.
        s.cursor_pos[0] = if (opts.offset_x > 0)
            s.origin[0] - w.scroll_x + opts.offset_x
        else
            s.cursor_pos_prev_line[0] + item_sp_x;
        s.cursor_pos[1] = s.cursor_pos_prev_line[1];
        s.line_height = s.prev_line_height;
    }

    /// Vertical separator. Fills the content width at current cursor.
    pub fn separator(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        const start: Vec2 = self.cursorScreenPos();
        const end_x: f32 = w.pos[0] + w.size[0] - self.ctx.style.window_padding[0];
        drawRectFilled(
            self.ctx,
            .{ .x = start[0], .y = start[1], .width = end_x - start[0], .height = 1 },
            Color.toWire(self.ctx.style.border),
        );
        // Advance one pixel + spacing
        const consumed = Vec2{ end_x - start[0], 1 };
        advanceLayout(w, consumed, self.ctx.style.item_spacing, self.ctx.style.window_padding[0]);
    }

    /// Add empty space on the current line, then start a new line.
    pub fn spacing(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        advanceLayout(
            w,
            .{ 0, self.ctx.style.item_spacing[1] },
            self.ctx.style.item_spacing,
            self.ctx.style.window_padding[0],
        );
    }

    // ---- Widgets
    pub fn button(
        self: Ui,
        label: []const u8,
        opts: ButtonOpts,
    ) bool {
        return buttonImpl(self.ctx, label, opts);
    }

    /// Compact button - zero vertical frame padding, just label-tall.
    /// Useful inline with text for actions like "?" or "[x]" markers,
    /// or in dense toolbars where vertical space matters.
    /// ImGui: `SmallButton(label)`.
    pub fn smallButton(self: Ui, label: []const u8) bool {
        return smallButtonImpl(self.ctx, label);
    }

    /// Tiny directional button (square, font-sized, with a triangle
    /// glyph inside pointing in `dir`). Used for inline ±1 steppers
    /// next to numeric inputs, or for tab-bar / combo nav glyphs.
    /// `str_id` is the widget's unique label for state tracking; it
    /// is NOT drawn - only the arrow glyph is. ImGui:
    /// `ArrowButton(str_id, dir)`.
    pub fn arrowButton(
        self: Ui,
        str_id: []const u8,
        dir: ArrowDir,
    ) bool {
        return arrowButtonImpl(self.ctx, str_id, dir);
    }

    pub fn text(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        textImpl(self.ctx, fmt, args, self.ctx.style.text);
    }

    /// Like `text`, but with an explicit color. Convenience for
    /// status messages, error highlights, headings.
    pub fn textColored(
        self: Ui,
        color: Color,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        textImpl(self.ctx, fmt, args, color);
    }

    /// Like `text`, but soft-wraps at the right edge of the
    /// available content area. Wraps on word boundaries when
    /// possible, falls back to mid-word splits if a single token is
    /// longer than the line. No allocation: writes into the per-
    /// frame stack buffer.
    pub fn textWrapped(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        textWrappedImpl(self.ctx, fmt, args);
    }

    /// Render `label` on the left + formatted value on the right
    /// of the same row, with a small gap between. Common pattern
    /// for key/value displays ("Health: 100", "Status: ready").
    /// The label is in normal text color; the formatted value uses
    /// it too. For value-emphasis, wrap the args side in your own
    /// `text` / `textColored` calls; this is the imgui-parity
    /// convenience for the common "Label: value" form.
    pub fn labelText(
        self: Ui,
        label: []const u8,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        labelTextImpl(self.ctx, label, fmt, args);
    }

    /// Like `text`, but rendered in the dimmed `style.text_disabled`
    /// color. Use for hints, secondary info, captions - anything
    /// the eye should pass over before the main content.
    pub fn textDisabled(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        textImpl(self.ctx, fmt, args, self.ctx.style.text_disabled);
    }

    // ---- text helpers + Value + invisibleButton
    // Five small additions from imgui's Tier-3 widget set + one tiny gap-fill
    // (setItemTooltip). See `src/notes/imgui-plan.md` step 1.1.

    /// Section-header rule with a centered label. Renders as a short
    /// rule on the left, the `label` in normal text colour, then a long
    /// rule filling to the right edge of the window's work area. If
    /// `label` is empty, degrades to a plain full-width rule at the row's
    /// vertical centre (slightly heavier than `separator` - 2px vs 1px).
    /// ImGui: `SeparatorText(label)`.
    /// Use for top-level panel sections inside a window - like the
    /// "Controls / Log / Status" bands in the log viewer demo.
    pub fn separatorText(self: Ui, label: []const u8) void {
        separatorTextImpl(self.ctx, label);
    }

    /// Click-target rectangle with NO visual. Same hit-testing as
    /// `button` but doesn't draw a frame or label - useful for drag
    /// handles, hidden hit zones, "tap-anywhere-to-dismiss" overlays,
    /// or clickable banners where you draw your own visuals.
    /// Returns true on press (mouse-up while hovered). ImGui:
    /// `InvisibleButton(str_id, size, flags)`.
    /// Size semantics: a zero on either axis means "use a sensible
    /// default" - for X, fill the remaining row width to the right
    /// padding; for Y, the standard widget row height
    /// (`font_size + 2 * frame_padding[1]`). This mirrors imgui's
    /// `0 → -FLT_MIN → fill` convention.
    /// `id_str` disambiguates this hit zone from other invisible
    /// regions in the same window - it's hashed into the widget ID
    /// stack but never rendered.
    pub fn invisibleButton(
        self: Ui,
        id_str: []const u8,
        size: Vec2,
    ) bool {
        return invisibleButtonImpl(self.ctx, id_str, size);
    }

    /// Click-styled text. Renders `label` in `style.text_link` with a
    /// 1px underline below, switches to `style.text_link_hovered` and
    /// shows the pointing-hand cursor while hovered, and returns true
    /// on press. Use for in-text links that trigger an in-app action
    /// (open a panel, focus a widget, etc.) - for "open this URL"
    /// links, use `textLinkOpenURL` instead. ImGui: `TextLink(label)`.
    pub fn textLink(self: Ui, label: []const u8) bool {
        return textLinkImpl(self.ctx, label);
    }

    /// Click-styled text that opens `url` in a new browser tab on
    /// press. Hovering shows a tooltip with the destination URL so the
    /// user always sees where the link goes before clicking. Right-
    /// click pops a "Copy link" context menu (currently desktop-only
    /// phone support arrives with step 2.2's long-press bridge).
    /// Returns true on press for the rare caller that wants to react
    /// in-app to the click in addition to opening the URL.
    /// ImGui: `TextLinkOpenURL(label, url)`.
    /// Implementation is a composer over public methods - `textLink`
    /// for click semantics, `setItemTooltip` for the URL preview,
    /// `beginPopupContextItem` + `menuItem` for the right-click menu.
    /// Browsers may block the `window.open` call if it doesn't fire
    /// inside a user-gesture handler (the `runtime.core.openURL` path
    /// goes through the JS bridge from `web.zig`); a click on this
    /// widget IS a user gesture so the normal path works.
    pub fn textLinkOpenURL(
        self: Ui,
        label: []const u8,
        url: []const u8,
    ) bool {
        const pressed: bool = textLinkImpl(self.ctx, label);
        if (pressed) {
            runtime.core.openURL(url);
        }
        // Tooltip on hover. Always show the URL - even when the label
        // happens to equal the URL, repetition is friendlier than
        // confusion ("did I click the right one?").
        self.setItemTooltip("Open in browser:\n{s}", .{url});
        // Right-click → Copy link. Auto-opens on right-click hover via
        // `beginPopupContextItem`; on phone this never fires today since
        // touch only emits left-click events. lands the long-
        // press → right-click bridge that makes this reachable on phone.
        if (self.beginPopupContextItem(null)) {
            defer self.endPopup();
            if (self.menuItem("Copy link", .{})) {
                self.setClipboardText(url);
            }
        }
        return pressed;
    }

    /// Show a tooltip on hover, automatically gated to "only if the
    /// last-submitted item is hovered this frame." Saves the two-line
    /// `if (isItemHovered()) setTooltip(...)` boilerplate at the call
    /// site - and that boilerplate is the typical pattern, so most
    /// tooltips should use this. ImGui: `SetItemTooltip(fmt,...)`.
    /// Was missing from the zimr surface before now (v2 audit §C23
    /// listed it ❌); filled here because `textLinkOpenURL` needs it.
    pub fn setItemTooltip(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        if (self.isItemHovered(.{})) {
            self.setTooltip(fmt, args);
        }
    }

    /// Render `"label: <formatted-v>"` as a one-line read-only display.
    /// `v` can be any of:
    /// - `bool` → "true" / "false"
    /// - signed/unsigned int → decimal
    /// - float → "{d:.3}" (3 decimal places)
    /// - enum → `@tagName(v)`
    /// - `[]const u8` → the string bytes, passthrough
    /// - anything else → `{any}` fallback (ugly but readable)
    /// ImGui ships four overloads (`Value(prefix, bool)`,
    /// `Value(prefix, int)`, `Value(prefix, unsigned)`,
    /// `Value(prefix, float, format)`) because C++ doesn't have
    /// comptime dispatch. Zig does, so one signature covers all four
    /// imgui overloads plus enums and strings - net more capability,
    /// fewer functions. For a custom format (e.g. `"{d:.5}"`), reach
    /// for `Ui.text("{s}: {d:.5}",.{label, v})` directly; that's the
    /// same character count and zero new API.
    pub fn value(
        self: Ui,
        label: []const u8,
        v: anytype,
    ) void {
        valueImpl(self.ctx, label, v);
    }

    /// Toggleable boolean widget. Returns true if `*value` changed
    /// this frame (clicked while hovered). The function ALSO updates
    /// `*value` in place - caller can ignore the bool and just read
    /// `*value` after the call.
    pub fn checkbox(
        self: Ui,
        label: []const u8,
        v: *bool,
    ) bool {
        return checkboxImpl(self.ctx, label, v);
    }

    /// Drag-to-edit slider. Generic over numeric pointer types:
    /// `*f32`, `*f64`, `*i32`, `*u32`, `*i64`, `*u64`, etc. Returns
    /// true if the value changed this frame.
    ///     var f: f32 = 0.5;
    ///     _ = ui.slider("opacity", &f,.{.min = 0,.max = 1 });
    /// Comptime dispatch picks the right inner implementation
    /// float vs int - based on the pointed-to type.
    pub fn slider(
        self: Ui,
        label: []const u8,
        v: anytype,
        opts: SliderOpts,
    ) bool {
        return sliderDispatch(self.ctx, label, v, opts);
    }

    /// Inline RGB or RGBA editor. Generic over `*[3]f32`, `*[4]f32`,
    /// or `*Color` (zimr's u8 RGBA). Renders three or four slim
    /// sliders side-by-side plus a small swatch.
    pub fn colorEdit(
        self: Ui,
        label: []const u8,
        v: anytype,
        opts: ColorEditOpts,
    ) bool {
        return colorEditDispatch(self.ctx, label, v, opts);
    }

    /// Sparkline-style line plot. Takes a slice of `f32` samples;
    /// draws a connected line strip scaled to fit a row-height
    /// rectangle. Optional overlay text appears centered in the
    /// plot rect (imgui-style "current value" caption). When
    /// hovered, shows the value at the hovered index as a tooltip.
    /// Pattern (typical: a 60-frame FPS history):
    ///     _ = ui.plotLines("fps", &state.fps_hist,.{
    ///         .overlay = "60.0 fps",
    ///         .min = 0,
    ///         .max = 120,
    ///     });
    /// Pass `min == max` to auto-scale to the data's observed range.
    /// `height` is the plot rect's height; `0` means use a sensible
    /// default of 80px.
    pub fn plotLines(
        self: Ui,
        label: []const u8,
        values: []const f32,
        opts: PlotOpts,
    ) void {
        plotImpl(self.ctx, label, values, opts, .lines);
    }

    /// Bar-chart sparkline. Same API as `plotLines` but renders
    /// each sample as a filled column instead of connected lines.
    /// Suited to discrete-count data (histogram bins, per-second
    /// event counts, etc).
    pub fn plotHistogram(
        self: Ui,
        label: []const u8,
        values: []const f32,
        opts: PlotOpts,
    ) void {
        plotImpl(self.ctx, label, values, opts, .histogram);
    }

    /// Block-style color picker. Generic over `*[3]f32` (RGB),
    /// `*[4]f32` (RGBA), or `*Color` (zimr's u8 RGBA). Renders
    /// either a bar layout (hue gradient + SV box) or a wheel
    /// layout (hue ring + SV box inside) selectable via
    /// `opts.layout`. Returns true on any frame where the
    /// color changed.
    ///     var rgba: [4]f32 =.{ 0.2, 0.6, 0.9, 1.0 };
    ///     _ = ui.colorPicker("Tint", &rgba,.{
    ///         .layout =.wheel,
    ///         .alpha = true,
    ///     });
    pub fn colorPicker(
        self: Ui,
        label: []const u8,
        v: anytype,
        opts: ColorPickerOpts,
    ) bool {
        return colorPickerDispatch(self.ctx, label, v, opts);
    }

    /// Drop the cursor down by one row's worth - useful between two
    /// `sameLine`-prefixed widgets when you want to break the row
    /// without inserting a separator.
    pub fn newLine(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        const consumed: Vec2 = .{ 0, self.ctx.style.font_size };
        advanceLayout(w, consumed, self.ctx.style.item_spacing, self.ctx.style.window_padding[0]);
    }

    /// Drag-to-edit numeric widget. Like `slider` but unbounded
    /// each pixel of mouse drag changes the value by `opts.speed`,
    /// hard-clamped only if `opts.min`/`opts.max` are set. Common
    /// uses: world coordinates, infinite-range tunables.
    ///     var speed: f32 = 5.0;
    ///     _ = ui.drag("Speed", &speed,.{.speed = 0.1 });
    pub fn drag(
        self: Ui,
        label: []const u8,
        v: anytype,
        opts: DragOpts,
    ) bool {
        return dragDispatch(self.ctx, label, v, opts);
    }

    /// Mutually-exclusive selection: a small circle + label. Returns
    /// true if `*current` changed. Pattern (matches ImGui's
    /// per-button overload):
    ///     _ = ui.radioButton("Easy", &state.diff, 0);
    ///     _ = ui.radioButton("Hard", &state.diff, 1);
    pub fn radioButton(
        self: Ui,
        label: []const u8,
        current: *i32,
        v: i32,
    ) bool {
        return radioButtonImpl(self.ctx, label, current, v);
    }

    /// List-item-style clickable text. Returns true on the click
    /// frame. When `selected` is true the row paints with the
    /// active highlight. Foundation for menu items, file pickers,
    /// list selectors.
    pub fn selectable(
        self: Ui,
        label: []const u8,
        selected: bool,
        opts: SelectableOpts,
    ) bool {
        return selectableImpl(self.ctx, label, selected, opts);
    }

    /// Draggable splitter bar between two adjacent panes. Returns
    /// `true` while the user is dragging (held).
    /// `split_pos` is the size of the FIRST pane (left for `.x`,
    /// top for `.y`). The widget mutates it on drag, clamped by
    /// `opts.min1` and `opts.min2` (against `total - min2 -
    /// bar_width`).
    /// Canonical usage with `beginChild`:
    ///     const total_w = u.getContentRegionAvail()[0];
    ///     const total_h = u.getContentRegionAvail()[1];
    ///     const right_w = total_w - state.left_w - 4;
    ///     if (u.beginChild("L",.{ state.left_w, total_h },.{})) {
    ///         defer u.endChild();
    ///         //... left content
    ///     }
    ///     u.sameLine(.{});
    ///     _ = u.splitter("split", &state.left_w,.x,.{
    ///         .min1 = 80,.min2 = 100,.total_along_axis = total_w,
    ///     });
    ///     u.sameLine(.{});
    ///     if (u.beginChild("R",.{ right_w, total_h },.{})) {
    ///         defer u.endChild();
    ///         //... right content
    ///     }
    pub fn splitter(
        self: Ui,
        str_id: []const u8,
        split_pos: *f32,
        axis: SplitterAxis,
        opts: SplitterOpts,
    ) bool {
        return splitterImpl(self.ctx, str_id, split_pos, axis, opts);
    }

    // ---- MultiSelect API
    // See `src/notes/multiselect-tutorial.md` for the conceptual
    // walkthrough. Canonical caller pattern:
    //     const io = ui.beginMultiSelect(.{.clear_on_escape = true },
    //                                    @intCast(sel.size()), items.len);
    //     try sel.applyRequests(gpa, io); // drain pending
    //     for (items, 0..) |item, n| {
    //         ui.setNextItemSelectionUserData(@intCast(n));
    //         _ = ui.selectable(item.label, sel.contains(n),.{});
    //     }
    //     const io2 = ui.endMultiSelect();
    //     try sel.applyRequests(gpa, io2); // drain emitted

    /// Open a multi-select scope. Returns the IO view with any
    /// pending requests (from this frame's keyboard shortcuts or
    /// previous frame's box-select completion) ready to apply.
    /// `selection_size` and `items_count` are informational
    /// passed back via `io.items_count` for `applyRequests` to
    /// scope SetAll over. Pass `items_count = items.len` and
    /// `selection_size = sel.size()` from your storage.
    /// returns IO with empty requests + null anchor /
    /// nav_id. Real Begin-time logic (apply keyboard shortcuts,
    /// detect scope focus) lands.
    pub fn beginMultiSelect(
        self: Ui,
        flags: MultiSelectFlags,
        selection_size: u32,
        items_count: u32,
    ) *const MultiSelectIO {
        return beginMultiSelectImpl(self.ctx, flags, selection_size, items_count);
    }

    /// Close the multi-select scope and return the IO view with
    /// this loop's click-emitted requests. Call `applyRequests`
    /// on it to update storage.
    pub fn endMultiSelect(self: Ui) *const MultiSelectIO {
        return endMultiSelectImpl(self.ctx);
    }

    /// Tag the next widget with a selection-user-data value. In a
    /// MultiSelect scope, the widget's item-side hooks read this
    /// to identify the item for range-select bookkeeping and
    /// SetRange request emission. Outside a scope, the value is
    /// still stored (matches imgui - widgets pre-tag cheaply) but
    /// nothing consumes it.
    pub fn setNextItemSelectionUserData(self: Ui, data: u64) void {
        self.ctx.next_item_selection_user_data = data;
    }

    /// Click-to-toggle section header. When `*open` is true the
    /// caller should submit the section's child widgets; when
    /// false they're suppressed (caller is expected to gate them
    /// with `if`). Returns true when the section is open this
    /// frame (== `*open`). Pattern:
    ///     if (ui.collapsingHeader("Advanced", &state.show_adv)) {
    ///         _ = ui.checkbox("Verbose logging", &state.verbose);
    ///         _ = ui.slider("Buffer size", &state.bufsz,.{.max = 1024 });
    ///     }
    pub fn collapsingHeader(
        self: Ui,
        label: []const u8,
        open: *bool,
    ) bool {
        return collapsingHeaderImpl(self.ctx, label, open);
    }

    // ---- tables - layout core
    /// Open a table scope. `n_columns` is the column count (each
    /// column gets `tableSetupColumn` between begin and the first
    /// row, or sensible defaults are used). Returns true when the
    /// table is active (always today; reserved for future
    /// auto-hide flags). Pattern:
    ///     if (ui.beginTable("scores", 3,.{.borders = true })) {
    ///         ui.tableSetupColumn("Name",.{.sizing =.stretch });
    ///         ui.tableSetupColumn("Score",.{.sizing =.fixed,.width = 80 });
    ///         ui.tableSetupColumn("Rank",.{.sizing =.fixed,.width = 50 });
    ///         for (rows) |r| {
    ///             ui.tableNextRow();
    ///             ui.tableNextColumn();
    ///             ui.text("{s}",.{r.name});
    ///             ui.tableNextColumn();
    ///             ui.text("{d}",.{r.score});
    ///             ui.tableNextColumn();
    ///             ui.text("#{d}",.{r.rank});
    ///         }
    ///         ui.endTable();
    ///     }
    pub fn beginTable(
        self: Ui,
        label: []const u8,
        n_columns: u32,
        opts: TableOpts,
    ) bool {
        return beginTableImpl(self.ctx, label, n_columns, opts);
    }

    /// Close a table scope. Must match a `beginTable` that
    /// returned true.
    pub fn endTable(self: Ui) void {
        endTableImpl(self.ctx);
    }

    /// Configure one column. Call between `beginTable` and the
    /// first `tableNextRow`; subsequent calls during data rows
    /// are no-ops. Order is left-to-right.
    pub fn tableSetupColumn(
        self: Ui,
        label: []const u8,
        opts: TableColumnOpts,
    ) void {
        tableSetupColumnImpl(self.ctx, label, opts);
    }

    /// Advance to the next data row. Resets the current column
    /// index to 0 and computes the row's y position based on the
    /// previous row's height.
    pub fn tableNextRow(self: Ui) void {
        tableNextRowImpl(self.ctx);
    }

    /// Advance to the next column within the current row. Sets
    /// the layout cursor to the column's x position; the next
    /// widget renders inside that column's clip rect. Returns
    /// true when the column is "in bounds" (i.e. we haven't run
    /// past `n_columns` for this row).
    pub fn tableNextColumn(self: Ui) bool {
        return tableNextColumnImpl(self.ctx);
    }

    /// Render the table's header row. Call BEFORE the first
    /// `tableNextRow`. Each column gets a clickable header that
    /// cycles sort state when clicked. Shift-click appends as
    /// a secondary key (up to N=3 per decision Q8). Plain click
    /// either flips the direction (if already primary) or
    /// promotes that column to the new primary.
    /// Pattern:
    ///     u.tableHeadersRow();
    ///     if (u.tableGetSortSpecs()) |specs| {
    ///         std.mem.sort(Row, &rows, specs, sortCmp);
    ///     }
    ///     for (rows) |r| {
    ///         u.tableNextRow();
    ///         ...
    ///     }
    pub fn tableHeadersRow(self: Ui) void {
        tableHeadersRowImpl(self.ctx);
    }

    /// Return the active table's current sort spec, or null if no
    /// sort is configured (no columns clicked yet). Pointer is
    /// stable for the rest of the current frame. Read between
    /// `tableHeadersRow` and the first `tableNextRow` to sort
    /// the data before submitting it.
    pub fn tableGetSortSpecs(self: Ui) ?*const TableSortSpecs {
        return tableGetSortSpecsImpl(self.ctx);
    }

    /// Index of the column currently being populated (0-based).
    /// Null if no table is active, or if no `tableNextColumn`
    /// has run yet this row (i.e. between `tableNextRow` and
    /// the first `tableNextColumn`).  Useful for per-cell
    /// branching when the loop body is shared across columns
    /// but renders slightly different content per column.
    pub fn tableGetColumnIndex(self: Ui) ?u32 {
        const ts: *const TableState = if (self.ctx.active_table) |*t| t else return null;
        if (ts.cur_col < 0) {
            return null;
        }
        return @intCast(ts.cur_col);
    }

    /// Number of columns configured at `beginTable`.  Null if no
    /// table is active.  Stable across the entire frame; reads
    /// the count the caller passed to `beginTable`, not the
    /// number of `tableSetupColumn` calls made so far.
    pub fn tableGetColumnCount(self: Ui) ?u32 {
        const ts: *const TableState = if (self.ctx.active_table) |*t| t else return null;
        return ts.n_columns;
    }

    /// Display name of column `index` as configured at
    /// `tableSetupColumn`, or null if no active table or if
    /// `index >= column_count`.  The returned slice points into
    /// the column's inline `name_buf` and is stable across the
    /// current frame.  Columns whose `tableSetupColumn` call
    /// passed an empty label return an empty slice (not null).
    pub fn tableGetColumnName(self: Ui, index: u32) ?[]const u8 {
        const ts: *const TableState = if (self.ctx.active_table) |*t| t else return null;
        if (index >= ts.n_columns) {
            return null;
        }
        return ts.columns[index].name();
    }

    /// Snapshot of column `index`'s queryable flag state.  Null
    /// if no active table or `index >= column_count`.  See
    /// `TableColumnFlags` docs re: what's included vs why some
    /// `TableColumnOpts` fields (sizing/width/weight) aren't
    /// roundtrippable through column state.
    pub fn tableGetColumnFlags(self: Ui, index: u32) ?TableColumnFlags {
        const ts: *const TableState = if (self.ctx.active_table) |*t| t else return null;
        if (index >= ts.n_columns) {
            return null;
        }
        const c: *const TableColumnState = &ts.columns[index];
        return .{
            .no_sort = c.no_sort,
            .no_sort_ascending = c.no_sort_ascending,
            .no_sort_descending = c.no_sort_descending,
            .no_header_label = c.no_header_label,
            .default_sort = c.default_sort,
        };
    }

    /// Override the current row's background color, overriding
    /// any alternating tint that `TableOpts.row_bg` would
    /// otherwise apply. Call AFTER `tableNextRow` and BEFORE
    /// `tableNextColumn` to set the bg for the row about to be
    /// populated.
    /// Use cases: highlight a selected row, flag a warning row in
    /// red, mark a "current user" row in accent, etc. Pass
    /// `Color.transparent` (alpha=0) to force NO background even
    /// when alternating tint would otherwise paint one.
    pub fn tableSetRowBgColor(self: Ui, color: Color) void {
        if (self.ctx.active_table) |*ts| {
            ts.row_bg_override = color;
        }
    }

    /// Override the background color of the CURRENT cell — the one
    /// just entered via `tableNextColumn`. Call AFTER
    /// `tableNextColumn` for the column you want to tint.
    /// Use cases: heat-map cells, flag specific values, draw
    /// attention to a single field without highlighting the whole
    /// row. The cell bg paints UNDER the cell's content (P7.2's
    /// 2-channel render) and OVER the row bg (cell-level overrides
    /// are more specific than row-level — so they win visually).
    /// No-op when called outside a table or before any
    /// `tableNextColumn`. Pass `Color.transparent` to clear a
    /// pending override that hasn't been painted yet.
    /// ImGui equivalent: `TableSetBgColor(ImGuiTableBgTarget_CellBg,
    /// color)` with the implicit "current column" target.
    pub fn tableSetCellBgColor(self: Ui, color: Color) void {
        const ts: *TableState = if (self.ctx.active_table) |*t| t else return;
        if (ts.cur_col < 0) {
            return;
        }
        const col_idx: usize = @intCast(ts.cur_col);
        if (col_idx >= ts.n_columns) {
            return;
        }
        ts.columns[col_idx].cell_bg_pending = color;
    }

    // ---- drag-drop source
    /// Open a drag-drop source scope. Call IMMEDIATELY after a
    /// widget that should be draggable - the widget's last_item_id
    /// is captured as the drag origin. Returns true when a drag
    /// is actively in flight from this widget THIS FRAME, in which
    /// case the caller should:
    ///   1. Call `setDragDropPayload` to register a typed payload.
    ///   2. Submit any preview widgets (text, icon) that should
    ///      follow the cursor.
    ///   3. Call `endDragDropSource` to close the scope.
    ///     if (ui.button("drag me")) {}
    ///     if (ui.beginDragDropSource(.{})) {
    ///         ui.setDragDropPayload(BuildId, &build.id);
    ///         ui.text("Build #{d}",.{build.id});
    ///         ui.endDragDropSource();
    ///     }
    /// Drag begins on mouse-down + movement past
    /// `DragDropState.DRAG_THRESHOLD` pixels (matches imgui's 4 px
    /// default). Drag ends on mouse-up; if no target consumed
    /// the payload, it's simply discarded.
    pub fn beginDragDropSource(self: Ui, opts: DragDropFlags) bool {
        return beginDragDropSourceImpl(self.ctx, opts);
    }

    /// Register a typed payload for the in-flight drag. Generic
    /// over `T` - the type tag is `@typeName(T)`, so the target
    /// side can match types at compile time. `value` is a
    /// pointer; the bytes are copied into the drag state's inline
    /// buffer. Must be called inside a `beginDragDropSource`
    /// scope that returned true.
    /// Payload size cap: `DragDropState.PAYLOAD_CAP` bytes.
    /// Oversize values silently fail to register - the source
    /// scope still renders preview, but no target will accept.
    pub fn setDragDropPayload(
        self: Ui,
        comptime T: type,
        v: *const T,
    ) void {
        setDragDropPayloadImpl(self.ctx, T, v);
    }

    /// Close a drag-drop source scope. Pairs with a
    /// `beginDragDropSource` that returned true.
    pub fn endDragDropSource(self: Ui) void {
        endDragDropSourceImpl(self.ctx);
    }

    /// Open a drop-target scope. Call IMMEDIATELY after a widget
    /// that should accept drops. Returns true when:
    ///   1. A drag is currently active, AND
    ///   2. The cursor is over the just-submitted widget's rect.
    /// While the target scope is open the target's rect is
    /// outlined in `style.button_active` so the user sees where
    /// the drop will land. Pattern:
    ///     // a slot/lane widget
    ///     ui.child("lane:" ++ name,.{ 200, 80 });
    ///     if (ui.beginDragDropTarget(.{})) {
    ///         if (ui.acceptDragDropPayload(BuildPayload,.{})) |build| {
    ///             // user released over this lane → move build here
    ///         }
    ///         ui.endDragDropTarget();
    ///     }
    /// `opts: DragDropFlags` - pass `.{}` for default. Useful
    /// flags: `.accept_no_draw_default_rect` (suppress the dashed
    /// highlight rect), `.accept_draw_as_hovered` (render the
    /// target as if hovered).
    pub fn beginDragDropTarget(self: Ui, opts: DragDropFlags) bool {
        return beginDragDropTargetImpl(self.ctx, opts);
    }

    /// Try to take the active drag's payload as a `T`. Returns the
    /// payload value when:
    ///   - The drag is active.
    ///   - The current widget is the active drop target (i.e.
    ///     called inside a `beginDragDropTarget` that returned
    ///     true).
    ///   - The payload's type tag matches `@typeName(T)`.
    ///   - The user RELEASED the mouse this frame (release-edge),
    ///     unless `opts.accept_before_delivery` is set, in which
    ///     case mid-drag peeks succeed too.
    /// Returns null otherwise. After accepting, the payload is
    /// still readable for the rest of this frame; cleanup happens
    /// at endFrame.
    pub fn acceptDragDropPayload(
        self: Ui,
        comptime T: type,
        opts: DragDropFlags,
    ) ?T {
        return acceptDragDropPayloadImpl(self.ctx, T, opts);
    }

    /// Close a drop-target scope. Pairs with a
    /// `beginDragDropTarget` that returned true.
    pub fn endDragDropTarget(self: Ui) void {
        self.ctx.drag_drop.target_widget_id = 0;
    }

    /// Tiny filled square + same-line cursor advance, ImGui-style.
    /// Common as a list-item glyph when you want a manually-bulleted
    /// paragraph.
    pub fn bullet(self: Ui) void {
        bulletImpl(self.ctx);
    }

    /// Bullet glyph + formatted text on the same line. Equivalent
    /// to `ui.bullet(); ui.sameLine(.{}); ui.text(fmt, args);`.
    pub fn bulletText(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        bulletImpl(self.ctx);
        self.sameLine(.{});
        textImpl(self.ctx, fmt, args, self.ctx.style.text);
    }

    /// Display a GPU texture inline at the current cursor. Accepts
    /// any of:
    /// - `u32` / `u32` - raw GL texture ID (legacy / advanced)
    /// - `Texture` / `*const Texture` - raylib-native, infers size
    /// - `RenderTexture` / `*const RenderTexture` - render target,
    ///   infers size AND auto-flips V coordinates so the user sees
    ///   it the right way up (RTs in OpenGL are origin-bottom-left)
    /// Pass `null` for `size` to use the texture's natural pixel size,
    /// or a `Vec2` to scale. No interaction - pair with `selectable`
    /// or `button` for clickable image variants.
    /// This is the bridge that makes recursive UI-on-render-texture
    /// composition feel natural: render a HUD to an RT, then
    /// `f.ui.image(my_rt, null)` displays it elsewhere.
    pub fn image(
        self: Ui,
        source: anytype,
        size: ?Vec2,
    ) void {
        const T = @TypeOf(source);
        var tex_id: u32 = 0;
        var natural: Vec2 = .{ 64, 64 };
        var flipped: bool = false;

        switch (@typeInfo(T)) {
            .int, .comptime_int => {
                tex_id = @intCast(source);
            },
            .pointer => |p| {
                // Single-item pointer to Texture / RenderTexture.
                switch (p.child) {
                    types.Texture => {
                        tex_id = source.id;
                        natural = .{ @floatFromInt(source.width), @floatFromInt(source.height) };
                    },
                    RenderTexture => {
                        tex_id = source.texture.id;
                        natural = .{ @floatFromInt(source.texture.width), @floatFromInt(source.texture.height) };
                        flipped = true;
                    },
                    else => @compileError(
                        "ui.image: pointer must target Texture or RenderTexture, got *" ++ @typeName(p.child),
                    ),
                }
            },
            .@"struct" => switch (T) {
                types.Texture => {
                    tex_id = source.id;
                    natural = .{ @floatFromInt(source.width), @floatFromInt(source.height) };
                },
                RenderTexture => {
                    tex_id = source.texture.id;
                    natural = .{ @floatFromInt(source.texture.width), @floatFromInt(source.texture.height) };
                    flipped = true;
                },
                else => @compileError("ui.image: unsupported struct type " ++ @typeName(T)),
            },
            else => @compileError("ui.image: pass u32 GL ID, Texture, or RenderTexture, got " ++ @typeName(T)),
        }

        imageImpl(self.ctx, tex_id, size orelse natural, flipped);
    }

    /// Direct mutable access to the active style (Tier A - see
    /// `docs/raylib-ui-integration.md`). Lets users tweak colors
    /// without reaching into internal `ctx`. Pattern:
    ///     f.ui.style().button = z.colors.amber_500;
    pub fn style(self: Ui) *Style {
        return &self.ctx.style;
    }

    /// Scale the whole UI to the viewport, in one call.
    ///
    /// ── ★★ WHY THIS EXISTS ──
    ///
    /// zimr ships in a browser tab, so "the window" is anything from a 360 px phone to a 4K
    /// desktop, and a UI sized in fixed pixels is unreadable at one end and comical at the
    /// other. **151 of the examples already scale by hand and 63 do not** — and the 151 do it
    /// with at least four different formulas (`/16`, `/26`, `/30`, `/46`, each with its own
    /// clamps) around an otherwise IDENTICAL block of padding and spacing. That block was
    /// copy-pasted verbatim: every one of them uses 0.35/0.3, 0.4, 0.5 and 1.6.
    ///
    /// ★ SO THE VARYING PART IS ONE NUMBER and the rest is duplication. `characters_across` is
    /// that number, named for what it actually controls: roughly how many characters of body
    /// text fit across the region the UI occupies. A full-width panel wants ~30; a half-width
    /// one wants ~16, which is the same text at the same size in half the space.
    ///
    /// ★ IT IS ADDITIVE, and deliberately so. Applying this from `UiHost.begin` instead would
    /// fix all 63 stragglers at once and DOUBLE-SCALE the 151 that already do it by hand.
    ///
    /// Returns the font size it chose, since callers size their own plots and images from it.
    pub fn scaleToViewport(self: Ui, viewport_width: f32, characters_across: f32) f32 {
        // ★ THE CLAMPS ARE NOT DECORATION. Without a floor, a narrow phone gets text no one can
        // read; without a ceiling, a wide desktop gets a panel that looks like a warning sign.
        // 12 and 26 are the range the hand-rolled versions converged on between them.
        const font_size: f32 = clamp(viewport_width / @max(1.0, characters_across), 12.0, 26.0);
        const s: *Style = self.style();
        s.font_size = font_size;
        s.frame_padding = .{ font_size * 0.35, font_size * 0.3 };
        s.item_spacing = .{ font_size * 0.4, font_size * 0.4 };
        s.window_padding = .{ font_size * 0.5, font_size * 0.5 };
        s.title_bar_height = font_size * 1.6;
        return font_size;
    }

    /// Whether the viewport is narrow enough to want a phone layout.
    ///
    /// ★ ONE THRESHOLD, NAMED ONCE. Demos that branch on width were each picking their own —
    /// and a demo that disagrees with its neighbour about what counts as a phone is a demo
    /// whose layout changes when you tab between them.
    pub fn isNarrow(viewport_width: f32) bool {
        return viewport_width < 620.0;
    }

    /// Temporarily override one field of `Style` until the matching
    /// `popStyle()`. Reflection-based: `field_name` is a comptime
    /// string that must name an actual field of `Style`; `value`
    /// is typed via `anytype` and must coerce to that field's type
    /// (compile error otherwise).
    ///     ui.pushStyle("frame_padding",.{ 12, 8 });
    ///     defer ui.popStyle();
    ///     _ = ui.button("Chunky",.{});
    /// Stack-cap: `style_stack`'s 32 slots. Every push must be
    /// paired with a pop; mismatched pushes/pops leave the style
    /// in a wrong state for the rest of the frame.
    pub fn pushStyle(
        self: Ui,
        comptime field_name: []const u8,
        v: anytype,
    ) void {
        pushStyleImpl(self.ctx, field_name, v);
    }

    /// Pair with `pushStyle`. Restores the most-recently-pushed
    /// field to its prior value. Safe to call on an empty stack
    /// (no-op).
    pub fn popStyle(self: Ui) void {
        popStyleImpl(self.ctx);
    }

    /// Push a font onto the style stack. Subsequent widgets render
    /// with `*font` until the matching `popFont()`. Use for code
    /// sections (mono font), section headers (larger / different
    /// face), etc.
    /// Currently `font_size` is NOT pushed alongside - fonts in zimr
    /// carry their own design size separately from the rendered size.
    /// To change rendered size while pushed, call `pushStyle(
    /// "font_size", new_size)` separately. ImGui's `PushFont(font,
    /// size)` does both; zimr keeps them separable so a single font
    /// can be scaled by callers without re-pushing.
    /// Convenience wrapper over `pushStyle("font", font)`. Pairs
    /// with `popFont()`. Pushing a null pointer reverts to the
    /// default cached font. ImGui: `PushFont(font)`.
    pub fn pushFont(self: Ui, font: ?*const Font) void {
        pushStyleImpl(self.ctx, "font", font);
    }

    /// Pair with `pushFont`. Restores the most-recently-pushed
    /// font. Safe to call on an empty stack (no-op). ImGui:
    /// `PopFont()`.
    pub fn popFont(self: Ui) void {
        popStyleImpl(self.ctx);
    }

    /// Read the current layout cursor (next-widget position) for
    /// the active window. Useful before calling `setCursorPos` to
    /// stash + restore manual layout decisions, or to overlay
    /// custom rendering at a known point in the flow. Returns
    /// `(0, 0)` outside any window scope.
    pub fn getCursorPos(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return w.layout.cursor_pos;
    }

    /// Force the layout cursor to a specific position within the
    /// current window. Use case: manually placing a widget at a
    /// pixel-precise spot, or restoring after a `getCursorPos`
    /// snapshot. No-op outside any window scope.
    pub fn setCursorPos(self: Ui, pos: Vec2) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.layout.cursor_pos = pos;
        w.layout.line_height = 0;
    }

    /// Returns true if the UI currently wants to consume keyboard
    /// input - i.e., an `inputText` is focused. Game-input handlers
    /// should gate themselves on `!f.ui.wantCaptureKeyboard()` to
    /// avoid double-firing while the user types into a UI field.
    pub fn wantCaptureKeyboard(self: Ui) bool {
        // Active widget plus an input_text_state cursor implies a
        // text field has focus. The state's defaults map to "no
        // focus" so this is robust across activation sources.
        return self.ctx.active_id != 0;
    }

    /// Returns true if the UI currently wants to consume mouse input
    /// - i.e., the pointer is over a UI window or a UI widget is
    /// being interacted with. Game-input handlers (camera drag,
    /// world-click selection) should gate themselves on
    /// `!f.ui.wantCaptureMouse()` to avoid clicking through windows.
    pub fn wantCaptureMouse(self: Ui) bool {
        if (self.ctx.active_id != 0) {
            return true;
        }
        // Hit-test the mouse against every window submitted this
        // frame. Cheap (typically ≤ 8 windows; bounded stack) and
        // robust to overlapping windows.
        const m: Vec2 = self.ctx.input.mouse_pos;
        for (self.ctx.frame_windows.items[0..self.ctx.frame_windows.len]) |w| {
            const r = Rectangle{ .x = w.pos[0], .y = w.pos[1], .width = w.size[0], .height = w.size[1] };
            if (pointInRect(m, r)) {
                return true;
            }
        }
        // ...and against LAST frame's windows, so this answers correctly even
        // when called before this frame's UI has been submitted (the natural
        // order: gate scene input first, draw the UI after). Without this the
        // list above is still empty and the pointer clicks straight through the
        // panel. Matches Dear ImGui, whose WantCaptureMouse likewise reflects
        // the previous frame's layout.
        for (self.ctx.prev_window_rects.items[0..self.ctx.prev_window_rects.len]) |r| {
            if (pointInRect(m, r)) {
                return true;
            }
        }
        return false;
    }

    /// Get the draw list of the currently-active window so the caller
    /// can record arbitrary `addLine` / `addCircleFilled` / etc.
    /// primitives inside it. Returns null when called outside a
    /// `ui.window(...)` block. The returned pointer is valid only
    /// for the rest of the current frame.
    pub fn getDrawList(self: Ui) ?*DrawList {
        const w: *Window = self.ctx.current_window orelse return null;
        return &w.draw_list;
    }

    /// Allocator backing the DrawList's command list + variable
    /// payloads. Returns the UiContext's frame arena, which is
    /// reset at endFrame - so any slice you allocate through this
    /// is valid for exactly one frame. Demos that call
    /// `getDrawList().addPolyline(...)` pass the result here as the
    /// `alloc` argument.
    pub fn drawListAllocator(self: Ui) Allocator {
        return self.ctx.frame_arena.allocator();
    }

    /// Current layout cursor position in screen-space pixels. Useful
    /// when you want to place custom-rendered primitives at the spot
    /// the next widget would land. Returns `.{0,0}` when called
    /// outside a window block.
    pub fn getCursorScreenPos(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return w.layout.cursor_pos;
    }

    /// Cursor position at the start of the current window's content
    /// area, in screen-space pixels. Useful as a reference point
    /// for computing relative offsets within a window — e.g.
    /// `getCursorPos() - getCursorStartPos()` is how far down the
    /// content area you've laid out so far. Returns `.{0,0}` when
    /// called outside a window block. Differs from raw ImGui
    /// `GetCursorStartPos()` which returns window-local coords; the
    /// rest of zimr's cursor accessors use screen-space, so this
    /// getter follows that convention. ImGui: `GetCursorStartPos()`.
    pub fn getCursorStartPos(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return w.layout.origin;
    }

    /// Single-line text edit. Caller passes the backing buffer
    /// (`buf: []u8`) and a pointer to its current content length
    /// (`len: *usize`). We grow `len` up to `buf.len` on type, never
    /// realloc. Returns true on any frame where contents changed.
    /// Pattern:
    ///     var name_buf: [64]u8 = undefined;
    ///     var name_len: usize = 0;
    ///     _ = ui.inputText("Name", &name_buf, &name_len,.{});
    /// Supports: insert at cursor, backspace, delete, left/right
    /// arrows, home/end, click-to-position cursor, commit-on-Enter
    /// (defocuses), cancel-on-Escape (defocuses, no revert). No
    /// selection ranges or clipboard support.
    pub fn inputText(
        self: Ui,
        label: []const u8,
        buf: []u8,
        len: *usize,
        opts: InputTextOpts,
    ) bool {
        return inputTextImpl(self.ctx, label, buf, len, opts);
    }

    /// Like `inputText`, but `hint` is shown in dimmed
    /// `style.text_disabled` color when the buffer is empty AND
    /// the widget isn't focused. Disappears the moment the user
    /// types or focuses. Equivalent to setting `opts.hint`
    /// directly - provided for ImGui parity (`InputTextWithHint`).
    ///     _ = ui.inputTextWithHint("Search", "type to search...",
    ///                              &state.query_buf, &state.query_len,.{});
    pub fn inputTextWithHint(
        self: Ui,
        label: []const u8,
        hint: []const u8,
        buf: []u8,
        len: *usize,
        opts: InputTextOpts,
    ) bool {
        var o: @TypeOf(opts) = opts;
        o.hint = hint;
        return inputTextImpl(self.ctx, label, buf, len, o);
    }

    /// Multi-line text editor. Same buffer-and-length contract as
    /// `inputText`, plus an explicit `size: Vec2` for the
    /// editor's rendered dimensions (in pixels - caller decides;
    /// `size.x <= 0` auto-fills the remaining row width). Returns
    /// true on any frame the buffer changed.
    /// Differences from `inputText`:
    ///   - **Enter inserts a newline** (single-line variant
    ///     defocuses on Enter).
    ///   - **Up / Down arrows** move the cursor between lines,
    ///     preserving column where possible.
    ///   - **Click-to-place** computes the target line by y-
    ///     distance from the editor's top, then the column by x-
    ///     distance into that line.
    ///   - **Escape defocuses** without committing.
    /// Limitations (deferred to later phases):
    ///   - No selection (shift-arrow, mouse-drag).
    ///   - No clipboard cut/copy/paste - lands in Phase A4 with
    ///     `InputTextCallbackData`.
    ///   - No undo/redo.
    ///   - No tab character handling (Tab is consumed as a
    ///     focus-traversal key by the runtime; pasting a string
    ///     with `\t` works, typing one doesn't).
    ///   - No scroll - caller wraps in `beginChild(...)` for
    ///     scrollable editing of buffers taller than `size.y`.
    pub fn inputTextMultiline(
        self: Ui,
        label: []const u8,
        buf: []u8,
        len: *usize,
        size: Vec2,
        opts: InputTextOpts,
    ) bool {
        return inputTextMultilineImpl(self.ctx, label, buf, len, size, opts);
    }

    /// Slider over an angle stored as RADIANS, displayed and
    /// dragged in DEGREES. ImGui's `SliderAngle` convention: the
    /// math wants radians, the user wants degrees. Returns true
    /// when the value changed this frame. `min_deg` / `max_deg`
    /// are in degrees (default -360 / 360).
    ///     _ = ui.sliderAngle("Rotation", &state.yaw_rad,.{});
    pub fn sliderAngle(
        self: Ui,
        label: []const u8,
        rad: *f32,
        opts: SliderAngleOpts,
    ) bool {
        var deg: f32 = degFromRad(rad.*);
        const changed: bool = self.slider(label, &deg, .{
            .min = opts.min_deg,
            .max = opts.max_deg,
            .fmt = opts.fmt,
        });
        if (changed) {
            rad.* = radFromDeg(deg);
        }
        return changed;
    }

    /// Shorthand for `if (isItemHovered()) beginTooltip()`. Open a
    /// tooltip scope ONLY when the just-submitted widget is
    /// currently hovered. Returns true when the tooltip is open
    /// - caller submits tooltip content then calls
    /// `endItemTooltip()`.
    ///     _ = ui.button("?",.{});
    ///     if (ui.beginItemTooltip()) {
    ///         defer ui.endItemTooltip();
    ///         ui.text("This button does the thing.",.{});
    ///         ui.text("(Press Enter to confirm)",.{});
    ///     }
    pub fn beginItemTooltip(self: Ui) bool {
        if (!self.isItemHovered(.{})) {
            return false;
        }
        self.beginTooltip();
        return true;
    }

    /// Pair with `beginItemTooltip` when it returned true.
    /// Identical to `endTooltip` - separate name keeps the
    /// matched pair visually obvious in caller code.
    pub fn endItemTooltip(self: Ui) void {
        self.endTooltip();
    }

    /// Public wrapper over the internal text-measurement
    /// machinery. Use to lay out custom widgets that need to
    /// reserve space for a piece of text without first drawing
    /// it. Honors the current `Style.font` + `font_size` +
    /// `font_spacing`.
    pub fn calcTextSize(self: Ui, s: []const u8) Vec2 {
        return measureTextS(self.ctx, s);
    }

    /// Queue keyboard focus for the NEXT focusable widget
    /// submitted this frame. Call BEFORE the widget you want
    /// focused (e.g. before an `inputText` you want to be ready
    /// for typing the moment a modal opens). No-op if no
    /// focusable widget follows in the same frame. Today only
    /// `inputText` honors the flag.
    ///     if (state.search_just_opened) {
    ///         ui.setKeyboardFocusHere();
    ///         state.search_just_opened = false;
    ///     }
    ///     _ = ui.inputText("Search", &buf, &len,.{});
    pub fn setKeyboardFocusHere(self: Ui) void {
        self.ctx.next_widget_take_focus = true;
    }

    /// Dropdown picker - click the closed row to expand a vertical
    /// list of items, click an item to select. Returns true on the
    /// frame the selection changed.
    ///     const modes = [_][]const u8{ "Off", "Low", "Medium", "High" };
    ///     _ = ui.combo("Quality", &state.quality_idx, &modes,.{});
    /// Single-slot: only one combo can be open at a time. Clicking
    /// outside the dropdown (or on the closed row again) closes it.
    /// **Real overlay popup** - the dropdown is recorded into the
    /// foreground draw list, replayed at endFrame on top of all
    /// windows. The layout below the combo does NOT reflow when
    /// the dropdown opens; the dropdown floats over whatever's there.
    /// This matches Dear ImGui's combo behavior. Multiple combos in
    /// the same window are stable: open one, the layout below stays
    /// put.
    pub fn combo(
        self: Ui,
        label: []const u8,
        current_index: *i32,
        items: []const []const u8,
        opts: ComboOpts,
    ) bool {
        return comboImpl(self.ctx, label, current_index, items, opts);
    }

    /// Begin a combo dropdown that the caller fills with custom
    /// content. Sibling of `combo()` (which takes a string array);
    /// use `beginCombo` when rows need icons, color swatches,
    /// descriptions, or any other widget. Returns true when the
    /// dropdown is open - caller submits widgets, then MUST call
    /// `endCombo()` to close the scope. Returns false when
    /// closed; do NOT call endCombo in that case. ImGui:
    /// `BeginCombo(label, preview_value, flags)`.
    pub fn beginCombo(
        self: Ui,
        label: []const u8,
        preview: []const u8,
        opts: ComboOpts,
    ) bool {
        return beginComboImpl(self.ctx, label, preview, opts);
    }

    /// Close a `beginCombo` scope. Pair with EXACTLY one
    /// `beginCombo` that returned true. ImGui: `EndCombo()`.
    pub fn endCombo(self: Ui) void {
        endComboImpl(self.ctx);
    }

    /// Recursive disclosure-triangle hierarchy node. Library-managed
    /// open state (persistent across frames in `UiContext.tree_open_state`).
    /// Returns true when open - the caller should submit child widgets
    /// inside the `if` block and pair with `treePop()` on the way out.
    /// Pattern:
    ///     if (ui.treeNode("Player",.{})) {
    ///         defer ui.treePop();
    ///         _ = ui.slider("HP", &state.hp,.{.min = 0,.max = 100 });
    ///         _ = ui.slider("MP", &state.mp,.{.min = 0,.max = 100 });
    ///         if (ui.treeNode("Inventory",.{})) {
    ///             defer ui.treePop();
    ///             _ = ui.checkbox("Sword", &state.has_sword);
    ///         }
    ///     }
    /// Each open node bumps the window's `indent_x` so children
    /// visually nest. Nodes are stable across frames (open state
    /// keyed by hashed label + parent ID).
    /// Opts-arg form: pass `.{}` for the
    /// default click-toggle node, or set fields on `TreeNodeOpts`
    /// for flags like `.default_open`, `.leaf`, `.framed`, etc.
    /// See `TreeNodeOpts` for the full flag inventory.
    ///     if (ui.treeNode("src",.{.default_open = true })) {
    ///         defer ui.treePop();
    ///         _ = ui.treeNode("ui.zig",.{.leaf = true });
    ///         ui.treePop(); // pair with leaf
    ///     }
    /// For `opts.leaf = true`, always returns true (no toggle, no
    /// arrow - caller still calls `treePop` if they push children,
    /// otherwise can skip the pop). Replaces the old
    /// `treeNode(label)` + `treeNodeEx(label, opts)` dual API.
    pub fn treeNode(
        self: Ui,
        label: []const u8,
        opts: TreeNodeOpts,
    ) bool {
        return treeNodeExImpl(self.ctx, label, opts);
    }

    /// Pair with `treeNode` on the way out. Decrements indent.
    /// Safe to call when the tree was closed (no-op).
    /// In the new layout model, this just decrements
    /// `indent_x` - the next widget's `advanceLayout` will reset
    /// the cursor X to `origin + indent` from the popped depth.
    /// No need to manually mutate `cursor_pos` here (the turn-308
    /// hack of "also decrement cursor_pos[0]" is no longer needed,
    /// because the cursor is recomputed from origin+indent on
    /// every row).
    pub fn treePop(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        if (w.layout.indent_x >= indent_amount) {
            w.layout.indent_x -= indent_amount;
            // Update cursor_pos[0] for the first widget submitted
            // right after the pop (before any advanceLayout has
            // re-resolved it). Without this, that widget would see
            // a stale cursor_pos[0] from the deeper-indent inner
            // scope and render one indent_amount too far right.
            // Imgui-style screen-X formula: origin - scroll + local.
            w.layout.cursor_pos[0] = w.layout.origin[0] - w.scroll_x + w.layout.indent_x;
        }
    }

    /// Force the next tree node's open state. Cleared after
    /// consumption. Imgui: `SetNextItemOpen`.
    pub fn setNextItemOpen(self: Ui, open: bool) void {
        self.ctx.next_item_open = open;
    }

    /// True if the most-recently-submitted tree node was toggled
    /// this frame. Imgui: `IsItemToggledOpen()` (queries the
    /// ToggledOpen status flag on LastItemData).
    pub fn isItemToggledOpen(self: Ui) bool {
        return self.ctx.item_just_toggled;
    }

    /// Query a tree node's stored open state without rendering.
    /// Useful for parent code that wants to know if a section is
    /// expanded. `str_id` must hash to the same id the tree node
    /// uses (i.e. its label inside the current id-stack scope).
    /// Returns `default_open` if no state stored. Imgui:
    /// `TreeNodeGetOpen(id)`.
    pub fn treeNodeGetOpen(self: Ui, str_id: []const u8) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        const id: Id = widgetId(self.ctx, w, str_id);
        return self.ctx.tree_open_state.get(id) orelse false;
    }

    /// Horizontal offset from the tree-node's start-X to the
    /// label start. Useful for `sameLine`-aligning content
    /// underneath a node's label column. Returns
    /// `font_size + 4` (triangle width + gap), matching the
    /// existing `treeNodeImpl` layout. Imgui:
    /// `GetTreeNodeToLabelSpacing()`.
    pub fn getTreeNodeToLabelSpacing(self: Ui) f32 {
        return self.ctx.style.font_size + 4;
    }

    /// Manually push a horizontal indent on the cursor. Pair with
    /// `unindent()`. Useful for visual grouping outside of trees.
    pub fn indent(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.layout.indent_x += indent_amount;
        // The current row's cursor x ALSO needs to bump so the next
        // widget on this row honors the new indent. Subsequent rows
        // pick up `indent_x` via advanceLayout's reset.
        w.layout.cursor_pos[0] += indent_amount;
    }

    /// Pair with `indent()`. Decrements indent and pulls the current
    /// row's cursor back. Safe to call at zero indent (no-op).
    pub fn unindent(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        if (w.layout.indent_x >= indent_amount) {
            w.layout.indent_x -= indent_amount;
            w.layout.cursor_pos[0] -= indent_amount;
        }
    }

    // ---- Item state queries
    /// Was the most recently submitted item under the mouse this
    /// frame? Use after a widget call to attach hover behavior:
    ///     if (ui.button("Save",.{})) save();
    ///     if (ui.isItemHovered(.{})) ui.setTooltip("Ctrl+S",.{});
    /// Opts-arg form: pass `.{}` for the
    /// default "directly hovered, not blocked" semantics, or set
    /// fields on `HoveredFlags` for relaxed checks:
    ///     if (ui.isItemHovered(.{.allow_when_disabled = true }))...
    /// Today most `HoveredFlags` fields are accepted but NO-OP for
    /// items - they relax blocking checks zimr doesn't yet enforce
    /// (popup-blocking, active-item occlusion, per-item z-order,
    /// disabled-state, nav override). User code can set them
    /// today and pick up the behavior automatically when each
    /// machinery lands.
    /// Hover-delay flags are not on `HoveredFlags` yet - deferred
    /// until per-id hover-start timestamp state lands on
    /// `UiContext`. ImGui: `IsItemHovered(flags)`.
    pub fn isItemHovered(self: Ui, opts: HoveredFlags) bool {
        _ = opts;
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_hovered;
    }

    // ---- Mouse cursor + drag (Phase B1)
    /// Set the canvas cursor style. Pass the imgui-style mouse-cursor
    /// enum - `default`, `pointing_hand`, `ibeam`, `resize_ew`, etc.
    /// Pairs naturally with hover detection:
    ///     if (ui.isItemHovered(.{})) ui.setMouseCursor(.pointing_hand);
    /// The value persists until something else sets it (no per-frame
    /// reset), so most apps call this conditionally from their hover
    /// branches. No-op when the in-flight frame's input state isn't
    /// available - defensive for ctx-only test harnesses.
    pub fn setMouseCursor(self: Ui, cursor: MouseCursor) void {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return;
        runtime.input.setMouseCursor(s, cursor);
    }

    /// The cursor value most recently passed to `setMouseCursor`.
    /// Defaults to `.default` for a fresh `InputState`. Useful for
    /// stacked hover detection where multiple widgets may try to
    /// claim the cursor - read the current value, decide, then set.
    pub fn getMouseCursor(self: Ui) MouseCursor {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return .default;
        return runtime.input.getMouseCursor(s);
    }

    /// True while `button` is held and the cursor has moved more than
    /// `lock_threshold` pixels from where the button was pressed. Pass
    /// `-1` for the imgui-default threshold (6 px). Distinguishes
    /// click-vs-drag for custom widgets:
    ///     if (ui.isMouseDragging(.left, -1)) {
    ///         const d = ui.getMouseDragDelta(.left, -1);
    ///         widget_pos.x += d.x; widget_pos.y += d.y;
    ///         ui.resetMouseDragDelta(.left);
    ///     }
    /// True while `key` is currently held. Reads the per-frame
    /// `InputSnapshot.keys` array — no syscall, no runtime input
    /// lookup, just an array index. Stable across the whole frame.
    /// Mirrors imgui's `IsKeyDown` (imgui.h:1097).
    pub fn isKeyDown(self: Ui, key: KeyCode) bool {
        return self.ctx.input.keys[@backingInt(key)].down;
    }

    /// True for exactly one frame: the frame `key` transitioned
    /// up→down. Edge event. Mirrors imgui's `IsKeyPressed`
    /// (imgui.h:1098). This is one-shot only; for key-repeat
    /// firing, use `isKeyPressedOrRepeat`.
    pub fn isKeyPressed(self: Ui, key: KeyCode) bool {
        return self.ctx.input.keys[@backingInt(key)].pressed_this_frame;
    }

    /// True for exactly one frame: the frame `key` transitioned
    /// down→up. Edge event. Mirrors imgui's `IsKeyReleased`
    /// (imgui.h:1099).
    pub fn isKeyReleased(self: Ui, key: KeyCode) bool {
        return self.ctx.input.keys[@backingInt(key)].released_this_frame;
    }

    /// True if either left or right Shift is currently held.
    /// Convenience for the very common case of testing a modifier
    /// without caring which side. Mirrors imgui's `io.KeyShift`.
    pub fn isShiftDown(self: Ui) bool {
        return self.ctx.input.keys[@backingInt(KeyCode.left_shift)].down or
            self.ctx.input.keys[@backingInt(KeyCode.right_shift)].down;
    }

    /// True if either left or right Control is currently held.
    /// On macOS this is the literal Control key, NOT Cmd —
    /// platform-aware modifier remapping (imgui's KeyCtrl-on-mac =
    /// Cmd convention) is not yet done; callers on mac who want
    /// "command-or-control" should check both `isCtrlDown` and
    /// `isSuperDown`.
    pub fn isCtrlDown(self: Ui) bool {
        return self.ctx.input.keys[@backingInt(KeyCode.left_control)].down or
            self.ctx.input.keys[@backingInt(KeyCode.right_control)].down;
    }

    /// True if either left or right Alt is currently held.
    pub fn isAltDown(self: Ui) bool {
        return self.ctx.input.keys[@backingInt(KeyCode.left_alt)].down or
            self.ctx.input.keys[@backingInt(KeyCode.right_alt)].down;
    }

    /// True if either left or right Super (Windows / Command) is held.
    pub fn isSuperDown(self: Ui) bool {
        return self.ctx.input.keys[@backingInt(KeyCode.left_super)].down or
            self.ctx.input.keys[@backingInt(KeyCode.right_super)].down;
    }

    /// `isKeyPressed` plus key-repeat: fires on initial press AND
    /// at the OS-defined repeat cadence while held. Used by text
    /// input for backspace/delete/arrow keys so the user can hold
    /// the key for accelerated motion/deletion. Mirrors imgui's
    /// `IsKeyPressed(key, repeat=true)` (the default `repeat=true`
    /// variant — `imgui.h:1098`).
    ///
    /// Implementation routes through raylib's
    /// `isKeyPressedRepeat` for the held-and-repeating case
    /// (because raylib owns the OS-level repeat timer; mirroring
    /// it in zimr would drift). Initial-press case uses the
    /// snapshot for consistency with `isKeyPressed`.
    pub fn isKeyPressedOrRepeat(self: Ui, key: KeyCode) bool {
        if (self.isKeyPressed(key)) {
            return true;
        }
        const s: *runtime.input.InputState = self.ctx.input_state orelse return false;
        return runtime.input.isKeyPressedRepeat(s, key.toRaylib());
    }

    /// Result of `getOrPutState`. Mirrors `GetOrPutResult` from
    /// `std.AutoHashMapUnmanaged` — the caller branches on
    /// `found_existing` to decide whether to write `value_ptr` with
    /// an initial value or read what's already there.
    ///
    /// `value_ptr` is stable until the next `getOrPutState(T,...)`
    /// for the same `T`. Don't hold across calls.
    pub fn StateGetOrPut(comptime T: type) type {
        return struct {
            value_ptr: *T,
            found_existing: bool,
        };
    }

    /// Look up (T, id) — return a slot pointer plus whether it
    /// existed. When `!found_existing`, the slot's contents are
    /// **undefined** (matches `std.HashMap.getOrPut` semantics) —
    /// the caller MUST write through `value_ptr` before reading.
    ///
    /// Standard idiom for a type with a sensible zero / default:
    ///
    ///     const r = u.getOrPutState(MyKnobState, id,.{});
    ///     if (!r.found_existing) r.value_ptr.* =.{};
    ///     r.value_ptr.angle += delta;
    ///
    /// For a type without a default, supply the seed explicitly:
    ///
    ///     const r = u.getOrPutState(DragState, id,.{});
    ///     if (!r.found_existing) r.value_ptr.* =.{
    ///         .origin = mouse_pos,.active = true,
    ///     };
    ///
    /// One hash on the outer map, one on the inner map. No
    /// allocation in the common case (slot already exists).
    ///
    /// `opts.persist = true` enrolls T in the on-disk save/load
    /// path. Flag is sticky once set — re-passing `false` after
    /// a `true` does not disenroll, because some other call site
    /// may rely on the registration.
    pub fn getOrPutState(
        self: Ui,
        comptime T: type,
        id: Id,
        opts: StateOpts,
    ) StateGetOrPut(T) {
        const key: u64 = comptime extStorageKey(T);

        const OuterGop = std.AutoHashMapUnmanaged(u64, ExtStorageSlot).GetOrPutResult;
        const outer: OuterGop = self.ctx.ext_storage.getOrPut(self.ctx.gpa, key) catch
            @panic("ext_storage outer-map OOM");
        if (!outer.found_existing) {
            const inner: *std.AutoHashMapUnmanaged(Id, T) =
                self.ctx.gpa.create(std.AutoHashMapUnmanaged(Id, T)) catch
                    @panic("ext_storage inner-map OOM");
            inner.* = .{};
            outer.value_ptr.* = .{
                .map = @ptrCast(inner),
                .deinit_fn = deinitErasedMap(T),
                .has_persist = false,
            };
        }

        // Persist enrollment is sticky and bound on first true.
        // The fn closures need T comptime-known — here is the only
        // place that's available.
        if (opts.persist and !outer.value_ptr.has_persist) {
            outer.value_ptr.has_persist = true;
            outer.value_ptr.type_name = @typeName(T);
            outer.value_ptr.serialize_fn = serializeErasedMap(T);
            outer.value_ptr.deserialize_fn = deserializeErasedMap(T);
        }

        const typed: *std.AutoHashMapUnmanaged(Id, T) =
            @ptrCast(@alignCast(outer.value_ptr.map));
        const InnerGop = std.AutoHashMapUnmanaged(Id, T).GetOrPutResult;
        const inner: InnerGop = typed.getOrPut(self.ctx.gpa, id) catch
            @panic("ext_storage inner-map id OOM");
        return .{ .value_ptr = inner.value_ptr, .found_existing = inner.found_existing };
    }

    /// Read-only state lookup. Returns null if no slot exists for
    /// (T, id). Use when you want to react to existing state but
    /// not create it — most callers want `getOrPutState`.
    pub fn getState(
        self: Ui,
        comptime T: type,
        id: Id,
    ) ?*T {
        const key: u64 = comptime extStorageKey(T);
        const slot: *ExtStorageSlot = self.ctx.ext_storage.getPtr(key) orelse return null;
        const typed: *std.AutoHashMapUnmanaged(Id, T) = @ptrCast(@alignCast(slot.map));
        return typed.getPtr(id);
    }

    // Three primitives that compose into "the minimum extension-
    // author surface" — given (id, rect, opts), do all the
    // boilerplate (clip test, hovered_id update, press/release
    // machine, button_repeat, keyboard activation) that every
    // widget needs. Used by zimr's built-in button/checkbox/
    // radio/selectable/arrowButton/smallButton.
    //

    // Imgui ref: `imgui_internal.h:3546-3548` (ItemSize, ItemAdd)
    // + `imgui_internal.h:3968` (ButtonBehavior).

    /// Advance the layout cursor by `size`, marking that a widget
    /// of those dimensions occupied the current cursor position.
    /// Must be called by every widget at end-of-submission, AFTER
    /// drawing (so the cursor advance happens once).
    ///
    /// Mirrors imgui's `ItemSize(ImVec2)`. Imgui's optional
    /// `text_baseline_y` is not surfaced — zimr widgets don't
    /// currently use cross-baseline alignment. Add if needed.
    pub fn itemSize(self: Ui, size: Vec2) void {
        const w: *Window = self.ctx.current_window orelse return;
        advanceLayout(w, size, self.ctx.style.item_spacing, 0);
    }

    /// Register a widget rectangle with the given `id`, returning
    /// `true` if the widget should be drawn this frame. Returns
    /// `false` when the rect is fully outside the current clip
    /// rect (so the caller can skip drawing entirely — early
    /// exit). Side effects: sets `ctx.hovered_id = id` when the
    /// mouse is over the rect.
    ///
    /// Mirrors imgui's `ItemAdd(const ImRect& bb, ImGuiID id)`.
    /// Today the clip-rect check is simple "is rect within
    /// window bounds"; future canvas / scroll-clip integration
    /// (Q4) will tighten this.
    ///
    /// The CALLER computes the rect and the id (`u.getId(label)`).
    /// itemAdd doesn't claim the layout cursor — pair with
    /// `itemSize` after drawing.
    pub fn itemAdd(
        self: Ui,
        rect: Rectangle,
        id: Id,
    ) bool {
        const w: *Window = self.ctx.current_window orelse return false;

        // Clip test: is the rect outside the window's content area?
        // Cheap "is fully outside" check. Partial overlap returns
        // true (caller draws + the renderer clips at scissor time).
        const wx: f32 = w.pos[0];
        const wy: f32 = w.pos[1];
        const wx2: f32 = w.pos[0] + w.size[0];
        const wy2: f32 = w.pos[1] + w.size[1];
        const fully_outside: bool =
            rect.x + rect.width <= wx or
            rect.x >= wx2 or
            rect.y + rect.height <= wy or
            rect.y >= wy2;
        if (fully_outside) {
            return false;
        }

        // Hovered update. pointInRect is the same test
        // buttonImpl uses, so the behavior is consistent.
        if (pointInRect(self.ctx.input.mouse_pos, rect)) {
            self.ctx.hovered_id = id;
        }
        return true;
    }

    /// Output of `buttonBehavior`: every edge event + level state
    /// the extension might react to. All booleans are stable for
    /// one frame — read once, branch as needed.
    pub const ButtonResult = struct {
        /// True for one frame when the button "fires" — release-
        /// inside-rect after a press OR a `button_repeat` tick OR
        /// keyboard activation while focused. This is what
        /// existing `pressed` returns from `u.button`.
        pressed: bool,
        /// True while the mouse is over the widget's rect this
        /// frame. Same as `ctx.hovered_id == id` AFTER itemAdd
        /// runs.
        hovered: bool,
        /// True while `ctx.active_id == id` (mouse pressed inside
        /// the rect, button still down). Useful for "darken on
        /// hold" visual feedback.
        held: bool,
        /// True for ONE frame: the frame the user clicked into
        /// this widget (mouse_down inside the rect). Same as
        /// imgui's `g.ActiveIdJustActivated` for this id.
        just_activated: bool,
        /// True for ONE frame: the frame `active_id` returned to 0
        /// because this widget released (regardless of inside/
        /// outside). Useful for drag-end snap-back patterns.
        just_deactivated: bool,
    };

    /// Options for `buttonBehavior`. Subset of imgui's
    /// `ImGuiButtonFlags`; zimr's per-widget `ItemFlags` covers
    /// the same ground for built-ins, but extension authors
    /// using `buttonBehavior` directly want a self-contained
    /// surface that doesn't depend on `pushItemFlag` ceremony.
    pub const ButtonBehaviorOpts = struct {
        /// When true, fires `pressed` periodically while held.
        /// Cadence matches imgui defaults: 400ms initial delay,
        /// 50ms repeat thereafter. Same machinery as
        /// `ItemFlags.button_repeat` on built-in widgets.
        repeat: bool = false,
    };

    /// Run the press / release / repeat / keyboard-activation
    /// state machine for `id` over the rect `rect`. Returns
    /// edge events + level state in a `ButtonResult`. Doesn't
    /// draw anything — caller draws based on `result.hovered` /
    /// `held`. Doesn't claim the layout — caller pairs with
    /// `itemSize(rect_size)` after drawing.
    ///
    /// Mirrors imgui's `ButtonBehavior(const ImRect&, ImGuiID,
    /// bool*, bool*, ImGuiButtonFlags)`. Output struct replaces
    /// imgui's out-pointer pattern.
    ///
    /// The mouse hit test inside this fn uses `pointInRect` for
    /// consistency with `itemAdd`. Calling pattern:
    ///
    ///     const rect =...;
    ///     const id = u.getId("knob");
    ///     u.itemSize(rect_size); // OR after the draw if you
    ///                             // want pixel-exact "current
    ///                             // line height" tracking
    ///     if (!u.itemAdd(rect, id)) return;
    ///     const r: Ui.ButtonResult = u.buttonBehavior(rect, id,.{});
    ///     // draw using r.hovered / r.held / r.pressed
    pub fn buttonBehavior(
        self: Ui,
        rect: Rectangle,
        id: Id,
        opts: ButtonBehaviorOpts,
    ) ButtonResult {
        const ctx: *UiContext = self.ctx;
        const hovered: bool = itemHoverable(ctx, rect);
        var pressed: bool = false;
        var just_activated: bool = false;
        var just_deactivated: bool = false;

        // Mouse-down inside rect → claim active_id.
        if (hovered and ctx.input.mouse_left_clicked) {
            ctx.active_id = id;
            ctx.active_id_just_activated = true;
            ctx.active_id_press_time = ctx.frame_time_seconds;
            ctx.active_id_last_repeat_time = ctx.frame_time_seconds;
            just_activated = true;
        }
        // Mouse-up while we own active_id → fire pressed if still
        // hovered; release the claim either way.
        if (ctx.active_id == id and ctx.input.mouse_left_released) {
            if (hovered) {
                pressed = true;
            }
            ctx.active_id = 0;
            just_deactivated = true;
        }
        // Repeat: 400ms delay, then 50ms cadence. Held = active_id
        // is us AND mouse-down AND cursor still over us.
        if (opts.repeat and ctx.active_id == id and
            ctx.input.mouse_left_down and hovered)
        {
            const REPEAT_DELAY: f32 = 0.4;
            const REPEAT_RATE: f32 = 0.05;
            const since_press: f32 = ctx.frame_time_seconds - ctx.active_id_press_time;
            if (since_press >= REPEAT_DELAY) {
                const since_last: f32 = ctx.frame_time_seconds - ctx.active_id_last_repeat_time;
                if (since_last >= REPEAT_RATE) {
                    pressed = true;
                    ctx.active_id_last_repeat_time = ctx.frame_time_seconds;
                }
            }
        }
        // keyboard nav: Enter on focused item fires pressed.
        if (triggerNavActivate(ctx, id)) {
            pressed = true;
        }

        return .{
            .pressed = pressed,
            .hovered = hovered,
            .held = ctx.active_id == id,
            .just_activated = just_activated,
            .just_deactivated = just_deactivated,
        };
    }

    /// Override one or more style fields for a scope. Returns a
    /// `StyleGuard` that restores the prior values when
    /// `g.restore()` is called. Use with `defer`:
    ///
    ///     const g = u.styleOverride(.{.text = my_red });
    ///     defer g.restore();
    ///     u.text("warning",.{});
    ///
    /// Only the fields you set on `overrides` are touched — null
    /// fields leave the live style alone. Nesting is safe: each
    /// guard saves the value live at the time IT ran, so multiple
    /// stacked overrides restore correctly in defer-stack order.
    pub fn styleOverride(self: Ui, overrides: PartialStyle) StyleGuard {
        var saved: PartialStyle = .{};
        inline for (@typeInfo(Style).@"struct".field_names) |f_name| {
            if (@field(overrides, f_name)) |new_val| {
                // Capture prior, apply new.
                @field(saved, f_name) = @field(self.ctx.style, f_name);
                @field(self.ctx.style, f_name) = new_val;
            }
        }
        return .{ .ctx = self.ctx, .saved = saved };
    }

    // A canvas is a rectangular sub-region of the current window
    // with its own clip rect. Caller draws through a
    // `DrawListHandle` that's pre-bracketed with push_clip /
    // pop_clip, so anything drawn lands scissored to the canvas
    // bounds.
    //

    // Pattern:
    //     if (u.beginCanvas("graph",.{ 400, 300 },.{})) |c| {
    //         defer u.endCanvas(c);
    //         c.drawList().addCircleFilled(.{ 200, 150 }, 50, 0xFFFF0000);
    //         // mouse position in the canvas's authoring space:
    //         const lm = c.localMouse();
    //     }
    //

    // The canvas's draws go on the SAME parent-window drawlist,
    // scissored. No separate DrawList struct, no channel-pair
    // splitter. If z-order control becomes a real need, channels
    // can wrap on top later without disturbing this surface.

    /// Options for `beginCanvas`. Empty for now; the transform
    /// stack is push/popped imperatively via
    /// `CanvasCtx.pushTransform` rather than passed in at begin.
    pub const CanvasOpts = struct {
        /// Padding field — Zig disallows zero-field structs in
        /// some positional contexts. Remove when the struct
        /// gains a real field.
        _: u1 = 0,
    };

    /// Live state of an active canvas scope. Returned by
    /// `beginCanvas` when the canvas is visible; pass to
    /// `endCanvas` to close out. Field access is the canvas's
    /// public surface — see method docs.
    pub const CanvasCtx = struct {
        ctx: *UiContext,
        /// Window the canvas was opened inside; used by endCanvas
        /// to find the drawlist to pop_clip on.
        window: *Window,
        /// Screen-space rectangle the canvas occupies. Cached so
        /// `localMouse()` doesn't re-resolve it.
        rect: Rectangle,
        /// Canvas ID (hashStr of the label). Same shape every
        /// other widget uses for state-keyed lookup.
        id: Id,
        /// Depth of the canvas_transforms stack at begin time.
        /// `endCanvas` truncates back to this depth — guards
        /// against caller-side push-without-pop.
        transform_depth_at_begin: usize,

        /// Get a `DrawListHandle` for this canvas's draws. The
        /// handle wraps the parent window's drawlist; commands
        /// recorded through it are bracketed by the push_clip
        /// already emitted at begin time, so they're scissored
        /// to the canvas bounds at render time.
        pub fn drawList(self: CanvasCtx) DrawListHandle {
            return .{
                .list = &self.window.draw_list,
                .gpa = self.ctx.frame_arena.allocator(),
            };
        }

        /// Mouse position in canvas authoring space. Subtracts
        /// the canvas's screen origin to get canvas-local coords,
        /// then applies the INVERSE of the current cumulative
        /// transform so callers always read coordinates in their
        /// authoring frame — whatever pushTransform layers have
        /// been added.
        ///
        /// With no transforms pushed, the inverse is identity, so
        /// this is `screen_mouse - rect.{x,y}` (matching the
        /// 422 MVP behavior).
        pub fn localMouse(self: CanvasCtx) Vec2 {
            const m: Vec2 = self.ctx.input.mouse_pos;
            const in_canvas: Vec2 = .{ m[0] - self.rect.x, m[1] - self.rect.y };
            const cur: ?CanvasTransform = self.ctx.canvas_transforms.top();
            if (cur) |t| {
                return t.inverse().applyLocal(in_canvas);
            }
            return in_canvas;
        }

        /// Push a translate+scale transform onto the canvas's
        /// transform stack. Subsequent `localMouse` calls will
        /// see coordinates in the post-transform authoring space.
        /// The stack composes — pushing (t1, s1) then (t2, s2)
        /// gives a top of `compose(parent={t1,s1}, child={t2,s2})`,
        /// so the math behaves exactly like nested coordinate
        /// systems. Pair with `popTransform()` — typically via
        /// `defer c.popTransform()`.
        ///
        /// Returns silently on overflow (stack capped at 16
        /// entries); a deeper nest is almost certainly a bug.
        pub fn pushTransform(
            self: CanvasCtx,
            translate: Vec2,
            scale: Vec2,
        ) void {
            const new_local: CanvasTransform = .{ .translate = translate, .scale = scale };
            const composed: CanvasTransform = if (self.ctx.canvas_transforms.top()) |parent|
                parent.compose(new_local)
            else
                new_local;
            self.ctx.canvas_transforms.append(composed) catch return;
        }

        /// Pop the most recently pushed transform. No-op when
        /// the stack is empty (safer than a panic since it lets
        /// stray pops in error paths still compile).
        pub fn popTransform(self: CanvasCtx) void {
            _ = self.ctx.canvas_transforms.pop();
        }

        /// Get the cumulative current transform. Returns identity
        /// when nothing has been pushed. This is the transform
        /// from authoring-space to CANVAS-LOCAL space (i.e. relative
        /// to the canvas top-left, NOT screen coords). Most callers
        /// want `toScreen()` instead, which composes this with the
        /// canvas-origin translation.
        pub fn currentTransform(self: CanvasCtx) CanvasTransform {
            return self.ctx.canvas_transforms.top() orelse .{};
        }

        /// Project an authoring-space point to SCREEN coords —
        /// suitable for handing to `drawList().add*()` calls.
        /// Applies the cumulative transform AND the canvas-origin
        /// offset, so the inverse of `localMouse()`:
        ///   `toScreen(localMouse()) == ctx.input.mouse_pos`.
        /// Use this for any geometry you compute in authoring space
        /// and want to draw — addRectFilled, addBezierCubic, etc.
        /// take screen coords (the drawlist is the parent window's,
        /// not a canvas-local one — see ADR Q4).
        pub fn toScreen(self: CanvasCtx, p: Vec2) Vec2 {
            const xf: CanvasTransform = self.currentTransform();
            const local: Vec2 = xf.applyLocal(p);
            return .{ local[0] + self.rect.x, local[1] + self.rect.y };
        }

        /// True when the mouse is within the canvas's clip rect
        /// AND the canvas's parent window is the topmost window
        /// at the mouse position (i.e. no popup, tooltip, or
        /// other window is covering the canvas at the mouse).
        /// The window-id check is what distinguishes "mouse-in-rect"
        /// from "this canvas owns the hover" — a popup drawn over
        /// the canvas claims the topmost window without disturbing
        /// the canvas's rect.
        pub fn hovered(self: CanvasCtx) bool {
            if (!pointInRect(self.ctx.input.mouse_pos, self.rect)) {
                return false;
            }
            return self.ctx.hovered_window_id == self.window.id;
        }
    };

    /// Open a canvas scope. Returns null when the canvas is
    /// clipped entirely outside the current window's content area
    /// (so the caller can skip the canvas body entirely). When
    /// non-null, the caller MUST pair with `endCanvas` — typically
    /// via `defer`.
    pub fn beginCanvas(
        self: Ui,
        label: []const u8,
        size: Vec2,
        opts: CanvasOpts,
    ) ?CanvasCtx {
        _ = opts;
        const w: *Window = self.ctx.current_window orelse return null;
        const id: Id = widgetId(self.ctx, w, label);

        // Place at current cursor.
        const at: Vec2 = resolveCursor(w, self.ctx.style.item_spacing[0]);
        const rect: Rectangle = .{
            .x = at[0],
            .y = at[1],
            .width = size[0],
            .height = size[1],
        };

        // Layout: claim the cursor space immediately (so subsequent
        // sibling widgets land below the canvas).
        advanceLayout(w, size, self.ctx.style.item_spacing, 0);

        // Clip: skip entirely if outside window bounds.
        if (!self.itemAdd(rect, id)) {
            return null;
        }

        // Push the clip rect onto the window's drawlist. Anything
        // recorded through `c.drawList()` between now and
        // `endCanvas` will be scissored.
        w.draw_list.pushClipRect(self.ctx.frame_arena.allocator(), rect);

        return .{
            .ctx = self.ctx,
            .window = w,
            .rect = rect,
            .id = id,
            .transform_depth_at_begin = self.ctx.canvas_transforms.len,
        };
    }

    /// Close a canvas scope. Pops the clip rect that `beginCanvas`
    /// pushed, and truncates the transform stack back to its
    /// depth at begin time (so any pushTransforms the caller
    /// forgot to pop don't leak to the next canvas). Safe to
    /// call exactly once per matching begin.
    pub fn endCanvas(self: Ui, c: CanvasCtx) void {
        _ = self;
        // Restore transform-stack depth — defensive cleanup for
        // callers who pushed but didn't pop. In well-behaved code
        // this is a no-op.
        c.ctx.canvas_transforms.len = c.transform_depth_at_begin;
        c.window.draw_list.popClipRect(c.ctx.frame_arena.allocator());
    }

    // ========================================================================
    // Animation primitives
    // ========================================================================
    //
    // Two flavors of motion, both keyed by a stable label string:
    //
    //   `u.animated(label, opts)` — one-shot tween from `from` to
    //       `to` over `duration` seconds.  Restarts if `to` changes.
    //
    //   `u.spring(label, opts)` — physical spring following
    //       `target`. Tracks `target` smoothly as it moves between
    //       frames.  Critically-damped by default (no overshoot).
    //
    // Both return the current value to plug into a draw call:
    //
    //     const alpha = u.animated("fade", .{
    //         .from = 0, .to = 1, .duration = 0.3, .easing = .ease_out,
    //     });
    //     u.fillRect(rect, .{ .r = 255, .g = 0, .b = 0, .a = @trunc(alpha * 255) });
    //
    // State lives in `ext_storage` via `getOrPutState`, so it
    // gets persistence for free if a caller opts in — though
    // animations rarely want that.

    /// One-shot tween.  Returns the current interpolated value.
    /// Reads `ctx.input.delta_time` to advance the slot.
    ///
    /// If `opts.to` differs from the previous frame's `to`, the
    /// tween restarts — useful for "snap to a new target" patterns.
    pub fn animated(
        self: Ui,
        label: []const u8,
        opts: AnimatedOpts,
    ) f32 {
        const ctx: *UiContext = self.ctx;
        const id: Id = hashStr(0, label);
        const r = self.getOrPutState(TweenSlot, id, .{});
        if (!r.found_existing) {
            r.value_ptr.* = .{};
        }
        const s: *TweenSlot = r.value_ptr;

        // Detect a target change.  On the first frame the slot is
        // fresh (seeded == false); just remember `to` and start.
        if (!s.seeded) {
            s.last_to = opts.to;
            s.seeded = true;
        } else if (s.last_to != opts.to) {
            s.elapsed = 0;
            s.last_to = opts.to;
        }

        s.elapsed += ctx.input.delta_time;

        // Delay phase: hold at `from`.
        if (s.elapsed < opts.delay) {
            return opts.from;
        }
        if (opts.duration <= 0) {
            // Degenerate duration — snap to `to`.
            return opts.to;
        }
        const since_motion: f32 = s.elapsed - opts.delay;
        if (since_motion >= opts.duration) {
            return opts.to;
        }
        const t: f32 = since_motion / opts.duration;
        const eased: f32 = applyEasing(opts.easing, t);
        return opts.from + (opts.to - opts.from) * eased;
    }

    /// Physical spring following `opts.target`.  Returns the
    /// current value.  Each call advances the spring by one
    /// `delta_time` step using semi-implicit Euler integration.
    ///
    /// Pass a new `opts.target` each frame; the spring smoothly
    /// follows.  At rest, the call is cheap (zero work beyond a
    /// settle test).
    pub fn spring(
        self: Ui,
        label: []const u8,
        opts: SpringOpts,
    ) f32 {
        const ctx: *UiContext = self.ctx;
        const id: Id = hashStr(0, label);
        const r = self.getOrPutState(SpringSlot, id, .{});
        if (!r.found_existing) {
            r.value_ptr.* = .{};
        }
        const s: *SpringSlot = r.value_ptr;

        if (!s.seeded) {
            s.value = opts.initial;
            s.velocity = 0;
            s.seeded = true;
        }

        // Semi-implicit Euler step for a damped harmonic
        // oscillator:  v += (-k * (x - target) - c * v) * dt
        //              x += v * dt
        // where k = stiffness, c = 2 * damping * sqrt(k).  The
        // factor of two-sqrt-k makes `damping = 1.0` mean
        // critical damping (textbook definition).
        const dt: f32 = ctx.input.delta_time;
        const k: f32 = opts.stiffness;
        const c: f32 = 2.0 * opts.damping * @sqrt(k);
        const dx: f32 = s.value - opts.target;
        const accel: f32 = -k * dx - c * s.velocity;
        s.velocity += accel * dt;
        s.value += s.velocity * dt;

        // Settle: when velocity AND offset-from-target are both
        // negligible relative to the target's magnitude, snap
        // exactly to target and zero velocity.  Avoids perpetual
        // sub-pixel jitter and lets callers branch on "spring at
        // rest" via `value == target`.  The threshold scales with
        // |target| so springs that track large numerical ranges
        // (e.g. pixel coords in the hundreds-of-pixels regime)
        // settle as readily as small ones.
        const settle_scale: f32 = @max(@abs(opts.target), 1.0);
        const SETTLE_REL: f32 = 0.001;
        if (@abs(s.velocity) < SETTLE_REL * settle_scale and
            @abs(dx) < SETTLE_REL * settle_scale)
        {
            s.value = opts.target;
            s.velocity = 0;
        }

        return s.value;
    }

    // ========================================================================
    // miniPlot — throwaway smoke test for the architectural pillars
    // ========================================================================
    //
    // **Will be deleted when real `beginPlot` lands** (planned Tier 4).
    // The point of this stub is to find integration bugs between the
    // canvas / arcs / state / style / input / animation pillars NOW,
    // while the cost of fixing them is small.  A real plot stack is
    // 30+ turns of work; an integration bug in one of the underlying
    // primitives is much cheaper to fix in isolation than threaded
    // through that whole stack.
    //
    // Pillars touched, in order:
    //   - canvas (the plot draws inside `beginCanvas` / `endCanvas`)
    //   - getOrPutState (caches the auto-fit Y limits per label)
    //   - styleOverride (pushes plot-specific bg + grid color)
    //   - isKeyPressed (R resets auto-fit)
    //   - spring (animates limits when they change between frames)
    //   - addPolyline + addCircleFilled + addArc (the actual draw)

    /// Single-line plot in a canvas-clipped rectangle.  No axes,
    /// no title, no markers beyond a "latest value" dot — just
    /// enough to verify the pillars compose.  `xs` and `ys` must
    /// be the same length; `xs` must be monotonic ascending for
    /// the line to render sensibly (not enforced).
    ///
    /// Returns `true` if the user pressed R while the plot was
    /// hovered (a courtesy signal — most callers ignore it).
    pub fn miniPlot(
        self: Ui,
        label: []const u8,
        rect: Rectangle,
        xs: []const f32,
        ys: []const f32,
    ) bool {
        if (xs.len == 0 or xs.len != ys.len) {
            return false;
        }

        // Q5: scope a style override for the plot's own colors.
        // The plot looks "different" from the rest of the window
        // (darker bg, brighter grid) without persistent state.
        const guard: StyleGuard = self.styleOverride(.{
            .frame_bg = .{ .r = 8, .g = 10, .b = 16, .a = 255 },
            .border = .{ .r = 40, .g = 60, .b = 90, .a = 255 },
        });
        defer guard.restore();

        // Q2: per-label slot for auto-fit + animation targets.
        const id: Id = hashStr(0, label);
        const r = self.getOrPutState(MiniPlotSlot, id, .{});
        if (!r.found_existing) {
            r.value_ptr.* = .{};
        }
        const slot: *MiniPlotSlot = r.value_ptr;

        // Q1: R-key resets the auto-fit so the next frame recomputes.
        // We could check hover, but for a smoke test global is fine.
        var r_pressed: bool = false;
        if (self.isKeyPressed(.r)) {
            slot.fitted = false;
            r_pressed = true;
        }

        // Auto-fit on first frame or after a reset.  10% padding
        // so the line doesn't kiss the edges.
        if (!slot.fitted) {
            var lo: f32 = ys[0];
            var hi: f32 = ys[0];
            for (ys) |y| {
                if (y < lo) {
                    lo = y;
                }
                if (y > hi) {
                    hi = y;
                }
            }
            const pad: f32 = @max((hi - lo) * 0.1, 0.001);
            slot.targetMin = lo - pad;
            slot.targetMax = hi + pad;
            slot.fitted = true;
        }

        // Q9: spring the live limits toward their targets.  When
        // `ys` changes shape and the targets move, the animated
        // values lag and produce a smooth zoom.  Two distinct
        // labels so the springs don't share state.
        const cur_min: f32 = self.spring("miniplot_min", .{
            .target = slot.targetMin,
            .initial = slot.targetMin,
        });
        const cur_max: f32 = self.spring("miniplot_max", .{
            .target = slot.targetMax,
            .initial = slot.targetMax,
        });

        // Q4: a canvas hosts the actual draws.  Coords are
        // window-relative; we use the canvas's drawList handle.
        if (self.beginCanvas(label, .{ rect.width, rect.height }, .{})) |c| {
            defer self.endCanvas(c);

            const dl: DrawListHandle = c.drawList();
            // Background.
            dl.addRectFilled(
                .{ .x = 0, .y = 0, .width = rect.width, .height = rect.height },
                self.ctx.style.frame_bg,
            );

            // A few horizontal grid lines — three rows.
            var i: u32 = 1;
            while (i < 4) : (i += 1) {
                const fy: f32 = (float(i) / 4.0) * rect.height;
                dl.addLine(
                    .{ 0, fy },
                    .{ rect.width, fy },
                    self.ctx.style.border,
                    1,
                );
            }

            // Map xs/ys → screen rect.  X spans the full width
            // proportional to position in the array; Y maps from
            // [cur_min, cur_max] flipped (top = max).
            const span: f32 = cur_max - cur_min;
            const safe_span: f32 = if (span > 1e-6) span else 1;
            const points: []Vec2 = self.ctx.frame_arena.allocator().alloc(Vec2, ys.len) catch return r_pressed;
            for (ys, 0..) |y, k| {
                const fx: f32 = (float(k) / float(ys.len - 1)) * rect.width;
                const fy: f32 = rect.height - ((y - cur_min) / safe_span) * rect.height;
                points[k] = .{ fx, fy };
            }
            dl.addPolyline(points, Color.fromWire(0xFF6DB0E0), 1.5, false);

            // Latest-value dot + a small arc behind it as an
            // exercise for Q7's arc primitives.
            if (ys.len >= 1) {
                const last: Vec2 = points[points.len - 1];
                dl.addArcFilled(last, 6, 0, tau, Color.fromWire(0x402090F0));
                dl.addCircleFilled(last, 3, Color.fromWire(0xFFF0F4FA));
            }
        }

        return r_pressed;
    }

    /// Options for `beginItem`. Caller specifies a `size` and the
    /// helper handles ID hashing, cursor placement, rect
    /// computation, clip-test, hovered-id update, AND the
    /// button-behavior state machine in one call. The single-call
    /// surface is for "I just want to write a widget and be done"
    /// — for fine-grained control (custom hit shapes, multi-rect
    /// widgets, non-button interaction patterns), reach for the
    /// B-path primitives (`itemAdd`/`buttonBehavior`) directly.
    pub const ItemOpts = struct {
        /// Widget size in pixels. Caller computes this from
        /// content (text width + padding etc). No "auto-size from
        /// label" today — the label is for the ID, not for sizing.
        size: Vec2,
        /// Same as `ButtonBehaviorOpts.repeat`. Default off.
        repeat: bool = false,
    };

    /// Result of `beginItem`. Same field set as `ButtonResult`
    /// plus `id` and `rect`. `null` from beginItem means the rect
    /// was fully clipped — caller skips drawing entirely.
    pub const ItemCtx = struct {
        id: Id,
        rect: Rectangle,
        pressed: bool,
        hovered: bool,
        held: bool,
        just_activated: bool,
        just_deactivated: bool,
    };

    /// Single-call widget primitive. Composes `widgetId` +
    /// `resolveCursor` + `itemAdd` + `buttonBehavior` into one
    /// "do all the boilerplate" call. Returns `null` if the
    /// widget's rect is fully outside the window (caller skips
    /// drawing); otherwise returns the full state needed to draw
    /// + react.
    ///
    /// Pair with `endItem(ctx)` (which calls `itemSize`). Use
    /// `defer` to make pairing mistake-proof:
    ///
    ///     if (u.beginItem("knob",.{.size =.{ 40, 40 } })) |it| {
    ///         defer u.endItem(it);
    ///         // draw using it.hovered / it.held / it.rect
    ///         return it.pressed;
    ///     }
    ///
    /// Imgui has no canonical equivalent — its widgets reimplement
    /// the boilerplate inline. Q3's two-path design (B for
    /// imgui-style + C for opinionated) gives extension authors
    /// the choice; C is the recommended starting point.
    pub fn beginItem(
        self: Ui,
        label: []const u8,
        opts: ItemOpts,
    ) ?ItemCtx {
        const w: *Window = self.ctx.current_window orelse return null;
        const id: Id = widgetId(self.ctx, w, label);
        const at: Vec2 = resolveCursor(w, self.ctx.style.item_spacing[0]);
        const rect: Rectangle = .{
            .x = at[0],
            .y = at[1],
            .width = opts.size[0],
            .height = opts.size[1],
        };
        if (!self.itemAdd(rect, id)) {
            // Still advance the cursor on clipped items — matches
            // imgui semantics so subsequent widgets land in the
            // expected position regardless of clipping.
            self.itemSize(opts.size);
            return null;
        }
        const r: ButtonResult = self.buttonBehavior(rect, id, .{ .repeat = opts.repeat });
        return .{
            .id = id,
            .rect = rect,
            .pressed = r.pressed,
            .hovered = r.hovered,
            .held = r.held,
            .just_activated = r.just_activated,
            .just_deactivated = r.just_deactivated,
        };
    }

    /// Pair with `beginItem`. Advances the layout cursor by the
    /// item's size. Pass the `ItemCtx` returned from `beginItem`
    /// so the helper has the rect — and so a mistakenly-called
    /// `endItem` without a matching `beginItem` is a compile
    /// error (no ItemCtx in scope).
    pub fn endItem(self: Ui, it: ItemCtx) void {
        self.itemSize(.{ it.rect.width, it.rect.height });
    }

    pub fn isMouseDragging(
        self: Ui,
        btn: MouseButton,
        lock_threshold: f32,
    ) bool {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return false;
        return runtime.input.isMouseDragging(s, btn, lock_threshold);
    }

    /// Cursor displacement since the most recent press of `button`,
    /// or `(0, 0)` if the button isn't held / threshold not yet crossed.
    /// Threshold semantics match `isMouseDragging` - pass `-1` for
    /// the imgui default.
    pub fn getMouseDragDelta(
        self: Ui,
        btn: MouseButton,
        lock_threshold: f32,
    ) Vec2 {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return .{ 0, 0 };
        const v: Vec2 = runtime.input.getMouseDragDelta(s, btn, lock_threshold);
        return .{ v[0], v[1] };
    }

    /// Reset the drag anchor for `button` to the current cursor
    /// position - subsequent `getMouseDragDelta` calls start fresh
    /// from here. Idiomatic for incremental drag handlers that
    /// consume the delta each frame.
    pub fn resetMouseDragDelta(self: Ui, btn: MouseButton) void {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return;
        runtime.input.resetMouseDragDelta(s, btn);
    }

    /// Current mouse position in screen pixels (same coordinate space as
    /// widget draw calls). Off-screen sentinel when there is no pointer.
    /// Used by custom widgets that need the raw cursor for hit-testing or
    /// zoom-around-cursor (e.g. the plot widget's wheel zoom).
    pub fn getMousePos(self: Ui) Vec2 {
        return self.ctx.input.mouse_pos;
    }

    /// Vertical mouse-wheel delta accumulated this frame. Positive =
    /// wheel rolled away from the user / scroll up. Zero when idle.
    pub fn getMouseWheel(self: Ui) f32 {
        return self.ctx.input.mouse_wheel_y;
    }

    /// Number of active touch points this frame (0 on a mouse-only
    /// device, 1 for a single finger, 2 during a pinch/two-finger
    /// gesture). Each browser pointer is fed in by `pointerId`, so this
    /// reflects real multi-touch on the web.
    pub fn getTouchPointCount(self: Ui) i32 {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return 0;
        return runtime.input.getTouchPointCount(s);
    }

    /// Screen position of the `index`-th active touch point, or the
    /// off-screen origin if there is no such touch.
    pub fn getTouchPos(self: Ui, index: usize) Vec2 {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return @splat(0);
        return runtime.input.getTouchPosition(s, @intCast(index));
    }

    /// This frame's pinch gesture, off the shared detector ticked in
    /// `beginFrameRaw`. `scale` is the frame-to-frame finger-distance
    /// ratio (>1 spreading / zoom in, <1 closing, 1.0 = no pinch — a
    /// no-op factor), `mid` the focal point to hold fixed while zooming.
    /// Widgets apply it to their own view; the detection is shared with
    /// every other pinch-zoom surface (fractals, 3D camera, ...).
    pub fn pinch(self: Ui) Pinch {
        return .{
            .scale = runtime.gestures.getGesturePinchScale(&self.ctx.gestures),
            .mid = runtime.gestures.getGesturePinchMid(&self.ctx.gestures),
        };
    }

    /// The gesture classified this frame by the shared detector (e.g.
    /// `.doubletap`, `.hold`, `.swipe_left`). `.none` when nothing fired.
    pub fn gesture(self: Ui) Gesture {
        return runtime.gestures.getGestureDetected(&self.ctx.gestures);
    }

    /// True if the current mouse position is inside the axis-aligned
    /// rectangle `(x0..x1, y0..y1)`. Edges are inclusive on near
    /// side, exclusive on far side (imgui semantics - half-open
    /// intervals so adjacent rects don't double-count). Coordinates
    /// are in the same space as the widget's draw calls.
    pub fn isMouseHoveringRect(
        self: Ui,
        x0: f32,
        y0: f32,
        x1: f32,
        y1: f32,
    ) bool {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return false;
        return runtime.input.isMouseHoveringRect(s, x0, y0, x1, y1);
    }

    // ---- Keyboard shortcuts (Phase B2)
    /// True if `chord` fires this frame. Edge-triggered on the key,
    /// level-triggered on modifiers. Pairs with conditional drawing
    /// to attach hotkey behavior to specific UI states:
    ///     if (ui.shortcut(.{.key =.s,.ctrl = true },.{})) save();
    ///     if (ui.shortcut(.{.key =.escape },.{})) cancel();
    /// Modifier strictness: Ctrl+S won't fire a bare-S shortcut.
    /// Pass `opts.repeat = true` to also fire on auto-repeat
    /// events (held key). See `runtime.input.KeyChord` and
    /// `ShortcutOpts` for the underlying types.
    pub fn shortcut(
        self: Ui,
        chord: KeyChord,
        opts: ShortcutOpts,
    ) bool {
        const s: *runtime.input.InputState = self.ctx.input_state orelse return false;
        return runtime.input.isKeyChordPressed(s, chord, opts);
    }

    // ---- Drawlist accessors (Phase B3)
    /// Get a handle on the BACKGROUND draw list - renders under all
    /// windows. Use for backdrops, grids, watermarks, debug overlays
    /// that should never occlude widgets.
    ///     const dl = ui.getBackgroundDrawList();
    ///     dl.addRectFilled(.{.x = 0,.y = 0,.width = 800,.height = 600 }, 0xFF1F2937);
    ///     dl.addText("debug",.{ 8, 8 }, 12, 0xFFE2E8F0);
    /// The handle is per-frame: it carries a pointer into the
    /// context's `background_dl` and the frame arena. Don't stash
    /// it across frames - the arena resets at endFrame and the
    /// pointer becomes invalid.
    pub fn getBackgroundDrawList(self: Ui) DrawListHandle {
        return .{
            .list = &self.ctx.background_dl,
            .gpa = self.ctx.frame_arena.allocator(),
        };
    }

    /// Get a handle on the FOREGROUND draw list - renders above all
    /// windows + popups (but below tooltips and drag previews).
    /// Use for watermarks, custom HUDs, debug crosshairs.
    ///     const dl = ui.getForegroundDrawList();
    ///     const red = colorToU32(.{ .r = 239, .g = 68, .b = 68, .a = 255 });
    ///     dl.addText("DEBUG BUILD", .{ 10, 10 }, 14, red);
    /// Colors are ColorU32 (0xAABBGGRR — R is the LOW byte), so prefer
    /// `colorToU32(Color)` over hand-packed hex. Handle is per-frame.
    pub fn getForegroundDrawList(self: Ui) DrawListHandle {
        return .{
            .list = &self.ctx.foreground_dl,
            .gpa = self.ctx.frame_arena.allocator(),
        };
    }

    /// Get a handle on the CURRENT WINDOW's draw list — the same list
    /// built-in widgets render into, so it is clipped to the window's
    /// content rect. Custom widgets that draw window-relative geometry
    /// (via beginItem/endItem) should use THIS rather than the
    /// foreground list, so their output is clipped to the window instead
    /// of spilling past its edges. Falls back to the foreground list
    /// when no window is current. Per-frame handle (arena-backed).
    pub fn getWindowDrawList(self: Ui) DrawListHandle {
        return .{
            .list = self.ctx.current_draw_list orelse &self.ctx.foreground_dl,
            .gpa = self.ctx.frame_arena.allocator(),
        };
    }

    /// Convenience: draw a filled rectangle on the current window's
    /// draw list using the `Color` struct (not the packed `ColorU32`
    /// the underlying DrawList takes). Equivalent to
    /// `u.getForegroundDrawList().addRectFilled(rect, colorToU32(c))`
    /// but shorter at the call site — extension widgets that want
    /// to paint inside their own rect reach for this constantly.
    /// No-op if no window is currently open.
    /// Convenience: draw a filled rectangle on the current window's
    /// draw list using the `Color` struct (not the packed `ColorU32`
    /// the underlying DrawList takes). Equivalent to
    /// `u.getForegroundDrawList().addRectFilled(rect, colorToU32(c))`
    /// but shorter at the call site — extension widgets that want
    /// to paint inside their own rect reach for this constantly.
    /// No-op if no window is currently open.
    pub fn fillRect(
        self: Ui,
        rect: Rectangle,
        c: Color,
    ) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.draw_list.addRectFilled(self.ctx.frame_arena.allocator(), rect, Color.toWire(c));
    }

    /// Convenience: stroked rectangle outline. See `fillRect`.
    pub fn strokeRect(
        self: Ui,
        rect: Rectangle,
        c: Color,
    ) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.draw_list.addRectOutline(self.ctx.frame_arena.allocator(), rect, Color.toWire(c));
    }

    // ---- item state queries
    /// True if the user is currently interacting with the most-
    /// recently-submitted widget (e.g. a slider being dragged, a
    /// button being held). raylib parity: `IsItemActive`.
    pub fn isItemActive(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_id != 0 and self.ctx.active_id == w.layout.last_item_id;
    }

    /// True if the most-recent widget became active this frame
    /// (transition from inactive → active). ImGui: `IsItemActivated`.
    pub fn isItemActivated(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_activated;
    }

    /// True if the most-recent widget transitioned from active → inactive
    /// this frame. ImGui: `IsItemDeactivated`.
    pub fn isItemDeactivated(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_deactivated;
    }

    /// True if the most-recent widget transitioned from active →
    /// inactive this frame AND the user edited its value at any point
    /// during the activation. Useful for "commit on release" patterns.
    /// ImGui: `IsItemDeactivatedAfterEdit`.
    pub fn isItemDeactivatedAfterEdit(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_deactivated_after_edit;
    }

    /// True if the user mutated the most-recent widget's value this
    /// frame (slider drag, checkbox toggle, inputText keystroke).
    /// ImGui: `IsItemEdited`.
    pub fn isItemEdited(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_edited;
    }

    /// True if the user clicked the most-recent widget this frame
    /// (mouse-down inside its rect on the same frame the click
    /// register). raylib parity: `IsItemClicked` (mouse button 0).
    pub fn isItemClicked(self: Ui) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        return w.layout.last_item_clicked;
    }

    /// True if the most-recent widget is currently keyboard-focused.
    /// Equivalent to `isItemActive` since there's no keyboard nav.
    pub fn isItemFocused(self: Ui) bool {
        return self.isItemActive();
    }

    /// Top-left of the most-recent widget's rectangle (screen px).
    /// raylib parity: `GetItemRectMin`.
    pub fn getItemRectMin(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return .{ w.layout.last_item_rect.x, w.layout.last_item_rect.y };
    }

    /// Bottom-right of the most-recent widget's rectangle (screen px).
    pub fn getItemRectMax(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return .{
            w.layout.last_item_rect.x + w.layout.last_item_rect.width,
            w.layout.last_item_rect.y + w.layout.last_item_rect.height,
        };
    }

    /// Width × height of the most-recent widget. ImGui: `GetItemRectSize`.
    pub fn getItemRectSize(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return .{ w.layout.last_item_rect.width, w.layout.last_item_rect.height };
    }

    /// Hashed ID of the most-recent widget (0 if none). Useful for
    /// debug + custom hover/active dispatch.
    pub fn getItemID(self: Ui) Id {
        const w: *Window = self.ctx.current_window orelse return 0;
        return w.layout.last_item_id;
    }

    // ---- setNextWindow* + window-state queries
    /// Set the position the next `window(...)` call applies. Default
    /// is "every frame" (matches ImGui's `ImGuiCond_Always`); pass
    /// `.{.once = true }` to apply only on first creation.
    /// ImGui: `SetNextWindowPos(pos, cond)`.
    pub fn setNextWindowPos(
        self: Ui,
        pos: Vec2,
        opts: SetNextWindowOpts,
    ) void {
        self.ctx.next_window_pos = pos;
        self.ctx.next_window_pos_always = !opts.once;
    }

    /// Set the size the next `window(...)` call applies. See
    /// `setNextWindowPos` for the once-vs-always distinction.
    /// ImGui: `SetNextWindowSize(size, cond)`.
    /// Size the next window.
    ///
    /// ★ A ZERO COMPONENT MEANS "FIT THE CONTENT ON THAT AXIS", matching Dear ImGui's
    /// `SetNextWindowSize`. Passing `.{ 380, 0 }` is the natural way to say "this wide, as
    /// tall as it needs to be", and taking the zero literally produced a window one pixel
    /// tall whose every control was clipped away — a panel that looked like it had simply
    /// failed to render, which is a bad way for a UI toolkit to answer a reasonable request.
    ///
    /// Auto-fit is deferred to the layout: a zero simply leaves that axis unset, so the
    /// window falls through to its content-derived size the same way an unspecified size
    /// does.
    pub fn setNextWindowSize(
        self: Ui,
        size: Vec2,
        opts: SetNextWindowOpts,
    ) void {
        self.ctx.next_window_size = size;
        self.ctx.next_window_size_auto = .{ size[0] == 0, size[1] == 0 };
        self.ctx.next_window_size_always = !opts.once;
    }

    /// Constrain the next window's size to `[min, max]` on its
    /// next open + every subsequent frame. Either bound can be
    /// `null` for "no limit". Useful for chrome-bounded windows
    /// (e.g. "this window must be at least 300×200 so its
    /// content fits").
    /// Constraints are also applied to user drag-resize gestures
    /// - the window simply can't grow/shrink past the bounds.
    /// Imgui: `SetNextWindowSizeConstraints` (`imgui.cpp:8664`).
    /// Imgui's custom-callback variant (for non-rectangular
    /// constraints) is deferred - see Step 1.x followup.
    pub fn setNextWindowSizeConstraints(
        self: Ui,
        min: ?Vec2,
        max: ?Vec2,
    ) void {
        self.ctx.next_window_size_min = min;
        self.ctx.next_window_size_max = max;
    }

    /// Set the position of an existing top-level window by name.
    /// No-op if no window with that name has been opened yet
    /// (matches imgui's `SetWindowPos(name,...)` which silently
    /// no-ops on FindWindowByName failure). Always-semantics
    /// applies unconditionally; ImGui's Cond gating is filed as a
    /// follow-up. Imgui: `imgui.cpp:8540`.
    pub fn setWindowPos(
        self: Ui,
        name: []const u8,
        pos: Vec2,
    ) void {
        const id: Id = hashStr(0, name);
        if (self.ctx.windows.get(id)) |w| {
            w.pos = pos;
        }
    }

    /// Set the size of an existing top-level window by name.
    /// See `setWindowPos` re: no-op when window absent. Marks
    /// `user_resized = true` so the window won't auto-fit growth
    /// after this call. Imgui: `imgui.cpp:8586`.
    pub fn setWindowSize(
        self: Ui,
        name: []const u8,
        size: Vec2,
    ) void {
        const id: Id = hashStr(0, name);
        if (self.ctx.windows.get(id)) |w| {
            w.size = size;
            w.user_resized = true;
        }
    }

    /// Raise an existing top-level window to focused. No-op if
    /// the window doesn't exist. Imgui: `imgui.cpp:12813`.
    pub fn setWindowFocus(self: Ui, name: []const u8) void {
        const id: Id = hashStr(0, name);
        if (self.ctx.windows.get(id)) |_| {
            self.ctx.focused_window_id = id;
        }
    }

    // Note: `setWindowCollapsed(name, bool)` from the plan is
    // deferred - zimr's Window struct doesn't yet have a
    // `collapsed` field nor the title-bar tap-toggle rendering
    // path that would back it. Filed: collapsed-window support
    // is its own multi-piece feature, not just an API addition.

    /// Override the next window's background alpha - 0 = fully
    /// transparent, 1 = opaque. Cleared after the window opens.
    /// ImGui: `SetNextWindowBgAlpha(alpha)`.
    pub fn setNextWindowBgAlpha(self: Ui, alpha: f32) void {
        self.ctx.next_window_bg_alpha = alpha;
    }

    /// Raise the next window to top of z-order on this frame.
    /// ImGui: `SetNextWindowFocus()`.
    pub fn setNextWindowFocus(self: Ui) void {
        self.ctx.next_window_focus = true;
    }

    /// True if the current window has focus, optionally including
    /// children / parents per `FocusedFlags`. Pass `.{}` for the
    /// default "exactly me" semantics; set
    /// `.root_and_child_windows` for "anything in my hierarchy."
    /// - `child_windows`: true if THIS window OR any descendant has
    ///   focus. Walks the focused window's parent chain.
    /// - `root_window`: walk to root of THIS window's parent chain
    ///   before testing.
    /// - `root_window` + `child_windows`: "is anything in my whole
    ///   hierarchy focused?" Docking-relevant combo.
    /// - `any_window`: true if ANY window in `UiContext` has focus.
    /// `no_popup_hierarchy` is accepted but no-op today (popup
    /// hierarchy linkage lands in a later phase). Always-false
    /// outside a window scope. ImGui: `IsWindowFocused(flags)`.
    pub fn isWindowFocused(self: Ui, opts: FocusedFlags) bool {
        const ctx: *UiContext = self.ctx;
        if (opts.any_window) {
            return ctx.focused_window_id != 0;
        }
        const me: *Window = ctx.current_window orelse return false;
        const focused_id: Id = ctx.focused_window_id;
        if (focused_id == 0) {
            return false;
        }
        if (opts.root_window) {
            const root: *Window = rootWindowOf(ctx, me);
            if (opts.child_windows) {
                return isWindowAncestor(ctx, root, focused_id);
            }
            return focused_id == root.id;
        }
        if (opts.child_windows) {
            return isWindowAncestor(ctx, me, focused_id);
        }
        return focused_id == me.id;
    }

    /// True if the mouse is over the current window's outer rect AND
    /// no later (higher-z) window covers that point, optionally
    /// including children / parents per `HoveredFlags`. Pass `.{}`
    /// for the default "exactly me" semantics.
    /// Hierarchy traversal (`child_windows`, `root_window`,
    /// `any_window`, `no_popup_hierarchy`) mirrors
    /// `isWindowFocused`. Implementation specifics:
    /// - `child_windows = true`: the mouse is over me OR any
    ///   descendant. Because children are nested inside the parent's
    ///   outer rect (zimr children don't escape parent bounds
    ///   enforced by the defensive clamp in `beginChildImpl`), this
    ///   is equivalent to `pointInRect(mouse, w.outer_rect)` for
    ///   non-overlapping descendants. For the FULL imgui semantics
    ///   we walk the hovered window's parent chain - handles the
    ///   case where a hovered popup-of-child should count as "child."
    /// The `allow_when_blocked_by_*`, `allow_when_overlapped_by_*`,
    /// `allow_when_disabled`, and `no_nav_override` flags are
    /// accepted but no-op today - see `HoveredFlags` field
    /// docstrings for when each lands.
    /// ImGui: `IsWindowHovered(flags)`.
    pub fn isWindowHovered(self: Ui, opts: HoveredFlags) bool {
        const ctx: *UiContext = self.ctx;
        if (opts.any_window) {
            return ctx.hovered_window_id != 0;
        }
        const me: *Window = ctx.current_window orelse return false;
        const hovered_id: Id = ctx.hovered_window_id;
        if (hovered_id == 0) {
            return false;
        }
        if (opts.root_window) {
            const root: *Window = rootWindowOf(ctx, me);
            if (opts.child_windows) {
                return isWindowAncestor(ctx, root, hovered_id);
            }
            return hovered_id == root.id;
        }
        if (opts.child_windows) {
            return isWindowAncestor(ctx, me, hovered_id);
        }
        return hovered_id == me.id;
    }

    /// Position of the current window's top-left in screen pixels.
    /// ImGui: `GetWindowPos()`.
    pub fn getWindowPos(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return w.pos;
    }

    /// Outer size of the current window (including title bar) in
    /// pixels. ImGui: `GetWindowSize()`.
    pub fn getWindowSize(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return w.size;
    }

    /// Width of the current window in pixels. Shortcut for
    /// `getWindowSize()[0]`.
    pub fn getWindowWidth(self: Ui) f32 {
        return self.getWindowSize()[0];
    }

    /// Height of the current window in pixels. Shortcut for
    /// `getWindowSize()[1]`.
    pub fn getWindowHeight(self: Ui) f32 {
        return self.getWindowSize()[1];
    }

    // ---- layout helpers
    /// Override the width of the next widget's primary input element.
    /// Cleared after the next widget consumes it. ImGui:
    /// `SetNextItemWidth(width)`.
    pub fn setNextItemWidth(self: Ui, width: f32) void {
        self.ctx.next_item_width = width;
    }

    /// Push an item width onto the stack - every subsequent widget
    /// reads it as their preferred width until popped. Stacks, so
    /// nested `pushItemWidth` calls compose. ImGui:
    /// `PushItemWidth(width)`.
    pub fn pushItemWidth(self: Ui, width: f32) void {
        self.ctx.item_width_stack.append(width) catch assertUnreachable(@src(), "OOM", .{});
    }

    /// Pop the most-recent `pushItemWidth` value. Symmetric - call
    /// exactly once per push. ImGui: `PopItemWidth()`.
    pub fn popItemWidth(self: Ui) void {
        _ = self.ctx.item_width_stack.pop();
    }

    /// Available content region from the current cursor to the right
    /// edge of the window's content area, and from the cursor to the
    /// bottom of the content area. Useful for sizing widgets that
    /// should fill remaining space. ImGui: `GetContentRegionAvail()`.
    pub fn getContentRegionAvail(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        // Use the CURRENT scope's bounds (`work_rect_max`), not the
        // top-level window's edges. When called from inside a
        // nested child, this gives the available space inside THAT
        // child - the right value for auto-sized layouts. Was the
        // companion bug to the spillover bug fixed.
        const cur: Vec2 = resolveCursor(w, self.ctx.style.item_spacing[0]);
        return .{
            @max(0, w.layout.work_rect_max[0] - cur[0]),
            @max(0, w.layout.work_rect_max[1] - cur[1]),
        };
    }

    /// Top-left of the window's content region, in WINDOW-LOCAL
    /// coordinates (relative to the window's top-left corner).
    /// Returns `.{0,0}` when called outside a window block. Matches
    /// ImGui's coordinate convention for this specific getter
    /// (window-local), even though most of zimr's cursor accessors
    /// use screen-space — the "window content region" framing
    /// implies window-local space, and matches what callers expect
    /// for fitting custom layouts into a window.
    /// ImGui: `GetWindowContentRegionMin()`.
    pub fn getWindowContentRegionMin(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return .{
            w.layout.origin[0] - w.pos[0],
            w.layout.origin[1] - w.pos[1],
        };
    }

    /// Bottom-right of the window's content region, in WINDOW-LOCAL
    /// coordinates (relative to the window's top-left corner).
    /// Returns `.{0,0}` when called outside a window block. Pair
    /// with `getWindowContentRegionMin` to compute the full content
    /// rect in window-local space.
    /// ImGui: `GetWindowContentRegionMax()`.
    pub fn getWindowContentRegionMax(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return .{
            w.layout.work_rect_max[0] - w.pos[0],
            w.layout.work_rect_max[1] - w.pos[1],
        };
    }

    /// Reserve a `size`-sized rectangle at the current cursor.
    /// Advances the layout cursor as if a widget that big had been
    /// drawn, and records it as the most-recent item so `isItem*`
    /// queries see a non-zero rect. Useful as a spacer or as a
    /// custom-render placeholder. ImGui: `Dummy(size)`.
    pub fn dummy(self: Ui, size: Vec2) void {
        const w: *Window = self.ctx.current_window orelse return;
        const at: Vec2 = resolveCursor(w, self.ctx.style.item_spacing[0]);
        const rect: Rectangle = .{
            .x = at[0],
            .y = at[1],
            .width = size[0],
            .height = size[1],
        };
        // Dummy is non-interactive; record id=0 so item-state
        // queries return safe defaults.
        w.layout.last_item_id = 0;
        w.layout.last_item_rect = rect;
        w.layout.last_item_hovered = false;
        markItemPost(self.ctx, w, false);
        advanceLayout(
            w,
            size,
            self.ctx.style.item_spacing,
            self.ctx.style.window_padding[0],
        );
    }

    /// Vertically align text to match the baseline of framed widgets
    /// (slider, drag, inputText) on the next line. When you intermix
    /// `text("Speed:")` with `slider(...)` on the same row via
    /// `sameLine`, the bare text otherwise sits flush at the cursor
    /// while the slider's frame extends both above and below - this
    /// padding compensates so the text reads centred-on-frame.
    /// ImGui: `AlignTextToFramePadding()`.
    pub fn alignTextToFramePadding(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        // Push cursor down by the frame's vertical padding so the
        // next text() call's baseline matches a framed widget's.
        w.layout.cursor_pos.y += self.ctx.style.frame_padding.y;
    }

    // ---- disabled scope
    /// Open a "disabled" scope. While the disabled stack is non-empty,
    /// widgets ignore input AND render with reduced alpha (matches
    /// `style.disabled_alpha`). Always pair with `endDisabled()`
    /// `defer` is the right way to spell that. Pass `false` to
    /// open a no-op scope (useful for conditional disabling without
    /// branching at every widget). ImGui: `BeginDisabled(bool disabled)`.
    pub fn beginDisabled(self: Ui, disabled: bool) void {
        // Push the marker first so endDisabled can pop symmetrically
        // regardless of whether THIS scope contributed.
        self.ctx.disabled_marker_stack.append(disabled) catch assertUnreachable(@src(), "OOM", .{});
        if (!disabled) {
            return;
        }
        // Outermost transition - save input + apply alpha + suppress
        // mouse buttons so widgets see "no clicks". Inner scopes
        // just bump the count.
        if (self.ctx.disabled_count == 0) {
            self.ctx.saved_input_when_disabled = self.ctx.input;
            self.ctx.input.mouse_left_clicked = false;
            self.ctx.input.mouse_left_down = false;
            self.ctx.input.mouse_left_released = false;
            self.ctx.input.mouse_right_clicked = false;
            self.ctx.input.mouse_middle_clicked = false;
            // Wheel + position deliberately preserved - users can
            // still scroll a disabled-content panel and hover-tooltips
            // continue to work.
            self.ctx.alpha_mul = self.ctx.style.disabled_alpha;
        }
        self.ctx.disabled_count += 1;
    }

    /// Close the matching `beginDisabled` scope.
    pub fn endDisabled(self: Ui) void {
        const was_disabled: bool = self.ctx.disabled_marker_stack.pop() orelse false;
        if (!was_disabled) {
            return;
        }
        if (self.ctx.disabled_count > 0) {
            self.ctx.disabled_count -= 1;
        }
        // Outermost-pop transition - restore input + alpha.
        if (self.ctx.disabled_count == 0) {
            if (self.ctx.saved_input_when_disabled) |saved| {
                self.ctx.input = saved;
            }
            self.ctx.saved_input_when_disabled = null;
            self.ctx.alpha_mul = 1.0;
        }
    }

    /// True if any active `beginDisabled` scope is currently open.
    /// Widgets check this to gate input + apply the alpha multiplier.
    pub fn isDisabled(self: Ui) bool {
        return self.ctx.disabled_count > 0;
    }

    /// Push an `ItemFlags` scope. Merged with the existing
    /// top-of-stack via `mergeItemFlags` (disabling AND repeating
    /// flags OR; auto_close_popups ANDs - disabling a parent's
    /// auto-close propagates).
    /// Use this for cross-widget behavior toggles. For example:
    ///     ui.pushItemFlag(.{.button_repeat = true });
    ///     defer ui.popItemFlag();
    ///     if (ui.button("+",.{})) increment(); // auto-repeats while held
    /// ImGui: `PushItemFlag(flag, enabled)` / `PopItemFlag()`.
    pub fn pushItemFlag(self: Ui, flags: ItemFlags) void {
        const ctx: *UiContext = self.ctx;
        const parent: ItemFlags = currentItemFlagsImpl(ctx);
        const merged: ItemFlags = mergeItemFlags(parent, flags);
        ctx.item_flags_stack.append(merged) catch assertUnreachable(@src(), "OOM", .{});
        // If this push turned.disabled true and we weren't already
        // disabled, mirror through beginDisabled's machinery so the
        // input-suppression + alpha-mul side effects fire too.
        if (merged.disabled and !parent.disabled) {
            ctx.saved_input_when_disabled = ctx.input;
            ctx.input.mouse_left_clicked = false;
            ctx.input.mouse_left_down = false;
            ctx.input.mouse_left_released = false;
            ctx.input.mouse_right_clicked = false;
            ctx.input.mouse_middle_clicked = false;
            ctx.alpha_mul = ctx.style.disabled_alpha;
            ctx.disabled_count += 1;
        } else if (merged.disabled) {
            ctx.disabled_count += 1;
        }
    }

    /// Pop the matching `pushItemFlag`. Always pair with a push;
    /// no-op when the stack is empty (defensive).
    pub fn popItemFlag(self: Ui) void {
        const ctx: *UiContext = self.ctx;
        const popped: ItemFlags = ctx.item_flags_stack.pop() orelse return;
        if (popped.disabled) {
            if (ctx.disabled_count > 0) {
                ctx.disabled_count -= 1;
            }
            // Outermost-pop transition - restore input + alpha.
            if (ctx.disabled_count == 0) {
                if (ctx.saved_input_when_disabled) |saved| {
                    ctx.input = saved;
                }
                ctx.saved_input_when_disabled = null;
                ctx.alpha_mul = 1.0;
            }
        }
    }

    /// The current effective item flags - the top of
    /// `item_flags_stack`, or all-default if empty. Widgets
    /// consult this for cross-widget behavior gates.
    pub fn currentItemFlags(self: Ui) ItemFlags {
        return currentItemFlagsImpl(self.ctx);
    }

    // ---- groups
    /// Open a "group" scope. Widgets submitted between `beginGroup`
    /// and `endGroup` lay out exactly as they normally would, but the
    /// group as a whole records a single bounding rect - so a
    /// follow-up `isItemHovered()` reports hover-over-the-whole-group
    /// rather than just hover-over-the-last-widget-in-it. Useful for
    /// labelled clusters that should act as one row. ImGui:
    /// `BeginGroup()`.
    pub fn beginGroup(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        // Resolve any pending sameLine BEFORE snapshotting so the
        // group's top-left is the resolved cursor.
        const at: Vec2 = resolveCursor(w, self.ctx.style.item_spacing[0]);
        const state: GroupState = .{
            .saved_cursor_pos = at,
            .saved_cursor_max = w.layout.cursor_max,
            .saved_line_height = w.layout.line_height,
        };
        self.ctx.group_stack.append(state) catch assertUnreachable(@src(), "OOM", .{});
        // Reset row-level state inside the group so a sameLine
        // outside the group doesn't accidentally cross into it.
        w.layout.line_height = 0;
        w.layout.cursor_pos = at;
    }

    /// Close the matching `beginGroup`. Computes the group's
    /// bounding rect, writes it into `last_item_*` for any
    /// follow-up `isItem*` query, and advances the parent cursor
    /// as if the group were a single item. ImGui: `EndGroup()`.
    pub fn endGroup(self: Ui) void {
        const w: *Window = self.ctx.current_window orelse return;
        const state: GroupState = self.ctx.group_stack.pop() orelse return;

        // Group rect: from the saved top-left to the max we extended
        // to. Use cursor_max which records the bottom-right of any
        // widget submitted during the group's lifetime.
        const min_corner: Vec2 = state.saved_cursor_pos;
        const max_corner: Vec2 = w.layout.cursor_max;
        const rect: Rectangle = .{
            .x = min_corner[0],
            .y = min_corner[1],
            .width = @max(0, max_corner[0] - min_corner[0]),
            .height = @max(0, max_corner[1] - min_corner[1]),
        };
        // The group has no stable id of its own - id=0 is fine
        // for hover-only queries; `markItemPost` skips the
        // activation-transition computation but still sets
        // last_item_hovered correctly via direct assignment below.
        w.layout.last_item_id = 0;
        w.layout.last_item_rect = rect;
        w.layout.last_item_hovered = pointInRect(self.ctx.input.mouse_pos, rect);
        markItemPost(self.ctx, w, false);

        // Restore row state to what was set BEFORE the group, then
        // advance the parent cursor so subsequent widgets sit BELOW
        // the group rect.
        w.layout.line_height = state.saved_line_height;
        advanceLayout(
            w,
            .{ rect.width, rect.height },
            self.ctx.style.item_spacing,
            self.ctx.style.window_padding[0],
        );
    }

    // ---- popups
    /// Mark a popup as "should be open from this frame onward".
    /// The popup itself doesn't render until matched with
    /// `beginPopup(str_id)`. `str_id` is hashed against the current
    /// window's id so two windows can have popups with identical
    /// labels without collision. Anchor position captured from the
    /// current mouse position - popup will appear at the cursor
    /// (matches ImGui's right-click-context-menu behaviour).
    /// ImGui: `OpenPopup(str_id)`.
    pub fn openPopup(self: Ui, str_id: []const u8) void {
        const parent_id: Id = if (self.ctx.current_window) |pw| pw.id else 0;
        const id: Id = hashStr(parent_id, str_id);
        // lint #4: double-open in same frame. If an entry
        // already exists AND its `opened_at_frame` matches the
        // current frame, the caller invoked openPopup twice this
        // frame for the same id — almost always a bug (the second
        // call's anchor wins; debug events fire twice).
        if (self.ctx.popup_open.get(id)) |existing| {
            if (existing.opened_at_frame == self.ctx.frame_count) {
                warnOnce(
                    @src(),
                    "ui.openPopup({s}): opened twice this frame (id={x})",
                    .{ str_id, id },
                );
            }
        }
        self.ctx.popup_open.put(self.ctx.gpa, id, .{
            .anchor = self.ctx.input.mouse_pos,
            .opened_at_frame = self.ctx.frame_count,
        }) catch assertUnreachable(@src(), "OOM", .{});
        debugLogPush(self.ctx, .popup_opened, "id={x} str='{s}'", .{ id, str_id });
    }

    /// True if the popup is currently open. ImGui: `IsPopupOpen(str_id)`.
    pub fn isPopupOpen(self: Ui, str_id: []const u8) bool {
        const parent_id: Id = if (self.ctx.current_window) |pw| pw.id else 0;
        const id: Id = hashStr(parent_id, str_id);
        return self.ctx.popup_open.contains(id);
    }

    /// Begin a popup scope. Returns true if the popup is open;
    /// caller must match a true return with `endPopup()`. Pattern:
    ///     if (ui.beginPopup("ctx_menu")) {
    ///         defer ui.endPopup();
    ///         if (ui.menuItem("Copy",.{})) {... }
    ///     }
    /// While submission is inside the popup scope, widgets render
    /// to the popup's draw list (which replays AFTER all regular
    /// windows in `endFrame`) and use the popup's persistent
    /// position + cursor. Click outside the popup OR a call to
    /// `closeCurrentPopup` dismisses it. ImGui: `BeginPopup(str_id)`.
    pub fn beginPopup(self: Ui, str_id: []const u8) bool {
        return openPopupScope(self.ctx, str_id);
    }

    /// Close the matching `beginPopup` scope. Symmetric - call
    /// EXACTLY once per `beginPopup` that returned true. `defer`
    /// is the recommended spelling. ImGui: `EndPopup()`.
    pub fn endPopup(self: Ui) void {
        closePopupScope(self.ctx);
    }

    /// Close the topmost popup currently open. Typically called
    /// from inside a popup body, e.g. on "Close" menu item or after
    /// a click that should dismiss. ImGui: `CloseCurrentPopup()`.
    pub fn closeCurrentPopup(self: Ui) void {
        const id: Id = self.ctx.popup_stack.top() orelse return;
        _ = self.ctx.popup_open.remove(id);
        debugLogPush(self.ctx, .popup_closed, "id={x} reason=user", .{id});
    }

    /// Open + begin a context-menu popup if the user right-clicked
    /// on the most-recently-submitted widget this frame. Returns
    /// true once the popup is open; pair with `endPopup()`.
    /// `str_id` defaults to `"context"` when null. Pattern:
    ///     _ = ui.button("Save",.{});
    ///     if (ui.beginPopupContextItem(null)) {
    ///         defer ui.endPopup();
    ///         if (ui.menuItem("Reset",.{})) state.reset();
    ///     }
    /// ImGui: `BeginPopupContextItem(str_id, flags)`.
    pub fn beginPopupContextItem(self: Ui, str_id: ?[]const u8) bool {
        const w: *Window = self.ctx.current_window orelse return false;
        const sid: []const u8 = str_id orelse "##ctx";
        // Auto-open: if last item is hovered AND user right-clicked.
        if (w.layout.last_item_hovered and self.ctx.input.mouse_right_clicked) {
            self.openPopup(sid);
        }
        return self.beginPopup(sid);
    }

    /// Begin a modal popup scope. Modals differ from regular popups
    /// in two ways: they render a fullscreen backdrop dim BEFORE
    /// the popup's chrome (visually disabling everything below), and
    /// they ignore click-outside-to-close - they must be dismissed
    /// explicitly via `closeCurrentPopup` OR by setting `*open_ptr`
    /// to false (typically wired to a Cancel/X button inside the
    /// modal body).
    ///     if (state.show_about) ui.openPopup("about");
    ///     if (ui.beginPopupModal("about", &state.show_about)) {
    ///         defer ui.endPopup();
    ///         ui.text("zimr v0.7.0",.{});
    ///         if (ui.button("OK",.{})) {
    ///             state.show_about = false;
    ///             ui.closeCurrentPopup();
    ///         }
    ///     }
    /// ImGui: `BeginPopupModal(name, p_open, flags)`.
    pub fn beginPopupModal(
        self: Ui,
        name: []const u8,
        open_ptr: ?*bool,
    ) bool {
        // Mark the popup-state as modal BEFORE entering scope so
        // the open helper renders the backdrop. Note: openPopup
        // must have been called separately; this just upgrades the
        // existing entry. If user passed open_ptr=false, dismiss.
        if (open_ptr) |p| {
            if (!p.*) {
                const parent_id: Id = if (self.ctx.current_window) |pw| pw.id else 0;
                const id: Id = hashStr(parent_id, name);
                _ = self.ctx.popup_open.remove(id);
                return false;
            }
        }
        const parent_id: Id = if (self.ctx.current_window) |pw| pw.id else 0;
        const id: Id = hashStr(parent_id, name);
        if (self.ctx.popup_open.getPtr(id)) |state| {
            state.is_modal = true;
        }
        return self.beginPopup(name);
    }

    // ---- main menu bar + menu + menuItem
    /// Begin the main menu bar at the top of the canvas. Returns
    /// true if the bar is active (rare false: not enough memory to
    /// allocate the synthetic bar window). Pair with
    /// `endMainMenuBar`. ImGui: `BeginMainMenuBar()`.
    ///     if (f.ui.beginMainMenuBar()) {
    ///         defer f.ui.endMainMenuBar();
    ///         if (f.ui.beginMenu("File")) {
    ///             defer f.ui.endMenu();
    ///             if (f.ui.menuItem("Open",.{.shortcut = "Ctrl+O" })) {}
    ///             if (f.ui.menuItem("Quit",.{})) state.should_quit = true;
    ///         }
    ///     }
    pub fn beginMainMenuBar(self: Ui) bool {
        return openMainMenuBar(self.ctx);
    }

    /// Close the main menu bar scope. Symmetric - call EXACTLY once
    /// per `beginMainMenuBar` that returned true. ImGui:
    /// `EndMainMenuBar()`.
    pub fn endMainMenuBar(self: Ui) void {
        closeMainMenuBar(self.ctx);
    }

    /// Begin a per-window menu bar - a horizontal strip pinned to the
    /// top of the current window, just below the title bar. Pair with
    /// `endMenuBar`. Returns true so the caller can use
    /// `if (ui.beginMenuBar()) { defer ui.endMenuBar();... }` with a
    /// uniform shape. Unlike `beginMainMenuBar` (which floats at the
    /// top of the canvas regardless of which window is active), this
    /// bar belongs to the window - drag the window, the bar drags
    /// with it. ImGui: `BeginMenuBar()` paired with a window opened
    /// via `Begin(name, p_open, ImGuiWindowFlags_MenuBar)`.
    ///     if (u.window("Tools",.{})) |w| {
    ///         defer w.close();
    ///         if (u.beginMenuBar()) {
    ///             defer u.endMenuBar();
    ///             if (u.beginMenu("File")) {
    ///                 defer u.endMenu();
    ///                 _ = u.menuItem("Save",.{.shortcut = "Ctrl+S" });
    ///             }
    ///         }
    ///         u.text("Window content below the bar...",.{});
    ///     }
    pub fn beginMenuBar(self: Ui) bool {
        return openWindowMenuBar(self.ctx);
    }

    /// Close the per-window menu bar scope. Symmetric - call
    /// EXACTLY once per `beginMenuBar` that returned true. ImGui:
    /// `EndMenuBar()`.
    pub fn endMenuBar(self: Ui) void {
        closeWindowMenuBar(self.ctx);
    }

    /// Begin a menu inside the main menu bar. Renders a clickable
    /// label in the bar; on click, opens a popup anchored just
    /// below the label. Returns true if the menu's popup is open
    /// (caller submits menu items, then calls `endMenu`). ImGui:
    /// `BeginMenu(label, enabled)`.
    pub fn beginMenu(self: Ui, label: []const u8) bool {
        return openMenu(self.ctx, label, true);
    }

    /// End a `beginMenu` scope. Symmetric - call EXACTLY once per
    /// `beginMenu` that returned true. ImGui: `EndMenu()`.
    pub fn endMenu(self: Ui) void {
        // The menu's popup is the topmost popup; close-popup-scope
        // matches the openMenu's beginPopup-style entry.
        closePopupScope(self.ctx);
    }

    /// A clickable menu entry. Returns true on the click frame.
    /// `opts.shortcut` is a display-only string (right-aligned in
    /// the row) - wiring the actual keyboard shortcut is the
    /// caller's responsibility.
    /// `opts.selected` shows a checkmark when true (toggle-style
    /// menu items). ImGui: `MenuItem(label, shortcut, selected,
    /// enabled)`.
    pub fn menuItem(
        self: Ui,
        label: []const u8,
        opts: MenuItemOpts,
    ) bool {
        return menuItemImpl(self.ctx, label, opts);
    }

    // ---- +: tab bars
    /// Begin a horizontal tab bar. Pair with `endTabBar`. Returns
    /// true so the caller can use `if (ui.beginTabBar(...,.{})) {... }`
    /// to skip the body when the bar can't open. ImGui:
    /// `BeginTabBar(str_id, flags)`.
    ///     if (f.ui.beginTabBar("settings_tabs",.{})) {
    ///         defer f.ui.endTabBar();
    ///         if (f.ui.beginTabItem("General", null,.{})) {
    ///             defer f.ui.endTabItem();
    ///             //... general settings widgets
    ///         }
    ///         if (f.ui.beginTabItem("Audio", null,.{})) {
    ///             defer f.ui.endTabItem();
    ///             //... audio settings widgets
    ///         }
    ///     }
    /// `opts: TabBarFlags` - pass `.{}` for default. See
    /// `TabBarFlags` for the flag inventory and current wired/
    /// no-op status.
    pub fn beginTabBar(
        self: Ui,
        str_id: []const u8,
        opts: TabBarFlags,
    ) bool {
        return openTabBar(self.ctx, str_id, opts);
    }

    /// Close the matching `beginTabBar` scope. Renders the
    /// bar→content separator line, GCs tabs the caller stopped
    /// submitting, advances the parent cursor past the tab bar.
    pub fn endTabBar(self: Ui) void {
        closeTabBar(self.ctx);
    }

    /// Begin a tab item inside the current tab bar. Returns true
    /// if THIS tab is the active one (caller submits widgets, then
    /// calls `endTabItem`).
    /// `open_ptr` (optional): non-null = render close-X. Clicking
    /// it (or middle-clicking the tab, unless suppressed) sets
    /// `*open_ptr = false` and removes the tab next frame.
    /// `opts: TabItemFlags` - pass `.{}` for default. Useful:
    /// `.unsaved_document` for `*` decoration, `.set_selected` to
    /// force-select. ImGui: `BeginTabItem(label, p_open, flags)`.
    pub fn beginTabItem(
        self: Ui,
        label: []const u8,
        open_ptr: ?*bool,
        opts: TabItemFlags,
    ) bool {
        return openTabItem(self.ctx, label, open_ptr, opts);
    }

    /// Close the matching `beginTabItem` scope. Symmetric - call
    /// EXACTLY once per `beginTabItem` that returned true. ImGui:
    /// `EndTabItem()`.
    pub fn endTabItem(self: Ui) void {
        closeTabItem(self.ctx);
    }

    // ---- list box
    /// Begin a fixed-height scrollable list box. Pair with
    /// `endListBox`. Inside the scope, the cursor lays out
    /// vertically as in any window; the box is clipped to its
    /// rect. Useful when you want a scrollable selection area
    /// inside a non-scrollable parent window.
    /// `size` interprets `0` as "auto" - width defaults to the
    /// available content region; height defaults to ~7 rows of
    /// the current font. ImGui: `BeginListBox(label, size)`.
    pub fn beginListBox(
        self: Ui,
        label: []const u8,
        size: Vec2,
    ) bool {
        return openListBox(self.ctx, label, size);
    }

    /// Close the matching `beginListBox` scope. Renders the
    /// border + advances the parent cursor. ImGui: `EndListBox()`.
    pub fn endListBox(self: Ui) void {
        closeListBox(self.ctx);
    }

    /// Convenience - render a complete labelled list box that
    /// shows `items` as selectable rows; `current.*` is the
    /// selected index. Returns true on the frame the user
    /// changes selection. ImGui: `ListBox(label, current, items,
    /// items_count, height_in_items)`.
    pub fn listBox(
        self: Ui,
        label: []const u8,
        current: *i32,
        items: []const []const u8,
    ) bool {
        return listBoxImpl(self.ctx, label, current, items);
    }

    // ---- additional widgets
    /// Progress indicator. `fraction` clamped to [0, 1]. `size`
    /// passes 0 in either axis to mean "auto" (full content width;
    /// 1-row default height). `overlay` is an optional centred
    /// caption - pass `""` for none. ImGui: `ProgressBar(fraction,
    /// size_arg, overlay)`.
    pub fn progressBar(
        self: Ui,
        fraction: f32,
        size: Vec2,
        overlay: []const u8,
    ) void {
        progressBarImpl(self.ctx, fraction, size, overlay);
    }

    /// Vertical slider - same semantics as `slider` but laid out
    /// top-to-bottom with `size.y` driving the bar's vertical span.
    /// Useful for mixers, level meters, etc. `value` is `*f32` or
    /// `*i32` (or any float/int via comptime dispatch). Returns
    /// true on the frame the value changes. ImGui:
    /// `VSliderFloat(label, size, v, v_min, v_max, format)` etc.
    pub fn vSlider(
        self: Ui,
        label: []const u8,
        size: Vec2,
        v: anytype,
        opts: SliderOpts,
    ) bool {
        return vSliderDispatch(self.ctx, label, size, v, opts);
    }

    /// Text-entry float input - like `inputText` but typed scalar.
    /// Renders the current value formatted via `opts.fmt`; user
    /// types a new number and presses Enter to commit. Invalid
    /// input is silently rejected on commit (value stays at last
    /// good). Returns true on the frame the value changes.
    /// Text-entry numeric input, generic over scalar or array. Pass
    /// `*f32` / `*i32` for a single value; pass `*[N]f32` / `*[N]i32`
    /// for a multi-component widget (N narrow boxes side-by-side).
    /// Returns true on any frame the value(s) changed. ImGui:
    /// `InputFloat` / `InputInt` / `InputFloat3` / `InputInt2`,
    /// collapsed to one generic function.
    ///     var pos: [3]f32 =.{ 0, 0, 0 };
    ///     _ = ui.input("position", &pos,.{});
    pub fn input(
        self: Ui,
        label: []const u8,
        v: anytype,
        opts: InputScalarOpts,
    ) bool {
        return inputDispatch(self.ctx, label, v, opts);
    }

    /// Text-entry float input. See `inputFloat`.
    /// ImGui: `InputFloat(label, v, step, step_fast, format,
    /// flags)`.
    pub fn inputFloat(
        self: Ui,
        label: []const u8,
        v: *f32,
        opts: InputScalarOpts,
    ) bool {
        return inputScalarImpl(self.ctx, label, v, f32, opts);
    }

    /// Text-entry int input. See `inputFloat`.
    pub fn inputInt(
        self: Ui,
        label: []const u8,
        v: *i32,
        opts: InputScalarOpts,
    ) bool {
        return inputScalarImpl(self.ctx, label, v, i32, opts);
    }

    /// Compact colour swatch - a clickable rectangle that displays
    /// a colour and shows the RGBA breakdown as a tooltip on hover.
    /// Returns true on the frame the user clicks the swatch.
    /// `value` is `*const [4]f32`, `*const [3]f32`, or `*const Color`.
    /// ImGui: `ColorButton(desc_id, col, flags, size)`.
    pub fn colorButton(
        self: Ui,
        desc_id: []const u8,
        v: anytype,
        size: Vec2,
    ) bool {
        return colorButtonDispatch(self.ctx, desc_id, v, size);
    }

    /// Clickable variant of `image`. Renders the texture as a
    /// button-sized rect (using the same `source` polymorphism as
    /// `image`) and returns true on the frame the user clicks it.
    /// `size: ?Vec2` - `null` means "use the texture's natural
    /// pixel dimensions". ImGui: `ImageButton(str_id, texture,
    /// size,...)`.
    pub fn imageButton(
        self: Ui,
        str_id: []const u8,
        source: anytype,
        size: ?Vec2,
    ) bool {
        return imageButtonImpl(self.ctx, str_id, source, size);
    }

    // ---- editStruct - comptime-reflective struct inspector
    /// Auto-build an editor UI for a struct via comptime reflection.
    /// Each field gets a widget chosen from its type:
    ///   - `bool` → `checkbox`
    ///   - `f32` / `f64` → `inputFloat` (or `slider` if opts gives min+max)
    ///   - `i32` / `u32` / … → `inputInt` (or `slider` if opts gives min+max)
    ///   - `[]const u8` → read-only `text` line (mutation TBD)
    ///   - nested struct → `treeNode` + recursive `editStruct`
    ///   - `enum` → `combo` over all enum values
    ///   - `[3]f32` / `[4]f32`→ `colorEdit3` / `colorEdit4` (special-cased)
    ///   - other arrays of float/int → one widget per element
    /// Returns true on the frame ANY field changed.
    ///     var s: MySettings =.{};
    ///     if (f.ui.editStruct(&s)) {
    ///         // re-apply settings...
    ///     }
    /// `editStruct` dispatches to `editStructOpts` with empty opts.
    pub fn editStruct(self: Ui, value_ptr: anytype) bool {
        return editStructImpl(self.ctx, value_ptr, .{});
    }

    /// Same as `editStruct` but accepts a per-field options struct.
    /// `opts` is a struct literal whose field names match the value's
    /// fields; each entry is itself a struct with optional members:
    ///   - `.min`, `.max` → switch to slider for numeric fields
    ///   - `.fmt` → format string (default per type)
    ///   - `.skip` → skip this field entirely
    ///   - `.label` → override the displayed label
    ///   - `.is_color` → force colorEdit dispatch for [3]/[4] f32 arrays
    /// Fields not mentioned in `opts` use defaults. Unknown opts
    /// fields are silently ignored - no @compileError - so a struct
    /// can grow without breaking existing call-sites.
    ///     f.ui.editStructOpts(&state,.{
    ///         .speed =.{.min = 0,.max = 100,.fmt = "{d:.1}" },
    ///         .iterations =.{.min = 1,.max = 1000 },
    ///         .password =.{.skip = true },
    ///     });
    pub fn editStructOpts(
        self: Ui,
        value_ptr: anytype,
        opts: anytype,
    ) bool {
        return editStructImpl(self.ctx, value_ptr, opts);
    }

    /// Reflection inspector (P1, AM-8). Wraps `editStruct` in a
    /// labeled, collapsible tree node — the right shape for a
    /// section header in a settings panel or dev-tools tab.
    ///     if (u.inspect("Style", &ctx.style)) {
    ///         // re-apply theme...
    ///     }
    /// The treeNode collapses by default; opens once on first click,
    /// remembers per-frame open state. When closed, returns false
    /// and skips the field iteration entirely (zero per-frame cost
    /// for collapsed inspectors).
    ///
    /// Use `editStruct(ptr)` directly when you DON'T want a header
    /// (e.g. when the inspector is already inside its own tab or
    /// window section), or `inspectWithAttrs` for per-field hints.
    pub fn inspect(
        self: Ui,
        label: []const u8,
        value_ptr: anytype,
    ) bool {
        if (!self.treeNode(label, .{})) {
            return false;
        }
        defer self.treePop();
        return editStructImpl(self.ctx, value_ptr, .{});
    }

    /// Labeled variant of `editStructOpts`. Same per-field opts
    /// shape; wraps in a collapsible tree node like `inspect`.
    ///     if (u.inspectWithAttrs("Settings", &s,.{
    ///         .speed =.{.min = 0,.max = 100 },
    ///         .password =.{.skip = true },
    ///     })) {... }
    pub fn inspectWithAttrs(
        self: Ui,
        label: []const u8,
        value_ptr: anytype,
        opts: anytype,
    ) bool {
        if (!self.treeNode(label, .{})) {
            return false;
        }
        defer self.treePop();
        return editStructImpl(self.ctx, value_ptr, opts);
    }

    // ---- editArrayList - list editor with add/remove
    /// Auto-build an editor UI for a `std.ArrayList(T)`. Renders a
    /// collapsible header with the count + an "Add" button that
    /// appends a default-initialized `T`, then one row per element
    /// with a "Remove" button. Each element is dispatched through
    /// the same field-type matrix as `editStruct` (struct → recursive
    /// editor, primitive → matching widget, etc.).
    /// Pass a pointer to your `std.ArrayList(T)`. The list's
    /// allocator is read from `ctx.gpa` (the same allocator used by
    /// every other persistent UI structure). Returns true on the
    /// frame ANY field changes OR the list grows/shrinks.
    ///     var enemies: std.ArrayList(Enemy) =.empty;
    ///     defer enemies.deinit(gpa);
    ///     //... later, in update():
    ///     if (f.ui.editArrayList("Enemies", &enemies)) {
    ///         // re-sort spatial index, etc.
    ///     }
    pub fn editArrayList(
        self: Ui,
        label: []const u8,
        list_ptr: anytype,
    ) bool {
        return editArrayListImpl(self.ctx, label, list_ptr);
    }

    /// Same as `editArrayList` but accepts the same per-field opts
    /// struct as `editStructOpts`. Forwarded to each element when
    /// the element type is a struct so per-element fields can be
    /// constrained (e.g. `.health =.{.min = 0,.max = 100 }`).
    pub fn editArrayListOpts(
        self: Ui,
        label: []const u8,
        list_ptr: anytype,
        opts: anytype,
    ) bool {
        return editArrayListImplOpts(self.ctx, label, list_ptr, opts);
    }

    // ---- Style editor + layout persistence
    /// Build a complete editor for the active `Style` via
    /// `editStruct`. Every Color slot becomes a `colorEdit` widget,
    /// every Vec2 becomes a side-by-side pair of inputFloats,
    /// every f32 becomes an inputFloat. Returns true on the frame
    /// any style field changed.
    ///     if (f.ui.styleEditor()) {
    ///         // restyle just happened - bump theme rev counter etc.
    ///     }
    pub fn styleEditor(self: Ui) bool {
        return editStructImpl(self.ctx, self.style(), .{});
    }

    /// Serialize all currently-known windows' positions, sizes,
    /// scroll states, and user-resized flags into a binary buffer
    /// the caller owns and frees. Format is tagged with magic +
    /// version so future format changes can be detected. Pair with
    /// `applyLayout(bytes)` to restore. Useful for "remember
    /// window layout across launches".
    ///     const buf = try f.ui.serializeLayout(gpa);
    ///     defer gpa.free(buf);
    ///     try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = "layout.bin", .data = buf });
    pub fn serializeLayout(self: Ui, gpa: Allocator) ![]u8 {
        return serializeLayoutImpl(self.ctx, gpa);
    }

    /// Restore window positions/sizes from a buffer previously
    /// produced by `serializeLayout`. Unknown magic / version is
    /// rejected with `error.LayoutFormatMismatch`. Window IDs not
    /// present in the current `ctx.windows` map create new entries
    /// with the saved geometry; IDs that DO exist get their pos /
    /// size / scroll_y / user_resized fields overwritten. Order
    /// of windows in the buffer doesn't matter. Safe to call
    /// before any window is submitted.
    pub fn applyLayout(self: Ui, bytes: []const u8) !void {
        return applyLayoutImpl(self.ctx, bytes);
    }

    // ---- keyboard nav + showDemoWindow
    /// Show the canonical zimr/imgui demo window. One call walks
    /// every widget category the port supports, organized into a
    /// tab bar (Widgets / Layout / Style / About). Useful as a
    /// living showcase, a smoke-test that every widget at least
    /// submits without panic, and a copy-paste reference for users
    /// learning the API.
    /// `state` carries the persistent values the demo's widgets
    /// drive - sliders, checkboxes, text buffers, etc. Pass a
    /// pointer to a `DemoState` initialized with `.{}` (all defaults).
    /// `p_open`, when non-null, is read at the top: if false, the
    /// demo doesn't render. When the user clicks the window's close
    /// button (not yet implemented for general windows), `*p_open`
    /// becomes false. Pass `null` to render unconditionally.
    ///     var demo: ui.DemoState =.{};
    ///     //... in update():
    ///     f.ui.showDemoWindow(&demo, null);
    pub fn showDemoWindow(
        self: Ui,
        state: *DemoState,
        p_open: ?*bool,
    ) void {
        showDemoWindowImpl(self, state, p_open);
    }

    /// Submit a tooltip to be drawn above all other content at end
    /// of frame. Position is the current mouse position +
    /// (16, 16) offset. Last call this frame wins.
    pub fn setTooltip(
        self: Ui,
        comptime fmt: []const u8,
        args: anytype,
    ) void {
        var tt = TooltipData{
            .pos = .{ self.ctx.input.mouse_pos[0] + 16, self.ctx.input.mouse_pos[1] + 16 },
        };
        const formatted: []u8 = bufPrint(&tt.text_buf, fmt, args) catch tt.text_buf[0..0];
        tt.text_len = formatted.len;
        self.ctx.pending_tooltip = tt;
    }

    /// Open a tooltip block. Widgets submitted between
    /// `beginTooltip` and `endTooltip` are routed into the
    /// tooltip's own draw list, which renders on top of
    /// everything else (above popups) at endFrame.
    /// Position is anchored at the current mouse position +
    /// (16, 16) offset. The tooltip's size auto-fits its
    /// content. Pattern:
    ///     if (ui.isItemHovered(.{})) {
    ///         ui.beginTooltip();
    ///         ui.text("Detailed info...",.{});
    ///         _ = ui.slider("preview", &p.x,.{});
    ///         ui.endTooltip();
    ///     }
    /// Multiple `beginTooltip` / `endTooltip` pairs in one frame
    /// are not supported - the last `beginTooltip` wins (its
    /// contents replace any previous tooltip block).
    pub fn beginTooltip(self: Ui) void {
        beginTooltipImpl(self.ctx);
    }

    /// Close the tooltip block opened by `beginTooltip`. Safe to
    /// call when no tooltip is open (no-op).
    pub fn endTooltip(self: Ui) void {
        endTooltipImpl(self.ctx);
    }

    // ---- Helpers exposed for later widget impls
    /// Current widget anchor in screen pixels. In the post-308.5
    /// layout model, sameLine writes directly to `cursor_pos`, so
    /// this is just a read; the function form is retained for
    /// callsite readability.
    pub fn cursorScreenPos(self: Ui) Vec2 {
        const w: *Window = self.ctx.current_window orelse return .{ 0, 0 };
        return resolveCursor(w, self.ctx.style.item_spacing[0]);
    }

    // ============================================================================
    // Phase A1 - Window scroll API + clipboard
    // ============================================================================

    /// Current vertical scroll offset of the active window in
    /// pixels. Returns 0 if no window is active. ImGui:
    /// `GetScrollY()`.
    pub fn getScrollY(self: Ui) f32 {
        const w: *Window = self.ctx.current_window orelse return 0;
        return w.scroll_y;
    }

    /// Maximum allowed scroll for the active window - clamp upper
    /// bound enforced by end-of-frame. Reads last frame's
    /// computed value; for mid-frame programmatic scroll the
    /// previous frame's max is the best estimate (subsequent
    /// frames converge). Returns 0 if no window is active or if
    /// content fits without overflow. ImGui: `GetScrollMaxY()`.
    pub fn getScrollMaxY(self: Ui) f32 {
        const w: *Window = self.ctx.current_window orelse return 0;
        return w.scroll_max_y;
    }

    /// Set the vertical scroll position directly. Clamped to
    /// `[0, scroll_max_y]`. Useful for "remember scroll position"
    /// or "jump to top" buttons. ImGui: `SetScrollY(scroll_y)`.
    pub fn setScrollY(self: Ui, y: f32) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.scroll_y = clamp(y, 0, w.scroll_max_y);
    }

    // ---- X-axis scroll accessors --------------------

    /// Current horizontal scroll offset of the active window in
    /// pixels. Returns 0 if no window is active OR if the window
    /// hasn't opted into `WindowFlags.horizontal_scrollbar` (scroll_x
    /// is forced to 0 in `closeWindow` when the flag is unset).
    /// Imgui: `GetScrollX()`.
    pub fn getScrollX(self: Ui) f32 {
        const w: *Window = self.ctx.current_window orelse return 0;
        return w.scroll_x;
    }

    /// Maximum allowed horizontal scroll for the active window.
    /// Reads last frame's computed value (same convergence semantics
    /// as `getScrollMaxY`). Returns 0 if no window is active, the
    /// horizontal-scrollbar flag is unset, or content fits without
    /// X-overflow. Imgui: `GetScrollMaxX()`.
    pub fn getScrollMaxX(self: Ui) f32 {
        const w: *Window = self.ctx.current_window orelse return 0;
        return w.scroll_max_x;
    }

    /// Set the horizontal scroll position directly. Clamped to
    /// `[0, scroll_max_x]`. No-op when the window hasn't opted into
    /// `WindowFlags.horizontal_scrollbar` (the next `closeWindow`
    /// would clobber any write to scroll_x back to 0 anyway).
    /// Imgui: `SetScrollX(scroll_x)`.
    pub fn setScrollX(self: Ui, x: f32) void {
        const w: *Window = self.ctx.current_window orelse return;
        w.scroll_x = clamp(x, 0, w.scroll_max_x);
    }

    /// Adjust scroll so the current cursor position appears at
    /// `ratio` within the visible vertical area:
    ///   - 0.0 - cursor at the TOP of visible area
    ///   - 0.5 - cursor CENTERED
    ///   - 1.0 - cursor at the BOTTOM
    /// Idiomatic use: at end-of-frame in a log viewer, call
    /// `setScrollHereY(1.0)` to auto-scroll-to-bottom. ImGui:
    /// `SetScrollHereY(center_y_ratio = 0.5)`.
    pub fn setScrollHereY(self: Ui, ratio: f32) void {
        const w: *Window = self.ctx.current_window orelse return;
        const ctx: *UiContext = self.ctx;
        // Recover content-coord y of the cursor (cursor_pos is
        // already screen-coord and pre-shifted by scroll_y, so
        // undo the shift).
        const inner_origin_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
        const cursor_content_y: f32 = w.layout.cursor_pos[1] + w.scroll_y - inner_origin_y;
        const viewport_h: f32 = @max(0, w.size[1] - ctx.style.title_bar_height - ctx.style.window_padding[1]);
        const desired: f32 = cursor_content_y - ratio * viewport_h;
        w.scroll_y = clamp(desired, 0, w.scroll_max_y);
    }

    /// Like `setScrollHereY` but with an explicit content-area
    /// y-coordinate instead of the cursor. `local_y` is relative
    /// to the window's content-area top-left. ImGui:
    /// `SetScrollFromPosY(local_y, center_y_ratio = 0.5)`.
    pub fn setScrollFromPosY(
        self: Ui,
        local_y: f32,
        ratio: f32,
    ) void {
        const w: *Window = self.ctx.current_window orelse return;
        const ctx: *UiContext = self.ctx;
        const viewport_h: f32 = @max(0, w.size.y - ctx.style.title_bar_height - ctx.style.window_padding.y);
        const desired: f32 = local_y - ratio * viewport_h;
        w.scroll_y = clamp(desired, 0, w.scroll_max_y);
    }

    /// Write text to the system clipboard. Sync from caller's
    /// perspective; the underlying browser API
    /// (`navigator.clipboard.writeText`) is async fire-and-forget
    /// and may silently fail if the document lacks focus or the
    /// user hasn't granted permission. On the host build this is
    /// a no-op. ImGui: `SetClipboardText(text)`.
    pub fn setClipboardText(self: Ui, s: []const u8) void {
        _ = self;
        runtime.core.setClipboardText(s);
    }

    /// Return the most recently read clipboard text, or "" if no
    /// successful read has occurred yet. Reads are inherently
    /// async on the web platform - the imgui-style sync getter is
    /// a stub for surface parity; the actual async fetch happens
    /// via `runtime.getClipboardTextAsync()` with a polling
    /// handle. Long-form: store the result of the async read in
    /// `ctx.clipboard_cache_buf` and this getter returns that.
    /// Today: empty (no caching wired yet - that lands with the
    /// `InputTextCallbackData` paste plumbing in Phase A4).
    /// ImGui: `GetClipboardText() const char*`.
    pub fn getClipboardText(self: Ui) []const u8 {
        return self.ctx.clipboard_cache[0..self.ctx.clipboard_cache_len];
    }

    // ============================================================================
    // Phase A2 - ImGuiListClipper: virtualized rendering for huge lists
    // ============================================================================

    /// Open a virtualized clipper scope. Use when rendering long
    /// item lists (1000+ rows) where most rows would fall outside
    /// the visible viewport. Without a clipper, every row's
    /// widget submission cost is paid even for rows the user
    /// can't see.
    /// Idiomatic use:
    ///     var clip = u.clipper(line_count, line_height);
    ///     while (clip.step()) |range| {
    ///         var i: usize = range.start;
    ///         while (i < range.end): (i += 1) {
    ///             u.text("Row {d}: {s}",.{ i, rows[i] });
    ///         }
    ///     }
    /// **Precondition: `item_height` must be the rendered height
    /// of one item - including item_spacing.y.** The clipper
    /// computes the visible row range arithmetically from
    /// `(viewport_top - cursor.y) / item_height`; a wrong height
    /// silently miscalculates the range (renders the wrong rows
    /// or duplicates rows when the user scrolls). For variable-
    /// height rows the imgui idiom is "measure on first frame,
    /// virtualize on second frame" - not implemented in A2 (see
    /// `Clipper.measure_pending` field reserved for that).
    /// `item_count == 0` returns a clipper that completes
    /// immediately (zero step iterations). Negative item_height
    /// is clamped to 1 to avoid division-by-zero.
    /// ImGui: `ImGuiListClipper` (constructor + `Begin`).
    pub fn clipper(
        self: Ui,
        item_count: usize,
        item_height: f32,
    ) Clipper {
        return Clipper.init(self.ctx, item_count, item_height);
    }
};

// ============================================================================
// Options structs (per-widget configuration)
// ============================================================================

/// Per-channel value display format used by `colorEdit` for the
/// text overlaid on each channel slider.  Mirrors imgui's
/// `_DisplayRGB` / `_DisplayHex` / `_Float` / `_Uint8` flag pairs;
/// zimr collapses the orthogonal axes into a single enum because
/// HSV display + non-RGB picker variants belong to a later P10
/// sub-turn (no need for an HSV float vs HSV int distinction
/// until HSV display lands).
///
/// Mirrors imgui flags: `_Float` (default), `_Uint8`, `_DisplayHex`.
pub const ColorEditDisplayFormat = enum {
    /// Per-channel 0.0–1.0 with `{d:.2}` precision (e.g. "0.50").
    /// Default — matches the conventional "shader uniform" mental
    /// model where channels are floats.
    float,
    /// Per-channel 0–255 (e.g. "128").  The web/CSS / 8-bit image
    /// mental model.  Computed as `@round(v * 255)`.
    int_0_255,
    /// Single combined hex string overlaid on the swatch
    /// (e.g. "#80FF8040" for RGBA).  Per-channel sliders show no
    /// value text in this mode — the hex IS the value display.
    /// Format: `#RRGGBB` for 3 channels, `#RRGGBBAA` for 4.
    hex,
};

pub const ColorEditOpts = struct {
    /// DEPRECATED.  Was intended for custom slider-value
    /// precision, but `std.fmt.bufPrint` requires a comptime
    /// format string and `[]const u8` opts fields are runtime —
    /// so the field was silently ignored.  Kept for source
    /// compatibility; new code should not set it.  Value text is
    /// always `{d:.2}` for `.float` and `{d}` for `.int_0_255`.
    /// Custom precision would need a separate mechanism (e.g.
    /// an enum of allowed precisions).
    fmt: []const u8 = "{d:.2}",
    /// Inline width override (default: auto-fit to row).
    width: f32 = 0,
    /// How channel values are rendered on top of the sliders.
    /// See `ColorEditDisplayFormat` for the regime details.
    display_format: ColorEditDisplayFormat = .float,
};

/// Format an RGB triplet (or RGBA quad) into a `#RRGGBB[AA]`
/// string.  Caller provides the destination buffer (must be at
/// least 9 bytes for RGBA, 7 for RGB).  Returns the populated
/// slice.  Channels are clamped to 0.0–1.0 before conversion so
/// out-of-range inputs round-trip predictably.
///
/// Pure function — no UI state touched — so it's testable in
/// isolation and reusable from non-widget code (e.g. logging,
/// serialization).
pub fn formatColorRgbHex(
    rgba: [4]f32,
    has_alpha: bool,
    out: []u8,
) []const u8 {
    const min_needed: usize = if (has_alpha) 9 else 7;
    if (out.len < min_needed) {
        return out[0..0];
    }
    const r: u8 = @round(clamp(rgba[0], 0.0, 1.0) * 255);
    const g: u8 = @round(clamp(rgba[1], 0.0, 1.0) * 255);
    const b: u8 = @round(clamp(rgba[2], 0.0, 1.0) * 255);
    out[0] = '#';
    _ = bufPrint(out[1..3], "{X:0>2}", .{r}) catch return out[0..0];
    _ = bufPrint(out[3..5], "{X:0>2}", .{g}) catch return out[0..0];
    _ = bufPrint(out[5..7], "{X:0>2}", .{b}) catch return out[0..0];
    if (has_alpha) {
        const a: u8 = @round(clamp(rgba[3], 0.0, 1.0) * 255);
        _ = bufPrint(out[7..9], "{X:0>2}", .{a}) catch return out[0..0];
        return out[0..9];
    }
    return out[0..7];
}

/// Convert a 0.0–1.0 channel value to its 0–255 integer
/// representation with imgui-compatible rounding (round-half-
/// away-from-zero).  Out-of-range inputs clamp first.
///
/// Pure fn, used by the `.int_0_255` display path.
pub fn colorChannelToInt255(v: f32) u8 {
    return @round(clamp(v, 0.0, 1.0) * 255);
}

/// Which on-screen layout `colorPicker` uses for the hue selector.
pub const ColorPickerLayout = enum {
    /// Bar: horizontal hue gradient stacked above a saturation/
    /// value box. Compact; fits in a standard widget row stack.
    bar,
    /// Wheel: hue ring around a saturation/value triangle. Larger
    /// footprint, looks more painterly.
    wheel,
};

pub const ColorPickerOpts = struct {
    /// Bar or wheel hue selector. Default `.bar` matches the
    /// imgui default; switch to `.wheel` for a more visual layout.
    layout: ColorPickerLayout = .bar,
    /// Edit alpha channel too (renders an extra alpha bar / slider).
    /// Only relevant for `*[4]f32` / `*Color`; ignored for `*[3]f32`.
    alpha: bool = true,
    /// Side length (pixels) of the SV box / wheel diameter.
    /// Zero = sensible default of 180.
    size: f32 = 0,
};

/// Table-level sizing policy. Sets the DEFAULT sizing for any
/// column whose `tableSetupColumn` opts don't specify a per-column
/// override. Mirrors imgui's `ImGuiTableFlags_Sizing*` family
/// (imgui.h:2141-2144).
///
/// All four modes rely on `width_auto_seen` — the maximum content
/// width measured during the PREVIOUS frame, persisted across
/// frames in `UiContext.table_width_auto_cache`. The first frame
/// a table is submitted has no measurement yet, so each column
/// falls back to `fallbackColumnWidth(style.font_size)` (≈ 6em).
/// One frame of layout lag is intrinsic — zimr is single-pass and
/// cannot know a column's natural width before its cells render.
pub const TableSizing = enum {
    /// Every stretch column shares the available width equally.
    /// Each gets `remaining / count_stretch` pixels unless the
    /// caller passed a per-column `weight`, which wins.
    /// Matches imgui's `SizingStretchSame`.
    /// This is the default — preserves zimr's pre-behavior.
    stretch_same,
    /// Stretch columns share the available width proportionally
    /// to their measured content width — a column with twice as
    /// much content gets twice the share. Per-column `weight`
    /// (if supplied) wins.
    /// Matches imgui's `SizingStretchProp`.
    stretch_prop,
    /// Each column is sized to its own measured content width.
    /// Per-column `width` (if supplied) wins.
    /// Matches imgui's `SizingFixedFit`.
    fixed_fit,
    /// All fixed columns get the same width — the maximum of any
    /// fixed column's measured content width. Per-column `width`
    /// (if supplied) wins.
    /// Matches imgui's `SizingFixedSame`.
    fixed_same,
};

pub const TableOpts = struct {
    /// P8.4: table-level sizing policy. Sets the
    /// default sizing for every column that doesn't override via
    /// `tableSetupColumn`'s `sizing` opt. The four modes are
    /// content-fit variants — see `TableSizing` for what each
    /// mode does and the first-frame fallback caveat.
    ///
    /// Default `.stretch_same` — equal share across all columns
    /// — preserves zimr's pre-behavior. Existing tables
    /// that don't set this field keep their old layout.
    /// Mirrors imgui's `ImGuiTableFlags_Sizing*` family
    /// (imgui.h:2141-2144).
    sizing: TableSizing = .stretch_same,

    /// When true, draw 1px borders. Default true; set false for
    /// a cleaner data grid without lines. P8.2: this
    /// is now a MASTER flag that AND-gates the four granular
    /// `borders_*` flags below — `borders = false` disables ALL
    /// border drawing regardless of the granular flags' values.
    /// For finer-grained control, leave `borders = true` (the
    /// default) and selectively disable individual `borders_*`
    /// flags. Backward compat: setting `borders = false` works
    /// exactly as it did pre-P8.2.
    borders: bool = true,

    /// P8.2: horizontal interior lines — the per-row separator
    /// between data rows AND the line between the header row and
    /// the first data row. Gated by `borders`. Default true.
    /// ImGui equivalent: `ImGuiTableFlags_BordersInnerH`.
    borders_inner_h: bool = true,

    /// P8.2: horizontal exterior lines — the top and bottom
    /// edges of the table's outer rect. Gated by `borders`.
    /// Default true.
    /// ImGui equivalent: `ImGuiTableFlags_BordersOuterH`.
    borders_outer_h: bool = true,

    /// P8.2: vertical interior lines — the column dividers and
    /// the per-cell right edges in the header row. Gated by
    /// `borders`. Default true.
    /// ImGui equivalent: `ImGuiTableFlags_BordersInnerV`.
    borders_inner_v: bool = true,

    /// P8.2: vertical exterior lines — the left and right edges
    /// of the table's outer rect. Gated by `borders`. Default
    /// true.
    /// ImGui equivalent: `ImGuiTableFlags_BordersOuterV`.
    borders_outer_v: bool = true,

    /// Horizontal padding inside each cell. Default 4px.
    cell_padding_x: f32 = 4,
    /// Vertical padding inside each cell. Default 2px.
    cell_padding_y: f32 = 2,

    /// P8.5: explicit horizontal-scroll opt-in. When
    /// true, the table allows the total column width to exceed
    /// `outer_width`; content past `outer_width` is clipped on
    /// the right side, and the column-overflow lint is
    /// suppressed (overflow is intentional, not a bug).
    ///
    /// Default false. Mirrors imgui's `ImGuiTableFlags_ScrollX`
    /// (imgui.h:2157). Like imgui's flag, this requires
    /// `outer_width > 0` to be meaningful — when `outer_width`
    /// is 0 (size-to-content), there's nothing to scroll past.
    ///
    /// NOTE: this turn lands the flag, the clip
    /// behavior, and the lint suppression. Actual horizontal
    /// scrolling INPUT (shift-wheel, drag) and a horizontal
    /// scrollbar UI are deferred to a follow-up turn. Callers
    /// who set `scroll_x = true` today get a wider, clipped
    /// table but can't yet pan to see the right side.
    scroll_x: bool = false,

    /// P8.5: explicit vertical-scroll opt-in. When
    /// true (or when `outer_height > 0`, kept for back-compat),
    /// vertical scrolling is enabled. Mirrors imgui's
    /// `ImGuiTableFlags_ScrollY` (imgui.h:2158).
    ///
    /// Pre-zimr enabled vertical scrolling implicitly
    /// whenever `outer_height > 0`. That path is preserved —
    /// existing callers don't need to set this flag. The flag
    /// is provided so new callers can express intent explicitly:
    /// "this table is meant to scroll vertically" reads better
    /// than "this table has a fixed height (which incidentally
    /// makes it scroll)".
    scroll_y: bool = false,

    /// P8.3: when true, the LEFTMOST column's content
    /// is flush against the table's outer-left edge — no
    /// `cell_padding_x` gap between the outer border and the
    /// first cell's content. Default false (legacy behaviour
    /// preserved: column 0 gets the same `cell_padding_x` left
    /// gap as every other column).
    /// zimr applies cell_padding_x as LEFT-side margin only;
    /// the right side has no explicit padding today, so the
    /// rightmost column's outer-right gap is unaffected by this
    /// flag. ImGui equivalent: `ImGuiTableFlags_NoPadOuterX`
    /// (with the caveat that ImGui's model has symmetric L/R
    /// padding; zimr's is L-only).
    no_pad_outer_x: bool = false,

    /// P8.3: when true, columns 1..N-1 (every column EXCEPT the
    /// first) have no `cell_padding_x` gap on their left side —
    /// content is flush against the column divider line on the
    /// left. Default false. Useful for tightly-packed grids
    /// where the column divider IS the visual break and the
    /// padding gap would feel excessive.
    /// ImGui equivalent: `ImGuiTableFlags_NoPadInnerX`.
    no_pad_inner_x: bool = false,
    /// Override the table's outer width. Zero = fill remaining
    /// row width in the parent window.
    outer_width: f32 = 0,
    /// Height cap for the table (pixels). When non-zero AND the
    /// submitted rows' total height exceeds this, the table
    /// becomes vertically scrollable - wheel-over scrolls within
    /// the cap, content beyond the cap is clipped. Zero (the
    /// default) means "size to content" (no scroll).
    outer_height: f32 = 0,
    /// Number of leading rows kept pinned to the top during
    /// scroll. Typically 1 (the header row created by
    /// `tableHeadersRow`). Default 0 = no freeze. The header
    /// always renders at the top whether `freeze_rows` is set or
    /// not; this option specifically controls whether data rows
    /// scroll BENEATH the header.
    freeze_rows: u32 = 0,
    /// When true, draw alternating-row tinted backgrounds using
    /// `style.table_row_bg` (even rows) and `style.table_row_bg_alt`
    /// (odd rows). Standard "striped" data-grid look. Default
    /// false; the caller opts in. Per-row override is available
    /// via `tableSetRowBgColor` after `tableNextRow`.
    row_bg: bool = false,
};

// DragDropSourceOpts removed - replaced by `DragDropFlags`
//. Use:
//   beginDragDropSource(.{.source_no_preview = true })
// instead of the old:
//   beginDragDropSource(.{.source_no_preview = true })

// ============================================================================
// Tree node flags
// ============================================================================
// Imgui equivalent: `ImGuiTreeNodeFlags` (imgui.h:1301-1333), 26 flag
// values translated per zimr's flag-decision rule (exclusive groups
// become enums, independents stay bools). All 13 fields exposed
// from day 1; ~7 wired effective in MVP, the rest marked
// `// TODO Step 1.x` with imgui line refs.

/// When does clicking on the tree node toggle its open state?
/// Exclusive group from imgui (`OpenOnDoubleClick` /
/// `OpenOnArrow` / default). Imgui line 1310-1311.
pub const TreeOpenTrigger = enum {
    /// Default: click anywhere on the row toggles.
    click_anywhere,
    /// Only clicking on the disclosure arrow toggles. Useful
    /// when the row body is also a Selectable (multi-select
    /// scope) - the arrow is the toggle, the body is the
    /// selection. Imgui: `OpenOnArrow`.
    click_arrow,
    /// Double-click toggles. Single click is a no-op (so the
    /// row can act as a Selectable for single-click). Imgui:
    /// `OpenOnDoubleClick`.
    double_click,
};

/// How wide does the tree node's hit box / highlight rect extend?
/// Exclusive group from imgui (`SpanAvailWidth` / `SpanFullWidth`
/// / `SpanLabelWidth` / `SpanAllColumns` / `LabelSpanAllColumns`).
/// Imgui lines 1315-1319.
pub const TreeNodeSpan = enum {
    /// Default: triangle + label, hit box just covers them.
    default,
    /// Extend hit box to right edge of content area. Useful for
    /// "click anywhere on the row" behavior (matches `treeNode`'s
    /// natural row-tap on phone). Imgui: `SpanAvailWidth`.
    avail_width,
    /// Extend hit box from left edge (covers indent area) to
    /// right edge. TODO Step 1.x - not wired in MVP; accepts
    /// but treated as `.avail_width`. Imgui: `SpanFullWidth`.
    full_width,
    /// Narrow hit box covering only the label. TODO Step 1.x;
    /// treated as `.default`. Imgui: `SpanLabelWidth`.
    label_width,
    /// Frame spans all columns of the container table. TODO
    /// Step 1.x - depends on table-column infra. Imgui:
    /// `SpanAllColumns`.
    all_columns,
    /// Label spans all columns. TODO Step 1.x. Imgui:
    /// `LabelSpanAllColumns`.
    label_all_columns,
};

/// Vertical-line connectors between tree levels. Imgui added
/// these in 1.92; visual polish. Imgui lines 1326-1328.
pub const TreeNodeDrawLines = enum {
    /// No connector lines (default). Imgui: `DrawLinesNone`.
    none,
    /// Horizontal lines to children + vertical line down to
    /// TreePop position. Faster for big trees. TODO Step 1.x.
    full,
    /// Horizontal lines to children + vertical line down to
    /// bottom-most child. Slower. TODO Step 1.x.
    to_nodes,
};

/// Flags for `treeNode`. Mirrors imgui's `ImGuiTreeNodeFlags`
/// (`imgui.h:1301-1333`). All 13 fields exist from day 1; check
/// inline comments for which are wired in MVP vs accepted-but-
/// ignored with TODO.
pub const TreeNodeOpts = struct {
    // ---- Exclusive groups ----
    /// When clicks toggle. See `TreeOpenTrigger`. ✓ MVP for
    /// `.click_anywhere` + `.click_arrow`; `.double_click`
    /// accepted but treated as `.click_anywhere`.
    open_trigger: TreeOpenTrigger = .click_anywhere,
    /// Hit-box / highlight width policy. See `TreeNodeSpan`.
    /// ✓ MVP for `.default` + `.avail_width`.
    span: TreeNodeSpan = .default,
    /// Connector-line drawing. See `TreeNodeDrawLines`. TODO
    /// Step 1.x - not wired in MVP.
    draw_lines: TreeNodeDrawLines = .none,

    // ---- Independent bools ---- (✓ MVP unless noted) ----
    /// Draw the node as selected. Useful with MultiSelect.
    /// Imgui: `Selected`. ✓ MVP.
    selected: bool = false,
    /// Draw a frame with background. Imgui's collapsing-header
    /// look (different widget in zimr but the flag is the same).
    /// Imgui: `Framed`. ✓ MVP.
    framed: bool = false,
    /// Allow hit-test layering with subsequent overlapping
    /// widgets. TODO Step 1.x - zimr's hit-test stacking model
    /// hasn't been factored for layered widgets yet. Imgui:
    /// `AllowOverlap`.
    allow_overlap: bool = false,
    /// Don't push indent or id-stack entry on open (collapsing-
    /// header behavior). TODO Step 1.x - zimr's
    /// `collapsingHeader` is a separate widget so this is only
    /// useful for advanced fold patterns. Imgui:
    /// `NoTreePushOnOpen`.
    no_tree_push_on_open: bool = false,
    /// Skip auto-open when logging is active. No logging in
    /// zimr. Imgui: `NoAutoOpenOnLog`.
    no_auto_open_on_log: bool = false,
    /// Initial open state for the node's first appearance.
    /// User clicks toggle from there. Imgui: `DefaultOpen`.
    /// ✓ MVP.
    default_open: bool = false,
    /// Leaf node - no arrow, no collapse. Calling code still
    /// pairs with `treePop` (returns true unconditionally so the
    /// caller's `if (treeNodeEx(...)) {... treePop(); }`
    /// pattern stays balanced). Imgui: `Leaf`. ✓ MVP.
    leaf: bool = false,
    /// Render a bullet instead of the disclosure triangle.
    /// Imgui: `Bullet`. ✓ MVP.
    bullet: bool = false,
    /// Use frame_padding for vertical alignment (matches
    /// regular widget height - useful when other widgets sit
    /// next to the tree node). Imgui: `FramePadding`. ✓ MVP.
    frame_padding: bool = false,
    /// Left-arrow nav jumps back to parent node. TODO Step 6.x
    /// - zimr's keyboard nav is minimal today. Imgui:
    /// `NavLeftJumpsToParent`.
    nav_left_jumps_to_parent: bool = false,
};

// ============================================================================
// Splitter
// ============================================================================
// Draggable bar between two adjacent panes. The caller owns a
// single `split_pos: f32` describing where the bar is along its
// axis; the splitter widget reads/writes it. Adjacent panes
// derive their sizes from `split_pos` (one is `split_pos` long
// from the splitter's start cursor, the other fills the remainder
// `total - split_pos - bar_width`).
// API shape: matches imgui's `SplitterBehavior`
// (`imgui_widgets.cpp:1801-1857`) in semantics but with two
// changes for zimr:
//   1. Single `*split_pos` instead of `*size1, *size2`. Zero-sum
//      math is implicit (caller derives `size2 = total - split_pos
//      - bar_width`). Equivalent expressive power, simpler call
//      site.
//   2. Phone-friendly `hit_extend` default (16px each side, so 36px
//      total hit zone with a 4px bar). Thin visible bar (looks pro);
//      generous interaction.

// ============================================================================
// MultiSelect
// ============================================================================
// Multi-selection scope wrapping a list of Selectable/Checkbox/etc items.
// Standard idioms: click=replace, Ctrl=toggle, Shift=range, Escape=clear,
// Ctrl+A=all, click-void=clear. Imgui's design: scope code emits a list
// of REQUESTS (SetAll/SetRange); your storage applies them. Decouples
// the scope logic from how you store selection.
// See `src/notes/multiselect-tutorial.md` for the conceptual walkthrough.
// Imgui source: `imgui.h:3026-3140`, `imgui_widgets.cpp:7995-8525`,
// `imgui_widgets.cpp:8583-8810` (storage).
// MVP coverage decisions:
// - `?u64` for selection user-data (idiomatic Zig optional, not `-1` sentinel).
// - SelectionBasicStorage WITHOUT the index→ID adapter - indexes ARE IDs.
//   Add adapter when a future reorderable-list demo proves it pays off.
// - HashMap on UiContext keyed by scope id for per-scope persistent state
//   (anchor, nav_id) - matches imgui's `g.MultiSelectStorage`.
// - Single active-scope slot (no nesting support) - adding stack later is
//   non-breaking.
// - 6 effective flags (`SingleSelect`, `NoSelectAll`, `NoRangeSelect`,
//   `NoAutoClearOnReselect`, `ClearOnEscape`, `ClearOnClickVoid`). Full
//   17-field struct surface; the 11 inert fields are accepted-but-ignored
//   with `// TODO Step 1.x` annotations citing imgui line refs.
// - Same `selectable()` signature - MS hooks are additive (matches imgui).

/// One selection mutation request emitted by the multi-select scope.
/// Tag union mirroring imgui's `ImGuiSelectionRequestType` +
/// `ImGuiSelectionRequest` payload (`imgui.h:3074-3090`).
/// `applyRequests` on your storage iterates a list of these and
/// updates state accordingly. See `src/notes/multiselect-tutorial.md`
/// § 4 + § 6 for the canonical apply body.
pub const SelectionRequest = union(enum) {
    /// Imgui: `ImGuiSelectionRequestType_SetAll`. If `selected ==
    /// true`, select every item from 0..items_count. If false,
    /// clear the selection. `items_count` is in the `MultiSelectIO`
    /// for the apply-time lookup.
    set_all: bool,
    /// Imgui: `ImGuiSelectionRequestType_SetRange`. Set every item
    /// in the inclusive range `first..=last` to `selected`.
    /// `direction` is `+1` if `first` came chronologically before
    /// `last` (top-to-bottom shift-click), `-1` if the other way
    /// (bottom-to-top); useful only if you want to preserve
    /// selection order on a backward Shift+click - most apps
    /// ignore it.
    set_range: struct {
        first: u64,
        last: u64,
        direction: i2,
        selected: bool,
    },
};

/// IO view returned by `beginMultiSelect` and `endMultiSelect`. Owned
/// by the UiContext (lives in the active `MultiSelectScope`); valid
/// until the next Begin/End on the same Ui. Imgui: `ImGuiMultiSelectIO`
/// (`imgui.h:3062-3071`).
/// Usage: call `selection.applyRequests(io)` on both the Begin-time IO
/// (drains pending requests from keyboard shortcuts / box-select drag
/// completion) and the End-time IO (drains this-frame's click-emitted
/// requests).
pub const MultiSelectIO = struct {
    /// Pending selection-mutation work. Slice into the active
    /// scope's request ArrayList; valid until next Begin/End.
    requests: []const SelectionRequest,
    /// The "anchor" item - where shift-click ranges start from.
    /// Survives across frames in `MultiSelectState`. `null` if no
    /// item has been selected yet in this scope's lifetime. When
    /// using a clipper, the user MUST ensure this item is
    /// submitted (zimr has no clipper yet, so this is
    /// informational). Imgui: `RangeSrcItem`.
    range_src_item: ?u64,
    /// Last item the keyboard nav was focused on. Used by
    /// deletion-aware UIs to re-focus after a delete (zimr's MVP
    /// doesn't implement deletion-aware focus; this is set but
    /// unused). Imgui: `NavIdItem`.
    nav_id_item: ?u64,
    /// Selected-state of `nav_id_item` (only meaningful when
    /// `nav_id_item != null`). Imgui: `NavIdSelected`.
    nav_id_selected: bool,
    /// Items_count argument passed to `beginMultiSelect`, echoed
    /// here for convenience inside `applyRequests`.
    items_count: u32,
};

/// Transient state for the in-progress Begin/End pair. Lives at
/// `UiContext.current_multi_select` (single-slot, no nesting in MVP).
/// Imgui: `ImGuiMultiSelectTempData` (`imgui_internal.h`).
/// Cleared at every `beginMultiSelect`; ArrayList capacity is
/// retained across frames to avoid re-allocation.
pub const MultiSelectScope = struct {
    /// Identity of the scope - top of the window's id stack at
    /// Begin time. Looked up in `UiContext.ms_storage` to find
    /// the persistent state.
    id: Id,
    /// Pointer to the persistent state in `UiContext.ms_storage`.
    /// Valid for the duration of the Begin/End pair (no map
    /// rehashes happen during a scope).
    storage: *MultiSelectState,
    /// Flags as configured at Begin. Imgui clears mutually
    /// inconsistent flag combinations here (e.g. SingleSelect
    /// strips box-select bits). We do the same in
    /// `beginMultiSelect`.
    flags: MultiSelectFlags,
    /// Snapshot of keyboard modifiers AT Begin time. Imgui
    /// captures these so multi-frame interactions don't require
    /// the user keep modifiers held the whole time
    /// (`imgui_widgets.cpp:8036-8039`).
    key_shift: bool,
    key_ctrl: bool,
    /// IO view, populated by Begin (with pending requests) and
    /// then again by End (with click-emitted requests).
    io: MultiSelectIO,
    /// Backing storage for `io.requests`. Reset at Begin start
    /// and at End start. Capacity grows on demand and is
    /// retained across frames.
    requests_buf: ArrayList(SelectionRequest),
    /// Set by Begin if there's a pending "apply this to every
    /// item submitted in the loop" override - used when SetAll
    /// requests need to take effect on items the user is about
    /// to render without waiting for the End-time apply. Imgui:
    /// `LoopRequestSetAll` - -1 = none, 0 = clear-all,
    /// 1 = select-all.
    loop_request_set_all: enum { none, clear, select } = .none,
    /// Set true once `SetNextItemSelectionUserData(item ==
    /// storage.range_src_item)` has been observed during the
    /// loop. Imgui: `RangeSrcPassedBy`. Used to determine
    /// SetRange direction when a shift-click resolves.
    range_src_passed_by: bool = false,
    /// True if this scope owns keyboard focus. Imgui:
    /// `IsFocused`. In MVP, we set this true when the scope's
    /// window is the focused window (no NavFocusScope routing
    /// yet).
    is_focused: bool = false,
    /// True after the End-time emit phase has started. Imgui
    /// uses this to discriminate "Begin populated pending
    /// requests" from "End is collecting fresh ones" - we mirror
    /// the same pattern for parity.
    is_end_io: bool = false,
};

/// Default storage helper for selection state. AutoHashMap of
/// selected indices (the `u64` payload of `SelectionUserData`). Most
/// applications can use this as-is; if you need something more
/// elaborate, you can implement `applyRequests` yourself against the
/// same `MultiSelectIO` shape.
/// Imgui: `ImGuiSelectionBasicStorage` (`imgui.h:3108-3127`,
/// `imgui_widgets.cpp:8583-8810`). Our MVP omits the
/// `AdapterIndexToStorageId` callback - indexes ARE IDs. Adding the
/// adapter later is non-breaking (identity == current behavior); see
/// `src/notes/imgui-plan.md` deferred section.
pub const SelectionBasicStorage = struct {
    /// Map of selected ids → present. Absence == not selected.
    /// `void`-valued map = pure set semantics, no per-entry
    /// payload.
    map: std.AutoHashMapUnmanaged(u64, void) = .{},

    pub fn deinit(self: *SelectionBasicStorage, gpa: Allocator) void {
        self.map.deinit(gpa);
    }

    /// Number of selected items. O(1) - backed by the HashMap's
    /// own count.
    pub fn size(self: *const SelectionBasicStorage) usize {
        return self.map.count();
    }

    /// True if `id` is currently in the selection. O(1).
    pub fn contains(self: *const SelectionBasicStorage, id: u64) bool {
        return self.map.contains(id);
    }

    /// Add `id` to the selection. No-op if already present.
    pub fn add(
        self: *SelectionBasicStorage,
        gpa: Allocator,
        id: u64,
    ) !void {
        try self.map.put(gpa, id, {});
    }

    /// Remove `id` from the selection. No-op if absent.
    pub fn remove(self: *SelectionBasicStorage, id: u64) void {
        _ = self.map.remove(id);
    }

    /// Clear all selected items. Retains the map's capacity for
    /// reuse.
    pub fn clear(self: *SelectionBasicStorage) void {
        self.map.clearRetainingCapacity();
    }

    /// Apply each request in `io.requests` to the selection.
    /// Conceptual O(N) per SetAll, O(R) per SetRange where N is
    /// `io.items_count` and R is range size.
    /// Imgui's optimized version
    /// (`imgui_widgets.cpp:8683-8810`) uses batched sorts for
    /// 100k+ item lists; the literal version below works fine for
    /// realistic UI scales. Re-do if/when someone has a
    /// performance complaint.
    pub fn applyRequests(
        self: *SelectionBasicStorage,
        gpa: Allocator,
        io: *const MultiSelectIO,
    ) !void {
        for (io.requests) |req| switch (req) {
            .set_all => |selected| {
                self.clear();
                if (selected) {
                    var idx: u64 = 0;
                    while (idx < io.items_count) : (idx += 1) {
                        try self.add(gpa, idx);
                    }
                }
            },
            .set_range => |r| {
                // Imgui range is inclusive at both ends. Walk
                // [first..=last] regardless of `direction`
                // direction only matters if the caller wants to
                // preserve selection ORDER for downstream UI (zimr
                // doesn't model order today).
                const lo: u64 = @min(r.first, r.last);
                const hi: u64 = @max(r.first, r.last);
                var idx: u64 = lo;
                while (idx <= hi) : (idx += 1) {
                    if (r.selected) {
                        try self.add(gpa, idx);
                    } else {
                        self.remove(idx);
                    }
                }
            },
        };
    }
};

pub const InputTextEvent = enum {
    char_filter,
    edit,
    completion,
    history,
};

pub const HistoryDir = enum { up, down };

/// Shared state passed to every `InputTextOpts` callback. Mirror
/// of imgui's `ImGuiInputTextCallbackData` adapted to zimr's
/// caller-owned-buffer model. No `BufDirty` flag (the callback
/// helpers mutate `buf_len`/`cursor_pos` directly) and no
/// selection fields (selection lands with multi-select in Phase C3).
pub const InputTextCallbackData = struct {
    /// Which callback event is firing right now. Read-only.
    event: InputTextEvent,

    /// Full buffer slice (capacity, not just current length).
    /// Mutable contents - callback can rewrite directly, but for
    /// non-trivial edits prefer `insertChars`/`deleteChars`/
    /// `setBuffer` so cursor + length tracking stays consistent.
    buf: []u8,

    /// Mutable pointer to the buffer's live byte length. Always
    /// `< buf.len`.
    buf_len: *usize,

    /// Mutable pointer to the caret position (byte offset within
    /// the live buffer). Always `<= buf_len.*`.
    cursor_pos: *usize,

    /// CharFilter only. The codepoint about to be inserted. Set
    /// to 0 to drop, or to a different codepoint to substitute.
    /// Read-write; ignored outside the CharFilter event.
    event_char: u32 = 0,

    /// History only. Which arrow triggered the callback.
    /// Read-only; meaningless outside the History event.
    history_dir: HistoryDir = .up,

    /// Opaque user context - same pointer passed via
    /// `InputTextOpts.user_data`. Cast back to your typed state.
    user_data: ?*anyopaque,

    /// Insert `text` at byte offset `pos`. Returns false if the
    /// insertion would overflow `buf.len`. Adjusts `buf_len.*`
    /// and shifts `cursor_pos.*` if the insertion happens at or
    /// before the cursor.
    pub fn insertChars(
        self: *InputTextCallbackData,
        pos: usize,
        text: []const u8,
    ) bool {
        const cur_len: usize = self.buf_len.*;
        const has_room: bool = (cur_len + text.len) <= self.buf.len;
        if (!has_room) {
            return false;
        }
        if (pos > cur_len) {
            return false;
        }
        std.mem.copyBackwards(
            u8,
            self.buf[pos + text.len .. cur_len + text.len],
            self.buf[pos..cur_len],
        );
        @memcpy(self.buf[pos .. pos + text.len], text);
        self.buf_len.* = cur_len + text.len;
        if (self.cursor_pos.* >= pos) {
            self.cursor_pos.* += text.len;
        }
        return true;
    }

    /// Delete `n` bytes starting at `pos`. Clamps to live length.
    /// Adjusts `cursor_pos.*` if the deletion overlaps or precedes
    /// the cursor.
    pub fn deleteChars(
        self: *InputTextCallbackData,
        pos: usize,
        n: usize,
    ) void {
        const cur_len: usize = self.buf_len.*;
        if (pos >= cur_len) {
            return;
        }
        const actual_n: usize = @min(n, cur_len - pos);
        std.mem.copyForwards(
            u8,
            self.buf[pos .. cur_len - actual_n],
            self.buf[pos + actual_n .. cur_len],
        );
        self.buf_len.* = cur_len - actual_n;
        const cursor: usize = self.cursor_pos.*;
        if (cursor > pos + actual_n) {
            self.cursor_pos.* = cursor - actual_n;
        } else if (cursor > pos) {
            self.cursor_pos.* = pos;
        }
    }

    /// Replace the entire buffer contents with `text`. Cursor
    /// moves to the end of `text`. Returns false if `text`
    /// wouldn't fit in `buf.len`.
    pub fn setBuffer(
        self: *InputTextCallbackData,
        text: []const u8,
    ) bool {
        if (text.len > self.buf.len) {
            return false;
        }
        @memcpy(self.buf[0..text.len], text);
        self.buf_len.* = text.len;
        self.cursor_pos.* = text.len;
        return true;
    }
};

/// Signature of every `InputTextOpts` callback. See
/// `InputTextCallbackData` for what the callback can read and
/// mutate. ImGui's `ImGuiInputTextCallback` is one type carrying
/// an `EventFlag` discriminator; zimr separates the slots on
/// `InputTextOpts` (one slot per event), but the callback signature
/// is uniform so dispatch is identical.
pub const InputTextCallback = *const fn (data: *InputTextCallbackData) void;

// ============================================================================
// Input layer tests — dense per-frame key-state array
// ============================================================================

test "Q1: KeyCode.MAX is the count sentinel, every other variant indexes a slot" {
    const max_idx: usize = @backingInt(KeyCode.MAX);
    // sanity: a few key positions
    try expect(@backingInt(KeyCode.a) < max_idx);
    try expect(@backingInt(KeyCode.enter) < max_idx);
    try expect(@backingInt(KeyCode.left_shift) < max_idx);
    try expect(@backingInt(KeyCode.kp_equal) < max_idx);
}

test "Q1: KeyCode.fromRaylib round-trips for the keys zimr surfaces" {
    // Sample of keys that should round-trip cleanly
    const samples = [_]struct { rk: types.KeyboardKey, kc: KeyCode }{
        .{ .rk = .a, .kc = .a },
        .{ .rk = .space, .kc = .space },
        .{ .rk = .enter, .kc = .enter },
        .{ .rk = .left_shift, .kc = .left_shift },
        .{ .rk = .right_control, .kc = .right_control },
        .{ .rk = .f7, .kc = .f7 },
        .{ .rk = .kp_5, .kc = .kp_5 },
    };
    for (samples) |s| {
        const got: ?KeyCode = KeyCode.fromRaylib(s.rk);
        try expectEqual(@as(?KeyCode, s.kc), got);
    }
}

test "Q1: KeyCode.fromRaylib returns null for unsupported raylib keys" {
    try expectEqual(@as(?KeyCode, null), KeyCode.fromRaylib(.null));
    try expectEqual(@as(?KeyCode, null), KeyCode.fromRaylib(.kb_menu));
}

test "Q1: KeyState default = all-false / duration 0" {
    const ks: KeyState = .{};
    try expect(!ks.down);
    try expect(!ks.pressed_this_frame);
    try expect(!ks.released_this_frame);
    try expectEqual(@as(u32, 0), ks.down_duration_frames);
}

test "Q1: InputSnapshot.keys defaults to MAX-sized array of zero KeyStates" {
    const s: InputSnapshot = .{};
    try expectEqual(@as(usize, @backingInt(KeyCode.MAX)), s.keys.len);
    // Spot-check several slots are zeroed
    try expect(!s.keys[@backingInt(KeyCode.a)].down);
    try expect(!s.keys[@backingInt(KeyCode.enter)].down);
    try expectEqual(@as(u32, 0), s.keys[@backingInt(KeyCode.space)].down_duration_frames);
}

test "Q1: edge-event logic (was_down/is_down → pressed/released combinations)" {
    // Simulate the four transitions the population loop computes.
    const cases = [_]struct { was: bool, is: bool, pressed: bool, released: bool, dur: u32 }{
        .{ .was = false, .is = false, .pressed = false, .released = false, .dur = 0 },
        .{ .was = false, .is = true, .pressed = true, .released = false, .dur = 0 },
        .{ .was = true, .is = true, .pressed = false, .released = false, .dur = 6 }, // prior was 5, now 6
        .{ .was = true, .is = false, .pressed = false, .released = true, .dur = 0 },
    };
    for (cases) |c| {
        const prior_dur: u32 = if (c.was) 5 else 0;
        const ks: KeyState = .{
            .down = c.is,
            .pressed_this_frame = c.is and !c.was,
            .released_this_frame = !c.is and c.was,
            .down_duration_frames = if (c.is) (if (c.was) prior_dur + 1 else 0) else 0,
        };
        try expectEqual(c.pressed, ks.pressed_this_frame);
        try expectEqual(c.released, ks.released_this_frame);
        try expectEqual(c.dur, ks.down_duration_frames);
    }
}

test "Q1: KeyCode.toRaylib is the inverse of fromRaylib for every surfaced key" {
    // Round-trip every KeyCode (skipping MAX) through toRaylib →
    // fromRaylib and confirm identity. Comptime iteration so a
    // missing field in either direction surfaces as a compile error.
    inline for (@typeInfo(KeyCode).@"enum".field_names) |kf_name| {
        if (comptime eql(u8, kf_name, "MAX")) {
            continue;
        }
        const kc: KeyCode = @field(KeyCode, kf_name);
        const rk: types.KeyboardKey = kc.toRaylib();
        const back: ?KeyCode = KeyCode.fromRaylib(rk);
        try expectEqual(@as(?KeyCode, kc), back);
    }
}

test "Q1: keyEventSnapshot builds a snapshot with one key fully primed" {
    const s: InputSnapshot = keyEventSnapshot(.space);
    const sp: KeyState = s.keys[@backingInt(KeyCode.space)];
    try expect(sp.down);
    try expect(sp.pressed_this_frame);
    try expect(!sp.released_this_frame);
    // No other key should be touched.
    const a: KeyState = s.keys[@backingInt(KeyCode.a)];
    try expect(!a.down);
    try expect(!a.pressed_this_frame);
}

test "Q1: snapshot modifier helpers aggregate left+right sides" {
    var s: InputSnapshot = .{};
    try expect(!snapshotShiftDown(&s));
    try expect(!snapshotCtrlDown(&s));

    // Right-shift alone counts.
    s.keys[@backingInt(KeyCode.right_shift)].down = true;
    try expect(snapshotShiftDown(&s));
    try expect(!snapshotCtrlDown(&s));

    // Both sides also counts.
    s.keys[@backingInt(KeyCode.left_shift)].down = true;
    try expect(snapshotShiftDown(&s));

    // Ctrl independent.
    s.keys[@backingInt(KeyCode.left_control)].down = true;
    try expect(snapshotCtrlDown(&s));

    // Releasing right side leaves left side still active.
    s.keys[@backingInt(KeyCode.right_shift)].down = false;
    try expect(snapshotShiftDown(&s));

    // Releasing left side too clears it.
    s.keys[@backingInt(KeyCode.left_shift)].down = false;
    try expect(!snapshotShiftDown(&s));
}

test "Q1: synthetic input injection via beginFrameRaw populates the key array" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1: inject Tab pressed. The new snapshot should show
    // it both via the raw array AND via the Ui handle's helpers.
    const u: Ui = ctx.beginFrameRaw(
        keyEventSnapshot(.tab),
        null,
        800,
        600,
        &gl_dummy,
        &shapes_dummy,
        &font_dummy,
    );
    try expect(u.isKeyDown(.tab));
    try expect(u.isKeyPressed(.tab));
    try expect(!u.isKeyReleased(.tab));
    try expect(!u.isKeyDown(.enter)); // sanity: untouched
}

