test "Q2: getState on never-put returns null" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { count: i32 = 0 };
    try expectEqual(@as(?*TestState, null), u.getState(TestState, 42));
}

test "Q2: putState + getState round trip" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { count: i32, label: u8 };
    const put_ptr: *TestState = blk: {
        const _r = u.getOrPutState(TestState, 7, .{});
        _r.value_ptr.* = .{ .count = 42, .label = 'X' };
        break :blk _r.value_ptr;
    };
    try expectEqual(@as(i32, 42), put_ptr.count);

    const got: ?*TestState = u.getState(TestState, 7);
    try expect(got != null);
    try expectEqual(@as(i32, 42), got.?.count);
    try expectEqual(@as(u8, 'X'), got.?.label);
}

test "Q2: type isolation — same id, different T, independent slots" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const StateA = struct { val: i32 };
    const StateB = struct { val: f32 };
    {
        const _r = u.getOrPutState(StateA, 100, .{});
        _r.value_ptr.* = .{ .val = 999 };
    }
    {
        const _r = u.getOrPutState(StateB, 100, .{});
        _r.value_ptr.* = .{ .val = 3.14 };
    }

    const a: *StateA = u.getState(StateA, 100).?;
    const b: *StateB = u.getState(StateB, 100).?;
    try expectEqual(@as(i32, 999), a.val);
    try expectEqual(@as(f32, 3.14), b.val);
}

test "Q2: putState overwrites prior value at same (T, id)" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { val: i32 };
    {
        const _r = u.getOrPutState(TestState, 5, .{});
        _r.value_ptr.* = .{ .val = 1 };
    }
    {
        const _r = u.getOrPutState(TestState, 5, .{});
        _r.value_ptr.* = .{ .val = 99 };
    }
    const got: *TestState = u.getState(TestState, 5).?;
    try expectEqual(@as(i32, 99), got.val);
}

test "Q2: returned pointer from putState lets caller mutate in place" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { val: i32 };
    const ptr: *TestState = blk: {
        const _r = u.getOrPutState(TestState, 0, .{});
        _r.value_ptr.* = .{ .val = 0 };
        break :blk _r.value_ptr;
    };
    ptr.val = 42;

    // getState retrieves the same slot — sees the mutation.
    const got: *TestState = u.getState(TestState, 0).?;
    try expectEqual(@as(i32, 42), got.val);
}

test "Q2: persist flag is recorded on the outer slot (inert until Q8)" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { val: i32 };
    {
        const _r = u.getOrPutState(TestState, 0, .{ .persist = true });
        _r.value_ptr.* = .{ .val = 1 };
    }

    const key: u64 = comptime extStorageKey(TestState);
    const slot: *ExtStorageSlot = ctx.ext_storage.getPtr(key).?;
    try expect(slot.has_persist);
}

test "Q2: persist flag stays sticky once set, across non-persist puts" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const TestState = struct { val: i32 };
    {
        const _r = u.getOrPutState(TestState, 0, .{ .persist = true });
        _r.value_ptr.* = .{ .val = 1 };
    }
    {
        const _r = u.getOrPutState(TestState, 1, .{ .persist = false });
        _r.value_ptr.* = .{ .val = 2 };
    }

    const key: u64 = comptime extStorageKey(TestState);
    const slot: *ExtStorageSlot = ctx.ext_storage.getPtr(key).?;
    // Sticky: T-level flag latches at first persist=true call.
    try expect(slot.has_persist);
}

test "Q2: ext_storage starts empty — zero allocation when unused" {
