}

// ============================================================================
// Widget primitive (B-path) tests — itemAdd / buttonBehavior
// ============================================================================

const TestEnv = struct {
    ctx: UiContext,
    gl_dummy: Gl = .{},
    shapes_dummy: shapes2d.ShapesTextureState = .{},
    font_dummy: text2d.FontCache = .{},

    fn init(gpa: Allocator) TestEnv {
        return .{ .ctx = UiContext.init(gpa) };
    }
    fn deinit(self: *TestEnv) void {
        self.ctx.deinit();
    }
    fn beginFrameWith(self: *TestEnv, snap: InputSnapshot) Ui {
        return self.ctx.beginFrameRaw(snap, null, 800, 600, &self.gl_dummy, &self.shapes_dummy, &self.font_dummy);
    }
};

test "Q3: itemAdd returns false when rect fully outside window" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const u: Ui = env.beginFrameWith(.{});
    const w: WindowHandle = u.window("test", .{}) orelse unreachable;
    defer w.close();

    // Rect at negative-Y is fully outside any window.
    const offscreen: Rectangle = .{ .x = 0, .y = -100, .width = 50, .height = 20 };
    try expect(!u.itemAdd(offscreen, 0xDEAD));
}

test "Q3: itemAdd returns true and sets hovered_id when mouse is over rect" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
