    const id: Id = 0xCAFE;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };
    try expect(u.itemAdd(rect, id));
    try expectEqual(id, env.ctx.hovered_id);
}

test "Q3: itemAdd does NOT set hovered_id when mouse is elsewhere" {
