test "Q3: buttonBehavior fires pressed on click-then-release inside rect" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const id: Id = 0x1234;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };

    // Frame 1: mouse click inside → just_activated, not yet pressed.
    var snap: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true, .mouse_left_clicked = true };
    var u: Ui = env.beginFrameWith(snap);
    var w: WindowHandle = u.window("t", .{}) orelse unreachable;
    var r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{});
    try expect(!r.pressed);
    try expect(r.just_activated);
    try expect(r.held);
    w.close();

    // Frame 2: release inside → pressed = true, just_deactivated.
    snap = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_released = true };
    u = env.beginFrameWith(snap);
    w = u.window("t", .{}) orelse unreachable;
    r = u.buttonBehavior(rect, id, .{});
    try expect(r.pressed);
    try expect(r.just_deactivated);
    w.close();
}

test "Q3: buttonBehavior does NOT fire pressed on release outside rect" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const id: Id = 0x1234;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };

    // Frame 1: click inside.
    var snap: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true, .mouse_left_clicked = true };
    var u: Ui = env.beginFrameWith(snap);
    var w: WindowHandle = u.window("t", .{}) orelse unreachable;
    _ = u.buttonBehavior(rect, id, .{});
    w.close();

    // Frame 2: drag-and-release OUTSIDE rect → no press.
    snap = .{ .mouse_pos = .{ 500, 500 }, .mouse_left_released = true };
    u = env.beginFrameWith(snap);
    w = u.window("t", .{}) orelse unreachable;
    const r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{});
    try expect(!r.pressed);
    try expect(r.just_deactivated);
    w.close();
}

test "Q3: buttonBehavior with repeat = true fires repeatedly while held" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const id: Id = 0x1234;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };

    // Frame 1: press.
    var snap: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true, .mouse_left_clicked = true };
    var u: Ui = env.beginFrameWith(snap);
    var w: WindowHandle = u.window("t", .{}) orelse unreachable;
    _ = u.buttonBehavior(rect, id, .{ .repeat = true });
    w.close();

    // Frame 2: hold past the 400ms initial delay. Synthesize the
    // passage of time by adjusting the active_id timestamps.
    env.ctx.active_id_press_time = 0;
    env.ctx.active_id_last_repeat_time = 0;
    env.ctx.frame_time_seconds = 1.0; // 1s elapsed, well past 400ms
    snap = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true };
    u = env.beginFrameWith(snap);
    w = u.window("t", .{}) orelse unreachable;
    const r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{ .repeat = true });
    try expect(r.pressed);
    try expect(r.held);
    w.close();
}

test "Q3: buttonBehavior without repeat does NOT fire while held" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const id: Id = 0x1234;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };

    var snap: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true, .mouse_left_clicked = true };
    var u: Ui = env.beginFrameWith(snap);
    var w: WindowHandle = u.window("t", .{}) orelse unreachable;
    _ = u.buttonBehavior(rect, id, .{});
    w.close();

    // Frame 2: still held, no repeat. Should NOT fire pressed.
    env.ctx.frame_time_seconds = 1.0;
    snap = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true };
    u = env.beginFrameWith(snap);
    w = u.window("t", .{}) orelse unreachable;
    const r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{}); // no repeat
    try expect(!r.pressed);
    try expect(r.held);
    w.close();
}

test "Q3: itemSize advances the layout cursor by `size`" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const u: Ui = env.beginFrameWith(.{});
    const w: WindowHandle = u.window("t", .{}) orelse unreachable;
    defer w.close();

    const cursor_before: Vec2 = env.ctx.current_window.?.layout.cursor_pos;
    u.itemSize(.{ 100, 30 });
    const cursor_after: Vec2 = env.ctx.current_window.?.layout.cursor_pos;
    // Y advanced (cursor wraps to next row), X resets to indent
    try expect(cursor_after[1] > cursor_before[1]);
}

test "Q3: buttonBehavior on focused widget fires pressed on Enter (kbd nav)" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const id: Id = 0x1234;
    const rect: Rectangle = .{ .x = 80, .y = 80, .width = 50, .height = 50 };

    env.ctx.nav_id = id;
    const u: Ui = env.beginFrameWith(keyEventSnapshot(.enter));
    const w: WindowHandle = u.window("t", .{}) orelse unreachable;
    defer w.close();

    // Important: register the rect with itemAdd so the nav system
    // sees it. buttonBehavior alone handles the activation, but
    // triggerNavActivate consults the registration trail.
    _ = u.itemAdd(rect, id);
    const r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{});
    try expect(r.pressed);
}

test "Q3: extension-author pattern — itemSize + itemAdd + buttonBehavior compose" {
    // The cumulative shape: a knob-like custom widget built
    // entirely from the 3 primitives + drawing. Verifies the
    // primitives suffice for the documented extension pattern.
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const snap: InputSnapshot = .{ .mouse_pos = .{ 110, 110 }, .mouse_left_clicked = true, .mouse_left_down = true };
    const u: Ui = env.beginFrameWith(snap);
    const w: WindowHandle = u.window("t", .{}) orelse unreachable;
    defer w.close();

    // Hypothetical custom widget body:
    const id: Id = hashStr(0, "knob");
    const size: Vec2 = .{ 40, 40 };
    const at: Vec2 = .{ 90, 90 };
    const rect: Rectangle = .{ .x = at[0], .y = at[1], .width = size[0], .height = size[1] };
    u.itemSize(size);
    if (u.itemAdd(rect, id)) {
        const r: Ui.ButtonResult = u.buttonBehavior(rect, id, .{});
        // Press THIS frame: just_activated is set.
        try expect(r.just_activated);
        try expect(r.held);
    } else {
        try expect(false); // unreachable in this layout
    }
}

