test "Q3 C-path: beginItem returns ItemCtx with valid id+rect, then endItem advances cursor" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const u: Ui = env.beginFrameWith(.{});
    const w: WindowHandle = u.window("t", .{}) orelse unreachable;
    defer w.close();

    const cursor_before: Vec2 = env.ctx.current_window.?.layout.cursor_pos;
    if (u.beginItem("widget", .{ .size = .{ 50, 30 } })) |it| {
        defer u.endItem(it);
        try expect(it.id != 0);
        try expectEqual(@as(f32, 50), it.rect.width);
        try expectEqual(@as(f32, 30), it.rect.height);
    } else {
        try expect(false);
    }
    const cursor_after: Vec2 = env.ctx.current_window.?.layout.cursor_pos;
    try expect(cursor_after[1] > cursor_before[1]);
}

test "Q3 C-path: beginItem reports hovered + held + pressed across frames" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();

    // Frame 1: click on widget.
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 400 } };

    // Mouse at (100, 100) — comfortably inside the 200×200 widget
    // even after the desktop-default style bump (title_bar_height
    // grew from 22 → 28, window_padding from 8 → 10).  The widget
    // starts at roughly (window_padding[0], title_bar_height +
    // window_padding[1]) = (10, 38) and extends to (210, 238); a
    // (100, 100) click is dead-center.  The previous (30, 30)
    // landed in the title bar under the new defaults.
    const snap1: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_down = true, .mouse_left_clicked = true };
    var u: Ui = env.beginFrameWith(snap1);
    var w: WindowHandle = u.window("t", wopts) orelse unreachable;
    if (u.beginItem("hit_me", .{ .size = .{ 200, 200 } })) |it| {
        defer u.endItem(it);
        try expect(it.hovered);
        try expect(it.held);
        try expect(it.just_activated);
    } else {
        try expect(false);
    }
    w.close();

    // Frame 2: release inside.
    const snap2: InputSnapshot = .{ .mouse_pos = .{ 100, 100 }, .mouse_left_released = true };
    u = env.beginFrameWith(snap2);
    w = u.window("t", wopts) orelse unreachable;
    if (u.beginItem("hit_me", .{ .size = .{ 200, 200 } })) |it| {
        defer u.endItem(it);
        try expect(it.pressed);
        try expect(it.just_deactivated);
    } else {
        try expect(false);
    }
    w.close();
}

test "Q3 C-path: beginItem returns null when window is missing" {
