}

test "Q3 C-path: id is stable across frames (same label → same id)" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();

    var id_frame1: Id = 0;
    {
        const u: Ui = env.beginFrameWith(.{});
        const w: WindowHandle = u.window("t", .{}) orelse unreachable;
        defer w.close();
        const it: Ui.ItemCtx = u.beginItem("knob", .{ .size = .{ 10, 10 } }).?;
        defer u.endItem(it);
        id_frame1 = it.id;
    }
    {
        const u: Ui = env.beginFrameWith(.{});
        const w: WindowHandle = u.window("t", .{}) orelse unreachable;
        defer w.close();
        const it: Ui.ItemCtx = u.beginItem("knob", .{ .size = .{ 10, 10 } }).?;
        defer u.endItem(it);
        try expectEqual(id_frame1, it.id);
    }
}

test "Q3 C-path + Q2 storage: extension widget pattern (custom state per id)" {
    // This is the documented extension-author pattern: get-or-put
    // per-id state via Q2, drive interaction via Q3's single-call.
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();

    const KnobState = struct { value: f32 = 0 };
    const u: Ui = env.beginFrameWith(.{});
    const w: WindowHandle = u.window("t", .{}) orelse unreachable;
    defer w.close();

    if (u.beginItem("knob", .{ .size = .{ 40, 40 } })) |it| {
        defer u.endItem(it);
        const r = u.getOrPutState(KnobState, it.id, .{});
        if (!r.found_existing) {
            r.value_ptr.* = .{};
        }
        r.value_ptr.value += 0.1; // simulate per-frame mutation
        try expect(r.value_ptr.value > 0);
    } else {
        try expect(false);
    }
}

