test "Q7: addArc emits a polyline cmd with non-zero point count" {
    var arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const A: Allocator = arena.allocator();
    var dl: DrawList = .{};
    defer dl.deinit(A);

    dl.addArc(
        A,
        .{ 100, 100 },
        50,
        0,
        pi, // half-circle
        0xFFFFFFFF,
        2,
        0, // auto segments
    );
    try expectEqual(@as(usize, 1), dl.cmds.items.len);
    switch (dl.cmds.items[0]) {
        .polyline => |p| {
            try expect(p.points.len >= 2);
            try expectEqual(@as(u32, 0xFFFFFFFF), p.col);
            try expect(!p.closed);
        },
        else => return error.WrongCmdKind,
    }
}

