test "Q7: addArc points lie ON the circle (within ~1 px of true)" {
    var arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const A: Allocator = arena.allocator();
    var dl: DrawList = .{};
    defer dl.deinit(A);
    const cx: f32 = 100;
    const cy: f32 = 100;
    const r: f32 = 50;
    dl.addArc(A, .{ cx, cy }, r, 0, 2.0 * pi, 0xFF, 1, 32);
    switch (dl.cmds.items[0]) {
        .polyline => |p| {
            for (p.points) |pt| {
                const dx: f32 = pt[0] - cx;
                const dy: f32 = pt[1] - cy;
                const dist: f32 = @sqrt(dx * dx + dy * dy);
                try expect(@abs(dist - r) < 1.0);
            }
        },
        else => return error.WrongCmdKind,
    }
}

