test "Q7: addPolygon emits N-2 triangles for an N-gon" {
    var arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const A: Allocator = arena.allocator();
    var dl: DrawList = .{};
    defer dl.deinit(A);
    // Pentagon: 5 points → 3 triangles
    const pentagon = [_]Vec2{
        .{ 0, 0 },
        .{ 1, 0 },
        .{ 1.5, 1 },
        .{ 0.5, 1.5 },
        .{ -0.5, 1 },
    };
    dl.addPolygon(A, &pentagon, 0xFF112233);
    try expectEqual(@as(usize, 3), dl.cmds.items.len);
    for (dl.cmds.items) |cmd| {
        switch (cmd) {
            .triangle_filled => |tf| try expectEqual(@as(u32, 0xFF112233), tf.col),
            else => return error.WrongCmdKind,
        }
    }
}

