// ============================================================================
// Style override guard (defer-RAII) tests
// ============================================================================

test "Q5: styleOverride changes the live style field" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const original: Color = ctx.style.text;
    const new_text: Color = .{ .r = 255, .g = 0, .b = 0, .a = 255 };

    const g: StyleGuard = u.styleOverride(.{ .text = new_text });
    try expectEqual(new_text, ctx.style.text);
    g.restore();
    try expectEqual(original, ctx.style.text);
}

test "Q5: styleOverride leaves unset fields untouched" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const before_button: Color = ctx.style.button;
    const before_border: Color = ctx.style.border;
    const g: StyleGuard = u.styleOverride(.{ .text = .{ .r = 1, .g = 2, .b = 3, .a = 4 } });
    // Untouched fields preserved.
    try expectEqual(before_button, ctx.style.button);
    try expectEqual(before_border, ctx.style.border);
    g.restore();
}

test "Q5: nested styleOverride restores in defer-stack order" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const original: Color = ctx.style.text;
    const red: Color = .{ .r = 255, .g = 0, .b = 0, .a = 255 };
    const blue: Color = .{ .r = 0, .g = 0, .b = 255, .a = 255 };

    const outer: StyleGuard = u.styleOverride(.{ .text = red });
    try expectEqual(red, ctx.style.text);
    {
        const inner: StyleGuard = u.styleOverride(.{ .text = blue });
        try expectEqual(blue, ctx.style.text);
        inner.restore();
        // After inner restore, back to outer's value.
        try expectEqual(red, ctx.style.text);
    }
    outer.restore();
    try expectEqual(original, ctx.style.text);
}

test "Q5: styleOverride with multiple fields restores all of them" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const orig_text: Color = ctx.style.text;
    const orig_button: Color = ctx.style.button;
    const orig_border: Color = ctx.style.border;
    const c: Color = .{ .r = 99, .g = 99, .b = 99, .a = 99 };

    const g: StyleGuard = u.styleOverride(.{
        .text = c,
        .button = c,
        .border = c,
    });
    try expectEqual(c, ctx.style.text);
    try expectEqual(c, ctx.style.button);
    try expectEqual(c, ctx.style.border);
    g.restore();
    try expectEqual(orig_text, ctx.style.text);
    try expectEqual(orig_button, ctx.style.button);
    try expectEqual(orig_border, ctx.style.border);
}

test "Q5: empty styleOverride (no fields set) is a no-op" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const before: Style = ctx.style;
    const g: StyleGuard = u.styleOverride(.{});
    // Nothing changed.
    try expectEqual(before.text, ctx.style.text);
    try expectEqual(before.button, ctx.style.button);
    g.restore();
    // Still nothing changed.
    try expectEqual(before.text, ctx.style.text);
}

test "Q5: restore is idempotent — calling twice doesn't corrupt" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const original: Color = ctx.style.text;
    const red: Color = .{ .r = 255, .g = 0, .b = 0, .a = 255 };

    const g: StyleGuard = u.styleOverride(.{ .text = red });
    g.restore();
    try expectEqual(original, ctx.style.text);
    // Second call writes the captured prior again — same value.
    g.restore();
    try expectEqual(original, ctx.style.text);
}

test "Q5: works with non-color fields too (Vec2 style fields)" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const before: Vec2 = ctx.style.frame_padding;
    const new_padding: Vec2 = .{ 20, 30 };
    const g: StyleGuard = u.styleOverride(.{ .frame_padding = new_padding });
    try expectEqual(new_padding, ctx.style.frame_padding);
    g.restore();
    try expectEqual(before, ctx.style.frame_padding);
}

test "Q5: errdefer-safety — restore runs even when scope returns early" {
    // Simulates the common error-path pattern: function takes a
    // styleOverride, may return an error early; defer-restore must
    // fire on either path. This test exercises the success path
    // (defer fires after return); the language guarantees the
    // error path identically.
    const Inner = struct {
        fn run(uu: Ui, c: Color) Color {
            const guard: StyleGuard = uu.styleOverride(.{ .text = c });
            defer guard.restore();
            return uu.ctx.style.text; // value inside the scope
        }
    };
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    const original: Color = ctx.style.text;
    const red: Color = .{ .r = 255, .g = 0, .b = 0, .a = 255 };
    const inside: Color = Inner.run(u, red);
    try expectEqual(red, inside);
    // After the inner scope returned, defer fired → style restored.
    try expectEqual(original, ctx.style.text);
}

