test "Q4: beginCanvas + endCanvas brackets the window drawlist with push/pop clip" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const u: Ui = env.beginFrameWith(.{});
    const w: WindowHandle = u.window("host", .{}) orelse unreachable;
    defer w.close();

    const cmds_before: usize = env.ctx.current_window.?.draw_list.cmds.items.len;
    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 100, 80 }, .{}) orelse unreachable;
    const cmds_after_begin: usize = env.ctx.current_window.?.draw_list.cmds.items.len;
    u.endCanvas(c);
    const cmds_after_end: usize = env.ctx.current_window.?.draw_list.cmds.items.len;

    // begin appended push_clip (+1), end appended pop_clip (+1).
    try expectEqual(cmds_before + 1, cmds_after_begin);
    try expectEqual(cmds_after_begin + 1, cmds_after_end);

    // Verify the cmd kinds.
    const dl: *DrawList = &env.ctx.current_window.?.draw_list;
    switch (dl.cmds.items[cmds_after_begin - 1]) {
        .push_clip => {}, // ok
        else => return error.ExpectedPushClip,
    }
    switch (dl.cmds.items[cmds_after_end - 1]) {
        .pop_clip => {}, // ok
        else => return error.ExpectedPopClip,
    }
}

