test "Q4: canvas.localMouse returns mouse coords relative to canvas top-left" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    var snap: InputSnapshot = .{};
    snap.mouse_pos = .{ 200, 150 };
    const u: Ui = env.beginFrameWith(snap);
