    const w: WindowHandle = u.window("host", wopts) orelse unreachable;
    defer w.close();

    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 200, 100 }, .{}) orelse unreachable;
    defer u.endCanvas(c);
    const lm: Vec2 = c.localMouse();
    // canvas top-left = cursor at submission time = window pos +
    // window padding. Independent of the exact offset, the
    // invariant is: lm + rect.{x,y} == mouse_pos.
    try expectEqual(@as(f32, 200), lm[0] + c.rect.x);
    try expectEqual(@as(f32, 150), lm[1] + c.rect.y);
