test "Q4c: toScreen is the inverse of localMouse (round-trip)" {
    // The big design invariant: if you call toScreen(localMouse())
    // you should get back the actual screen mouse position.
    // Authoring-space coords → screen via toScreen, screen coords
    // → authoring via localMouse, the loop must close.
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const snap: InputSnapshot = .{ .mouse_pos = .{ 250, 175 } };
    const u: Ui = env.beginFrameWith(snap);
    const wopts: WindowOpts = .{ .initial_pos = .{ 30, 30 }, .initial_size = .{ 500, 400 } };
    const w: WindowHandle = u.window("host", wopts) orelse unreachable;
    defer w.close();

    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 400, 300 }, .{}) orelse unreachable;
    defer u.endCanvas(c);

    // Identity transform first.
    const lm0: Vec2 = c.localMouse();
    const round0: Vec2 = c.toScreen(lm0);
    try expect(@abs(round0[0] - 250) < 0.001);
    try expect(@abs(round0[1] - 175) < 0.001);

    // With pan + zoom too.
    c.pushTransform(.{ 25, 35 }, .{ 1.5, 1.5 });
    defer c.popTransform();
    const lm1: Vec2 = c.localMouse();
    const round1: Vec2 = c.toScreen(lm1);
    try expect(@abs(round1[0] - 250) < 0.001);
    try expect(@abs(round1[1] - 175) < 0.001);
}

test "Q4c: canvas.hovered() is false when a sibling window covers the canvas" {
    // 422c hover guard: even with mouse in the canvas rect,
    // `hovered()` returns false if the topmost window at the
    // mouse position isn't the canvas's parent.
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    const snap: InputSnapshot = .{ .mouse_pos = .{ 100, 100 } };
    const u: Ui = env.beginFrameWith(snap);
    const wopts_back: WindowOpts = .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 400, 400 } };
    const w_back: WindowHandle = u.window("back", wopts_back) orelse unreachable;
    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 300, 300 }, .{}) orelse unreachable;
    u.endCanvas(c);
    w_back.close();

    // Simulate a popup/sibling overlay claiming the hover by
    // pointing `hovered_window_id` at a different window.
    env.ctx.hovered_window_id = 0xDEAD;
    try expect(!c.hovered());

    // Restore to the canvas's parent — hover should re-engage.
    env.ctx.hovered_window_id = c.window.id;
    try expect(c.hovered());
}

