test "Q4b: CanvasTransform compose translate+scale" {
    const parent: CanvasTransform = .{ .translate = .{ 100, 200 }, .scale = .{ 2, 2 } };
    const child: CanvasTransform = .{ .translate = .{ 10, 10 } };
    // Child translate composed: 10*parent.scale + parent.translate
    // = 20 + 100 = 120
    const composed: CanvasTransform = parent.compose(child);
    try expectEqual(@as(Vec2, .{ 120, 220 }), composed.translate);
    try expectEqual(@as(Vec2, .{ 2, 2 }), composed.scale);
