test "Q4b: CanvasTransform inverse is a true inverse (round-trip applyPoint)" {
    const t: CanvasTransform = .{ .translate = .{ 50, -30 }, .scale = .{ 4, 0.5 } };
    const inv: CanvasTransform = t.inverse();
    const p: Vec2 = .{ 7, 11 };
    const projected: Vec2 = t.applyLocal(p);
    const back: Vec2 = inv.applyLocal(projected);
    // Float math — be lenient.
    try expect(@abs(back[0] - p[0]) < 0.001);
    try expect(@abs(back[1] - p[1]) < 0.001);
}

test "Q4b: CanvasTransform inverse handles zero scale safely (no NaN)" {
    const t: CanvasTransform = .{ .translate = .{ 10, 10 }, .scale = .{ 0, 0 } };
    const inv: CanvasTransform = t.inverse();
