}

test "Q4b: pushTransform then localMouse returns coords in authoring space" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    var snap: InputSnapshot = .{};
    snap.mouse_pos = .{ 200, 200 };
    const u: Ui = env.beginFrameWith(snap);
    const wopts: WindowOpts = .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 400, 400 } };
    const w: WindowHandle = u.window("host", wopts) orelse unreachable;
    defer w.close();

    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 200, 200 }, .{}) orelse unreachable;
    defer u.endCanvas(c);

    // No transforms: localMouse == screen mouse minus canvas origin.
    const lm_no_xf: Vec2 = c.localMouse();

    // Push a pan: translate by (50, 50). Now authoring space is
    // shifted, so the same screen mouse should be 50 units LESS
    // in each axis when reported in local coords.
    c.pushTransform(.{ 50, 50 }, .{ 1, 1 });
    const lm_after_pan: Vec2 = c.localMouse();
    try expectEqual(lm_no_xf[0] - 50, lm_after_pan[0]);
    try expectEqual(lm_no_xf[1] - 50, lm_after_pan[1]);
    c.popTransform();

    // After pop: back to identity.
    const lm_after_pop: Vec2 = c.localMouse();
    try expectEqual(lm_no_xf, lm_after_pop);
}

test "Q4b: pushTransform with scale halves localMouse coords (zoom in 2x)" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();
    var snap: InputSnapshot = .{};
    snap.mouse_pos = .{ 200, 200 };
    const u: Ui = env.beginFrameWith(snap);
    const wopts: WindowOpts = .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 400, 400 } };
    const w: WindowHandle = u.window("host", wopts) orelse unreachable;
    defer w.close();

    const c: Ui.CanvasCtx = u.beginCanvas("c", .{ 200, 200 }, .{}) orelse unreachable;
    defer u.endCanvas(c);

    const lm_no_xf: Vec2 = c.localMouse();
    c.pushTransform(.{ 0, 0 }, .{ 2, 2 });
    const lm_zoomed: Vec2 = c.localMouse();
    // 2x zoom: authoring-space coord is half the screen-canvas coord.
    try expect(@abs(lm_zoomed[0] - lm_no_xf[0] / 2) < 0.001);
    try expect(@abs(lm_zoomed[1] - lm_no_xf[1] / 2) < 0.001);
