test "InputMode: every enum variant maps to a non-empty attr string" {
    // Exhaustive guard: if a new variant is added to InputMode
    // without a `toAttr` case, the switch in `toAttr` fails to
    // compile.  This test reinforces that — every variant goes
    // through `toAttr` with a non-empty result.
    inline for (@typeInfo(InputMode).@"enum".field_values) |f_value| {
        const v: InputMode = @fromBackingInt(@intCast(f_value));
        const s: []const u8 = v.toAttr();
        try expect(s.len > 0);
    }
}

test "InputTextOpts: input_mode defaults to .text" {
    const opts: InputTextOpts = .{};
    try expectEqual(InputMode.text, opts.input_mode);
}

test "InputTextOpts: input_mode field is settable through the struct literal" {
    const opts: InputTextOpts = .{ .input_mode = .numeric };
    try expectEqual(InputMode.numeric, opts.input_mode);
    try expectEqualStrings("numeric", opts.input_mode.toAttr());
