test "P9.1: chars_* filter flags default to false" {
    const opts: InputTextOpts = .{};
    try expect(!opts.chars_decimal);
    try expect(!opts.chars_hexadecimal);
    try expect(!opts.chars_scientific);
    try expect(!opts.chars_uppercase);
    try expect(!opts.chars_no_blank);
}

inline fn isDecimalChar(cp: u32) bool {
    return (cp >= '0' and cp <= '9') or cp == '.' or cp == '+' or cp == '-';
}

inline fn isHexChar(cp: u32) bool {
    return (cp >= '0' and cp <= '9') or
        (cp >= 'a' and cp <= 'f') or
        (cp >= 'A' and cp <= 'F');
}

inline fn isScientificChar(cp: u32) bool {
    return isDecimalChar(cp) or cp == 'e' or cp == 'E';
}

/// Apply the declarative `chars_*` filter flags from `opts`.
/// Returns 0 ("drop") if the codepoint fails any active filter,
/// the (possibly rewritten) codepoint otherwise.  Pulled out so
/// it can be unit-tested without standing up an InputText.
///
/// Multi-flag semantics: when two filters allow disjoint sets
/// (e.g. `chars_decimal` + `chars_hexadecimal`), the intersection
/// is enforced — a character has to pass each set independently.
/// In practice callers typically set only one of the accept-list
/// filters at a time; `chars_no_blank` and `chars_uppercase`
/// compose orthogonally with anything.
fn applyCharsFlagFilters(opts: InputTextOpts, cp_in: u32) u32 {
    var cp: u32 = cp_in;
    if (opts.chars_uppercase and cp >= 'a' and cp <= 'z') {
        cp = cp - 'a' + 'A';
    }
    if (opts.chars_no_blank and (cp == ' ' or cp == '\t')) {
        return 0;
    }
    if (opts.chars_decimal and !isDecimalChar(cp)) {
        return 0;
    }
    if (opts.chars_hexadecimal and !isHexChar(cp)) {
        return 0;
    }
    if (opts.chars_scientific and !isScientificChar(cp)) {
        return 0;
    }
    return cp;
}

test "P9.1: chars_decimal accepts digits + .+- and drops the rest" {
    const opts: InputTextOpts = .{ .chars_decimal = true };
    // Accept.
    try expectEqual(@as(u32, '0'), applyCharsFlagFilters(opts, '0'));
    try expectEqual(@as(u32, '9'), applyCharsFlagFilters(opts, '9'));
    try expectEqual(@as(u32, '.'), applyCharsFlagFilters(opts, '.'));
    try expectEqual(@as(u32, '+'), applyCharsFlagFilters(opts, '+'));
    try expectEqual(@as(u32, '-'), applyCharsFlagFilters(opts, '-'));
    // Drop letters, symbols, whitespace.
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'e'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, ' '));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, '/'));
}

test "P9.1: chars_hexadecimal accepts 0-9 a-f A-F only" {
    const opts: InputTextOpts = .{ .chars_hexadecimal = true };
    try expectEqual(@as(u32, '0'), applyCharsFlagFilters(opts, '0'));
    try expectEqual(@as(u32, 'a'), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, 'F'), applyCharsFlagFilters(opts, 'F'));
    // Drops the rest.
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'g'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'G'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, '.'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, '-'));
}

test "P9.1: chars_scientific is a superset of decimal with eE added" {
    const opts: InputTextOpts = .{ .chars_scientific = true };
    // Decimal characters still accepted.
    try expectEqual(@as(u32, '5'), applyCharsFlagFilters(opts, '5'));
    try expectEqual(@as(u32, '.'), applyCharsFlagFilters(opts, '.'));
    try expectEqual(@as(u32, '-'), applyCharsFlagFilters(opts, '-'));
    // Plus the exponent letters.
    try expectEqual(@as(u32, 'e'), applyCharsFlagFilters(opts, 'e'));
    try expectEqual(@as(u32, 'E'), applyCharsFlagFilters(opts, 'E'));
    // Other letters still rejected.
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'x'));
}

test "P9.1: chars_uppercase rewrites a-z, leaves others alone" {
    const opts: InputTextOpts = .{ .chars_uppercase = true };
    // Rewrites.
    try expectEqual(@as(u32, 'A'), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, 'Z'), applyCharsFlagFilters(opts, 'z'));
    // Already uppercase passes through.
    try expectEqual(@as(u32, 'A'), applyCharsFlagFilters(opts, 'A'));
    // Digits, symbols, whitespace untouched.
    try expectEqual(@as(u32, '5'), applyCharsFlagFilters(opts, '5'));
    try expectEqual(@as(u32, '-'), applyCharsFlagFilters(opts, '-'));
    try expectEqual(@as(u32, ' '), applyCharsFlagFilters(opts, ' '));
}

test "P9.1: chars_no_blank drops space and tab only" {
    const opts: InputTextOpts = .{ .chars_no_blank = true };
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, ' '));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, '\t'));
    // Newline passes — multiline owns newline policy.
    try expectEqual(@as(u32, '\n'), applyCharsFlagFilters(opts, '\n'));
    // Visible characters pass through.
    try expectEqual(@as(u32, 'a'), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, '_'), applyCharsFlagFilters(opts, '_'));
}

test "P9.1: chars_uppercase composes with chars_hexadecimal" {
    // 'a' first uppercases to 'A', which then passes the hex filter.
    // 'g' uppercases to 'G' but G isn't a hex digit, so it drops.
    const opts: InputTextOpts = .{ .chars_uppercase = true, .chars_hexadecimal = true };
    try expectEqual(@as(u32, 'A'), applyCharsFlagFilters(opts, 'a'));
    try expectEqual(@as(u32, 'F'), applyCharsFlagFilters(opts, 'f'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, 'g'));
    try expectEqual(@as(u32, 0), applyCharsFlagFilters(opts, '.'));
    try expectEqual(@as(u32, '0'), applyCharsFlagFilters(opts, '0'));
}

/// Run the CharFilter callback (if any) over `original_cp`.
/// Returns the (possibly substituted) codepoint the caller should
/// actually insert; 0 means "drop, don't insert." Inlined into
/// the per-char insert loop, so it's marked inline.
///
/// Order of operations matches imgui:
///   1. Declarative `chars_*` flag filters reject / rewrite first.
///   2. The user's `char_filter` callback runs on whatever survives.
/// A character has to pass ALL flag filters that are set.  Filters
/// only see codepoints arriving via keystroke; paste, `setBuffer`,
/// and `insertChars` from inside callbacks bypass them.
inline fn runCharFilter(
    opts: InputTextOpts,
    buf: []u8,
    buf_len: *usize,
    cursor_pos: *usize,
    original_cp: u32,
) u32 {
    const cp: u32 = applyCharsFlagFilters(opts, original_cp);
    if (cp == 0) {
        return 0;
    }
    const cb: InputTextCallback = opts.char_filter orelse return cp;
    var data: InputTextCallbackData = .{
        .event = .char_filter,
        .buf = buf,
        .buf_len = buf_len,
        .cursor_pos = cursor_pos,
        .event_char = cp,
        .history_dir = .up,
        .user_data = opts.user_data,
    };
    cb(&data);
    return data.event_char;
}

test "P9.1: runCharFilter applies flag filters before user callback" {
    // The flag-filter rewrites 'a' → 'A' (uppercase) before the
    // user callback sees it.  The callback then converts every 'A'
    // it sees to 'Z'.  Final: 'a' arrives as 'Z'.  Verifies the
    // ordering documented in runCharFilter's doc comment.
    const cb = struct {
        fn fn_(data: *InputTextCallbackData) void {
            if (data.event_char == 'A') data.event_char = 'Z';
        }
    }.fn_;
    var buf: [16]u8 = undefined;
    var buf_len: usize = 0;
    var cursor: usize = 0;
    const opts: InputTextOpts = .{ .chars_uppercase = true, .char_filter = cb };
    const out: u32 = runCharFilter(opts, &buf, &buf_len, &cursor, 'a');
    try expectEqual(@as(u32, 'Z'), out);

    // A flag-filter rejection short-circuits — the callback never
    // runs on a dropped char.  chars_decimal drops 'x' before the
    // callback (which would otherwise rewrite it to 'Z') could see.
    const opts2: InputTextOpts = .{ .chars_decimal = true, .char_filter = cb };
    const out2: u32 = runCharFilter(opts2, &buf, &buf_len, &cursor, 'x');
    try expectEqual(@as(u32, 0), out2);
}

// ============================================================================
// P9.2 InputText behavior-flag tests
// ============================================================================
// These are the first host-path tests for inputText edit operations.
// Each test stands up a minimal UiContext + Window, force-focuses
// the widget by setting active_id = widgetId, then injects
// keystrokes via ctx.input fields and calls u.inputText().
// Shared setup logic lives in `setupInputTextForTest`.

/// Stand up a minimal UiContext + Window suitable for hosting one
/// inputText widget.  Returns the widget id pre-computed so tests
/// can force-focus via `ctx.active_id = id`.  The caller is
/// expected to deinit the draw_list and the ctx separately.
fn setupInputTextForTest(
    ctx: *UiContext,
    w: *Window,
    label: []const u8,
) Id {
    ctx.current_window = w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };
    return widgetId(ctx, w, label);
}

/// Push one printable codepoint into the typed-char queue.  Each
/// test that wants to inject characters builds the queue then
/// calls inputText so the per-frame insert loop sees them.
fn pushTypedChar(ctx: *UiContext, cp: u32) void {
    const i: usize = ctx.input.chars_typed_count;
    ctx.input.chars_typed[i] = cp;
    ctx.input.chars_typed_count = i + 1;
}

/// Returns the slice to RENDER in place of the live buffer.
/// When `opts.password_mask` is false: returns `buf` unchanged
/// (zero-copy passthrough).  When true: fills `mask_buf` with
/// `*` characters and returns the relevant prefix.  The
/// mask emits ONE asterisk per buffer byte — fine for ASCII;
/// when multi-byte UTF-8 lands, this becomes "one asterisk per
/// codepoint" instead.  Caller owns `mask_buf` and sizes it >=
/// expected max buffer length; truncation is silent (the
/// rendered slice is just shorter than the real buffer, which
/// is acceptable since password fields are typically short).
fn passwordMaskText(
    opts: InputTextOpts,
    buf: []const u8,
    mask_buf: []u8,
) []const u8 {
    if (!opts.password_mask) {
        return buf;
    }
    const n: usize = @min(buf.len, mask_buf.len);
    @memset(mask_buf[0..n], '*');
    return mask_buf[0..n];
}

test "P9.2: passwordMaskText off returns buf unchanged; on returns asterisks" {
    var mask_buf: [16]u8 = undefined;
    const buf: []const u8 = "secret";

    // off → zero-copy passthrough; same pointer + length.
    const off_opts: InputTextOpts = .{};
    const out_off: []const u8 = passwordMaskText(off_opts, buf, &mask_buf);
    try expectEqualStrings("secret", out_off);

    // on → length matches, contents are all asterisks.
    const on_opts: InputTextOpts = .{ .password_mask = true };
    const out_on: []const u8 = passwordMaskText(on_opts, buf, &mask_buf);
    try expectEqualStrings("******", out_on);

    // Empty buffer round-trips cleanly.
    const out_empty: []const u8 = passwordMaskText(on_opts, "", &mask_buf);
    try expectEqual(@as(usize, 0), out_empty.len);
}

test "P9.2: P9.2 flags default to false on InputTextOpts" {
    const opts: InputTextOpts = .{};
    try expect(!opts.enter_returns_true);
    try expect(!opts.escape_clears);
    try expect(!opts.password_mask);
    try expect(!opts.read_only);
    try expect(!opts.allow_tab_input);
}

/// Pack the 5 `chars_*` flag fields from `opts` into a bitmask
/// matching the constants in `web.zig` so the JS-side 'input'
/// event listener can apply the same accept/reject logic the
/// host-path `applyCharsFlagFilters` uses.  See turn 440c — the
/// host-path filter was a no-op on web because the DOM input is
/// the editor and wasm only polls the final value.
fn packCharFilterFlags(opts: InputTextOpts) u32 {
    var flags: u32 = 0;
    const dom = web.dom;
    if (opts.chars_decimal) {
        flags |= dom.CHAR_FILTER_DECIMAL;
    }
    if (opts.chars_hexadecimal) {
        flags |= dom.CHAR_FILTER_HEXADECIMAL;
    }
    if (opts.chars_scientific) {
        flags |= dom.CHAR_FILTER_SCIENTIFIC;
    }
    if (opts.chars_uppercase) {
        flags |= dom.CHAR_FILTER_UPPERCASE;
    }
    if (opts.chars_no_blank) {
        flags |= dom.CHAR_FILTER_NO_BLANK;
    }
    return flags;
}

test "P9.1 web: packCharFilterFlags bitmask matches CHAR_FILTER_* constants" {
    // The JS-side 'input' event listener relies on this exact bit
    // layout.  If the bits drift here, web-path filtering goes
    // silently wrong.  Lock the mapping.
    const dom = web.dom;
    try expectEqual(@as(u32, 0), packCharFilterFlags(.{}));
    try expectEqual(dom.CHAR_FILTER_DECIMAL, packCharFilterFlags(.{ .chars_decimal = true }));
    try expectEqual(dom.CHAR_FILTER_HEXADECIMAL, packCharFilterFlags(.{ .chars_hexadecimal = true }));
    try expectEqual(dom.CHAR_FILTER_SCIENTIFIC, packCharFilterFlags(.{ .chars_scientific = true }));
    try expectEqual(dom.CHAR_FILTER_UPPERCASE, packCharFilterFlags(.{ .chars_uppercase = true }));
    try expectEqual(dom.CHAR_FILTER_NO_BLANK, packCharFilterFlags(.{ .chars_no_blank = true }));

    // Multi-flag composition: bitmask is the OR of active flags.
    const all_opts: InputTextOpts = .{
        .chars_decimal = true,
        .chars_hexadecimal = true,
        .chars_scientific = true,
        .chars_uppercase = true,
        .chars_no_blank = true,
    };
    const expected: u32 = dom.CHAR_FILTER_DECIMAL |
        dom.CHAR_FILTER_HEXADECIMAL |
        dom.CHAR_FILTER_SCIENTIFIC |
        dom.CHAR_FILTER_UPPERCASE |
        dom.CHAR_FILTER_NO_BLANK;
    try expectEqual(expected, packCharFilterFlags(all_opts));
}

