test "P9.2 multiline: default Enter inserts \\n" {
    // Default behavior (ctrl_enter_for_newline = false): plain
    // Enter inserts a newline byte at the cursor.  Same as zimr's
    // existing multiline behavior.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    const id: Id = setupInputTextForTest(&ctx, &w, "field");
    ctx.active_id = id;
    ctx.input_text_state.cursor_pos = 2;
    ctx.input.keys[@backingInt(KeyCode.enter)].pressed_this_frame = true;

    var buf: [32]u8 = undefined;
    buf[0..2].* = "hi".*;
    var len: usize = 2;

    const u: Ui = .{ .ctx = &ctx };
    _ = u.inputTextMultiline("field", &buf, &len, .{ 200, 100 }, .{});

    try expectEqual(@as(usize, 3), len);
    try expectEqualStrings("hi\n", buf[0..len]);
    try expectEqual(id, ctx.active_id); // still focused
}

