// ============================================================================
// P9.3 — InputText callback contracts (turn 442)
// ============================================================================
// All four callbacks (`char_filter`, `edit`, `completion`,
// `history`) already exist on `InputTextOpts` and are wired
// into both `inputTextImpl` and (for `char_filter` + `edit`)
// `inputTextMultilineImpl`.  These tests pin down WHEN each
// fires + WHAT each receives, so future refactors can't
// silently break the contracts.
//
// Web-path note: only `edit` is reliably observable on web (the
// DOM path triggers `changed=true` via length-change polling, and
// the existing `if (changed) opts.edit` dispatch fires the same
// way on host and web).  `char_filter`, `completion`, and
// `history` are HOST-ONLY today because they depend on wasm-side
// keyboard events the DOM input/textarea overlay swallows.  See
// the field docs on `InputTextOpts` for the per-callback
// breakdown.  Web-path parity for these is a future turn.

const CbCounter = struct {
    edit_count: usize = 0,
    completion_count: usize = 0,
    history_count: usize = 0,
    history_dirs: [16]HistoryDir = undefined,
    char_filter_count: usize = 0,
    last_buf_len_seen: usize = 0,
    last_cursor_seen: usize = 0,
};

fn editCounterCb(d: *InputTextCallbackData) void {
    const c: *CbCounter = @ptrCast(@alignCast(d.user_data.?));
    c.edit_count += 1;
    c.last_buf_len_seen = d.buf_len.*;
    c.last_cursor_seen = d.cursor_pos.*;
}

fn completionCounterCb(d: *InputTextCallbackData) void {
    const c: *CbCounter = @ptrCast(@alignCast(d.user_data.?));
    c.completion_count += 1;
}

fn historyCounterCb(d: *InputTextCallbackData) void {
    const c: *CbCounter = @ptrCast(@alignCast(d.user_data.?));
    if (c.history_count < c.history_dirs.len) {
        c.history_dirs[c.history_count] = d.history_dir;
    }
    c.history_count += 1;
}

fn charFilterDropDigitsCb(d: *InputTextCallbackData) void {
    const c: *CbCounter = @ptrCast(@alignCast(d.user_data.?));
    c.char_filter_count += 1;
    if (d.event_char >= '0' and d.event_char <= '9') {
        d.event_char = 0; // drop
    }
}

test "P9.3: edit callback fires when buffer changes via typed char" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    const id: Id = setupInputTextForTest(&ctx, &w, "field");
    ctx.active_id = id;
    pushTypedChar(&ctx, 'a');

    var buf: [32]u8 = undefined;
    var len: usize = 0;
    var counter: CbCounter = .{};

    const u: Ui = .{ .ctx = &ctx };
    _ = u.inputText("field", &buf, &len, .{
        .edit = editCounterCb,
        .user_data = &counter,
    });

    try expectEqual(@as(usize, 1), counter.edit_count);
    try expectEqual(@as(usize, 1), counter.last_buf_len_seen);
    try expectEqual(@as(usize, 1), counter.last_cursor_seen);
}

