    try expectEqual(@as(usize, 0), counter.completion_count);
    // The Tab DID insert a \t (allow_tab_input took the path).
    try expectEqual(@as(usize, 1), len);
    try expectEqual(@as(u8, '\t'), buf[0]);
}

