// ============================================================================
// P10.1 — ColorEdit display format (turn 443)
// ============================================================================
// The format helpers (`colorChannelToInt255`,
// `formatColorRgbHex`) are pure functions, so unit-testable in
// isolation without spinning up a UI context.  The widget impl
// in `colorEditNFloat` just composes these helpers — once they're
// correct, the rendering is correct (modulo layout, which is
// covered by the existing widget integration tests).

test "P10.1: ColorEditOpts.display_format defaults to .float" {
    const opts: ColorEditOpts = .{};
    try expectEqual(ColorEditDisplayFormat.float, opts.display_format);
}

test "P10.1: colorChannelToInt255 rounds half-away-from-zero" {
    // 0.0 → 0, 1.0 → 255, 0.5 → 128 (round-half-up at the integer
    // boundary).  Out-of-range clamps.
    try expectEqual(@as(u8, 0), colorChannelToInt255(0.0));
    try expectEqual(@as(u8, 255), colorChannelToInt255(1.0));
    try expectEqual(@as(u8, 128), colorChannelToInt255(0.5));
    try expectEqual(@as(u8, 64), colorChannelToInt255(0.25));
    // Out-of-range clamps.
    try expectEqual(@as(u8, 0), colorChannelToInt255(-0.5));
    try expectEqual(@as(u8, 255), colorChannelToInt255(1.5));
}

test "P10.1: formatColorRgbHex RGB output is #RRGGBB" {
    // Pure-red, pure-green, pure-blue, and a saturated mid-value.
    var buf: [16]u8 = undefined;

    const red: []const u8 = formatColorRgbHex(.{ 1.0, 0.0, 0.0, 1.0 }, false, &buf);
    try expectEqualStrings("#FF0000", red);

    const green: []const u8 = formatColorRgbHex(.{ 0.0, 1.0, 0.0, 1.0 }, false, &buf);
    try expectEqualStrings("#00FF00", green);

    const orange: []const u8 = formatColorRgbHex(.{ 1.0, 0.5, 0.0, 1.0 }, false, &buf);
    try expectEqualStrings("#FF8000", orange);
}

test "P10.1: formatColorRgbHex RGBA output is #RRGGBBAA" {
    var buf: [16]u8 = undefined;

    const opaque_white: []const u8 = formatColorRgbHex(.{ 1.0, 1.0, 1.0, 1.0 }, true, &buf);
    try expectEqualStrings("#FFFFFFFF", opaque_white);

    const semi: []const u8 = formatColorRgbHex(.{ 1.0, 0.5, 0.0, 0.25 }, true, &buf);
    try expectEqualStrings("#FF800040", semi);

    const transparent_black: []const u8 = formatColorRgbHex(.{ 0.0, 0.0, 0.0, 0.0 }, true, &buf);
    try expectEqualStrings("#00000000", transparent_black);
}

test "P10.1: formatColorRgbHex clamps out-of-range channels" {
    // Negative + > 1.0 inputs clamp to [0,1] BEFORE the 0-255 map.
    // Round-trip behavior: -0.5 acts like 0.0, +1.5 acts like 1.0.
    var buf: [16]u8 = undefined;
    const out: []const u8 = formatColorRgbHex(.{ -0.5, 1.5, 0.5, 1.0 }, true, &buf);
    try expectEqualStrings("#00FF80FF", out);
}

test "P10.1: formatColorRgbHex returns empty slice for too-small buf" {
    // The caller might allocate exactly the wrong size; the helper
    // returns an empty slice (caller can detect + fall back).
    // RGB needs 7 bytes (`#RRGGBB`); RGBA needs 9 (`#RRGGBBAA`).
    var small_buf: [6]u8 = undefined;
    const rgb_short: []const u8 = formatColorRgbHex(.{ 1.0, 0.5, 0.0, 1.0 }, false, &small_buf);
    try expectEqual(@as(usize, 0), rgb_short.len);

    var medium_buf: [8]u8 = undefined;
    const rgba_short: []const u8 = formatColorRgbHex(.{ 1.0, 0.5, 0.0, 0.5 }, true, &medium_buf);
    try expectEqual(@as(usize, 0), rgba_short.len);

    // RGB into 7-byte buf: should work.
    var rgb_buf: [7]u8 = undefined;
    const rgb_ok: []const u8 = formatColorRgbHex(.{ 1.0, 0.5, 0.0, 1.0 }, false, &rgb_buf);
    try expectEqualStrings("#FF8000", rgb_ok);
}

test "P10.1: all three display formats are distinct enum variants" {
    // Sanity: enum has three variants, and `.float` is the default.
    // This is the canary test — if a future refactor adds an HSV
    // variant and accidentally reorders the existing ones,
    // existing `.float` users would silently switch behavior.
    try expect(ColorEditDisplayFormat.float != ColorEditDisplayFormat.int_0_255);
    try expect(ColorEditDisplayFormat.float != ColorEditDisplayFormat.hex);
    try expect(ColorEditDisplayFormat.int_0_255 != ColorEditDisplayFormat.hex);
}

