test "P9.2: allow_tab_input takes precedence over completion callback" {
    // When both `allow_tab_input` AND `completion` are set, Tab
    // routes to the tab-insert branch and the callback is NOT
    // called.  Verifies the dispatch order documented in
    // inputTextImpl.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    const id: Id = setupInputTextForTest(&ctx, &w, "field");
    ctx.active_id = id;
    ctx.input.keys[@backingInt(KeyCode.tab)].pressed_this_frame = true;

    const State = struct {
        var called: bool = false;
        fn cb(_: *InputTextCallbackData) void {
            called = true;
        }
    };
    State.called = false;

    var buf: [32]u8 = undefined;
    var len: usize = 0;

    const u: Ui = .{ .ctx = &ctx };
    _ = u.inputText("field", &buf, &len, .{
        .allow_tab_input = true,
        .completion = State.cb,
    });

    try expect(!State.called);
    try expectEqualStrings("\t", buf[0..len]);
}

