test "P9.2: enter_returns_true on → typing doesn't return true; Enter does" {
    // Frame 1: type a char.  With enter_returns_true, returns false
    // even though the buffer changed.
    // Frame 2: press Enter.  Returns true.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    const id: Id = setupInputTextForTest(&ctx, &w, "field");
    ctx.active_id = id;

    var buf: [32]u8 = undefined;
    var len: usize = 0;

    const u: Ui = .{ .ctx = &ctx };

    // Frame 1: char insertion shouldn't trigger return-true.
    pushTypedChar(&ctx, 'a');
    const r1: bool = u.inputText("field", &buf, &len, .{ .enter_returns_true = true });
    try expect(!r1);
    try expectEqualStrings("a", buf[0..len]);
    try expectEqual(id, ctx.active_id); // still focused

    // Frame 2: Enter pressed.  Returns true; widget defocuses.
    ctx.input.chars_typed_count = 0; // clear typed queue
    ctx.input.keys[@backingInt(KeyCode.enter)].pressed_this_frame = true;
    const r2: bool = u.inputText("field", &buf, &len, .{ .enter_returns_true = true });
    try expect(r2);
    try expectEqual(@as(Id, 0), ctx.active_id);
}

test "P9.2: enter_returns_true + escape_clears: Esc cancels (returns false, buf empty)" {
    // On host with `enter_returns_true`, Esc is NOT a commit — the
    // function returns false even though the widget defocused.
    // `escape_clears` zeros the buffer so the caller can detect
    // the cancel via len if they care.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    const id: Id = setupInputTextForTest(&ctx, &w, "field");
    ctx.active_id = id;
    ctx.input.keys[@backingInt(KeyCode.escape)].pressed_this_frame = true;

    var buf: [32]u8 = undefined;
    buf[0..5].* = "hello".*;
    var len: usize = 5;

    const u: Ui = .{ .ctx = &ctx };
    const out: bool = u.inputText("field", &buf, &len, .{
        .enter_returns_true = true,
        .escape_clears = true,
    });

    // Returns false (Esc is not a commit on host).
    try expect(!out);
    // Buffer cleared.
    try expectEqual(@as(usize, 0), len);
    // Widget defocused.
    try expectEqual(@as(Id, 0), ctx.active_id);
}

// ============================================================================
// Animation primitive tests — tween + spring (label-keyed, dt-driven)
// ============================================================================

test "animated: linear tween at midpoint returns midpoint value" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    // First call seeds; with delta_time = 0 the slot starts at t=0.
    ctx.input.delta_time = 0;
    _ = u.animated("fade", .{ .from = 0, .to = 100, .duration = 1, .easing = .linear });

    // Advance to half the duration.
    ctx.input.delta_time = 0.5;
    const v: f32 = u.animated("fade", .{ .from = 0, .to = 100, .duration = 1, .easing = .linear });
    try expectApproxEqAbs(@as(f32, 50), v, 0.001);
}

test "animated: linear tween at full duration returns to-value exactly" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    ctx.input.delta_time = 0;
    _ = u.animated("a", .{ .from = 0, .to = 10, .duration = 0.5, .easing = .linear });
    ctx.input.delta_time = 0.5;
    const v: f32 = u.animated("a", .{ .from = 0, .to = 10, .duration = 0.5, .easing = .linear });
    try expectEqual(@as(f32, 10), v);
}

test "animated: clamped to to-value after duration" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
