    ctx.input.delta_time = 0;
    _ = u.animated("alpha", .{ .from = 0, .to = 100, .duration = 1, .easing = .linear });
    _ = u.animated("beta", .{ .from = 0, .to = 50, .duration = 1, .easing = .linear });

    ctx.input.delta_time = 1;
    const a: f32 = u.animated("alpha", .{ .from = 0, .to = 100, .duration = 1, .easing = .linear });
    const b: f32 = u.animated("beta", .{ .from = 0, .to = 50, .duration = 1, .easing = .linear });
    try expectEqual(@as(f32, 100), a);
    try expectEqual(@as(f32, 50), b);
}

test "spring: approaches target over time" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    // Seed: initial = 0, target = 100, default stiffness/damping.
    ctx.input.delta_time = 0;
    _ = u.spring("s", .{ .target = 100, .initial = 0 });

    // Step forward 1 second total in small increments.  Spring
    // should be substantially closer to target.
    var step: u32 = 0;
    while (step < 60) : (step += 1) {
        ctx.input.delta_time = 1.0 / 60.0;
        _ = u.spring("s", .{ .target = 100 });
    }
    const v: f32 = u.spring("s", .{ .target = 100 });
    try expect(v > 90); // critically-damped within 1s
    try expect(v <= 100);
}

test "spring: settles exactly on target after enough time" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    ctx.input.delta_time = 0;
    _ = u.spring("s", .{ .target = 50, .initial = 0 });

    // Step forward a long time — should settle to exact target.
    var step: u32 = 0;
    while (step < 600) : (step += 1) {
        ctx.input.delta_time = 1.0 / 60.0;
        _ = u.spring("s", .{ .target = 50 });
    }
    const v: f32 = u.spring("s", .{ .target = 50 });
    try expectEqual(@as(f32, 50), v);
}

test "spring: mid-flight target change is followed smoothly" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    ctx.input.delta_time = 0;
    _ = u.spring("s", .{ .target = 100, .initial = 0 });

    // Get partway.
    var step: u32 = 0;
    while (step < 10) : (step += 1) {
        ctx.input.delta_time = 1.0 / 60.0;
        _ = u.spring("s", .{ .target = 100 });
    }
    const mid: f32 = u.spring("s", .{ .target = 100 });

    // Flip target — spring should now chase the new target.
    step = 0;
    while (step < 600) : (step += 1) {
        ctx.input.delta_time = 1.0 / 60.0;
        _ = u.spring("s", .{ .target = 200 });
    }
    const settled: f32 = u.spring("s", .{ .target = 200 });
    try expectEqual(@as(f32, 200), settled);
    // Sanity: mid is between 0 and 100.
    try expect(mid > 0);
    try expect(mid < 100);
}

test "spring: distinct labels track distinct springs" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    ctx.input.delta_time = 0;
    _ = u.spring("a", .{ .target = 10, .initial = 0 });
    _ = u.spring("b", .{ .target = 1000, .initial = 0 });

    var step: u32 = 0;
    while (step < 600) : (step += 1) {
        ctx.input.delta_time = 1.0 / 60.0;
        _ = u.spring("a", .{ .target = 10 });
        _ = u.spring("b", .{ .target = 1000 });
    }
    const a: f32 = u.spring("a", .{ .target = 10 });
    const b: f32 = u.spring("b", .{ .target = 1000 });
    try expectEqual(@as(f32, 10), a);
    try expectEqual(@as(f32, 1000), b);
}

test "animated: zero duration snaps to to-value immediately" {
