test "miniPlot: R-key press clears fitted, returns true that frame" {
    var env = TestEnv.init(std.testing.allocator);
    defer env.deinit();

    const xs: []const f32 = &.{ 0, 1, 2 };
    const ys: []const f32 = &.{ 0, 10, 20 };
    const rect: Rectangle = .{ .x = 0, .y = 0, .width = 200, .height = 100 };

    // Frame 1: seed.  No R-press → returns false, slot fitted.
    {
        const u: Ui = env.beginFrameWith(.{});
        const w: WindowHandle = u.window("t", .{}) orelse unreachable;
        defer w.close();
        const pressed: bool = u.miniPlot("p", rect, xs, ys);
        try expect(!pressed);
    }

    // Frame 2: R-key edge.  Should return true, slot.fitted false,
    // and then refit (so next frame sees fitted = true again).
    {
        var snap: InputSnapshot = .{};
        snap.keys[@backingInt(KeyCode.r)] = .{
            .down = true,
            .pressed_this_frame = true,
            .released_this_frame = false,
            .down_duration_frames = 0,
        };
        const u: Ui = env.beginFrameWith(snap);
        const w: WindowHandle = u.window("t", .{}) orelse unreachable;
        defer w.close();
        const pressed: bool = u.miniPlot("p", rect, xs, ys);
        try expect(pressed);
    }
}

// ============================================================================
// Persistence integration tests — opt-in flag + auto-serialize
// ============================================================================

/// The current schema version. Bump on breaking changes.
pub const current_version: u32 = 1;

/// Build the compound key used in `pending_tab_bar_selections`.
/// Returns an owned `[]u8` - caller must free with `gpa.free`.
/// The NUL byte separator is safe because both `window_name` and
/// `str_id` are user-supplied strings that don't contain NUL
/// (Zig strings can, but no real ui widget identifier does).
fn makeTabBarKey(
    gpa: Allocator,
    window_name: []const u8,
    str_id: []const u8,
) Allocator.Error![]u8 {
    var buf = try gpa.alloc(u8, window_name.len + 1 + str_id.len);
    @memcpy(buf[0..window_name.len], window_name);
    buf[window_name.len] = 0;
    @memcpy(buf[window_name.len + 1 ..], str_id);
    return buf;
}

/// Parse `text` (must be sentinel-terminated `[:0]const u8` per
/// std.zon API contract) as a `PersistedState`, populate
/// `ctx.pending_persistence` with deep-copies of each entry's
/// name (so the names live in `gpa` independent of the parsed
/// payload's lifetime).
/// Version mismatch: silently drops the payload. Returns no
/// error - calling code should be able to call `apply` on
/// arbitrary user input without crashing the app.
/// Parse failure: returns `error.InvalidPayload`. Callers
/// generally log + ignore (start with empty state).
pub fn apply(
    gpa: Allocator,
    ctx: *UiContext,
    text: [:0]const u8,
) Error!void {
    // PersistedStyle in ~38 fields to the parsed
    // graph; std.zon's recursive parser hit the default
    // 1000-branch quota. 10k is comfortable headroom for the
    // current shape + future additions.
    @setEvalBranchQuota(10_000);
    // Parse with `ignore_unknown_fields = true` so that adding a
    // new optional field doesn't break loading old payloads. The
    // forward-compat direction (new client, old payload) is what
    // matters in practice - users update their browser tab,
    // localStorage is from last week.
    // The reverse direction (old client, new payload) is rarer
    // and we don't try to handle it specially; the unknown
    // fields are simply dropped, defaults fill in.
    var diag: std.zon.parse.Diagnostics = .{};
    defer diag.deinit(gpa);
    const parsed = std.zon.parse.fromSliceAlloc(
        PersistedState,
        gpa,
        text,
        &diag,
        .{ .ignore_unknown_fields = true },
    ) catch {
        return error.InvalidPayload;
    };
    defer std.zon.parse.free(gpa, parsed);

    // Version gate: discard non-matching payloads. Could grow
    // a migration switch here when we have something to migrate.
    if (parsed.version != current_version) {
        return;
    }

    // Stage every entry into the pending map. Deep-copy the
    // name so the entry survives the parse-result free above.
    // Existing pending entries with the same name are replaced
    // (latest wins) - supports "reload from a fresh payload"
    // without leaking old keys.
    for (parsed.windows) |pw| {
        // Reject zero-length names - they'd alias every unnamed
        // window submission and corrupt unrelated state. A real
        // window always has a name (window titles are required).
        if (pw.name.len == 0) {
            continue;
        }

        const name_copy: []u8 = try gpa.dupe(u8, pw.name);
        // If a pending entry already exists for this name (e.g.
        // apply() called twice), free the old name to avoid leak.
        if (ctx.pending_persistence.fetchRemove(pw.name)) |old| {
            gpa.free(@constCast(old.key));
            // The value (PersistedWindow) has only POD fields
            // besides `name`, which we just freed.
        }

        try ctx.pending_persistence.put(gpa, name_copy, .{
            .name = name_copy,
            .pos = pw.pos,
            .size = pw.size,
            .scroll_y = pw.scroll_y,
            .scroll_x = pw.scroll_x,
            .user_resized = pw.user_resized,
            // The tab_bars slice owned by `parsed` is freed
            // below; we route the relevant bits into
            // `ctx.pending_tab_bar_selections` immediately so
            // they survive. PersistedWindow.tab_bars itself
            // isn't used after apply - only the staging map is
            // consulted by `takeTabBarSelection`.
            .tab_bars = &.{},
        });

        // Stage each tab bar's selection under a compound
        // "<window>\x00<str_id>" key. Selection labels are
        // deep-copied so they survive the parse-result free.
        for (pw.tab_bars) |tb| {
            if (tb.str_id.len == 0) {
                continue;
            }
            // Empty label = "no preference stored" - we still
            // record the entry's existence so the restore path
            // can distinguish "no persistence" from "explicit
            // empty selection". Stored as the empty string;
            // dupe(gpa, "") returns an empty slice from gpa
            // which is safe to free.
            const compound_key: []u8 = try makeTabBarKey(gpa, pw.name, tb.str_id);
            const label_copy = try gpa.dupe(u8, tb.selected_tab_label);

            // Replace any existing entry for the same key.
            if (ctx.pending_tab_bar_selections.fetchRemove(compound_key)) |old| {
                gpa.free(@constCast(old.key));
                gpa.free(@constCast(old.value));
            }
            try ctx.pending_tab_bar_selections.put(gpa, compound_key, label_copy);
        }
    }

    // stage the dock tree. Deep-copy
    // window-name strings since the parsed payload is freed
    // when this function returns. Stored as one flat array
    // on the UiContext; drained by the first `dockSpace()`
    // call after load (or freed on `UiContext.deinit` if no
    // dockspaces ever get submitted).
    // Replace-on-reload: if a stale pending tree already
    // exists, free its allocations first. Supports
    // calling apply() twice (e.g. user-driven "reload
    // layout" UI).
    if (parsed.dock_nodes.len > 0) {
        freePendingDockTree(gpa, ctx);
        const out_nodes = try gpa.alloc(PersistedDockNode, parsed.dock_nodes.len);
        for (parsed.dock_nodes, out_nodes) |src, *dst| {
            // Deep-copy leaf window names and selected name.
            const names = try gpa.alloc([]const u8, src.leaf_window_names.len);
            for (src.leaf_window_names, names) |s, *d| {
                d.* = try gpa.dupe(u8, s);
            }
            const sel_copy = try gpa.dupe(u8, src.leaf_selected_window_name);
            dst.* = .{
                .id = src.id,
                .parent_id = src.parent_id,
                .flags = src.flags,
                .is_split = src.is_split,
                .split_axis = src.split_axis,
                .split_ratio = src.split_ratio,
                .split_child_a = src.split_child_a,
                .split_child_b = src.split_child_b,
                .split_size_ref_a = src.split_size_ref_a,
                .split_size_ref_b = src.split_size_ref_b,
                .leaf_window_names = names,
                .leaf_selected_window_name = sel_copy,
            };
        }
        ctx.pending_dock_tree = out_nodes;
    }

    // P4.1: apply persisted style. Optional — null means the
    // saved payload was from an unthemed app and the in-memory
    // default stays untouched. `applyTo` preserves
    // `ctx.style.font` (caller-owned pointer; the.zon save
    // couldn't carry it).
    if (parsed.style) |s| {
        s.applyTo(&ctx.style);
    }

    // Restore persistable extension state. Match each saved
    // `ext_state` entry by type_name against live ext_storage
    // slots (which captured their own type_name on first
    // persist-true lookup). Unknown type_names are silently
    // discarded — forward-compat for "saved payload mentions a
    // type the current binary doesn't compile in any more."
    //

    // Each payload is zon text that the slot's `deserialize_fn`
    // knows how to parse. A successful parse merges entries by
    // id (incoming wins). A parse failure for one type doesn't
    // abort the whole apply — the next entry still runs.
    //

    // Ordering caveat: `apply` may run before the app has touched
    // the persistable types this frame (e.g. localStorage load at
    // startup, before the first `update`). In that case the
    // type's slot doesn't exist in `ext_storage` yet and the
    // entry is silently skipped. Apps that want persistence on
    // the very first frame must `getOrPutState` for those types
    // in init, before `apply`.
    for (parsed.ext_state) |e| {
        var es_it: std.AutoHashMapUnmanaged(u64, ExtStorageSlot).Iterator = ctx.ext_storage.iterator();
        while (es_it.next()) |kv| {
            const slot: *ExtStorageSlot = kv.value_ptr;
            const slot_name: []const u8 = slot.type_name orelse continue;
            if (!eql(u8, slot_name, e.type_name)) {
                continue;
            }
            const de_fn: DeserializeExtFn = slot.deserialize_fn orelse break;
            // Need a sentinel-terminated copy of the payload for
            // std.zon.parse — the parsed slice is borrowed but
            // not sentinel-terminated.
            const buf: [:0]u8 = gpa.allocSentinel(u8, e.payload.len, 0) catch break;
            defer gpa.free(buf);
            @memcpy(buf, e.payload);
            de_fn(slot.map, gpa, buf) catch {}; // lint:off catch-suppression: bad persisted ext payload skipped
            break; // matched + handled
        }
    }
}

test "Q8: plain struct round-trips through serialize → apply" {
    const Counter = struct { n: i32 = 0, label: [16]u8 = @splat(0) };
    const id: Id = hashStr(0, "counter1");

    var ctx_a: UiContext = UiContext.init(std.testing.allocator);
    defer ctx_a.deinit();
    const u_a: Ui = .{ .ctx = &ctx_a };
    const slot_a: *Counter = blk: {
        const _r = u_a.getOrPutState(Counter, id, .{ .persist = true });
        _r.value_ptr.* = .{ .n = 42 };
        break :blk _r.value_ptr;
    };
    slot_a.label[0] = 'X';

    const text: []u8 = try serialize(std.testing.allocator, &ctx_a);
    defer std.testing.allocator.free(text);

    var ctx_b: UiContext = UiContext.init(std.testing.allocator);
    defer ctx_b.deinit();
    const u_b: Ui = .{ .ctx = &ctx_b };
    {
        const _r = u_b.getOrPutState(Counter, id, .{ .persist = true });
        _r.value_ptr.* = .{};
    }

    const text_z: [:0]u8 = try std.testing.allocator.allocSentinel(u8, text.len, 0);
    defer std.testing.allocator.free(text_z);
    @memcpy(text_z, text);
    try apply(std.testing.allocator, &ctx_b, text_z);

    const restored: *Counter = u_b.getState(Counter, id) orelse unreachable;
    try expectEqual(@as(i32, 42), restored.n);
    try expectEqual(@as(u8, 'X'), restored.label[0]);
}

