}

test "Q8: mixed persistable + non-persistable types in same context" {
    const Saved = struct { x: i32 = 0 };
    const Skipped = struct { y: i32 = 0 };
    const id_s: Id = hashStr(0, "saved");
    const id_k: Id = hashStr(0, "skipped");

    var ctx_a: UiContext = UiContext.init(std.testing.allocator);
    defer ctx_a.deinit();
    const u_a: Ui = .{ .ctx = &ctx_a };
    {
        const _r = u_a.getOrPutState(Saved, id_s, .{ .persist = true });
        _r.value_ptr.* = .{ .x = 7 };
    }
    {
        const _r = u_a.getOrPutState(Skipped, id_k, .{});
        _r.value_ptr.* = .{ .y = 13 };
    } // no persist

    const text: []u8 = try serialize(std.testing.allocator, &ctx_a);
    defer std.testing.allocator.free(text);

    // Saved type_name present.
    try expect(std.mem.indexOf(u8, text, @typeName(Saved)) != null);
    // Skipped absent.
    try expect(std.mem.indexOf(u8, text, @typeName(Skipped)) == null);
}

test "Q8: unknown type_name silently discarded at apply (forward-compat)" {
    // Hand-craft a payload referencing a type the binary doesn't
    // know about. apply must not crash.
    const Known = struct { v: i32 = 0 };
    const id: Id = hashStr(0, "k");

    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    {
        const _r = u.getOrPutState(Known, id, .{ .persist = true });
        _r.value_ptr.* = .{ .v = 5 };
    }

    // Payload with an unknown type — should be parsed and ignored.
    const text: [:0]const u8 =
        \\.{
        \\    .version = 6,
        \\    .ext_state = .{
        \\        .{ .type_name = "test_made_up_type", .payload = "[]" },
        \\    },
        \\}
    ;
    // version may have moved; load current version from constant
    // to make this test robust.
    const versioned: [:0]u8 = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        ".{{ .version = {d}, .ext_state = .{{ .{{ .type_name = \"foo_made_up\", .payload = \"[]\" }} }} }}",
        .{current_version},
        0,
    );
    defer std.testing.allocator.free(versioned);
    _ = text;
    try apply(std.testing.allocator, &ctx, versioned);

    // Known type's data should be unchanged (apply didn't touch it).
    const still: *Known = u.getState(Known, id) orelse unreachable;
    try expectEqual(@as(i32, 5), still.v);
}

