test "DrawList: draw2d rect/rectXYWH/circle wrap the add* methods" {
    const alloc = std.testing.allocator;
    const r: Rectangle = .{ .x = 5, .y = 10, .width = 40, .height = 20 };
    const c: Color = .{ .r = 200, .g = 40, .b = 40, .a = 255 };

    // draw2d rect(struct) == direct addRectFilled(toWire)
    var dl_a: DrawList = .{};
    defer dl_a.deinit(alloc);
    const ha: DrawListHandle = .{ .list = &dl_a, .gpa = alloc };
    ha.rect(r, .{ .color = c });

    var dl_b: DrawList = .{};
    defer dl_b.deinit(alloc);
    dl_b.addRectFilled(alloc, r, c.toWire());

    try expectEqual(@as(usize, 1), dl_a.cmds.items.len);
    try expectEqual(dl_b.cmds.items.len, dl_a.cmds.items.len);
    try expectEqual(dl_b.cmds.items[0].rect_filled.col, dl_a.cmds.items[0].rect_filled.col);
    try expectEqual(r.width, dl_a.cmds.items[0].rect_filled.rect.width);

    // rectXYWH(numbers) produces the same command as rect(struct)
    var dl_c: DrawList = .{};
    defer dl_c.deinit(alloc);
    const hc: DrawListHandle = .{ .list = &dl_c, .gpa = alloc };
    hc.rectXYWH(5, 10, 40, 20, .{ .color = c });
    try expectEqual(dl_a.cmds.items[0].rect_filled.col, dl_c.cmds.items[0].rect_filled.col);
    try expectEqual(dl_a.cmds.items[0].rect_filled.rect.height, dl_c.cmds.items[0].rect_filled.rect.height);

    // circle records something
    var dl_d: DrawList = .{};
    defer dl_d.deinit(alloc);
    const hd: DrawListHandle = .{ .list = &dl_d, .gpa = alloc };
    hd.circle(.{ 20, 20 }, 8, .{ .color = c });
    try expect(!dl_d.isEmpty());

    // line records something
    var dl_e: DrawList = .{};
    defer dl_e.deinit(alloc);
    const he: DrawListHandle = .{ .list = &dl_e, .gpa = alloc };
    he.line(.{ 0, 0 }, .{ 10, 10 }, .{ .color = c, .thickness = 2 });
    try expect(!dl_e.isEmpty());

    // triangle records something
    var dl_f: DrawList = .{};
    defer dl_f.deinit(alloc);
    const hf: DrawListHandle = .{ .list = &dl_f, .gpa = alloc };
    hf.triangle(.{ 0, 0 }, .{ 10, 0 }, .{ 5, 8 }, .{ .color = c });
    try expect(!dl_f.isEmpty());
}

test "DrawList: unpackColor round-trips with colorToU32 (used in replay)" {
    // The recorded col is a packed u32; replay unpacks back to Color.
    // Round-trip must be exact for visual equivalence with the eager path.
    const original = Color{ .r = 0x12, .g = 0x34, .b = 0x56, .a = 0x78 };
    const packed_col: ColorU32 = Color.toWire(original);
    const round_col: Color = Color.fromWire(packed_col);
    try expectEqual(original.r, round_col.r);
    try expectEqual(original.g, round_col.g);
    try expectEqual(original.b, round_col.b);
    try expectEqual(original.a, round_col.a);
}

// ============================================================================
// Tests: beginChild / endChild - sub-layout + clipping correctness
// ============================================================================

test "child windows: persist in ctx.windows across frames" {
    // (child-as-Window): each `beginChild` allocates a
    // persistent `Window` keyed by hashed child id, stored in
    // `ctx.windows`. The same child must be found again on the
    // next frame so per-child state (scroll, focus, future dock
    // node) survives. This test exercises the persistence
    // contract directly: hash the same str_id twice, fetch from
    // ctx.windows both times, expect the same pointer.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    // No children yet.
    try expectEqual(@as(usize, 0), ctx.windows.count());

    // Simulate two beginChild calls with the same str_id under the
    // same parent ID stack - should fetch the same Window pointer.
    const parent_id: Id = 0xDEADBEEF;
    const child_id: Id = hashStr(parent_id, "panel");
    const first: *Window = findOrCreateChildWindow(&ctx, child_id);
    const second: *Window = findOrCreateChildWindow(&ctx, child_id);
    try expect(first == second);
    try expectEqual(@as(usize, 1), ctx.windows.count());
    // Hash with a different str_id → different Window.
    const sibling_id: Id = hashStr(parent_id, "other");
    const sibling: *Window = findOrCreateChildWindow(&ctx, sibling_id);
    try expect(sibling != first);
    try expectEqual(@as(usize, 2), ctx.windows.count());
    // Flag check: children are flagged as such.
    try expect(first.flags.is_child);
    try expect(sibling.flags.is_child);
}

test "child scroll_max_y reflects content overflow" {
    // After endChild, the child's scroll_max_y must equal
    // (content_height - viewport_height) when content overflows.
    // Zero when content fits. Pin both cases.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // ---- Case 1: content overflows ---------------------------------
    // Child is 200×100; submit 10 buttons each ~22px tall =
    // content_h ≈ 220 + spacings. scroll_max_y should be positive.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();

        var child_id: Id = 0;
        if (ui.beginChild("scrolly", .{ 200, 100 }, .{})) {
            defer ui.endChild();
            child_id = ctx.current_window.?.id;
            var i: usize = 0;
            while (i < 10) : (i += 1) {
                _ = ui.button("row", .{});
            }
        }

        const child: *Window = ctx.windows.get(child_id).?;
        try expect(child.scroll_max_y > 0);
        // 10 rows of (~24px button + 6px spacing) ≈ 280px of CONTENT
        // but only ~196 lands as `cursor_max` for our 10-button stack
        // (font_size 16 + 2*frame_padding.y 4 = 24, no spacing after
        // the last row). Viewport is 100 (default ChildFlags → no
        // padding). Substantial overflow expected;
        // the > 80 bound proves the scrolling math is right without
        // pinning the exact value (depends on font metrics).
        try expect(child.scroll_max_y > 80);
    }

    // ---- Case 2: content fits, scroll_max_y stays zero -------------
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();

        var fits_id: Id = 0;
        if (ui.beginChild("fits", .{ 200, 300 }, .{})) {
            defer ui.endChild();
            fits_id = ctx.current_window.?.id;
            _ = ui.button("only one", .{});
        }

        const child: *Window = ctx.windows.get(fits_id).?;
        try expectEqual(@as(f32, 0), child.scroll_max_y);
    }
}

test "ChildFlags: default (no flags) → no inner padding" {
    // Imgui-parity: ChildFlags{} means the child's
