test "mouse wheel consumed by deepest hovered child" {
    // Inner child's endChildImpl runs BEFORE outer's (LIFO via the
    // user's `defer ui.endChild()` pattern). If the cursor is
    // over both, inner should consume the wheel; outer should see
    // `mouse_wheel_consumed = true` and skip applying.
    // Test shape: outer at host's origin, inner FIRST inside outer
    // (so inner has real space at outer's inner-origin), then outer
    // has 20 more rows of scrollable content. Mouse hit-tests both
    // - inner only gets the wheel because it runs first.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // First frame: discover the children's actual screen rects so
    // we can place the mouse correctly on the second frame. Wheel
    // = 0 so nothing scrolls yet.
    var outer_id: Id = 0;
    var inner_id: Id = 0;
    var inner_rect: Rectangle = undefined;
    {
        const snapshot: InputSnapshot = .{};
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window(
            "host",
            .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 800, 600 } },
        ) orelse unreachable;
        defer h.close();

        if (ui.beginChild("outer", .{ 200, 200 }, .{})) {
            defer ui.endChild();
            outer_id = ctx.current_window.?.id;
            if (ui.beginChild("inner", .{ 120, 120 }, .{})) {
                defer ui.endChild();
                const inner: *Window = ctx.current_window.?;
                inner_id = inner.id;
                inner_rect = .{
                    .x = inner.pos[0],
                    .y = inner.pos[1],
                    .width = inner.size[0],
                    .height = inner.size[1],
                };
                // Submit 20 rows so inner overflows.
                var i: usize = 0;
                while (i < 20) : (i += 1) {
                    _ = ui.button("rowI", .{});
                }
            }
            // Then 20 rows in outer to make IT overflow too.
            var j: usize = 0;
            while (j < 20) : (j += 1) {
                _ = ui.button("rowO", .{});
            }
        }
    }
    // Sanity: both children allocated.
    try expect(outer_id != 0);
    try expect(inner_id != 0);

    // Second frame: place the mouse inside the inner rect (which
    // is also inside the outer rect, since inner is nested), wheel
    // down → both children COULD scroll but only inner should.
    const inner_center: Vec2 = .{
        inner_rect.x + inner_rect.width / 2,
        inner_rect.y + inner_rect.height / 2,
    };
    {
        const snapshot: InputSnapshot = .{
            .mouse_pos = inner_center,
            .mouse_wheel_y = -1, // negative → scroll DOWN (scroll_y increases)
        };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();

        if (ui.beginChild("outer", .{ 200, 200 }, .{})) {
            defer ui.endChild();
            if (ui.beginChild("inner", .{ 120, 120 }, .{})) {
                defer ui.endChild();
                var i: usize = 0;
                while (i < 20) : (i += 1) {
                    _ = ui.button("rowI", .{});
                }
            }
            var j: usize = 0;
            while (j < 20) : (j += 1) {
                _ = ui.button("rowO", .{});
            }
        }
    }

    const inner: *Window = ctx.windows.get(inner_id).?;
    const outer: *Window = ctx.windows.get(outer_id).?;
    // Inner consumed the wheel - scroll_y > 0.
    try expect(inner.scroll_y > 0);
    // Outer saw consumed=true, did not scroll.
    try expectEqual(@as(f32, 0), outer.scroll_y);
}

test "HoveredFlags.any_window - non-zero hovered_window_id" {
    // The simplest meaningful flag: `.any_window` returns true iff
    // ANY window has the mouse, i.e. `ctx.hovered_window_id != 0`.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1: mouse far away from any window - none hovered.
    {
        const snapshot: InputSnapshot = .{ .mouse_pos = .{ -100, -100 } };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window(
            "solo",
            .{ .initial_pos = .{ 10, 10 }, .initial_size = .{ 100, 100 } },
        ) orelse unreachable;
        defer h.close();
        try expect(!ui.isWindowHovered(.{}));
        try expect(!ui.isWindowHovered(.{ .any_window = true }));
    }

    // Frame 2: mouse inside the window - both forms true.
    {
        const snapshot: InputSnapshot = .{ .mouse_pos = .{ 50, 50 } };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("solo", .{}) orelse unreachable;
        defer h.close();
        try expect(ui.isWindowHovered(.{}));
        try expect(ui.isWindowHovered(.{ .any_window = true }));
    }
}

test "HoveredFlags.child_windows - parent reports hovered when child is hovered" {
    // Two-frame test (frame 1 discovers child geometry, frame 2
    // places mouse in the child and queries from the parent's scope).
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    var child_center: Vec2 = .{ 0, 0 };
    var child_id_capture: Id = 0;
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window(
            "host",
            .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 400 } },
        ) orelse unreachable;
        defer h.close();
        if (ui.beginChild("c", .{ 120, 120 }, .{})) {
            defer ui.endChild();
            const c: *Window = ctx.current_window.?;
            child_id_capture = c.id;
            child_center = .{ c.pos[0] + c.size[0] / 2, c.pos[1] + c.size[1] / 2 };
        }
    }
    try expect(child_id_capture != 0);

    // Frame 2: place the mouse at the child's center, fake the
    // hovered_window_id to be the child (deepest-hovered semantics
    // aren't fully wired today - `hovered_window_id` tracks the
    // top-level only - so we override directly to exercise the
    // child_windows traversal logic). Once.x lands deeper
    // hover-tracking, this fake becomes unnecessary.
    {
        const snapshot: InputSnapshot = .{ .mouse_pos = child_center };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        // Force ctx.hovered_window_id to the child so the traversal
        // logic has something to walk back from.
        ctx.hovered_window_id = child_id_capture;
        // Parent scope query, no flags: child is hovered, parent is NOT.
        try expect(!ui.isWindowHovered(.{}));
        // Parent scope query, child_windows = true: TRUE (parent
        // walked back from child via parent_id chain).
        try expect(ui.isWindowHovered(.{ .child_windows = true }));
        // Convenience constant root_and_child_windows: also TRUE.
        try expect(ui.isWindowHovered(HoveredFlags.root_and_child_windows));
        // Now query from inside the child's scope:
        if (ui.beginChild("c", .{ 120, 120 }, .{})) {
            defer ui.endChild();
            // From child's scope, isWindowHovered() is TRUE (the
            // child IS the hovered window).
            try expect(ui.isWindowHovered(.{}));
            // root_window from child: walks UP to host; host is NOT
            // the hovered window (child is) → FALSE without
            // child_windows.
            try expect(!ui.isWindowHovered(.{ .root_window = true }));
            // root_window + child_windows: walks to host, then
            // checks "is anyone in host's hierarchy hovered?" → TRUE.
            try expect(ui.isWindowHovered(HoveredFlags.root_and_child_windows));
        }
    }
}

