test "DrawList: push/pop clip rect on child boundaries (foundation for tables)" {
    // beginChild emits a `push_clip` cmd; endChild emits a `pop_clip`.
    // The pair brackets the child's content cmds. Verify the cmd
    // structure of a synthetic child submission directly (without
    // running a full UiContext frame).
    var test_arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer test_arena.deinit();
    var dl = DrawList{};
    defer dl.deinit(test_arena.allocator());
    // Simulate: parent emits 1 rect, then beginChild, child emits 2
    // rects, endChild, parent emits 1 more rect.
    dl.addRectFilled(test_arena.allocator(), .{ .x = 0, .y = 0, .width = 10, .height = 10 }, 0);
    dl.pushClipRect(test_arena.allocator(), .{ .x = 5, .y = 5, .width = 100, .height = 50 });
    dl.addRectFilled(test_arena.allocator(), .{ .x = 10, .y = 10, .width = 5, .height = 5 }, 0);
    dl.addRectFilled(test_arena.allocator(), .{ .x = 15, .y = 15, .width = 5, .height = 5 }, 0);
    dl.popClipRect(test_arena.allocator());
    dl.addRectFilled(test_arena.allocator(), .{ .x = 0, .y = 60, .width = 10, .height = 10 }, 0);
    // 5 cmds: rect, push, rect, rect, pop, rect - wait, that's 6.
    try expectEqual(@as(usize, 6), dl.cmds.items.len);
    try expect(dl.cmds.items[0] == .rect_filled);
    try expect(dl.cmds.items[1] == .push_clip);
    try expect(dl.cmds.items[2] == .rect_filled);
    try expect(dl.cmds.items[3] == .rect_filled);
    try expect(dl.cmds.items[4] == .pop_clip);
    try expect(dl.cmds.items[5] == .rect_filled);
}

test "DrawList: nested clip rects (child-in-child) record both pushes" {
    // The nested-child case from the demo - outer push, inner push,
    // some content, inner pop, outer pop. At replay time, the
    // scissor stack composes: inner content is clipped by both
    // rects (effectively the intersection).
    var test_arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer test_arena.deinit();
    var dl = DrawList{};
    defer dl.deinit(test_arena.allocator());
    dl.pushClipRect(test_arena.allocator(), .{ .x = 0, .y = 0, .width = 200, .height = 140 });
    dl.pushClipRect(test_arena.allocator(), .{ .x = 10, .y = 20, .width = 140, .height = 80 });
    dl.addRectFilled(test_arena.allocator(), .{ .x = 12, .y = 22, .width = 4, .height = 4 }, 0);
    dl.popClipRect(test_arena.allocator());
    dl.popClipRect(test_arena.allocator());
    try expectEqual(@as(usize, 5), dl.cmds.items.len);
    // First two are pushes (outer then inner).
    try expect(dl.cmds.items[0] == .push_clip);
    try expect(dl.cmds.items[1] == .push_clip);
    // Outer push has the bigger rect.
    try expectEqual(@as(f32, 200), dl.cmds.items[0].push_clip.rect.width);
    try expectEqual(@as(f32, 140), dl.cmds.items[1].push_clip.rect.width);
    // Last two are pops.
    try expect(dl.cmds.items[3] == .pop_clip);
    try expect(dl.cmds.items[4] == .pop_clip);
}

