test "DrawList: addPolyline duplicates points into arena" {
    var test_arena: std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer test_arena.deinit();
    var dl = DrawList{};
    defer dl.deinit(test_arena.allocator());
    {
        var local: [3]Vec2 = .{
            .{ 0, 0 },
            .{ 10, 5 },
            .{ 20, 0 },
        };
        dl.addPolyline(test_arena.allocator(), local[0..], 0xFF00FF00, 1.0, false);
        // Stomp - proves the arena owns the bytes, not the caller.
        for (&local) |*p| {
            p.* = .{ -1, -1 };
        }
    }
    try expectEqual(@as(usize, 1), dl.cmds.items.len);
    const c: @TypeOf(dl.cmds.items[0].polyline) = dl.cmds.items[0].polyline;
    try expectEqual(@as(usize, 3), c.points.len);
    try expectEqual(@as(f32, 10), c.points[1][0]);
    try expectEqual(@as(f32, 5), c.points[1][1]);
}

