// ============================================================================
// Tests: multi-component widgets - slider / drag / input over `*[N]T`
// ============================================================================
// These exercise the dispatch path: `slider(&my_array, opts)` must
// resolve to the array path (sliderArray / dragArray / inputArray),
// and the per-component IDs must not collide with each other or with
// scalar sliders at the same label.

test "sliderArray ID hashing: component IDs distinct from parent and each other" {
    // The array dispatch hashes `(parent_id, i)` for each component.
    // Verify those hashes are distinct so focus state can't alias
    // across components or against the parent's own id.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const parent: Id = hashStr(0, "vec3");
    const c0: Id = hashInt(parent, 0);
    const c1: Id = hashInt(parent, 1);
    const c2: Id = hashInt(parent, 2);
    try expect(parent != c0);
    try expect(c0 != c1);
    try expect(c1 != c2);
    try expect(c0 != c2);
}

test "slider dispatches *[3]f32 to array path (compile + no crash)" {
    // Compile-time check that the dispatch resolves; runtime check
    // that the call doesn't panic when invoked outside a window
    // (early-returns false via current_window == null).
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    var v: [3]f32 = .{ 0.1, 0.2, 0.3 };
    const changed: bool = u.slider("vec3", &v, .{ .min = 0, .max = 1 });
    try expectEqual(false, changed); // no window → early-return
    // Values untouched.
    try expectEqual(@as(f32, 0.1), v[0]);
    try expectEqual(@as(f32, 0.2), v[1]);
    try expectEqual(@as(f32, 0.3), v[2]);
}

