// ----------------------------------------------------------------------------
// table 2-channel render
// ----------------------------------------------------------------------------
// beginTable allocates a 2-channel DrawListSplitter on TableState
// and redirects ctx.current_draw_list to channel 1. Cell bg/borders
// the table draws itself go to channel 0; widget submissions during
// cells go to channel 1. endTable merges channel 0 BEFORE channel 1
// into the window's draw_list — bg lands UNDER content in the final
// stream. These tests pin the contract.

test "table: beginTable redirects current_draw_list to splitter channel 1" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    // Pre-condition: current_draw_list points at the window's draw_list.
    ctx.current_draw_list = &w.draw_list;
    const saved_before: ?*DrawList = ctx.current_draw_list;

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 2, .{}));
    const ts: *TableState = &ctx.active_table.?;
    // Splitter set up with 2 channels.
    try expectEqual(@as(usize, 2), ts.splitter.channels.items.len);
    // Saved old draw list.
    try expectEqual(saved_before, ts.saved_draw_list);
    // Redirected to channel 1.
    try expectEqual(
        @as(*DrawList, &ts.splitter.channels.items[1]),
        ctx.current_draw_list.?,
    );
}

test "table: endTable restores current_draw_list and merges channels in order" {
    // The keystone test: drive a 2-row, 1-column table with per-row
    // bg colors enabled. After endTable, the window's draw_list
    // contains channel-0 cmds (the row bgs) BEFORE channel-1 cmds
    // (any cell content) — proving bg paints UNDER content.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };
    ctx.style.table_row_bg = .{ .r = 32, .g = 32, .b = 32, .a = 255 };
    ctx.style.table_row_bg_alt = .{ .r = 64, .g = 64, .b = 64, .a = 255 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 1, .{ .row_bg = true }));
    const ts: *TableState = &ctx.active_table.?;

    // Row 0: submit a "content" cmd into channel 1 by writing
    // through the redirected current_draw_list.
    u.tableNextRow();
    _ = u.tableNextColumn();
    ctx.current_draw_list.?.addRectFilled(
        ctx.frame_arena.allocator(),
        .{ .x = 10, .y = 10, .width = 50, .height = 20 },
        0xFFFFFFFF, // white content rect — distinct from bgs.
    );

    // Row 1: same — second content cmd.
    u.tableNextRow();
    _ = u.tableNextColumn();
    ctx.current_draw_list.?.addRectFilled(
        ctx.frame_arena.allocator(),
        .{ .x = 10, .y = 30, .width = 50, .height = 20 },
        0xFFEEEEEE,
    );

    // Sanity before endTable: channel 1 has 2 content rects, channel 0
    // has at least row-0's bg (painted lazily by tableNextRow for row 1).
    try expectEqual(@as(usize, 2), ts.splitter.channels.items[1].cmds.items.len);

    u.endTable();

    // Post-condition: ctx.active_table cleared, current_draw_list restored.
    try expect(ctx.active_table == null);
    try expectEqual(@as(?*DrawList, &w.draw_list), ctx.current_draw_list);

    // Window's draw_list now contains the merged stream. Find the
    // first content cmd (white, 0xFFFFFFFF) and the first bg cmd
    // (dark grey table_row_bg) — bg's index must be < content's.
    var first_content_idx: ?usize = null;
    var first_bg_idx: ?usize = null;
    for (w.draw_list.cmds.items, 0..) |c, i| {
        if (c != .rect_filled) {
            continue;
        }
        const col: ColorU32 = c.rect_filled.col;
        if (col == 0xFFFFFFFF and first_content_idx == null) {
            first_content_idx = i;
        }
        // table_row_bg = rgba(32,32,32,255) → packed 0xFF202020.
        if (col == 0xFF202020 and first_bg_idx == null) {
            first_bg_idx = i;
        }
    }
    try expect(first_bg_idx != null);
    try expect(first_content_idx != null);
    // The contract: bg index < content index. Before this
    // was the OTHER way around — bg appended after content, painting
    // over it. The splitter merge inverts that order.
    try expect(first_bg_idx.? < first_content_idx.?);
}

test "table: splitter merge appends to existing target draw_list" {
    // Confirms the merge target is the saved current_draw_list (i.e.
    // the window's draw_list when not nested), and that pre-existing
    // commands on that target survive — the merge APPENDS, doesn't
    // replace.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    // Pre-table: paint a sentinel cmd into the window's draw_list.
    ctx.current_draw_list.?.addRectFilled(
        ctx.frame_arena.allocator(),
        .{ .x = 0, .y = 0, .width = 1, .height = 1 },
        0xFFDEADBE, // sentinel color
    );
    try expectEqual(@as(usize, 1), w.draw_list.cmds.items.len);

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 1, .{ .row_bg = true }));
    u.tableNextRow();
    _ = u.tableNextColumn();
    u.endTable();

    // After endTable: the sentinel cmd is STILL the first cmd in the
    // window's draw_list (merge appended after it, not replaced it).
    try expect(w.draw_list.cmds.items.len > 1);
    try expect(w.draw_list.cmds.items[0] == .rect_filled);
    try expectEqual(@as(u32, 0xFFDEADBE), w.draw_list.cmds.items[0].rect_filled.col);
}

// ----------------------------------------------------------------------------
// table cell bg colors
// ----------------------------------------------------------------------------
// `tableSetCellBgColor` records a pending bg for the column just
// entered via `tableNextColumn`. The bg is flushed at row
// finalization (tableNextRow for completed rows; endTable for the
// final row). Painted to splitter channel 0 (bg layer) AFTER the
// row bg, so cell-level overrides win over row-level visually but
// still land UNDER cell content (channel 1).

test "cell bg: TableColumnState.cell_bg_pending defaults to null" {
    const col: TableColumnState = .{};
    try expectEqual(@as(?Color, null), col.cell_bg_pending);
}

test "cell bg: tableSetCellBgColor is a no-op without an active table" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    // Should not crash, should not allocate anything.
    u.tableSetCellBgColor(.{ .r = 255, .g = 0, .b = 0, .a = 255 });
    try expect(ctx.active_table == null);
}

test "cell bg: tableSetCellBgColor before tableNextColumn is a no-op" {
    // cur_col is -1 immediately after tableNextRow (no column entered
    // yet). Calling tableSetCellBgColor at that point must not
    // attempt to write to ts.columns[-1].
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 2, .{}));
    u.tableNextRow();
    // No tableNextColumn yet — cur_col is -1.
    u.tableSetCellBgColor(.{ .r = 100, .g = 100, .b = 100, .a = 255 });
    const ts: *TableState = &ctx.active_table.?;
    // No column got a pending color.
    try expectEqual(@as(?Color, null), ts.columns[0].cell_bg_pending);
    try expectEqual(@as(?Color, null), ts.columns[1].cell_bg_pending);
    u.endTable();
}

test "cell bg: tableSetCellBgColor stores the color on the current column" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 2, .{}));
    u.tableNextRow();
    _ = u.tableNextColumn(); // cur_col -> 0
    const c0: Color = .{ .r = 200, .g = 50, .b = 50, .a = 255 };
    u.tableSetCellBgColor(c0);
    const ts: *TableState = &ctx.active_table.?;
    try expectEqual(@as(?Color, c0), ts.columns[0].cell_bg_pending);
    try expectEqual(@as(?Color, null), ts.columns[1].cell_bg_pending);

    _ = u.tableNextColumn(); // cur_col -> 1
    const c1: Color = .{ .r = 50, .g = 200, .b = 50, .a = 255 };
    u.tableSetCellBgColor(c1);
    try expectEqual(@as(?Color, c0), ts.columns[0].cell_bg_pending);
    try expectEqual(@as(?Color, c1), ts.columns[1].cell_bg_pending);
    u.endTable();
}

test "cell bg: pending bg is flushed and reset on tableNextRow" {
    // Drive row 0 with a cell bg override. When row 1 begins via
    // tableNextRow, the row-finalization branch flushes the pending
    // override into splitter channel 0 and clears the field.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 1, .{}));
    u.tableNextRow();
    _ = u.tableNextColumn();
    const ts: *TableState = &ctx.active_table.?;
    const cell_color: Color = .{ .r = 80, .g = 90, .b = 100, .a = 255 };
    u.tableSetCellBgColor(cell_color);
    try expectEqual(@as(?Color, cell_color), ts.columns[0].cell_bg_pending);

    // Sanity: ensure the row has some height so the flushed bg has
    // a non-zero rect. Bump cursor_max so row_max_h grows on next
    // column advance.
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };

    const ch0_before: usize = ts.splitter.channels.items[0].cmds.items.len;
    u.tableNextRow();
    // After finalizing row 0, the pending bg has been painted into
    // channel 0 (one extra rect_filled cmd) and reset.
    try expect(ts.splitter.channels.items[0].cmds.items.len > ch0_before);
    try expectEqual(@as(?Color, null), ts.columns[0].cell_bg_pending);
    u.endTable();
}

test "cell bg: final row's pending bg is flushed at endTable" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 1, .{}));
    u.tableNextRow();
    _ = u.tableNextColumn();
    // Sentinel color — distinctive so the merge output can be probed.
    const cell_color: Color = .{ .r = 0xC0, .g = 0xFF, .b = 0xEE, .a = 255 };
    u.tableSetCellBgColor(cell_color);
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };
    u.endTable();

    // After endTable: the merged window draw_list contains the
    // sentinel rect_filled (packed 0xFFEEFFC0 — bgra → rgba
    // packing in colorToU32).
    const packed_sentinel: u32 = Color.toWire(cell_color);
    var found: bool = false;
    for (w.draw_list.cmds.items) |c| {
        if (c == .rect_filled and c.rect_filled.col == packed_sentinel) {
            found = true;
            break;
        }
    }
    try expect(found);
}

test "cell bg: alpha=0 cell color skips painting (clear-pending semantic)" {
    // Setting cell bg to transparent is the "I changed my mind; don't
    // paint anything for this cell" path. The pending field is set
    // (so future SetCellBgColor calls in the same cell override it),
    // but flushTableCellBgs skips alpha=0 colors at flush time.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    // No row_bg + no borders → channel 0 should have ZERO rect_filled
    // cmds when the only candidate (cell bg) is alpha=0 and skipped.
    try expect(u.beginTable("t", 1, .{ .row_bg = false, .borders = false }));
    u.tableNextRow();
    _ = u.tableNextColumn();
    u.tableSetCellBgColor(.{ .r = 255, .g = 255, .b = 255, .a = 0 });
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };
    u.endTable();

    // After merge, the only thing the table could have added to
    // w.draw_list is bg-layer cmds (no widgets were submitted to
    // channel 1). With alpha=0 cell, no row bg, no borders, the
    // merged target should contain ZERO rect_filled cmds.
    var rect_count: usize = 0;
    for (w.draw_list.cmds.items) |c| {
        if (c == .rect_filled) {
            rect_count += 1;
        }
    }
    try expectEqual(@as(usize, 0), rect_count);
}

test "cell bg: cell override paints AFTER row bg in channel 0" {
    // Z-order contract: cell bgs are more specific than row bgs.
    // In channel 0's cmd stream, the row bg cmd must appear BEFORE
    // the cell bg cmd — so on replay the cell bg paints OVER the row
    // bg. (Both still land before channel 1's cell content after
    // the merge.)
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };
    ctx.style.table_row_bg = .{ .r = 32, .g = 32, .b = 32, .a = 255 };
    ctx.style.table_row_bg_alt = .{ .r = 64, .g = 64, .b = 64, .a = 255 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 1, .{ .row_bg = true }));
    u.tableNextRow();
    _ = u.tableNextColumn();
    const cell_sentinel: Color = .{ .r = 0xAA, .g = 0xBB, .b = 0xCC, .a = 255 };
    u.tableSetCellBgColor(cell_sentinel);
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };
    u.endTable();

    // Scan merged draw_list for first row-bg cmd (rgba 32,32,32,255
    // → packed 0xFF202020) and first cell-bg cmd (cell_sentinel).
    const packed_row_bg: u32 = Color.toWire(ctx.style.table_row_bg);
    const packed_cell_bg: u32 = Color.toWire(cell_sentinel);
    var row_idx: ?usize = null;
    var cell_idx: ?usize = null;
    for (w.draw_list.cmds.items, 0..) |c, i| {
        if (c != .rect_filled) {
            continue;
        }
        if (c.rect_filled.col == packed_row_bg and row_idx == null) {
            row_idx = i;
        }
        if (c.rect_filled.col == packed_cell_bg and cell_idx == null) {
            cell_idx = i;
        }
    }
    try expect(row_idx != null);
    try expect(cell_idx != null);
    // Row bg appears BEFORE cell bg → cell bg paints over row bg.
    try expect(row_idx.? < cell_idx.?);
}

// ----------------------------------------------------------------------------
// table borders_* family
// ----------------------------------------------------------------------------
// The single `borders: bool` master flag is now AND-gated with four
// granular sub-flags (borders_inner_h/outer_h/inner_v/outer_v). Each
// gate controls a specific subset of the border lines. Defaults:
// all four sub-flags `true`, master `borders` `true` — visually
// identical to pre-P8.2. Setting any individual sub-flag false
// suppresses just that subset. Setting `borders = false` still
// disables ALL borders for backward compat.

test "borders: defaults match pre-(master true, all granular true)" {
    const o: TableOpts = .{};
    try expect(o.borders);
    try expect(o.borders_inner_h);
    try expect(o.borders_outer_h);
    try expect(o.borders_inner_v);
    try expect(o.borders_outer_v);
}

test "borders: master `borders = false` overrides all granular flags" {
    // Even if every granular flag is true, master `borders = false`
    // suppresses all border drawing — backward compat with pre-P8.2.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    try expect(u.beginTable("t", 2, .{
        .borders = false, // master OFF
        .borders_inner_h = true, // ignored because master is off
        .borders_outer_h = true,
        .borders_inner_v = true,
        .borders_outer_v = true,
        .row_bg = false,
    }));
    u.tableNextRow();
    _ = u.tableNextColumn();
    _ = u.tableNextColumn();
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };
    u.endTable();

    // No border lines (no rect_outline either — split into
    // per-side addLine cmds), no row bg, no cell bg → the merged
    // window draw_list has zero line cmds from the table.
    var line_count: usize = 0;
    for (w.draw_list.cmds.items) |c| {
        if (c == .line) {
            line_count += 1;
        }
    }
    try expectEqual(@as(usize, 0), line_count);
}

