    u.tableNextRow();
    _ = u.tableNextColumn();
    ctx.current_window.?.layout.cursor_max = .{ 10, 30 };
    u.endTable();

    var line_count: usize = 0;
    for (w.draw_list.cmds.items) |c| {
        if (c == .line) {
            line_count += 1;
        }
    }
    try expectEqual(@as(usize, 4), line_count);
}

