test "computeTableColumnLayout: fixed columns get user width, stretch share the remainder" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var ts: TableState = .{
        .id = 0,
        .n_columns = 3,
        .columns_set_up = 0,
        .columns = @splat(.{}),
        .row_y = 0,
        .row_max_h = 0,
        .cur_col = -1,
        .cur_row = -1,
        .opts = .{},
        .outer_rect = .{ .x = 0, .y = 0, .width = 300, .height = 0 },
        .has_setup = true,
        .scroll_y = 0,
        .data_origin_y = 0,
        .clip_pushed = false,
        .row_bg_override = null,
    };
    // Column 0: fixed 80px. Column 1: stretch weight 1. Column 2:
    // stretch weight 2. Remainder = 300 - 80 = 220 shared 1:2 →
    // ~73.33 and ~146.67.
    ts.columns[0].sizing = .fixed;
    ts.columns[0].user_width = 80;
    ts.columns[1].sizing = .stretch;
    ts.columns[1].user_weight = 1;
    ts.columns[2].sizing = .stretch;
    ts.columns[2].user_weight = 2;
    ts.columns_set_up = 3;

    computeTableColumnLayout(&ctx, &ts);

    try expectApproxEqAbs(@as(f32, 80), ts.columns[0].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 220.0 / 3.0), ts.columns[1].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 440.0 / 3.0), ts.columns[2].width, 1e-3);
    // X positions stack left-to-right.
    try expectApproxEqAbs(@as(f32, 0), ts.columns[0].x, 1e-3);
    try expectApproxEqAbs(@as(f32, 80), ts.columns[1].x, 1e-3);
    try expectApproxEqAbs(@as(f32, 80 + 220.0 / 3.0), ts.columns[2].x, 1e-3);
}

