// ---- sizing-mode suite -----------------------------
//

// Each test builds a TableState directly with measured `width_auto_seen`
// values (simulating the previous-frame measurement state) and asserts
// `computeTableColumnLayout` produces the expected per-column widths.
//

// The factory keeps boilerplate down: three measured columns, the
// caller picks the table-level policy.

fn makeP84TableState(sizing: TableSizing, outer_w: f32) TableState {
    var ts: TableState = std.mem.zeroes(TableState);
    ts.id = 0xCAFEBABE;
    ts.n_columns = 3;
    ts.columns_set_up = 3; // pretend three setup calls already ran
    ts.cur_row = -1;
    ts.cur_col = -1;
    ts.outer_rect = .{ .x = 0, .y = 0, .width = outer_w, .height = 0 };
    ts.opts = .{ .sizing = sizing };
    // Three columns with distinct measured widths. The values are
    // chosen so the four policies produce visibly-different outputs.
    ts.columns[0] = .{ .sizing = defaultColumnSizing(sizing), .width_auto_seen = 30 };
    ts.columns[1] = .{ .sizing = defaultColumnSizing(sizing), .width_auto_seen = 60 };
    ts.columns[2] = .{ .sizing = defaultColumnSizing(sizing), .width_auto_seen = 90 };
    return ts;
}

test "P8.4: stretch_same — equal width regardless of content" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Three stretch columns, 300px outer → 100px each. Measured
    // widths (30 / 60 / 90) are ignored because the policy
    // distributes EQUALLY when no per-column weights are set.
    var ts: TableState = makeP84TableState(.stretch_same, 300);
    computeTableColumnLayout(&ctx, &ts);
    try expectApproxEqAbs(@as(f32, 100), ts.columns[0].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 100), ts.columns[1].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 100), ts.columns[2].width, 1e-3);
}

test "P8.4: stretch_prop — widths proportional to measured content" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Three stretch columns with content weights 30/60/90 (sum 180),
    // 360px outer → 60/120/180px. No per-column weight override, so
    // the policy supplies weights from `width_auto_seen`.
    var ts: TableState = makeP84TableState(.stretch_prop, 360);
    computeTableColumnLayout(&ctx, &ts);
    try expectApproxEqAbs(@as(f32, 60), ts.columns[0].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 120), ts.columns[1].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 180), ts.columns[2].width, 1e-3);
}

test "P8.4: fixed_fit — each column = its own measured content width" {
