test "P8.4: per-column override beats table policy (user weight wins)" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Policy is stretch_prop (content-driven weights) but we pin
    // column 1 to an explicit weight of 4. Policy gives col 0 and
    // col 2 their content-derived weights (30 and 90); col 1's 4
    // wins over its content-derived value (60). Sum = 30 + 4 + 90
    // = 124. outer 620 → 30 * 5 = 150, 4 * 5 = 20, 90 * 5 = 450.
    var ts: TableState = makeP84TableState(.stretch_prop, 620);
    ts.columns[1].user_weight = 4;
    computeTableColumnLayout(&ctx, &ts);
    try expectApproxEqAbs(@as(f32, 150), ts.columns[0].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 20), ts.columns[1].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 450), ts.columns[2].width, 1e-3);
}

test "P8.4: per-column override beats table policy (user width wins)" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Policy is fixed_same (every fixed column = max measured = 90)
    // but column 0 has user_width = 25 which always wins.
    var ts: TableState = makeP84TableState(.fixed_same, 400);
    ts.columns[0].user_width = 25;
    computeTableColumnLayout(&ctx, &ts);
    try expectApproxEqAbs(@as(f32, 25), ts.columns[0].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 90), ts.columns[1].width, 1e-3);
    try expectApproxEqAbs(@as(f32, 90), ts.columns[2].width, 1e-3);
}

test "P8.4: defaultColumnSizing maps table policy to column sizing" {
