    try expectEqual(TableColumnSizing.stretch, defaultColumnSizing(.stretch_prop));
    try expectEqual(TableColumnSizing.fixed, defaultColumnSizing(.fixed_fit));
    try expectEqual(TableColumnSizing.fixed, defaultColumnSizing(.fixed_same));
