    // Cache must now have the three values stored against id 0xBEEF.
    const cached: [max_table_columns]f32 = ctx.table_width_auto_cache.get(0xBEEF) orelse
        return error.CacheMissing;
    try expectEqual(@as(f32, 42), cached[0]);
    try expectEqual(@as(f32, 73), cached[1]);
    try expectEqual(@as(f32, 19), cached[2]);
