test "table: snapshotCellHeight captures the last cell of each row" {
    // Regression test for the latent bug spotted while implementing
    // P8.4: tableNextColumnImpl only snapshotted height
    // when ADVANCING between cells, so the LAST cell of every row
    // was never measured. Symptom: a row whose tallest cell was
    // the rightmost column rendered with row_max_h reflecting only
    // cells 0..N-2.
    //

    // We simulate the situation directly with a TableState rather
    // than driving it through the full Ui/Window machinery: set
    // cur_col to the last column, push cursor_max[1] down to mimic
    // a tall widget, call snapshotCellHeight, and verify row_max_h
    // got bumped. This is what tableNextRow / endTable now do
    // for the last cell.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var w: Window = std.mem.zeroes(Window);
    var ts: TableState = std.mem.zeroes(TableState);
    ts.n_columns = 3;
    ts.cur_col = 2; // simulate "inside the last column"
    ts.cur_row = 0;
    ts.row_y = 100;
    ts.row_max_h = 20; // cells 0 + 1 had height 20
    ts.opts = .{ .cell_padding_y = 2 };
    // Simulate a widget that wrote to y = 100 + 50 = 150 — a tall
    // cell whose used height (150 - 100) + cell_padding_y = 52
    // should overtake the existing row_max_h of 20.
    w.layout.cursor_max = .{ 0, 150 };
    snapshotCellHeight(&ts, &w);
    try expectApproxEqAbs(@as(f32, 52), ts.row_max_h, 1e-3);
}

test "table: snapshotCellHeight is a no-op when no active column" {
    // Guard against the "cur_col == -1 between tableNextRow and the
    // first tableNextColumn" state — calling the helper there
    // would have to do nothing rather than misread row state.
    var w: Window = std.mem.zeroes(Window);
    var ts: TableState = std.mem.zeroes(TableState);
    ts.cur_col = -1;
    ts.row_max_h = 7;
    w.layout.cursor_max = .{ 0, 9999 }; // would normally bump row_max_h
    snapshotCellHeight(&ts, &w);
    // row_max_h unchanged because cur_col < 0 short-circuits.
    try expectEqual(@as(f32, 7), ts.row_max_h);
}

