    var default_col: TableColumnState = .{};
    const id: Id = 42;
    cycleTableSort(&ctx, id, 1, true, &default_col); // start
    cycleTableSort(&ctx, id, 2, true, &default_col); // additive
    var ss: *TableSortSpecs = ctx.table_sort_state.getPtr(id).?;
    try expectEqual(@as(u8, 2), ss.len);
