test "P8.6: default_sort seeds initial sort specs at column setup" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const ui_handle: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const w: WindowHandle = ui_handle.window("w", .{}) orelse unreachable;
    defer w.close();

    if (ui_handle.beginTable("t", 3, .{})) {
        defer ui_handle.endTable();
        ui_handle.tableSetupColumn("col0", .{});
        ui_handle.tableSetupColumn("col1", .{ .default_sort = .descending });
        ui_handle.tableSetupColumn("col2", .{});
    }

    // Find the table's id.  beginTable hashes the table label
    // under the window's id stack — easiest to find the live
    // table id is `active_table.id`, but that's nulled at
    // endTable.  Walk the persisted sort_state map instead:
    // there should be exactly one entry, the table we just
    // submitted.
    var it: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Iterator = ctx.table_sort_state.iterator();
    const entry: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Entry = it.next() orelse return error.MissingSortSpec;
    const ss: *TableSortSpecs = entry.value_ptr;
    try expectEqual(@as(u8, 1), ss.len);
    try expectEqual(@as(u32, 1), ss.specs[0].column_index);
    try expectEqual(TableSortDirection.descending, ss.specs[0].direction);
}

test "P8.6: default_sort does NOT re-seed once the user has interacted" {
    // Same setup twice; between submissions, simulate a user
    // click moving the primary to a different column.  The second
    // submission must NOT clobber the user's choice.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1: submit, default_sort lands on col 1 ascending.
    {
        const ui_handle: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const w: WindowHandle = ui_handle.window("w", .{}) orelse unreachable;
        defer w.close();
        if (ui_handle.beginTable("t", 3, .{})) {
            defer ui_handle.endTable();
            ui_handle.tableSetupColumn("col0", .{});
            ui_handle.tableSetupColumn("col1", .{ .default_sort = .ascending });
            ui_handle.tableSetupColumn("col2", .{});
        }
    }

    // "User clicks col2."  Find the table's id (only entry in
    // the sort map), then directly mutate the specs as the click
    // handler would.
    var it: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Iterator = ctx.table_sort_state.iterator();
    const entry: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Entry = it.next() orelse return error.MissingSortSpec;
    const table_id: Id = entry.key_ptr.*;
    var col2: TableColumnState = .{};
    cycleTableSort(&ctx, table_id, 2, false, &col2);
    try expectEqual(@as(u32, 2), entry.value_ptr.specs[0].column_index);

    // Frame 2: same submission.  default_sort on col 1 must NOT
    // re-fire because the spec already exists.
    {
        const ui_handle: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const w: WindowHandle = ui_handle.window("w", .{}) orelse unreachable;
        defer w.close();
        if (ui_handle.beginTable("t", 3, .{})) {
            defer ui_handle.endTable();
            ui_handle.tableSetupColumn("col0", .{});
            ui_handle.tableSetupColumn("col1", .{ .default_sort = .ascending });
            ui_handle.tableSetupColumn("col2", .{});
        }
    }

    // Primary still col 2 — user's click was preserved.
    var it2: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Iterator = ctx.table_sort_state.iterator();
    const entry2: std.AutoHashMapUnmanaged(Id, TableSortSpecs).Entry = it2.next() orelse return error.MissingSortSpec;
    try expectEqual(@as(u32, 2), entry2.value_ptr.specs[0].column_index);
}

