test "P8.6: width_auto resolves to sizing=.fixed with user_width=0" {
    // `width_auto` is a setup-time shortcut for "fit content."
    // Resolution: state.sizing → .fixed; state.user_width → 0;
    // downstream layout reads `width_auto_seen` for the actual
    // value.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const ui_handle: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const w: WindowHandle = ui_handle.window("w", .{}) orelse unreachable;
    defer w.close();

    _ = ui_handle.beginTable("t", 2, .{});
    defer ui_handle.endTable();
    ui_handle.tableSetupColumn("auto", .{ .width_auto = true });
    ui_handle.tableSetupColumn("stretchy", .{ .sizing = .stretch });

    const ts: *TableState = if (ctx.active_table) |*t| t else return error.NoTable;
    try expectEqual(TableColumnSizing.fixed, ts.columns[0].sizing);
    try expectEqual(@as(f32, 0), ts.columns[0].user_width);
    try expectEqual(TableColumnSizing.stretch, ts.columns[1].sizing);
}

test "P8.6: width_auto wins over explicit sizing and width" {
    // The caller's intent when setting width_auto is unambiguous:
    // fit content.  Any conflicting .sizing or .width on the same
    // opts is ignored — width_auto overrides both.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const ui_handle: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const w: WindowHandle = ui_handle.window("w", .{}) orelse unreachable;
    defer w.close();

    _ = ui_handle.beginTable("t", 1, .{});
    defer ui_handle.endTable();
    // Set conflicting hints: explicit width 200 + stretch sizing,
    // BUT width_auto = true.  The flag wins.
    ui_handle.tableSetupColumn("conflicty", .{
        .sizing = .stretch,
        .width = 200,
        .width_auto = true,
    });

    const ts: *TableState = if (ctx.active_table) |*t| t else return error.NoTable;
    try expectEqual(TableColumnSizing.fixed, ts.columns[0].sizing);
    try expectEqual(@as(f32, 0), ts.columns[0].user_width);
}

