test "P8.8: tableGetColumnCount + Index reflect setup + iteration state" {
    // getColumnCount mirrors `beginTable`'s `n_columns` arg.
    // getColumnIndex returns null until the first tableNextColumn,
    // then tracks the current cell's column 0-based.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w = Window{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 400, 300 }, .draw_list = .{} };
    defer w.draw_list.deinit(ctx.frame_arena.allocator());
    ctx.current_window = &w;
    ctx.current_draw_list = &w.draw_list;
    w.layout.cursor_pos = .{ 10, 10 };
    w.layout.work_rect_max = .{ 400, 300 };

    const u: Ui = .{ .ctx = &ctx };
    // No active table → both queries return null.
    try expectEqual(@as(?u32, null), u.tableGetColumnCount());
    try expectEqual(@as(?u32, null), u.tableGetColumnIndex());

    try expect(u.beginTable("t", 3, .{}));
    try expectEqual(@as(?u32, 3), u.tableGetColumnCount());
    // Inside a table, before any tableNextColumn, cur_col is -1.
    try expectEqual(@as(?u32, null), u.tableGetColumnIndex());
    u.tableNextRow();
    try expectEqual(@as(?u32, null), u.tableGetColumnIndex());
    _ = u.tableNextColumn();
    try expectEqual(@as(?u32, 0), u.tableGetColumnIndex());
    _ = u.tableNextColumn();
    try expectEqual(@as(?u32, 1), u.tableGetColumnIndex());
    _ = u.tableNextColumn();
    try expectEqual(@as(?u32, 2), u.tableGetColumnIndex());
    u.endTable();
    // After endTable, no active table again.
    try expectEqual(@as(?u32, null), u.tableGetColumnCount());
}

