test "DragDropState: starts idle with no payload" {
    const dd: DragDropState = .{};
    try expectEqual(DragDropState.Phase.idle, dd.phase);
    try expectEqual(@as(usize, 0), dd.type_name_len);
    try expectEqual(@as(usize, 0), dd.payload_len);
}

test "setDragDropPayload: stores @typeName + bytes for active drag" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    // Force the state into active manually (in production this
    // happens via the begin* edge logic).
    ctx.drag_drop.phase = .active;

    const PayloadT = struct { build_id: u32, ok: bool };
    const value: PayloadT = .{ .build_id = 1234, .ok = true };
    setDragDropPayloadImpl(&ctx, PayloadT, &value);

    // Type tag stored.
    const tn: []const u8 = ctx.drag_drop.typeName();
    try expect(tn.len > 0);
    try expect(std.mem.indexOf(u8, tn, "PayloadT") != null);

    // Payload bytes round-trip via memcpy into a properly-aligned
    // local - same pattern target-side code uses with
    // acceptDragDropPayload (). Direct @ptrCast off the
    // u8 buffer would be alignment-UB.
    var back: PayloadT = undefined;
    @memcpy(std.mem.asBytes(&back), ctx.drag_drop.payload_buf[0..@sizeOf(PayloadT)]);
    try expectEqual(@as(u32, 1234), back.build_id);
    try expectEqual(true, back.ok);
}

test "setDragDropPayload: no-op when drag is idle" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    // Phase stays idle - call should be silently dropped.
    const v: u32 = 42;
    setDragDropPayloadImpl(&ctx, u32, &v);
    try expectEqual(@as(usize, 0), ctx.drag_drop.type_name_len);
    try expectEqual(@as(usize, 0), ctx.drag_drop.payload_len);
}

test "setDragDropPayload: oversize types are rejected (no type tag)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    ctx.drag_drop.phase = .active;
    // 512 bytes > PAYLOAD_CAP (256).
    const Big = [512]u8;
    var huge: Big = undefined;
    huge[0] = 0xAA;
    setDragDropPayloadImpl(&ctx, Big, &huge);
    // Rejected: type tag cleared so no target will match.
    try expectEqual(@as(usize, 0), ctx.drag_drop.type_name_len);
    try expectEqual(@as(usize, 0), ctx.drag_drop.payload_len);
}

