test "acceptDragDropPayload: type mismatch returns null" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    ctx.drag_drop.phase = .active;
    ctx.drag_drop.target_widget_id = 99;

    // Set a payload of type u32.
    const v: u32 = 42;
    setDragDropPayloadImpl(&ctx, u32, &v);
    // Release edge.
    ctx.input.mouse_left_released = true;

    // Asking for f32 → type mismatch → null.
    const wrong: ?f32 = acceptDragDropPayloadImpl(&ctx, f32, .{});
    try expectEqual(@as(?f32, null), wrong);
    // Asking for the right type → success.
    const right: ?u32 = acceptDragDropPayloadImpl(&ctx, u32, .{});
    try expectEqual(@as(?u32, 42), right);
}

test "acceptDragDropPayload: only delivers on the release edge" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    ctx.drag_drop.phase = .active;
    ctx.drag_drop.target_widget_id = 99;

    const Pld = struct { n: u32 };
    const v: Pld = .{ .n = 7 };
    setDragDropPayloadImpl(&ctx, Pld, &v);

    // No release edge yet - null.
    ctx.input.mouse_left_released = false;
    try expectEqual(@as(?Pld, null), acceptDragDropPayloadImpl(&ctx, Pld, .{}));

    // Release edge → delivered.
    ctx.input.mouse_left_released = true;
    const got = acceptDragDropPayloadImpl(&ctx, Pld, .{});
    try expect(got != null);
    try expectEqual(@as(u32, 7), got.?.n);
}

test "accept_before_delivery returns payload mid-drag (no release)" {
    // The new flag lets a target peek the payload while the mouse
    // is still held down. Useful for "is this droppable here?"
    // visual feedback that updates as the user drags.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    ctx.drag_drop.phase = .active;
    ctx.drag_drop.target_widget_id = 99;

    const Pld = struct { n: u32 };
    const v: Pld = .{ .n = 42 };
    setDragDropPayloadImpl(&ctx, Pld, &v);

    // Mouse STILL held.
    ctx.input.mouse_left_released = false;

    // Without the flag → null (release-edge gated).
    try expectEqual(@as(?Pld, null), acceptDragDropPayloadImpl(&ctx, Pld, .{}));

    // With.accept_before_delivery → returns payload mid-drag.
    const peek: ?Pld = acceptDragDropPayloadImpl(&ctx, Pld, .{ .accept_before_delivery = true });
    try expect(peek != null);
    try expectEqual(@as(u32, 42), peek.?.n);
}

test "accept_peek_only convenience combines flags" {
    // Convenience constant should equal { accept_before_delivery, accept_no_draw_default_rect }.
    const combo_flags: DragDropFlags = DragDropFlags.accept_peek_only;
    try expect(combo_flags.accept_before_delivery);
    try expect(combo_flags.accept_no_draw_default_rect);
    try expect(!combo_flags.source_no_preview);
    try expect(!combo_flags.accept_draw_as_hovered);
}

test "pushItemFlag .disabled suppresses button click" {
    // The new stack-based path should compose with the existing
    // beginDisabled machinery. Verify by pushing disabled, then
    // confirming a synthesized click is ignored.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 400,
        .canvas_h = 300,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    var btn_center: Vec2 = .{ 0, 0 };
    // Frame 1: lay out the button (no click), capture rect.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .disabled = true });
        defer ui.popItemFlag();
        // Button submitted in a disabled scope. Cursor away - no click.
        const clicked: bool = ui.button("Go", .{});
        try expect(!clicked);
        const r: Rectangle = ctx.current_window.?.layout.last_item_rect;
        btn_center = .{ r.x + r.width / 2, r.y + r.height / 2 };
    }
    // Frame 2: synthesize a click ON the button - disabled scope
    // should suppress it.
    {
        const snapshot: InputSnapshot = .{
            .mouse_pos = btn_center,
            .mouse_left_clicked = true,
            .mouse_left_down = true,
            .mouse_left_released = false,
        };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .disabled = true });
        defer ui.popItemFlag();
        // Click on the button. Disabled scope must eat it.
        const clicked: bool = ui.button("Go", .{});
        try expect(!clicked);
        try expect(ui.isDisabled());
    }
}

test "mergeItemFlags OR semantics for bool flags" {
    // disabled / button_repeat / allow_overlap / no_tab_stop OR
    // up the stack; auto_close_popups ANDs (parent's disable wins).
    const parent: ItemFlags = .{
        .disabled = true,
        .button_repeat = false,
        .auto_close_popups = false,
    };
    const child: ItemFlags = .{
        .disabled = false,
        .button_repeat = true,
        .auto_close_popups = true,
    };
    const merged: ItemFlags = mergeItemFlags(parent, child);
    try expect(merged.disabled); // parent's true wins.
    try expect(merged.button_repeat); // child contributes true.
    try expect(!merged.auto_close_popups); // parent's false wins (AND).
}

test "currentItemFlags reads top of stack" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 400,
        .canvas_h = 300,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    // Empty stack → defaults.
    try expect(!ui.currentItemFlags().button_repeat);
    try expect(ui.currentItemFlags().auto_close_popups); // default true.

    ui.pushItemFlag(.{ .button_repeat = true });
    try expect(ui.currentItemFlags().button_repeat);
    ui.popItemFlag();
    try expect(!ui.currentItemFlags().button_repeat);
}

test "button_repeat fires after initial delay then at rate" {
    // Synthesize: hold the button down, advance frame_time_seconds.
    // First press fires (regular click). Then delay (400ms) before
    // first repeat. Then steady cadence of one repeat per 50ms.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 400,
        .canvas_h = 300,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    var btn_center: Vec2 = .{ 0, 0 };
    var press_count: u32 = 0;

    // Frame 0: place button, capture rect, no click.
    {
        const ui: Ui = ctx.beginFrameRaw(
            .{ .delta_time = 0.016 },
            null,
            400,
            300,
            &gl_dummy,
            &shapes_dummy,
            &font_dummy,
        );
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .button_repeat = true });
        defer ui.popItemFlag();
        _ = ui.button("inc", .{});
        const r: Rectangle = ctx.current_window.?.layout.last_item_rect;
        btn_center = .{ r.x + r.width / 2, r.y + r.height / 2 };
    }

    // Frame 1: click-down on the button. Counts as press 1
    // (regular click, the release-edge fires this). But for
    // repeat we just care that active_id_press_time gets stamped.
    {
        const snapshot: InputSnapshot = .{
            .mouse_pos = btn_center,
            .mouse_left_clicked = true,
            .mouse_left_down = true,
            .delta_time = 0.016,
        };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .button_repeat = true });
        defer ui.popItemFlag();
        if (ui.button("inc", .{})) {
            press_count += 1;
        }
    }

    // Frames 2-25: hold button, advance time. Should see no
    // repeats until cumulative held-time exceeds 400ms.
    var early_count: u32 = 0;
    var i: u32 = 0;
    while (i < 23) : (i += 1) {
        const snapshot: InputSnapshot = .{
            .mouse_pos = btn_center,
            .mouse_left_clicked = false,
            .mouse_left_down = true,
            .delta_time = 0.016, // ~23 * 16ms = ~368ms cumulative held
        };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .button_repeat = true });
        defer ui.popItemFlag();
        if (ui.button("inc", .{})) {
            early_count += 1;
        }
    }
    // Below 400ms delay → no repeats fired.
    try expectEqual(@as(u32, 0), early_count);

    // Frames 26+: push past 400ms then through steady repeat cadence.
    // 20 more frames at 16ms each = +320ms, total held ~688ms,
    // ~288ms past the delay → ~5-6 repeats at 50ms cadence.
    var repeat_count: u32 = 0;
    i = 0;
    while (i < 20) : (i += 1) {
        const snapshot: InputSnapshot = .{
            .mouse_pos = btn_center,
            .mouse_left_clicked = false,
            .mouse_left_down = true,
            .delta_time = 0.016,
        };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        ui.pushItemFlag(.{ .button_repeat = true });
        defer ui.popItemFlag();
        if (ui.button("inc", .{})) {
            repeat_count += 1;
        }
    }
    // Expect at least 3 repeats fired (conservative - exact count
    // depends on phase alignment of the 50ms cadence against
    // 16ms frame ticks). This proves the wiring works without
    // being brittle to exact timing.
    try expect(repeat_count >= 3);
}

test "beginDragDropTarget with accept_no_draw_default_rect skips highlight" {
    // Compare draw-cmd count between default vs flag-set call.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 400,
        .canvas_h = 300,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // First pass: figure out the button's rect by submitting once
    // with a far-away mouse; we just need the rect, not interaction.
    var btn_center: Vec2 = .{ 0, 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 400, 300, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window(
            "host",
            .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 200, 200 } },
        ) orelse unreachable;
        defer h.close();
        _ = ui.button("target", .{});
        const r: Rectangle = ctx.current_window.?.layout.last_item_rect;
        btn_center = .{ r.x + r.width / 2, r.y + r.height / 2 };
    }

    // (real test frame): ordinary call - should add the highlight ring.
    {
        const ui: Ui = ctx.beginFrameRaw(
            .{ .mouse_pos = btn_center },
            null,
            400,
            300,
            &gl_dummy,
            &shapes_dummy,
            &font_dummy,
        );
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.button("target", .{});
        // Pretend we're mid-drag: source is some OTHER widget so the
        // button can be a target.
        ctx.drag_drop.phase = .active;
        ctx.drag_drop.source_widget_id = 99999; // not our button's id
        const before: usize = ctx.current_window.?.draw_list.cmds.items.len;
        const ok: bool = ui.beginDragDropTarget(.{});
        try expect(ok);
        const after_default: usize = ctx.current_window.?.draw_list.cmds.items.len;
        try expect(after_default > before); // highlight cmd added
        ui.endDragDropTarget();
        ctx.drag_drop.phase = .idle;
        ctx.drag_drop.target_widget_id = 0;
    }
    // with accept_no_draw_default_rect - no extra cmd.
    {
        const ui: Ui = ctx.beginFrameRaw(
            .{ .mouse_pos = btn_center },
            null,
            400,
            300,
            &gl_dummy,
            &shapes_dummy,
            &font_dummy,
        );
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.button("target", .{});
        ctx.drag_drop.phase = .active;
        ctx.drag_drop.source_widget_id = 99999;
        const before: usize = ctx.current_window.?.draw_list.cmds.items.len;
        const ok: bool = ui.beginDragDropTarget(.{ .accept_no_draw_default_rect = true });
        try expect(ok);
        const after: usize = ctx.current_window.?.draw_list.cmds.items.len;
        try expectEqual(before, after); // no highlight cmd
    }
}

