// ----------------------------------------------------------------------------
// P6 layout/cursor query gaps
// ----------------------------------------------------------------------------
// Coverage tests for the three getters added:
//   - getCursorStartPos (screen-space, matches zimr's cursor
//                              convention; ImGui-divergent on
//                              coordinate space but consistent with
//                              the rest of zimr's cursor accessors)
//   - getWindowContentRegionMin (window-local)
//   - getWindowContentRegionMax (window-local)
// Each test pins the outside-window fallback (returns.{0,0}) AND the
// inside-window math against a hand-set LayoutScope.

test "P6: getCursorStartPos returns (0,0) outside a window scope" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    const p: Vec2 = u.getCursorStartPos();
    try expectEqual(@as(f32, 0), p[0]);
    try expectEqual(@as(f32, 0), p[1]);
}

test "P6: getCursorStartPos returns layout.origin (screen-space)" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
