    var w: Window = .{
        .id = 1,
        .pos = .{ 100, 200 },
        .size = .{ 320, 240 },
        .layout = .{
            .origin = .{ 108, 230 },
            .cursor_pos = .{ 108, 250 },
            .work_rect_max = .{ 416, 432 },
        },
    };
    defer w.draw_list.deinit(std.testing.allocator);
    ctx.current_window = &w;
    const u: Ui = .{ .ctx = &ctx };
    // Screen-space — equals layout.origin verbatim.
    try expectEqual(@as(Vec2, .{ 108, 230 }), u.getCursorStartPos());
}

