test "P6: getWindowContentRegionMin/Max return window-local coords" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{
        .id = 1,
        .pos = .{ 100, 200 },
        .size = .{ 320, 240 },
        .layout = .{
            // Origin sits 8 px inside the window's top-left after
            // chrome + padding — a typical decorated-window layout.
            .origin = .{ 108, 230 },
            // Work rect's bottom-right is inset by similar padding
            // from the window's bottom-right (100+320=420, 200+240=440).
            .work_rect_max = .{ 412, 432 },
        },
    };
    defer w.draw_list.deinit(std.testing.allocator);
    ctx.current_window = &w;
    const u: Ui = .{ .ctx = &ctx };
    // Window-local = scope coords minus window pos.
    try expectEqual(@as(Vec2, .{ 8, 30 }), u.getWindowContentRegionMin());
    try expectEqual(@as(Vec2, .{ 312, 232 }), u.getWindowContentRegionMax());
    // Content region size = max - min, useful for callers.
    const min_corner: Vec2 = u.getWindowContentRegionMin();
    const max_corner: Vec2 = u.getWindowContentRegionMax();
    try expectEqual(@as(f32, 304), max_corner[0] - min_corner[0]);
    try expectEqual(@as(f32, 202), max_corner[1] - min_corner[1]);
}

