// ============================================================================
// tests - markItemPost transitions, setNextWindow*,
// item-state queries. These pin the architectural contracts the
// per-widget bookkeeping relies on (and that user code reads via
// `isItemActive` / `isItemEdited` / `isItemDeactivatedAfterEdit`).
// ============================================================================

test " markItemPost - id=0 items have all flags false" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 100, 100 } };
    defer w.draw_list.deinit(std.testing.allocator);
    // Simulate a non-interactive widget: id=0 plus a hovered rect.
    w.layout.last_item_id = 0;
    w.layout.last_item_hovered = true;
    ctx.input.mouse_left_clicked = true;
    markItemPost(&ctx, &w, true); // even with edited=true, id=0 forces all-false
    try expect(!w.layout.last_item_edited);
    try expect(!w.layout.last_item_clicked);
    try expect(!w.layout.last_item_activated);
    try expect(!w.layout.last_item_deactivated);
    try expect(!w.layout.last_item_deactivated_after_edit);
}

test " markItemPost - clicked = hovered AND mouse-down-this-frame" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 100, 100 } };
    defer w.draw_list.deinit(std.testing.allocator);
