    // No-click frame: clicked should clear.
    ctx.input.mouse_left_clicked = false;
    markItemPost(&ctx, &w, false);
    try expect(!w.layout.last_item_clicked);

    // Click-but-not-hovered: clicked stays false.
    w.layout.last_item_hovered = false;
    ctx.input.mouse_left_clicked = true;
    markItemPost(&ctx, &w, false);
    try expect(!w.layout.last_item_clicked);
}

test " markItemPost - activation transitions over 3 frames" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 100, 100 } };
    defer w.draw_list.deinit(std.testing.allocator);
    const id: Id = 0x1234;

    // Frame 1: widget inactive → no transition.
    w.layout.last_item_id = id;
    ctx.active_id = 0;
    ctx.active_id_prev_frame = 0;
    markItemPost(&ctx, &w, false);
    try expect(!w.layout.last_item_activated);
    try expect(!w.layout.last_item_deactivated);

    // Frame 2: widget activates this frame.
    ctx.active_id = id;
    ctx.active_id_prev_frame = 0;
    markItemPost(&ctx, &w, false);
    try expect(w.layout.last_item_activated);
    try expect(!w.layout.last_item_deactivated);

    // Frame 3: widget continues active.
    ctx.active_id = id;
    ctx.active_id_prev_frame = id;
    markItemPost(&ctx, &w, false);
    try expect(!w.layout.last_item_activated);
    try expect(!w.layout.last_item_deactivated);

    // Frame 4: widget deactivates.
    ctx.active_id = 0;
    ctx.active_id_prev_frame = id;
    markItemPost(&ctx, &w, false);
    try expect(!w.layout.last_item_activated);
    try expect(w.layout.last_item_deactivated);
}

test " markItemPost - deactivatedAfterEdit sticky during activation" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 100, 100 } };
    defer w.draw_list.deinit(std.testing.allocator);
    const id: Id = 0x5678;
    w.layout.last_item_id = id;

    // Activate without edit.
    ctx.active_id = id;
    ctx.active_id_prev_frame = 0;
    markItemPost(&ctx, &w, false);
    try expect(!ctx.active_id_was_edited);

    // Mid-activation edit fires - flag goes sticky.
    ctx.active_id = id;
    ctx.active_id_prev_frame = id;
    markItemPost(&ctx, &w, true);
    try expect(ctx.active_id_was_edited);

    // Continue holding (no edit this frame) - flag remains sticky.
    markItemPost(&ctx, &w, false);
    try expect(ctx.active_id_was_edited);

    // Deactivate - surface deactivatedAfterEdit, then clear sticky.
    ctx.active_id = 0;
    ctx.active_id_prev_frame = id;
    markItemPost(&ctx, &w, false);
    try expect(w.layout.last_item_deactivated);
    try expect(w.layout.last_item_deactivated_after_edit);
    try expect(!ctx.active_id_was_edited); // sticky cleared
}

test " markItemPost - no-edit deactivation does NOT set deactivatedAfterEdit" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    var w: Window = .{ .id = 1, .pos = .{ 0, 0 }, .size = .{ 100, 100 } };
    defer w.draw_list.deinit(std.testing.allocator);
    const id: Id = 0x9ABC;
    w.layout.last_item_id = id;

    // Activate, hold, release - never edited.
    ctx.active_id = id;
    ctx.active_id_prev_frame = 0;
    markItemPost(&ctx, &w, false);
    ctx.active_id_prev_frame = id;
    markItemPost(&ctx, &w, false);
    ctx.active_id = 0;
    markItemPost(&ctx, &w, false);
    try expect(w.layout.last_item_deactivated);
    try expect(!w.layout.last_item_deactivated_after_edit);
}

test " setNextWindow* state persists in UiContext + clears on use" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    // Field defaults - no overrides pending.
    try expect(ctx.next_window_pos == null);
    try expect(ctx.next_window_size == null);
    try expect(ctx.next_window_pos_always); // default is "every frame"
    try expect(ctx.next_window_size_always);
    try expect(!ctx.next_window_focus);

    // Setting via the public API stores the override.
    const ui: Ui = .{ .ctx = &ctx };
    ui.setNextWindowPos(.{ 100, 50 }, .{});
    ui.setNextWindowSize(.{ 300, 200 }, .{ .once = true });
    ui.setNextWindowFocus();
    try expectEqual(@as(?Vec2, .{ 100, 50 }), ctx.next_window_pos);
    try expectEqual(@as(?Vec2, .{ 300, 200 }), ctx.next_window_size);
    try expect(ctx.next_window_pos_always); // .{}.once defaults to false → always = !once = true
    try expect(!ctx.next_window_size_always); // .once = true → always = false
    try expect(ctx.next_window_focus);
}

