// ============================================================================
// - vertical scrollbar + auto-fit gating
// These pin the scroll math contract - when content overflows the
// window viewport, scroll_max_y is positive; clamping keeps scroll_y
// in `[0, scroll_max_y]`; mouse-wheel translates wheel ticks; the
// auto-fit grow path defers to user_resized.
// ============================================================================

test " openWindow shifts cursor by scroll_y" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle: WindowHandle = ui.window("scroll_test", .{}) orelse unreachable;
    const w: *Window = handle.win;
    // First frame: scroll_y is zero; cursor sits at inner_origin.
    const inner_origin_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    try expectEqual(inner_origin_y, w.layout.cursor_pos[1]);
    handle.close();

    // Second frame: simulate scroll, re-open, cursor should be shifted up.
    w.scroll_y = 30;
    _ = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle2: WindowHandle = ui.window("scroll_test", .{}) orelse unreachable;
    const w2: *Window = handle2.win;
    try expectEqual(inner_origin_y - 30, w2.layout.cursor_pos[1]);
    handle2.close();
}

test " closeWindow computes scroll_max_y from content overflow" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle: WindowHandle = ui.window(
        "overflow_test",
        .{ .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    const w: *Window = handle.win;
    // Force `user_resized` so closeWindow doesn't grow the window
    // to absorb our simulated content.
    w.user_resized = true;
    // Simulate 300px of content (cursor ends 300 below origin).
    const inner_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    w.layout.cursor_max = .{ w.pos[0] + 100, inner_y + 300 };
    handle.close();

    const viewport_h: f32 = 100 - ctx.style.title_bar_height - ctx.style.window_padding[1];
    try expectEqual(@as(f32, 300 - viewport_h), w.scroll_max_y);
}

test " scroll_y clamps to [0, scroll_max_y]" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    // First frame: create the window so subsequent frames can mutate
    // its persistent state directly.
    const create: WindowHandle = ui.window(
        "clamp_test",
        .{ .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    const w: *Window = create.win;
    w.user_resized = true;
    create.close();

    // Second frame: pre-set scroll_y way past content extent. The
    // window's openWindow will pick it up and shift cursor_pos
    // accordingly; we record cursor_max consistent with that shift.
    w.scroll_y = 99999;
    _ = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window(
        "clamp_test",
        .{ .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    // Simulate a widget that records 200px of content past the
    // (shifted-by-scroll_y) cursor position.
    h.win.layout.cursor_max = .{ h.win.layout.cursor_pos[0], h.win.layout.cursor_pos[1] + 200 };
    h.close();
    try expect(h.win.scroll_y == h.win.scroll_max_y);
    try expect(h.win.scroll_y < 99999);

    // Third frame: negative scroll_y also clamps to 0.
    h.win.scroll_y = -50;
    _ = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h2: WindowHandle = ui.window(
        "clamp_test",
        .{ .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    h2.win.layout.cursor_max = .{ h2.win.layout.cursor_pos[0], h2.win.layout.cursor_pos[1] + 200 };
    h2.close();
    try expectEqual(@as(f32, 0), h2.win.scroll_y);
}

test " mouse wheel translates scroll_y on the hovered window" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const wheel_input: InputSnapshot = .{ .mouse_wheel_y = -1, .mouse_pos = .{ 100, 100 } };
    const ui: Ui = ctx.beginFrameRaw(wheel_input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle: WindowHandle = ui.window(
        "wheel_test",
        .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    const w: *Window = handle.win;
    w.user_resized = true;
    // Mouse pos (100, 100) is inside window rect (50, 50, 200, 100) →
    // openWindow set hovered_window_id to this window.
    try expect(ctx.hovered_window_id == w.id);
    // Simulate enough content to enable scrolling.
    const inner_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    w.layout.cursor_max = .{ w.pos[0], inner_y + 500 };
    handle.close();
    // Wheel = -1 ⇒ scroll DOWN ⇒ scroll_y increases by `5 * font_size`.
    try expect(w.scroll_y > 0);
    try expect(w.scroll_y <= w.scroll_max_y);
}

test "touch-pan: drag on window body scrolls when content overflows" {
    // Mobile devices don't emit wheel events from finger drags; touch
    // is mirrored to left-mouse-down + mouse_move.  closeWindow's
    // touch-pan branch translates this into scroll_y / scroll_x.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    // Frame 1 — touch begins inside the window body.
    const touch_start: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_left_down = true,
        .mouse_left_clicked = true,
    };
    const ui1: Ui = ctx.beginFrameRaw(touch_start, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h1: WindowHandle = ui1.window(
        "pan_test",
        .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    const w: *Window = h1.win;
    w.user_resized = true;
    // Inject content overflow so scroll_max_y > 0.
    const inner_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    w.layout.cursor_max = .{ w.pos[0], inner_y + 500 };
    h1.close();
    try expect(w.touch_pan_active);
    const start_scroll: f32 = w.scroll_y;
    // Frame 2 — finger moved up 40 px while still held.  Content should
    // scroll DOWN (scroll_y increases) by 40.
    const touch_drag: InputSnapshot = .{
        .mouse_pos = .{ 100, 60 },
        .mouse_left_down = true,
    };
    const ui2: Ui = ctx.beginFrameRaw(touch_drag, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h2: WindowHandle = ui2.window("pan_test", .{}) orelse unreachable;
    h2.win.layout.cursor_max = .{ h2.win.pos[0], inner_y + 500 };
    h2.close();
    try expectApproxEqAbs(start_scroll + 40, h2.win.scroll_y, 0.5);
    // Frame 3 — finger released.  Pan deactivates.
    const touch_release: InputSnapshot = .{
        .mouse_pos = .{ 100, 60 },
        .mouse_left_down = false,
    };
    const ui3: Ui = ctx.beginFrameRaw(touch_release, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h3: WindowHandle = ui3.window("pan_test", .{}) orelse unreachable;
    h3.close();
    try expect(!h3.win.touch_pan_active);
}

test "touch-pan: does not hijack when the drag starts outside the window" {
    // A finger that presses DOWN outside the window and then drags across
    // it must NOT start scrolling that window. (On touch, hover follows the
    // finger, so the old code started a pan the moment the finger entered.)
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    // Frame 1 — press down well outside the window's rect.
    const down_outside: InputSnapshot = .{
        .mouse_pos = .{ 500, 450 },
        .mouse_left_down = true,
        .mouse_left_clicked = true,
    };
    const ui1: Ui = ctx.beginFrameRaw(down_outside, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h1: WindowHandle = ui1.window(
        "pan_outside",
        .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 200, 100 } },
    ) orelse unreachable;
    const w: *Window = h1.win;
    w.user_resized = true;
    const inner_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    w.layout.cursor_max = .{ w.pos[0], inner_y + 500 };
    h1.close();
    // Simulate the sticky-hover hazard: hovered_window_id never clears, so it
    // can still point at this window while the finger is in empty space.
    ctx.hovered_window_id = w.id;
    try expect(!w.touch_pan_active);
    // Frame 2 — finger still held, now dragged OVER the window body. The
    // press did not begin here, so no pan must start.
    const drag_in: InputSnapshot = .{
        .mouse_pos = .{ 100, 90 },
        .mouse_left_down = true,
    };
    const ui2: Ui = ctx.beginFrameRaw(drag_in, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h2: WindowHandle = ui2.window("pan_outside", .{}) orelse unreachable;
    h2.win.layout.cursor_max = .{ h2.win.pos[0], inner_y + 500 };
    h2.close();
    try expect(!h2.win.touch_pan_active);
    try expectEqual(@as(f32, 0), h2.win.scroll_y);
    // Frame 3 — a brand-new press DOWN in empty space while hovered_window_id
    // still (stale) points at the window. Geometric gate must reject it.
    ctx.hovered_window_id = w.id;
    const press_empty: InputSnapshot = .{
        .mouse_pos = .{ 600, 500 },
        .mouse_left_down = true,
        .mouse_left_clicked = true,
    };
    const ui3: Ui = ctx.beginFrameRaw(press_empty, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h3: WindowHandle = ui3.window("pan_outside", .{}) orelse unreachable;
    h3.win.layout.cursor_max = .{ h3.win.pos[0], inner_y + 500 };
    h3.close();
    try expect(!h3.win.touch_pan_active);
    try expectEqual(@as(f32, 0), h3.win.scroll_y);
}

test "touch-pan: does not activate when there's nothing to scroll" {
    // Pan must remain dormant on windows whose content fits — otherwise
    // every touch in a non-scrolling window would briefly start a
    // gesture and potentially clobber widget interactions.
    // Pan must remain dormant on windows whose content fits — otherwise
    // every touch in a non-scrolling window would briefly start a
    // gesture and potentially clobber widget interactions.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const touch: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_left_down = true,
    };
    const ui: Ui = ctx.beginFrameRaw(touch, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window(
        "no_overflow",
        .{ .initial_pos = .{ 50, 50 }, .initial_size = .{ 200, 400 } },
    ) orelse unreachable;
    h.win.user_resized = true;
    // Content fits well within 400 px height — no overflow.
    h.close();
    try expect(!h.win.touch_pan_active);
    try expectEqual(@as(f32, 0), h.win.scroll_max_y);
}

test " auto-fit grows window only while user_resized = false" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle: WindowHandle = ui.window(
        "autofit_test",
        .{ .initial_size = .{ 100, 50 } },
    ) orelse unreachable;
    const w: *Window = handle.win;
    // No setNextWindowSize, no manual resize → user_resized stays false.
    try expect(!w.user_resized);
    // Pretend a widget grew the cursor past the initial size.
    const inner_y: f32 = w.pos[1] + ctx.style.title_bar_height + ctx.style.window_padding[1];
    w.layout.cursor_max = .{ w.pos[0] + 250, inner_y + 200 };
    handle.close();
    try expect(w.size[0] >= 250);
    try expect(w.size[1] > 200);

    // Now mark resized and re-submit with the same overflow - size
    // should NOT grow; scroll_max_y should be positive instead.
    const prior_w: f32 = w.size[0];
    const prior_h: f32 = w.size[1];
    w.user_resized = true;
    _ = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h2: WindowHandle = ui.window(
        "autofit_test",
        .{ .initial_size = .{ 100, 50 } },
    ) orelse unreachable;
    h2.win.layout.cursor_max = .{ h2.win.pos[0], inner_y + prior_h + 300 };
    h2.close();
    try expectEqual(prior_w, h2.win.size[0]);
    try expectEqual(prior_h, h2.win.size[1]);
    try expect(h2.win.scroll_max_y > 0);
}

// ============================================================================
// tests - layout helpers, item-width stack, disabled gating,
// groups. Each pins one architectural contract.
// ============================================================================

test " multiplyAlpha clamps + scales" {
    // Opaque red, mul 0.5 → 255*0.5 = 127.5, round-to-nearest → 128.
    const red: ColorU32 = 0xFF0000FF; // packed: AABBGGRR
    const half: ColorU32 = multiplyAlpha(red, 0.5);
    try expectEqual(@as(u32, 0x800000FF), half);
    // mul 1.0 short-circuits - same value back.
    try expectEqual(red, multiplyAlpha(red, 1.0));
    // mul 0 → fully transparent.
    try expectEqual(@as(u32, 0x000000FF), multiplyAlpha(red, 0));
}

test " effectiveItemWidth priority - next > stack > opts > default" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    // Default falls through when nothing set.
    try expectEqual(@as(f32, 100), effectiveItemWidth(&ctx, 0, 100));
    // opts wins over default.
    try expectEqual(@as(f32, 50), effectiveItemWidth(&ctx, 50, 100));
    // Stack wins over opts.
    ctx.item_width_stack.append(75) catch panicf(@src(), "OOM", .{});
    try expectEqual(@as(f32, 75), effectiveItemWidth(&ctx, 50, 100));
    // next_item_width wins over stack - and gets cleared on read.
    ctx.next_item_width = 200;
    try expectEqual(@as(f32, 200), effectiveItemWidth(&ctx, 50, 100));
    try expect(ctx.next_item_width == null);
    // After clear, fall back to stack.
    try expectEqual(@as(f32, 75), effectiveItemWidth(&ctx, 50, 100));
}

test " pushItemWidth/popItemWidth balance" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const ui: Ui = .{ .ctx = &ctx };
    ui.pushItemWidth(40);
    ui.pushItemWidth(60);
    try expectEqual(@as(?f32, 60), ctx.item_width_stack.top());
    ui.popItemWidth();
    try expectEqual(@as(?f32, 40), ctx.item_width_stack.top());
    ui.popItemWidth();
    try expectEqual(@as(?f32, null), ctx.item_width_stack.top());
}

test " beginDisabled gates input on outermost transition" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const ui: Ui = .{ .ctx = &ctx };

    // Pretend a click is pending.
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;

    ui.beginDisabled(true);
    // Input cleared while disabled.
    try expect(!ctx.input.mouse_left_clicked);
    try expect(!ctx.input.mouse_left_down);
    try expectEqual(ctx.style.disabled_alpha, ctx.alpha_mul);

    // Nested beginDisabled bumps count but doesn't re-save.
    ui.beginDisabled(true);
    try expectEqual(@as(u32, 2), ctx.disabled_count);
    ui.endDisabled(); // count back to 1, still disabled
    try expect(!ctx.input.mouse_left_clicked);

    // Outermost endDisabled restores.
    ui.endDisabled();
    try expect(ctx.input.mouse_left_clicked);
    try expect(ctx.input.mouse_left_down);
    try expectEqual(@as(f32, 1.0), ctx.alpha_mul);
}

test " beginDisabled(false) is a no-op pass-through" {
    var ctx: UiContext = UiContext.init(std.testing.allocator);
