// ============================================================================
// tests - popup primitives. Each pins one architectural
// contract: open/close lifecycle, isPopupOpen accuracy, beginPopup
// returns false when closed, click-outside dismissal, frame-grace
// for the opening click.
// ============================================================================

test " openPopup + isPopupOpen + closeCurrentPopup lifecycle" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const handle: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer handle.close();

    // Initially closed.
    try expect(!ui.isPopupOpen("ctx_menu"));
    ui.openPopup("ctx_menu");
    try expect(ui.isPopupOpen("ctx_menu"));

    // Open + begin scope returns true.
    try expect(ui.beginPopup("ctx_menu"));
    ui.closeCurrentPopup();
    ui.endPopup();
    try expect(!ui.isPopupOpen("ctx_menu"));
}

test " beginPopup returns false when popup is closed" {
