}

test " click-outside dismisses popup on subsequent frames" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    // Frame 1 - open at anchor (200, 200). Popup rect roughly (200, 200, 120, 60).
    {
        const opening_input: InputSnapshot = .{ .mouse_pos = .{ 200, 200 } };
        const ui: Ui = ctx.beginFrameRaw(opening_input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        ui.openPopup("p");
        // Submit the popup so its size is recorded.
        if (ui.beginPopup("p")) {
            ui.endPopup();
        }
        h.close();
    }
    // Frame 2 - click far outside popup rect. Frame-grace allows
    // dismissal because opened_at_frame < frame_count.
    {
        const click_outside: InputSnapshot = .{
            .mouse_pos = .{ 500, 500 },
            .mouse_left_clicked = true,
        };
        const ui: Ui = ctx.beginFrameRaw(click_outside, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        try expect(!ui.isPopupOpen("p"));
        h.close();
    }
}

test " opening-frame click does NOT dismiss the popup" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    // Single frame - click happens THIS frame; openPopup happens
    // THIS frame at the same time. The frame-grace check should
    // suppress the dismiss.
    const open_and_click: InputSnapshot = .{
        .mouse_pos = .{ 200, 200 },
        .mouse_left_clicked = true,
    };
    const ui: Ui = ctx.beginFrameRaw(open_and_click, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    ui.openPopup("p");
    // Same frame - popup should remain open inside the host scope.
    // (The frame-grace blocked the dismiss check at beginFrame, AND
    // openPopup happened post-beginFrame so the dismissal pass had
    // already run.)
    try expect(ui.isPopupOpen("p"));
    h.close();
}

