    _ = ui.beginMainMenuBar();
    const before_x: f32 = ctx.menu_bar_cursor_x;
    const opened: bool = ui.beginMenu("File");
    try expect(opened);
    if (opened) {
        ui.endMenu();
    }
    // Cursor advanced.
    try expect(ctx.menu_bar_cursor_x > before_x);
    ui.endMainMenuBar();
}

test " menuItem returns true on click + closes parent menu" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Click positions derived from style so future default tweaks
    // don't drift this test.  Previous version hard-coded
    // `(30, 10)` and `(30, 36)` against the old menu_bar_height=22
    // / window_padding=8 defaults; both shifted when the desktop-
    // default bump moved those to 28 / 10.
    const bar_click_y: f32 = ctx.style.menu_bar_height * 0.5;
    const item_click_y: f32 = ctx.style.menu_bar_height +
        ctx.style.window_padding[1] +
        ctx.style.frame_padding[1] + 2;
    const click_x: f32 = 30; // inside the "File" button regardless of font

    // Frame 1 - open the menu via click on its bar button.
    {
        const click_input: InputSnapshot = .{
            .mouse_pos = .{ click_x, bar_click_y },
            .mouse_left_clicked = true,
        };
        const ui: Ui = ctx.beginFrameRaw(click_input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        _ = ui.beginMainMenuBar();
        if (ui.beginMenu("File")) {
            ui.endMenu();
        }
        ui.endMainMenuBar();
    }
    // Frame 2 - menu is open. Click on a menu item inside it.
    // Popup is anchored at the bar button (x≈8, y=menu_bar_height).
    // First menuItem renders at (anchor.x + window_padding.x,
    // anchor.y + window_padding.y), so a click slightly inside
    // that origin lands on the first item.
    {
        const click_item: InputSnapshot = .{
            .mouse_pos = .{ click_x, item_click_y },
            .mouse_left_clicked = true,
        };
        const ui: Ui = ctx.beginFrameRaw(click_item, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        _ = ui.beginMainMenuBar();
        var clicked: bool = false;
        if (ui.beginMenu("File")) {
            clicked = ui.menuItem("Open", .{ .shortcut = "Ctrl+O" });
            ui.endMenu();
        }
        ui.endMainMenuBar();
        try expect(clicked);
        // Menu auto-closed after the click.
        const bar_id: Id = ctx.main_menu_bar_win.?.id;
        const menu_id: Id = hashStr(bar_id, "File");
        try expect(!ctx.popup_open.contains(menu_id));
    }
}

