// ---- Turn 411 tab-bg priority + lift geometry suite ---------------
//

// Sentinel pattern: pick three style colors that pack to distinct
// ColorU32 values so we can scan `w.draw_list.cmds` and identify
// which rect_filled came from which style slot. Helpers below.

/// Packed sentinel colors for the four tab states a paint can land
/// in. Returned from `turn411TabStyle` so tests can read each
/// state's color back from the draw list by exact-match comparison.
const TabSentinelColors = struct {
    tab_idle: ColorU32,
    tab_hovered: ColorU32,
    tab_active: ColorU32,
    separator: ColorU32,
};

fn turn411TabStyle(ctx: *UiContext) TabSentinelColors {
    // Distinct sentinel colors per state so a draw-list scan
    // tells us unambiguously which branch fired.
    ctx.style.tab = .{ .r = 0x11, .g = 0x11, .b = 0x11, .a = 0xFF };
    ctx.style.tab_hovered = .{ .r = 0x22, .g = 0x22, .b = 0x22, .a = 0xFF };
    ctx.style.tab_active = .{ .r = 0x33, .g = 0x33, .b = 0x33, .a = 0xFF };
    ctx.style.tab_separator = .{ .r = 0x44, .g = 0x44, .b = 0x44, .a = 0xFF };
    return .{
        .tab_idle = Color.toWire(ctx.style.tab),
        .tab_hovered = Color.toWire(ctx.style.tab_hovered),
        .tab_active = Color.toWire(ctx.style.tab_active),
        .separator = Color.toWire(ctx.style.tab_separator),
    };
}

/// Result of scanning the draw list for a specific rect color.
/// `idx` lets tests compare relative paint order; `rect` lets them
/// check geometry (e.g. the active-tab lift effect via height).
const FoundRectFilled = struct {
    idx: usize,
    rect: Rectangle,
};

/// Search the window's draw list for a rect_filled command matching
/// `col`. Returns the first match (lowest index) or null.
fn findRectFilled(w: *const Window, col: ColorU32) ?FoundRectFilled {
    for (w.draw_list.cmds.items, 0..) |c, i| {
        if (c != .rect_filled) {
            continue;
        }
        if (c.rect_filled.col == col) {
            return .{ .idx = i, .rect = c.rect_filled.rect };
        }
    }
    return null;
}

test "Turn 411: hovered idle tab paints with tab_hovered" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const cols: TabSentinelColors = turn411TabStyle(&ctx);
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 300 } };

    // First frame: submit A (auto-selects) + B. Capture B's rect.
    var b_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.beginTabBar("bar", .{});
        if (ui.beginTabItem("A", null, .{})) {
            ui.endTabItem();
        }
        if (ui.beginTabItem("B", null, .{})) {
            ui.endTabItem();
        }
        b_rect = h.win.layout.last_item_rect;
        ui.endTabBar();
        h.close();
    }

    // Second frame: mouse parked on B (B is NOT active — A is the
    // auto-selected one). Expect B's bg color = tab_hovered.
    const input: InputSnapshot = .{
        .mouse_pos = .{ b_rect.x + b_rect.width / 2, b_rect.y + b_rect.height / 2 },
    };
    const ui: Ui = ctx.beginFrameRaw(input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    defer ui.endTabBar();
    if (ui.beginTabItem("A", null, .{})) {
        ui.endTabItem();
    }
    if (ui.beginTabItem("B", null, .{})) {
        ui.endTabItem();
    }

    // The hovered-but-idle B tab queued a rect_filled in tab_hovered.
    try expect(findRectFilled(h.win, cols.tab_hovered) != null);
}

test "Turn 411: hover wins over active (active+hovered → tab_hovered, not tab_active)" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const cols: TabSentinelColors = turn411TabStyle(&ctx);
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 300 } };

    // Frame 1: submit A (auto-selects) and capture its rect.
    var a_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.beginTabBar("bar", .{});
        if (ui.beginTabItem("A", null, .{})) {
            ui.endTabItem();
        }
        a_rect = h.win.layout.last_item_rect;
        ui.endTabBar();
        h.close();
    }

    // Frame 2: A is still active (selected_id == A), AND we park the
    // mouse inside A. The crucial check: bg should be tab_hovered
    // (press-feedback) NOT tab_active. Pre-turn-411 zimr did the
    // opposite priority and this is the regression alarm for that.
    const input: InputSnapshot = .{
        .mouse_pos = .{ a_rect.x + a_rect.width / 2, a_rect.y + a_rect.height / 2 },
    };
    const ui: Ui = ctx.beginFrameRaw(input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    defer ui.endTabBar();
    if (ui.beginTabItem("A", null, .{})) {
        ui.endTabItem();
    }

    // hovered-AND-active A: tab_hovered SHOULD appear, tab_active
    // should NOT. Two independent assertions for clarity.
    try expect(findRectFilled(h.win, cols.tab_hovered) != null);
    try expect(findRectFilled(h.win, cols.tab_active) == null);
}

