test "Turn 411: separator paints BEFORE any tab bg (enables lift via geometry)" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const cols: TabSentinelColors = turn411TabStyle(&ctx);
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 300 } };

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    defer ui.endTabBar();
    if (ui.beginTabItem("A", null, .{})) {
        ui.endTabItem();
    }

    // The separator (drawn first in openTabBar) must appear in the
    // draw list at a lower index than the tab's bg (drawn during
    // beginTabItem). Pre-turn-411 the separator was drawn at
    // endTabBar time and ended up AFTER the tab bg — that order
    // meant the separator overdrew every tab's bottom 1px, making
    // the "lift effect" require a separate 1px overdraw slice.
    const sep: FoundRectFilled = findRectFilled(h.win, cols.separator) orelse
        return error.SeparatorMissing;
    const a_bg: FoundRectFilled = findRectFilled(h.win, cols.tab_active) orelse
        return error.TabBgMissing;
    try expect(sep.idx < a_bg.idx);
}

test "Turn 411: active tab bg covers full bar height; inactive trims 1px" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const cols: TabSentinelColors = turn411TabStyle(&ctx);
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 300 } };

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    defer ui.endTabBar();
    if (ui.beginTabItem("A", null, .{})) {
        ui.endTabItem(); // active
    }
    if (ui.beginTabItem("B", null, .{})) {
        ui.endTabItem(); // idle
    }

    const a_bg: FoundRectFilled = findRectFilled(h.win, cols.tab_active) orelse
        return error.ActiveBgMissing;
    const b_bg: FoundRectFilled = findRectFilled(h.win, cols.tab_idle) orelse
        return error.IdleBgMissing;
    // Inactive tab's bg is exactly 1px shorter than active's. This
    // is the geometric encoding of the "active tab merges with the
    // content below" lift effect — active covers the separator,
    // idle stops just above it.
    try expectEqual(@as(f32, 1.0), a_bg.rect.height - b_bg.rect.height);
}

test "tabs persisted across frames" {
    // The new tab list (TabBarState.tabs) accumulates entries the
    // first time each tab is seen, then re-finds them on subsequent
    // frames. Pin both: 3 tabs submitted twice → exactly 3 entries.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    var bar_id: Id = 0;
    var frame: u32 = 0;
    while (frame < 2) : (frame += 1) {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.beginTabBar("bar", .{});
        defer ui.endTabBar();
        if (frame == 0) {
            bar_id = hashStr(h.win.id, "bar");
        }
        if (ui.beginTabItem("A", null, .{})) {
            ui.endTabItem();
        }
        if (ui.beginTabItem("B", null, .{})) {
            ui.endTabItem();
        }
        if (ui.beginTabItem("C", null, .{})) {
            ui.endTabItem();
        }
    }
    const state: *TabBarState = ctx.tab_bar_state.getPtr(bar_id) orelse unreachable;
    try expectEqual(@as(usize, 3), state.tabs.items.len);
}

