    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    if (ui.beginTabItem("A", null, .{})) {
        ui.endTabItem();
    }
    // .set_selected on B should ROUTE selection through next_selected_id.
    if (ui.beginTabItem("B", null, .{ .set_selected = true })) {
        ui.endTabItem();
    }
    ui.endTabBar();
    const bar_id: Id = hashStr(h.win.id, "bar");
    const b_id: Id = hashStr(bar_id, "B");
    const state: *TabBarState = ctx.tab_bar_state.getPtr(bar_id) orelse unreachable;
    try expectEqual(b_id, state.selected_id);
}

test "leading + trailing tabs pin to their edges" {
    // Layout check: leading tab gets x_offset at bar.x; middle tabs
    // follow after; trailing tab is at the right edge. We don't
    // store x_offset per-tab in the state today (computed at render
    // time), so this test exercises the cursor advancement through
    // the bar frame: after submitting one leading + one middle, the
    // middle_cursor_x should be greater than the leading_cursor_x's
    // starting position.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{ .initial_size = .{ 600, 400 } }) orelse unreachable;
    defer h.close();
    _ = ui.beginTabBar("bar", .{});
    if (ui.beginTabItem("Lead", null, .{ .leading = true })) {
        ui.endTabItem();
    }
    if (ui.beginTabItem("Mid", null, .{})) {
        ui.endTabItem();
    }
    if (ui.beginTabItem("Trail", null, .{ .trailing = true })) {
        ui.endTabItem();
    }
    // Inspect the frame's cursors before endTabBar pops it.
    const frame: TabBarFrame = ctx.tab_bar_stack.items[ctx.tab_bar_stack.len - 1];
    try expect(frame.leading_cursor_x > frame.rect.x);
    try expect(frame.middle_cursor_x > frame.leading_cursor_x);
    try expect(frame.trailing_cursor_x < frame.rect.x + frame.rect.width);
    ui.endTabBar();
}

test "middle-click closes tab (default behavior)" {
    // Two frames: first to lay out tabs + capture rects, second to
    // place mouse on tab B and middle-click. Expect tab_open to be
    // false after endTabBar finalizes the close.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    var b_center: Vec2 = .{ 0, 0 };
    var a_open: bool = true;
    var b_open: bool = true;
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{ .initial_size = .{ 600, 400 } }) orelse unreachable;
        defer h.close();
        _ = ui.beginTabBar("bar", .{});
        defer ui.endTabBar();
        if (ui.beginTabItem("A", &a_open, .{})) {
            ui.endTabItem();
        }
        if (ui.beginTabItem("B", &b_open, .{})) {
            ui.endTabItem();
        }
        // Capture B's screen rect: last_item_rect on the window after
        // submitting B is B's button.
        const r: Rectangle = ctx.current_window.?.layout.last_item_rect;
        b_center = .{ r.x + r.width / 2, r.y + r.height / 2 };
    }
    {
        const snapshot: InputSnapshot = .{ .mouse_pos = b_center, .mouse_middle_clicked = true };
        const ui: Ui = ctx.beginFrameRaw(snapshot, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.beginTabBar("bar", .{});
        defer ui.endTabBar();
        if (ui.beginTabItem("A", &a_open, .{})) {
            ui.endTabItem();
        }
        if (ui.beginTabItem("B", &b_open, .{})) {
            ui.endTabItem();
        }
    }
    // endTabBar should have written b_open = false on the close finalize.
    try expect(a_open);
    try expect(!b_open);
}

