test " beginListBox/endListBox saves+restores cursor" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    const before: Vec2 = h.win.layout.cursor_pos;
    try expect(ui.beginListBox("items", .{ 200, 80 }));
    // After's child-as-Window refactor, the host window's
    // layout is NOT mutated during the listBox scope - the list box
    // has its own Window with its own layout. The current_window
    // pointer flips to the list box's Window. Verify it.
    const list_box: *Window = ctx.current_window.?;
    try expect(list_box != h.win);
    try expect(list_box.flags.is_child);
    // The list box's cursor starts at its inner_origin (inside the
    // frame_padding), distinct from the host's cursor which still
    // points where it was before beginListBox.
    try expect(list_box.layout.cursor_pos[0] != before[0] or list_box.layout.cursor_pos[1] != before[1]);
    try expectEqual(before, h.win.layout.cursor_pos);
    ui.endListBox();
    // After endListBox, host's cursor advanced past the box (Y > before.y).
    try expect(h.win.layout.cursor_pos[1] >= before[1]);
}

