test " progressBar clamps fraction + records last_item_rect" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    const before_y: f32 = h.win.layout.cursor_pos[1];

    // Out-of-range fractions should clamp visually but not crash;
    // the item rect should reflect requested size.
    const requested_size: Vec2 = .{ 200, 20 };
    ui.progressBar(2.5, requested_size, ""); // > 1, clamps to 1
    try expectEqual(@as(f32, 200), h.win.layout.last_item_rect.width);
    try expectEqual(@as(f32, 20), h.win.layout.last_item_rect.height);

    ui.progressBar(-0.5, requested_size, "loading"); // < 0, clamps to 0
    // Cursor should have advanced after both calls.
    try expect(h.win.layout.cursor_pos[1] > before_y);
}

test " vSlider drives value when clicked + dragged" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 200, 200 } };
    var v: f32 = 0.5;

    // Frame 1 - render so we know the bar's rect.
    var bar_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.vSlider("vol", .{ 20, 100 }, &v, .{ .min = 0, .max = 1 });
        bar_rect = h.win.layout.last_item_rect;
        h.close();
    }

    // Frame 2 - click at the TOP of the bar. Top = max in vertical
    // slider convention, so v should jump close to opts.max=1.0.
    {
        const click_top: InputSnapshot = .{
            .mouse_pos = .{ bar_rect.x + bar_rect.width / 2, bar_rect.y + 2 },
            .mouse_left_clicked = true,
            .mouse_left_down = true,
        };
        const ui: Ui = ctx.beginFrameRaw(click_top, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.vSlider("vol", .{ 20, 100 }, &v, .{ .min = 0, .max = 1 });
        h.close();
    }
    // After the click+drag, value should have moved upward toward 1.
    try expect(v > 0.9);
}

test " parseScalar accepts ints, floats, scientific notation; rejects garbage" {
    try expectEqual(@as(?f32, 3.14), parseScalar(f32, "3.14"));
    try expectEqual(@as(?f32, -2.5), parseScalar(f32, "-2.5"));
    try expectEqual(@as(?f32, 1.5e3), parseScalar(f32, "1.5e3"));
    try expectEqual(@as(?i32, 42), parseScalar(i32, "42"));
    try expectEqual(@as(?i32, -100), parseScalar(i32, "-100"));
    // Whitespace stripped.
    try expectEqual(@as(?i32, 7), parseScalar(i32, "  7  "));
    // Empty + garbage return null.
    try expectEqual(@as(?f32, null), parseScalar(f32, ""));
    try expectEqual(@as(?f32, null), parseScalar(f32, "abc"));
    try expectEqual(@as(?i32, null), parseScalar(i32, "1.5"));
}

