test " inputInt commits parsed value on Enter" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 300, 200 } };
    var v: i32 = 5;

    // Frame 1 - focus the input.
    var box: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.inputInt("count", &v, .{ .fmt = "{d}" });
        box = h.win.layout.last_item_rect;
        h.close();
    }
    // Frame 2 - click + start typing "42".
    {
        var inp: InputSnapshot = .{
            .mouse_pos = .{ box.x + box.width / 2, box.y + box.height / 2 },
            .mouse_left_clicked = true,
        };
        inp.chars_typed[0] = '4';
        inp.chars_typed[1] = '2';
        inp.chars_typed_count = 2;
        const ui: Ui = ctx.beginFrameRaw(inp, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.inputInt("count", &v, .{ .fmt = "{d}" });
        h.close();
        // Value still 5 - no commit yet.
        try expectEqual(@as(i32, 5), v);
    }
    // Frame 3 - Enter commits.
    {
        var inp: InputSnapshot = .{
            .mouse_pos = .{ box.x + box.width / 2, box.y + box.height / 2 },
        };
        inp.keys[@backingInt(KeyCode.enter)].pressed_this_frame = true;
        const ui: Ui = ctx.beginFrameRaw(inp, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        const changed: bool = ui.inputInt("count", &v, .{ .fmt = "{d}" });
        h.close();
        // The buffer was "5" + "42" = "542" because the seed-on-focus
        // path puts the existing value FIRST, then the typed chars
        // appended. Verify whatever the buffer parses to.
        try expect(changed);
        try expectEqual(@as(i32, 542), v);
        // Active focus dropped after commit.
        try expectEqual(@as(Id, 0), ctx.active_id);
    }
}

