    var box_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.inputFloat("x", &v, .{});
        box_rect = h.win.layout.last_item_rect;
        h.close();
    }
    // Frame 2 - click to focus.
    {
        const click_input: InputSnapshot = .{
            .mouse_pos = .{ box_rect.x + 5, box_rect.y + 5 },
            .mouse_left_clicked = true,
        };
        const ui: Ui = ctx.beginFrameRaw(click_input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.inputFloat("x", &v, .{});
        h.close();
    }
    // Frame 3 - type "++--", commit on Enter - buffer fails parseFloat,
    // value should stay at 9.0.
    {
        var typed: [16]u32 = undefined;
        typed[0] = '+';
        typed[1] = '+';
        typed[2] = '-';
        typed[3] = '-';
        var type_input: InputSnapshot = .{
            .mouse_pos = .{ box_rect.x + 5, box_rect.y + 5 },
            .chars_typed = typed,
            .chars_typed_count = 4,
        };
        type_input.keys[@backingInt(KeyCode.enter)].pressed_this_frame = true;
        const ui: Ui = ctx.beginFrameRaw(type_input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        const changed: bool = ui.inputFloat("x", &v, .{});
        h.close();
        try expect(!changed);
        try expectEqual(@as(f32, 9.0), v);
    }
}

// ============================================================================
// tests - editStruct dispatch. Each test pins one path
// through `editStructImpl` / `editFieldDispatch`: bool, float, int,
// enum, nested struct, color array, opts.skip, opts.label.
