test " editStruct compiles + runs over a flat struct" {
    const Settings = struct {
        enabled: bool = true,
        speed: f32 = 1.0,
        iterations: i32 = 100,
    };
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    var s: Settings = .{};
    // Pure render frame - no input changes - so editStruct must NOT
    // claim anything changed. Compiling at all proves the dispatch
    // covers bool/float/int.
    const changed: bool = ui.editStruct(&s);
    try expect(!changed);
    // Field values unchanged.
    try expect(s.enabled);
    try expectEqual(@as(f32, 1.0), s.speed);
    try expectEqual(@as(i32, 100), s.iterations);
}

