test "P1.3: BoundedString set/asSlice round-trip" {
    var bs: BoundedString(32) = .{};
    try expectEqual(@as(usize, 0), bs.len);
    try expectEqualStrings("", bs.asSlice());

    const n: usize = bs.set("Hello, world!");
    try expectEqual(@as(usize, 13), n);
    try expectEqual(@as(usize, 13), bs.len);
    try expectEqualStrings("Hello, world!", bs.asSlice());

    // Truncation when input exceeds capacity.
    var small: BoundedString(4) = .{};
    const truncated: usize = small.set("abcdefgh");
    try expectEqual(@as(usize, 4), truncated);
    try expectEqualStrings("abcd", small.asSlice());
}

