test "P1.3: dispatcher detects BoundedString before generic struct recursion" {
    // A BoundedString nested in a parent struct should NOT recurse
    // into a "buf" / "len" tree node - it should route to inputText
    // as a leaf widget. Inspectable by checking that editStruct
    // doesn't crash AND the len/buf weren't surfaced as separate
    // sub-tree widgets (the test for that is compile-time: the inline
    // for over fields would have picked them up if dispatched as a
    // generic struct, but the BoundedString check intercepts first).
    const Wrap = struct {
        name: BoundedString(8) = .{},
        other: i32 = 0,
    };
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    var w: Wrap = .{};
    _ = w.name.set("hi");
    _ = ui.editStruct(&w);
    // Name preserved through the dispatch path; capacity-aware len
    // didn't get overwritten by a recursive descent.
    try expectEqual(@as(usize, 2), w.name.len);
    try expectEqualStrings("hi", w.name.asSlice());
}

test "P2.1: debugLogPush appends events with frame + kind + message" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    ctx.frame_count = 42;

    try expectEqual(@as(usize, 0), ctx.debug_log.len);
    debugLogPush(&ctx, .popup_opened, "id={x} str='ctx'", .{0xdeadbeef});
    try expectEqual(@as(usize, 1), ctx.debug_log.len);

    const ev: *const DebugEvent = &ctx.debug_log.slice()[0];
    try expectEqual(@as(u32, 42), ev.frame);
    try expectEqual(DebugEventKind.popup_opened, ev.kind);
    try expectEqualStrings("id=deadbeef str='ctx'", ev.messageSlice());

    // debugLogSlice mirrors the populated prefix.
    const slice: []const DebugEvent = debugLogSlice(&ctx);
    try expectEqual(@as(usize, 1), slice.len);
    try expectEqualStrings("id=deadbeef str='ctx'", slice[0].messageSlice());
}

test "P2.1: debugLog ring drops oldest event when at cap" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Fill to cap. Use the index as the frame number so we can
    // verify which events landed.
    var i: u32 = 0;
    while (i < debug_log_cap) : (i += 1) {
        ctx.frame_count = i;
        debugLogPush(&ctx, .item_activated, "evt-{d}", .{i});
    }
    try expectEqual(debug_log_cap, ctx.debug_log.len);
    // First event should be evt-0, last should be evt-(CAP-1).
    const ring: []const DebugEvent = ctx.debug_log.constSlice();
    try expectEqualStrings("evt-0", ring[0].messageSlice());
    var expected_tail_buf: [32]u8 = undefined;
    const expected_tail: []const u8 = bufPrint(
        &expected_tail_buf,
        "evt-{d}",
        .{debug_log_cap - 1},
    ) catch panicf(@src(), "OOM", .{});
    try expectEqualStrings(
        expected_tail,
        ring[debug_log_cap - 1].messageSlice(),
    );

    // One more push: should drop evt-0 (orderedRemove(0)) and append
    // the new event at the tail.
    ctx.frame_count = 999;
    debugLogPush(&ctx, .item_activated, "overflow", .{});

    try expectEqual(debug_log_cap, ctx.debug_log.len); // still saturated
    const ring_after: []const DebugEvent = ctx.debug_log.constSlice();
    try expectEqualStrings("evt-1", ring_after[0].messageSlice());
    try expectEqualStrings("overflow", ring_after[debug_log_cap - 1].messageSlice());
    try expectEqual(@as(u32, 999), ring_after[debug_log_cap - 1].frame);
}

test "P2.1: debugLogPush truncates messages longer than the inline buffer" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Build a payload that exceeds debug_log_msg_max (128 bytes).
    const long_input: [200]u8 = @splat('x');
    debugLogPush(&ctx, .lint_warning, "{s}", .{long_input[0..]});

    try expectEqual(@as(usize, 1), ctx.debug_log.len);
    // bufPrint hit NoSpaceLeft → message_len recorded as MAX.
    const first: *const DebugEvent = &ctx.debug_log.slice()[0];
    try expectEqual(@as(u8, debug_log_msg_max), first.message_len);
    // The buffer carries the truncated prefix.
    for (first.messageSlice()) |b| {
        try expectEqual(@as(u8, 'x'), b);
    }
}

