test "P2.2: metricsCollectAtEndFrame populates frame/window/active fields" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Simulate a frame's worth of state without actually running
    // beginFrame/endFrame (which require a runtime GlState and a
    // Frame wrapper). metricsCollectAtEndFrame is a pure read of
    // ctx state into ctx.metrics.
    ctx.frame_count = 7;
    ctx.input.delta_time = 0.01666; // ≈ 60 fps
    ctx.hovered_window_id = 0xabcd;
    ctx.active_id = 0xfeedface;

    metricsCollectAtEndFrame(&ctx);

    try expectEqual(@as(u32, 7), ctx.metrics.frame_count);
    try expectApproxEqAbs(@as(f32, 16.66), ctx.metrics.frame_time_ms, 0.01);
    try expectEqual(@as(u32, 0), ctx.metrics.windows_active); // frame_windows.len == 0
    try expectEqual(@as(u32, 1), ctx.metrics.windows_hovered);
    try expectEqual(@as(Id, 0xfeedface), ctx.metrics.last_active_widget_id);
    // History ring advanced by one.
    try expectEqual(@as(u8, 1), ctx.metrics.history_head);
    try expectApproxEqAbs(
        @as(f32, 16.66),
        ctx.metrics.frame_time_ms_history[0],
        0.01,
    );
}

test "P2.2: history ring wraps after metrics_history_len samples" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Push LEN+1 samples; head should land at index 1, NOT
    // metrics_history_len (which would overflow u8 anyway).
    var i: u32 = 0;
    while (i < metrics_history_len + 1) : (i += 1) {
        ctx.frame_count = i;
        ctx.input.delta_time = float(i) * 0.001;
        metricsCollectAtEndFrame(&ctx);
    }
    // After LEN+1 writes, head is at 1. The sample at history[0]
    // is the LAST write (the LEN-th sample, i.e. frame LEN); the
    // sample at history[1] would be the FIRST write (frame 0) if
    // it had survived — but it was overwritten on the (LEN+1)th
    // write which lands at index LEN%LEN=0. Therefore:
    //   - history[0] should be the sample for frame LEN (delta = LEN ms)
    //   - history[1] should be the sample for frame 1 (delta = 1 ms)
    try expectEqual(@as(u8, 1), ctx.metrics.history_head);
    try expectApproxEqAbs(
        float(metrics_history_len),
        ctx.metrics.frame_time_ms_history[0],
        0.01,
    );
    try expectApproxEqAbs(
        @as(f32, 1),
        ctx.metrics.frame_time_ms_history[1],
        0.01,
    );
}

test "P2.2: cmd_count and drawlist_count accumulate via drawlist helpers" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Build two synthetic draw lists with different cmd counts.
    var dl_a: DrawList = .{};
    defer dl_a.deinit(std.testing.allocator);
    try dl_a.cmds.append(
        std.testing.allocator,
        .{ .rect_filled = .{ .rect = .{ .x = 0, .y = 0, .width = 1, .height = 1 }, .col = 0 } },
    );
    try dl_a.cmds.append(
        std.testing.allocator,
        .{ .rect_filled = .{ .rect = .{ .x = 1, .y = 1, .width = 1, .height = 1 }, .col = 0 } },
    );

    var dl_b: DrawList = .{};
    defer dl_b.deinit(std.testing.allocator);
    try dl_b.cmds.append(
        std.testing.allocator,
        .{ .rect_filled = .{ .rect = .{ .x = 2, .y = 2, .width = 1, .height = 1 }, .col = 0 } },
    );

    // Pretend the render loop just kicked off.
    metricsResetRenderCounters(&ctx);
    try expectEqual(@as(u32, 0), ctx.metrics.cmd_count);
    try expectEqual(@as(u32, 0), ctx.metrics.drawlist_count);

    // Accumulate both lists.
    metricsAccumulateDrawList(&ctx, &dl_a);
    metricsAccumulateDrawList(&ctx, &dl_b);

    try expectEqual(@as(u32, 3), ctx.metrics.cmd_count);
    try expectEqual(@as(u32, 2), ctx.metrics.drawlist_count);

    // A second reset zeros both counters again.
    metricsResetRenderCounters(&ctx);
    try expectEqual(@as(u32, 0), ctx.metrics.cmd_count);
    try expectEqual(@as(u32, 0), ctx.metrics.drawlist_count);
}

test "P2.2: last_active_widget_id sticks across frames with no active widget" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Frame 1: widget gets activated.
    ctx.active_id = 0xdeadbeef;
    metricsCollectAtEndFrame(&ctx);
    try expectEqual(@as(Id, 0xdeadbeef), ctx.metrics.last_active_widget_id);

    // Frame 2: nothing active, but last_active should persist
    // (the user might want to inspect "what was the last thing
    // I clicked").
    ctx.active_id = 0;
    metricsCollectAtEndFrame(&ctx);
    try expectEqual(@as(Id, 0xdeadbeef), ctx.metrics.last_active_widget_id);

    // Frame 3: new widget activated → replaces.
    ctx.active_id = 0x1234abcd;
    metricsCollectAtEndFrame(&ctx);
    try expectEqual(@as(Id, 0x1234abcd), ctx.metrics.last_active_widget_id);
}

// ============================================================================
// — tactical lint asserts
// ============================================================================
// These tests verify the lint sites are reachable without crashing
// and that the host call path runs to completion. The actual
// `std.log.warn` output isn't captured here (would need a custom
// log handler); the value is in pinning that the lint paths
// don't accidentally pull in any test-only types or panic.

test "#1: slider with min >= max doesn't crash (lint fires once)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    var v: f32 = 0.5;
    // Degenerate range (min == max). Lint should fire (writes to
    // stderr via std.log.warn) but the slider should still
    // early-return false because we're outside a window.
    const changed: bool = u.slider("test", &v, .{ .min = 1.0, .max = 1.0 });
    try expectEqual(false, changed);
    // Subsequent calls must continue to work (no state corruption).
    const changed2: bool = u.slider("test", &v, .{ .min = 0.0, .max = 1.0 });
    try expectEqual(false, changed2);
}

test "#2: drag with min > max doesn't crash (== is no-clamp sentinel)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    var v: f32 = 0.0;
    // min == max is the documented "disable clamping" sentinel —
    // this should NOT trigger the lint.
    const changed1: bool = u.drag("ok", &v, .{ .min = 0, .max = 0 });
    try expectEqual(false, changed1);
    // min > max is inverted — lint should fire.
    const changed2: bool = u.drag("bad", &v, .{ .min = 10, .max = 5 });
    try expectEqual(false, changed2);
}

test "#3: table column overflow lint reachable" {
    // 8 columns at min_w = 2*pad+8 ≈ 24px each = 192px minimum,
    // outer rect 100px wide → overflow. We build the TableState
    // directly because beginTable needs a live window.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    const cell_pad_x: f32 = 8;
    const min_w: f32 = 2 * cell_pad_x + 8; // 24px
    var ts: TableState = std.mem.zeroes(TableState);
    ts.id = 0xdeadbeef;
    ts.n_columns = 8;
    ts.columns_set_up = 8;
    ts.outer_rect = .{ .x = 0, .y = 0, .width = 100, .height = 200 };
    ts.opts = .{ .cell_padding_x = cell_pad_x, .cell_padding_y = 4 };
    var i: u32 = 0;
    while (i < 8) : (i += 1) {
        ts.columns[i] = .{};
    }
    computeTableColumnLayout(&ctx, &ts);
    // Every column floors at min_w, last col x + width > outer right.
    const final_right: f32 = ts.columns[7].x + ts.columns[7].width;
    try expect(final_right > ts.outer_rect.x + ts.outer_rect.width);
    // Each column got at least the minimum.
    for (ts.columns[0..8]) |c| {
        try expect(c.width >= min_w - 0.01);
    }
}

test "#4: double openPopup in same frame doesn't crash" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };
    ctx.frame_count = 5;
    // First call — primes the map.
    u.openPopup("ctx");
    // Second call same frame — lint should fire. Map entry should
    // STILL exist after; behavior is otherwise unchanged.
    u.openPopup("ctx");
    const parent_id: Id = 0; // no current_window
    const expected_id: Id = hashStr(parent_id, "ctx");
    try expect(ctx.popup_open.contains(expected_id));
    // DebugLog should record both opens.
    const events: []const DebugEvent = debugLogSlice(&ctx);
    try expectEqual(@as(usize, 2), events.len);
    try expectEqual(DebugEventKind.popup_opened, events[0].kind);
    try expectEqual(DebugEventKind.popup_opened, events[1].kind);
}

test "#5: warnOnce dedup mechanism (same call site fires once)" {
    // The `warnOnce` dedup flag isn't directly observable from a
    // test (it's a per-call-site anonymous-struct global), so what
    // we CAN verify is that calling the same site repeatedly doesn't
    // crash and behavior is otherwise stable. This is a smoke test
    // for the helper itself.
    var i: u32 = 0;
    while (i < 100) : (i += 1) {
        utils.warnOnce(@src(), "smoke-test iteration {d}", .{i});
    }
    // We reached here without panic. In a Debug build, std.log.warn
    // produced exactly ONE line on the first iteration; the other 99
    // were short-circuited by `dedup.fired = true`.
}

// ============================================================================
// P3 — Long-press → right-click synthesis
// ============================================================================
// Tests drive `applyLongPressSynthesis` directly with synthetic
// InputState + InputSnapshot pairs, bypassing the `beginFrame`
// plumbing (no Frame / GlState construction needed). Each test
// pins one contract.

test "P3: touch held past threshold fires synthetic right-click" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    var input_state: runtime.input.InputState = .{};
    // Touchdown at (100, 100). Mouse-left bridges to down via JS;
    // simulate that explicitly.
    runtime.input.pushTouchDown(&input_state, 42, 100, 100);
    runtime.input.pushMouseButtonDown(&input_state, 0);

    // Frame 1: 0ms elapsed. Touchdown observed; no synthesis yet.
    var snap1: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_left_down = true,
        .mouse_left_clicked = true,
        .delta_time = 0.0, // first frame
    };
    applyLongPressSynthesis(&ctx, &snap1, &input_state);
    try expectEqual(false, snap1.mouse_right_clicked);
    try expectEqual(true, snap1.mouse_left_down);
    try expectEqual(@as(i32, 42), ctx.long_press.touch_id);

    // Frame 2: simulate 600ms elapsed since touchdown — over threshold.
    // (Tracker initialised in frame 1, so accumulator is 0; bumping
    // delta_time accumulates from here.)
    var snap2: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_left_down = true,
        .delta_time = 0.6, // 600ms in seconds
    };
    applyLongPressSynthesis(&ctx, &snap2, &input_state);
    try expectEqual(true, snap2.mouse_right_clicked);
    try expectEqual(false, snap2.mouse_left_down);
    try expectEqual(true, ctx.long_press.just_fired_this_frame);
}

test "P3: drift > 6px cancels the long-press" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    var input_state: runtime.input.InputState = .{};
    runtime.input.pushTouchDown(&input_state, 7, 100, 100);
    runtime.input.pushMouseButtonDown(&input_state, 0);

    var snap1: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.0 };
    applyLongPressSynthesis(&ctx, &snap1, &input_state);

    // Frame 2: finger moved 20px down — far beyond drift threshold.
    runtime.input.pushTouchMove(&input_state, 7, 100, 120);
    var snap2: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.3 };
    applyLongPressSynthesis(&ctx, &snap2, &input_state);
    try expectEqual(false, snap2.mouse_right_clicked);

    // Frame 3: even after enough additional time, drift-cancel
    // sticks for the rest of the press.
    var snap3: InputSnapshot = .{
        .mouse_pos = .{ 100, 120 },
        .mouse_left_down = true,
        .delta_time = 0.5,
    };
    applyLongPressSynthesis(&ctx, &snap3, &input_state);
    try expectEqual(false, snap3.mouse_right_clicked);
}

test "P3: multi-touch (>1 finger) never synthesizes" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    var input_state: runtime.input.InputState = .{};
    // Two fingers down at once → pinch / pan gesture.
    runtime.input.pushTouchDown(&input_state, 1, 100, 100);
    runtime.input.pushTouchDown(&input_state, 2, 200, 100);
    runtime.input.pushMouseButtonDown(&input_state, 0);

    var snap1: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.0 };
    applyLongPressSynthesis(&ctx, &snap1, &input_state);
    try expectEqual(@as(i32, -1), ctx.long_press.touch_id);

    // Frame 2: even after long elapsed, no synthesis.
    var snap2: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.6 };
    applyLongPressSynthesis(&ctx, &snap2, &input_state);
    try expectEqual(false, snap2.mouse_right_clicked);
}

test "P3: desktop mouse hold doesn't trigger synthesis" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // No touches active — pure mouse press.
    var input_state: runtime.input.InputState = .{};
    runtime.input.pushMouseButtonDown(&input_state, 0);

    var snap1: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.6 };
    applyLongPressSynthesis(&ctx, &snap1, &input_state);
    try expectEqual(false, snap1.mouse_right_clicked);
    try expectEqual(true, snap1.mouse_left_down); // untouched
    try expectEqual(@as(i32, -1), ctx.long_press.touch_id);

    // Even after many ticks — no synthesis without a tracked touch.
    var snap2: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 1.0 };
    applyLongPressSynthesis(&ctx, &snap2, &input_state);
    try expectEqual(false, snap2.mouse_right_clicked);
}

test "P3: fired flag is one-shot — second frame doesn't re-fire" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    var input_state: runtime.input.InputState = .{};
    runtime.input.pushTouchDown(&input_state, 100, 50, 50);
    runtime.input.pushMouseButtonDown(&input_state, 0);

    // Tick 1: arm.
    var s1: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.0 };
    applyLongPressSynthesis(&ctx, &s1, &input_state);

    // Tick 2: cross threshold → fires.
    var s2: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.55 };
    applyLongPressSynthesis(&ctx, &s2, &input_state);
    try expectEqual(true, s2.mouse_right_clicked);
    try expectEqual(true, ctx.long_press.just_fired_this_frame);

    // Tick 3: still holding the same finger → no re-fire. The
    // `just_fired_this_frame` flag resets at the start of the call.
    var s3: InputSnapshot = .{
        .mouse_pos = .{ 50, 50 },
        // After fire, the caller might still set this true on the next
        // frame because the user hasn't lifted yet; tracker must
        // suppress re-fire regardless.
        .mouse_left_down = true,
        .delta_time = 0.02,
    };
    applyLongPressSynthesis(&ctx, &s3, &input_state);
    try expectEqual(false, s3.mouse_right_clicked);
    try expectEqual(false, ctx.long_press.just_fired_this_frame);
}

test "P3: touch lifted then re-pressed re-arms the tracker" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    var input_state: runtime.input.InputState = .{};
    // First press, drift-cancel.
    runtime.input.pushTouchDown(&input_state, 5, 100, 100);
    runtime.input.pushMouseButtonDown(&input_state, 0);

    var s1: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.0 };
    applyLongPressSynthesis(&ctx, &s1, &input_state);
    runtime.input.pushTouchMove(&input_state, 5, 200, 200); // drift
    var s2: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.1 };
    applyLongPressSynthesis(&ctx, &s2, &input_state);
    try expectEqual(@as(f32, -1), ctx.long_press.elapsed_ms);

    // Release the touch.
    runtime.input.pushTouchUp(&input_state, 5);
    runtime.input.pushMouseButtonUp(&input_state, 0);
    var s3: InputSnapshot = .{ .delta_time = 0.02 };
    applyLongPressSynthesis(&ctx, &s3, &input_state);
    try expectEqual(@as(i32, -1), ctx.long_press.touch_id);
    try expectEqual(@as(f32, 0), ctx.long_press.elapsed_ms); // re-armed

    // Fresh press with different id → fresh tracking.
    runtime.input.pushTouchDown(&input_state, 99, 50, 50);
    runtime.input.pushMouseButtonDown(&input_state, 0);
    var s4: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.0 };
    applyLongPressSynthesis(&ctx, &s4, &input_state);
    try expectEqual(@as(i32, 99), ctx.long_press.touch_id);

    var s5: InputSnapshot = .{ .mouse_left_down = true, .delta_time = 0.6 };
    applyLongPressSynthesis(&ctx, &s5, &input_state);
    try expectEqual(true, s5.mouse_right_clicked);
}

