    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("flagged", .{
        .flags = .{
            .no_title_bar = true,
            .no_resize = true,
            .no_move = true,
            .no_background = true,
            .no_scrollbar = true,
        },
    }) orelse unreachable;
    defer h.close();

    const w: *Window = ctx.current_window.?;
    try expect(w.flags.no_title_bar);
    try expect(w.flags.no_resize);
    try expect(w.flags.no_move);
    try expect(w.flags.no_background);
    try expect(w.flags.no_scrollbar);
    // Unset flag remains false.
    try expect(!w.flags.no_collapse);
}

test "P5.1: no_title_bar shifts content origin up by title_bar_height" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // First submission: WITHOUT no_title_bar (sanity check).
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("normal", .{
            .initial_pos = .{ 100, 100 },
            .initial_size = .{ 300, 200 },
        }) orelse unreachable;
        const w: *Window = ctx.current_window.?;
        // origin.y = pos.y + title_bar_height + padding.y
        const expected_y: f32 = 100 + ctx.style.title_bar_height + ctx.style.window_padding[1];
        try expectApproxEqAbs(expected_y, w.layout.origin[1], 0.01);
        h.close();
    }

    // Second submission: WITH no_title_bar — same window, flag flips.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("normal", .{
            .flags = .{ .no_title_bar = true },
        }) orelse unreachable;
        const w: *Window = ctx.current_window.?;
        // origin.y = pos.y + 0 + padding.y (title bar absent)
        const expected_y: f32 = 100 + 0 + ctx.style.window_padding[1];
        try expectApproxEqAbs(expected_y, w.layout.origin[1], 0.01);
        h.close();
    }
}

test "P5.1: no_background skips the window-bg drawRectFilled" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Plain window — count cmds in its draw list after chrome render.
    const ui1: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui1.window("a", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 150 },
        }) orelse unreachable;
        h.close();
    }
    const w1: *Window = ctx.windows.get(hashStr(0, "a")).?;
    const cmds_with_bg: usize = w1.draw_list.cmds.items.len;

    // Reset frame, same window now with no_background.
    const ui2: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui2.window("a", .{
            .flags = .{ .no_background = true },
        }) orelse unreachable;
        h.close();
    }
    const w2: *Window = ctx.windows.get(hashStr(0, "a")).?;
    const cmds_without_bg: usize = w2.draw_list.cmds.items.len;

    // The no_background submission has exactly ONE fewer cmd (the
    // suppressed window-bg drawRectFilled).
    try expectEqual(cmds_with_bg - 1, cmds_without_bg);
}

