    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1: flag set.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("toggle", .{
            .flags = .{ .no_resize = true },
        }) orelse unreachable;
        try expect(ctx.current_window.?.flags.no_resize);
        h.close();
    }

    // Frame 2: flag cleared on same window. Re-stamp logic must
    // pick up the new value rather than retaining the prior frame's.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("toggle", .{
            .flags = .{ .no_resize = false },
        }) orelse unreachable;
        try expect(!ctx.current_window.?.flags.no_resize);
        h.close();
    }
}

