test "P5.4: no_mouse_inputs lets hover fall through to deeper window" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame with mouse positioned at (150, 150) — inside both windows.
    // Submission order: "bottom" first, then "top" (overlay).
    // Without the flag, "top" would claim hover. With it, "bottom"
    // keeps the hover.
    const snap: InputSnapshot = .{ .mouse_pos = .{ 150, 150 } };
    const ui: Ui = ctx.beginFrameRaw(snap, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);

    {
        const h: WindowHandle = ui.window("bottom", .{
            .initial_pos = .{ 100, 100 },
            .initial_size = .{ 300, 200 },
        }) orelse unreachable;
        h.close();
    }
    // Sanity: "bottom" claimed hover on its own submission.
    const bottom_id: Id = hashStr(0, "bottom");
    try expectEqual(bottom_id, ctx.hovered_window_id);

    {
        const h: WindowHandle = ui.window("top", .{
            .initial_pos = .{ 100, 100 },
            .initial_size = .{ 300, 200 },
            .flags = .{ .no_mouse_inputs = true },
        }) orelse unreachable;
        h.close();
    }

    // "top" was submitted later (covers "bottom"), but the flag
    // suppressed its hover claim — "bottom" still owns the hover.
    try expectEqual(bottom_id, ctx.hovered_window_id);
}

