test "P5.5a: unsaved_document marker draws — same chrome cmd count, different title text" {
    // The marker is "{name} *" formatted into a stack buffer, then
    // drawn as ONE text cmd at the same position the plain title
    // would have used. Net effect: same number of chrome cmds as
    // a plain window (the title is still one cmd), but the text
    // payload differs. Test verifies cmd count parity AND that
    // the marker is observable in the formatted output by
    // re-running the format check at the call site.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Baseline.
    const ui1: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui1.window("untitled", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 150 },
        }) orelse unreachable;
        h.close();
    }
    const w1: *Window = ctx.windows.get(hashStr(0, "untitled")).?;
    const baseline_cmds: usize = w1.draw_list.cmds.items.len;

    // With unsaved_document.
    const ui2: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui2.window("untitled", .{
            .flags = .{ .unsaved_document = true },
        }) orelse unreachable;
        h.close();
    }
    const w2: *Window = ctx.windows.get(hashStr(0, "untitled")).?;
    const marker_cmds: usize = w2.draw_list.cmds.items.len;

    // Same number of chrome cmds — marker just changes the title's
    // string payload, not the cmd structure.
    try expectEqual(baseline_cmds, marker_cmds);

    // Sanity-check the format produces the expected " *" suffix.
    // (The actual title cmd is buried in the draw list; this is a
    // contract test on the format step itself.)
    var name_buf: [132]u8 = undefined;
    const formatted: []const u8 = try bufPrint(&name_buf, "{s} *", .{w2.name()});
    try expectEqualStrings("untitled *", formatted);
}

