test "P5.5b: scroll_max_x > 0 when flag set + content overflows" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Pre-mark the window's cursor_max.x past the right edge to
    // simulate a wide widget. Cleaner than relying on font metrics
    // (which can vary by 1-2px between platforms).
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui.window("hscroll", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 100 },
            .flags = .{ .horizontal_scrollbar = true },
        }) orelse unreachable;
        // Push cursor_max far to the right so content_w_natural is
        // clearly > viewport_w.
        const w_mid: *Window = ctx.current_window.?;
        w_mid.layout.cursor_max[0] = w_mid.pos[0] + 500; // 500px content
        h.close();
    }
    const w: *Window = ctx.windows.get(hashStr(0, "hscroll")).?;
    try expect(w.scroll_max_x > 0);
}

test "P5.5b: wheel-X scrolls window with flag set, ignored without" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
