    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui.window("s", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 100 },
            .flags = .{ .horizontal_scrollbar = true },
        }) orelse unreachable;
        // Force scroll_max_x = 300 by mutating directly (closeWindow
        // hasn't run yet so cursor_max would otherwise be tiny).
        ctx.current_window.?.scroll_max_x = 300;

        // Normal set in range.
        ui.setScrollX(150);
        try expectEqual(@as(f32, 150), ui.getScrollX());

        // Over-range clamps to scroll_max_x.
        ui.setScrollX(99999);
        try expectEqual(@as(f32, 300), ui.getScrollX());

        // Negative clamps to 0.
        ui.setScrollX(-50);
        try expectEqual(@as(f32, 0), ui.getScrollX());

        // getScrollMaxX returns the stored max.
        try expectEqual(@as(f32, 300), ui.getScrollMaxX());
        h.close();
    }
}

test "P5.5b: X + Y wheel consumption are independent" {
    var ctx: UiContext = .{
