        const w_mid: *Window = ctx.current_window.?;
        w_mid.layout.cursor_max[0] = w_mid.pos[0] + 500;
        w_mid.layout.cursor_max[1] = w_mid.pos[1] + 500;
        h.close();
    }
    try expect(ctx.mouse_wheel_consumed); // Y consumed
    try expect(ctx.mouse_wheel_x_consumed); // X also consumed
}

// ============================================================================
// P8.5 — shift-wheel pan + scroll_x persistence
// ============================================================================

test "P8.5: shift+wheel-y routes to scroll_x when horizontal_scrollbar set" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    var snap: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_wheel_y = -2.0,
    };
    snap.keys[@backingInt(KeyCode.left_shift)] = .{
        .down = true,
        .pressed_this_frame = true,
        .released_this_frame = false,
        .down_duration_frames = 1,
    };

    const ui: Ui = ctx.beginFrameRaw(snap, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui.window("pan", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 100 },
            .flags = .{ .horizontal_scrollbar = true },
        }) orelse unreachable;
        ctx.current_window.?.layout.cursor_max[0] = ctx.current_window.?.pos[0] + 500;
        h.close();
    }
    const w: *Window = ctx.windows.get(hashStr(0, "pan")).?;
    // wheel_y = -2.0 + shift held → scroll_x advances right
    // (mirrors the wheel-y → scroll-y sign convention: scroll_x -=
    // wheel_y * speed).  scroll_x = 0 initially, so a negative
    // wheel_y produces a positive scroll_x.
    try expect(w.scroll_x > 0);
    // scroll_y must NOT advance — shift-pan consumed the wheel
    // before the normal Y-wheel handler could fire.
    try expectEqual(@as(f32, 0), w.scroll_y);
    // Both consumption flags get set so neither outer scope
    // double-applies.
    try expect(ctx.mouse_wheel_x_consumed);
    try expect(ctx.mouse_wheel_consumed);
}

test "P8.5: shift+wheel-y falls through to scroll_y when no h-scrollbar" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Shift held but the window has NO horizontal_scrollbar.  Shift
    // pan must not fire (no dead key); wheel-y goes to scroll_y.
    var snap: InputSnapshot = .{
        .mouse_pos = .{ 100, 100 },
        .mouse_wheel_y = -2.0,
    };
    snap.keys[@backingInt(KeyCode.left_shift)] = .{
        .down = true,
        .pressed_this_frame = true,
        .released_this_frame = false,
        .down_duration_frames = 1,
    };

    const ui: Ui = ctx.beginFrameRaw(snap, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    {
        const h: WindowHandle = ui.window("noh", .{
            .initial_pos = .{ 50, 50 },
            .initial_size = .{ 200, 100 },
            // no horizontal_scrollbar flag
        }) orelse unreachable;
        ctx.current_window.?.layout.cursor_max[1] = ctx.current_window.?.pos[1] + 500;
        h.close();
    }
    const w: *Window = ctx.windows.get(hashStr(0, "noh")).?;
    // scroll_y advanced because shift-pan didn't fire (mirrors the
    // normal wheel-y → scroll-y sign convention).
    try expect(w.scroll_y > 0);
    try expectEqual(@as(f32, 0), w.scroll_x);
}

