test "P8.5: PersistedWindow round-trips scroll_x value" {
    const gpa: Allocator = std.testing.allocator;

    // Build a PersistedWindow with scroll_x set, serialize to .zon
    // bytes via the schema's struct, then re-parse and confirm
    // the round-trip preserves scroll_x.
    const original: PersistedWindow = .{
        .name = "saved",
        .pos = .{ 100, 100 },
        .size = .{ 400, 300 },
        .scroll_y = 50,
        .scroll_x = 75,
        .user_resized = true,
        .tab_bars = &.{},
    };

    var alloc_writer: std.Io.Writer.Allocating = .init(gpa);
    defer alloc_writer.deinit();
    try std.zon.stringify.serialize(original, .{}, &alloc_writer.writer);
    const text: []const u8 = alloc_writer.written();

    const text_z: [:0]u8 = try dupeZ(gpa, text);
    defer gpa.free(text_z);
    const parsed: PersistedWindow = try std.zon.parse.fromSliceAlloc(
        PersistedWindow,
        gpa,
        text_z,
        null,
        .{},
    );
    defer std.zon.parse.free(gpa, parsed);

    try expectEqual(@as(f32, 75), parsed.scroll_x);
    try expectEqual(@as(f32, 50), parsed.scroll_y);
}

test "P8.5: legacy PersistedWindow without scroll_x parses with default 0" {
    const gpa: Allocator = std.testing.allocator;

    // Older .zon files written before scroll_x was added.  They
    // contain every other field but no scroll_x.  Parsing must
    // succeed and default scroll_x to 0.
    const legacy_zon: [:0]const u8 =
        \\.{
        \\    .name = "old",
        \\    .pos = .{ 10, 20 },
        \\    .size = .{ 200, 100 },
        \\    .scroll_y = 33,
        \\    .user_resized = true,
        \\    .tab_bars = .{},
        \\}
    ;

    const parsed: PersistedWindow = try std.zon.parse.fromSliceAlloc(
        PersistedWindow,
        gpa,
        legacy_zon,
        null,
        .{},
    );
    defer std.zon.parse.free(gpa, parsed);

    try expectEqual(@as(f32, 0), parsed.scroll_x);
    try expectEqual(@as(f32, 33), parsed.scroll_y);
}

test "P8.5: openWindow restores scroll_x from PersistedWindow on first frame" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
