    const font_dummy: text2d.FontCache = .{};

    // Stash a pending entry with scroll_x = 42 before any window
    // submission.  openWindow must consume the entry and copy
    // scroll_x onto the new Window.
    const name_copy: []u8 = try ctx.gpa.dupe(u8, "restored");
    try ctx.pending_persistence.put(ctx.gpa, name_copy, .{
        .name = name_copy,
        .pos = .{ 30, 40 },
        .size = .{ 300, 200 },
        .scroll_y = 0,
        .scroll_x = 42,
        .user_resized = true,
        .tab_bars = &.{},
    });

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("restored", .{
        .flags = .{ .horizontal_scrollbar = true },
    }) orelse unreachable;
    defer h.close();

    const w: *Window = ctx.current_window.?;
    try expectEqual(@as(f32, 42), w.scroll_x);
}

test "P8.5: scroll_x shifts cursor_pos[0] left so content draws at offset" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Restore a window with scroll_x = 30 already set.  After
    // openWindow runs, the first widget's effective draw X should
    // be inner_origin[0] - 30, NOT inner_origin[0].  Without the
    // shift, scroll_x is bookkeeping-only and the user-visible
    // content never moves when they drag the X scrollbar.
    const name_copy: []u8 = try ctx.gpa.dupe(u8, "shifty");
    try ctx.pending_persistence.put(ctx.gpa, name_copy, .{
        .name = name_copy,
        .pos = .{ 50, 50 },
        .size = .{ 300, 200 },
        .scroll_y = 0,
        .scroll_x = 30,
        .user_resized = true,
        .tab_bars = &.{},
    });

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("shifty", .{
        .flags = .{ .horizontal_scrollbar = true, .no_title_bar = true },
    }) orelse unreachable;
    defer h.close();

    const w: *Window = ctx.current_window.?;
    // Inner origin is `pos + window_padding` because no_title_bar
    // skips the title-bar height.  Cursor should be at
    // (inner_origin_x - scroll_x).
    const inner_origin_x: f32 = w.pos[0] + ctx.style.window_padding[0];
    try expectEqual(inner_origin_x - 30, w.layout.cursor_pos[0]);
}

test "P8.5: cursor_pos[0] stays shifted by scroll_x after newLine (every row)" {
    // The "only first widget shifts" bug: openWindow shifted the
    // cursor once, but advanceLayout reset cursor_pos[0] to
    // `origin[0] + indent_x` on every new line, dropping the
    // shift.  Mimics imgui's `window.Pos.x - window.Scroll.x +
    // local_x` formula: every line-reset includes the scroll
    // subtraction.
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    const name_copy: []u8 = try ctx.gpa.dupe(u8, "scrolled");
    try ctx.pending_persistence.put(ctx.gpa, name_copy, .{
        .name = name_copy,
        .pos = .{ 100, 100 },
        .size = .{ 400, 300 },
        .scroll_y = 0,
        .scroll_x = 25,
        .user_resized = true,
        .tab_bars = &.{},
    });

    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("scrolled", .{
        .flags = .{ .horizontal_scrollbar = true, .no_title_bar = true },
    }) orelse unreachable;

    const w: *Window = ctx.current_window.?;
    const inner_origin_x: f32 = w.pos[0] + ctx.style.window_padding[0];
    const expected_x: f32 = inner_origin_x - 25;

    // Submit a couple of "rows" to force newLine/advanceLayout
    // to fire.  After each one, cursor_pos[0] must be back at
    // the scroll-aware origin, not the unshifted origin.
    ui.newLine();
    try expectEqual(expected_x, w.layout.cursor_pos[0]);

    ui.newLine();
    try expectEqual(expected_x, w.layout.cursor_pos[0]);

    ui.newLine();
    try expectEqual(expected_x, w.layout.cursor_pos[0]);

    h.close();
}

