    const font_dummy: text2d.FontCache = .{};
    const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
    defer h.close();
    var list: ArrayList(i32) = .empty;
    defer list.deinit(std.testing.allocator);
    // No clicks → no changes; returns false.
    try expect(!ui.editArrayList("nums", &list));
    try expectEqual(@as(usize, 0), list.items.len);
}

test " editArrayList renders one row per existing element" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    var list: ArrayList(i32) = .empty;
    defer list.deinit(std.testing.allocator);
    try list.append(std.testing.allocator, 10);
    try list.append(std.testing.allocator, 20);
    try list.append(std.testing.allocator, 30);

    // Frame 1 - open the tree node by clicking it. The tree node
    // sits at the cursor position on first widget submission;
    // measure it via last_item_rect AFTER a no-op frame.
    var tree_rect: Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    {
        const wopts: WindowOpts = .{ .initial_pos = .{ 0, 0 }, .initial_size = .{ 400, 400 } };
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", wopts) orelse unreachable;
        _ = ui.editArrayList("nums", &list);
        // After editArrayList returns, last_item_rect is the LAST
        // widget drawn - the "x" Remove button on the last element.
        // Just verify that some rect was recorded (non-zero size).
        tree_rect = h.win.layout.last_item_rect;
        h.close();
    }
    // Without opening the tree node, last_item_rect refers to the
    // collapsed tree-node row itself.
    try expect(tree_rect.width > 0);
    try expect(tree_rect.height > 0);
    // List still has 3 elements (we didn't click Add or Remove).
    try expectEqual(@as(usize, 3), list.items.len);
}

