    // No input changes anything; just verify the comptime walk
    // succeeds for every Style field. If a new field is added with
    // an unsupported type, the walk renders a "<unsupported …>"
    // text line but doesn't crash.
    const changed: bool = ui.styleEditor();
    try expect(!changed);
}

test " serializeLayout + applyLayout round-trip preserves geometry" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Create + touch two windows so they live in ctx.windows.
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h_a: WindowHandle = ui.window(
            "settings",
            .{ .initial_pos = .{ 50, 60 }, .initial_size = .{ 320, 240 } },
        ) orelse unreachable;
        h_a.close();
        const h_b: WindowHandle = ui.window(
            "inspector",
            .{ .initial_pos = .{ 400, 80 }, .initial_size = .{ 280, 320 } },
        ) orelse unreachable;
        h_b.close();
    }

    // Manually mutate one window's pos + scroll + user_resized so
    // we can verify the round-trip preserves non-default values.
    const settings_id: Id = hashStr(0, "settings");
    const inspector_id: Id = hashStr(0, "inspector");
    const settings_w: *Window = ctx.windows.get(settings_id) orelse unreachable;
    settings_w.pos = .{ 123, 456 };
    settings_w.size = .{ 333, 222 };
    settings_w.scroll_y = 99;
    settings_w.user_resized = true;

    // Serialize.
    const buf: []u8 = try serializeLayoutImpl(&ctx, std.testing.allocator);
    defer std.testing.allocator.free(buf);

    // Reset both windows to default-ish values so we can detect
    // that applyLayout actually wrote to them.
    settings_w.pos = .{ 0, 0 };
    settings_w.size = .{ 0, 0 };
    settings_w.scroll_y = 0;
    settings_w.user_resized = false;
    const inspector_w_pre: *Window = ctx.windows.get(inspector_id) orelse unreachable;
    inspector_w_pre.pos = .{ 0, 0 };
    inspector_w_pre.size = .{ 0, 0 };

    // Apply - both windows should restore.
    try applyLayoutImpl(&ctx, buf);

    const settings_w_post: *Window = ctx.windows.get(settings_id) orelse unreachable;
    try expectEqual(@as(f32, 123), settings_w_post.pos[0]);
    try expectEqual(@as(f32, 456), settings_w_post.pos[1]);
    try expectEqual(@as(f32, 333), settings_w_post.size[0]);
    try expectEqual(@as(f32, 222), settings_w_post.size[1]);
    try expectEqual(@as(f32, 99), settings_w_post.scroll_y);
    try expectEqual(true, settings_w_post.user_resized);

    // Inspector also restored to its post-creation geometry (50,80,280,320 etc.).
    const inspector_w_post: *Window = ctx.windows.get(inspector_id) orelse unreachable;
    try expect(inspector_w_post.size[0] > 0); // restored, not zero
}

