test " applyLayout creates stub windows for titles not yet known" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();

    // Hand-rolled ZON describing one window - exercises the
    // human-readable contract end-to-end. No window is in
    // ctx.windows yet; applyLayout should create a stub keyed by
    // hashStr(0, "settings") whose geometry matches the ZON.
    var src_buf: [256]u8 = undefined;
    const src: []const u8 = bufPrint(&src_buf,
        \\.{{
        \\    .version = {d},
        \\    .windows = .{{
        \\        .{{
        \\            .title = "settings",
        \\            .pos = .{{ 100, 200 }},
        \\            .size = .{{ 300, 400 }},
        \\            .scroll_y = 10,
        \\            .user_resized = true,
        \\        }},
        \\    }},
        \\}}
    , .{layout_schema_version}) catch panicf(@src(), "OOM", .{});

    try expectEqual(@as(usize, 0), ctx.windows.count());
    try applyLayoutImpl(&ctx, src);
    try expectEqual(@as(usize, 1), ctx.windows.count());

    const id: Id = hashStr(0, "settings");
    const stub: *Window = ctx.windows.get(id) orelse unreachable;
    try expectEqual(@as(f32, 100), stub.pos[0]);
    try expectEqual(@as(f32, 200), stub.pos[1]);
    try expectEqual(@as(f32, 300), stub.size[0]);
    try expectEqual(@as(f32, 400), stub.size[1]);
    try expectEqual(@as(f32, 10), stub.scroll_y);
    try expectEqual(true, stub.user_resized);
    // Title was copied into name_buf so a follow-up serialize round-trips.
    try expectEqualStrings("settings", stub.name());
}

