// ============================================================================
// tests - keyboard nav (Tab focus + Enter activate) + showDemoWindow.
// Each test pins one architectural contract: Tab advances nav_id
// through the previous frame's submitted items, Shift+Tab steps
// backward, Enter on the focused widget synthesizes a click,
// showDemoWindow walks every category without panic.
// ============================================================================

test " Tab advances nav_id through submitted items in submission order" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
    };
    defer ctx.deinit();
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1 - submit two buttons, no Tab pressed. Both register
    // as navigable; nav_id stays at 0 (unfocused).
    {
        const ui: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.button("A", .{});
        _ = ui.button("B", .{});
    }
    try expectEqual(@as(Id, 0), ctx.nav_id);
    try expect(ctx.frame_nav_items.len >= 2);
    const first_id: Id = ctx.frame_nav_items.items[0];
    const second_id: Id = ctx.frame_nav_items.items[1];

    // Frame 2 - Tab pressed. advanceNav runs; nav_id was 0 (not in
    // list) so it focuses the FIRST item.
    {
        const ui: Ui = ctx.beginFrameRaw(keyEventSnapshot(.tab), null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.button("A", .{});
        _ = ui.button("B", .{});
    }
    try expectEqual(first_id, ctx.nav_id);

    // Frame 3 - Tab pressed again. Advances to the SECOND item.
    {
        const ui: Ui = ctx.beginFrameRaw(keyEventSnapshot(.tab), null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = ui.window("host", .{}) orelse unreachable;
        defer h.close();
        _ = ui.button("A", .{});
        _ = ui.button("B", .{});
    }
    try expectEqual(second_id, ctx.nav_id);
}

test " Tab wraps from last item back to first" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
