        _ = ui.button("B", .{});
        _ = ui.button("C", .{});
    }
    try expectEqual(first_id, ctx.nav_id);
}

test " Enter on focused button synthesizes a click" {
    var ctx: UiContext = .{
        .gpa = std.testing.allocator,
        .frame_arena = FrameArena.init(std.testing.allocator, ui_frame_arena_ceiling, "ui"),
        .canvas_w = 800,
        .canvas_h = 600,
