// ============================================================================
// Text measurement + drawing - Style-driven (Tier B).
// ============================================================================
// When `style.font == null` we route through the default bitmap path
// (text2d.draw + measure) - same path as Phases 1-4. When
// `style.font` is set, we route through `drawTextEx` / `measureTextEx`
// for proper TTF rendering with per-pixel size and `font_spacing`.
// The legacy hardcoded `FONT_SIZE = 10` / `ctx.style.font_size = 10`
// constants are gone - line height is now `style.font_size` (which
// defaults to 10 to keep existing visual layout unchanged).

// All widget code routes text through `measureTextS` / `drawTextAtS`
// above (which read Style.font / font_size). Legacy line-height
// constant kept for layouts that still use it as a magic number
// gradually transitioning to `style.font_size` everywhere.

// ============================================================================
// Rendering - rlgl immediate-mode triangle emission.
// ============================================================================
// Adapted from rlImGui's ImGuiRenderTriangles + EnableScissor path.
// The difference: rlImGui consumes a pre-built ImDrawList; we render
// each widget's geometry eagerly as the widget runs. No per-frame
// draw-list bookkeeping, no z-ordering - keeps it simple.

// ============================================================================
// Layout / cursor tests
// ============================================================================

test "advanceLayout: solo widget sets cursor_max" {
    var w = Window{
        .id = 1,
        .pos = .{ 100, 100 },
        .size = .{ 200, 200 },
        .layout = .{
            .origin = .{ 100, 100 },
            .cursor_pos = .{ 100, 100 },
            .cursor_max = .{ 100, 100 },
        },
    };
    advanceLayout(&w, .{ 50, 20 }, .{ 8, 4 }, 8);
    try expectEqual(@as(f32, 150), w.layout.cursor_max[0]);
    try expectEqual(@as(f32, 120), w.layout.cursor_max[1]);
    // Next-row cursor should be below the placed widget.
    try expect(w.layout.cursor_pos[1] > 100);
}

test "advanceLayout: records cursor_pos_prev_line for sameLine" {
    // After a widget advances, the layout scope must remember the
    // row's right edge + top so the next sameLine can rejoin it.
    // This is the structural fix for the turn-308 sameLine bug.
    var w = Window{
        .id = 1,
        .pos = .{ 0, 0 },
        .size = .{ 400, 400 },
        .layout = .{
            .origin = .{ 8, 8 },
            .cursor_pos = .{ 8, 8 },
            .cursor_max = .{ 8, 8 },
        },
    };
    advanceLayout(&w, .{ 50, 20 }, .{ 4, 4 }, 8);
    // Right edge of placed widget = 8 + 50 = 58.
    try expectEqual(@as(f32, 58), w.layout.cursor_pos_prev_line[0]);
    // Top of row = where the widget was placed.
    try expectEqual(@as(f32, 8), w.layout.cursor_pos_prev_line[1]);
    // Row's tallest widget tracked.
    try expectEqual(@as(f32, 20), w.layout.prev_line_height);
}

// ============================================================================
// widget tests - pure functions (math + format) for now,
// since end-to-end widget invocation requires a UiContext + GL.
// ============================================================================

test "scalarToF64 / scalarFromF64: float roundtrip" {
    try expectApproxEqAbs(@as(f64, 0.5), scalarToF64(f32, 0.5), 1e-6);
    try expectApproxEqAbs(@as(f32, 0.25), scalarFromF64(f32, 0.25), 1e-6);
}

test "scalarToF64 / scalarFromF64: int rounds correctly" {
    try expectEqual(@as(f64, 42), scalarToF64(i32, 42));
    try expectEqual(@as(i32, 42), scalarFromF64(i32, 42.4));
    try expectEqual(@as(i32, 43), scalarFromF64(i32, 42.6));
    // Negative
    try expectEqual(@as(i32, -3), scalarFromF64(i32, -3.4));
}

test "scalarFromF64: extreme int range" {
    try expectEqual(@as(u8, 255), scalarFromF64(u8, 255.0));
    try expectEqual(@as(u8, 0), scalarFromF64(u8, 0.0));
    try expectEqual(@as(i64, 1_000_000), scalarFromF64(i64, 1_000_000.0));
}

test "colorToU32: wire format matches ImDrawVert.col layout" {
    // 0xAABBGGRR (little-endian) - same as ImGui's IM_COL32_*.
    const c = Color{ .r = 0x11, .g = 0x22, .b = 0x33, .a = 0x44 };
    const packed_v: ColorU32 = Color.toWire(c);
    try expectEqual(@as(u32, 0x44332211), packed_v);
}

test "formatScalar: float and int use type-appropriate defaults" {
    var buf: [32]u8 = undefined;
    // Float → 3 decimal places.
    const f_str = formatScalar(&buf, f32, 1.5, "");
    try expectEqualStrings("1.500", f_str);

    // Int → no decimals.
    const i_str = formatScalar(&buf, i32, -42, "");
    try expectEqualStrings("-42", i_str);
}

test "TooltipData: text() returns valid slice into buffer" {
    var t = TooltipData{ .pos = .{ 0, 0 } };
    const msg: []const u8 = "hello";
    @memcpy(t.text_buf[0..msg.len], msg);
    t.text_len = msg.len;
    try expectEqualStrings("hello", t.text());
}

// ============================================================================
// widget tests - pure functions / state-machine sanity.
// ============================================================================

test "drag clamping: in-range value untouched" {
    // Simulate a drag whose computed new value is inside [min, max].
    // Just exercising zm.clamp directly to lock in semantics
    // (the real drag loop tests would need a UiContext + GL stub).
    const new_f: f64 = 0.7;
    try expectEqual(@as(f64, 0.7), clamp(new_f, 0.0, 1.0));
}

test "drag clamping: out-of-range hits min/max" {
    try expectEqual(@as(f64, 1.0), clamp(@as(f64, 1.5), 0.0, 1.0));
    try expectEqual(@as(f64, 0.0), clamp(@as(f64, -0.3), 0.0, 1.0));
}

test "radioButton ID disambiguation: same label, different value → different IDs" {
    // A single radio group has multiple buttons sharing a label slot
    // (visible labels differ, but the ID derivation must include the
    // value so each button has its own active-id state).
    const win_id: Id = 0xDEADBEEF;
    const label_hash: Id = hashStr(win_id, "Option");
    const id_0: Id = hashInt(label_hash, 0);
    const id_1: Id = hashInt(label_hash, 1);
    const id_2: Id = hashInt(label_hash, 2);
    try expect(id_0 != id_1);
    try expect(id_1 != id_2);
    try expect(id_0 != id_2);
}

// ============================================================================
// Phase A2 clipper unit tests
// ============================================================================

/// Build a minimal UiContext + Window for clipper unit tests.
/// The window's `cursor_pos` is set so we know the clipper's
/// computed origin_y; viewport is the window's interior minus
/// title bar and padding. Caller must `deinit` the context.
/// also seeds `layout.origin` and `layout.work_rect_max`
/// because the clipper now reads its viewport bounds from these
/// (not from `w.pos + style padding`). Mirrors what `openWindow`
/// would have done - content area = window rect minus title bar
/// + window_padding. Using zimr's default style values (title 22,
/// padding 8) so the math matches a real workspace.
fn testMakeUiCtxWithWindow(
    gpa: Allocator,
    win_y: f32,
    win_h: f32,
    cursor_y: f32,
) !*UiContext {
    const ctx = try gpa.create(UiContext);
    ctx.* = UiContext.init(gpa);

    const title_bar: f32 = ctx.style.title_bar_height;
    const pad_y: f32 = ctx.style.window_padding[1];
    const inner_top: f32 = win_y + title_bar + pad_y;
    const inner_bot: f32 = win_y + win_h - pad_y;
    const pad_x: f32 = ctx.style.window_padding[0];

    const w = try gpa.create(Window);
    w.* = .{
        .id = 0xC11FA,
        .pos = .{ 0, win_y },
        .size = .{ 800, win_h },
        .layout = .{
            .origin = .{ pad_x, inner_top },
            .work_rect_max = .{ 800 - pad_x, inner_bot },
            .cursor_pos = .{ 0, cursor_y },
            .cursor_max = .{ 0, cursor_y },
        },
    };
    ctx.current_window = w;
    return ctx;
}

fn testDestroyUiCtxWithWindow(gpa: Allocator, ctx: *UiContext) void {
    if (ctx.current_window) |w| {
        gpa.destroy(w);
    }
    ctx.deinit();
    gpa.destroy(ctx);
}

test "Clipper.init: empty list completes immediately" {
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    var clip = Clipper.init(ctx, 0, 20);
    try expectEqual(Clipper.State.done, clip.state);
    try expectEqual(@as(?Clipper.Range, null), clip.step());
}

test "Clipper: visible range covers cursor-aligned rows" {
    // Window y=0, height=400, title_bar=20 + padding=8 → viewport
    // top = 28, bottom = 392. Cursor starts at 60 (so origin_y =
    // 60). Item height 20. Rows 0..N at y=60, 80, 100,...
    // First visible row: rows that intersect [28, 392]. Since
    // origin_y > vtop, first visible is row 0 (then overscan-1
    // clamps to 0 too). Visible rows = ceil((392-28)/20) + 1 + 1 + 1
    // = ceil(18.2) + 3 = 22.
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    var clip = Clipper.init(ctx, 1000, 20);
    const r1: Clipper.Range = clip.step() orelse return error.UnexpectedNullStep;
    try expect(r1.start == 0);
    try expect(r1.end > 0);
    try expect(r1.end < 1000); // virtualized, not all rows
    // Second step finalizes.
    try expectEqual(@as(?Clipper.Range, null), clip.step());
    // Third step is safe.
    try expectEqual(@as(?Clipper.Range, null), clip.step());
}

test "Clipper: cursor advances past full content height after step()" {
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    const item_count: usize = 100;
    const item_h: f32 = 20;
    var clip = Clipper.init(ctx, item_count, item_h);

    const r: Clipper.Range = clip.step() orelse return error.UnexpectedNullStep;
    // After the first step, cursor advanced to the first visible
    // row's y. Simulate the caller submitting `r.start..r.end` rows.
    const w: *Window = ctx.current_window.?;
    const rows_submitted: f32 = float(r.end - r.start);
    w.layout.cursor_pos[1] += rows_submitted * item_h;

    // End the clipper - cursor should land at origin + total*height.
    _ = clip.step();
    const expected_final_y: f32 = 60 + float(item_count) * item_h;
    try expectApproxEqAbs(expected_final_y, w.layout.cursor_pos[1], 0.5);
}

test "Clipper.end: completes iteration safely" {
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    var clip = Clipper.init(ctx, 1000, 20);
    clip.end();
    try expectEqual(Clipper.State.done, clip.state);
    // Idempotent - calling again is safe.
    clip.end();
    try expectEqual(Clipper.State.done, clip.state);
}

test "Clipper: tiny item count where every row visible" {
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    var clip = Clipper.init(ctx, 3, 20);
    const r: Clipper.Range = clip.step() orelse return error.UnexpectedNullStep;
    try expectEqual(@as(usize, 0), r.start);
    try expectEqual(@as(usize, 3), r.end); // capped at item_count
}

test "Clipper: zero or negative item_height clamped to 1" {
    const gpa: Allocator = std.testing.allocator;
    const ctx: *UiContext = try testMakeUiCtxWithWindow(gpa, 0, 400, 60);
    defer testDestroyUiCtxWithWindow(gpa, ctx);

    const clip = Clipper.init(ctx, 100, 0);
    try expectEqual(@as(f32, 1), clip.item_height);

    const clip2 = Clipper.init(ctx, 100, -5);
    try expectEqual(@as(f32, 1), clip2.item_height);
}

// ============================================================================
// Phase A3 multiline cursor helpers - unit tests
// ============================================================================
// These three helpers are pure (no UiContext mutation), so they
// test cleanly without the synthetic-Window fixture used by the
// clipper tests. `xyToByte` does take a UiContext for its text-
// measure call; we only test it indirectly via the line-walking
// part of `lineColToByte` here.

test "byteToLineCol: first line" {
    const buf: []const u8 = "hello\nworld\n!";
    const lc: LineCol = byteToLineCol(buf, 3);
    try expectEqual(@as(usize, 0), lc.line);
    try expectEqual(@as(usize, 3), lc.col);
}

test "byteToLineCol: at newline boundary" {
    const buf: []const u8 = "hello\nworld\n!";
    // Position 5 is the '\n' itself; still on line 0.
    const at_nl: LineCol = byteToLineCol(buf, 5);
    try expectEqual(@as(usize, 0), at_nl.line);
    try expectEqual(@as(usize, 5), at_nl.col);
    // Position 6 is the 'w' on line 1, col 0.
    const after_nl: LineCol = byteToLineCol(buf, 6);
    try expectEqual(@as(usize, 1), after_nl.line);
    try expectEqual(@as(usize, 0), after_nl.col);
}

test "byteToLineCol: middle line" {
    const buf: []const u8 = "hello\nworld\n!";
    // Position 9 is 'r' on line 1 (line starts at 6, col = 9 - 6 = 3).
    const lc: LineCol = byteToLineCol(buf, 9);
    try expectEqual(@as(usize, 1), lc.line);
    try expectEqual(@as(usize, 3), lc.col);
}

test "byteToLineCol: last line / end of buffer" {
    const buf: []const u8 = "hello\nworld\n!";
    // Last char 'l' on line 2, col 0.
    const lc: LineCol = byteToLineCol(buf, 12);
    try expectEqual(@as(usize, 2), lc.line);
    try expectEqual(@as(usize, 0), lc.col);
    // Past the end - col extends.
    const past: LineCol = byteToLineCol(buf, 13);
    try expectEqual(@as(usize, 2), past.line);
    try expectEqual(@as(usize, 1), past.col);
}

test "lineColToByte: round-trips byteToLineCol" {
    const buf: []const u8 = "abc\ndef\nghij";
    var pos: usize = 0;
    while (pos <= buf.len) : (pos += 1) {
        const lc: LineCol = byteToLineCol(buf, pos);
        // Round-trip: byte -> (line, col) -> byte must land exactly where it started.
        const back: usize = lineColToByte(buf, lc);
        try expectEqual(pos, back);
    }
}

test "lineColToByte: column past line-end clamps to line-end" {
    const buf: []const u8 = "ab\ncdef\ng";
    // Line 0 has 2 chars (a, b). Asking for col 99 should land
    // at line 0's end (byte 2 = position of the \n).
    const at_line0_end: usize = lineColToByte(buf, .{ .line = 0, .col = 99 });
    try expectEqual(@as(usize, 2), at_line0_end);
    // Line 2 has 1 char (g). Asking for col 5 → byte 9 (end of buf).
    const at_line2_end: usize = lineColToByte(buf, .{ .line = 2, .col = 5 });
    try expectEqual(@as(usize, 9), at_line2_end);
}

test "lineColToByte: line past last line clamps to buffer length" {
    const buf: []const u8 = "abc\ndef";
    // Line 99 doesn't exist - clamps to buf.len.
    const past: usize = lineColToByte(buf, .{ .line = 99, .col = 0 });
    try expectEqual(buf.len, past);
}

// ============================================================================
// Phase A4 callback-helper tests
// ============================================================================
// `InputTextCallbackData` is what callbacks see. Its helper
// methods (`insertChars`, `deleteChars`, `setBuffer`) handle
// buffer mutation + cursor + length accounting in one place; if
// they're wrong every callback that uses them is wrong.

fn makeCallbackData(
    buf: []u8,
    buf_len: *usize,
    cursor: *usize,
) InputTextCallbackData {
    return .{
        .event = .completion,
        .buf = buf,
        .buf_len = buf_len,
        .cursor_pos = cursor,
        .event_char = 0,
        .history_dir = .up,
        .user_data = null,
    };
}

test "InputTextCallbackData.insertChars: at cursor, pushes cursor right" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..5], "hello");
    var len: usize = 5;
    var cursor: usize = 5;
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    const ok: bool = data.insertChars(5, ", world");
    try expect(ok);
    try expectEqual(@as(usize, 12), len);
    try expectEqual(@as(usize, 12), cursor);
    try expectEqualSlices(u8, "hello, world", buf[0..len]);
}

test "InputTextCallbackData.insertChars: before cursor, cursor shifts right" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..5], "abcde");
    var len: usize = 5;
    var cursor: usize = 3; // sitting at 'd'
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    _ = data.insertChars(0, "XY");
    try expectEqual(@as(usize, 7), len);
    try expectEqual(@as(usize, 5), cursor);
    try expectEqualSlices(u8, "XYabcde", buf[0..len]);
}

test "InputTextCallbackData.insertChars: overflow returns false, leaves buf untouched" {
    var buf: [8]u8 = std.mem.zeroes([8]u8);
    @memcpy(buf[0..5], "hello");
    var len: usize = 5;
    var cursor: usize = 5;
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    const ok: bool = data.insertChars(5, "world!"); // 5 + 6 = 11 > 8
    try expect(!ok);
    try expectEqual(@as(usize, 5), len);
    try expectEqualSlices(u8, "hello", buf[0..len]);
}

test "InputTextCallbackData.deleteChars: after cursor, cursor unchanged" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..10], "helloworld");
    var len: usize = 10;
    var cursor: usize = 5; // sitting between hello / world
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    data.deleteChars(5, 5); // wipe "world"
    try expectEqual(@as(usize, 5), len);
    try expectEqual(@as(usize, 5), cursor);
    try expectEqualSlices(u8, "hello", buf[0..len]);
}

test "InputTextCallbackData.deleteChars: before cursor, cursor shifts left" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..10], "helloworld");
    var len: usize = 10;
    var cursor: usize = 10; // at end
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    data.deleteChars(0, 5); // wipe "hello"
    try expectEqual(@as(usize, 5), len);
    try expectEqual(@as(usize, 5), cursor);
    try expectEqualSlices(u8, "world", buf[0..len]);
}

test "InputTextCallbackData.deleteChars: overlapping cursor pulls cursor back" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..10], "helloworld");
    var len: usize = 10;
    var cursor: usize = 7; // 2 chars into "world"
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    data.deleteChars(5, 5); // wipe "world" - cursor was inside
    try expectEqual(@as(usize, 5), len);
    try expectEqual(@as(usize, 5), cursor);
}

test "InputTextCallbackData.setBuffer: replaces and moves cursor to end" {
    var buf: [16]u8 = std.mem.zeroes([16]u8);
    @memcpy(buf[0..5], "hello");
    var len: usize = 5;
    var cursor: usize = 2;
    var data: InputTextCallbackData = makeCallbackData(&buf, &len, &cursor);
    const ok: bool = data.setBuffer("greetings");
    try expect(ok);
    try expectEqual(@as(usize, 9), len);
    try expectEqual(@as(usize, 9), cursor);
    try expectEqualSlices(u8, "greetings", buf[0..len]);
}

// ============================================================================
// formatValue - unit tests
// ============================================================================
// `formatValue` is the pure dispatcher inside `valueImpl` - extracted so
// the comptime type-handling logic can be exercised without spinning up
// a full UiContext + Window fixture. One test per arm of the switch.

test "formatValue: bool true / false" {
    var buf: [16]u8 = undefined;
    try expectEqualSlices(u8, "true", formatValue(&buf, true));
    try expectEqualSlices(u8, "false", formatValue(&buf, false));
}

test "formatValue: signed int prints decimal" {
    var buf: [16]u8 = undefined;
    try expectEqualSlices(u8, "-42", formatValue(&buf, @as(i32, -42)));
    try expectEqualSlices(u8, "0", formatValue(&buf, @as(i32, 0)));
}

test "formatValue: unsigned int prints decimal" {
    var buf: [16]u8 = undefined;
    try expectEqualSlices(u8, "100", formatValue(&buf, @as(usize, 100)));
    try expectEqualSlices(u8, "65535", formatValue(&buf, @as(u32, 65535)));
}

test "formatValue: float prints with 3 decimals" {
    var buf: [16]u8 = undefined;
    try expectEqualSlices(u8, "1.234", formatValue(&buf, @as(f32, 1.234)));
    // Round-up edge: 0.0005 → "0.001" (single rounding step at 3 dp).
    try expectEqualSlices(u8, "0.000", formatValue(&buf, @as(f32, 0.0)));
}

test "formatValue: enum uses @tagName" {
    const Mode = enum { idle, running, paused };
    var buf: [16]u8 = undefined;
    try expectEqualSlices(u8, "running", formatValue(&buf, Mode.running));
    try expectEqualSlices(u8, "idle", formatValue(&buf, Mode.idle));
}

test "formatValue: string slice passthrough" {
    var buf: [16]u8 = undefined;
    const s: []const u8 = "hello";
    try expectEqualSlices(u8, "hello", formatValue(&buf, s));
}

test "formatValue: comptime int" {
    var buf: [16]u8 = undefined;
    // Literal `42` is a comptime_int - the dispatcher must accept that
    // tag, not just runtime ints.
    try expectEqualSlices(u8, "42", formatValue(&buf, 42));
}

test "formatValue: overflow returns empty slice (no crash)" {
    // 4-byte buffer; the number 12345 needs 5 bytes formatted ("12345").
    // bufPrint errors → caller's empty-slice fallback fires. Display
    // shows nothing rather than crashing the demo.
    var tiny: [4]u8 = undefined;
    const out = formatValue(&tiny, @as(i32, 12345));
    try expectEqual(@as(usize, 0), out.len);
}

// ============================================================================
// SelectionBasicStorage tests
// ============================================================================
// Headless tests for `SelectionBasicStorage`. No UiContext, no
// rendering - pure data-structure correctness. Imgui equivalents:
// `imgui_widgets.cpp:8580-8810` (default adapter case).
// The test fixtures synthesize `MultiSelectIO` and call
// `applyRequests` directly. This is the same code path that will
// run after `beginMultiSelect` / `endMultiSelect` once the
// click-emit logic lands.

test "SelectionBasicStorage: empty by default" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);
    try expectEqual(@as(usize, 0), sel.size());
    try expect(!sel.contains(0));
    try expect(!sel.contains(42));
}

test "SelectionBasicStorage: add and contains" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);
    try sel.add(std.testing.allocator, 5);
    try expect(sel.contains(5));
    try expect(!sel.contains(4));
    try expect(!sel.contains(6));
    try expectEqual(@as(usize, 1), sel.size());
}

test "SelectionBasicStorage: add same id is idempotent" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);
    try sel.add(std.testing.allocator, 7);
    try sel.add(std.testing.allocator, 7);
    try sel.add(std.testing.allocator, 7);
    try expectEqual(@as(usize, 1), sel.size());
}

test "SelectionBasicStorage: remove" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);
    try sel.add(std.testing.allocator, 3);
    try sel.add(std.testing.allocator, 4);
    sel.remove(3);
    try expect(!sel.contains(3));
    try expect(sel.contains(4));
    try expectEqual(@as(usize, 1), sel.size());
    // Removing a non-present id is a no-op.
    sel.remove(99);
    try expectEqual(@as(usize, 1), sel.size());
}

test "SelectionBasicStorage: clear" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);
    try sel.add(std.testing.allocator, 1);
    try sel.add(std.testing.allocator, 2);
    try sel.add(std.testing.allocator, 3);
    sel.clear();
    try expectEqual(@as(usize, 0), sel.size());
    try expect(!sel.contains(1));
    try expect(!sel.contains(2));
    try expect(!sel.contains(3));
}

test "SelectionBasicStorage.applyRequests: SetAll(true) selects all" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    const reqs = [_]SelectionRequest{.{ .set_all = true }};
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = null,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);

    try expectEqual(@as(usize, 10), sel.size());
    var i: u64 = 0;
    while (i < 10) : (i += 1) {
        try expect(sel.contains(i));
    }
}

test "SelectionBasicStorage.applyRequests: SetAll(false) clears" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    // Pre-populate.
    var i: u64 = 0;
    while (i < 5) : (i += 1) try sel.add(std.testing.allocator, i);

    const reqs = [_]SelectionRequest{.{ .set_all = false }};
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = null,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 5,
    };
    try sel.applyRequests(std.testing.allocator, &io);
    try expectEqual(@as(usize, 0), sel.size());
}

test "SelectionBasicStorage.applyRequests: SetRange inclusive both ends" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    const reqs = [_]SelectionRequest{.{ .set_range = .{
        .first = 2,
        .last = 5,
        .direction = 1,
        .selected = true,
    } }};
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = null,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);

    // [2, 3, 4, 5] inclusive → size 4.
    try expectEqual(@as(usize, 4), sel.size());
    try expect(!sel.contains(1));
    try expect(sel.contains(2));
    try expect(sel.contains(3));
    try expect(sel.contains(4));
    try expect(sel.contains(5));
    try expect(!sel.contains(6));
}

test "SelectionBasicStorage.applyRequests: SetRange unselect deletes" {
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    var i: u64 = 0;
    while (i < 10) : (i += 1) try sel.add(std.testing.allocator, i);

    const reqs = [_]SelectionRequest{.{ .set_range = .{
        .first = 3,
        .last = 7,
        .direction = 1,
        .selected = false,
    } }};
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = null,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);

    // Started 10, unselected 5 in [3..7] → 5 remain.
    try expectEqual(@as(usize, 5), sel.size());
    try expect(sel.contains(0));
    try expect(sel.contains(1));
    try expect(sel.contains(2));
    try expect(!sel.contains(3));
    try expect(!sel.contains(7));
    try expect(sel.contains(8));
}

test "SelectionBasicStorage.applyRequests: SetRange backward direction same result" {
    // direction is informational - applyRequests treats first/last
    // identically regardless of sign. Imgui keeps direction for
    // callers who want to preserve selection ORDER (which zimr
    // doesn't model today).
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    const reqs = [_]SelectionRequest{.{
        .set_range = .{
            .first = 5,
            .last = 2, // first > last is valid; means user shift-clicked upward
            .direction = -1,
            .selected = true,
        },
    }};
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = null,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);
    try expectEqual(@as(usize, 4), sel.size());
    try expect(sel.contains(2));
    try expect(sel.contains(5));
}

test "SelectionBasicStorage.applyRequests: typical shift-click pair (clear+range)" {
    // The most common request sequence: shift-click emits
    // SetAll(false) followed by SetRange(anchor..clicked, true).
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    // Caller had item 3 selected from a prior plain-click.
    try sel.add(std.testing.allocator, 3);

    const reqs = [_]SelectionRequest{
        .{ .set_all = false },
        .{ .set_range = .{ .first = 3, .last = 7, .direction = 1, .selected = true } },
    };
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = 3,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);

    try expectEqual(@as(usize, 5), sel.size());
    var i: u64 = 3;
    while (i <= 7) : (i += 1) try expect(sel.contains(i));
}

test "SelectionBasicStorage.applyRequests: Ctrl-click toggle pattern (no clear)" {
    // Ctrl-click emits ONLY SetRange(item..item, !was_selected)
    // no SetAll-clear preceding. Demonstrates that requests
    // compose correctly without auto-clear.
    var sel: SelectionBasicStorage = .{};
    defer sel.deinit(std.testing.allocator);

    try sel.add(std.testing.allocator, 1);
    try sel.add(std.testing.allocator, 4);

    // User Ctrl-clicked item 4: toggle to unselected.
    const reqs = [_]SelectionRequest{
        .{ .set_range = .{ .first = 4, .last = 4, .direction = 1, .selected = false } },
    };
    const io: MultiSelectIO = .{
        .requests = &reqs,
        .range_src_item = 4,
        .nav_id_item = null,
        .nav_id_selected = false,
        .items_count = 10,
    };
    try sel.applyRequests(std.testing.allocator, &io);

    try expect(sel.contains(1));
    try expect(!sel.contains(4));
    try expectEqual(@as(usize, 1), sel.size());
}

// ============================================================================
//: MultiSelect Begin/End + click-emit integration tests
// ============================================================================
// These tests construct a UiContext, drive a single
// beginMultiSelect → setNextItemSelectionUserData →
// multiSelectItemFooter → endMultiSelect cycle directly (bypassing
// the full beginFrame plumbing), and assert the resulting request
// list against the click → request truth table from the tutorial.
// What's exercised:
//   - Plain click: SetAll(false) + SetRange(item..item, true).
//   - Ctrl-click on unselected: SetRange(item..item, true) only.
//   - Ctrl-click on selected: SetRange(item..item, false) only
//     (toggle off, no auto-clear).
//   - Shift-click: SetAll(false) + SetRange(anchor..item, true).
//   - Escape (with clear_on_escape): SetAll(false) from Begin.
//   - clear_on_click_void: SetAll(false) when click hits no item.
//   - no_auto_clear_on_reselect: re-tap on selected leaves siblings.
// What's NOT exercised here (filed for follow-up tests):
//   - Multi-frame state survival (anchor across frames).
//   - Selectable's actual click path (these tests call the footer
//     directly with a synthesized `pressed=true`).

// Synthesize a focused-window state so beginMultiSelect's
// `is_focused = (focused_window_id == w.id)` succeeds without
// having to drive a real frame.
fn msTestSetup(ctx: *UiContext) *Window {
    const w = ctx.gpa.create(Window) catch panicf(@src(), "OOM", .{});
    w.* = .{
        .id = 1234,
        .pos = .{ 0, 0 },
        .size = .{ 400, 800 },
    };
    ctx.windows.put(ctx.gpa, w.id, w) catch panicf(@src(), "OOM", .{});
    ctx.current_window = w;
    ctx.focused_window_id = w.id;
    return w;
}

test "MultiSelect: plain click → SetAll(false) + SetRange(item..item, true)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = msTestSetup(&ctx);

    _ = beginMultiSelectImpl(&ctx, .{}, 0, 10);
    // Tag item 3, simulate a press on it.
    ctx.next_item_selection_user_data = 3;
    multiSelectItemFooter(&ctx, 999, false, true);

    const io: *const MultiSelectIO = endMultiSelectImpl(&ctx);
    // Expect exactly 2 requests: SetAll(false), SetRange(3..3, true).
    try expectEqual(@as(usize, 2), io.requests.len);
    try expect(io.requests[0] == .set_all);
    try expectEqual(false, io.requests[0].set_all);
    try expect(io.requests[1] == .set_range);
    try expectEqual(@as(u64, 3), io.requests[1].set_range.first);
    try expectEqual(@as(u64, 3), io.requests[1].set_range.last);
    try expectEqual(true, io.requests[1].set_range.selected);
}

test "MultiSelect: Ctrl-click on unselected → SetRange(item..item, true) only" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = msTestSetup(&ctx);
    ctx.input.keys[@backingInt(KeyCode.left_control)].down = true;

    _ = beginMultiSelectImpl(&ctx, .{}, 0, 10);
    ctx.next_item_selection_user_data = 7;
    multiSelectItemFooter(&ctx, 999, false, true);

    const io: *const MultiSelectIO = endMultiSelectImpl(&ctx);
    // Ctrl-click skips the SetAll-clear; just toggles single item.
    try expectEqual(@as(usize, 1), io.requests.len);
    try expect(io.requests[0] == .set_range);
    try expectEqual(@as(u64, 7), io.requests[0].set_range.first);
    try expectEqual(@as(u64, 7), io.requests[0].set_range.last);
    try expectEqual(true, io.requests[0].set_range.selected);
}

test "MultiSelect: Ctrl-click on selected → SetRange(item..item, false) only (toggle off)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = msTestSetup(&ctx);
    ctx.input.keys[@backingInt(KeyCode.left_control)].down = true;

    _ = beginMultiSelectImpl(&ctx, .{}, 1, 10);
    ctx.next_item_selection_user_data = 7;
    // Pass selected=true so the toggle resolves to false.
    multiSelectItemFooter(&ctx, 999, true, true);

    const io: *const MultiSelectIO = endMultiSelectImpl(&ctx);
    try expectEqual(@as(usize, 1), io.requests.len);
    try expect(io.requests[0] == .set_range);
    try expectEqual(false, io.requests[0].set_range.selected);
}

test "MultiSelect: Shift-click → SetAll(false) + SetRange(anchor..item, true)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = msTestSetup(&ctx);

    // First, plain-click item 3 to establish an anchor.
    _ = beginMultiSelectImpl(&ctx, .{}, 0, 10);
    ctx.next_item_selection_user_data = 3;
    multiSelectItemFooter(&ctx, 999, false, true);
    _ = endMultiSelectImpl(&ctx);
    // Sanity: anchor stored.
    const stored: MultiSelectState = ctx.ms_storage.get(ctx.current_multi_select.?.id) orelse unreachable;
    try expectEqual(@as(?u64, 3), stored.range_src_item);

    // Next frame: shift-click item 7.
    ctx.input.keys[@backingInt(KeyCode.left_shift)].down = true;
    _ = beginMultiSelectImpl(&ctx, .{}, 1, 10);
    ctx.next_item_selection_user_data = 7;
    multiSelectItemFooter(&ctx, 999, false, true);

    const io: *const MultiSelectIO = endMultiSelectImpl(&ctx);
    try expectEqual(@as(usize, 2), io.requests.len);
    try expect(io.requests[0] == .set_all);
    try expectEqual(false, io.requests[0].set_all);
    try expect(io.requests[1] == .set_range);
    try expectEqual(@as(u64, 3), io.requests[1].set_range.first);
    try expectEqual(@as(u64, 7), io.requests[1].set_range.last);
    try expectEqual(true, io.requests[1].set_range.selected);
    try expectEqual(@as(i2, 1), io.requests[1].set_range.direction);
}

test "MultiSelect: Escape with clear_on_escape → SetAll(false) from Begin" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = msTestSetup(&ctx);
    ctx.input.keys[@backingInt(KeyCode.escape)].pressed_this_frame = true;

    // selection_size > 0 is required to trigger the shortcut.
    const io: *const MultiSelectIO = beginMultiSelectImpl(&ctx, .{ .clear_on_escape = true }, 3, 10);

    // Pending request from Begin should be SetAll(false).
    try expectEqual(@as(usize, 1), io.requests.len);
    try expect(io.requests[0] == .set_all);
    try expectEqual(false, io.requests[0].set_all);

    // Also: the loop_request_set_all flag is set, so the Header
    // override fires for all items rendered in this frame.
    try expectEqual(
        @as(@TypeOf(ctx.current_multi_select.?.loop_request_set_all), .clear),
        ctx.current_multi_select.?.loop_request_set_all,
    );

    _ = endMultiSelectImpl(&ctx);
}

