// ============================================================================
//: Splitter tests
// ============================================================================
// Headless tests for splitterImpl. Constructs a UiContext + Window
// directly, then drives `splitterImpl` with synthesized input state
// across one or two frames and asserts the *split_pos behavior.
// What's exercised:
//   - Idle (no mouse interaction) → *split_pos unchanged.
//   - Held drag → *split_pos changes by mouse delta.
//   - Clamp against min1 (can't shrink first pane below it).
//   - Clamp against min2 (can't shrink second pane below it).
//   - Released (mouse_left_released) clears active_id.

fn splitterTestSetup(ctx: *UiContext) *Window {
    const w = ctx.gpa.create(Window) catch panicf(@src(), "OOM", .{});
    w.* = .{
        .id = 5555,
        .pos = .{ 0, 0 },
        .size = .{ 400, 800 },
        // Cursor sits at window-padding (default 8,8 in style) - the
        // splitter widget computes geometry relative to cursor.
        .layout = .{
            .origin = .{ 8, 8 },
            .cursor_pos = .{ 8, 8 },
        },
    };
    ctx.windows.put(ctx.gpa, w.id, w) catch panicf(@src(), "OOM", .{});
    ctx.current_window = w;
    return w;
}

test "Splitter: idle (no input) leaves *split_pos unchanged" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = splitterTestSetup(&ctx);

    var split_pos: f32 = 120;
    const held: bool = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
    });
    try expectEqual(false, held);
    try expectEqual(@as(f32, 120), split_pos);
}

test "Splitter: held drag mutates *split_pos by mouse delta (axis .x)" {
    // New semantics: bar renders AT the cursor, not at
    // cursor + split_pos. Caller positions the cursor at the bar's
    // intended X via sameLine after the first pane's endChild. So
    // we set the cursor to where the bar should sit (here: x=128,
    // simulating "pane 1 of width 120 ended; cursor now at x=128").
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    var split_pos: f32 = 120;

    // Cursor at (128, 8) → bar at x=128, w=4, center=130.
    w.layout.cursor_pos = .{ 128, 8 };
    ctx.input.mouse_pos = .{ 130, 100 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;

    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
    });
    // First-frame delta should be ~0 (mouse at bar center).
    try expectApproxEqAbs(@as(f32, 120), split_pos, 0.5);

    // Simulate next frame: cursor reset to new bar position
    // (pane 1's new width = updated split_pos).
    w.layout.cursor_pos = .{ 8 + split_pos, 8 };
    w.layout.line_height = 0;

    // Frame 2: mouse drifted right by +30. Bar wants to move with
    // it, so split_pos grows by 30.
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_pos = .{ 160, 100 };
    const held: bool = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
    });
    try expectEqual(true, held);
    // bar_center = cursor.x + 2 = 130. delta = 160 - 130 = 30.
    // split_pos = 120 + 30 = 150.
    try expectApproxEqAbs(@as(f32, 150), split_pos, 1.0);
}

test "Splitter: clamp against min1 (can't shrink first pane below)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    var split_pos: f32 = 100;

    // Cursor at where bar should sit (x = pane1.x + split_pos = 8+100=108).
    w.layout.cursor_pos = .{ 108, 8 };
    ctx.input.mouse_pos = .{ 110, 100 }; // bar center at 110
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
        .min1 = 80,
    });

    // Simulate next frame, cursor follows new split_pos.
    w.layout.cursor_pos = .{ 8 + split_pos, 8 };
    w.layout.line_height = 0;
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_pos = .{ 30, 100 }; // way to the left
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
        .min1 = 80,
    });

    // split_pos cannot go below min1=80.
    try expectApproxEqAbs(@as(f32, 80), split_pos, 0.5);
}

test "Splitter: clamp against min2 (can't shrink second pane below)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    var split_pos: f32 = 280; // close to right edge of total=400

    // Cursor at bar position = 8 + 280 = 288.
    w.layout.cursor_pos = .{ 288, 8 };
    ctx.input.mouse_pos = .{ 290, 100 }; // bar center
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
        .min2 = 100,
        .bar_width = 4,
    });

    w.layout.cursor_pos = .{ 8 + split_pos, 8 };
    w.layout.line_height = 0;
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_pos = .{ 380, 100 }; // way to the right
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
        .min2 = 100,
        .bar_width = 4,
    });

    // Max split_pos = total - bar_width - min2 = 400 - 4 - 100 = 296.
    try expectApproxEqAbs(@as(f32, 296), split_pos, 0.5);
}

test "Splitter: vertical (.y) axis drags along Y" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    var split_pos: f32 = 200;

    // Cursor at (8, 208) →.y bar at Y=208, h=4, center Y=210.
    w.layout.cursor_pos = .{ 8, 208 };
    ctx.input.mouse_pos = .{ 100, 210 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = splitterImpl(&ctx, "vs", &split_pos, .y, .{
        .total_along_axis = 600,
    });

    w.layout.cursor_pos = .{ 8, 8 + split_pos };
    w.layout.line_height = 0;
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_pos = .{ 100, 250 }; // drift +40 along Y
    const held: bool = splitterImpl(&ctx, "vs", &split_pos, .y, .{
        .total_along_axis = 600,
    });

    try expectEqual(true, held);
    try expectApproxEqAbs(@as(f32, 240), split_pos, 1.0);
}

test "Splitter: release clears active_id" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    var split_pos: f32 = 120;
    // Cursor at bar position 8+120=128.
    w.layout.cursor_pos = .{ 128, 8 };
    ctx.input.mouse_pos = .{ 130, 100 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
    });
    try expect(ctx.active_id != 0);

    w.layout.cursor_pos = .{ 8 + split_pos, 8 };
    w.layout.line_height = 0;
    // Release.
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_left_down = false;
    ctx.input.mouse_left_released = true;
    _ = splitterImpl(&ctx, "s", &split_pos, .x, .{
        .total_along_axis = 400,
    });
    try expectEqual(@as(Id, 0), ctx.active_id);
}

