}

// ============================================================================
//: TreeNodeEx flag tests
// ============================================================================
// Headless tests for treeNodeExImpl. Uses the same
// `splitterTestSetup` pattern: synthesizes a Window + sets
// current_window directly, then drives treeNodeExImpl with
// `default_open` / `leaf` / `setNextItemOpen` / etc. and asserts
// the resulting open-state and persistence.

test "TreeNodeEx: leaf returns true unconditionally, no toggle" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    _ = splitterTestSetup(&ctx);

    const open_a: bool = treeNodeExImpl(&ctx, "leaf-a", .{ .leaf = true });
    try expectEqual(true, open_a);

    // Click on the leaf: should NOT toggle anything.
    ctx.input.mouse_pos = .{ 12, 12 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = treeNodeExImpl(&ctx, "leaf-b", .{ .leaf = true });
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_left_released = true;
    const open_b: bool = treeNodeExImpl(&ctx, "leaf-b", .{ .leaf = true });
    // Still true (leaf always returns true), no stored state.
    try expectEqual(true, open_b);
    // No entry in tree_open_state for leaves.
    const id: Id = widgetId(&ctx, ctx.current_window.?, "leaf-b");
    try expectEqual(@as(?bool, null), ctx.tree_open_state.get(id));
}

