test "TreeNodeEx: isItemToggledOpen surfaces toggle edge" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);

    // First call: not toggled (just initial submission).
    _ = treeNodeExImpl(&ctx, "folder", .{});
    try expectEqual(false, ctx.item_just_toggled);

    // Simulate click on the node. Cursor at (8,8); node rect
    // starts at cursor, height = font_size (10) + 2*0 = 10
    // (no frame_padding), width = tri_size+4+text_width.
    // Click at (12, 12) is inside.
    w.layout.cursor_pos = .{ 8, 8 };
    w.layout.line_height = 0;
    ctx.input.mouse_pos = .{ 12, 12 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = treeNodeExImpl(&ctx, "folder", .{});
    // Press-down doesn't toggle yet - toggle is on release.
    try expectEqual(false, ctx.item_just_toggled);

    // Release.
    w.layout.cursor_pos = .{ 8, 8 };
    w.layout.line_height = 0;
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_left_down = false;
    ctx.input.mouse_left_released = true;
    _ = treeNodeExImpl(&ctx, "folder", .{});
    try expectEqual(true, ctx.item_just_toggled);
}

