//: regression tests for the sameLine fix
// (previously, sameLine left cursor_pos[1] past the previous widget's
// bottom - widgets ended up vertically stacked rather than on the
// same row). Imgui equivalent: SameLine() restores
// CursorPos.y = CursorPosPrevLine.y.

test "sameLine: keeps next widget on the same row as previous" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    w.layout.cursor_pos = .{ 8, 8 };

    const u = Ui{ .ctx = &ctx };
    _ = u.button("A", .{});
    const a_y: f32 = w.layout.last_item_rect.y;
    u.sameLine(.{});
    _ = u.button("B", .{});
    const b_y: f32 = w.layout.last_item_rect.y;
    try expectEqual(a_y, b_y);
}

test "sameLine after endChild: next widget at child's row" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    w.layout.cursor_pos = .{ 8, 8 };

    const u = Ui{ .ctx = &ctx };
    if (u.beginChild("L", .{ 100, 200 }, .{})) {
        defer u.endChild();
        _ = u.button("inside", .{});
    }
    const child_y: f32 = w.layout.last_item_rect.y;
    u.sameLine(.{});
    _ = u.button("after", .{});
    const after_y: f32 = w.layout.last_item_rect.y;
    // "after" must be at the SAME Y as the child it sits beside.
    try expectEqual(child_y, after_y);
}

test "beginChild: second widget renders at child's inner-left, not parent's" {
    // Regression for the left-clip bug discovered:
    // advanceLayout used `w.pos[0] + window_pad` for its next-row
    // cursor reset, ignoring which child was active. Widgets inside
    // a child anchored away from parent's left edge wrapped back to
    // the parent's left on every row.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    w.pos = .{ 0, 0 };
    w.layout.origin[0] = 8; // window content left
    w.layout.cursor_pos = .{ 200, 8 }; // simulate cursor positioned after sameLine
    w.layout.last_item_rect = .{ .x = 100, .y = 8, .width = 100, .height = 20 };

    const u = Ui{ .ctx = &ctx };
    if (u.beginChild("right", .{ 150, 100 }, .{})) {
        defer u.endChild();
        _ = u.button("first", .{});
        const first_x: f32 = w.layout.last_item_rect.x;
        _ = u.button("second", .{});
        const second_x: f32 = w.layout.last_item_rect.x;
        // Second widget must align with the FIRST inside the child
        // NOT bounce back to the parent window's content-left at x=8.
        try expectEqual(first_x, second_x);
    }
}

test "beginChild auto-fill: nested child bounds to PARENT child's right edge, not window's" {
    // Regression for the right-pane spillover bug seen:
    // an `editor` child with size.{0, h} inside a narrow `right`
    // child filled to the TOP-LEVEL WINDOW's right edge, blowing
    // past the right child's right edge. Fixed by
    // routing the auto-fill through `LayoutScope.work_rect_max`.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    // Simulate a workspace at 400 wide, sample a "right" pane
    // that's narrow (20 wide) at x=340.
    w.pos = .{ 0, 0 };
    w.size = .{ 400, 600 };
    w.layout.origin = .{ 8, 8 };
    w.layout.work_rect_max = .{ 392, 592 }; // workspace's inner-bottom-right
    w.layout.cursor_pos = .{ 340, 8 };

    const u = Ui{ .ctx = &ctx };
    if (u.beginChild("right", .{ 20, 200 }, .{})) {
        defer u.endChild();
        // After's child-as-Window refactor, the child's
        // outer rect is `current_window.pos` + `.size` - the child
        // IS a Window now.
        const right_child: *Window = ctx.current_window.?;
        const right_pane_right: f32 = right_child.pos[0] + right_child.size[0];
        // Now an editor inside with auto-fill width.
        if (u.beginChild("editor", .{ 0, 100 }, .{})) {
            defer u.endChild();
            const editor: *Window = ctx.current_window.?;
            const editor_right: f32 = editor.pos[0] + editor.size[0];
            // Editor's right edge MUST NOT exceed the right child's
            // right edge. Before the fix, this assertion failed by
            // ~360 pixels.
            try expect(editor_right <= right_pane_right);
        }
    }
}

test "beginChild: explicit oversized width clamped to parent scope" {
    // Defensive structural fix: even when user math is
    // wrong - e.g. forgot to account for `sameLine` spacing - the
    // child's actual rect is clamped to its parent's `work_rect_max`.
    // Before the clamp, ui_panes's right pane extended ~16px past
    // the workspace edge (the bug the user photographed).
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    w.pos = .{ 0, 0 };
    w.size = .{ 400, 600 };
    w.layout.origin = .{ 8, 8 };
    w.layout.work_rect_max = .{ 392, 592 }; // workspace's inner-bottom-right
    // Place cursor at x=380, then ask for a child 50 pixels wide.
    // 380 + 50 = 430 - that's 38 pixels past work_rect_max[0]=392.
    // The clamp must trim actual_size[0] to 12 (= 392 - 380).
    w.layout.cursor_pos = .{ 380, 8 };
    const parent_right: f32 = w.layout.work_rect_max[0];

    const u = Ui{ .ctx = &ctx };
    if (u.beginChild("oversized", .{ 50, 100 }, .{})) {
        defer u.endChild();
        // After, the child is a real Window; its outer
        // rect is `child.pos` + `child.size`.
        const child: *Window = ctx.current_window.?;
        const child_right: f32 = child.pos[0] + child.size[0];
        // Right edge of the child must not exceed parent's
        // work_rect_max[0] (captured before beginChild).
        try expect(child_right <= parent_right);
        // Specifically: clamped to exactly 12 pixels.
        try expectApproxEqAbs(@as(f32, 12), child.size[0], 0.1);
    }
}

test "row max-height: sameLine across mixed heights clears the tallest" {
    // Latent bug discovered during architecture discussion (turn
    // 308.5): if widgets on a sameLine row have different heights
    // (A=20, B=10, C=15), the row's next-wrap must clear the
    // TALLEST widget on the row (20), not just the last one (15).
    // imgui's `PrevLineSize.y` tracks the row's max; zimr's
    // `LayoutScope.line_height` accumulates and is promoted to
    // `prev_line_height` on advance.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const w: *Window = splitterTestSetup(&ctx);
    w.layout.cursor_pos = .{ 0, 0 };
    w.layout.origin = .{ 0, 0 };
    w.layout.cursor_pos_prev_line = .{ 0, 0 };

    // Simulate row of three widgets at heights 20, 10, 15 via
    // direct advanceLayout calls (skipping widget construction so
    // we can pin down the row-height contract in isolation).
    advanceLayout(w, .{ 50, 20 }, .{ 4, 4 }, 8); // widget A, h=20
    const u = Ui{ .ctx = &ctx };
    u.sameLine(.{});
    advanceLayout(w, .{ 30, 10 }, .{ 4, 4 }, 8); // widget B, h=10 (sameLine)
    u.sameLine(.{});
    advanceLayout(w, .{ 40, 15 }, .{ 4, 4 }, 8); // widget C, h=15 (sameLine)

    // After C's advance, cursor.y should clear the TALLEST widget
    // on the row (A's 20), not just C's 15. Expected next-row Y:
    //   row_top (0) + max_height (20) + spacing (4) = 24.
    try expectApproxEqAbs(@as(f32, 24), w.layout.cursor_pos[1], 0.1);
}

test "cursor_pos_prev_line: seeded at window-open inner origin" {
    // A `sameLine` call before ANY widget submission must not read
    // an uninitialized (0, 0) cursor_pos_prev_line. openWindow
    // and beginChild both seed it to inner_origin. This test
    // documents the contract; the actual openWindow path requires
    // a full UiContext + GL setup, so we exercise the same seeding
    // via beginChild.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const parent: *Window = splitterTestSetup(&ctx);
    parent.layout.cursor_pos = .{ 8, 8 };

    const u = Ui{ .ctx = &ctx };
    if (u.beginChild("seed-check", .{ 100, 100 }, .{})) {
        defer u.endChild();
        // After, inside beginChild, `current_window` is
        // the CHILD Window with its own layout. No widget
        // submitted yet - child's cursor_pos_prev_line must match
        // its inner origin (not (0,0) from default init).
        const child: *Window = ctx.current_window.?;
        try expectEqual(child.layout.origin[0], child.layout.cursor_pos_prev_line[0]);
        try expectEqual(child.layout.origin[1], child.layout.cursor_pos_prev_line[1]);
        // And neither is 0 (the buggy default).
        try expect(child.layout.cursor_pos_prev_line[0] > 0);
        try expect(child.layout.cursor_pos_prev_line[1] > 0);
    }
}

// ============================================================================
//.i + d.ii (turns 321-322) - title-bar drag tracks dragging_window
// with cumulative-motion threshold
// ============================================================================

test "5.5d.ii: dock-drag threshold gates dragging_window (null below, set above)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    ctx.canvas_w = 800;
    ctx.canvas_h = 600;

    // Build a single window via the normal path so it has a
    // populated id, pos, size, name, etc. Submit one frame to
    // register the window in `ctx.windows`.
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};

    // Frame 1: register the window.
    {
        const u: Ui = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = u.window("Draggy", .{
            .initial_pos = .{ 100, 100 },
            .initial_size = .{ 200, 150 },
        }) orelse return error.NoWindow;
        h.close();
    }
    // Sanity: dragging_window starts as null (no drag).
    try expectEqual(@as(?Id, null), ctx.dock.dragging_window);

    // Frame 2: mouse down inside the title bar; this triggers the
    // drag-begin path. No motion yet - `dragging_window` must
    // remain null because we haven't passed dock_drag_threshold_px.
    const w: *Window = ctx.windows.values()[0];
    const w_id: Id = w.id;
    const press_pos: Vec2 = .{ w.pos[0] + 20, w.pos[1] + 8 };
    ctx.input.mouse_pos = press_pos;
    ctx.input.mouse_left_down = true;
    ctx.input.mouse_left_clicked = true;
    {
        const u: Ui = ctx.beginFrameRaw(ctx.input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = u.window("Draggy", .{}) orelse return error.NoWindow;
        h.close();
    }
    try expectEqual(@as(?Id, null), ctx.dock.dragging_window);

    // Frame 3: mouse moved past the 8 px threshold. Now
    // `dragging_window` must reflect this window's id.
    ctx.input.mouse_pos = .{ press_pos[0] + 20, press_pos[1] };
    ctx.input.mouse_left_clicked = false; // press already happened
    {
        const u: Ui = ctx.beginFrameRaw(ctx.input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = u.window("Draggy", .{}) orelse return error.NoWindow;
        h.close();
    }
    try expectEqual(@as(?Id, w_id), ctx.dock.dragging_window);

    // Frame 4: mouse released - dragging_window must clear.
    ctx.input.mouse_left_down = false;
    ctx.input.mouse_left_clicked = false;
    {
        const u: Ui = ctx.beginFrameRaw(ctx.input, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
        const h: WindowHandle = u.window("Draggy", .{}) orelse return error.NoWindow;
        h.close();
    }
    try expectEqual(@as(?Id, null), ctx.dock.dragging_window);
}

// ============================================================================
//.iv - drop hit-test enqueues DockRequest on release
// ============================================================================

test "5.5d.iv: dockTargetZonesFor returns null for tiny leaves" {
    // At font_size 12, the cross needs ~hs*5 ≈ 60+ px min dim.
    // A 30×30 leaf is comfortably below threshold.
    try expectEqual(@as(?[5]Rectangle, null), dockTargetZonesFor(.{ 0, 0 }, .{ 30, 30 }, 12));
}

test "5.5d.iv: dockTargetZonesFor centers the cross on the leaf" {
    const zones: [5]Rectangle = dockTargetZonesFor(.{ 100, 100 }, .{ 400, 300 }, 14) orelse return error.TooSmall;
    // Leaf center: (300, 250). Center zone (index 0) is centered
    // there regardless of exact size - assert center-of-zone matches
    // center-of-leaf, not exact dimensions (which depend on font_size).
    const center_zone_cx: f32 = zones[0].x + zones[0].width * 0.5;
    const center_zone_cy: f32 = zones[0].y + zones[0].height * 0.5;
    try expectApproxEqAbs(@as(f32, 300), center_zone_cx, 1.0);
    try expectApproxEqAbs(@as(f32, 250), center_zone_cy, 1.0);
    // Center zone is square and ~10% bigger than edge zones.
    try expectApproxEqAbs(zones[0].width, zones[0].height, 0.5);
    try expect(zones[0].width > zones[1].width);
}

test "5.5d.iv: hitTestDockTargets returns center for mouse on center zone" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    leaf.pos = .{ 100, 100 };
    leaf.size = .{ 400, 300 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    // Mouse exactly at leaf center → center zone wins (score ~1.0).
    const hit: DockTargetHit = hitTestDockTargets(&ctx, .{ 300, 250 }) orelse return error.MissedHit;
    try expectEqual(DockTargetKind.center, hit.kind);
    try expectEqual(leaf_id, hit.target_node);
}

test "5.5d.iv: hitTestDockTargets returns right for mouse near right zone center" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    leaf.pos = .{ 0, 0 };
    leaf.size = .{ 400, 300 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    // Compute the right zone's actual center using the helper, then
    // probe with the mouse exactly there. Independent of font_size
    // and adaptive sizing.
    const zones: [5]Rectangle = dockTargetZonesFor(
        leaf.pos,
        leaf.size,
        ctx.style.font_size,
    ) orelse return error.TooSmall;
    const right_cx: f32 = zones[2].x + zones[2].width * 0.5;
    const right_cy: f32 = zones[2].y + zones[2].height * 0.5;
    const hit: DockTargetHit = hitTestDockTargets(&ctx, .{ right_cx, right_cy }) orelse return error.MissedHit;
    try expectEqual(DockTargetKind.right, hit.kind);
}

test "5.5d.iv: hitTestDockTargets returns null when mouse is far from any zone" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    leaf.pos = .{ 0, 0 };
    leaf.size = .{ 400, 300 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    // Far corner of the leaf - way outside every square's pull radius, so the drop
    // floats (docking only happens ON a square).
    try expectEqual(@as(?DockTargetHit, null), hitTestDockTargets(&ctx, .{ 5, 5 }));
}

test "5.5e: dockZoneScore peaks at center, decays smoothly" {
    const z: Rectangle = .{ .x = 100, .y = 100, .width = 40, .height = 40 };
    // Mouse at zone center → score = 1.0
    try expectApproxEqAbs(@as(f32, 1.0), dockZoneScore(z, .{ 120, 120 }, 1.0), 0.001);
    // Mouse at exactly pull_radius distance → score = 0
    const diag_half = @sqrt(@as(f32, 40 * 40 + 40 * 40)) * 0.5; // ~28.28
    try expectApproxEqAbs(@as(f32, 0.0), dockZoneScore(z, .{ 120 + diag_half, 120 }, 1.0), 0.001);
    // Mouse far away → score = 0
    try expectEqual(@as(f32, 0), dockZoneScore(z, .{ 1000, 1000 }, 1.0));
    // Mouse halfway to pull radius → score ~0.5
    try expectApproxEqAbs(@as(f32, 0.5), dockZoneScore(z, .{ 120 + diag_half * 0.5, 120 }, 1.0), 0.01);
}

test "5.5e: closest zone wins (no ambiguity between adjacent zones)" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    leaf.pos = .{ 0, 0 };
    leaf.size = .{ 400, 300 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    const zones: [5]Rectangle = dockTargetZonesFor(
        leaf.pos,
        leaf.size,
        ctx.style.font_size,
    ) orelse return error.TooSmall;
    // Probe at a point that's between center and right but closer
    // to right. Old rect-contains would return "no hit" if the
    // point sat in the gap; new score-based logic gives right.
    const center_cx: f32 = zones[0].x + zones[0].width * 0.5;
    const center_cy: f32 = zones[0].y + zones[0].height * 0.5;
    const right_cx: f32 = zones[2].x + zones[2].width * 0.5;
    // 75% of the way from center to right.
    const probe_x: f32 = center_cx + (right_cx - center_cx) * 0.75;
    const hit: DockTargetHit = hitTestDockTargets(&ctx, .{ probe_x, center_cy }) orelse return error.MissedHit;
    try expectEqual(DockTargetKind.right, hit.kind);
}

test "5.5h: pre-dock pos/size stashed on first dock via dockBuilder" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });

    // Create the window with a recognizable pos/size.
    const w: *Window = findOrCreateWindow(&ctx, "PreDockTest", .{
        .initial_pos = .{ 50, 60 },
        .initial_size = .{ 200, 150 },
    });
    // Sanity: stash empty before any dock.
    try expectEqual(@as(?Vec2, null), w.pre_dock_pos);

    u.dockBuilderDockWindow("PreDockTest", leaf_id);

    // After the first dock, the stash should hold the original
    // floating pos/size.
    try expectEqual(@as(?Vec2, .{ 50, 60 }), w.pre_dock_pos);
    try expectEqual(@as(?Vec2, .{ 200, 150 }), w.pre_dock_size);
}

test "5.5h: pre-dock stash NOT overwritten by re-dock" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_a: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf_b: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });

    const w: *Window = findOrCreateWindow(&ctx, "ReDockTest", .{
        .initial_pos = .{ 10, 20 },
        .initial_size = .{ 300, 200 },
    });

    // First dock: stash is set to (10, 20) / (300, 200).
    u.dockBuilderDockWindow("ReDockTest", leaf_a);
    try expectEqual(@as(?Vec2, .{ 10, 20 }), w.pre_dock_pos);

    // Simulate the window having been moved while docked
    // (shouldn't happen in practice, but exercises the "no
    // re-stash" invariant - moving to leaf_b must NOT overwrite
    // the pre-dock anchor with a docked pos).
    w.pos = .{ 999, 999 };
    u.dockBuilderDockWindow("ReDockTest", leaf_b);
    try expectEqual(@as(?Vec2, .{ 10, 20 }), w.pre_dock_pos);
    try expectEqual(@as(?Vec2, .{ 300, 200 }), w.pre_dock_size);
}

test "5.5h: undock via dockBuilderRemoveNode restores pre-dock rect" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });

    const w: *Window = findOrCreateWindow(&ctx, "UndockTest", .{
        .initial_pos = .{ 80, 90 },
        .initial_size = .{ 250, 175 },
    });
    u.dockBuilderDockWindow("UndockTest", leaf_id);

    // While docked, the window's effective rect is the leaf's
    // (driven each frame by findOrCreateWindow). Simulate that.
    w.pos = .{ 0, 0 };
    w.size = .{ 1000, 500 };

    // Undock: clear via the dock-builder removal path.
    u.dockBuilderRemoveNode(leaf_id);

    // Window should be back at its pre-dock rect, and the
    // anchor should be cleared (ready to re-stash on next dock).
    try expectEqual(@as(Vec2, .{ 80, 90 }), w.pos);
    try expectEqual(@as(Vec2, .{ 250, 175 }), w.size);
    try expectEqual(@as(?Vec2, null), w.pre_dock_pos);
    try expectEqual(@as(?Vec2, null), w.pre_dock_size);
    try expectEqual(@as(?Id, null), w.dock_node_id);
}

test "5.5f: DockNodeFlags packed struct round-trips through u16" {
