test "5.5f: transfer_mask passes leaf-affinity, blocks tree-structural" {
    const all: DockNodeFlags = .{
        .no_split = true,
        .no_tab_bar = true,
        .hidden_tab_bar = true,
        .no_resize = true,
        .no_docking_over_me = true,
        .no_close_button = true,
        .passthru_central = true,
        .is_central = true,
        .is_dockspace = true,
    };
    const transferred: DockNodeFlags = all.intersect(DockNodeFlags.transfer_mask);
    // Leaf-affinity bits move:
    try expect(transferred.no_split);
    try expect(transferred.no_tab_bar);
    try expect(transferred.hidden_tab_bar);
    try expect(transferred.no_resize);
    try expect(transferred.no_docking_over_me);
    try expect(transferred.no_close_button);
    try expect(transferred.is_central);
    // Tree-structural bits stay home:
    try expect(!transferred.passthru_central);
    try expect(!transferred.is_dockspace);
}

test "5.5f: splitNode transfers leaf-affinity flags to inheritor" {
    var dock_ctx: DockContext = .{};
    defer dock_ctx.deinit(std.testing.allocator);

    const root: Id = try dock_ctx.createLeaf(std.testing.allocator, null);
    // Configure the leaf with constraints + a tree-structural flag.
    dock_ctx.lookup(root).?.flags = .{
        .no_split = true,
        .no_close_button = true,
        .is_dockspace = true,
    };

    // Split: existing content goes to child_b (since dir=.right
    // means new content on the right, existing on left → child_a
    // for left = first_child = true... wait, let me match the
    // existing convention). See Dir.isFirstChild and the
    // existing 5.5d test setup.
    const r: SplitResult = try splitNode(&dock_ctx, std.testing.allocator, root, .right, 0.5);

    // Parent (now a split node) keeps is_dockspace but loses
    // leaf-affinity flags.
    const parent: *DockNode = dock_ctx.lookup(root).?;
    try expect(parent.flags.is_dockspace);
    try expect(!parent.flags.no_split);
    try expect(!parent.flags.no_close_button);

    // Inheritor (child_a - existing went to the LEFT for.right
    // because `isFirstChild()` is false for.right, so
    // existing_goes_to_a is true) carries the leaf flags.
    const inheritor: *DockNode = dock_ctx.lookup(r.a).?;
    try expect(inheritor.flags.no_split);
    try expect(inheritor.flags.no_close_button);
    try expect(!inheritor.flags.is_dockspace);

    // Fresh child gets default flags (no constraints).
    const fresh: *DockNode = dock_ctx.lookup(r.b).?;
    try expect(!fresh.flags.no_split);
    try expect(!fresh.flags.no_close_button);
}

