test "5.5f: no_split allows center but blocks side zones" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    leaf.pos = .{ 0, 0 };
    leaf.size = .{ 400, 300 };
    leaf.flags = .{ .no_split = true };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    const zones: [5]Rectangle = dockTargetZonesFor(
        leaf.pos,
        leaf.size,
        ctx.style.font_size,
    ) orelse return error.TooSmall;

    // Center still works.
    const center_hit: DockTargetHit = hitTestDockTargets(&ctx, .{
        zones[0].x + zones[0].width * 0.5,
        zones[0].y + zones[0].height * 0.5,
    }) orelse return error.MissedCenter;
    try expectEqual(DockTargetKind.center, center_hit.kind);

    // Right zone center is a no-hit on a no_split leaf: the side score is zeroed
    // and there is no region fallback, so a drop there floats instead of docking.
    try expectEqual(@as(?DockTargetHit, null), hitTestDockTargets(&ctx, .{
        zones[2].x + zones[2].width * 0.5,
        zones[2].y + zones[2].height * 0.5,
    }));
}

test "runtime dock: enqueue + processRequests + sync links the window" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const w: *Window = findOrCreateWindow(&ctx, "Editor", .{});
    const editor_id: Id = w.id;
    try expectEqual(@as(?Id, null), w.dock_node_id); // starts floating

    // Exactly what the title-bar release handler enqueues for a center drop.
    try ctx.dock.pending_requests.append(ctx.gpa, .{ .dock_as_tab = .{
        .target_node = leaf_id,
        .source_window = editor_id,
    } });
    // Exactly what endFrame does.
    try processRequests(&ctx.dock, ctx.gpa);
    syncDockedWindowIds(&ctx);

    const leaf: *DockNode = ctx.dock.lookup(leaf_id).?;
    try expect(leaf.leaf.?.indexOf(editor_id) != null); // in the tab list
    try expectEqual(@as(?Id, leaf_id), w.dock_node_id); // window linked
}

test "runtime dock: dock_as_split links the source into the new child" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const root: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const editor: *Window = findOrCreateWindow(&ctx, "Editor", .{});
    try dockWindowAsTab(&ctx.dock, ctx.gpa, root, editor.id);
    const files: *Window = findOrCreateWindow(&ctx, "Files", .{});

    // What the release handler enqueues for an edge (bottom) drop.
    try ctx.dock.pending_requests.append(ctx.gpa, .{ .dock_as_split = .{
        .target_node = root,
        .source_window = files.id,
        .dir = .bottom,
