test "5.5i: dockSplitterSeamRect places the seam at the boundary" {
    var dock_ctx: DockContext = .{};
    defer dock_ctx.deinit(std.testing.allocator);

    const root: Id = try dock_ctx.createLeaf(std.testing.allocator, null);
    _ = try splitNode(&dock_ctx, std.testing.allocator, root, .right, 0.25);
    layoutSubtree(&dock_ctx, root, .{ 100, 50 }, .{ 800, 400 });

    const root_node: *DockNode = dock_ctx.lookup(root).?;
    const seam: Rectangle = dockSplitterSeamRect(root_node);
    const avail: f32 = 800 - splitter_size;
    // Seam x = root.pos[0] + avail * 0.25.
    try expectApproxEqAbs(@as(f32, 100 + avail * 0.25), seam.x, 0.001);
    try expectApproxEqAbs(@as(f32, 50), seam.y, 0.001);
    try expectApproxEqAbs(splitter_size, seam.width, 0.001);
    try expectApproxEqAbs(@as(f32, 400), seam.height, 0.001);
}

test "5.5i: splitter drag updates ratio" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const root: Id = try ctx.dock.createLeaf(ctx.gpa, null);
    _ = try splitNode(&ctx.dock, ctx.gpa, root, .right, 0.30);
    layoutSubtree(&ctx.dock, root, .{ 0, 0 }, .{ 800, 400 });
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, root);

    const root_node: *DockNode = ctx.dock.lookup(root).?;
    const initial_seam: Rectangle = dockSplitterSeamRect(root_node);
    const initial_x: f32 = initial_seam.x + initial_seam.width * 0.5;

    // Simulate click on seam: mouse over, mouse_left_clicked.
    ctx.input.mouse_pos = .{ initial_x, 200 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = renderDockSplittersImpl(&ctx, root);
    // active_id should be set.
    const expected_id: Id = hashStr(root, "__dock_splitter");
    try expectEqual(expected_id, ctx.active_id);

    // Next frame: still down, mouse moved 200 px right.
    ctx.input.mouse_left_clicked = false;
    ctx.input.mouse_pos = .{ initial_x + 200, 200 };
    _ = renderDockSplittersImpl(&ctx, root);
    // Ratio should have increased. Mouse at (initial_x + 200) +
    // pivot adjustment gives ~ (avail * 0.3 + 200) / avail ≈ 0.55.
    const new_ratio: f32 = root_node.split.?.ratio;
    try expect(new_ratio > 0.30);
    try expect(new_ratio < 0.70);

    // Release.
    ctx.input.mouse_left_down = false;
    ctx.input.mouse_left_released = true;
    _ = renderDockSplittersImpl(&ctx, root);
    try expectEqual(@as(Id, 0), ctx.active_id);
}

test "5.5i: no_resize flag blocks splitter interaction" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const root: Id = try ctx.dock.createLeaf(ctx.gpa, null);
    _ = try splitNode(&ctx.dock, ctx.gpa, root, .right, 0.30);
    ctx.dock.lookup(root).?.flags = .{ .no_resize = true };
    layoutSubtree(&ctx.dock, root, .{ 0, 0 }, .{ 800, 400 });
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, root);

    const root_node: *DockNode = ctx.dock.lookup(root).?;
    const seam: Rectangle = dockSplitterSeamRect(root_node);
    const initial_ratio: f32 = root_node.split.?.ratio;

    // Click on the seam.
    ctx.input.mouse_pos = .{ seam.x + seam.width * 0.5, 200 };
    ctx.input.mouse_left_clicked = true;
    ctx.input.mouse_left_down = true;
    _ = renderDockSplittersImpl(&ctx, root);

    // active_id should NOT have been claimed.
    try expectEqual(@as(Id, 0), ctx.active_id);

    // Even if we forced active_id, drag wouldn't fire - but
    // simpler: ratio unchanged after the call.
    try expectEqual(initial_ratio, root_node.split.?.ratio);
}

test "5.5g: size_ref on child a locks its size, b absorbs remainder" {
    var dock_ctx: DockContext = .{};
    defer dock_ctx.deinit(std.testing.allocator);

    const root: Id = try dock_ctx.createLeaf(std.testing.allocator, null);
    _ = try splitNode(&dock_ctx, std.testing.allocator, root, .right, 0.5);
    // Lock child a at 200 px.
    dock_ctx.lookup(root).?.split.?.size_ref[0] = 200;

    // 1000-px dockspace: a = 200, b = 1000 - 4 - 200 = 796.
    layoutSubtree(&dock_ctx, root, .{ 0, 0 }, .{ 1000, 400 });
    const root_node: *DockNode = dock_ctx.lookup(root).?;
    const a_node: *DockNode = dock_ctx.lookup(root_node.split.?.child_ids[0]).?;
    const b_node: *DockNode = dock_ctx.lookup(root_node.split.?.child_ids[1]).?;
    try expectApproxEqAbs(@as(f32, 200), a_node.size[0], 0.001);
    try expectApproxEqAbs(@as(f32, 796), b_node.size[0], 0.001);

    // Grow the dockspace to 1400 px. a STAYS at 200; b grows to 1196.
    layoutSubtree(&dock_ctx, root, .{ 0, 0 }, .{ 1400, 400 });
    try expectApproxEqAbs(@as(f32, 200), a_node.size[0], 0.001);
    try expectApproxEqAbs(@as(f32, 1196), b_node.size[0], 0.001);

    // Shrink the dockspace to 600 px. a still 200; b shrinks to 396.
    layoutSubtree(&dock_ctx, root, .{ 0, 0 }, .{ 600, 400 });
    try expectApproxEqAbs(@as(f32, 200), a_node.size[0], 0.001);
    try expectApproxEqAbs(@as(f32, 396), b_node.size[0], 0.001);
}

test "5.5g: size_ref on child b locks its size, a absorbs remainder" {
