test "5.5j: undockSingleWindow restores pre_dock + clears dock_node_id" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const w: *Window = findOrCreateWindow(&ctx, "Closable", .{
        .initial_pos = .{ 30, 40 },
        .initial_size = .{ 200, 150 },
    });
    u.dockBuilderDockWindow("Closable", leaf_id);

    // Simulate docked state - the window's effective rect would
    // be the leaf's during render, but the stash still holds
    // the original floating rect.
    try expectEqual(@as(?Id, leaf_id), w.dock_node_id);
    try expectEqual(@as(?Vec2, .{ 30, 40 }), w.pre_dock_pos);

    undockSingleWindow(&ctx, w.id);

    // After undock: dock id cleared, pre-dock stash drained,
    // window back at original floating rect.
    try expectEqual(@as(?Id, null), w.dock_node_id);
    try expectEqual(@as(?Vec2, null), w.pre_dock_pos);
    try expectEqual(@as(Vec2, .{ 30, 40 }), w.pos);
    try expectEqual(@as(Vec2, .{ 200, 150 }), w.size);

    // Leaf should now have no windows.
    try expectEqual(@as(usize, 0), ctx.dock.lookup(leaf_id).?.leaf.?.window_ids.items.len);
}

