test "5.5j: detachAndStartDrag discards pre_dock_pos, positions under cursor" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const w: *Window = findOrCreateWindow(&ctx, "Detachable", .{
        .initial_pos = .{ 200, 300 },
        .initial_size = .{ 220, 160 },
    });
    u.dockBuilderDockWindow("Detachable", leaf_id);
    // Sanity: docked, pre-dock stash populated.
    try expectEqual(@as(?Id, leaf_id), w.dock_node_id);
    try expectEqual(@as(?Vec2, .{ 200, 300 }), w.pre_dock_pos);

    // Simulate the cursor being at (500, 100) when the user
    // crosses the detach threshold.
    ctx.input.mouse_pos = .{ 500, 100 };
    detachAndStartDrag(&ctx, w.id);

    // After detach:
    //   - dock_node_id cleared
    //   - pre_dock_pos and pre_dock_size dropped (the
    //     window is going to where the cursor is, not back)
    //   - dragging_window set to this window's id
    //   - active_id set to the window's title-bar drag id, so the held-mouse
    //     continue-drag picks up immediately (the fresh-click press can't).
    try expectEqual(@as(?Id, null), w.dock_node_id);
    try expectEqual(@as(?Vec2, null), w.pre_dock_pos);
    try expectEqual(@as(?Vec2, null), w.pre_dock_size);
    try expectEqual(@as(?Id, w.id), ctx.dock.dragging_window);
    try expectEqual(widgetId(&ctx, w, "##drag_title"), ctx.active_id);

    // Position: title bar should be roughly centered horizontally
    // under the cursor and vertically just above it. Cursor was
    // at (500, 100), restored size is (220, 160), title height
    // is `ctx.style.title_bar_height`.
    const title_h: f32 = ctx.style.title_bar_height;
    try expectApproxEqAbs(@as(f32, 500 - 110), w.pos[0], 0.001);
    try expectApproxEqAbs(@as(f32, 100 - title_h * 0.5), w.pos[1], 0.001);
    // Size restored to pre-dock value.
    try expectEqual(@as(Vec2, .{ 220, 160 }), w.size);

    // Leaf is now empty.
    try expectEqual(@as(usize, 0), ctx.dock.lookup(leaf_id).?.leaf.?.window_ids.items.len);
}

test "5.5j: detachAndStartDrag uses w.size when no pre_dock stash" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    const w: *Window = findOrCreateWindow(&ctx, "NoStash", .{
        .initial_pos = .{ 50, 50 },
        .initial_size = .{ 300, 200 },
    });
    u.dockBuilderDockWindow("NoStash", leaf_id);
    // Manually clear the stash (simulating a window that was
    // docked from creation rather than dragged in).
    w.pre_dock_pos = null;
    w.pre_dock_size = null;
    // Simulate the leaf rect having been applied as the
    // window's effective size during render.
    w.size = .{ 800, 400 };

    ctx.input.mouse_pos = .{ 100, 50 };
    detachAndStartDrag(&ctx, w.id);

    // No stash → keeps current (leaf-sized) size as the new
    // floating size. Less ideal than the pre-dock-restore
    // case but doesn't crash.
    try expectEqual(@as(Vec2, .{ 800, 400 }), w.size);
}

test "5.5j: detachAndStartDrag is no-op for non-docked window" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    const w: *Window = findOrCreateWindow(&ctx, "Floater", .{
        .initial_pos = .{ 10, 20 },
        .initial_size = .{ 100, 80 },
    });
