    // Unchanged.
    try expectEqual(@as(?Id, null), w.dock_node_id);
    try expectEqual(@as(?Id, null), ctx.dock.dragging_window);
    try expectEqual(@as(Vec2, .{ 10, 20 }), w.pos);
}

test "5.5j: drag-reorder swaps tab ordering when cursor crosses a sibling slot" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    // Build a dockspace with 3 docked windows: A B C.
    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    ctx.dock.lookup(leaf_id).?.pos = .{ 0, 0 };
    ctx.dock.lookup(leaf_id).?.size = .{ 300, 200 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    _ = findOrCreateWindow(&ctx, "A", .{});
    _ = findOrCreateWindow(&ctx, "B", .{});
    _ = findOrCreateWindow(&ctx, "C", .{});
    u.dockBuilderDockWindow("A", leaf_id);
    u.dockBuilderDockWindow("B", leaf_id);
    u.dockBuilderDockWindow("C", leaf_id);

    // Pre-condition: order is A, B, C.
    const leaf: *DockNode.LeafData = &ctx.dock.lookup(leaf_id).?.leaf.?;
    try expectEqual(@as(usize, 3), leaf.window_ids.items.len);
    const a_wid: Id = leaf.window_ids.items[0];
    const b_wid: Id = leaf.window_ids.items[1];
    const c_wid: Id = leaf.window_ids.items[2];

    // Simulate: user is dragging tab A (idx 0). Cursor over
    // tab C's horizontal slot (idx 2), still inside the strip
    // vertically.
    ctx.active_id = hashStr(a_wid, "__tab_drag");
    ctx.active_id_press_screen = .{ 50, 10 };
    ctx.input.mouse_pos = .{ 250, 10 }; // tab_w = 100; slot 2 spans 200-300
    ctx.input.mouse_left_down = true;

    ctx.current_draw_list = &ctx.foreground_dl;
    renderDockLeafTabBars(&ctx, leaf_id);

    // After reorder: A should now be at idx 2.
    try expectEqual(@as(usize, 3), leaf.window_ids.items.len);
    try expectEqual(b_wid, leaf.window_ids.items[0]);
    try expectEqual(c_wid, leaf.window_ids.items[1]);
    try expectEqual(a_wid, leaf.window_ids.items[2]);
}

