test "5.5j: drag pulled Y > DETACH_Y_THRESHOLD out of strip → detach" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    ctx.dock.lookup(leaf_id).?.pos = .{ 0, 0 };
    ctx.dock.lookup(leaf_id).?.size = .{ 300, 200 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    _ = findOrCreateWindow(&ctx, "A", .{});
    _ = findOrCreateWindow(&ctx, "B", .{});
    u.dockBuilderDockWindow("A", leaf_id);
    u.dockBuilderDockWindow("B", leaf_id);

    const leaf: *DockNode.LeafData = &ctx.dock.lookup(leaf_id).?.leaf.?;
    const a_wid: Id = leaf.window_ids.items[0];

    // Dragging A. Cursor at Y=80 - well below the title-bar
    // strip (height ≈ 26 px at default style.font_size=16).
    // Should detach.
    ctx.active_id = hashStr(a_wid, "__tab_drag");
    ctx.active_id_press_screen = .{ 50, 10 };
    ctx.input.mouse_pos = .{ 50, 80 };
    ctx.input.mouse_left_down = true;

    ctx.current_draw_list = &ctx.foreground_dl;
    renderDockLeafTabBars(&ctx, leaf_id);

    // A should be undocked now.
    const a_win: *Window = ctx.windows.get(a_wid).?;
    try expectEqual(@as(?Id, null), a_win.dock_node_id);
    try expectEqual(@as(?Id, a_wid), ctx.dock.dragging_window);
    // Leaf collapsed to just B.
    try expectEqual(@as(usize, 1), leaf.window_ids.items.len);
}

test "5.5j: small Y excursion within dead zone → no detach, no reorder" {
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u = Ui{ .ctx = &ctx };

    const leaf_id: Id = try ctx.dock.createNode(ctx.gpa, null, .{ .leaf = {} });
    ctx.dock.lookup(leaf_id).?.pos = .{ 0, 0 };
    ctx.dock.lookup(leaf_id).?.size = .{ 300, 200 };
    try ctx.dock.dockspaces_this_frame.append(ctx.gpa, leaf_id);

    _ = findOrCreateWindow(&ctx, "A", .{});
    _ = findOrCreateWindow(&ctx, "B", .{});
    u.dockBuilderDockWindow("A", leaf_id);
    u.dockBuilderDockWindow("B", leaf_id);

    const leaf: *DockNode.LeafData = &ctx.dock.lookup(leaf_id).?.leaf.?;
    const a_wid: Id = leaf.window_ids.items[0];

    // Cursor just below the strip's bottom edge - outside the
    // reorder slack but inside the detach dead zone.
    // Strip is at Y [0, ~26]; slack adds 4 px so reorder ends
    // at Y=30. Detach threshold is 16 px past strip bottom,
    // so detach starts at Y=42. Y=35 is dead zone.
    ctx.active_id = hashStr(a_wid, "__tab_drag");
    ctx.active_id_press_screen = .{ 50, 10 };
    ctx.input.mouse_pos = .{ 50, 35 };
    ctx.input.mouse_left_down = true;

    ctx.current_draw_list = &ctx.foreground_dl;
    renderDockLeafTabBars(&ctx, leaf_id);

    // A should still be docked; no reorder.
    const a_win: *Window = ctx.windows.get(a_wid).?;
    try expectEqual(@as(?Id, leaf_id), a_win.dock_node_id);
    try expectEqual(a_wid, leaf.window_ids.items[0]);
}

// ============================================================================
// Dock layer (inlined from former src/ui_dock.zig)
// ============================================================================
//

// What this section owns: the dock tree data model and the
// pure-CPU operations that mutate it. No drawing, no input
// handling — those live alongside other widget code earlier in
// this file (dockSpace widget, drag-to-dock targets, splitter
// drag, docked-window rendering all reside in the main widget
// section above).
//

// History: this content was its own file (`src/ui_dock.zig`) from
// the 5.5a-5.5g arc that built the docking feature. Inlined back
// here — keeping it separate cost ongoing navigation
// for thin benefit, since the dock layer and the widget layer
// touch each other constantly.
//

// The model, briefly:
//   - A `DockNode` is either a SPLIT (two children + axis +
//     ratio) or a LEAF (a list of window IDs + a "selected"
//     pointer for the tab bar). Never both, never neither.
//     Encoded as two optional fields where exactly one is set.
//   - A `DockContext` owns the node pool, keyed by `Id`. Nodes
//     reference children by ID (not pointer) so the pool can
//     reallocate the underlying HashMap without invalidating
//     references.
//   - Tree mutation goes through `splitNode`, `dockWindow`,
//     `undockWindow`, `removeNode`. Each maintains the
//     invariant that a SPLIT has two non-null child IDs that
//     exist in the pool; a LEAF has a possibly-empty window
//     list; and each non-root node has a parent_id resolving to
//     a SPLIT containing this node's id in its child_ids.
//

// What this section deliberately doesn't do (delegated to widget
// code above): drag-drop hit-testing, visual rendering, and
// persistence integration (which lives in `src/ui_persistence.zig`).
// The user-facing API is `dockBuilder*` exposed on the `Ui`
// handle earlier in this file.
// ============================================================================

// ============================================================================
// SECTION 1 - Enums + small types
// ============================================================================

/// Split orientation. A horizontal split divides space along the
/// horizontal axis, putting children side-by-side; a vertical split
/// stacks them top/bottom. Matches imgui's `ImGuiDir_*` mapping
/// for the two non-degenerate cases.
pub const SplitAxis = enum(u8) {
    /// Children sit left/right of each other; the boundary is a
    /// vertical line.
    horizontal,
    /// Children sit above/below each other; the boundary is a
    /// horizontal line.
    vertical,
};

/// Dock target direction for drag-drop. Center = tab into the
/// target leaf; the four edges create a new split with the dragged
/// window on that side. Used by `DockRequest.dock_as_split` and
/// the future drag-target zone visualization.
pub const Dir = enum(u8) {
    center,
    top,
    right,
    bottom,
    left,

    /// True for the four edge directions - useful for "split or
    /// tab" branches at call sites.
    pub fn isEdge(self: Dir) bool {
        return self != .center;
    }

    /// The split axis implied by an edge direction. Top/bottom
    /// → vertical (stacked). Left/right → horizontal (side-by-side).
    /// Center isn't an edge - calling `splitAxis(.center)` is a
    /// programmer error; we return horizontal as a fallback rather
    /// than panicking so misuse degrades to wrong-but-not-crashing.
    pub fn splitAxis(self: Dir) SplitAxis {
        return switch (self) {
            .top, .bottom => .vertical,
            .left, .right => .horizontal,
            .center => .horizontal,
        };
    }

    /// True when the dragged window should become the FIRST child
    /// (top of a vertical split, or left of a horizontal one).
    /// False for bottom/right. Determines child ordering in
    /// `splitNode`.
    pub fn isFirstChild(self: Dir) bool {
        return switch (self) {
            .top, .left => true,
            .bottom, .right => false,
            .center => true,
        };
    }
};

/// Default split ratio when one side has no size preference.
/// 0.5 = 50/50. Used by `splitNode` if `ratio` is undefined.
pub const default_split_ratio: f32 = 0.5;

// ============================================================================
// SECTION 2 - DockNode
// ============================================================================

/// A node in the dock tree. Lives in `DockContext.nodes`,
/// referenced everywhere else by `Id`.
/// Invariants:
///   - Exactly one of `split` and `leaf` is non-null. A SPLIT
///     node has children; a LEAF holds windows. Empty leaves are
///     allowed (the user closed all docked windows in this slot);
///     empty splits are not (a split with one or zero children
///     should be collapsed away by `collapse`).
///   - `parent_id == null` iff this node is the root of a
///     dockspace.
///   - For a SPLIT, both `child_ids` exist in `DockContext.nodes`
///     and their `parent_id` resolves back to this node.
pub const DockNode = struct {
    id: Id,
    parent_id: ?Id = null,

    /// Computed rect - top-left corner + outer dimensions in
    /// screen pixels. Refreshed each frame by `layout` based on
    /// the dockspace's rect and the cumulative split ratios.
    /// Holds the previous frame's value between layouts; widgets
    /// can read it.
    pos: Vec2 = .{ 0, 0 },
    size: Vec2 = .{ 0, 0 },

    /// SPLIT data, null for leaves.
    split: ?SplitData = null,
    /// LEAF data, null for splits.
    leaf: ?LeafData = null,

    /// per-node flags constraining behavior.
    /// Flat packed struct, no Shared/Local/Local-in-Windows tier
    /// system imgui has - JUSTIFIED simplification. See
    /// `DockNodeFlags` doc.
    flags: DockNodeFlags = .{},

    /// Per-node generation counter - incremented on every mutation
    /// (split, dock, undock, ratio change). Used by callers that
    /// cache derived state to detect "did anything change since
    /// last frame". Wrapping is fine; collisions across many
    /// thousands of frames don't break anything (the cache
    /// invalidates on the wrong frame at worst).
    generation: u32 = 0,

    pub const SplitData = struct {
        axis: SplitAxis,
        /// Fraction of available space allocated to the FIRST
        /// child (top or left). Clamped to `[min_ratio,
        /// 1 - min_ratio]` so neither child can collapse to zero.
        /// Used when neither child has a `size_ref` lock.
        ratio: f32 = default_split_ratio,
        /// Two children - first is top/left, second is bottom/right.
        /// Both must always be valid IDs in the pool.
        child_ids: [2]Id,
        /// optional pixel-locked sizes per
        /// child. `null` means "follow `ratio`"; non-null means
        /// "lock this child at this many pixels along the split
        /// axis". Exactly one element should be non-null at a
        /// time - locking both makes the layout over-constrained
        /// (current behavior: falls back to ratio if both are
        /// non-null). Lighter version of imgui's per-node
        /// `SizeRef[axis]` field.
        /// Pairs with `DockNodeFlags.is_central` for "fixed-width
        /// left panel + central area absorbs remainder" UX. See
        /// `dockBuilderSetSizeRef`.
        size_ref: [2]?f32 = .{ null, null },
    };

    pub const LeafData = struct {
        /// Windows currently docked into this leaf. Order is the
        /// tab order (left-to-right in the tab bar). Allocated
        /// through the context's gpa.
        window_ids: ArrayList(Id) = .empty,
        /// Which docked window is currently visible. Should equal
        /// one of the entries in `window_ids` whenever the list is
        /// non-empty. Zero when the leaf is empty.
        selected_window_id: Id = 0,

        pub fn deinit(self: *LeafData, gpa: Allocator) void {
            self.window_ids.deinit(gpa);
        }

        /// Linear scan for a window's index in this leaf. Returns
        /// null if not present. Tab counts in leaves are small
        /// (~3-10 in typical use) so linear is fine - same logic
        /// as `TabBarState.findTab`.
        pub fn indexOf(self: *const LeafData, window_id: Id) ?usize {
            for (self.window_ids.items, 0..) |id, i| {
                if (id == window_id) {
                    return i;
                }
            }
            return null;
        }
    };

    pub fn isSplit(self: *const DockNode) bool {
        return self.split != null;
    }
    pub fn isLeaf(self: *const DockNode) bool {
        return self.leaf != null;
    }
};

/// Minimum split ratio. Below this, the side becomes too small
/// to drag/click reliably. Splitter drag clamps to
/// `[min_ratio, 1 - min_ratio]`.
pub const min_ratio: f32 = 0.05;

// ============================================================================
// SECTION 3 - DockRequest
// ============================================================================

// ============================================================================
// SECTION 4 - DockContext
// ============================================================================

// ============================================================================
// SECTION 5 - Tree mutation primitives
// ============================================================================

/// Split `target_id` along `dir`, creating two new child leaves.
/// The original `target` (which must be a leaf) is turned into a
/// SPLIT; its windows move into the child that's on the OPPOSITE
/// side of `dir` (so dragging a window to the right of a leaf
/// puts the existing content on the left). Returns the two new
/// child IDs as `{a, b}` where `a` is the first/top/left child
/// and `b` is the second/bottom/right child.
/// `ratio` controls space allocated to the first child (top/left);
/// passing `default_split_ratio` gives a 50/50 split.
/// Errors:
///   - InvalidTarget if `target_id` doesn't refer to a leaf.
///   - OutOfMemory if node allocation fails.
pub const SplitError = error{InvalidTarget} || Allocator.Error;

pub fn splitNode(
    ctx: *DockContext,
    gpa: Allocator,
    target_id: Id,
    dir: Dir,
    ratio: f32,
) SplitError!SplitResult {
    if (dir == .center) {
        return error.InvalidTarget;
    }
    const target: *DockNode = ctx.lookup(target_id) orelse return error.InvalidTarget;
    if (!target.isLeaf()) {
        return error.InvalidTarget;
    }

    // Capture the leaf's windows; they'll go into one of the new
    // children (the one OPPOSITE to `dir`).
    const existing: DockNode.LeafData = target.leaf.?;
    target.leaf = null; // we're taking ownership of `existing`'s list

    const child_a: Id = try ctx.createLeaf(gpa, target_id);
    const child_b: Id = try ctx.createLeaf(gpa, target_id);

    // Decide which child gets the existing windows. Convention:
    // dragging to.top puts the new content ABOVE existing
    // existing windows go to child_b (bottom). Symmetrically for
    // .bottom/.left/.right. See `Dir.isFirstChild`.
    const existing_goes_to_a: bool = !dir.isFirstChild();
    const recipient_id: Id = if (existing_goes_to_a) child_a else child_b;
    if (ctx.lookup(recipient_id)) |recip| {
        recip.leaf.?.window_ids = existing.window_ids;
        recip.leaf.?.selected_window_id = existing.selected_window_id;
        // transfer leaf-affinity flags from the
        // original (now-promoted-to-split) target to the
        // inheritor child. The "fresh" child keeps defaults.
        // Mirrors imgui:20204 (DockNodeTreeSplit) using
        // `LocalFlagsTransferMask_` - but we transfer ALL
        // matching bits to the inheritor and clear them on the
        // parent (which becomes a split node and shouldn't carry
        // leaf-only flags anymore).
        recip.flags = target.flags.intersect(DockNodeFlags.transfer_mask);
    }
    // Parent (now a split node) clears the transferable flags;
    // keeps tree-structural ones (is_dockspace, passthru_central).
    target.flags = target.flags.except(DockNodeFlags.transfer_mask);

    const clamped_ratio: f32 = clamp(ratio, min_ratio, 1.0 - min_ratio);
    target.split = .{
        .axis = dir.splitAxis(),
        .ratio = clamped_ratio,
        .child_ids = .{ child_a, child_b },
    };
    target.generation +%= 1;

    return .{ .a = child_a, .b = child_b };
}

// ============================================================================
// SECTION 6 - Layout
// ============================================================================

/// Get the final rect of `node_id` after the last layout pass.
/// Returns a zero-sized rect at the origin if the id doesn't
/// exist. Read-only helper for the future docked-window
/// rendering path.
pub fn nodeRect(ctx: *const DockContext, node_id: Id) Rectangle {
    const node: *DockNode = ctx.lookup(node_id) orelse return .{ .x = 0, .y = 0, .width = 0, .height = 0 };
    return .{
        .x = node.pos[0],
        .y = node.pos[1],
        .width = node.size[0],
        .height = node.size[1],
    };
}

// ============================================================================
// SECTION 7 - Request processing
// ============================================================================

/// Apply all queued requests in submission order. Called at a
/// well-defined point in the frame (before window submission, after
/// drag-drop releases have been observed). Drains
/// `pending_requests`.
pub fn processRequests(ctx: *DockContext, gpa: Allocator) Allocator.Error!void {
    // Drain into a local snapshot so requests enqueued during
    // processing (rare but possible) wait until next frame.
    const reqs = try gpa.dupe(DockRequest, ctx.pending_requests.items);
    defer gpa.free(reqs);
    ctx.pending_requests.clearRetainingCapacity();

    for (reqs) |req| {
        switch (req) {
            .dock_as_tab => |r| {
                _ = dockWindowAsTab(ctx, gpa, r.target_node, r.source_window) catch
                    assertUnreachable(@src(), "OOM", .{});
            },
            .dock_as_split => |r| {
                if (r.dir == .center) {
                    _ = dockWindowAsTab(ctx, gpa, r.target_node, r.source_window) catch
                        assertUnreachable(@src(), "OOM", .{});
                } else {
                    const result: SplitResult = splitNode(
                        ctx,
                        gpa,
                        r.target_node,
                        r.dir,
                        default_split_ratio,
                    ) catch continue;
                    const target_child: Id = if (r.dir.isFirstChild()) result.a else result.b;
                    _ = dockWindowAsTab(ctx, gpa, target_child, r.source_window) catch
                        assertUnreachable(@src(), "OOM", .{});
                }
            },
            .undock => |r| {
                _ = undockWindow(ctx, gpa, r.source_window);
            },
            .split => |r| {
                _ = splitNode(ctx, gpa, r.target_node, r.dir, r.ratio) catch continue;
            },
        }
    }
}

// ============================================================================
// SECTION 8 - Tests
// ============================================================================

const testing = std.testing;

test "createLeaf + lookup: roundtrip" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const id: Id = try ctx.createLeaf(gpa, null);
    const node: *DockNode = ctx.lookup(id) orelse return error.LookupFailed;
    try testing.expect(node.isLeaf());
    try testing.expect(!node.isSplit());
    try testing.expectEqual(@as(?Id, null), node.parent_id);
}

