test "undockWindow: empty leaf with parent split collapses, sibling absorbs parent" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const root: Id = try ctx.createLeaf(gpa, null);
    try dockWindowAsTab(&ctx, gpa, root, 1);
    try dockWindowAsTab(&ctx, gpa, root, 2);

    const split_result: SplitResult = try splitNode(&ctx, gpa, root, .right, 0.5);
    try dockWindowAsTab(&ctx, gpa, split_result.b, 3); // put window 3 on right side

    // Now root is a SPLIT, child_a holds windows 1,2, child_b holds 3.
    // Undock all from child_b - leaf goes empty, parent collapses,
    // root becomes a leaf again containing windows 1 and 2.
    _ = undockWindow(&ctx, gpa, 3);

    const root_node: *DockNode = ctx.lookup(root).?;
    try testing.expect(root_node.isLeaf());
    try testing.expectEqual(@as(usize, 2), root_node.leaf.?.window_ids.items.len);
    // The two child nodes should be freed.
    try testing.expectEqual(@as(?*DockNode, null), ctx.lookup(split_result.a));
    try testing.expectEqual(@as(?*DockNode, null), ctx.lookup(split_result.b));
}

test "9.1: collapse carries the surviving sibling's flags up" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const root: Id = try ctx.createLeaf(gpa, null);
    try dockWindowAsTab(&ctx, gpa, root, 1);
    const sr: SplitResult = try splitNode(&ctx, gpa, root, .right, 0.3);
    // .right keeps existing window 1 in child_a; put window 2 in child_b.
    try dockWindowAsTab(&ctx, gpa, sr.b, 2);
    // The survivor (child_b) is the central, non-resizable node.
    ctx.lookup(sr.b).?.flags.is_central = true;
    ctx.lookup(sr.b).?.flags.no_resize = true;

    // Undock window 1 -> child_a empties -> collapses -> child_b absorbs root.
    _ = undockWindow(&ctx, gpa, 1);

    const root_node: *DockNode = ctx.lookup(root).?;
    try testing.expect(root_node.isLeaf());
    try testing.expectEqual(@as(usize, 1), root_node.leaf.?.window_ids.items.len);
    // The #9.1 fix: the survivor's leaf-affinity flags must carry up. Before the
    // fix these were silently dropped (parent kept its own split-node flags).
    try testing.expect(root_node.flags.is_central);
    try testing.expect(root_node.flags.no_resize);
}

