test "layoutSubtree: horizontal split divides width by ratio with gap" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const root: Id = try ctx.createLeaf(gpa, null);
    const split_result: SplitResult = try splitNode(&ctx, gpa, root, .right, 0.3);
    layoutSubtree(&ctx, root, .{ 0, 0 }, .{ 1000, 500 });

    // splitter_size (4 px) is reserved between children; the
    // remaining 996 px is divided 30/70.
    const avail: f32 = 1000 - splitter_size;
    const left: Rectangle = nodeRect(&ctx, split_result.a);
    const right: Rectangle = nodeRect(&ctx, split_result.b);
    try testing.expectApproxEqAbs(avail * 0.3, left.width, 0.001);
    try testing.expectApproxEqAbs(avail * 0.7, right.width, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 0), left.x, 0.001);
    try testing.expectApproxEqAbs(left.width + splitter_size, right.x, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 500), left.height, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 500), right.height, 0.001);
}

test "layoutSubtree: vertical split divides height by ratio with gap" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const root: Id = try ctx.createLeaf(gpa, null);
    const split_result: SplitResult = try splitNode(&ctx, gpa, root, .bottom, 0.4);
    layoutSubtree(&ctx, root, .{ 0, 0 }, .{ 800, 600 });

    const avail: f32 = 600 - splitter_size;
    const top: Rectangle = nodeRect(&ctx, split_result.a);
    const bottom: Rectangle = nodeRect(&ctx, split_result.b);
    try testing.expectApproxEqAbs(avail * 0.4, top.height, 0.001);
    try testing.expectApproxEqAbs(avail * 0.6, bottom.height, 0.001);
    try testing.expectApproxEqAbs(top.height + splitter_size, bottom.y, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 800), top.width, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 800), bottom.width, 0.001);
}

test "layoutSubtree: nested splits recurse correctly" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    // Build:
    //   root (vertical split, ratio 0.5)
    //     ├ a (top half)
    //     └ b (bottom half)
    //         └ split into [c (left), d (right)] horizontally at 0.5
    const root: Id = try ctx.createLeaf(gpa, null);
    const r1: SplitResult = try splitNode(&ctx, gpa, root, .bottom, 0.5);
    const r2: SplitResult = try splitNode(&ctx, gpa, r1.b, .right, 0.5);

    layoutSubtree(&ctx, root, .{ 0, 0 }, .{ 1000, 1000 });

    // Each split eats splitter_size; outer split halves
    // (1000 - 4)/2 = 498. Inner split inside the bottom 498:
    // halves (1000 - 4)/2 = 498 horizontally.
    const outer_half: f32 = (1000 - splitter_size) * 0.5;
    const inner_half: f32 = (1000 - splitter_size) * 0.5;
    try testing.expectApproxEqAbs(outer_half, nodeRect(&ctx, r1.a).height, 0.001);
    try testing.expectApproxEqAbs(inner_half, nodeRect(&ctx, r2.a).width, 0.001);
    try testing.expectApproxEqAbs(outer_half, nodeRect(&ctx, r2.a).height, 0.001);
    try testing.expectApproxEqAbs(inner_half, nodeRect(&ctx, r2.b).width, 0.001);
}

