test "generation: bumps on mutation" {
    const gpa: Allocator = testing.allocator;
    var ctx: DockContext = .{};
    defer ctx.deinit(gpa);

    const leaf: Id = try ctx.createLeaf(gpa, null);
    const node: *DockNode = ctx.lookup(leaf).?;
    const g0: u32 = node.generation;

    try dockWindowAsTab(&ctx, gpa, leaf, 1);
    try testing.expect(node.generation != g0);

    const g1: u32 = node.generation;
    try dockWindowAsTab(&ctx, gpa, leaf, 1); // dup - promotes selection but no new tab
    // Generation only bumps on tree structure mutations, not on
    // re-selection of an existing tab. This is fine; cachers
    // re-check selection separately.
    try testing.expectEqual(g1, node.generation);
}

// ============================================================================
// Persistence layer (inlined from former src/ui_persistence.zig)
// ============================================================================
//

// What this section owns: serialization + deserialization of
// UiContext state to/from zon text. The schema-versioned shape
// (`PersistedState`) decouples the in-memory representation from
// the on-the-wire format; missing optional fields take their
// defaults so additive schema changes don't bump the version.
//

// History: this content was its own file (`src/ui_persistence.zig`)
// from the persistence arc. Inlined back here — same
// reasoning as ui_dock: the dense cross-references to
// Window, DockContext, Style, TabBarState made the file boundary
// pure navigation cost.
//

// Responsibilities:
//   - `PersistedWindow` / `PersistedState` — on-the-wire shape
//   - `serialize(gpa, ctx)` — walk windows, build snapshot, zon-stringify
//   - `apply(gpa, ctx, text)` — parse zon, populate
//     `ctx.pending_persistence` for next-frame consumption
//   - `takeFor(ctx, title)` — pop a pending entry on first
//     `openWindow` for that name
//

// Storage layer (the JS / localStorage half) is NOT in this section.
// This content is pure CPU + std.zon, fully host-testable. The JS
// externs that move bytes between zimr and `localStorage` live
// alongside other runtime input/clipboard externs.
//

// Schema versioning policy:
//   - Every payload starts with `.version = N`
//   - On non-additive change (rename, remove, semantic shift) bump
//     `current_version`; mismatched payloads are silently discarded
//   - Additive changes (new optional fields with defaults) need no
//     version bump — zon parser skips unknown keys with
//     `.ignore_unknown_fields = true` and defaults fill the rest
// ============================================================================

// ============================================================================
// SECTION 1 - Schema
// ============================================================================

inline fn colorToBytes(c: Color) [4]u8 {
    return .{ c.r, c.g, c.b, c.a };
}

inline fn bytesToColor(b: [4]u8) Color {
    return .{ .r = b[0], .g = b[1], .b = b[2], .a = b[3] };
}

/// On-the-wire shape for `Style`. Mirrors every Color + numeric
/// field on `Style` (skips `font: ?*const Font` — pointers can't
/// round-trip a localStorage save). Optional on `PersistedState`;
/// apps that don't theme can leave it null and save no bytes.
///
/// Each `Color` is stored as `[4]u8` (r, g, b, a) for compact.zon
/// output — `Color = struct { r: u8, g: u8, b: u8, a: u8 }` would
/// also work but produces a much chattier serialization.
///
/// Versioning: when a new color slot is added to `Style`, give it
/// a default in `PersistedStyle.fromStyle` so old saves load
/// cleanly. The opposite direction (loading a NEW save into OLD
/// code) is handled by std.zon ignoring unknown fields when
/// `.allow_unknown = true` is passed to `parseFromSlice`.
pub const PersistedStyle = struct {
    // ---- Colors (27 slots — order matches Style decl)
    text: [4]u8 = .{ 230, 230, 230, 255 },
    text_disabled: [4]u8 = .{ 128, 128, 128, 255 },
    window_bg: [4]u8 = .{ 15, 15, 15, 240 },
    border: [4]u8 = .{ 110, 110, 128, 128 },
    title_bg: [4]u8 = .{ 10, 10, 10, 255 },
    title_bg_active: [4]u8 = .{ 41, 74, 122, 255 },
    button: [4]u8 = .{ 66, 150, 250, 102 },
    button_hovered: [4]u8 = .{ 66, 150, 250, 255 },
    button_active: [4]u8 = .{ 15, 135, 250, 255 },
    frame_bg: [4]u8 = .{ 41, 74, 122, 138 },
    frame_bg_hovered: [4]u8 = .{ 66, 150, 250, 102 },
    frame_bg_active: [4]u8 = .{ 66, 150, 250, 171 },
    scrollbar_bg: [4]u8 = .{ 5, 5, 5, 135 },
    scrollbar_grab: [4]u8 = .{ 79, 79, 79, 255 },
    scrollbar_grab_hovered: [4]u8 = .{ 105, 105, 105, 255 },
    scrollbar_grab_active: [4]u8 = .{ 130, 130, 130, 255 },
    popup_bg: [4]u8 = .{ 20, 20, 20, 240 },
    modal_dim_bg: [4]u8 = .{ 35, 40, 50, 88 },
    menu_bar_bg: [4]u8 = .{ 30, 30, 35, 255 },
    menu_hovered: [4]u8 = .{ 66, 150, 250, 180 },
    tab: [4]u8 = .{ 46, 89, 148, 219 },
    tab_hovered: [4]u8 = .{ 66, 150, 250, 204 },
    tab_active: [4]u8 = .{ 51, 105, 173, 255 },
    tab_separator: [4]u8 = .{ 110, 110, 130, 255 },
    table_row_bg: [4]u8 = .{ 0, 0, 0, 0 },
    table_row_bg_alt: [4]u8 = .{ 255, 255, 255, 15 },
    text_link: [4]u8 = .{ 102, 159, 218, 255 },
    text_link_hovered: [4]u8 = .{ 140, 195, 240, 255 },
    text_link_underline: [4]u8 = .{ 80, 130, 180, 255 },

    // ---- Numeric (Vec2 written as [2]f32; scalars as their native type)
    window_padding: [2]f32 = .{ 8, 8 },
    frame_padding: [2]f32 = .{ 4, 3 },
    item_spacing: [2]f32 = .{ 8, 4 },
    title_bar_height: f32 = 22,
    menu_bar_height: f32 = 22,
    disabled_alpha: f32 = 0.6,
    font_size: f32 = 10,
    font_spacing: f32 = 0,
    line_spacing: i32 = 2,

    /// Capture a runtime `Style` into a serialization-ready form.
    /// Drops the `font` pointer (can't round-trip).
    pub fn fromStyle(s: *const Style) PersistedStyle {
        return .{
            .text = colorToBytes(s.text),
            .text_disabled = colorToBytes(s.text_disabled),
            .window_bg = colorToBytes(s.window_bg),
            .border = colorToBytes(s.border),
            .title_bg = colorToBytes(s.title_bg),
            .title_bg_active = colorToBytes(s.title_bg_active),
            .button = colorToBytes(s.button),
            .button_hovered = colorToBytes(s.button_hovered),
            .button_active = colorToBytes(s.button_active),
            .frame_bg = colorToBytes(s.frame_bg),
            .frame_bg_hovered = colorToBytes(s.frame_bg_hovered),
            .frame_bg_active = colorToBytes(s.frame_bg_active),
            .scrollbar_bg = colorToBytes(s.scrollbar_bg),
            .scrollbar_grab = colorToBytes(s.scrollbar_grab),
            .scrollbar_grab_hovered = colorToBytes(s.scrollbar_grab_hovered),
            .scrollbar_grab_active = colorToBytes(s.scrollbar_grab_active),
            .popup_bg = colorToBytes(s.popup_bg),
            .modal_dim_bg = colorToBytes(s.modal_dim_bg),
            .menu_bar_bg = colorToBytes(s.menu_bar_bg),
            .menu_hovered = colorToBytes(s.menu_hovered),
            .tab = colorToBytes(s.tab),
            .tab_hovered = colorToBytes(s.tab_hovered),
            .tab_active = colorToBytes(s.tab_active),
            .tab_separator = colorToBytes(s.tab_separator),
            .table_row_bg = colorToBytes(s.table_row_bg),
            .table_row_bg_alt = colorToBytes(s.table_row_bg_alt),
            .text_link = colorToBytes(s.text_link),
            .text_link_hovered = colorToBytes(s.text_link_hovered),
            .text_link_underline = colorToBytes(s.text_link_underline),
            .window_padding = .{ s.window_padding[0], s.window_padding[1] },
            .frame_padding = .{ s.frame_padding[0], s.frame_padding[1] },
            .item_spacing = .{ s.item_spacing[0], s.item_spacing[1] },
            .title_bar_height = s.title_bar_height,
            .menu_bar_height = s.menu_bar_height,
            .disabled_alpha = s.disabled_alpha,
            .font_size = s.font_size,
            .font_spacing = s.font_spacing,
            .line_spacing = s.line_spacing,
        };
    }

    /// Apply this persisted form back onto `target`. Preserves the
    /// caller's `font: ?*const Font` — the pointer cannot round-trip,
    /// so the caller's binding wins.
    pub fn applyTo(self: PersistedStyle, target: *Style) void {
        target.text = bytesToColor(self.text);
        target.text_disabled = bytesToColor(self.text_disabled);
        target.window_bg = bytesToColor(self.window_bg);
        target.border = bytesToColor(self.border);
        target.title_bg = bytesToColor(self.title_bg);
        target.title_bg_active = bytesToColor(self.title_bg_active);
        target.button = bytesToColor(self.button);
        target.button_hovered = bytesToColor(self.button_hovered);
        target.button_active = bytesToColor(self.button_active);
        target.frame_bg = bytesToColor(self.frame_bg);
        target.frame_bg_hovered = bytesToColor(self.frame_bg_hovered);
        target.frame_bg_active = bytesToColor(self.frame_bg_active);
        target.scrollbar_bg = bytesToColor(self.scrollbar_bg);
        target.scrollbar_grab = bytesToColor(self.scrollbar_grab);
        target.scrollbar_grab_hovered = bytesToColor(self.scrollbar_grab_hovered);
        target.scrollbar_grab_active = bytesToColor(self.scrollbar_grab_active);
        target.popup_bg = bytesToColor(self.popup_bg);
        target.modal_dim_bg = bytesToColor(self.modal_dim_bg);
        target.menu_bar_bg = bytesToColor(self.menu_bar_bg);
        target.menu_hovered = bytesToColor(self.menu_hovered);
        target.tab = bytesToColor(self.tab);
        target.tab_hovered = bytesToColor(self.tab_hovered);
        target.tab_active = bytesToColor(self.tab_active);
        target.tab_separator = bytesToColor(self.tab_separator);
        target.table_row_bg = bytesToColor(self.table_row_bg);
        target.table_row_bg_alt = bytesToColor(self.table_row_bg_alt);
        target.text_link = bytesToColor(self.text_link);
        target.text_link_hovered = bytesToColor(self.text_link_hovered);
        target.text_link_underline = bytesToColor(self.text_link_underline);
        target.window_padding = .{ self.window_padding[0], self.window_padding[1] };
        target.frame_padding = .{ self.frame_padding[0], self.frame_padding[1] };
        target.item_spacing = .{ self.item_spacing[0], self.item_spacing[1] };
        target.title_bar_height = self.title_bar_height;
        target.menu_bar_height = self.menu_bar_height;
        target.disabled_alpha = self.disabled_alpha;
        target.font_size = self.font_size;
        target.font_spacing = self.font_spacing;
        target.line_spacing = self.line_spacing;
        // target.font: caller-owned pointer; deliberately not touched.
    }
};

/// True when every field of `s` matches `Style.dark_default`.
/// Used by `serialize` to skip emitting a `PersistedStyle` block
/// for apps that haven't themed. Compares the Color + numeric
/// fields only; `font` is excluded (pointers compare by address
/// which is unstable across rebuilds).
fn styleIsDefault(s: *const Style) bool {
    const d: Style = Style.dark_default;
    return meta.eql(s.text, d.text) and
        meta.eql(s.text_disabled, d.text_disabled) and
        meta.eql(s.window_bg, d.window_bg) and
        meta.eql(s.border, d.border) and
        meta.eql(s.title_bg, d.title_bg) and
        meta.eql(s.title_bg_active, d.title_bg_active) and
        meta.eql(s.button, d.button) and
        meta.eql(s.button_hovered, d.button_hovered) and
        meta.eql(s.button_active, d.button_active) and
        meta.eql(s.frame_bg, d.frame_bg) and
        meta.eql(s.frame_bg_hovered, d.frame_bg_hovered) and
        meta.eql(s.frame_bg_active, d.frame_bg_active) and
        meta.eql(s.scrollbar_bg, d.scrollbar_bg) and
        meta.eql(s.scrollbar_grab, d.scrollbar_grab) and
        meta.eql(s.scrollbar_grab_hovered, d.scrollbar_grab_hovered) and
        meta.eql(s.scrollbar_grab_active, d.scrollbar_grab_active) and
        meta.eql(s.popup_bg, d.popup_bg) and
        meta.eql(s.modal_dim_bg, d.modal_dim_bg) and
        meta.eql(s.menu_bar_bg, d.menu_bar_bg) and
        meta.eql(s.menu_hovered, d.menu_hovered) and
        meta.eql(s.tab, d.tab) and
        meta.eql(s.tab_hovered, d.tab_hovered) and
        meta.eql(s.tab_active, d.tab_active) and
        meta.eql(s.tab_separator, d.tab_separator) and
        meta.eql(s.table_row_bg, d.table_row_bg) and
        meta.eql(s.table_row_bg_alt, d.table_row_bg_alt) and
        meta.eql(s.text_link, d.text_link) and
        meta.eql(s.text_link_hovered, d.text_link_hovered) and
        meta.eql(s.text_link_underline, d.text_link_underline) and
        meta.eql(s.window_padding, d.window_padding) and
        meta.eql(s.frame_padding, d.frame_padding) and
        meta.eql(s.item_spacing, d.item_spacing) and
        s.title_bar_height == d.title_bar_height and
        s.menu_bar_height == d.menu_bar_height and
        s.disabled_alpha == d.disabled_alpha and
        s.font_size == d.font_size and
        s.font_spacing == d.font_spacing and
        s.line_spacing == d.line_spacing;
}

/// The full persisted payload - a versioned envelope around an
/// array of `PersistedWindow`. Sized to fit comfortably in
/// localStorage (a few KB even for dozens of windows).
/// One persistable type's payload. `type_name` is `@typeName(T)`
/// from the putState call site, captured at first-persist time.
/// `payload` is a pre-stringified zon array of `{id, value}`
/// tuples — pre-stringified because each T is type-erased at
/// this layer and we can't put heterogeneous values in one slice.
/// The slot's `deserialize_fn` knows how to re-parse the array
/// back into the typed inner map.
pub const PersistedExtEntry = struct {
    type_name: []const u8 = "",
    payload: []const u8 = "",
};

pub const PersistedState = struct {
    version: u32 = current_version,
    windows: []const PersistedWindow = &.{},
    /// dock tree state. Empty for apps
    /// that don't use docking. Restored on load by walking
    /// the array and re-creating nodes verbatim - see
    /// `tryRestoreDockTree` in `apply`.
    dock_nodes: []const PersistedDockNode = &.{},
    /// User-themed style. Null = "use the in-memory default,
    /// don't override on load." Apps that mutate `ctx.style`
    /// AND set `persistence_key` get their colors saved alongside
    /// window layout; apps that leave `style` at `dark_default`
    /// can leave this null in the payload to save ~600 bytes.
    /// Set by `serialize` when the in-memory style differs from
    /// `Style.dark_default`.
    style: ?PersistedStyle = null,
    /// Per-typed-extension-state slots opted into persistence via
    /// `getOrPutState(T, id,.{.persist = true })`. Empty for
    /// apps that don't use persistable ext state.
    ext_state: []const PersistedExtEntry = &.{},
};

// ============================================================================
// SECTION 2 - Serialization
// ============================================================================

/// Collect tab-bar selections for the window with `window_name`.
/// Caller owns the returned slice (free with `gpa.free`). The
/// returned PersistedTabBar entries borrow into `ctx.tab_bar_state`
/// (str_id and label), valid until the next zon serialize pass.
fn collectTabBarsFor(
    gpa: Allocator,
    ctx: *const UiContext,
    window_name: []const u8,
) Allocator.Error![]PersistedTabBar {
    var out: ArrayList(PersistedTabBar) = .empty;
    errdefer out.deinit(gpa);

    var it: std.AutoHashMapUnmanaged(Id, TabBarState).Iterator = ctx.tab_bar_state.iterator();
    while (it.next()) |entry| {
        const state: *TabBarState = entry.value_ptr;
        // Match by parent window name. Bars whose parent doesn't
        // match (or whose name slot is empty because openTabBar
        // never populated it - shouldn't happen but defensive)
        // are skipped.
        const pname: []const u8 = state.parentWindowName();
        if (pname.len == 0) {
            continue;
        }
        if (!eql(u8, pname, window_name)) {
            continue;
        }
        const sid: []const u8 = state.strId();
        if (sid.len == 0) {
            continue;
        }

        // Find the currently-selected tab's label. If selected_id
        // is 0 (no selection persisted) or doesn't match any tab,
        // emit an empty label - the restore path treats this as
        // "no preference, use first-tab-auto-select".
        // CRITICAL: iterate by pointer. Capturing `t` by value
        // copies the entire TabState (including its inline
        // `label_buf` array) onto the loop stack frame; slicing
        // `t.label_buf[..]` then aliases that stack copy, which
        // dies when the loop iteration ends. Subsequent zon
        // serialize reads dangling memory.
        var label: []const u8 = "";
        for (state.tabs.items) |*t| {
            if (t.id == state.selected_id) {
                label = t.label_buf[0..t.label_len];
                break;
            }
        }
        try out.append(gpa, .{
            .str_id = sid,
            .selected_tab_label = label,
        });
    }
    return try out.toOwnedSlice(gpa);
}

/// Walk `ctx.windows`, build a `PersistedState`, zon-stringify it.
/// Caller owns the returned bytes (free with `gpa.free`).
/// Skips windows whose `last_frame_active` is older than the current
/// frame minus `STALE_FRAMES` (default 60) - keeps the payload free
/// of windows the user has stopped submitting. Tooltip / popup
/// windows (transient) are skipped via `flags.is_child` and other
/// internal flags.
/// Returns an empty `.{}` payload if no eligible windows exist
/// callers shouldn't have to special-case "no state yet".
pub fn serialize(gpa: Allocator, ctx: *const UiContext) ![]u8 {
    // Stale window threshold - frames since last submission past
    // which we drop the window from the persisted state. 60 frames
    // ≈ 1s at 60fps - comfortably more than any single-frame
    // hiccup but conservatively short enough that closed dialogs
    // don't linger forever in storage.
    const STALE_FRAMES: u64 = 60;

    // Build a list of `PersistedWindow` from live state. Allocate
    // into the same gpa - the final stringify reads from it and
    // we free the whole thing before returning.
    var out_windows: ArrayList(PersistedWindow) = .empty;
    defer out_windows.deinit(gpa);

    var it: std.AutoArrayHashMapUnmanaged(Id, *Window).Iterator = ctx.windows.iterator();
    while (it.next()) |entry| {
        const w: *Window = entry.value_ptr.*;
        // Filter: skip windows the user hasn't submitted recently.
        // `last_frame_active` is updated by `openWindow` every
        // frame the title is submitted; the gap is meaningful
        // because the GC pass otherwise leaves dead windows in
        // the map.
        if (ctx.frame_count > w.last_frame_active + STALE_FRAMES) {
            continue;
        }

        // Filter: skip children (those have their own IDs and
        // re-derive position/size from the parent each frame
        // persistence would be wrong). Child detection via the
        // `is_child` flag set by `findOrCreateChildWindow`.
        if (w.flags.is_child) {
            continue;
        }

        // P5.2: explicit caller opt-out. Windows with
        // `no_saved_settings` are excluded from the persistence
        // payload entirely — they were never written. Use for
        // transient inspector windows, debug overlays, or any UI
        // element whose pos/size shouldn't survive sessions.
        if (w.flags.no_saved_settings) {
            continue;
        }

        // (Future: skip popups + tooltips once those flag fields
        // land on `WindowFlags`. Today only `is_child` is wired;
        // popups submit through a separate path that doesn't
        // persist anything, so this filter is sufficient.)

        try out_windows.append(gpa, .{
            .name = w.name_buf[0..w.name_len],
            .pos = .{ w.pos[0], w.pos[1] },
            .size = .{ w.size[0], w.size[1] },
            .scroll_y = w.scroll_y,
            .scroll_x = w.scroll_x,
            .user_resized = w.user_resized,
            .tab_bars = try collectTabBarsFor(gpa, ctx, w.name_buf[0..w.name_len]),
        });
    }

    // collect dock tree nodes. Walk
    // `ctx.dock.nodes`, build a `PersistedDockNode` per entry.
    // For leaves, resolve `window_ids` → names (by reverse-
    // lookup in `ctx.windows`). For splits, copy ratio/axis/
    // size_ref verbatim. Empty array if no docking is in use.
    var out_nodes: ArrayList(PersistedDockNode) = .empty;
    defer {
        // Free the leaf_window_names allocations we built per
        // node. String contents are copied into the.zon
        // output by stringify; we own the slice array here.
        for (out_nodes.items) |pn| {
            if (pn.leaf_window_names.len > 0) {
                gpa.free(pn.leaf_window_names);
            }
        }
        out_nodes.deinit(gpa);
    }
    {
        var dn_it: std.AutoHashMapUnmanaged(Id, *DockNode).Iterator = ctx.dock.nodes.iterator();
        while (dn_it.next()) |entry| {
            const node: *const DockNode = entry.value_ptr.*;
            const flags_bits: u16 = @bitCast(node.flags);
            const parent_id: u32 = node.parent_id orelse 0;
            if (node.split) |s| {
                try out_nodes.append(gpa, .{
                    .id = node.id,
                    .parent_id = parent_id,
                    .flags = flags_bits,
                    .is_split = true,
                    .split_axis = @backingInt(s.axis),
                    .split_ratio = s.ratio,
                    .split_child_a = s.child_ids[0],
                    .split_child_b = s.child_ids[1],
                    .split_size_ref_a = s.size_ref[0] orelse -1,
                    .split_size_ref_b = s.size_ref[1] orelse -1,
                });
            } else if (node.leaf) |leaf| {
                // Resolve window_ids → names. Linear scan over
                // ctx.windows for each id - leaves typically
                // have ≤ ~10 docked windows so the cost is fine.
                var names: ArrayList([]const u8) = .empty;
                errdefer names.deinit(gpa);
                for (leaf.window_ids.items) |wid| {
                    if (ctx.windows.get(wid)) |w| {
                        try names.append(gpa, w.name_buf[0..w.name_len]);
                    }
                }
                const sel_name: []const u8 = blk: {
                    if (leaf.selected_window_id == 0) {
                        break :blk "";
                    }
                    if (ctx.windows.get(leaf.selected_window_id)) |w| {
                        break :blk w.name_buf[0..w.name_len];
                    }
                    break :blk "";
                };
                try out_nodes.append(gpa, .{
                    .id = node.id,
                    .parent_id = parent_id,
                    .flags = flags_bits,
                    .is_split = false,
                    .leaf_window_names = try names.toOwnedSlice(gpa),
                    .leaf_selected_window_name = sel_name,
                });
            }
        }
    }

    // Collect persistable extension state. Walk ext_storage slots
    // with `has_persist == true`, ask each slot's serialize_fn to
    // encode the typed inner map as a zon-text payload. Each
    // payload owns its allocation — they're freed after stringify
    // has copied them into the outer buffer.
    var out_ext: ArrayList(PersistedExtEntry) = .empty;
    defer out_ext.deinit(gpa);
    {
        var es_it: std.AutoHashMapUnmanaged(u64, ExtStorageSlot).Iterator = ctx.ext_storage.iterator();
        while (es_it.next()) |kv| {
            const slot: *ExtStorageSlot = kv.value_ptr;
            if (!slot.has_persist) {
                continue;
            }
            // Both fn ptrs were bound when has_persist was set.
            const ser_fn: SerializeExtFn = slot.serialize_fn orelse continue;
            const text: []u8 = ser_fn(slot.map, gpa) catch continue;
            try out_ext.append(gpa, .{
                .type_name = slot.type_name orelse "",
                .payload = text,
            });
        }
    }
    defer {
        // Free each per-type payload now that out has copied
        // them into the outer buffer.
        for (out_ext.items) |e| gpa.free(e.payload);
    }

    const payload: PersistedState = .{
        .version = current_version,
        .windows = out_windows.items,
        .dock_nodes = out_nodes.items,
        // Style capture: emit only when the in-memory style has
        // diverged from `dark_default`. Comparison is field-level
        // via stdlib's structural equality. When equal, leave
        // `null` to save ~600 bytes per save.
        .style = if (styleIsDefault(&ctx.style))
            null
        else
            PersistedStyle.fromStyle(&ctx.style),
        .ext_state = out_ext.items,
    };

    var out: std.Io.Writer.Allocating = .init(gpa);
    errdefer out.deinit();
    try std.zon.stringify.serialize(payload, .{}, &out.writer);
    // Free the inner tab_bars allocations we built up for each
    // window (the slices are owned by us, the writer just copied
    // their string contents into the output buffer).
    for (out_windows.items) |pw| {
        gpa.free(pw.tab_bars);
    }
    return try out.toOwnedSlice();
}

// ============================================================================
// SECTION 3 - Deserialization + pending-map application
// ============================================================================

/// Reverse-lookup a window by its user-given name. Linear scan
/// over `ctx.windows`; typical window counts are ≤ 50, so cheap.
/// Returns null when no match exists - caller treats as
/// "window not submitted yet; degrade gracefully".
fn findWindowIdByName(ctx: *const UiContext, name: []const u8) ?u32 {
    var it: std.AutoArrayHashMapUnmanaged(Id, *Window).Iterator = ctx.windows.iterator();
    while (it.next()) |entry| {
        const w: *Window = entry.value_ptr.*;
        if (eql(u8, w.name_buf[0..w.name_len], name)) {
            return entry.key_ptr.*;
        }
    }
    return null;
}

/// consume the pending dock tree (if any),
/// rebuilding `ctx.dock` to match. Called by `dockSpace()` the
/// first time a dockspace is submitted after load. Walks the
/// flat `PersistedDockNode[]` and:
///   1. Creates every node in `ctx.dock.nodes` with the original
///      `id` (preserves stable ids across reloads).
///   2. Wires split-vs-leaf role, ratio, axis, child_ids,
///      size_ref, flags.
///   3. For leaves: resolves window NAMES to live `Window` ids
///      via `findOrCreateWindow`. Sets `dock_node_id` on each
///      window so they render in the docked path.
///   4. Bumps `ctx.dock.next_node_id` past the max observed id
///      so future fresh allocations don't collide.
/// On any structural inconsistency (a child_id that doesn't
/// resolve, a leaf with no recoverable windows), the offending
/// node is skipped but the rest of the tree is preserved.
/// Persistence is a hint, never a hard requirement - a broken
/// payload degrades to "fresh tree", not a crash.
/// Returns true if the tree was restored (even partially), or
/// false if pending_dock_tree was empty.
pub fn tryRestoreDockTree(gpa: Allocator, ctx: *UiContext) bool {
    if (ctx.pending_dock_tree.len == 0) {
        return false;
    }
    defer freePendingDockTree(gpa, ctx);

    // Pass 1: create nodes by id. Split vs leaf determined by
    // the flat record. Skip nodes whose id is already taken
    // (shouldn't happen on a fresh ctx, but stay defensive).
    var max_id: u32 = 0;
    for (ctx.pending_dock_tree) |pn| {
        if (pn.id > max_id) {
            max_id = pn.id;
        }
        if (ctx.dock.nodes.contains(pn.id)) {
            continue;
        }
        const node: *DockNode = gpa.create(DockNode) catch continue;
        const parent_opt: ?u32 = if (pn.parent_id == 0) null else pn.parent_id;
        node.* = .{
            .id = pn.id,
            .parent_id = parent_opt,
            .flags = @bitCast(pn.flags),
        };
        ctx.dock.nodes.put(gpa, pn.id, node) catch {
            gpa.destroy(node);
            continue;
        };
    }

    // Pass 2: populate role data. Done second so child_id
    // lookups in pass 1 can resolve to existing pointers (both
    // children must exist before we wire the split that
    // references them).
    for (ctx.pending_dock_tree) |pn| {
        const node: *DockNode = ctx.dock.nodes.get(pn.id) orelse continue;
        if (pn.is_split) {
            const a_ok: bool = ctx.dock.nodes.contains(pn.split_child_a);
            const b_ok: bool = ctx.dock.nodes.contains(pn.split_child_b);
            if (!a_ok or !b_ok) {
                continue;
            } // dangling - skip
            const axis: SplitAxis = @fromBackingInt(@intCast(pn.split_axis));
            node.split = .{
                .axis = axis,
                .ratio = pn.split_ratio,
                .child_ids = .{ pn.split_child_a, pn.split_child_b },
                .size_ref = .{
                    if (pn.split_size_ref_a >= 0) pn.split_size_ref_a else null,
                    if (pn.split_size_ref_b >= 0) pn.split_size_ref_b else null,
                },
            };
        } else {
            // Leaf - resolve window names to live window ids.
            // Names not currently registered in ctx.windows are
            // skipped (window may not have been re-submitted
            // yet; in that case the leaf reappears empty, which
            // is correct degradation).
            var leaf: DockNode.LeafData = .{};
            for (pn.leaf_window_names) |name| {
                const w_id: Id = findWindowIdByName(ctx, name) orelse continue;
                leaf.window_ids.append(gpa, w_id) catch continue;
                // Mark the window as docked. pre_dock_pos/size
                // are left null - the original floating rect is
                // not part of persistence, so undock-restore
                // (5.5h) yields the window's current pos/size
                // (which the layout pass overwrites with the
                // leaf rect anyway).
                if (ctx.windows.get(w_id)) |w| {
                    w.dock_node_id = pn.id;
                }
            }
            // Selected tab: resolve by name; default to first
            // window if the selected name doesn't resolve or
            // the leaf is empty.
            if (pn.leaf_selected_window_name.len > 0) {
                if (findWindowIdByName(ctx, pn.leaf_selected_window_name)) |sel| {
                    leaf.selected_window_id = sel;
                }
            }
            if (leaf.selected_window_id == 0 and leaf.window_ids.items.len > 0) {
                leaf.selected_window_id = leaf.window_ids.items[0];
            }
            node.leaf = leaf;
        }
    }

    // Bump next_node_id past the max observed so fresh splits
    // post-restore don't reuse ids that were just claimed.
    if (max_id >= ctx.dock.next_node_id) {
        ctx.dock.next_node_id = max_id + 1;
    }
    return true;
}

pub const Error = error{
    /// Payload was syntactically invalid zon, or didn't match the
    /// `PersistedState` shape. Caller should fall back to empty
    /// persistence.
    InvalidPayload,
} || Allocator.Error;

// ============================================================================
// SECTION 3.5 - Auto-load / auto-save wiring (wasm-only)
// ============================================================================
// The storage transport (localStorage round-trip) lives in
// `src/web.zig` behind `extern "dom"` declarations that don't
// link on host builds. We comptime-gate the auto-* helpers on
// `is_wasm` so host tests / standalone runners can use the pure
// `serialize` / `apply` pair without dragging in the extern
// imports. On host, `tryAutoLoad` / `tryAutoSave` are no-ops
// that return immediately.
// The wiring goes through `UiContext.persistence_key`:
//   - User sets `ctx.persistence_key = "my_demo"` once at startup.
//   - On the FIRST `beginFrameRaw` call (`frame_count == 0`),
//     `tryAutoLoad(ctx)` reads localStorage key "zimr_my_demo",
//     parses it via `apply`, and the pending map is ready to graft
//     into windows as they're created during the frame's
//     `findOrCreateWindow` calls.
//   - Every `save_cadence_frames` frames in `endFrame`,
//     `tryAutoSave(ctx)` re-serializes the live windows and writes
//     back to localStorage. Save is unconditional on the cadence
//     no dirty-tracking yet (filed as 5.1c optimization).
// Errors are swallowed (log only): persistence is a "best effort"
// feature; a quota-exceeded or parse-failure shouldn't prevent the
// frame from rendering.

// (Turn 414: `builtin` is already imported at the top of ui.zig.
// `is_wasm` is the local const we keep here since it's only used
// by the persistence layer's auto-save / auto-load paths.)
const is_wasm = builtin.target.cpu.arch.isWasm();

/// Save cadence - every N frames, write the current state to
/// localStorage. At 60fps this is ~1s. Bumping this higher
/// reduces storage churn at the cost of "freshness" if the tab
/// is suddenly closed; lower trades the other way. Tunable per-
/// context via `ctx.persistence_save_cadence` (override field
/// added when needed; today the constant is fine).
pub const save_cadence_frames: u64 = 60;

/// Wasm-only: read localStorage for `ctx.persistence_key`, parse
/// the payload, populate `ctx.pending_persistence`. No-op on
/// host or when no key is set. Called from `beginFrameRaw` on
/// the first frame.
pub fn tryAutoLoad(ctx: *UiContext) void {
    if (!is_wasm) {
        return;
    }
    const key: []const u8 = ctx.persistence_key orelse return;

    // Don't reload over an already-populated pending map - that's
    // either a test that manually loaded or a previous frame's
    // load that hasn't finished consuming. Idempotency: subsequent
    // beginFrames won't clobber the in-progress load.
    if (ctx.pending_persistence.count() > 0) {
        return;
    }

    // Web module is wasm-only by file - import it inside the
    // is_wasm gate so host builds don't try to resolve it.
    const dom = web.dom;
    const loaded: ?[]u8 = dom.persistence_load(ctx.gpa, key) catch null;
    const bytes: []u8 = loaded orelse return;
    defer ctx.gpa.free(bytes);

    // `apply` wants a `[:0]const u8`. Dup + sentinel-terminate.
    const sentinel: [:0]u8 = ctx.gpa.allocSentinel(u8, bytes.len, 0) catch return;
    defer ctx.gpa.free(sentinel);
    @memcpy(sentinel, bytes);

    apply(ctx.gpa, ctx, sentinel) catch { // lint:off catch-suppression: bad payload -> fresh start
        // Bad payload - fresh start. Same recovery as a missing
        // key. Log eventually; for now silent.
    };
}

/// Wasm-only: serialize live state and write to localStorage.
/// Called from `endFrame` every `save_cadence_frames` frames.
/// No-op on host or without a key.
pub fn tryAutoSave(ctx: *const UiContext) void {
    if (!is_wasm) {
        return;
    }
    const key: []const u8 = ctx.persistence_key orelse return;
    if (ctx.frame_count == 0 or ctx.frame_count % save_cadence_frames != 0) {
        return;
    }

    const bytes: []u8 = serialize(ctx.gpa, ctx) catch return;
    defer ctx.gpa.free(bytes);

    const dom = web.dom;
    // Status code 1 = quota exceeded, 2 = unavailable. We don't
    // surface these today - silently best-effort. Future: route
    // through a UiContext callback so demos can log/notify.
    _ = dom.persistence_save(key, bytes);
}

