// All tests construct UiContext directly (no app runner involved).
// `frame_arena` is required (no default) - this helper centralizes
// the boilerplate so future test cases stay short.
fn testCtx(gpa: Allocator) UiContext {
    return .{
        .gpa = gpa,
        .frame_arena = FrameArena.init(gpa, ui_frame_arena_ceiling, "ui"),
    };
}

test "serialize: empty context produces empty windows array" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();

    const bytes: []u8 = try serialize(gpa, &ctx);
    defer gpa.free(bytes);

    // Should at minimum contain the version field and an empty
    // windows array.
    try expect(std.mem.indexOf(u8, bytes, ".version") != null);
    try expect(std.mem.indexOf(u8, bytes, ".windows") != null);
}

