test "apply: parses zon and populates pending_persistence" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();

    const text: [:0]const u8 =
        \\.{
        \\    .version = 1,
        \\    .windows = .{
        \\        .{
        \\            .name = "alpha",
        \\            .pos = .{ 10, 20 },
        \\            .size = .{ 300, 200 },
        \\            .scroll_y = 5,
        \\            .user_resized = true,
        \\        },
        \\    },
        \\}
    ;
    try apply(gpa, &ctx, text);

    try expectEqual(@as(usize, 1), ctx.pending_persistence.count());
    const pw: PersistedWindow = ctx.pending_persistence.get("alpha") orelse return error.MissingEntry;
    try expectEqual(@as(f32, 10), pw.pos[0]);
    try expectEqual(@as(f32, 20), pw.pos[1]);
    try expectEqual(@as(f32, 300), pw.size[0]);
    try expectEqual(@as(f32, 5), pw.scroll_y);
    try expectEqual(true, pw.user_resized);
}

