test "roundtrip: serialize → apply produces matching pending state" {
    const gpa: Allocator = std.testing.allocator;

    // Source ctx with one window
    var ctx_src: UiContext = testCtx(gpa);
    defer ctx_src.deinit();
    const w: *Window = try gpa.create(Window);
    w.* = .{
        .id = 1,
        .pos = .{ 11, 22 },
        .size = .{ 333, 444 },
        .scroll_y = 7,
        .user_resized = true,
        .last_frame_active = ctx_src.frame_count,
    };
    const name: []const u8 = "roundtrip";
    @memcpy(w.name_buf[0..name.len], name);
    w.name_len = name.len;
    try ctx_src.windows.put(gpa, w.id, w);

    const bytes: []u8 = try serialize(gpa, &ctx_src);
    defer gpa.free(bytes);

    // Sentinel-terminate for the parser (apply takes [:0]const u8).
    const sentinel: [:0]u8 = try gpa.allocSentinel(u8, bytes.len, 0);
    defer gpa.free(sentinel);
    @memcpy(sentinel, bytes);

    // Apply into a fresh ctx.
    var ctx_dst: UiContext = testCtx(gpa);
    defer ctx_dst.deinit();
    try apply(gpa, &ctx_dst, sentinel);

    const pw: PersistedWindow = ctx_dst.pending_persistence.get("roundtrip") orelse return error.RoundtripFailed;
    try expectEqual(@as(f32, 11), pw.pos[0]);
    try expectEqual(@as(f32, 22), pw.pos[1]);
    try expectEqual(@as(f32, 333), pw.size[0]);
    try expectEqual(@as(f32, 444), pw.size[1]);
    try expectEqual(@as(f32, 7), pw.scroll_y);
    try expectEqual(true, pw.user_resized);
}

