test "tab bars: apply stages selections, takeTabBarSelection consumes" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();

    const text: [:0]const u8 =
        \\.{
        \\    .version = 1,
        \\    .windows = .{
        \\        .{
        \\            .name = "win",
        \\            .pos = .{0,0}, .size = .{100,100},
        \\            .tab_bars = .{
        \\                .{ .str_id = "bar1", .selected_tab_label = "Beta" },
        \\                .{ .str_id = "bar2", .selected_tab_label = "Tools" },
        \\            },
        \\        },
        \\    },
        \\}
    ;
    try apply(gpa, &ctx, text);
    try expectEqual(@as(usize, 2), ctx.pending_tab_bar_selections.count());

    const sel1: []const u8 = takeTabBarSelection(&ctx, "win", "bar1") orelse return error.MissingBar;
    defer gpa.free(@constCast(sel1));
    try expectEqualStrings("Beta", sel1);

    // Consumed - second call returns null.
    try expectEqual(@as(?[]const u8, null), takeTabBarSelection(&ctx, "win", "bar1"));

    // Other bar still present.
    const sel2: []const u8 = takeTabBarSelection(&ctx, "win", "bar2") orelse return error.MissingBar;
    defer gpa.free(@constCast(sel2));
    try expectEqualStrings("Tools", sel2);
}

