test "5.5k: serialize captures dock tree shape" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();

    // Build a small tree: root SPLIT (horizontal, ratio 0.3,
    // size_ref[0] = 200) with two leaf children, each holding
    // one named window.
    const u = Ui{ .ctx = &ctx };
    const root: Id = try ctx.dock.createLeaf(gpa, null);
    ctx.dock.lookup(root).?.flags = .{ .is_dockspace = true };
    const split_result: SplitResult = try splitNode(&ctx.dock, gpa, root, .right, 0.30);
    ctx.dock.lookup(root).?.split.?.size_ref[0] = 200;

    // Create two windows and dock them.
    _ = findOrCreateWindow(&ctx, "Tools", .{});
    _ = findOrCreateWindow(&ctx, "View", .{});
    u.dockBuilderDockWindow("Tools", split_result.a);
    u.dockBuilderDockWindow("View", split_result.b);

    const bytes: []u8 = try serialize(gpa, &ctx);
    defer gpa.free(bytes);

    // .zon output should contain the dock_nodes field and at
    // least one of each interesting bit of state.
    try expect(std.mem.indexOf(u8, bytes, ".dock_nodes") != null);
    try expect(std.mem.indexOf(u8, bytes, ".is_split = true") != null);
    try expect(std.mem.indexOf(u8, bytes, ".split_ratio") != null);
    try expect(std.mem.indexOf(u8, bytes, "Tools") != null);
    try expect(std.mem.indexOf(u8, bytes, "View") != null);
}

test "5.5k: round-trip serialize → apply → tryRestoreDockTree rebuilds tree" {
    const gpa: Allocator = std.testing.allocator;

    // Source ctx - build a tree and serialize.
    var src_ctx: UiContext = testCtx(gpa);
    defer src_ctx.deinit();
    const u_src = Ui{ .ctx = &src_ctx };
    const src_root: Id = try src_ctx.dock.createLeaf(gpa, null);
    src_ctx.dock.lookup(src_root).?.flags = .{ .is_dockspace = true };
    const split: SplitResult = try splitNode(&src_ctx.dock, gpa, src_root, .right, 0.40);
    src_ctx.dock.lookup(src_root).?.split.?.size_ref[0] = 250;
    src_ctx.dock.lookup(split.a).?.flags = .{ .no_split = true };
    _ = findOrCreateWindow(&src_ctx, "Tools", .{});
    _ = findOrCreateWindow(&src_ctx, "Viewport", .{});
    _ = findOrCreateWindow(&src_ctx, "Console", .{});
    u_src.dockBuilderDockWindow("Tools", split.a);
    u_src.dockBuilderDockWindow("Viewport", split.b);
    u_src.dockBuilderDockWindow("Console", split.b);

    const bytes: []u8 = try serialize(gpa, &src_ctx);
    defer gpa.free(bytes);
    const sentinel: [:0]const u8 = try dupeZ(gpa, bytes);
    defer gpa.free(@constCast(sentinel));

    // Destination ctx - apply, then create the windows by name
    // (the user's submission loop does this on first frame),
    // then drive tryRestoreDockTree.
    var dst_ctx: UiContext = testCtx(gpa);
    defer dst_ctx.deinit();
    try apply(gpa, &dst_ctx, sentinel);
    _ = findOrCreateWindow(&dst_ctx, "Tools", .{});
    _ = findOrCreateWindow(&dst_ctx, "Viewport", .{});
    _ = findOrCreateWindow(&dst_ctx, "Console", .{});

    const restored: bool = tryRestoreDockTree(gpa, &dst_ctx);
    try expect(restored);

    // Root preserved with is_dockspace flag.
    const dst_root: *DockNode = dst_ctx.dock.lookup(src_root) orelse return error.RootMissing;
    try expect(dst_root.flags.is_dockspace);
    try expect(dst_root.split != null);
    try expectApproxEqAbs(@as(f32, 0.40), dst_root.split.?.ratio, 0.001);
    try expectEqual(@as(?f32, 250), dst_root.split.?.size_ref[0]);

    // Tools leaf flags survived.
    const tools_leaf: *DockNode = dst_ctx.dock.lookup(split.a) orelse return error.LeafMissing;
    try expect(tools_leaf.flags.no_split);
    try expectEqual(@as(usize, 1), tools_leaf.leaf.?.window_ids.items.len);

    // Viewport leaf has 2 windows; selected should be the first
    // (Viewport was the first dockBuilderDockWindow call).
    const right_leaf: *DockNode = dst_ctx.dock.lookup(split.b) orelse return error.RightLeafMissing;
    try expectEqual(@as(usize, 2), right_leaf.leaf.?.window_ids.items.len);

    // Each docked window has its dock_node_id set.
    const tools: *Window = findOrCreateWindow(&dst_ctx, "Tools", .{});
    const viewport_win: *Window = findOrCreateWindow(&dst_ctx, "Viewport", .{});
    try expectEqual(@as(?u32, split.a), tools.dock_node_id);
    try expectEqual(@as(?u32, split.b), viewport_win.dock_node_id);

    // After restore, pending tree is freed.
    try expectEqual(@as(usize, 0), dst_ctx.pending_dock_tree.len);
}

