test "P4.1: serialize skips style block when style == dark_default" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();
    // ctx.style starts as dark_default — fresh ctx.

    const bytes: []u8 = try serialize(gpa, &ctx);
    defer gpa.free(bytes);

    // Should emit `.style = null,` rather than a full PersistedStyle block.
    try expect(std.mem.indexOf(u8, bytes, ".style = null") != null);
    // None of the per-color slot names should appear in the payload.
    try expect(std.mem.indexOf(u8, bytes, ".window_bg") == null);
    try expect(std.mem.indexOf(u8, bytes, ".text_link_underline") == null);
}

test "P4.1: serialize emits PersistedStyle block when style differs" {
    const gpa: Allocator = std.testing.allocator;
    var ctx: UiContext = testCtx(gpa);
    defer ctx.deinit();
    // Diverge from default: bump button color. One field is enough
    // to fail the default-equality check and trigger emission.
    ctx.style.button = .{ .r = 255, .g = 100, .b = 50, .a = 200 };

    const bytes: []u8 = try serialize(gpa, &ctx);
    defer gpa.free(bytes);

    // The block should be present this time.
    try expect(std.mem.indexOf(u8, bytes, ".style = null") == null);
    try expect(std.mem.indexOf(u8, bytes, ".button = ") != null);
}

test "P4.1: serialize → apply round-trips a customized style" {
    const gpa: Allocator = std.testing.allocator;
    var src_ctx: UiContext = testCtx(gpa);
    defer src_ctx.deinit();
    // Customize several fields covering colors, Vec2, scalar, and i32.
    src_ctx.style.button = .{ .r = 100, .g = 200, .b = 50, .a = 220 };
    src_ctx.style.text_link_underline = .{ .r = 1, .g = 2, .b = 3, .a = 4 };
    src_ctx.style.window_padding = .{ 12, 16 };
    src_ctx.style.disabled_alpha = 0.42;
    src_ctx.style.line_spacing = 7;

    const bytes: []u8 = try serialize(gpa, &src_ctx);
    defer gpa.free(bytes);

    const sentinel: [:0]u8 = try gpa.allocSentinel(u8, bytes.len, 0);
    defer gpa.free(sentinel);
    @memcpy(sentinel, bytes);

    var dst_ctx: UiContext = testCtx(gpa);
    defer dst_ctx.deinit();
    try apply(gpa, &dst_ctx, sentinel);

    try expectEqual(src_ctx.style.button, dst_ctx.style.button);
    try expectEqual(src_ctx.style.text_link_underline, dst_ctx.style.text_link_underline);
    try expectEqual(src_ctx.style.window_padding, dst_ctx.style.window_padding);
    try expectEqualDeep(src_ctx.style.disabled_alpha, dst_ctx.style.disabled_alpha);
    try expectEqual(src_ctx.style.line_spacing, dst_ctx.style.line_spacing);
}

test "P4.1: apply preserves caller-bound font pointer" {
    const gpa: Allocator = std.testing.allocator;

    // Source: themed but with NO font bound (the saved payload
    // can't carry the font; this is the realistic save state).
    var src_ctx: UiContext = testCtx(gpa);
    defer src_ctx.deinit();
    src_ctx.style.button = .{ .r = 50, .g = 60, .b = 70, .a = 80 };

    const bytes: []u8 = try serialize(gpa, &src_ctx);
    defer gpa.free(bytes);
    const sentinel: [:0]u8 = try gpa.allocSentinel(u8, bytes.len, 0);
    defer gpa.free(sentinel);
    @memcpy(sentinel, bytes);

    // Destination: caller has bound a font (e.g. via
    // loadFontFromTtfBytes BEFORE calling apply). apply must NOT
    // clobber that binding.
    var dst_ctx: UiContext = testCtx(gpa);
    defer dst_ctx.deinit();
    const sentinel_font: types.Font = undefined;
    dst_ctx.style.font = &sentinel_font;

    try apply(gpa, &dst_ctx, sentinel);

    try expectEqual(@as(?*const types.Font, &sentinel_font), dst_ctx.style.font);
    // Color did get applied.
    try expectEqual(src_ctx.style.button, dst_ctx.style.button);
}

