test "P4.2: applyPreset(.light) swaps every color, preserves numerics" {
    var s: Style = Style.dark_default;
    s.font_size = 20; // user choice — should survive
    s.window_padding = .{ 16, 16 };
    s.disabled_alpha = 0.42;

    s.applyPreset(.light);

    // A representative color shifted to the light theme.
    try expectEqual(Style.light_default.window_bg, s.window_bg);
    try expectEqual(Style.light_default.text, s.text);
    // Numeric chrome untouched.
    try expectEqual(@as(f32, 20), s.font_size);
    try expectEqual(@as(f32, 16), s.window_padding[0]);
    try expectEqual(@as(f32, 0.42), s.disabled_alpha);
}

test "P4.2: applyPreset(.classic) and back to .dark round-trips colors" {
    var s: Style = Style.dark_default;
    s.applyPreset(.classic);
    try expectEqual(Style.classic_default.button, s.button);

    s.applyPreset(.dark);
    try expectEqual(Style.dark_default.button, s.button);
    try expectEqual(Style.dark_default.window_bg, s.window_bg);
}

test "P4.2: applyPreset preserves font pointer" {
    var s: Style = Style.dark_default;
    const sentinel_font: types.Font = undefined;
    s.font = &sentinel_font;

    s.applyPreset(.light);
    try expectEqual(@as(?*const types.Font, &sentinel_font), s.font);

    s.applyPreset(.classic);
    try expectEqual(@as(?*const types.Font, &sentinel_font), s.font);
}

// ============================================================================
// Screenshot — DrawList → raster → RGBA8 → PNG
// ============================================================================
//
// Host-only debug + regression-test tool.  Walks every window's
// `DrawList` in a `UiContext` post-`beginFrame`+widget-submission
// state, replays the commands into a fresh `raster.Context` software
// framebuffer, then encodes the buffer as a PNG.  Lets us inspect
// UI layout WITHOUT running a real WebGL/wasm session — invaluable
// for debugging layout bugs (where the visual position is wrong
// but the state looks fine) and for snapshot-style regression
// tests built on `snapshot()` below.
//
// Why this exists:
// The canonical "looks fine in tests, broken on screen" failure
// surfaced from a phone screenshot showing tab-bar widgets
// visually overlapping while every TabBar unit test passed.  A
// self-driven screenshot path closes that gap — we can take a
// PNG mid-test, eyeball it (or assert over pixel rects), and
// catch layout bugs at test time.
//
// Scope and limitations:
//   - **Text**: rendered as a label-colored rectangle at the
//     text's bounding rect.  No glyph rasterization on the raster
//     side — that needs the font atlas uploaded as an raster
//     texture and a textured-quad emit path per glyph.  For
//     layout debugging, the box footprint is sufficient: you
//     SEE where text was placed even if you can't READ it.
//   - **Textured quads** (images, glyph atlases): rendered as a
//     solid-color placeholder using the cmd's tint color.
//   - **Clipping**: push_clip / pop_clip translate to raster's
//     scissor enable/disable pair.  Nested clips track a stack
//     and apply the deepest current clip rect.
//   - **Lines / polylines / triangles / circles / ngons /
//     bezier**: all rendered as immediate-mode triangles via the
//     raster rasterizer.  Outlines approximated by a series of
//     thin filled quads (no GL_LINE_WIDTH semantics in raster).
//
// Public API:
//   - `renderToBytes(gpa, ctx, w, h) ![]u8` — rasterize all
//     windows, return a freshly-allocated RGBA8 byte buffer.
//   - `renderToPng(gpa, ctx, w, h, path) !void` — convenience
//     that also encodes to PNG and writes to disk.
//   - `snapshot(gpa, ctx, w, h, ref_path) !PixelDiff` —
//     regression-test helper.  First run writes the baseline;
//     subsequent runs diff against it.  Refresh a baseline by
//     deleting the PNG.
//   - `comparePixels(a, b, tolerance) PixelDiff` — generic
//     RGBA8 byte-compare with a per-channel tolerance.  Not
//     UI-specific; useable on any same-size RGBA8 buffers.
//   - `loadPng(gpa, path) !codecs.png.Image` — generic PNG
//     read.  Same disclaimer.

/// Internal: draw a colored rectangle at the bbox where a text
/// command WOULD render its glyphs.  Color uses the text cmd's own
/// color so semantically-distinct text (regular, disabled, link,
/// error) still reads as distinct in the screenshot.  Alpha is
/// kept around 2/3 of the source so overlapping bboxes still show
/// layering without dominating the image.  Height = font_size;
/// width is a coarse estimate of `len * size * 0.5`.
fn drawTextBbox(
    sw: *raster.Context,
    s: []const u8,
    pos: Vec2,
    size: f32,
    packed_col: u32,
) void {
    if (s.len == 0) {
        return;
    }
    const r8: u8 = @intCast(packed_col & 0xFF);
    const g8: u8 = @intCast((packed_col >> 8) & 0xFF);
    const b8: u8 = @intCast((packed_col >> 16) & 0xFF);
    const a8_full: u8 = @intCast((packed_col >> 24) & 0xFF);
    // 2/3 of source alpha — readable but doesn't dominate.
    const a8: u8 = @intCast((@as(u32, a8_full) * 2) / 3);
    const est_w: f32 = float(s.len) * size * 0.5;
    sw.disable(.texture_2d);
    sw.color4ub(r8, g8, b8, a8);
    sw.begin(.quads);
    sw.vertex2f(pos[0], pos[1]);
    sw.vertex2f(pos[0], pos[1] + size);
    sw.vertex2f(pos[0] + est_w, pos[1] + size);
    sw.vertex2f(pos[0] + est_w, pos[1]);
    sw.end();
}

/// Rasterize `ctx`'s current frame (every window's draw list) into
/// a fresh RGBA8 buffer of size `w * h * 4`.  Caller owns the slice
/// and must free with `gpa`.
/// The contract: this is called AFTER `ctx.beginFrame(...)` and
/// AFTER the caller has submitted every window's widgets, but
/// BEFORE `ctx.endFrame(...)` (which would normally replay against
/// real GL).  We replay against raster instead.
pub fn renderToBytes(
    gpa: Allocator,
    ctx: *UiContext,
    w: u32,
    h: u32,
) ![]u8 {
    const w_i: i32 = @intCast(w);
    const h_i: i32 = @intCast(h);

    var sw: raster.Context = try raster.Context.init(gpa, w_i, h_i);
    defer sw.deinit(gpa);

    // Set up an ortho projection mapping pixel coords directly to
    // NDC.  ui widgets work in screen pixels (top-left origin,
    // y-down).  raster's NDC is standard GL (y-up) so we put `top`
    // < `bottom` in the ortho call to flip — the y-down feel
    // matches what the rlgl path produces.
    sw.matrixMode(.projection);
    sw.loadIdentity();
    sw.ortho(0, @floatFromInt(w), @floatFromInt(h), 0, -1, 1);
    sw.matrixMode(.modelview);
    sw.loadIdentity();
    sw.viewport(0, 0, w_i, h_i);

    // Clear to a typical zimr ui demo background colour.
    sw.clearColor(.{ .r = 15, .g = 23, .b = 42, .a = 255 });
    sw.clear(.{ .color = true });

    // Alpha-blend so semi-transparent rects compose correctly.
    sw.enable(.blend);
    sw.blendFunc(.src_alpha, .one_minus_src_alpha);

    // Synthetic WindowState — `DrawList.render` reads this for
    // DPR-aware scissor scaling.  On raster there's no DPR, so
    // screen_w == render_w (factor of 1).
    const ws: runtime.core.WindowState = .{
        .screen_width = w_i,
        .screen_height = h_i,
        .render_width = w_i,
        .render_height = h_i,
    };
    // Synthetic FontCache + ShapesTextureState.  Both zero-init;
    // the screenshot path doesn't bind real font glyph textures, so
    // text quads sample white (no texture bound) and render as solid
    // coloured rectangles.  That's actually the right placeholder
    // behaviour for layout debugging.
    const shapes_state: shapes2d.ShapesTextureState = .{};
    const font_cache: text2d.FontCache = .{};

    // In normal run-mode `endFrame` drains deferred dockspace tab
    // emission into `ctx.foreground_dl`.  The screenshot path
    // submits-then-renders without calling endFrame, so we have
    // to call this directly here so single-frame PNG renders
    // include the dock tabs.
    flushDockTabsToForeground(ctx);

    // Walk every active window's draw list and replay through the
    // SAME `DrawList.render` the rlgl path uses (which is generic
    // over `gl: anytype`).  HashMap iteration order isn't
    // submission order, so overlapping windows may composite in
    // arbitrary z-order — fine for layout debug.
    // Two passes per window:
    //   1. Text-bbox placeholders.  `text2d.draw` short-
    //      circuits when `font_cache.font.texture.id == 0` (an
    //      unloaded font), so we'd see no text at all using the
    //      real render path.  Pre-emit faint rectangles at each
    //      text cmd's bbox so screenshots show WHERE text lives.
    //   2. The real DrawList.render — paints rects, lines, scissor
    //      stack, etc., and silently no-ops the text cmds.
    var it: std.AutoArrayHashMapUnmanaged(Id, *Window).Iterator = ctx.windows.iterator();
    while (it.next()) |entry| {
        const win: *Window = entry.value_ptr.*;
        if (win.last_frame_active != ctx.frame_count) {
            continue;
        }
        // Pass 1: text bboxes.
        for (win.draw_list.cmds.items) |cmd| switch (cmd) {
            .text => |c| drawTextBbox(&sw, c.s, c.pos, c.size, c.col),
            else => {},
        };
        // Pass 2: the real renderer.
        win.draw_list.render(&sw, &ws, &shapes_state, &font_cache);
    }

    // Foreground draw list — tooltips, popup overlays, AND the
    // deferred dockspace tab-bar emission.  Rendered AFTER every
    // window so overlays composite on top of regular content.
    // Text-bbox pass first, then the real renderer (same shape).
    for (ctx.foreground_dl.cmds.items) |cmd| switch (cmd) {
        .text => |c| drawTextBbox(&sw, c.s, c.pos, c.size, c.col),
        else => {},
    };
    ctx.foreground_dl.render(&sw, &ws, &shapes_state, &font_cache);

    // Read out the framebuffer and hand it to the caller.
    const src: []const u8 = sw.colorBufferBytes();
    const dst: []u8 = try gpa.alloc(u8, src.len);
    @memcpy(dst, src);
    return dst;
}

/// Convenience: rasterize, encode, write to disk. Takes the application's
/// `io` (the `std.Io` chosen in `main`), threaded like the allocator.
pub fn renderToPng(
    gpa: Allocator,
    io: std.Io,
    ctx: *UiContext,
    w: u32,
    h: u32,
    out_path: []const u8,
) !void {
    const bytes: []u8 = try renderToBytes(gpa, ctx, w, h);
    defer gpa.free(bytes);

    const png_bytes: []u8 = try codecs.png.encode(gpa, bytes, w, h);
    defer gpa.free(png_bytes);

    var f: std.Io.File = try std.Io.Dir.cwd().createFile(io, out_path, .{});
    defer f.close(io);
    try f.writeStreamingAll(io, png_bytes);
}

/// Result of comparing two RGBA8 buffers pixel-by-pixel.
pub const PixelDiff = struct {
    /// Total pixels examined.  Always `w * h`.
    total: u32,
    /// Pixels where at least one channel differs by > tolerance.
    differing: u32,
    /// Largest per-channel absolute difference observed.
    max_channel_delta: u8,

    pub fn fraction(self: PixelDiff) f32 {
        if (self.total == 0) {
            return 0;
        }
        return float(self.differing) / float(self.total);
    }
};

/// Per-pixel RGBA8 byte-compare with a configurable per-channel
/// tolerance.  `a` and `b` must be the same length, a multiple of 4.
/// Not UI-specific; works on any same-size RGBA8 buffers.
pub fn comparePixels(
    a: []const u8,
    b: []const u8,
    tolerance: u8,
) PixelDiff {
    assert(a.len == b.len, @src());
    assert(a.len % 4 == 0, @src());
    var diff: PixelDiff = .{ .total = @intCast(a.len / 4), .differing = 0, .max_channel_delta = 0 };
    var i: usize = 0;
    while (i < a.len) : (i += 4) {
        var px_different: bool = false;
        var k: usize = 0;
        while (k < 4) : (k += 1) {
            const av: i16 = @intCast(a[i + k]);
            const bv: i16 = @intCast(b[i + k]);
            const d: u8 = @intCast(@abs(av - bv));
            if (d > diff.max_channel_delta) {
                diff.max_channel_delta = d;
            }
            if (d > tolerance) {
                px_different = true;
            }
        }
        if (px_different) {
            diff.differing += 1;
        }
    }
    return diff;
}

/// Read a PNG file into an `Image`.  Caller owns the result;
/// release with `image.deinit(gpa)`. Takes the application's `io`.
pub fn loadPng(
    gpa: Allocator,
    io: std.Io,
    path: []const u8,
) !codecs.png.Image {
    var f: std.Io.File = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer f.close(io);
    const st: std.Io.File.Stat = try f.stat(io);
    const bytes: []u8 = try gpa.alloc(u8, st.size);
    defer gpa.free(bytes);
    const read: usize = try f.readPositionalAll(io, bytes, 0);
    return try codecs.png.decode(gpa, bytes[0..read]);
}

/// Snapshot test: rasterize `ctx`, compare against the PNG at
/// `ref_path`.  On mismatch — OR when the reference doesn't yet
/// exist — write the current render to `ref_path` and return the
/// diff so the caller can decide what to do.
///
/// The "first run writes the baseline" behavior is intentional:
/// it makes adding a snapshot test as cheap as adding a regular
/// test.  Refresh a snapshot by deleting the reference PNG and
/// re-running.
pub fn snapshotPng(
    gpa: Allocator,
    io: std.Io,
    ctx: *UiContext,
    w: u32,
    h: u32,
    ref_path: []const u8,
) !PixelDiff {
    const fresh: []u8 = try renderToBytes(gpa, ctx, w, h);
    defer gpa.free(fresh);

    const ref_image: codecs.png.Image = loadPng(gpa, io, ref_path) catch |err| switch (err) {
        error.FileNotFound => {
            // First-run baseline write.  Encode the fresh render
            // and save it as the reference.  Caller sees a clean
            // pass (differing == 0) and can move on.
            try renderToPng(gpa, io, ctx, w, h, ref_path);
            return PixelDiff{ .total = w * h, .differing = 0, .max_channel_delta = 0 };
        },
        else => return err,
    };
    defer ref_image.deinit(gpa);

    if (ref_image.width != w or ref_image.height != h) {
        return error.SnapshotDimensionsMismatch;
    }
    return comparePixels(fresh, ref_image.pixels, 0);
}

test "wantCaptureMouse: answers correctly when queried BEFORE this frame's windows are submitted" {
    // The natural way to write an update is: gate the scene input on
    // `!u.wantCaptureMouse()`, THEN draw the UI. That means the query happens
    // while `frame_windows` is still EMPTY. Hit-testing only that list made the
    // query return false, so the pointer clicked straight through the panel —
    // tapping a button also dragged the scene underneath it (seen on-device in
    // scissor_test; decals + zimrphysics2d_demo had the same latent bug).
    // The fix: `endFrame` snapshots each window's RECT, and `wantCaptureMouse`
    // falls back to that snapshot. This test pins that behaviour.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();

    // A real Window (so it is safe to dereference) at a known rect.
    var w: Window = .{
        .id = 1,
        .pos = .{ 100, 50 },
        .size = .{ 200, 120 }, // covers x 100..300, y 50..170
    };
    ctx.frame_windows.append(&w) catch panicf(@src(), "OOM", .{});

    // End of frame N: the rect is snapshotted while the window is alive.
    ctx.endFrameNoRender();
    try expectEqual(@as(usize, 1), ctx.prev_window_rects.len);

    // Frame N+1 begins — `frame_windows` is cleared, nothing submitted yet.
    var gl_dummy: Gl = .{};
    const shapes_dummy: shapes2d.ShapesTextureState = .{};
    const font_dummy: text2d.FontCache = .{};
    _ = ctx.beginFrameRaw(.{}, null, 800, 600, &gl_dummy, &shapes_dummy, &font_dummy);
    try expectEqual(@as(usize, 0), ctx.frame_windows.len);

    const u: Ui = .{ .ctx = &ctx };

    // Pointer INSIDE the panel, queried before any window is submitted: the UI
    // must claim it. (Before the fix this returned false — the click-through.)
    ctx.input.mouse_pos = .{ 150, 90 };
    try expect(u.wantCaptureMouse());

    // Pointer OUTSIDE the panel: the scene must still get it, or the UI would
    // swallow every drag on the world.
    ctx.input.mouse_pos = .{ 600, 400 };
    try expect(!u.wantCaptureMouse());
}

test "setNextWindowSize: a zero component means auto-fit, not zero pixels" {
    // ★ A REAL FIELD BUG, pinned.
    //
    // `setNextWindowSize(.{ 380, 0 })` is the natural way to say "this wide, as tall as the
    // content needs" — it is exactly what Dear ImGui's SetNextWindowSize means. Taking the
    // zero literally created a window ONE PIXEL tall with every control clipped away, which
    // looks like the UI failed to render rather than like a size request being honoured.
    //
    // Found on a phone, where the panel was simply absent. zimr's own runtime UI lint
    // diagnosed it precisely — *content (216px) is >3x its viewport (1px)* — which is the
    // only reason it took minutes rather than an evening.
    var ctx = UiContext.init(std.testing.allocator);
    defer ctx.deinit();
    const u: Ui = .{ .ctx = &ctx };

    // Height zero: the width is a request, the height is "fit".
    u.setNextWindowSize(.{ 380, 0 }, .{});
    try expect(ctx.next_window_size_auto[0] == false);
    try expect(ctx.next_window_size_auto[1] == true);

    // Width zero, symmetrically.
    u.setNextWindowSize(.{ 0, 200 }, .{});
    try expect(ctx.next_window_size_auto[0] == true);
    try expect(ctx.next_window_size_auto[1] == false);

    // Both given: neither axis is auto, and the values are kept verbatim — a caller who
    // asks for an exact size still gets one.
    u.setNextWindowSize(.{ 320, 240 }, .{});
    try expect(ctx.next_window_size_auto[0] == false);
    try expect(ctx.next_window_size_auto[1] == false);
    try expect(ctx.next_window_size.?[0] == 320);
    try expect(ctx.next_window_size.?[1] == 240);
}

test "itemHoverable: a widget outside its window's bounds is not grabbable" {
    // ★★ THE BUG THIS PINS: widgets hit-tested with a bare `pointInRect` against their own
    // layout rect, with no clip. A slider scrolled out of its window — or laid out past the
    // window's edge — kept that rect, so it stayed LIVE while not being DRAWN. Dragging in
    // empty space moved sliders that were nowhere on screen.
    //
    // The clip stack that already existed is a DRAW-TIME structure consulted during draw-list
    // replay. Interaction had none, which is exactly why the fault was invisible from the
    // rendering side: correctly not drawn, incorrectly still interactive.
    // ★★ THIS TEST SETS `item_clip` BY HAND, AND THAT IS ITS LIMIT. It proves the PREDICATE is
    // right; it proves nothing about whether the predicate's input is ever populated. The
    // first version of this fix set `item_clip` only on the window POP path — so every widget
    // was submitted while it still held the previous window's rect, or null — and this test
    // passed the whole time. ★ A test that constructs the state under test, rather than
    // exercising the code that produces it, says nothing about the producer.
    // `refreshItemClip` is now called from BOTH push and pop for that reason.
    // A bare context: this test only exercises the hit-test predicate, so the allocator-backed
    // fields go unused. Constructed with  for those rather than a real arena,
    // because touching them here would be testing something else.
    var ctx: UiContext = undefined;
    ctx.input = .{};
    const window_rect: Rectangle = .{ .x = 100, .y = 100, .width = 200, .height = 150 };
    ctx.item_clip = window_rect;

    // A widget INSIDE the window, with the mouse on it: hoverable.
    const inside: Rectangle = .{ .x = 120, .y = 120, .width = 100, .height = 20 };
    ctx.input.mouse_pos = .{ 150, 130 };
    try expect(itemHoverable(&ctx, inside));

    // ★ The same widget, mouse still on it — but the widget now sits BELOW the window's
    // bottom edge, where a scroll region would have clipped it away. Its own rect still
    // contains the mouse, which is precisely why the bare test said yes.
    const clipped: Rectangle = .{ .x = 120, .y = 400, .width = 100, .height = 20 };
    ctx.input.mouse_pos = .{ 150, 410 };
    try expect(pointInRect(ctx.input.mouse_pos, clipped)); // the old test passed
    try expect(!itemHoverable(&ctx, clipped)); // the new one does not

    // With no window in scope (an overlay drawn straight to the viewport) there is nothing to
    // clip against, and the item stays hoverable.
    ctx.item_clip = null;
    try expect(itemHoverable(&ctx, clipped));
}
